type Page = "dashboard" | "exceptions" | "imports" | "master-data" | "sales" | "inventory" | "purchase" | "account-balance" | "image-tools" | "crm" | "crm-projects" | "users" | "settings";
type PermissionCode = string;
const EXCEPTION_CENTER_UI_ENABLED = String(import.meta.env.VITE_EXCEPTION_CENTER_ENABLED ?? "true").toLowerCase() === "true";
const EXCEPTION_AI_CHAT_UI_ENABLED = String(import.meta.env.VITE_EXCEPTION_AI_CHAT_ENABLED ?? "true").toLowerCase() === "true";
type ExceptionAssistantContext = { request: AiChatContext; label: string };
const defaultExceptionAssistantContext: ExceptionAssistantContext = {
  request: { scope: "current_filters", filters: {}, case_nos: [] },
  label: "当前筛选"
};
