type CrmNavEntry = {
  key: string;
  label: string;
  desc: string;
  icon: LucideIcon;
  permissions: PermissionCode[];
  targetPage?: Page;
  path: string;
  sectionKey?: CrmSectionKey;
};

const companyLogoSrc = `${import.meta.env.BASE_URL}brand/demo-logo.svg`;

const pageFromPath = (path: string): Page => {
  if (path.startsWith("/exceptions")) return "exceptions";
  if (path.startsWith("/imports")) return "master-data";
  if (path.startsWith("/master-data")) return "master-data";
  if (path.startsWith("/sales")) return "sales";
  if (path.startsWith("/inventory")) return "inventory";
  if (path.startsWith("/purchase")) return "purchase";
  if (path.startsWith("/account-balance")) return "account-balance";
  if (path.startsWith("/image-tools")) return "image-tools";
  if (path.startsWith("/crm/image-tools")) return "image-tools";
  if (path.startsWith("/crm-projects")) return "crm-projects";
  if (path.startsWith("/crm")) return "crm";
  if (path.startsWith("/authority")) return "users";
  if (path.startsWith("/users")) return "users";
  if (path.startsWith("/settings")) return "settings";
  return "dashboard";
};

