const hasPermission = (permissions: PermissionCode[], permissionCode: PermissionCode) => permissions.includes(permissionCode);
const hasAnyPermission = (permissions: PermissionCode[], permissionCodes: PermissionCode[]) => permissionCodes.some((permissionCode) => hasPermission(permissions, permissionCode));
const isAdminUser = (user: Pick<UserPublic, "role"> | null | undefined) => user?.role === "admin";
const CRM_APPROVAL_ACCESS_PERMISSIONS: PermissionCode[] = ["approval.view", "approval.approve", "crm_lead.view", "crm_lead.approve", "customer_tag.review"];
const CRM_APPROVAL_REVIEW_PERMISSIONS: PermissionCode[] = ["approval.approve", "crm_lead.approve", "customer_tag.review"];

