function crmSectionMeta(sectionKey: CrmSectionKey) {
  return crmSections.find((section) => section.key === sectionKey) ?? crmSections[0];
}

function crmSectionLabel(sectionKey: CrmSectionKey) {
  return crmSectionMeta(sectionKey).label;
}

function crmSectionPath(sectionKey: CrmSectionKey) {
  return crmSectionMeta(sectionKey).path;
}

function navigationPageFor(page: Page): Page {
  return page === "crm-projects" ? "crm" : page;
}

function canAccessCrmSection(section: { permissions: PermissionCode[] }, permissions: PermissionCode[]) {
  return hasAnyPermission(permissions, section.permissions);
}

function canAccessCrmEntry(entry: { permissions: PermissionCode[] }, permissions: PermissionCode[]) {
  return hasAnyPermission(permissions, entry.permissions);
}

function normalizeCrmPath(path: string) {
  const [pathname] = path.split(/[?#]/);
  return pathname.replace(/\/+$/, "") || "/crm";
}

const CRM_LEGACY_PATH_REDIRECTS: Record<string, string> = {
  "/crm/followup-entry": "/crm/tasks",
  "/crm/business-profile-submit": "/crm/customers",
  "/crm/customer-profile-submit": "/crm/customers",
  "/crm/insights": "/crm/projects?view=analysis",
  "/crm/reviews": "/crm/projects",
  "/crm/api-access": "/users/external-api",
  "/crm/assistant": "/exceptions?assistant=open"
};

function canonicalCrmPath(path: string) {
  const [rawPath, rawSearch = ""] = path.split("?");
  const normalizedPath = normalizeCrmPath(rawPath);
  const redirectTarget = CRM_LEGACY_PATH_REDIRECTS[normalizedPath];
  if (!redirectTarget) return rawSearch ? `${normalizedPath}?${rawSearch}` : normalizedPath;

  const [targetPath, targetSearch = ""] = redirectTarget.split("?");
  const params = new URLSearchParams(targetSearch);
  new URLSearchParams(rawSearch).forEach((value, key) => {
    if (!params.has(key)) params.set(key, value);
  });
  const query = params.toString();
  return query ? `${targetPath}?${query}` : targetPath;
}

function crmGroupShortLabel(label: string) {
  return label.includes("：") ? label.split("：").pop() ?? label : label;
}

function crmSectionFromPath(path: string): CrmSectionKey {
  if (path.startsWith("/crm-projects")) return "projects";
  if (path.startsWith("/crm/projects/")) return "projects";
  if (path.startsWith("/crm/insights")) return "projects";
  const currentPath = normalizeCrmPath(path);
  const section = crmSections.find((item) => item.path === currentPath);
  return section?.key ?? "home";
}

function canAccessCrmPath(path: string, permissions: PermissionCode[]) {
  const sectionKey = crmSectionFromPath(path);
  if (sectionKey === "work" && crmApprovalIdFromPath(path)) return true;
  return canAccessCrmSection(crmSectionMeta(sectionKey), permissions);
}

function crmProjectIdFromPath(path: string) {
  const match = path.match(/^\/crm\/projects\/(\d+)/);
  if (!match) return null;
  const projectId = Number.parseInt(match[1], 10);
  return Number.isNaN(projectId) ? null : projectId;
}

