function inferMasterKindFromFileName(fileName: string): MasterKind | null {
  const normalized = fileName.toLowerCase();
  if (normalized.includes("客户") || normalized.includes("customer")) return "customers";
  if (normalized.includes("员工") || normalized.includes("职员") || normalized.includes("employee")) return "employees";
  if (normalized.includes("商品") || normalized.includes("货品") || normalized.includes("product")) return "products";
  if (normalized.includes("供应商") || normalized.includes("供货商") || normalized.includes("supplier")) return "suppliers";
  return null;
}

function inferImportFileTypeFromFileName(fileName: string): string | null {
  const normalized = fileName.toLowerCase();
  if (normalized.includes("销售统计") || normalized.includes("销售明细") || normalized.includes("sales")) return "sales_detail";
  if (normalized.includes("采购明细") || normalized.includes("采购统计") || normalized.includes("purchase")) return "purchase_detail";
  if (normalized.includes("库存核验") || normalized.includes("实时库存") || normalized.includes("inventory_check")) return "inventory_check";
  if (normalized.includes("库存状况") || normalized.includes("库存") || normalized.includes("inventory") || normalized.includes("stock")) return "inventory_snapshot";
  if (normalized.includes("应收查询") || normalized.includes("应收账款") || normalized.includes("应收") || normalized.includes("receivable")) return "receivable_snapshot";
  if (normalized.includes("往来明细") || normalized.includes("往来对账明细") || normalized.includes("对账明细") || normalized.includes("account_ledger") || normalized.includes("ledger")) return "account_ledger";
  if (normalized.includes("往来对账") || normalized.includes("对账") || normalized.includes("balance")) return "account_ledger";
  const masterKind = inferMasterKindFromFileName(fileName);
  return masterKind ? importFileTypeByKind[masterKind] : null;
}

function inferImportDataDateFromFileName(fileName: string): string | null {
  const normalized = fileName.replace(/\.[^.]+$/, "");
  const patterns = [
    /(^|[^\d])(20\d{2})[-_.\/年](0?[1-9]|1[0-2])[-_.\/月](0?[1-9]|[12]\d|3[01])日?($|[^\d])/,
    /(^|[^\d])(20\d{2})(0[1-9]|1[0-2])([0-3]\d)($|[^\d])/,
    /(^|[^\d])(\d{2})(0[1-9]|1[0-2])([0-3]\d)($|[^\d])/
  ];
  for (const pattern of patterns) {
    const match = normalized.match(pattern);
    if (!match) continue;
    const offset = match.length === 6 ? 1 : 0;
    const yearRaw = Number(match[1 + offset]);
    const year = yearRaw < 100 ? 2000 + yearRaw : yearRaw;
    const month = Number(match[2 + offset]);
    const day = Number(match[3 + offset]);
    const parsed = new Date(year, month - 1, day);
    if (parsed.getFullYear() === year && parsed.getMonth() === month - 1 && parsed.getDate() === day) {
      return `${year}-${String(month).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
    }
  }
  const monthPatterns = [
    /(^|[^\d])(20\d{2})(0[1-9]|1[0-2])($|[^\d])/,
    /(^|[^\d])(\d{2})(0[1-9]|1[0-2])($|[^\d])/
  ];
  for (const pattern of monthPatterns) {
    const match = normalized.match(pattern);
    if (!match) continue;
    const yearRaw = Number(match[2]);
    const year = yearRaw < 100 ? 2000 + yearRaw : yearRaw;
    const month = Number(match[3]);
    const day = new Date(year, month, 0).getDate();
    return `${year}-${String(month).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
  }
  return null;
}

