function pathFor(page: Page) {
  if (page === "dashboard") return "/dashboard";
  if (page === "exceptions") return "/exceptions";
  if (page === "crm") return "/crm";
  if (page === "crm-projects") return "/crm/projects";
  return `/${page}`;
}

function initialQueryParam(name: string) {
  return new URLSearchParams(window.location.search).get(name) ?? "";
}

function crmApprovalIdFromPath(path: string) {
  const query = path.split("?", 2)[1] ?? "";
  const raw = new URLSearchParams(query).get("approval_id") ?? "";
  if (!/^[1-9]\d*$/.test(raw)) return null;
  const approvalId = Number(raw);
  return Number.isSafeInteger(approvalId) ? approvalId : null;
}

function initialPositiveQueryId(name: string) {
  const value = initialQueryParam(name);
  if (!/^[1-9]\d*$/.test(value)) return null;
  const parsed = Number(value);
  return Number.isSafeInteger(parsed) ? parsed : null;
}

function replaceCurrentQueryParams(updates: Record<string, string | number | null | undefined>) {
  const params = new URLSearchParams(window.location.search);
  Object.entries(updates).forEach(([key, value]) => {
    if (value === null || value === undefined || value === "") params.delete(key);
    else params.set(key, String(value));
  });
  const query = params.toString();
  window.history.replaceState(null, "", `${window.location.pathname}${query ? `?${query}` : ""}`);
}

function withQuery(path: string, params: Record<string, string | number | null | undefined>) {
  const query = new URLSearchParams();
  Object.entries(params).forEach(([key, value]) => {
    if (value === null || value === undefined || value === "") return;
    query.set(key, String(value));
  });
  const queryString = query.toString();
  return queryString ? `${path}?${queryString}` : path;
}

function buildMasterRecordPath(kind: MasterKind, target: MasterRecordJump) {
  const query = target.code ?? target.name ?? "";
  const open = target.open ?? target.code ?? target.name ?? "";
  return withQuery("/master-data", { kind, q: query, open, tab: target.tab, source: target.source });
}

function buildProcessPath(page: ProcessPage, filters: Record<string, string | number | null | undefined> = {}) {
  return withQuery(pathFor(page), filters);
}

function buildCrmCustomerPath(target: MasterRecordJump) {
  const query = target.code ?? target.name ?? "";
  const open = target.open ?? target.code ?? target.name ?? "";
  return withQuery("/crm/customers", { q: query, open });
}

function createBusinessJumpTools(navigate: BusinessJumpNavigate): BusinessJumpTools {
  const openMasterRecord = (kind: MasterKind, target: MasterRecordJump) => {
    navigate("master-data", buildMasterRecordPath(kind, target));
  };
  const openProcessPage = (page: ProcessPage, filters: Record<string, string | number | null | undefined> = {}) => {
    navigate(page, buildProcessPath(page, filters));
  };
  const openCrmCustomer = (target: MasterRecordJump) => {
    navigate("crm", buildCrmCustomerPath(target));
  };
  const fallbackOpenSettlementUnit = (target: MasterRecordJump & { kindHint?: "customer" | "supplier" | "unknown" }) => {
    if (target.kindHint === "customer") {
      openMasterRecord("customers", target);
      return;
    }
    if (target.kindHint === "supplier") {
      openMasterRecord("suppliers", target);
      return;
    }
    openProcessPage("account-balance", {
      settlement_unit_code: target.code ?? undefined,
      settlement_unit_name: target.name ?? undefined
    });
  };
  const openSettlementUnit: BusinessJumpTools["openSettlementUnit"] = (target) => {
    void resolveSettlementUnit({
      code: target.code,
      name: target.name,
      arBalance: target.arBalance,
      apBalance: target.apBalance,
      advanceReceiptBalance: target.advanceReceiptBalance,
      advancePaymentBalance: target.advancePaymentBalance
    })
      .then((result) => {
        if (result.target?.kind === "customers") {
          openMasterRecord("customers", { code: result.target.code, name: result.target.name });
          return;
        }
        if (result.target?.kind === "suppliers") {
          openMasterRecord("suppliers", { code: result.target.code, name: result.target.name });
          return;
        }
        fallbackOpenSettlementUnit(target);
      })
      .catch(() => fallbackOpenSettlementUnit(target));
  };
  return {
    buildMasterRecordPath,
    buildProcessPath,
    buildCrmCustomerPath,
    openMasterRecord,
    openProcessPage,
    openCrmCustomer,
    openSettlementUnit
  };
}

function canAccessPage(page: Page, permissions: PermissionCode[]) {
  const item = navItems.find((navItem) => navItem.page === navigationPageFor(page));
  if (!item) return false;
  return item.enabled !== false && (!item.permissions || hasAnyPermission(permissions, item.permissions));
}

function fallbackPageForPermissions(permissions: PermissionCode[]): Page {
  return navItems.find((navItem) => canAccessPage(navItem.page, permissions))?.page ?? "dashboard";
}

function useRoute() {
  const [page, setPage] = useState<Page>(() => pageFromPath(window.location.pathname));
  const [locationKey, setLocationKey] = useState(() => `${window.location.pathname}${window.location.search}`);

  useEffect(() => {
    const syncLocation = () => {
      const currentPath = `${window.location.pathname}${window.location.search}`;
      const canonicalPath = currentPath.startsWith("/crm") ? canonicalCrmPath(currentPath) : currentPath;
      if (canonicalPath !== currentPath) window.history.replaceState(null, "", canonicalPath);
      setPage(pageFromPath(window.location.pathname));
      setLocationKey(`${window.location.pathname}${window.location.search}`);
    };
    const onPopState = () => {
      syncLocation();
    };
    syncLocation();
    window.addEventListener("popstate", onPopState);
    return () => window.removeEventListener("popstate", onPopState);
  }, []);

  const navigate = (next: Page, path = pathFor(next)) => {
    const canonicalPath = next === "crm" ? canonicalCrmPath(path) : path;
    window.history.pushState(null, "", canonicalPath);
    setPage(pageFromPath(window.location.pathname));
    setLocationKey(`${window.location.pathname}${window.location.search}`);
  };

  return { page, navigate, locationKey };
}

