function inferSettlementUnitKind(row: AccountBalanceRow): "customer" | "supplier" | "unknown" {
  const arBalance = Math.abs(Number(row.ar_balance ?? 0));
  const advanceReceiptBalance = Math.abs(Number(row.advance_receipt_balance ?? 0));
  const apBalance = Math.abs(Number(row.ap_balance ?? 0));
  const advancePaymentBalance = Math.abs(Number(row.advance_payment_balance ?? 0));
  const customerWeight = (Number.isNaN(arBalance) ? 0 : arBalance) + (Number.isNaN(advanceReceiptBalance) ? 0 : advanceReceiptBalance);
  const supplierWeight = (Number.isNaN(apBalance) ? 0 : apBalance) + (Number.isNaN(advancePaymentBalance) ? 0 : advancePaymentBalance);
  if (customerWeight > 0 && supplierWeight === 0) return "customer";
  if (supplierWeight > 0 && customerWeight === 0) return "supplier";
  return "unknown";
}

function AccountBalancePage({ permissions, jumpTools }: { permissions: PermissionCode[]; jumpTools: BusinessJumpTools }) {
  const canViewAccountBalance = hasPermission(permissions, "account_ledger.view");
  const canViewReceivable = hasPermission(permissions, "receivable.view");
  const initialTab = initialQueryParam("tab");
  const initialAttentionState = initialQueryParam("attention_state");
  const [activeTab, setActiveTab] = useState<"balance" | "check">(
    (initialTab === "check" || initialTab === "receivable") && canViewReceivable
        ? "check"
        : "balance"
  );
  const canView = canViewAccountBalance || canViewReceivable;
  const [pageData, setPageData] = useState<AccountLedgerPageData | null>(null);
  const [query, setQuery] = useState(() => initialQueryParam("q"));
  const [dateFrom, setDateFrom] = useState(() => initialQueryParam("date_from"));
  const [dateTo, setDateTo] = useState(() => initialQueryParam("date_to"));
  const [settlementUnitCode, setSettlementUnitCode] = useState(() => initialQueryParam("settlement_unit_code"));
  const [settlementUnitName, setSettlementUnitName] = useState(() => initialQueryParam("settlement_unit_name"));
  const [documentType, setDocumentType] = useState(() => initialQueryParam("document_type"));
  const [rowRole, setRowRole] = useState(() => initialQueryParam("row_role") || "closing");
  const [attentionState, setAttentionState] = useState<AttentionFilterValue>(() => initialAttentionState === "normal" || initialAttentionState === "needs_attention" ? initialAttentionState : initialQueryParam("attention_reason") ? "needs_attention" : "");
  const [attentionReason, setAttentionReason] = useState(() => initialQueryParam("attention_reason"));
  const [batchId, setBatchId] = useState(() => Number(initialQueryParam("batch_id")) || 0);
  const [currentPage, setCurrentPage] = useState(1);
  const [selectedRow, setSelectedRow] = useState<AccountLedgerRow | null>(null);
  const [hierarchyRoot, setHierarchyRoot] = useState<ProcessCategoryNode | null>(null);
  const [selectedCategoryId, setSelectedCategoryId] = useState("account_ledger:root");
  const [expandedCategoryIds, setExpandedCategoryIds] = useState<Set<string>>(() => new Set(["account_ledger:root"]));
  const [categorySearch, setCategorySearch] = useState("");
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");

  const totalRows = pageData?.total ?? 0;
  const totalPages = Math.max(1, Math.ceil(totalRows / ACCOUNT_BALANCE_PAGE_SIZE));
  const safeCurrentPage = Math.min(currentPage, totalPages);
  const offset = (safeCurrentPage - 1) * ACCOUNT_BALANCE_PAGE_SIZE;
  const rangeStart = totalRows === 0 ? 0 : offset + 1;
  const rangeEnd = Math.min(offset + ACCOUNT_BALANCE_PAGE_SIZE, totalRows);

  const loadRows = async () => {
    if (!canViewAccountBalance) {
      setPageData(null);
      return;
    }
    setLoading(true);
    setMessage("");
    try {
      const nextPage = await accountLedgerPage({
        q: query,
        dateFrom,
        dateTo,
        settlementUnitCode,
        settlementUnitName,
        documentType,
        rowRole,
        attentionState,
        attentionReason,
        snapshotScope: batchId ? undefined : dateFrom || dateTo ? "daily_latest" : "latest",
        batchId: batchId || undefined,
        categoryPath: selectedCategory?.path ?? [],
        limit: ACCOUNT_BALANCE_PAGE_SIZE,
        offset
      });
      setPageData(nextPage);
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "往来明细加载失败");
      setPageData(null);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void loadRows();
  }, [activeTab, canViewAccountBalance, query, dateFrom, dateTo, settlementUnitCode, settlementUnitName, documentType, rowRole, attentionState, attentionReason, batchId, selectedCategoryId, offset]);

  useEffect(() => {
    replaceCurrentQueryParams({
      tab: activeTab === "check" ? "check" : null,
      attention_state: activeTab === "balance" ? attentionState : null,
      attention_reason: activeTab === "balance" ? attentionReason : null,
      date_from: activeTab === "balance" ? dateFrom : null,
      date_to: activeTab === "balance" ? dateTo : null,
      row_role: activeTab === "balance" ? rowRole : null,
      snapshot_scope: activeTab === "balance" ? batchId ? null : dateFrom || dateTo ? "daily_latest" : "latest" : null,
      batch_id: activeTab === "balance" && batchId ? batchId : null
    });
  }, [activeTab, attentionState, attentionReason, batchId, dateFrom, dateTo, rowRole]);

  useEffect(() => {
    if (!canViewAccountBalance) {
      setHierarchyRoot(null);
      return;
    }
    void accountLedgerHierarchy({ dateFrom, dateTo, rowRole, snapshotScope: batchId ? undefined : dateFrom || dateTo ? "daily_latest" : "latest", batchId: batchId || undefined }).then(setHierarchyRoot).catch(() => setHierarchyRoot(null));
  }, [canViewAccountBalance, batchId, dateFrom, dateTo, rowRole]);

  useEffect(() => {
    if (activeTab === "balance" && !canViewAccountBalance && canViewReceivable) setActiveTab("check");
  }, [activeTab, canViewAccountBalance, canViewReceivable]);

  useEffect(() => {
    if (currentPage !== safeCurrentPage) setCurrentPage(safeCurrentPage);
  }, [currentPage, safeCurrentPage]);

  const resetFilters = () => {
    setCurrentPage(1);
    setQuery("");
    setDateFrom("");
    setDateTo("");
    setSettlementUnitCode("");
    setSettlementUnitName("");
    setDocumentType("");
    setRowRole("closing");
    setAttentionState("");
    setAttentionReason("");
    setBatchId(0);
    setSelectedCategoryId("account_ledger:root");
  };

  const summary = pageData?.summary;
  const attentionSummary = pageData?.attention_summary;
  const rows = pageData?.items ?? [];
  const selectedCategory = hierarchyRoot ? findProcessCategoryNode(hierarchyRoot, selectedCategoryId) ?? hierarchyRoot : null;
  const categoryStats = selectedCategory ? {
    current: selectedCategory.label,
    children: selectedCategory.children.length,
    records: selectedCategory.count,
    abnormal: selectedCategory.abnormal_count
  } : null;
  const currentPath = selectedCategory ? [hierarchyRoot?.label ?? "全部往来明细", ...selectedCategory.path] : [];
  const documentTypeOptions = [
    { value: "", label: "全部单据" },
    { value: "期初", label: "期初" },
    { value: "期末", label: "期末" },
    { value: "销售出库单", label: "销售出库单" },
    { value: "收款单", label: "收款单" },
    { value: "付款单", label: "付款单" },
    { value: "业务凭证", label: "业务凭证" }
  ];
  const rowRoleOptions = [
    { value: "", label: "全部行" },
    { value: "opening", label: "期初" },
    { value: "transaction", label: "明细" },
    { value: "closing", label: "期末" }
  ];

  const accountBalanceTable = (
    <DataTableShell
      title="往来明细列表"
      description={loading ? "正在加载往来明细。" : message || "点击任意行可查看该笔往来明细；结算单位可联动客户或供应商上下文。"}
      meta={`${rangeStart}-${rangeEnd} / ${totalRows} 条记录`}
      toolbar={
        <DataToolbar onReset={resetFilters}>
          <ToolbarSearch value={query} onChange={(value) => { setCurrentPage(1); setQuery(value); }} placeholder="搜索结算单位编号或名称" />
          <SalesFilterInput label="开始日期" type="date" value={dateFrom} onChange={(value) => { setCurrentPage(1); setBatchId(0); setDateFrom(value); }} />
          <SalesFilterInput label="结束日期" type="date" value={dateTo} onChange={(value) => { setCurrentPage(1); setBatchId(0); setDateTo(value); }} />
          <SalesFilterInput label="单位编号" value={settlementUnitCode} onChange={(value) => { setCurrentPage(1); setSettlementUnitCode(value); }} />
          <SalesFilterInput label="单位名称" value={settlementUnitName} onChange={(value) => { setCurrentPage(1); setSettlementUnitName(value); }} />
          <ToolbarSelect value={documentType} onChange={(value) => { setCurrentPage(1); setDocumentType(value); }} label="单据类型" options={documentTypeOptions} />
          <ToolbarSelect value={rowRole} onChange={(value) => {
            setCurrentPage(1);
            setRowRole(value);
            if (value !== "closing") {
              setAttentionState("");
              setAttentionReason("");
            }
          }} label="行角色" options={rowRoleOptions} />
        </DataToolbar>
      }
    >
      <Table headers={accountLedgerColumns.map((column) => accountLedgerColumnLabels[column] ?? column)}>
        {rows.map((row) => (
          <tr
            key={String(row.id)}
            onClick={() => setSelectedRow(row)}
            className={`project-table-row-interactive ${selectedRow?.id === row.id ? "project-table-row-active" : ""}`}
          >
            {accountLedgerColumns.map((column) => (
              <td key={column}>{column === "attention_reasons" ? <AttentionReasonDisplay row={row} valueLabel={(reason) => accountAttentionReasonLabel(reason, row)} /> : renderAccountLedgerCell(column, row, jumpTools)}</td>
            ))}
          </tr>
        ))}
      </Table>
      <MasterPagination
        currentPage={safeCurrentPage}
        totalPages={totalPages}
        totalItems={totalRows}
        pageSize={ACCOUNT_BALANCE_PAGE_SIZE}
        rangeStart={rangeStart}
        rangeEnd={rangeEnd}
        onPageChange={setCurrentPage}
      />
    </DataTableShell>
  );

  return (
    <>
      <Header
        eyebrow="ACCOUNT BALANCE"
        title="往来对账"
        description="按结算单位查看往来期初、发生、期末，以及应收、应付、预收、预付余额，承接日常往来对账线性表。"
        actions={<Button secondary onClick={() => void loadRows()} disabled={loading}><RefreshCcw className="mr-1.5 h-4 w-4" />刷新</Button>}
      />

      {canView ? (
        <>
          <div className="mb-4 flex flex-wrap gap-2">
            {canViewAccountBalance ? <button type="button" onClick={() => setActiveTab("balance")} className={`rounded-lg border px-4 py-2 text-sm font-black ${activeTab === "balance" ? "border-primary bg-primary-soft text-primary" : "border-slate-200 bg-white text-slate-600"}`}>往来明细</button> : null}
            {canViewReceivable ? <button type="button" onClick={() => setActiveTab("check")} className={`rounded-lg border px-4 py-2 text-sm font-black ${activeTab === "check" ? "border-primary bg-primary-soft text-primary" : "border-slate-200 bg-white text-slate-600"}`}>应收校验</button> : null}
          </div>

          {activeTab === "balance" && canViewAccountBalance ? (
            <>
          <div className="mb-4 grid gap-3 md:grid-cols-2 xl:grid-cols-4">
            <SalesMetricCard label="最新日期" value={formatDate(summary?.latest_data_date)} detail={`${summary?.settlement_units ?? 0} 个结算单位`} />
            <SalesMetricCard label="期初/期末" value={`${summary?.opening_rows ?? 0} / ${summary?.closing_rows ?? 0}`} detail={`${summary?.transaction_rows ?? 0} 行明细`} />
            <SalesMetricCard label="应收/应付" value={`${formatMoney(summary?.ar_amount)} / ${formatMoney(summary?.ap_amount)}`} detail={`应收非零 ${summary?.non_zero_ar_rows ?? 0} 行`} tone={(summary?.non_zero_ar_rows ?? 0) > 0 ? "neutral" : "ok"} />
            <SalesMetricCard label="实收/实付" value={`${formatMoney(summary?.received_amount)} / ${formatMoney(summary?.paid_amount)}`} detail={`${summary?.documents ?? 0} 张单据`} />
          </div>

          {rowRole === "closing" ? (
            <AttentionFilterPanel
              title="往来余额待核对"
              description="期末行的应收、应付、预收或预付任一余额非零时列为待核对；非零余额是正常经营状态，不代表错账。"
              summary={attentionSummary}
              state={attentionState}
              reason={attentionReason}
              normalLabel="余额已清"
              attentionLabel="待核对"
              effectiveLabel={attentionSummary?.effective_date ? `有效日期 ${formatDate(attentionSummary.effective_date)}${attentionSummary.batch_id ? ` · 批次 ${attentionSummary.batch_id}` : ""}` : batchId ? `批次 ${batchId}` : undefined}
              onStateChange={(value) => {
                setCurrentPage(1);
                setAttentionState(value);
                if (value !== "needs_attention") setAttentionReason("");
              }}
              onReasonChange={(value) => {
                setCurrentPage(1);
                setAttentionReason(value);
                setAttentionState(value ? "needs_attention" : "");
              }}
            />
          ) : (
            <div className="mb-4 rounded-lg border border-slate-200 bg-white px-4 py-3 text-sm font-bold text-slate-500">余额待核对筛选仅适用于期末行；切换回“期末”即可按原因筛选。</div>
          )}

          {hierarchyRoot && selectedCategory && categoryStats ? (
            <div className="grid gap-4 xl:grid-cols-[300px_minmax(0,1fr)]">
              <ProcessHierarchyPanel
                title="明细层级"
                root={hierarchyRoot}
                selectedId={selectedCategory.id}
                expandedIds={expandedCategoryIds}
                search={categorySearch}
                onSearchChange={setCategorySearch}
                onSelect={(node) => {
                  setCurrentPage(1);
                  setSelectedCategoryId(node.id);
                }}
                onToggle={(node) => {
                  setExpandedCategoryIds((current) => {
                    const next = new Set(current);
                    if (next.has(node.id)) next.delete(node.id);
                    else next.add(node.id);
                    return next;
                  });
                }}
              />
              <div className="min-w-0">
                <ProcessCategorySummary path={currentPath} stats={categoryStats} attentionLabel="余额待核对" />
                {accountBalanceTable}
              </div>
            </div>
          ) : accountBalanceTable}
            </>
          ) : activeTab === "check" && canViewReceivable ? (
            <ReceivableCheckPanel permissions={permissions} jumpTools={jumpTools} />
          ) : (
            <Card className="p-6 text-sm font-bold text-slate-500">当前账号没有该页签查看权限。</Card>
          )}
        </>
      ) : <Card className="p-6 text-sm font-bold text-slate-500">当前账号没有往来对账查看权限。</Card>}

      <AnimatePresence>
        {selectedRow ? (
          <AccountLedgerDrawer
            key={String(selectedRow.id)}
            row={selectedRow}
            canEdit={hasPermission(permissions, "account_ledger.edit")}
            permissions={permissions}
            jumpTools={jumpTools}
            onSaved={(updatedRow) => {
              setSelectedRow(updatedRow);
              setPageData((current) => current ? { ...current, items: current.items.map((item) => item.id === updatedRow.id ? updatedRow : item) } : current);
              void loadRows();
              void accountLedgerHierarchy({ dateFrom, dateTo, rowRole, snapshotScope: batchId ? undefined : dateFrom || dateTo ? "daily_latest" : "latest", batchId: batchId || undefined }).then(setHierarchyRoot).catch(() => setHierarchyRoot(null));
            }}
            onClose={() => setSelectedRow(null)}
          />
        ) : null}
      </AnimatePresence>
    </>
  );
}

function ReceivableSnapshotPanel({
  permissions,
  jumpTools,
  embedded = false,
  onCommitted
}: {
  permissions: PermissionCode[];
  jumpTools: BusinessJumpTools;
  embedded?: boolean;
  onCommitted?: () => void | Promise<void>;
}) {
  const fileInputId = useId();
  const canUploadReceivable = hasPermission(permissions, "import.upload") && hasPermission(permissions, "receivable.import");
  const canCommitReceivable = hasPermission(permissions, "import.commit") && hasPermission(permissions, "receivable.import");
  const canViewImportErrors = hasPermission(permissions, "import.view");
  const [pageData, setPageData] = useState<ReceivablePage | null>(null);
  const [query, setQuery] = useState("");
  const [dateFrom, setDateFrom] = useState("");
  const [dateTo, setDateTo] = useState("");
  const [matchStatus, setMatchStatus] = useState("");
  const [riskType, setRiskType] = useState("");
  const [importFile, setImportFile] = useState<File | null>(null);
  const [importDataDate, setImportDataDate] = useState("");
  const [importBatch, setImportBatch] = useState<ImportBatch | null>(null);
  const [importErrorRows, setImportErrorRows] = useState<ImportErrorRow[]>([]);
  const [recentBatches, setRecentBatches] = useState<ImportBatch[]>([]);
  const [importMessage, setImportMessage] = useState("上传应收查询表后，系统会用它校验往来明细中的应收部分。");
  const [currentPage, setCurrentPage] = useState(1);
  const [selectedRow, setSelectedRow] = useState<ReceivableRow | null>(null);
  const [loading, setLoading] = useState(false);
  const [importLoading, setImportLoading] = useState(false);
  const [message, setMessage] = useState("");
  const totalRows = pageData?.total ?? 0;
  const totalPages = Math.max(1, Math.ceil(totalRows / ACCOUNT_BALANCE_PAGE_SIZE));
  const safeCurrentPage = Math.min(currentPage, totalPages);
  const offset = (safeCurrentPage - 1) * ACCOUNT_BALANCE_PAGE_SIZE;
  const rangeStart = totalRows === 0 ? 0 : offset + 1;
  const rangeEnd = Math.min(offset + ACCOUNT_BALANCE_PAGE_SIZE, totalRows);
  const summary = pageData?.summary;

  const loadRows = async () => {
    setLoading(true);
    setMessage("");
    try {
      setPageData(await receivablesPage({
        q: query,
        dateFrom,
        dateTo,
        matchStatus,
        riskType,
        limit: ACCOUNT_BALANCE_PAGE_SIZE,
        offset
      }));
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "应收查询加载失败");
      setPageData(null);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void loadRows();
  }, [query, dateFrom, dateTo, matchStatus, riskType, offset]);

  useEffect(() => {
    if (currentPage !== safeCurrentPage) setCurrentPage(safeCurrentPage);
  }, [currentPage, safeCurrentPage]);

  const loadRecentBatches = async () => {
    if (!canViewImportErrors) {
      setRecentBatches([]);
      return;
    }
    setRecentBatches(await batches({ file_type: "receivable_snapshot", limit: 6 }));
  };

  useEffect(() => {
    void loadRecentBatches().catch(() => setRecentBatches([]));
  }, [canViewImportErrors]);

  const resetFilters = () => {
    setCurrentPage(1);
    setQuery("");
    setDateFrom("");
    setDateTo("");
    setMatchStatus("");
    setRiskType("");
  };

  const loadImportErrors = async (batch: ImportBatch) => {
    if (!canViewImportErrors || batch.error_rows <= 0) {
      setImportErrorRows([]);
      return;
    }
    setImportErrorRows(await importErrors(batch.id));
  };

  const uploadReceivable = async () => {
    if (!importFile) {
      setImportMessage("请选择要上传的应收查询表。");
      return;
    }
    setImportLoading(true);
    setImportMessage("正在上传应收查询表。");
    try {
      const form = new FormData();
      form.set("file_type", "receivable_snapshot");
      if (importDataDate) form.set("data_date", importDataDate);
      form.set("file", importFile);
      const batch = await uploadImport(form);
      setImportBatch(batch);
      if (batch.data_date) setImportDataDate(String(batch.data_date).slice(0, 10));
      setImportMessage(`已上传批次 ${batch.batch_no}，系统识别日期：${formatDate(batch.data_date)}，请继续预校验。`);
      await loadImportErrors(batch);
      await loadRecentBatches();
    } catch (error) {
      setImportMessage(error instanceof Error ? error.message : "应收查询表上传失败。");
    } finally {
      setImportLoading(false);
    }
  };

  const validateReceivable = async () => {
    if (!importBatch) return;
    setImportLoading(true);
    setImportMessage("正在预校验应收查询表。");
    try {
      const batch = await validateImport(importBatch.id);
      setImportBatch(batch);
      setImportMessage(batch.error_rows > 0 ? `预校验完成，发现 ${batch.error_rows} 行错误。` : "预校验通过，可以提交入库。");
      await loadImportErrors(batch);
    } catch (error) {
      setImportMessage(error instanceof Error ? error.message : "应收查询表预校验失败。");
    } finally {
      setImportLoading(false);
    }
  };

  const commitReceivable = async () => {
    if (!importBatch) return;
    setImportLoading(true);
    setImportMessage("正在提交应收查询表入库。");
    try {
      const batch = await commitImport(importBatch.id);
      setImportBatch(batch);
      setImportMessage(batch.status === "committed" ? "应收查询已入库，应收校验结果已刷新。" : `当前批次状态：${batch.status}`);
      await loadImportErrors(batch);
      await loadRecentBatches();
      if (batch.status === "committed") {
        setCurrentPage(1);
        await loadRows();
        await onCommitted?.();
      }
    } catch (error) {
      setImportMessage(error instanceof Error ? error.message : "应收查询提交失败。");
    } finally {
      setImportLoading(false);
    }
  };

  const rows = pageData?.items ?? [];
  return (
    <>
      <div className={`mb-4 grid min-w-0 gap-4 ${embedded ? "xl:grid-cols-[minmax(0,1fr)_320px]" : ""}`}>
      <Card className="min-w-0 p-4">
        <div className="grid items-end gap-3 lg:grid-cols-[minmax(320px,1fr)_220px_260px]">
          <div className="grid min-w-0 gap-1.5">
            <span className="text-xs font-black text-muted-foreground">应收查询表</span>
            <input
              id={fileInputId}
              type="file"
              accept=".csv,.xls,.xlsx"
              disabled={!canUploadReceivable || importLoading}
              onChange={(event) => {
                const file = event.target.files?.[0] ?? null;
                setImportFile(file);
                if (!file) return;
                const inferredDate = inferImportDataDateFromFileName(file.name);
                if (inferredDate) {
                  setImportDataDate(inferredDate);
                  setImportMessage(`系统从文件名识别日期：${inferredDate}，可手动修改。`);
                } else {
                  setImportDataDate("");
                  setImportMessage("文件名未识别到日期，上传后会继续读取表格内日期字段。");
                }
              }}
              className="sr-only"
            />
            <label
              htmlFor={fileInputId}
              className={`flex h-11 min-w-0 cursor-pointer items-center gap-3 rounded-lg border border-slate-200 bg-white px-3 text-sm font-bold transition hover:border-primary hover:bg-primary-soft ${!canUploadReceivable || importLoading ? "pointer-events-none bg-slate-50 text-slate-400" : "text-slate-700"}`}
            >
              <span className="inline-flex h-7 shrink-0 items-center rounded-md border border-slate-200 bg-slate-50 px-2.5 text-xs font-black text-slate-700">
                选择文件
              </span>
              <span className={`min-w-0 truncate ${importFile ? "text-slate-900" : "text-slate-400"}`}>
                {importFile ? importFile.name : "未选择文件"}
              </span>
            </label>
          </div>
          <label className="grid min-w-0 gap-1.5">
            <span className="text-xs font-black text-muted-foreground">查询日期</span>
            <input
              type="date"
              value={importDataDate}
              onChange={(event) => setImportDataDate(event.target.value)}
              className="h-11 rounded-lg border border-slate-200 bg-white px-3 text-sm font-black text-slate-700 outline-none transition focus:border-primary focus:ring-4 focus:ring-primary/10"
            />
          </label>
          <div className="flex h-11 items-stretch justify-end gap-2">
            <Button onClick={() => void uploadReceivable()} disabled={!canUploadReceivable || importLoading}>上传查询</Button>
            <Button secondary onClick={() => void validateReceivable()} disabled={!canCommitReceivable || !importBatch || importLoading}>预校验</Button>
            <Button secondary onClick={() => void commitReceivable()} disabled={!canCommitReceivable || !importBatch || importBatch.error_rows > 0 || importLoading}>提交入库</Button>
          </div>
        </div>
        <div className="mt-3 grid gap-2 lg:grid-cols-[minmax(0,1fr)_auto] lg:items-center">
          <p className="m-0 text-sm font-bold text-primary">{importMessage}</p>
          {importBatch ? <span className="text-xs font-black text-slate-500">批次 {importBatch.batch_no} · 状态 {importBatch.status} · 错误 {importBatch.error_rows}</span> : null}
        </div>
        {importErrorRows.length > 0 ? (
          <div className="mt-3 rounded-lg border border-amber-200 bg-amber-50 p-3">
            <p className="m-0 text-xs font-black text-amber-700">错误行预览</p>
            <div className="mt-2 grid gap-1">
              {importErrorRows.slice(0, 3).map((row) => (
                <p key={row.id} className="m-0 text-xs font-bold text-amber-700">第 {row.row_number} 行：{row.error_message}</p>
              ))}
            </div>
          </div>
        ) : null}
      </Card>
      {embedded ? (
        <Card className="min-w-0 overflow-hidden p-4">
          <div className="flex min-w-0 items-start justify-between gap-3">
            <div className="min-w-0">
              <p className="m-0 text-xs font-black uppercase tracking-[0.12em] text-primary">CHECK TIMELINE</p>
              <h3 className="m-0 mt-1 text-base font-black text-slate-900">应收查询批次</h3>
            </div>
            <span className="shrink-0"><Badge tone={recentBatches.some((batch) => batch.error_rows > 0) ? "warn" : "neutral"}>{recentBatches.length} 批</Badge></span>
          </div>
          <div className="mt-3 grid min-w-0 gap-2">
            {recentBatches.length ? recentBatches.map((batch) => (
              <div key={batch.id} className="min-w-0 overflow-hidden rounded-lg border border-slate-200 bg-slate-50 p-3">
                <div className="flex min-w-0 items-start justify-between gap-2">
                  <span className="min-w-0 truncate text-xs font-black text-slate-700" title={batch.file_name}>{batch.file_name}</span>
                  <span className="shrink-0"><Badge tone={batch.error_rows > 0 ? "warn" : batch.status === "committed" ? "ok" : "neutral"}>{importBatchStatusLabel(batch.status)}</Badge></span>
                </div>
                <div className="mt-2 grid min-w-0 gap-1 text-xs font-bold leading-5 text-slate-500 sm:grid-cols-2 xl:grid-cols-1">
                  <span className="min-w-0 truncate">识别日期 {formatDate(batch.data_date)}</span>
                  <span className="min-w-0 truncate">行数 {batch.success_rows}/{batch.total_rows}</span>
                  <span className="min-w-0 truncate">错误 {batch.error_rows}</span>
                  <span className="min-w-0 truncate" title={formatDateTime(batch.uploaded_at)}>{formatDateTime(batch.uploaded_at)}</span>
                </div>
              </div>
            )) : (
              <p className="m-0 rounded-lg border border-dashed border-slate-200 bg-slate-50 px-3 py-6 text-center text-sm font-bold text-slate-500">
                暂无应收查询批次。
              </p>
            )}
          </div>
        </Card>
      ) : null}
      </div>
      <div className="mb-4 grid gap-3 md:grid-cols-2 xl:grid-cols-4">
        <SalesMetricCard label="最新日期" value={formatDate(summary?.latest_data_date)} detail={`${summary?.rows ?? 0} 行应收查询`} />
        <SalesMetricCard label="应收余额" value={formatMoney(summary?.ar_balance)} detail={`${summary?.customers ?? 0} 个客户`} tone={Number(summary?.ar_balance ?? 0) === 0 ? "neutral" : "ok"} />
        <SalesMetricCard label="未匹配单位" value={summary?.unmatched_rows ?? 0} detail="需核对结算单位编号或名称" tone={(summary?.unmatched_rows ?? 0) > 0 ? "neutral" : "ok"} />
        <SalesMetricCard label="差异项" value={summary?.risk_rows ?? 0} detail="由应收校验生成" tone={(summary?.risk_rows ?? 0) > 0 ? "neutral" : "ok"} />
      </div>
      {!embedded ? <DataTableShell
        title="应收查询列表"
        description={loading ? "正在加载应收查询。" : message || "点击结算单位可查看应收时间轴；编号缺失时不会阻断导入，会按名称参与校验。"}
        meta={`${rangeStart}-${rangeEnd} / ${totalRows} 条记录`}
        toolbar={
          <DataToolbar onReset={resetFilters}>
            <ToolbarSearch value={query} onChange={(value) => { setCurrentPage(1); setQuery(value); }} placeholder="搜索结算单位、业务员" />
            <SalesFilterInput label="开始日期" type="date" value={dateFrom} onChange={(value) => { setCurrentPage(1); setDateFrom(value); }} />
            <SalesFilterInput label="结束日期" type="date" value={dateTo} onChange={(value) => { setCurrentPage(1); setDateTo(value); }} />
            <ToolbarSelect value={matchStatus} onChange={(value) => { setCurrentPage(1); setMatchStatus(value); }} label="匹配状态" options={receivableMatchStatusOptions} />
            <ToolbarSelect value={riskType} onChange={(value) => { setCurrentPage(1); setRiskType(value); }} label="风险类型" options={receivableRiskTypeOptions} />
          </DataToolbar>
        }
      >
        <Table headers={["日期", "结算单位编号", "结算单位名称", "应收查询金额", "账龄", "业务员", "匹配状态"]}>
          {rows.map((row) => (
            <tr key={String(row.id)} onClick={() => setSelectedRow(row)} className={`project-table-row-interactive ${selectedRow?.id === row.id ? "project-table-row-active" : ""}`}>
              <td>{formatDate(row.data_date)}</td>
              <td>{displayValue(row.matched_customer_code ?? row.customer_code)}</td>
              <td>
                <BusinessLinkCell
                  value={row.matched_customer_name ?? row.customer_name}
                  title="打开客户上下文"
                  onClick={() => jumpTools.openSettlementUnit({
                    code: row.matched_customer_code ?? row.customer_code,
                    name: row.matched_customer_name ?? row.customer_name,
                    kindHint: "customer",
                    arBalance: row.ar_balance
                  })}
                />
              </td>
              <td>{formatMoney(row.ar_balance)}</td>
              <td>{displayValue(row.aging_label ?? (row.overdue_days ? `${row.overdue_days} 天` : null))}</td>
              <td>{displayValue(row.salesperson_name)}</td>
              <td>{receivableMatchStatusLabels[row.match_status] ?? row.match_status}</td>
            </tr>
          ))}
        </Table>
        <MasterPagination
          currentPage={safeCurrentPage}
          totalPages={totalPages}
          totalItems={totalRows}
          pageSize={ACCOUNT_BALANCE_PAGE_SIZE}
          rangeStart={rangeStart}
          rangeEnd={rangeEnd}
          onPageChange={setCurrentPage}
        />
      </DataTableShell> : null}
      <AnimatePresence>
        {!embedded && selectedRow ? (
          <ReceivableTimelineDrawer
            key={String(selectedRow.id)}
            row={selectedRow}
            permissions={permissions}
            jumpTools={jumpTools}
            onClose={() => setSelectedRow(null)}
          />
        ) : null}
      </AnimatePresence>
    </>
  );
}

function ReceivableCheckPanel({ permissions, jumpTools }: { permissions: PermissionCode[]; jumpTools: BusinessJumpTools }) {
  const canRebuild = hasPermission(permissions, "receivable.check");
  const [pageData, setPageData] = useState<ReceivableCheckResultPage | null>(null);
  const [query, setQuery] = useState(() => initialQueryParam("q"));
  const [dateFrom, setDateFrom] = useState(() => initialQueryParam("date_from"));
  const [dateTo, setDateTo] = useState(() => initialQueryParam("date_to"));
  const [resultType, setResultType] = useState(() => initialQueryParam("result_type"));
  const [currentPage, setCurrentPage] = useState(1);
  const [selectedResult, setSelectedResult] = useState<ReceivableCheckResult | null>(null);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");
  const totalRows = pageData?.total ?? 0;
  const totalPages = Math.max(1, Math.ceil(totalRows / ACCOUNT_BALANCE_PAGE_SIZE));
  const safeCurrentPage = Math.min(currentPage, totalPages);
  const offset = (safeCurrentPage - 1) * ACCOUNT_BALANCE_PAGE_SIZE;
  const rangeStart = totalRows === 0 ? 0 : offset + 1;
  const rangeEnd = Math.min(offset + ACCOUNT_BALANCE_PAGE_SIZE, totalRows);

  const loadRows = async () => {
    setLoading(true);
    setMessage("");
    try {
      setPageData(await receivableCheckResults({
        resultType,
        q: query,
        dateFrom,
        dateTo,
        limit: ACCOUNT_BALANCE_PAGE_SIZE,
        offset
      }));
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "应收校验加载失败");
      setPageData(null);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void loadRows();
  }, [query, dateFrom, dateTo, resultType, offset]);

  useEffect(() => {
    if (currentPage !== safeCurrentPage) setCurrentPage(safeCurrentPage);
  }, [currentPage, safeCurrentPage]);

  const resetFilters = () => {
    setCurrentPage(1);
    setQuery("");
    setDateFrom("");
    setDateTo("");
    setResultType("");
  };

  const rebuild = async () => {
    setLoading(true);
    setMessage("正在重建应收校验结果。");
    try {
      const result = await rebuildReceivableCheck();
      setMessage(`校验已重建：${result.total_rows ?? 0} 行，风险 ${result.risk_rows ?? 0} 项。`);
      await loadRows();
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "重建应收校验失败");
    } finally {
      setLoading(false);
    }
  };

  const rows = pageData?.items ?? [];
  const summary = pageData?.summary ?? {};
  return (
    <>
      <div className="mb-4 flex flex-wrap gap-2">
        <button type="button" className="rounded-lg border border-primary bg-primary-soft px-4 py-2 text-sm font-black text-primary">应收查询校验</button>
      </div>
      <ReceivableSnapshotPanel
        embedded
        permissions={permissions}
        jumpTools={jumpTools}
        onCommitted={() => {
          setCurrentPage(1);
          return loadRows();
        }}
      />
      <div className="mb-4 grid gap-3 md:grid-cols-2 xl:grid-cols-5">
        <SalesMetricCard label="金额不一致" value={summary.amount_mismatch ?? 0} detail="双方都有但金额不同" tone={(summary.amount_mismatch ?? 0) > 0 ? "neutral" : "ok"} />
        <SalesMetricCard label="往来缺失" value={summary.missing_in_ledger ?? 0} detail="应收查询有而往来无" tone={(summary.missing_in_ledger ?? 0) > 0 ? "neutral" : "ok"} />
        <SalesMetricCard label="应收查询缺失" value={summary.missing_in_receivable_query ?? 0} detail="往来有而查询无" tone={(summary.missing_in_receivable_query ?? 0) > 0 ? "neutral" : "ok"} />
        <SalesMetricCard label="名称不一致" value={summary.unit_name_mismatch ?? 0} detail="编号一致但名称不同" tone={(summary.unit_name_mismatch ?? 0) > 0 ? "neutral" : "ok"} />
        <SalesMetricCard label="重复结算单位" value={summary.duplicate_unit ?? 0} detail="同来源同单位重复" tone={(summary.duplicate_unit ?? 0) > 0 ? "neutral" : "ok"} />
      </div>
      <DataTableShell
        title="应收校验差异"
        description={loading ? "正在加载应收校验。" : message || "系统按结算单位编号/名称，将应收查询表与往来明细期初/期末应收进行比对。"}
        meta={`${rangeStart}-${rangeEnd} / ${totalRows} 条记录`}
        toolbar={
          <DataToolbar onReset={resetFilters}>
            <ToolbarSearch value={query} onChange={(value) => { setCurrentPage(1); setQuery(value); }} placeholder="搜索结算单位" />
            <SalesFilterInput label="开始日期" type="date" value={dateFrom} onChange={(value) => { setCurrentPage(1); setDateFrom(value); }} />
            <SalesFilterInput label="结束日期" type="date" value={dateTo} onChange={(value) => { setCurrentPage(1); setDateTo(value); }} />
            <ToolbarSelect value={resultType} onChange={(value) => { setCurrentPage(1); setResultType(value); }} label="差异类型" options={receivableRiskTypeOptions} />
            {canRebuild ? <Button secondary onClick={() => void rebuild()} disabled={loading}><RefreshCcw className="mr-1.5 h-4 w-4" />重建校验</Button> : null}
          </DataToolbar>
        }
      >
        <Table headers={["日期", "差异类型", "结算单位", "应收查询金额", "往来明细应收", "差异", "说明"]}>
          {rows.map((row) => (
            <tr key={String(row.id)} onClick={() => setSelectedResult(row)} className={`project-table-row-interactive ${selectedResult?.id === row.id ? "project-table-row-active" : ""}`}>
              <td>{formatDate(row.data_date)}</td>
              <td>{row.result_label}</td>
              <td>
                <BusinessLinkCell
                  value={row.matched_customer_name ?? row.customer_name}
                  title="打开客户上下文"
                  onClick={() => jumpTools.openSettlementUnit({
                    code: row.matched_customer_code ?? row.customer_code,
                    name: row.matched_customer_name ?? row.customer_name,
                    kindHint: "customer",
                    arBalance: row.receivable_ar_balance
                  })}
                />
              </td>
              <td>{formatMoney(row.receivable_ar_balance)}</td>
              <td>{formatMoney(row.account_ar_balance ?? row.previous_ar_balance)}</td>
              <td>{formatMoney(row.diff_amount)}</td>
              <td>{displayValue(row.message)}</td>
            </tr>
          ))}
        </Table>
        <MasterPagination
          currentPage={safeCurrentPage}
          totalPages={totalPages}
          totalItems={totalRows}
          pageSize={ACCOUNT_BALANCE_PAGE_SIZE}
          rangeStart={rangeStart}
          rangeEnd={rangeEnd}
          onPageChange={setCurrentPage}
        />
      </DataTableShell>
      <AnimatePresence>
        {selectedResult ? (
          <ReceivableCheckDrawer
            result={selectedResult}
            jumpTools={jumpTools}
            onClose={() => setSelectedResult(null)}
          />
        ) : null}
      </AnimatePresence>
    </>
  );
}

function ReceivableTimelineDrawer({
  row,
  permissions,
  jumpTools,
  onClose
}: {
  row: ReceivableRow;
  permissions: PermissionCode[];
  jumpTools: BusinessJumpTools;
  onClose: () => void;
}) {
  const [timeline, setTimeline] = useState<ReceivableRow[]>([]);
  const [loading, setLoading] = useState(false);
  useEffect(() => {
    setLoading(true);
    void receivableTimeline({
      customerCode: row.matched_customer_code ?? row.customer_code ?? undefined,
      customerName: row.matched_customer_name ?? row.customer_name ?? undefined,
      limit: 30
    }).then((result) => setTimeline(result.items)).catch(() => setTimeline([])).finally(() => setLoading(false));
  }, [row.id]);
  const customerCode = row.matched_customer_code ?? row.customer_code;
  const customerName = row.matched_customer_name ?? row.customer_name;
  return (
    <Drawer
      title={`应收查询：${displayValue(customerName)}`}
      subtitle={`${formatDate(row.data_date)} · 应收 ${formatMoney(row.ar_balance)} · ${receivableMatchStatusLabels[row.match_status] ?? row.match_status}`}
      onClose={onClose}
    >
      <div className="grid gap-4 xl:grid-cols-[minmax(0,1fr)_320px]">
        <div className="grid gap-3">
          <DetailGroups
            groups={[
              {
                title: "结算单位与匹配",
                icon: Building2,
                fields: [
                  ["结算单位编号", customerCode],
                  ["结算单位名称", customerName],
                  ["原始编号", row.customer_code],
                  ["原始名称", row.customer_name],
                  ["匹配状态", receivableMatchStatusLabels[row.match_status] ?? row.match_status],
                  ["业务员", row.salesperson_name],
                  ["部门", row.department_name]
                ]
              },
              {
                title: "应收余额",
                icon: CircleDollarSign,
                fields: [
                  ["数据日期", formatDate(row.data_date)],
                  ["期初应收", formatMoney(row.ar_opening_balance)],
                  ["本期发生", formatMoney(row.ar_current_amount)],
                  ["已收金额", formatMoney(row.received_amount)],
                  ["未收金额", formatMoney(row.unreceived_amount)],
                  ["应收余额", formatMoney(row.ar_balance)],
                  ["账龄", row.aging_label],
                  ["逾期天数", row.overdue_days]
                ]
              }
            ]}
          />
          <Card className="p-4">
            <div className="flex items-center justify-between gap-3">
              <p className="m-0 text-sm font-black text-slate-900">应收时间轴</p>
              <span className="text-xs font-bold text-slate-500">{loading ? "加载中" : `${timeline.length} 条记录`}</span>
            </div>
            <div className="mt-3 grid gap-2">
              {timeline.length ? timeline.map((item) => (
                <div key={item.id} className="rounded-lg border border-slate-200 bg-slate-50 p-3">
                  <div className="flex items-center justify-between gap-3">
                    <span className="text-xs font-black text-slate-700">{formatDate(item.data_date)}</span>
                    <span className="text-sm font-black text-slate-900">{formatMoney(item.ar_balance)}</span>
                  </div>
                  <p className="m-0 mt-1 text-xs font-bold text-slate-500">{displayValue(item.aging_label ?? item.remark)}</p>
                </div>
              )) : <p className="m-0 text-sm font-bold text-slate-500">暂无历史应收记录。</p>}
            </div>
          </Card>
        </div>
        <aside className="grid content-start gap-3">
          <CustomerSideCard title="快捷联动" icon={ExternalLink}>
            <Button secondary onClick={() => jumpTools.openSettlementUnit({ code: customerCode, name: customerName, kindHint: "customer", arBalance: row.ar_balance })}>客户上下文</Button>
            {hasPermission(permissions, "customer.view") ? <Button secondary onClick={() => jumpTools.openMasterRecord("customers", { code: customerCode, name: customerName })}>客户档案</Button> : null}
            <Button secondary onClick={() => jumpTools.openProcessPage("account-balance", { settlement_unit_code: customerCode, settlement_unit_name: customerName })}>往来明细</Button>
          </CustomerSideCard>
          <CustomerSideCard title="备注" icon={History}>
            <CustomerSideRow label="备注" value={displayValue(row.remark)} multiline />
          </CustomerSideCard>
        </aside>
      </div>
    </Drawer>
  );
}

function ReceivableCheckDrawer({ result, jumpTools, onClose }: { result: ReceivableCheckResult; jumpTools: BusinessJumpTools; onClose: () => void }) {
  const customerCode = result.matched_customer_code ?? result.customer_code;
  const customerName = result.matched_customer_name ?? result.customer_name;
  const displayAmount = result.receivable_ar_balance ?? result.account_ar_balance;
  return (
    <Drawer
      title={`应收校验：${result.result_label}`}
      subtitle={`${formatDate(result.data_date)} · ${displayValue(customerName)} · ${formatMoney(displayAmount)}`}
      onClose={onClose}
    >
      <div className="grid gap-4 xl:grid-cols-[minmax(0,1fr)_320px]">
        <DetailGroups
          groups={[
            {
              title: "差异说明",
              icon: FileWarning,
              fields: [
                ["差异类型", result.result_label],
                ["风险等级", result.severity === "danger" ? "高风险" : "关注"],
                ["说明", result.message],
                ["数据日期", formatDate(result.data_date)]
              ]
            },
            {
              title: "金额对照",
              icon: CircleDollarSign,
              fields: [
                ["应收查询金额", formatMoney(result.receivable_ar_balance)],
                ["往来明细应收", formatMoney(result.account_ar_balance)],
                ["差异金额", formatMoney(result.diff_amount)]
              ]
            },
            {
              title: "结算单位匹配",
              icon: Building2,
              fields: [
                ["结算单位编号", customerCode],
                ["结算单位名称", customerName],
                ["原始编号", result.customer_code],
                ["原始名称", result.customer_name]
              ]
            }
          ]}
        />
        <aside className="grid content-start gap-3">
          <CustomerSideCard title="处理入口" icon={ExternalLink}>
            <Button secondary onClick={() => jumpTools.openSettlementUnit({ code: customerCode, name: customerName, kindHint: "customer", arBalance: displayAmount })}>客户上下文</Button>
            <Button secondary onClick={() => jumpTools.openProcessPage("account-balance", { settlement_unit_code: customerCode, settlement_unit_name: customerName })}>往来明细</Button>
          </CustomerSideCard>
        </aside>
      </div>
    </Drawer>
  );
}

const accountLedgerRoleLabels: Record<string, string> = {
  opening: "期初",
  transaction: "明细",
  closing: "期末"
};

function AccountLedgerDrawer({
  row,
  canEdit,
  permissions: _permissions,
  jumpTools,
  onSaved,
  onClose
}: {
  row: AccountLedgerRow;
  canEdit: boolean;
  permissions: PermissionCode[];
  jumpTools: BusinessJumpTools;
  onSaved: (row: AccountLedgerRow) => void;
  onClose: () => void;
}) {
  const [mode, setMode] = useState<"view" | "edit">("view");
  const [currentRow, setCurrentRow] = useState(row);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  useEffect(() => {
    setCurrentRow(row);
    setMode("view");
    setError("");
  }, [row]);

  const save = async (payload: Record<string, string | number | null>) => {
    setSaving(true);
    setError("");
    try {
      const updatedRow = await updateAccountLedgerEntry(Number(currentRow.id), payload);
      setCurrentRow(updatedRow);
      onSaved(updatedRow);
      setMode("view");
    } catch (saveError) {
      setError(saveError instanceof Error ? saveError.message : "保存往来明细失败。");
    } finally {
      setSaving(false);
    }
  };

  const settlementCode = String(currentRow.settlement_unit_code ?? "");
  const settlementName = String(currentRow.settlement_unit_name ?? "");
  return (
    <Drawer
      title={`往来明细：${displayValue(currentRow.settlement_unit_name)}`}
      subtitle={`${formatDate(currentRow.data_date)} · ${displayValue(currentRow.document_type)} · ${displayValue(currentRow.document_no)}`}
      onClose={onClose}
    >
      <ProcessDrawerToolbar mode={mode} canEdit={canEdit} saving={saving} error={error} editLabel="编辑往来明细" onEdit={() => setMode("edit")} onCancel={() => setMode("view")} />
      <AttentionDetailNotice title="往来余额待核对原因" row={currentRow} valueLabel={(reason) => accountAttentionReasonLabel(reason, currentRow)} />
      {mode === "edit" ? (
        <ProcessEditForm
          row={currentRow}
          fields={[
            ["settlement_unit_name", "结算单位名称"],
            ["document_type", "单据类型"],
            ["document_date", "单据日期"],
            ["document_no", "单据编号"],
            ["handler_name", "经手人"],
            ["counterparty_name", "往来单位"],
            ["document_amount", "单据金额", "number"],
            ["received_amount", "实收金额", "number"],
            ["ar_amount", "应收金额", "number"],
            ["paid_amount", "实付金额", "number"],
            ["ap_amount", "应付金额", "number"],
            ["current_balance", "往来余额", "number"],
            ["summary", "摘要"],
            ["description", "说明"],
            ["reconciliation_mark", "对账标记"]
          ]}
          saving={saving}
          onCancel={() => setMode("view")}
          onSubmit={save}
        />
      ) : (
      <div className="grid gap-4 xl:grid-cols-[minmax(0,1fr)_320px]">
        <div className="grid gap-3">
          <DetailGroups
            groups={[
              {
                title: "结算单位",
                icon: Building2,
                fields: [
                  ["归属日期", formatDate(currentRow.data_date)],
                  ["结算单位编号", currentRow.settlement_unit_code],
                  ["结算单位名称", currentRow.settlement_unit_name],
                  ["行角色", accountLedgerRoleLabels[String(currentRow.row_role)] ?? currentRow.row_role],
                  ["批次 ID", currentRow.batch_id],
                  ["原始行号", currentRow.row_number]
                ]
              },
              {
                title: "单据信息",
                icon: ClipboardList,
                fields: [
                  ["单据类型", currentRow.document_type],
                  ["单据日期", formatDate(currentRow.document_date)],
                  ["单据编号", currentRow.document_no],
                  ["经手人", currentRow.handler_name],
                  ["往来单位", currentRow.counterparty_name],
                  ["对账标记", currentRow.reconciliation_mark]
                ]
              },
              {
                title: "金额结构",
                icon: CircleDollarSign,
                fields: [
                  ["单据金额", formatMoney(currentRow.document_amount)],
                  ["实收金额", formatMoney(currentRow.received_amount)],
                  ["应收金额", formatMoney(currentRow.ar_amount)],
                  ["实付金额", formatMoney(currentRow.paid_amount)],
                  ["应付金额", formatMoney(currentRow.ap_amount)],
                  ["预收金额", formatMoney(currentRow.advance_receipt_amount)],
                  ["预付金额", formatMoney(currentRow.advance_payment_amount)],
                  ["往来余额", formatMoney(currentRow.current_balance)]
                ]
              },
              {
                title: "备注",
                icon: History,
                fields: [
                  ["摘要", currentRow.summary],
                  ["说明", currentRow.description]
                ]
              }
            ]}
          />
        </div>
        <aside className="grid content-start gap-3">
          <CustomerSideCard title="快捷联动" icon={ExternalLink}>
            <Button secondary onClick={() => jumpTools.openSettlementUnit({ code: settlementCode, name: settlementName, kindHint: "customer", arBalance: currentRow.ar_amount, apBalance: currentRow.ap_amount })}>结算单位上下文</Button>
            <Button secondary onClick={() => jumpTools.openProcessPage("account-balance", { settlement_unit_code: settlementCode, settlement_unit_name: settlementName })}>筛选该单位</Button>
          </CustomerSideCard>
          <CustomerSideCard title="核验提示" icon={FileWarning}>
            <CustomerSideRow label="应收金额" value={formatMoney(currentRow.ar_amount)} />
            <CustomerSideRow label="行角色" value={accountLedgerRoleLabels[String(currentRow.row_role)] ?? displayValue(currentRow.row_role)} />
            <CustomerSideRow label="可用于核验" value={["opening", "closing"].includes(String(currentRow.row_role)) ? "是" : "否"} />
          </CustomerSideCard>
        </aside>
      </div>
      )}
    </Drawer>
  );
}

function renderAccountBalanceCell(column: string, row: AccountBalanceRow, jumpTools: BusinessJumpTools) {
  const value = row[column];
  if (column === "settlement_unit_code" || column === "settlement_unit_name") {
    return (
      <BusinessLinkCell
        value={value}
        title="聚焦该结算单位"
        onClick={() => jumpTools.openSettlementUnit({
          code: row.settlement_unit_code,
          name: row.settlement_unit_name,
          kindHint: inferSettlementUnitKind(row),
          arBalance: row.ar_balance,
          apBalance: row.ap_balance,
          advanceReceiptBalance: row.advance_receipt_balance,
          advancePaymentBalance: row.advance_payment_balance
        })}
      />
    );
  }
  const balanceType = accountBalanceTypeByColumn[column];
  if (balanceType) {
    return (
      <BusinessLinkCell
        value={formatMoney(value)}
        title="按该余额类型筛选往来对账"
        subtle
        onClick={() => jumpTools.openProcessPage("account-balance", {
          settlement_unit_code: row.settlement_unit_code,
          settlement_unit_name: row.settlement_unit_name,
          balance_type: balanceType
        })}
      />
    );
  }
  if (column === "data_date") return formatDate(value);
  if (column.includes("balance") || column.includes("amount")) return formatMoney(value);
  return displayValue(value);
}

function renderAccountLedgerCell(column: string, row: AccountLedgerRow, jumpTools: BusinessJumpTools) {
  const value = row[column];
  if (column === "settlement_unit_code" || column === "settlement_unit_name") {
    return (
      <BusinessLinkCell
        value={value}
        title="聚焦该结算单位"
        onClick={() => jumpTools.openSettlementUnit({
          code: row.settlement_unit_code,
          name: row.settlement_unit_name,
          kindHint: "customer",
          arBalance: row.ar_amount,
          apBalance: row.ap_amount
        })}
      />
    );
  }
  if (column === "data_date" || column === "document_date") return formatDate(value);
  if (column === "row_role") return accountLedgerRoleLabels[String(value)] ?? displayValue(value);
  if (column.endsWith("_amount") || column === "current_balance") return formatMoney(value);
  return displayValue(value);
}

