function ImportsPage({ permissions }: { permissions: PermissionCode[] }) {
  const [rows, setRows] = useState<ImportBatch[]>([]);
  const [current, setCurrent] = useState<ImportBatch | null>(null);
  const [status, setStatus] = useState("等待文件");
  const [loading, setLoading] = useState(false);
  const [batchQuery, setBatchQuery] = useState("");
  const [batchStatusFilter, setBatchStatusFilter] = useState("");
  const [batchTypeFilter, setBatchTypeFilter] = useState("");
  const canViewBatches = hasPermission(permissions, "import.view");
  const canUpload = hasPermission(permissions, "import.upload");
  const canCommit = hasPermission(permissions, "import.commit");

  const load = async () => {
    if (!canViewBatches) {
      setRows([]);
      return;
    }
    setRows(await batches());
  };
  useEffect(() => { void load(); }, [canViewBatches]);

  const submitUpload = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const form = new FormData(event.currentTarget);
    const file = form.get("file");
    if (!(file instanceof File) || !file.name) {
      setStatus("请选择文件");
      return;
    }
    setLoading(true);
    try {
      const batch = await uploadImport(form);
      setCurrent(batch);
      setStatus(`已上传批次 ${batch.id}`);
      if (canViewBatches) await load();
    } catch (error) {
      setStatus(error instanceof Error ? error.message : "上传失败");
    } finally {
      setLoading(false);
    }
  };

  const operate = async (action: "validate" | "commit") => {
    if (!current) return;
    setLoading(true);
    try {
      const batch = action === "validate" ? await validateImport(current.id) : await commitImport(current.id);
      setCurrent(batch);
      setStatus(action === "validate" ? (batch.error_rows > 0 ? `校验有 ${batch.error_rows} 个错误` : "校验通过") : `提交结果：${batch.status}`);
      if (canViewBatches) await load();
    } catch (error) {
      setStatus(error instanceof Error ? error.message : "操作失败");
    } finally {
      setLoading(false);
    }
  };

  return (
    <>
      <Header eyebrow="MASTER DATA IMPORT" title="主数据导入" description="员工、客户、商品、供应商四类主数据在主数据中心上传、校验、提交。" />
      <div className="grid gap-5 xl:grid-cols-2">
        {canUpload ? <Card>
          <div className="border-b border-slate-200 p-5">
            <h2 className="text-xl font-black">上传新批次</h2>
            <p className="mt-1 text-sm text-slate-500">{status}</p>
          </div>
          <form onSubmit={submitUpload} className="grid gap-4 p-5">
            <div className="grid gap-4 md:grid-cols-2">
              <label className="grid gap-2 text-sm font-bold">类型
                <select name="file_type" className="h-11 rounded-2xl border border-slate-200 px-3">
                  <option value="employee_profile">员工档案</option>
                  <option value="customer_master">客户档案</option>
                  <option value="product_master">商品档案</option>
                  <option value="supplier_master">供应商档案</option>
                </select>
              </label>
              <label className="grid gap-2 text-sm font-bold">数据日期
                <input name="data_date" type="date" defaultValue={new Date().toISOString().slice(0, 10)} className="h-11 rounded-2xl border border-slate-200 px-3" />
              </label>
            </div>
            <label className="grid gap-2 text-sm font-bold">文件
              <input name="file" accept=".csv,.xls,.xlsx" type="file" className="rounded-2xl border border-slate-200 p-3" />
            </label>
            <div className="flex flex-wrap gap-2">
              <Button type="submit" disabled={loading}>上传</Button>
              {canCommit ? <Button secondary disabled={!current || loading} onClick={() => void operate("validate")}>校验</Button> : null}
              {canCommit ? <Button secondary disabled={!current || current.error_rows > 0 || loading} onClick={() => void operate("commit")}>提交</Button> : null}
            </div>
            <pre className="min-h-44 overflow-auto rounded-2xl border border-slate-200 bg-slate-50 p-3 text-xs leading-6 text-slate-700">
              {current ? JSON.stringify(current, null, 2) : "尚无批次"}
            </pre>
          </form>
        </Card> : null}

        <Card>
          <div className="border-b border-slate-200 p-5">
            <h2 className="text-xl font-black">导入口径</h2>
            <p className="mt-1 text-sm text-slate-500">上传、校验、提交和错误行分层沉淀。</p>
          </div>
          <div className="grid gap-3 p-5">
            {["按别名映射表自动识别常见列名", "先落批次，再校验主键、必填和重复", "校验通过后写入主数据表和别名表", "上传人、批次、原始文件和错误行独立记录"].map((text, index) => (
              <div key={text} className="rounded-2xl border border-slate-200 bg-slate-50 p-4">
                <span className="text-xs font-black text-primary">0{index + 1}</span>
                <strong className="ml-3">{text}</strong>
              </div>
            ))}
          </div>
        </Card>
      </div>
      {canViewBatches ? (
        <BatchTable
          rows={rows}
          query={batchQuery}
          statusFilter={batchStatusFilter}
          typeFilter={batchTypeFilter}
          onQueryChange={setBatchQuery}
          onStatusFilterChange={setBatchStatusFilter}
          onTypeFilterChange={setBatchTypeFilter}
          onReset={() => {
            setBatchQuery("");
            setBatchStatusFilter("");
            setBatchTypeFilter("");
          }}
        />
      ) : null}
    </>
  );
}

function BatchTable({
  rows,
  query,
  statusFilter,
  typeFilter,
  onQueryChange,
  onStatusFilterChange,
  onTypeFilterChange,
  onReset,
  onSelect
}: {
  rows: ImportBatch[];
  query: string;
  statusFilter: string;
  typeFilter: string;
  onQueryChange: (value: string) => void;
  onStatusFilterChange: (value: string) => void;
  onTypeFilterChange: (value: string) => void;
  onReset: () => void;
  onSelect?: (row: ImportBatch) => void;
}) {
  const filteredRows = rows.filter((row) =>
    includesKeyword([row.id, row.batch_no, row.file_type, row.status], query)
    && (!statusFilter || row.status === statusFilter)
    && (!typeFilter || row.file_type === typeFilter)
  );
  const typeOptions = Array.from(new Set(rows.map((row) => row.file_type))).sort();
  const statusOptions = Array.from(new Set(rows.map((row) => row.status))).sort();
  return (
    <div className="mt-5">
    <DataTableShell
      title="最近导入批次"
      description="查看主数据导入批次、状态和行数结果。"
      meta={`${filteredRows.length} / ${rows.length} 条`}
      toolbar={
        <DataToolbar onReset={onReset}>
          <ToolbarSearch value={query} onChange={onQueryChange} placeholder="搜索批次号、类型、状态" />
          <ToolbarSelect value={typeFilter} onChange={onTypeFilterChange} label="类型" options={[{ value: "", label: "全部类型" }, ...typeOptions.map((value) => ({ value, label: value }))]} />
          <ToolbarSelect value={statusFilter} onChange={onStatusFilterChange} label="状态" options={[{ value: "", label: "全部状态" }, ...statusOptions.map((value) => ({ value, label: value }))]} />
        </DataToolbar>
      }
    >
      <Table headers={["ID", "批次号", "类型", "状态", "行数", "成功", "错误"]}>
        {filteredRows.map((row) => (
          <tr key={row.id} onClick={() => onSelect?.(row)} className={onSelect ? "project-table-row-interactive" : undefined}>
            <td>{row.id}</td>
            <td>{row.batch_no}</td>
            <td>{row.file_type}</td>
            <td><Badge tone={row.status === "committed" ? "ok" : "warn"}>{row.status}</Badge></td>
            <td>{row.total_rows}</td>
            <td>{row.success_rows}</td>
            <td>{row.error_rows}</td>
          </tr>
        ))}
      </Table>
    </DataTableShell>
    </div>
  );
}

function MasterDataPage({ stats, permissions, jumpTools }: { stats: Summary | null; permissions: PermissionCode[]; jumpTools: BusinessJumpTools }) {
  const visibleKinds = (Object.keys(masterKinds) as MasterKind[]).filter((key) => {
    const required: Record<MasterKind, PermissionCode> = {
      employees: "employee.view",
      customers: "customer.view",
      products: "product.view",
      suppliers: "supplier.view"
    };
    return hasPermission(permissions, required[key]);
  });
  const urlKind = (initialQueryParam("kind") || initialQueryParam("tab")) as MasterKind;
  const preferredInitialKind: MasterKind = visibleKinds.includes("customers")
    ? (visibleKinds.includes(urlKind) ? urlKind : "customers")
    : visibleKinds.includes("products")
      ? (visibleKinds.includes(urlKind) ? urlKind : "products")
      : (visibleKinds.includes(urlKind) ? urlKind : visibleKinds[0] ?? "customers");
  const initialMasterView: MasterCenterView = initialQueryParam("view") === "calendar" ? "calendar" : initialQueryParam("view") === "risk" ? "risk" : initialQueryParam("view") === "quality" ? "quality" : "records";
  const [kind, setKind] = useState<MasterKind>(preferredInitialKind);
  const [masterView, setMasterView] = useState<MasterCenterView>(initialMasterView);
  const [query, setQuery] = useState(() => initialQueryParam("q"));
  const [portraitScaleFilter, setPortraitScaleFilter] = useState("");
  const [portraitPaymentLevelFilter, setPortraitPaymentLevelFilter] = useState("");
  const [portraitCategoryFilter, setPortraitCategoryFilter] = useState("");
  const [portraitMarginFilter, setPortraitMarginFilter] = useState("");
  const [portraitReturnFilter, setPortraitReturnFilter] = useState("");
  const [portraitGrowthFilter, setPortraitGrowthFilter] = useState("");
  const [customerTagFilter, setCustomerTagFilter] = useState<string[]>([]);
  const [customerTagCatalog, setCustomerTagCatalog] = useState<CustomerTagRow[]>([]);
  const [customerAssignmentFilter, setCustomerAssignmentFilter] = useState("");
  const [customerMissingFilter, setCustomerMissingFilter] = useState("");
  const [attentionState, setAttentionState] = useState<AttentionFilterValue>(() => {
    const value = initialQueryParam("attention_state");
    return value === "normal" || value === "needs_attention" ? value : initialQueryParam("attention_reason") ? "needs_attention" : "";
  });
  const [attentionReason, setAttentionReason] = useState(() => initialQueryParam("attention_reason"));
  const [attentionSummary, setAttentionSummary] = useState<AttentionSummary | null>(null);
  const [openRecordKey, setOpenRecordKey] = useState(() => initialQueryParam("open"));
  const masterSource = initialQueryParam("source");
  const masterInitialTab = initialQueryParam("tab") as CustomerDetailTab;
  const isCrmLinkedCustomerMasterSource = masterSource === "crm-linked-customer";
  const crmLinkedCustomerInitialTab = crmLinkedCustomerMasterTabs.includes(masterInitialTab) ? masterInitialTab : "profile";
  const [rows, setRows] = useState<MasterRow[]>([]);
  const [totalRows, setTotalRows] = useState(0);
  const [hierarchyRoot, setHierarchyRoot] = useState<CategoryNode | null>(null);
  const [categorySearch, setCategorySearch] = useState("");
  const [selectedCategoryId, setSelectedCategoryId] = useState(`${kind}:root`);
  const [expandedCategoryIds, setExpandedCategoryIds] = useState<Set<string>>(() => new Set([`${kind}:root`]));
  const [categoryActionMessage, setCategoryActionMessage] = useState("");
  const [categoryNodes, setCategoryNodes] = useState<MasterCategoryNodeRow[]>([]);
  const [categoryDrawerMode, setCategoryDrawerMode] = useState<"create" | "edit" | null>(null);
  const [bindingRowKey, setBindingRowKey] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const [selectedEmployee, setSelectedEmployee] = useState<MasterRow | null>(null);
  const [selectedCustomer, setSelectedCustomer] = useState<MasterRow | null>(null);
  const [selectedProduct, setSelectedProduct] = useState<MasterRow | null>(null);
  const [selectedSupplier, setSelectedSupplier] = useState<MasterRow | null>(null);
  const [importDrawerOpen, setImportDrawerOpen] = useState(() => {
    const params = new URLSearchParams(window.location.search);
    return window.location.pathname.startsWith("/imports") || params.get("drawer") === "import";
  });
  const [importDrawerContext, setImportDrawerContext] = useState<ImportDrawerContext | null>(() => {
    const params = new URLSearchParams(window.location.search);
    return {
      batchId: params.get("batch") ? Number(params.get("batch")) : undefined,
      fileType: params.get("file_type") ?? undefined,
      dataDate: params.get("data_date") ?? undefined,
      activeTab: params.get("tab") === "history" ? "history" : params.get("tab") === "flow" ? "flow" : undefined
    };
  });
  const active = masterKinds[kind];
	  const canUseImport = hasAnyPermission(permissions, ["import.view", "import.upload", "import.commit"]);
	  const canViewCalendar = hasPermission(permissions, "import.view");
  const canUsePortraitFilters = kind === "customers" && hasPermission(permissions, "customer_portrait.view");
  const hierarchyEnabled = kind === "customers" || kind === "products";
  const hierarchyKind = hierarchyEnabled ? kind as HierarchyKind : null;

  useEffect(() => {
    if (!hasPermission(permissions, "customer.view")) return;
    customerTags(false).then(setCustomerTagCatalog).catch(() => setCustomerTagCatalog([]));
  }, [permissions.join("|")]);

  const loadRows = async () => {
    if (visibleKinds.length === 0) {
      setRows([]);
      setTotalRows(0);
      return;
    }
    const offset = (currentPage - 1) * MASTER_DATA_PAGE_SIZE;
    const categoryPath = hierarchyKind ? (selectedCategory?.path ?? []) : undefined;
    const page = kind === "employees"
      ? await employeesPage({ q: query, limit: MASTER_DATA_PAGE_SIZE, offset })
      : await masterDataPage(active.api, {
        q: query,
        limit: MASTER_DATA_PAGE_SIZE,
        offset,
        categoryPath,
        portraitScale: canUsePortraitFilters ? portraitScaleFilter : "",
        portraitPaymentLevel: canUsePortraitFilters ? portraitPaymentLevelFilter : "",
        portraitCategory: canUsePortraitFilters ? portraitCategoryFilter : "",
        portraitMargin: canUsePortraitFilters ? portraitMarginFilter : "",
        portraitReturn: canUsePortraitFilters ? portraitReturnFilter : "",
        portraitGrowth: canUsePortraitFilters ? portraitGrowthFilter : "",
        customerTags: kind === "customers" ? customerTagFilter : [],
        customerTagMatch: "any",
        assignmentScope: kind === "customers" ? customerAssignmentFilter : "",
        missingPhone: kind === "customers" && customerMissingFilter === "missing_phone",
        missingContact: kind === "customers" && customerMissingFilter === "missing_contact",
        missingAddress: kind === "customers" && customerMissingFilter === "missing_address",
        missingGroup: kind === "customers" && customerMissingFilter === "missing_group",
        missingBusinessProfile: kind === "customers" && customerMissingFilter === "missing_business_profile",
        missingBusinessProducts: kind === "customers" && customerMissingFilter === "missing_business_products",
        secondAssignmentCandidate: kind === "customers" && customerMissingFilter === "second_assignment_candidate",
        attentionState: kind === "customers" ? attentionState : "",
        attentionReason: kind === "customers" ? attentionReason : ""
      });
    setRows(page.items);
    setTotalRows(page.total);
    setAttentionSummary(kind === "customers" ? page.attention_summary ?? null : null);
  };

  useEffect(() => {
    if (!visibleKinds.includes(kind) && visibleKinds.length > 0) {
      setKind(visibleKinds[0]);
      setSelectedEmployee(null);
      setSelectedCustomer(null);
      setSelectedProduct(null);
      setSelectedSupplier(null);
      return;
    }
    if (visibleKinds.length === 0) {
      setRows([]);
      setTotalRows(0);
      setSelectedEmployee(null);
      setSelectedCustomer(null);
      setSelectedProduct(null);
      setSelectedSupplier(null);
      return;
    }
    void loadRows();
  }, [kind, query, active.api, visibleKinds.join("|"), currentPage, selectedCategoryId, hierarchyRoot?.id, portraitScaleFilter, portraitPaymentLevelFilter, portraitCategoryFilter, portraitMarginFilter, portraitReturnFilter, portraitGrowthFilter, customerTagFilter.join("|"), customerAssignmentFilter, customerMissingFilter, attentionState, attentionReason]);

  useEffect(() => {
    replaceCurrentQueryParams({
      attention_state: kind === "customers" ? attentionState : null,
      attention_reason: kind === "customers" ? attentionReason : null
    });
  }, [kind, attentionState, attentionReason]);

  useEffect(() => {
    if (!openRecordKey || rows.length === 0) return;
    const matched = rows.find((row) => {
      if (kind === "employees") return String(row.employee_code ?? "") === openRecordKey || String(row.employee_name ?? "") === openRecordKey;
      if (kind === "customers") return String(row.customer_code ?? "") === openRecordKey || String(row.customer_name ?? "") === openRecordKey;
      if (kind === "products") return String(row.product_code ?? "") === openRecordKey || String(row.product_name ?? "") === openRecordKey;
      if (kind === "suppliers") return String(row.supplier_code ?? "") === openRecordKey || String(row.supplier_name ?? "") === openRecordKey;
      return false;
    });
    if (!matched) return;
    if (kind === "employees") setSelectedEmployee(matched);
    if (kind === "customers") setSelectedCustomer(matched);
    if (kind === "products") setSelectedProduct(matched);
    if (kind === "suppliers") setSelectedSupplier(matched);
    setOpenRecordKey("");
  }, [openRecordKey, rows, kind]);

  useEffect(() => {
    if (!hierarchyKind) {
      setHierarchyRoot(null);
      setCategoryNodes([]);
      return;
    }
    void masterHierarchy(hierarchyKind)
      .then((root: MasterCategoryNode) => setHierarchyRoot(root as CategoryNode))
      .catch(() => setHierarchyRoot(null));
    void masterCategoryNodes(hierarchyKind, true)
      .then(setCategoryNodes)
      .catch(() => setCategoryNodes([]));
  }, [hierarchyKind]);

  useEffect(() => {
    if (kind !== "employees") setSelectedEmployee(null);
    if (kind !== "customers") setSelectedCustomer(null);
    if (kind !== "products") setSelectedProduct(null);
    if (kind !== "suppliers") setSelectedSupplier(null);
    setCategorySearch("");
    setCategoryActionMessage("");
    setCategoryDrawerMode(null);
    setBindingRowKey("");
    setSelectedCategoryId(`${kind}:root`);
    setExpandedCategoryIds(new Set([`${kind}:root`]));
    setCurrentPage(1);
    if (kind !== "customers") {
      setPortraitScaleFilter("");
      setPortraitPaymentLevelFilter("");
      setPortraitCategoryFilter("");
      setPortraitMarginFilter("");
      setPortraitReturnFilter("");
      setPortraitGrowthFilter("");
      setCustomerAssignmentFilter("");
      setCustomerMissingFilter("");
      setAttentionState("");
      setAttentionReason("");
      setAttentionSummary(null);
    }
  }, [kind]);

  useEffect(() => {
    const onPopState = () => {
      const params = new URLSearchParams(window.location.search);
      setImportDrawerOpen(window.location.pathname.startsWith("/imports") || params.get("drawer") === "import");
      setImportDrawerContext({
        batchId: params.get("batch") ? Number(params.get("batch")) : undefined,
        fileType: params.get("file_type") ?? undefined,
        dataDate: params.get("data_date") ?? undefined
      });
    };
    window.addEventListener("popstate", onPopState);
    return () => window.removeEventListener("popstate", onPopState);
  }, []);

	  const openImportDrawer = (context: ImportDrawerContext = {}) => {
	    setImportDrawerContext(context);
	    setImportDrawerOpen(true);
	    const params = new URLSearchParams({ drawer: "import" });
	    if (masterView !== "records") params.set("view", masterView);
	    if (context.batchId) params.set("batch", String(context.batchId));
	    if (context.fileType) params.set("file_type", context.fileType);
	    if (context.dataDate) params.set("data_date", context.dataDate);
	    window.history.pushState(null, "", `/master-data?${params.toString()}`);
	  };

	  const closeImportDrawer = () => {
	    setImportDrawerOpen(false);
	    setImportDrawerContext(null);
	    if (window.location.pathname.startsWith("/imports") || new URLSearchParams(window.location.search).get("drawer") === "import") {
	      window.history.replaceState(null, "", masterView === "calendar" ? "/master-data?view=calendar" : masterView === "risk" ? "/master-data?view=risk" : masterView === "quality" ? "/master-data?view=quality" : "/master-data");
	    }
	  };

  const counts: Record<MasterKind, number | undefined> = {
    employees: stats?.employees,
    customers: stats?.customers,
    products: stats?.products,
    suppliers: stats?.suppliers
  };
  const visibleLabels = visibleKinds.map((key) => masterKinds[key].label.replace("档案", ""));
  const masterDescription = visibleKinds.length > 0
    ? `${visibleLabels.join("、")}档案统一查询。${hasAnyPermission(permissions, ["import.view", "import.upload", "import.commit"]) ? "批量新增和更新可在当前页右侧导入抽屉完成。" : "批量新增和更新请联系具备导入权限的管理员。"}`
    : "当前账号没有主数据查看权限。";
  const selectedCategory = hierarchyRoot ? findCategoryNode(hierarchyRoot, selectedCategoryId) ?? hierarchyRoot : null;
  const tableRows = rows;
  const categoryStats = hierarchyKind && selectedCategory ? {
    current: selectedCategory.label,
    children: selectedCategory.children.length,
    records: selectedCategory.count,
    abnormal: selectedCategory.abnormal_count
  } : null;
  const totalPages = Math.max(1, Math.ceil(totalRows / MASTER_DATA_PAGE_SIZE));
  const safeCurrentPage = Math.min(currentPage, totalPages);
  const pageStartIndex = (safeCurrentPage - 1) * MASTER_DATA_PAGE_SIZE;
  const paginatedRows = tableRows;
  const pageRangeStart = totalRows === 0 ? 0 : pageStartIndex + 1;
  const pageRangeEnd = Math.min(pageStartIndex + paginatedRows.length, totalRows);
  const currentPath = hierarchyKind && selectedCategory
    ? [hierarchyKind === "products" ? "全部商品" : "全部客户", ...selectedCategory.path]
    : [];
  const editableCategory = selectedCategory?.category_id ? categoryNodes.find((node) => node.id === selectedCategory.category_id) ?? null : null;

	  const setActiveKind = (nextKind: MasterKind) => {
    setCurrentPage(1);
    setOpenRecordKey("");
    setKind(nextKind);
    setSelectedEmployee(null);
    setSelectedCustomer(null);
    setSelectedProduct(null);
    setSelectedSupplier(null);
	  };
	  const setActiveMasterView = (nextView: MasterCenterView) => {
	    setMasterView(nextView);
	    window.history.replaceState(null, "", nextView === "calendar" ? "/master-data?view=calendar" : nextView === "risk" ? "/master-data?view=risk" : nextView === "quality" ? "/master-data?view=quality" : "/master-data");
	  };

  const reloadHierarchy = async () => {
    if (!hierarchyKind) return;
    const [root, nodes] = await Promise.all([
      masterHierarchy(hierarchyKind),
      masterCategoryNodes(hierarchyKind, true)
    ]);
    setHierarchyRoot(root as CategoryNode);
    setCategoryNodes(nodes);
  };
  const bindRowToSelectedCategory = async (row: MasterRow) => {
    if (!hierarchyKind || !selectedCategory?.category_id) {
      setCategoryActionMessage("请先选择一个已持久化的分类，再绑定档案。");
      return;
    }
    const resourceCode = hierarchyKind === "customers" ? String(row.customer_code ?? "") : String(row.product_code ?? "");
    if (!resourceCode) {
      setCategoryActionMessage("当前档案缺少编号，无法绑定分类。");
      return;
    }
    setBindingRowKey(resourceCode);
    try {
      await bindMasterCategoryResource(selectedCategory.category_id, resourceCode, true);
      setCategoryActionMessage(`已将 ${resourceCode} 绑定到「${selectedCategory.label}」。`);
      await reloadHierarchy();
      await loadRows();
    } catch (error) {
      setCategoryActionMessage(error instanceof Error ? error.message : "绑定分类失败。");
    } finally {
      setBindingRowKey("");
    }
  };
  const resetMasterFilters = () => {
    setCurrentPage(1);
    setQuery("");
    setPortraitScaleFilter("");
    setPortraitPaymentLevelFilter("");
    setPortraitCategoryFilter("");
    setPortraitMarginFilter("");
    setPortraitReturnFilter("");
    setPortraitGrowthFilter("");
    setCustomerTagFilter([]);
    setCustomerAssignmentFilter("");
    setCustomerMissingFilter("");
    setAttentionState("");
    setAttentionReason("");
  };
  const portraitToolbar = kind === "customers" ? (
    <>
      <CustomerTagFilterControl catalog={customerTagCatalog} value={customerTagFilter} onChange={(value) => { setCurrentPage(1); setCustomerTagFilter(value); }} />
      <ToolbarSelect
        value={customerAssignmentFilter}
        onChange={(value) => { setCurrentPage(1); setCustomerAssignmentFilter(value); }}
        label="项目分配"
        options={[
          { value: "", label: "全部项目" },
          { value: "assigned", label: "已分配项目" },
          { value: "unassigned", label: "未分配项目" },
          { value: "active", label: "当前项目中" },
          { value: "historical", label: "历史分配过" }
        ]}
      />
      <ToolbarSelect
        value={customerMissingFilter}
        onChange={(value) => { setCurrentPage(1); setCustomerMissingFilter(value); }}
        label="资料缺失"
        options={[
          { value: "", label: "全部资料" },
          { value: "missing_phone", label: "缺电话" },
          { value: "missing_contact", label: "缺联系人" },
          { value: "missing_address", label: "缺地址" },
          { value: "missing_group", label: "缺客户群" },
          { value: "missing_business_profile", label: "缺经营资料" },
          { value: "missing_business_products", label: "缺经营产品" },
          { value: "second_assignment_candidate", label: "二次分配候选" }
        ]}
      />
      {canUsePortraitFilters ? (
        <>
          <ToolbarSelect value={portraitScaleFilter} onChange={(value) => { setCurrentPage(1); setPortraitScaleFilter(value); }} label="客户等级" options={[{ value: "", label: "全部等级" }, ...customerPortraitScaleOptions.map((value) => ({ value, label: value }))]} />
          <ToolbarSelect value={portraitPaymentLevelFilter} onChange={(value) => { setCurrentPage(1); setPortraitPaymentLevelFilter(value); }} label="回款风险" options={[{ value: "", label: "全部风险" }, ...customerPortraitPaymentLevelOptions.map((value) => ({ value, label: value }))]} />
          <ToolbarSelect value={portraitCategoryFilter} onChange={(value) => { setCurrentPage(1); setPortraitCategoryFilter(value); }} label="画像品类" options={[{ value: "", label: "全部品类" }, ...customerPortraitCategoryOptions.map((value) => ({ value, label: value }))]} />
          <ToolbarSelect value={portraitMarginFilter} onChange={(value) => { setCurrentPage(1); setPortraitMarginFilter(value); }} label="毛利" options={[{ value: "", label: "全部毛利" }, ...customerPortraitMarginOptions.map((value) => ({ value, label: value }))]} />
          <ToolbarSelect value={portraitReturnFilter} onChange={(value) => { setCurrentPage(1); setPortraitReturnFilter(value); }} label="退货" options={[{ value: "", label: "全部退货" }, ...customerPortraitReturnOptions.map((value) => ({ value, label: value }))]} />
          <ToolbarSelect value={portraitGrowthFilter} onChange={(value) => { setCurrentPage(1); setPortraitGrowthFilter(value); }} label="增长" options={[{ value: "", label: "全部增长" }, ...customerPortraitGrowthOptions.map((value) => ({ value, label: value }))]} />
        </>
      ) : null}
    </>
  ) : null;
  const customerAttentionPanel = kind === "customers" ? (
    <AttentionFilterPanel
      title="客户资料待补全"
      description="停用客户，或联系人、联系电话、详细地址任一缺失时计入待补全；这表示资料需要完善，不代表档案损坏。"
      summary={attentionSummary}
      state={attentionState}
      reason={attentionReason}
      normalLabel="资料完整"
      attentionLabel="待补全"
      onStateChange={(value) => {
        setCurrentPage(1);
        setAttentionState(value);
        if (value !== "needs_attention") setAttentionReason("");
      }}
      onReasonChange={(value) => {
        setCurrentPage(1);
        setAttentionReason(value);
        setAttentionState(value ? "needs_attention" : "");
      }}
    />
  ) : null;

  useEffect(() => {
    if (currentPage !== safeCurrentPage) setCurrentPage(safeCurrentPage);
  }, [currentPage, safeCurrentPage]);

  return (
    <>
      <Header
        eyebrow="MASTER DATA"
        title="主数据中心"
        description={masterDescription}
        actions={
          <div className="flex flex-wrap gap-2">
	            {masterView === "records" && hierarchyEnabled ? (
	              <>
	                <Button secondary onClick={() => setCategoryDrawerMode("create")}><Plus className="mr-1.5 h-4 w-4" />新增分类</Button>
	                <Button secondary onClick={() => editableCategory ? setCategoryDrawerMode("edit") : setCategoryActionMessage("请选择一个已持久化的分类后再编辑；动态兜底分类需要先新增为持久化分类。")} disabled={!selectedCategory || selectedCategory.path.length === 0}><Pencil className="mr-1.5 h-4 w-4" />编辑分类</Button>
	              </>
	            ) : null}
	            {canUseImport ? <Button onClick={openImportDrawer}><UploadCloud className="mr-1.5 h-4 w-4" />导入数据</Button> : null}
	            {masterView === "records" && hierarchyEnabled ? <Button secondary onClick={() => void reloadHierarchy()}><MoreHorizontal className="mr-1.5 h-4 w-4" />刷新分类</Button> : null}
	          </div>
	        }
	      />
	      <div className="mb-4 flex flex-wrap gap-2 rounded-lg border border-slate-200 bg-white p-2 shadow-sm">
	        <button
	          type="button"
	          onClick={() => setActiveMasterView("records")}
	          className={`inline-flex min-h-9 items-center rounded-lg px-4 text-sm font-black transition ${masterView === "records" ? "bg-primary text-white shadow-sm" : "text-slate-600 hover:bg-slate-50"}`}
	        >
	          <Database className="mr-1.5 h-4 w-4" />档案数据
	        </button>
	        {canViewCalendar ? (
	          <button
	            type="button"
	            onClick={() => setActiveMasterView("risk")}
	            className={`inline-flex min-h-9 items-center rounded-lg px-4 text-sm font-black transition ${masterView === "risk" ? "bg-primary text-white shadow-sm" : "text-slate-600 hover:bg-slate-50"}`}
	          >
	            <Siren className="mr-1.5 h-4 w-4" />风险提示
	          </button>
	        ) : null}
	        {canViewCalendar ? (
	          <button
	            type="button"
	            onClick={() => setActiveMasterView("calendar")}
	            className={`inline-flex min-h-9 items-center rounded-lg px-4 text-sm font-black transition ${masterView === "calendar" ? "bg-primary text-white shadow-sm" : "text-slate-600 hover:bg-slate-50"}`}
	          >
	            <CalendarDays className="mr-1.5 h-4 w-4" />数据日历
	          </button>
	        ) : null}
	        {canViewCalendar ? (
	          <button
	            type="button"
	            onClick={() => setActiveMasterView("quality")}
	            className={`inline-flex min-h-9 items-center rounded-lg px-4 text-sm font-black transition ${masterView === "quality" ? "bg-primary text-white shadow-sm" : "text-slate-600 hover:bg-slate-50"}`}
	          >
	            <FileWarning className="mr-1.5 h-4 w-4" />匹配问题
	          </button>
	        ) : null}
	      </div>
	      {masterView === "records" ? (
	        <div className="mb-5 grid gap-px overflow-hidden rounded-[18px] border border-slate-200 bg-slate-200 md:grid-cols-4">
	          {visibleKinds.map((key) => (
	            <button key={key} onClick={() => setActiveKind(key)} className={`bg-white p-4 text-left ${kind === key ? "text-primary" : ""}`}>
	              <span className="block text-sm text-slate-500">{masterKinds[key].label}</span>
	              <strong className="mt-2 block text-3xl font-black">{counts[key] ?? "-"}</strong>
	            </button>
	          ))}
	        </div>
	      ) : null}
	      {masterView === "risk" ? (
	        canViewCalendar ? (
	          <MasterRiskAlertCenter
	            permissions={permissions}
	            onOpenMasterRecord={(targetKind, lookup) => {
	              setActiveMasterView("records");
	              setActiveKind(targetKind);
	              setQuery(lookup);
	              setOpenRecordKey(lookup);
	              setCurrentPage(1);
	            }}
	          />
	        ) : <Card className="p-6 text-sm font-bold text-slate-500">当前账号没有导入批次查看权限，暂不能查看风险提示。</Card>
	      ) : masterView === "quality" ? (
	        canViewCalendar ? (
	          <MasterLinkIssueCenter
	            permissions={permissions}
	            onChanged={() => {
	              void loadRows();
	              if (hierarchyKind) void reloadHierarchy();
	            }}
	          />
	        ) : <Card className="p-6 text-sm font-bold text-slate-500">当前账号没有导入批次查看权限，暂不能查看匹配问题。</Card>
	      ) : masterView === "calendar" ? (
        canViewCalendar ? (
	          <DataActionCalendar
	            batchesLoader={batches}
	            canConfigureRules={hasPermission(permissions, "import.commit")}
	            canSendReminders={hasPermission(permissions, "import.commit")}
	            canViewAudit={hasPermission(permissions, "audit.view")}
	            canViewCrmTasks={hasPermission(permissions, "crm_task.view")}
	            onOpenImport={openImportDrawer}
	          />
        ) : <Card className="p-6 text-sm font-bold text-slate-500">当前账号没有导入批次查看权限，暂不能查看数据日历。</Card>
	      ) : visibleKinds.length > 0 ? (
        hierarchyKind && hierarchyRoot && selectedCategory && categoryStats ? (
          <div className="grid gap-4 xl:grid-cols-[300px_minmax(0,1fr)]">
            <CategoryTreePanel
              kind={hierarchyKind}
              root={hierarchyRoot}
              selectedId={selectedCategory.id}
              expandedIds={expandedCategoryIds}
              search={categorySearch}
              onSearchChange={setCategorySearch}
              onSelect={(node) => {
                setCurrentPage(1);
                setSelectedCategoryId(node.id);
              }}
              onToggle={(node) => {
                setExpandedCategoryIds((current) => {
                  const next = new Set(current);
                  if (next.has(node.id)) next.delete(node.id);
                  else next.add(node.id);
                  return next;
                });
              }}
            />
            <div className="min-w-0">
              <div className="mb-4 rounded-lg border border-slate-200 bg-white p-4 shadow-sm">
                <div className="flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between">
                  <div className="min-w-0">
                    <p className="m-0 text-xs font-bold uppercase tracking-[0.12em] text-primary">当前路径</p>
                    <div className="mt-2 flex min-w-0 flex-wrap items-center gap-1 text-sm font-black text-slate-900">
                      {currentPath.map((segment, index) => (
                        <span key={`${segment}-${index}`} className="inline-flex items-center gap-1">
                          {index > 0 ? <ChevronRight className="h-3.5 w-3.5 text-slate-300" /> : null}
                          <span className={index === currentPath.length - 1 ? "text-primary" : "text-slate-600"}>{segment}</span>
                        </span>
                      ))}
                    </div>
                  </div>
                  <Badge tone={categoryStats.abnormal > 0 ? "neutral" : "ok"}>{categoryStats.abnormal > 0 ? `${hierarchyKind === "customers" ? "资料待补全" : "分类待处理"} ${categoryStats.abnormal}` : "分类正常"}</Badge>
                </div>
                <div className="mt-4 grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
                  <CategoryStatCard label="当前分类" value={categoryStats.current} />
                  <CategoryStatCard label="子分类" value={categoryStats.children} />
                  <CategoryStatCard label="档案数量" value={categoryStats.records} />
                  <CategoryStatCard label={hierarchyKind === "customers" ? "资料待补全" : "待处理项"} value={categoryStats.abnormal} tone={categoryStats.abnormal > 0 ? "neutral" : "ok"} />
                </div>
                {categoryActionMessage ? <p className="m-0 mt-3 text-xs font-bold text-slate-400">{categoryActionMessage}</p> : null}
              </div>
              {customerAttentionPanel}
              <DataTableShell
                title={active.label}
                meta={`${pageRangeStart}-${pageRangeEnd} / ${totalRows} 条记录`}
                toolbar={
                  <DataToolbar onReset={resetMasterFilters}>
                    <ToolbarSearch value={query} onChange={(value) => { setCurrentPage(1); setQuery(value); }} placeholder="搜索编号或名称" />
                    {portraitToolbar}
                  </DataToolbar>
                }
              >
                <Table headers={[...active.columns.map((column) => masterColumnLabels[column] ?? column), "分类"]}>
                  {paginatedRows.map((row, index) => (
                    <MasterDataTableRow
                      key={String(row.id ?? `${safeCurrentPage}-${index}`)}
                      kind={kind}
                      row={row}
                      columns={active.columns}
                      tagCatalog={customerTagCatalog}
                      action={(
                        <button
                          type="button"
                          disabled={!selectedCategory?.category_id || bindingRowKey === String((hierarchyKind === "customers" ? row.customer_code : row.product_code) ?? "")}
                          onClick={(event) => {
                            event.stopPropagation();
                            void bindRowToSelectedCategory(row);
                          }}
                          className="project-inline-action disabled:opacity-40"
                        >
                          {bindingRowKey === String((hierarchyKind === "customers" ? row.customer_code : row.product_code) ?? "") ? "绑定中" : "绑定"}
                        </button>
                      )}
                      selected={
                        (kind === "customers" && selectedCustomer?.customer_code === row.customer_code)
                        || (kind === "products" && selectedProduct?.product_code === row.product_code)
                      }
                      onOpen={() => {
                        if (kind === "customers") setSelectedCustomer(row);
                        if (kind === "products") setSelectedProduct(row);
                      }}
                    />
                  ))}
                </Table>
                <MasterPagination
                  currentPage={safeCurrentPage}
                  totalPages={totalPages}
                  totalItems={totalRows}
                  pageSize={MASTER_DATA_PAGE_SIZE}
                  rangeStart={pageRangeStart}
                  rangeEnd={pageRangeEnd}
                  onPageChange={setCurrentPage}
                />
              </DataTableShell>
            </div>
          </div>
        ) : (
          <>
          {customerAttentionPanel}
          <DataTableShell
            title={active.label}
            meta={`${pageRangeStart}-${pageRangeEnd} / ${totalRows} 条记录`}
            toolbar={
              <DataToolbar onReset={resetMasterFilters}>
                <ToolbarSearch value={query} onChange={(value) => { setCurrentPage(1); setQuery(value); }} placeholder="搜索编号或名称" />
                {portraitToolbar}
              </DataToolbar>
            }
          >
            <Table headers={active.columns.map((column) => masterColumnLabels[column] ?? column)}>
              {paginatedRows.map((row, index) => (
                <MasterDataTableRow
                  key={String(row.id ?? `${safeCurrentPage}-${index}`)}
                  kind={kind}
                  row={row}
                  columns={active.columns}
                  tagCatalog={customerTagCatalog}
                  selected={
                    (kind === "employees" && selectedEmployee?.employee_code === row.employee_code)
                    || (kind === "suppliers" && selectedSupplier?.supplier_code === row.supplier_code)
                  }
                  onOpen={() => {
                    if (kind === "employees") setSelectedEmployee(row);
                    if (kind === "suppliers") setSelectedSupplier(row);
                  }}
                />
              ))}
            </Table>
            <MasterPagination
              currentPage={safeCurrentPage}
              totalPages={totalPages}
              totalItems={totalRows}
              pageSize={MASTER_DATA_PAGE_SIZE}
              rangeStart={pageRangeStart}
              rangeEnd={pageRangeEnd}
              onPageChange={setCurrentPage}
            />
          </DataTableShell>
          </>
        )
      ) : <Card className="p-6 text-sm font-bold text-slate-500">当前账号没有主数据查看权限。</Card>}
      <AnimatePresence>
        {categoryDrawerMode && hierarchyKind ? (
          <MasterCategoryDrawer
            key={`master-category-${categoryDrawerMode}`}
            mode={categoryDrawerMode}
            kind={hierarchyKind}
            selectedCategory={selectedCategory}
            editingCategory={categoryDrawerMode === "edit" ? editableCategory : null}
            nodes={categoryNodes}
            onClose={() => setCategoryDrawerMode(null)}
            onSaved={async (message, savedNode) => {
              setCategoryDrawerMode(null);
              setCategoryActionMessage(message);
              await reloadHierarchy();
              if (savedNode) {
                setExpandedCategoryIds((current) => new Set([...current, savedNode.parent_id ? `category:${savedNode.parent_id}` : `${hierarchyKind}:root`]));
                setSelectedCategoryId(`category:${savedNode.id}`);
              }
              await loadRows();
            }}
          />
        ) : null}
      </AnimatePresence>
      <AnimatePresence>
        {importDrawerOpen && canUseImport ? (
          <MasterDataImportDrawer
            key="master-data-import"
            defaultKind={kind}
            visibleKinds={visibleKinds}
            permissions={permissions}
            initialContext={importDrawerContext}
            onClose={closeImportDrawer}
            onCommitted={() => void loadRows()}
          />
        ) : null}
      </AnimatePresence>
      <AnimatePresence>
        {selectedCustomer && kind === "customers" ? (
          <CustomerDetailDrawer
            key={String(selectedCustomer.customer_code ?? selectedCustomer.id ?? "customer")}
            customer={selectedCustomer}
            canEdit={hasPermission(permissions, "customer.edit")}
            permissions={permissions}
            jumpTools={jumpTools}
            initialTab={isCrmLinkedCustomerMasterSource ? crmLinkedCustomerInitialTab : undefined}
            allowedTabs={isCrmLinkedCustomerMasterSource ? crmLinkedCustomerMasterTabs : undefined}
            onSaved={(updatedCustomer) => {
              setSelectedCustomer(updatedCustomer);
              setRows((currentRows) => currentRows.map((row) => row.customer_code === updatedCustomer.customer_code ? updatedCustomer : row));
              void loadRows();
            }}
            onClose={() => setSelectedCustomer(null)}
          />
        ) : null}
      </AnimatePresence>
      <AnimatePresence>
        {selectedEmployee && kind === "employees" ? (
          <EmployeeDetailDrawer
            key={String(selectedEmployee.employee_code ?? selectedEmployee.id ?? "employee")}
            employee={selectedEmployee}
            canEdit={hasPermission(permissions, "employee.edit")}
            jumpTools={jumpTools}
            onSaved={(updatedEmployee) => {
              setSelectedEmployee(updatedEmployee);
              setRows((currentRows) => currentRows.map((row) => row.employee_code === updatedEmployee.employee_code ? updatedEmployee : row));
              void loadRows();
            }}
            onClose={() => setSelectedEmployee(null)}
          />
        ) : null}
      </AnimatePresence>
      <AnimatePresence>
        {selectedProduct && kind === "products" ? (
          <ProductDetailDrawer
            key={String(selectedProduct.product_code ?? selectedProduct.id ?? "product")}
            product={selectedProduct}
            canEdit={hasPermission(permissions, "product.edit")}
            permissions={permissions}
            jumpTools={jumpTools}
            onSaved={(updatedProduct) => {
              setSelectedProduct(updatedProduct);
              setRows((currentRows) => currentRows.map((row) => row.product_code === updatedProduct.product_code ? updatedProduct : row));
              void loadRows();
            }}
            onClose={() => setSelectedProduct(null)}
          />
        ) : null}
      </AnimatePresence>
      <AnimatePresence>
        {selectedSupplier && kind === "suppliers" ? (
          <SupplierDetailDrawer
            key={String(selectedSupplier.supplier_code ?? selectedSupplier.id ?? "supplier")}
            supplier={selectedSupplier}
            canEdit={hasPermission(permissions, "supplier.edit")}
            permissions={permissions}
            jumpTools={jumpTools}
            onSaved={(updatedSupplier) => {
              setSelectedSupplier(updatedSupplier);
              setRows((currentRows) => currentRows.map((row) => row.supplier_code === updatedSupplier.supplier_code ? updatedSupplier : row));
              void loadRows();
            }}
            onClose={() => setSelectedSupplier(null)}
          />
        ) : null}
      </AnimatePresence>
    </>
	  );
	}

function DataActionCalendar({
  batchesLoader,
  canConfigureRules,
  canSendReminders,
  canViewAudit,
  canViewCrmTasks,
  onOpenImport
}: {
  batchesLoader: (query?: ImportBatchQuery) => Promise<ImportBatch[]>;
  canConfigureRules: boolean;
  canSendReminders: boolean;
  canViewAudit: boolean;
  canViewCrmTasks: boolean;
  onOpenImport: (context?: ImportDrawerContext) => void;
}) {
  const [month, setMonth] = useState(() => startOfMonth(new Date()));
  const [rows, setRows] = useState<ImportBatch[]>([]);
  const [coverageRows, setCoverageRows] = useState<DataCalendarCoverageRow[]>([]);
  const [ruleRows, setRuleRows] = useState<DataCalendarRuleRow[]>([]);
  const [calendarUsers, setCalendarUsers] = useState<UserPublic[]>([]);
  const [uploaders, setUploaders] = useState<Record<number, UserPublic>>({});
  const [errorPreviewByBatchId, setErrorPreviewByBatchId] = useState<Record<number, ImportErrorRow[]>>({});
  const [loading, setLoading] = useState(false);
  const [rulesLoading, setRulesLoading] = useState(false);
  const [ruleDrawerOpen, setRuleDrawerOpen] = useState(false);
  const [selectedDay, setSelectedDay] = useState<DataCalendarDay | null>(null);
  const monthEnd = addDays(addMonths(month, 1), -1);
  const rules = useMemo(() => normalizeDataCalendarRules(ruleRows), [ruleRows]);

  const loadRows = async () => {
    setLoading(true);
    try {
      const range = {
        data_date_from: toDateKey(month),
        data_date_to: toDateKey(monthEnd)
      };
      const [batchRows, coverage] = await Promise.all([
        batchesLoader({
          ...range,
          limit: 1000
        }),
        dataCalendarCoverage(range)
      ]);
      setRows(batchRows);
      setCoverageRows(coverage);
      // Calendar coverage is global import evidence. User names are optional metadata.
      const userRows = await users().catch(() => []);
      setCalendarUsers(userRows);
      setUploaders(Object.fromEntries(userRows.map((user) => [user.id, user])));
    } catch {
      setRows([]);
      setCoverageRows([]);
      setCalendarUsers([]);
      setUploaders({});
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void loadRows();
  }, [month.getFullYear(), month.getMonth()]);

  const loadRules = async () => {
    setRulesLoading(true);
    try {
      setRuleRows(await dataCalendarRules());
    } catch {
      setRuleRows([]);
    } finally {
      setRulesLoading(false);
    }
  };

  useEffect(() => {
    void loadRules();
  }, []);

  const loadBatchErrors = async (batch: ImportBatch) => {
    if (batch.error_rows <= 0 || errorPreviewByBatchId[batch.id]) return;
    try {
      const rows = await importErrors(batch.id);
      setErrorPreviewByBatchId((current) => ({ ...current, [batch.id]: rows.slice(0, 5) }));
    } catch {
      setErrorPreviewByBatchId((current) => ({ ...current, [batch.id]: [] }));
    }
  };

  const days = useMemo(() => buildDataCalendarDays(month, rows, rules, coverageRows), [month, rows, rules, coverageRows]);
  const monthDays = days.filter((day) => day.inMonth);
  const monthSummary = {
    expected: monthDays.reduce((sum, day) => sum + day.expected, 0),
    complete: monthDays.reduce((sum, day) => sum + day.complete, 0),
    missing: monthDays.reduce((sum, day) => sum + day.missing, 0),
    abnormal: monthDays.reduce((sum, day) => sum + day.abnormal, 0),
    pending: monthDays.reduce((sum, day) => sum + day.pending, 0),
    batches: monthDays.reduce((sum, day) => sum + day.batchCount, 0),
    errorRows: monthDays.reduce((sum, day) => sum + day.errorRows, 0),
    missingResponsible: monthDays.reduce((sum, day) => sum + day.missingResponsibleCount, 0),
    offDutyUploads: monthDays.reduce((sum, day) => sum + day.offDutyUploadCount, 0),
  };
  const completionRate = monthSummary.expected > 0 ? `${Math.round((monthSummary.complete / monthSummary.expected) * 100)}%` : "-";

  return (
    <div className="grid gap-4">
      <Card className="p-4">
        <div className="flex flex-col gap-4 lg:flex-row lg:items-center lg:justify-between">
          <div>
            <p className="m-0 text-xs font-black uppercase tracking-[0.16em] text-primary">DATA ACTION CALENDAR</p>
            <h2 className="m-0 mt-1 text-xl font-black text-slate-950">数据动作日历</h2>
            <p className="m-0 mt-1 text-sm font-bold leading-6 text-slate-500">按数据日期检查每日应上传表单、缺失项、异常批次和未闭环动作。</p>
          </div>
          <div className="flex flex-wrap gap-2">
            <Button secondary onClick={() => setMonth(addMonths(month, -1))}>上月</Button>
            <Button secondary onClick={() => setMonth(startOfMonth(new Date()))}>本月</Button>
            <Button secondary onClick={() => setMonth(addMonths(month, 1))}>下月</Button>
            <Button secondary onClick={() => void loadRows()} disabled={loading}><RefreshCcw className="mr-1.5 h-4 w-4" />刷新</Button>
            <Button secondary onClick={() => setRuleDrawerOpen(true)} disabled={rulesLoading}><Settings className="mr-1.5 h-4 w-4" />规则配置</Button>
            <Button onClick={onOpenImport}><UploadCloud className="mr-1.5 h-4 w-4" />导入数据</Button>
          </div>
        </div>
      </Card>

      <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-5">
        <ContextSummaryCard label="当前月份" value={formatCalendarMonth(month)} detail={loading ? "正在刷新批次" : `本月批次 ${rows.length} 条`} icon={CalendarDays} />
        <ContextSummaryCard label="应上传" value={monthSummary.expected} detail="每日必传表单合计" icon={ClipboardList} />
        <ContextSummaryCard label="完成率" value={completionRate} detail={`${monthSummary.complete} 个表单已入库`} icon={ShieldCheck} tone={monthSummary.missing > 0 ? "neutral" : "ok"} />
        <ContextSummaryCard label="责任缺失" value={monthSummary.missingResponsible || monthSummary.missing} detail={monthSummary.missingResponsible > 0 ? "已绑定同事的未上传责任" : "超过截止仍无有效批次"} icon={FileWarning} tone={monthSummary.missing > 0 ? "bad" : "ok"} />
        <ContextSummaryCard label="批次/错误行" value={`${monthSummary.batches}/${monthSummary.errorRows}`} detail={`异常 ${monthSummary.abnormal}，未闭环 ${monthSummary.pending}`} icon={Siren} tone={monthSummary.abnormal > 0 ? "bad" : monthSummary.pending > 0 ? "neutral" : "ok"} />
      </div>

      <Card className="overflow-hidden">
        <div className="flex flex-col gap-3 border-b border-slate-200 px-4 py-3 lg:flex-row lg:items-center lg:justify-between">
          <div>
            <h3 className="m-0 text-base font-black text-slate-950">{formatCalendarMonth(month)} 上传核验</h3>
            <p className="m-0 mt-1 text-sm text-slate-500">当前启用 {rules.length} 条上传规则；每日必传、按需补录和截止时间可在规则配置中维护。</p>
          </div>
          <div className="flex flex-wrap gap-2">
            {(["blue", "green", "orange", "red", "gray"] as CalendarActionLayer[]).map((layer) => (
              <span key={layer} className="inline-flex min-h-7 items-center gap-2 rounded-lg border border-slate-200 bg-white px-2.5 text-xs font-bold text-slate-600">
                <span className={`h-2.5 w-2.5 rounded-full ${calendarLayerMeta[layer].dot}`} />
                {calendarLayerMeta[layer].label}
              </span>
            ))}
          </div>
        </div>
        <div className="overflow-x-auto">
          <div className="min-w-[980px]">
            <div className="grid grid-cols-7 border-b border-slate-200 bg-slate-50">
              {["周一", "周二", "周三", "周四", "周五", "周六", "周日"].map((label) => (
                <div key={label} className="px-3 py-3 text-center text-xs font-black text-slate-500">{label}</div>
              ))}
            </div>
            <div className="grid grid-cols-7">
              {days.map((day) => (
                <button
                  key={day.iso}
                  type="button"
                  onClick={() => setSelectedDay(day)}
                  className={`min-h-[154px] border-b border-r border-slate-200 p-3 text-left transition hover:bg-primary-soft ${day.inMonth ? "bg-white" : "bg-slate-50 text-slate-400"} ${isTodayIso(day.iso) ? "outline outline-2 outline-offset-[-2px] outline-primary" : ""}`}
                >
                  <div className="flex items-start justify-between gap-2">
                    <span className={`text-lg font-black ${day.inMonth ? "text-slate-950" : "text-slate-400"}`}>{day.date.getDate()}</span>
                    <Badge tone={day.tone}>{day.label}</Badge>
                  </div>
                  <div className="mt-2 grid grid-cols-2 gap-1.5">
                    <CalendarMiniMetric label="应传" value={day.expected} />
                    <CalendarMiniMetric label="完成" value={day.complete} tone="ok" />
                    <CalendarMiniMetric label="缺失" value={day.missing} tone={day.missing > 0 ? "bad" : "neutral"} />
                    <CalendarMiniMetric label="责任" value={day.missingResponsibleCount} tone={day.missingResponsibleCount > 0 ? "bad" : day.offDutyUploadCount > 0 ? "warn" : "neutral"} />
                  </div>
                  <div className="mt-2 grid gap-1">
                    {day.requirements.filter((item) => item.rule.frequency === "daily" || item.batches.length > 0).slice(0, 4).map((item) => (
                      <span key={item.rule.code} className={`truncate rounded-md border px-2 py-1 text-xs font-bold ${requirementPillClass(item)}`}>
                        {item.rule.label} · {calendarRequirementStatusLabel(item.status)}
                      </span>
                    ))}
                  </div>
                </button>
              ))}
            </div>
          </div>
        </div>
      </Card>

      <AnimatePresence>
        {ruleDrawerOpen ? (
          <DataCalendarRuleDrawer
            key="data-calendar-rule-drawer"
            rows={ruleRows.length > 0 ? ruleRows : defaultDataCalendarRules.map((rule, index) => fallbackCalendarRuleRow(rule, index))}
            users={calendarUsers}
            canEdit={canConfigureRules}
            onClose={() => setRuleDrawerOpen(false)}
            onSaved={(nextRows) => {
              setRuleRows(nextRows);
              setRuleDrawerOpen(false);
            }}
          />
        ) : null}
      </AnimatePresence>

      <AnimatePresence>
        {selectedDay ? (
          <DataCalendarDayDrawer
            key={selectedDay.iso}
            day={selectedDay}
            uploaders={uploaders}
            errorPreviewByBatchId={errorPreviewByBatchId}
	            canSendReminders={canSendReminders}
	            canViewAudit={canViewAudit}
	            canViewCrmTasks={canViewCrmTasks}
	            onClose={() => setSelectedDay(null)}
            onOpenImport={onOpenImport}
            onPreviewErrors={(batch) => void loadBatchErrors(batch)}
          />
        ) : null}
      </AnimatePresence>
    </div>
  );
}

function CalendarMiniMetric({ label, value, tone = "neutral" }: { label: string; value: number; tone?: ContextTone }) {
  const toneClass = tone === "bad" ? "text-red-600" : tone === "ok" ? "text-emerald-700" : tone === "warn" ? "text-amber-700" : "text-slate-700";
  return (
    <span className="rounded-md bg-slate-50 px-2 py-1">
      <span className="block text-[11px] font-bold text-slate-400">{label}</span>
      <strong className={`block text-sm font-black ${toneClass}`}>{value}</strong>
    </span>
  );
}

function DataCalendarRuleDrawer({
  rows,
  users,
  canEdit,
  onClose,
  onSaved
}: {
  rows: DataCalendarRuleRow[];
  users: UserPublic[];
  canEdit: boolean;
  onClose: () => void;
  onSaved: (rows: DataCalendarRuleRow[]) => void;
}) {
  const [draftRows, setDraftRows] = useState<DataCalendarRuleRow[]>(rows);
  const [message, setMessage] = useState(canEdit ? "维护每日必传、按需上传、截止时间和责任角色。" : "当前账号只能查看规则，不能保存修改。");
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    setDraftRows(rows);
  }, [rows]);

  const patchRow = (ruleCode: string, patch: Partial<DataCalendarRuleRow>) => {
    setDraftRows((current) => current.map((row) => row.rule_code === ruleCode ? { ...row, ...patch } : row));
  };
  const activeUsers = users.filter((user) => user.status === "active" || user.is_active);
  const toggleOwner = (ruleCode: string, userId: number) => {
    setDraftRows((current) => current.map((row) => {
      if (row.rule_code !== ruleCode) return row;
      const currentIds = new Set((row.owner_user_ids ?? []).map((id) => Number(id)));
      if (currentIds.has(userId)) currentIds.delete(userId);
      else currentIds.add(userId);
      return { ...row, owner_user_ids: Array.from(currentIds).sort((left, right) => left - right) };
    }));
  };

  const saveRules = async () => {
    setSaving(true);
    setMessage("正在保存上传规则。");
    try {
      const payload: DataCalendarRulePayload[] = draftRows.map((row) => ({
        id: row.id > 0 ? row.id : null,
        rule_code: row.rule_code,
        file_type: row.file_type,
        label: row.label,
        action_layer: row.action_layer,
        frequency: row.frequency,
        deadline_hour: row.frequency === "daily" ? Number(row.deadline_hour ?? 18) : null,
        owner_role: row.owner_role || "数据中台",
        owner_user_ids: row.owner_user_ids && row.owner_user_ids.length > 0 ? row.owner_user_ids : null,
        is_required: row.frequency === "daily" ? true : row.is_required,
        is_enabled: row.is_enabled,
        sort_order: Number(row.sort_order ?? 0),
        remark: row.remark ?? null
      }));
      const nextRows = await saveDataCalendarRules(payload);
      setMessage("上传规则已保存。");
      onSaved(nextRows);
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "保存上传规则失败");
    } finally {
      setSaving(false);
    }
  };

  const resetRules = async () => {
    setSaving(true);
    setMessage("正在恢复默认上传规则。");
    try {
      const nextRows = await resetDataCalendarRules();
      setDraftRows(nextRows);
      setMessage("已恢复默认上传规则。");
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "恢复默认规则失败");
    } finally {
      setSaving(false);
    }
  };

  return (
    <Drawer title="上传规则配置" subtitle="配置数据动作日历的应传表单、上传频率、截止时间和责任角色。" onClose={onClose}>
      <div className="grid gap-4">
        <section className="rounded-lg border border-slate-200 bg-muted p-4">
          <div className="flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between">
            <div>
              <p className="m-0 text-sm font-black text-slate-950">规则口径</p>
              <p className="m-0 mt-1 text-sm font-bold text-slate-500">{message}</p>
            </div>
            <div className="flex flex-wrap gap-2">
              <Button secondary onClick={() => void resetRules()} disabled={!canEdit || saving}>恢复默认</Button>
              <Button onClick={() => void saveRules()} disabled={!canEdit || saving}>保存规则</Button>
            </div>
          </div>
        </section>

        <div className="grid gap-3">
          {draftRows
            .slice()
            .sort((left, right) => left.sort_order - right.sort_order || left.id - right.id)
            .map((row) => (
              <section key={row.rule_code} className="rounded-lg border border-slate-200 bg-white p-4 shadow-sm">
                <div className="flex flex-col gap-3 lg:flex-row lg:items-start lg:justify-between">
                  <div className="min-w-0">
                    <div className="flex flex-wrap items-center gap-2">
                      <span className={`h-2.5 w-2.5 rounded-full ${calendarLayerMeta[(["blue", "green", "orange", "red", "gray"].includes(row.action_layer) ? row.action_layer : "gray") as CalendarActionLayer].dot}`} />
                      <strong className="text-sm font-black text-slate-950">{row.label}</strong>
                      <Badge tone={row.is_enabled ? "ok" : "neutral"}>{row.is_enabled ? "启用" : "停用"}</Badge>
                      <Badge tone={row.frequency === "daily" ? "warn" : "neutral"}>{row.frequency === "daily" ? "每日必传" : "按需上传"}</Badge>
                      <Badge tone={(row.owner_user_ids?.length ?? 0) > 0 ? "ok" : "neutral"}>责任同事 {row.owner_user_ids?.length ?? 0}</Badge>
                    </div>
                    <p className="m-0 mt-1 text-xs font-bold text-slate-500">{row.rule_code} · {importTypeLabels[row.file_type] ?? row.file_type}</p>
                  </div>
                  <label className="flex items-center gap-2 text-sm font-black text-slate-600">
                    <input
                      type="checkbox"
                      checked={row.is_enabled}
                      disabled={!canEdit}
                      onChange={(event) => patchRow(row.rule_code, { is_enabled: event.target.checked })}
                      className="h-4 w-4 accent-primary"
                    />
                    启用规则
                  </label>
                </div>

                <div className="mt-4 grid gap-3 md:grid-cols-2 xl:grid-cols-6">
                  <AccountField label="显示名称">
                    <input disabled={!canEdit} value={row.label} onChange={(event) => patchRow(row.rule_code, { label: event.target.value })} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold disabled:bg-slate-50" />
                  </AccountField>
                  <AccountField label="动作层级">
                    <select disabled={!canEdit} value={row.action_layer} onChange={(event) => patchRow(row.rule_code, { action_layer: event.target.value })} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold disabled:bg-slate-50">
                      {(["blue", "green", "orange", "red", "gray"] as CalendarActionLayer[]).map((layer) => <option key={layer} value={layer}>{calendarLayerMeta[layer].label}</option>)}
                    </select>
                  </AccountField>
                  <AccountField label="频率">
                    <select
                      disabled={!canEdit}
                      value={row.frequency}
                      onChange={(event) => patchRow(row.rule_code, { frequency: event.target.value, deadline_hour: event.target.value === "daily" ? row.deadline_hour ?? 18 : null, is_required: event.target.value === "daily" })}
                      className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold disabled:bg-slate-50"
                    >
                      <option value="daily">每日必传</option>
                      <option value="ondemand">按需上传</option>
                    </select>
                  </AccountField>
                  <AccountField label="截止小时">
                    <input disabled={!canEdit || row.frequency !== "daily"} type="number" min={0} max={23} value={row.deadline_hour ?? ""} onChange={(event) => patchRow(row.rule_code, { deadline_hour: Number(event.target.value) })} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold disabled:bg-slate-50" />
                  </AccountField>
                  <AccountField label="责任角色">
                    <input disabled={!canEdit} value={row.owner_role} onChange={(event) => patchRow(row.rule_code, { owner_role: event.target.value })} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold disabled:bg-slate-50" />
                  </AccountField>
                  <AccountField label="排序">
                    <input disabled={!canEdit} type="number" value={row.sort_order} onChange={(event) => patchRow(row.rule_code, { sort_order: Number(event.target.value) })} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold disabled:bg-slate-50" />
                  </AccountField>
                </div>
                <label className="mt-3 grid gap-2 text-sm font-black text-slate-700">
                  备注
                  <textarea disabled={!canEdit} value={row.remark ?? ""} onChange={(event) => patchRow(row.rule_code, { remark: event.target.value })} className="min-h-20 rounded-lg border border-slate-200 px-3 py-2 text-sm font-bold text-slate-600 disabled:bg-slate-50" />
                </label>
                <div className="mt-3 rounded-lg border border-slate-200 bg-slate-50 p-3">
                  <div className="flex flex-col gap-2 lg:flex-row lg:items-center lg:justify-between">
                    <div>
                      <p className="m-0 text-sm font-black text-slate-900">责任同事</p>
                      <p className="m-0 mt-1 text-xs font-bold text-slate-500">未指定同事时，日历按责任角色展示；指定后可追踪具体同事未上传。</p>
                    </div>
                    {row.owner_user_ids?.length ? (
                      <button
                        type="button"
                        disabled={!canEdit}
                        onClick={() => patchRow(row.rule_code, { owner_user_ids: [] })}
                        className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-xs font-black text-slate-600 disabled:opacity-50"
                      >
                        清空责任人
                      </button>
                    ) : null}
                  </div>
                  <div className="mt-3 grid gap-2 sm:grid-cols-2 xl:grid-cols-4">
                    {activeUsers.length > 0 ? activeUsers.map((user) => {
                      const checked = (row.owner_user_ids ?? []).map((id) => Number(id)).includes(user.id);
                      return (
                        <label key={`${row.rule_code}-${user.id}`} className={`flex min-h-11 items-center gap-2 rounded-lg border px-3 py-2 text-sm font-bold transition ${checked ? "border-primary bg-primary-soft text-primary" : "border-slate-200 bg-white text-slate-600"}`}>
                          <input
                            type="checkbox"
                            checked={checked}
                            disabled={!canEdit}
                            onChange={() => toggleOwner(row.rule_code, user.id)}
                            className="h-4 w-4 accent-primary"
                          />
                          <span className="min-w-0 truncate">{user.real_name || user.username}</span>
                        </label>
                      );
                    }) : (
                      <div className="rounded-lg bg-white p-3 text-sm font-bold text-slate-500">暂无可选择的正常账号。</div>
                    )}
                  </div>
                </div>
              </section>
            ))}
        </div>
      </div>
    </Drawer>
  );
}

function DataCalendarDayDrawer({
  day,
  uploaders,
  errorPreviewByBatchId,
  canSendReminders,
  canViewAudit,
  canViewCrmTasks,
  onClose,
  onOpenImport,
  onPreviewErrors
}: {
  day: DataCalendarDay;
  uploaders: Record<number, UserPublic>;
  errorPreviewByBatchId: Record<number, ImportErrorRow[]>;
  canSendReminders: boolean;
  canViewAudit: boolean;
  canViewCrmTasks: boolean;
  onClose: () => void;
  onOpenImport: (context?: ImportDrawerContext) => void;
  onPreviewErrors: (batch: ImportBatch) => void;
}) {
  const [activeTab, setActiveTab] = useState<"focus" | "batches" | "rules">("focus");
  const [calendarAudits, setCalendarAudits] = useState<AuditLog[]>([]);
  const [crmDaySummary, setCrmDaySummary] = useState<CrmDailySummary | null>(null);
  const [crmLoading, setCrmLoading] = useState(false);
  const [auditLoading, setAuditLoading] = useState(false);
  const [reminderSending, setReminderSending] = useState(false);
  const [reminderMessage, setReminderMessage] = useState("");
  useEffect(() => {
    setActiveTab("focus");
    setReminderMessage("");
  }, [day.iso]);
  const completionRate = day.expected > 0 ? `${Math.round((day.complete / day.expected) * 100)}%` : "-";
  const dayBatches = day.requirements.flatMap((item) => item.batches);
  const abnormalBatches = dayBatches.filter((batch) => batch.error_rows > 0 || ["partial_error", "failed", "error"].includes(batch.status));
  const successRows = dayBatches.reduce((sum, batch) => sum + batch.success_rows, 0);
  const focusRequirements = dataCalendarActionableRequirements(day);
  const crmDueCount = crmDaySummary?.due_count ?? 0;
  const crmOverdueCount = crmDaySummary?.overdue_count ?? 0;
  const crmFocusCount = crmOverdueCount;
  const blockingCount = focusRequirements.filter((item) => item.status === "missing" || item.status === "abnormal" || item.missingResponsibleUserIds.length > 0).length + crmOverdueCount;
  const tabItems: { key: "focus" | "batches" | "rules"; label: string; count: number }[] = [
    { key: "focus", label: "待处理", count: focusRequirements.length + crmFocusCount },
    { key: "batches", label: "批次明细", count: day.batchCount },
    { key: "rules", label: "全部规则", count: day.requirements.length }
  ];
  const loadCalendarAudits = async () => {
    if (!canViewAudit) {
      setCalendarAudits([]);
      return;
    }
    setAuditLoading(true);
    try {
      const rows = await auditLogs({ limit: 20, resource_type: "data_calendar", resource_id: day.iso });
      setCalendarAudits(rows);
    } catch {
      setCalendarAudits([]);
    } finally {
      setAuditLoading(false);
    }
  };
  useEffect(() => {
    void loadCalendarAudits();
  }, [canViewAudit, day.iso]);
  useEffect(() => {
    if (!canViewCrmTasks) {
      setCrmDaySummary(null);
      return;
    }
    setCrmLoading(true);
    void crmDailySummary({ date: day.iso })
      .then(setCrmDaySummary)
      .catch(() => setCrmDaySummary(null))
      .finally(() => setCrmLoading(false));
  }, [canViewCrmTasks, day.iso]);
  const sendReminder = async () => {
    if (!canSendReminders || reminderSending) return;
    const items = focusRequirements.map((item): DataCalendarReminderItem => ({
      rule_code: item.rule.code,
      file_type: item.rule.fileType,
      label: item.rule.label,
      status: item.status,
      detail: item.detail,
      responsible_user_ids: item.responsibleUserIds,
      missing_responsible_user_ids: item.missingResponsibleUserIds,
      latest_batch_no: item.latestBatch?.batch_no ?? null
    }));
    if (crmDaySummary && crmDaySummary.overdue_count > 0) {
      items.push({
        rule_code: "crm_followup_due",
        file_type: "crm_followup_due",
        label: "CRM 跟进责任",
        status: "missing",
        detail: `${formatDate(day.iso)} 有 ${crmDaySummary.overdue_count} 个客户任务超期未形成有效反馈。`,
        responsible_user_ids: crmDaySummary.responsible_user_ids,
        missing_responsible_user_ids: crmDaySummary.missing_responsible_user_ids,
        latest_batch_no: null
      });
    }
    if (items.length === 0) {
      setReminderMessage("当天暂无需要提醒的事项。");
      return;
    }
    setReminderSending(true);
    setReminderMessage("正在记录提醒。");
    try {
      const result = await sendDataCalendarReminder({
        data_date: day.iso,
        reminder_type: "missing_and_abnormal",
        items,
        message: `${formatDate(day.iso)} 待处理 ${items.length} 项，阻塞 ${blockingCount} 项。`
      });
      setReminderMessage(`已记录提醒，审计 #${result.audit_id}，共 ${result.reminder_count} 项。`);
      await loadCalendarAudits();
    } catch (error) {
      setReminderMessage(error instanceof Error ? error.message : "记录提醒失败");
    } finally {
      setReminderSending(false);
    }
  };

  return (
    <Drawer title="日期详情工作台" subtitle={`${formatDate(day.iso)} · ${day.label}`} onClose={onClose}>
      <div className="grid gap-4">
        <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-6">
          <ContextSummaryCard label="应上传" value={day.expected} detail="每日必传表单" icon={ClipboardList} />
          <ContextSummaryCard label="已完成" value={day.complete} detail={`完成率 ${completionRate}`} icon={ShieldCheck} tone={day.missing > 0 ? "neutral" : "ok"} />
          <ContextSummaryCard label="责任缺失" value={day.missingResponsibleCount || day.missing} detail={day.missingResponsibleCount > 0 ? "具体同事未上传" : "超过截止仍无批次"} icon={FileWarning} tone={day.missing > 0 ? "bad" : "ok"} />
          <ContextSummaryCard label="错误行" value={day.errorRows} detail={`${abnormalBatches.length} 个异常批次`} icon={Siren} tone={day.errorRows > 0 ? "bad" : "ok"} />
          <ContextSummaryCard label="代传/未闭环" value={day.offDutyUploadCount + day.pending} detail={`代传 ${day.offDutyUploadCount}，未闭环 ${day.pending}`} icon={Clock3} tone={day.offDutyUploadCount > 0 || day.pending > 0 ? "neutral" : "ok"} />
          <ContextSummaryCard label="CRM跟进" value={crmLoading ? "刷新中" : crmDueCount} detail={`超期 ${crmOverdueCount} · 责任 ${crmDaySummary?.responsible_user_ids.length ?? 0} 人`} icon={BriefcaseBusiness} tone={crmOverdueCount > 0 ? "bad" : crmDueCount > 0 ? "neutral" : "ok"} />
        </div>

        <section className="rounded-lg border border-slate-200 bg-white p-2 shadow-sm">
          <div className="grid gap-2 sm:grid-cols-3">
            {tabItems.map((tab) => (
              <button
                key={tab.key}
                type="button"
                onClick={() => setActiveTab(tab.key)}
                className={`flex items-center justify-between rounded-md px-3 py-2 text-sm font-black transition ${
                  activeTab === tab.key
                    ? "bg-primary text-white shadow-sm"
                    : "bg-slate-50 text-slate-600 hover:bg-slate-100"
                }`}
              >
                <span>{tab.label}</span>
                <span className={`rounded-full px-2 py-0.5 text-xs ${activeTab === tab.key ? "bg-white/20 text-white" : "bg-white text-slate-500"}`}>{tab.count}</span>
              </button>
            ))}
          </div>
        </section>

        {activeTab === "focus" ? (
          <div className="grid gap-4 xl:grid-cols-[minmax(0,1fr)_320px]">
            <section className="rounded-lg border border-slate-200 bg-white p-4">
              <div className="flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between">
                <div>
                  <h4 className="m-0 text-sm font-black text-slate-950">待处理队列</h4>
                  <p className="m-0 mt-1 text-xs font-bold text-slate-500">优先列出缺失、异常、未入库、非责任人代传的表单，以及 CRM 超期跟进责任。</p>
                </div>
                <Button onClick={() => onOpenImport({ dataDate: day.iso })}><UploadCloud className="mr-1.5 h-4 w-4" />打开导入</Button>
              </div>
              <div className="mt-4 grid gap-3">
                {focusRequirements.length > 0 ? (
                  focusRequirements.map((item) => (
                    <CalendarIssueCard
                      key={item.rule.code}
                      requirement={item}
                      users={uploaders}
                      onOpenImport={() => onOpenImport({
                        batchId: item.latestBatch?.id,
                        fileType: item.rule.fileType,
                        dataDate: item.latestBatch ? batchDateKey(item.latestBatch) : day.iso,
                        activeTab: item.latestBatch ? "flow" : undefined
                      })}
                    />
                  ))
                ) : null}
                {canViewCrmTasks ? (
                  <CrmDailyFollowupBlock
                    summary={crmDaySummary}
                    loading={crmLoading}
                    users={uploaders}
                  />
                ) : null}
                {focusRequirements.length === 0 && crmOverdueCount === 0 && !crmLoading ? (
                  <div className="rounded-lg border border-emerald-100 bg-emerald-50 p-5">
                    <div className="flex items-center gap-2 text-sm font-black text-emerald-700">
                      <ShieldCheck className="h-4 w-4" />
                      当天没有待处理事项
                    </div>
                    <p className="m-0 mt-2 text-sm font-bold leading-6 text-emerald-700/80">所有必传表单、责任人上传和批次状态均已闭环，可以继续查看批次明细或全部规则。</p>
                  </div>
                ) : null}
              </div>
            </section>

            <aside className="grid content-start gap-3">
              <section className="rounded-lg border border-slate-200 bg-white p-4">
                <h4 className="m-0 text-sm font-black text-slate-950">处理摘要</h4>
                <div className="mt-3 grid gap-2">
	                  <InsightMetric label="阻塞事项" value={blockingCount} tone={blockingCount > 0 ? "bad" : "ok"} />
	                  <InsightMetric label="未闭环表单" value={day.pending} tone={day.pending > 0 ? "neutral" : "ok"} />
	                  <InsightMetric label="异常批次" value={abnormalBatches.length} tone={abnormalBatches.length > 0 ? "bad" : "ok"} />
	                  <InsightMetric label="CRM超期" value={crmOverdueCount} tone={crmOverdueCount > 0 ? "bad" : "ok"} />
	                </div>
	              </section>
              <section className="rounded-lg border border-slate-200 bg-white p-4">
                <h4 className="m-0 text-sm font-black text-slate-950">快捷入口</h4>
                <div className="mt-3 grid gap-2">
                  <Button onClick={() => onOpenImport({ dataDate: day.iso })}><UploadCloud className="mr-1.5 h-4 w-4" />按日期导入</Button>
                  <Button secondary onClick={() => setActiveTab("batches")}>查看当天批次</Button>
                  <Button secondary onClick={() => setActiveTab("rules")}>查看全部规则</Button>
                </div>
              </section>
              <CalendarReminderAuditPanel
	                focusCount={focusRequirements.length + crmFocusCount}
                blockingCount={blockingCount}
                audits={calendarAudits}
                auditLoading={auditLoading}
                canSendReminders={canSendReminders}
                canViewAudit={canViewAudit}
                reminderSending={reminderSending}
                message={reminderMessage}
                onSendReminder={() => void sendReminder()}
                onRefreshAudits={() => void loadCalendarAudits()}
              />
            </aside>
          </div>
        ) : null}

        {activeTab === "batches" ? (
          <section className="rounded-lg border border-slate-200 bg-white p-4">
            <div className="flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between">
              <div>
                <h4 className="m-0 text-sm font-black text-slate-950">当天批次明细</h4>
                <p className="m-0 mt-1 text-xs font-bold text-slate-500">按数据日期聚合当天所有关联批次，点击批次可回到导入抽屉继续校验或提交。</p>
              </div>
              <Button onClick={() => onOpenImport({ dataDate: day.iso, activeTab: "history" })}><UploadCloud className="mr-1.5 h-4 w-4" />打开当天批次</Button>
            </div>
            <div className="mt-4 grid gap-3 md:grid-cols-4">
              <InsightMetric label="关联批次" value={day.batchCount} tone={day.batchCount > 0 ? "ok" : "neutral"} />
              <InsightMetric label="成功行" value={successRows} tone="ok" />
              <InsightMetric label="错误行" value={day.errorRows} tone={day.errorRows > 0 ? "bad" : "ok"} />
              <InsightMetric label="责任缺失" value={day.missingResponsibleCount || "-"} tone={day.missingResponsibleCount > 0 ? "bad" : "neutral"} />
            </div>
            <div className="mt-4 grid gap-3">
              {dayBatches.length > 0 ? (
                dayBatches.map((batch) => (
                  <CalendarBatchCard
                    key={batch.id}
                    batch={batch}
                    uploader={batch.uploaded_by ? uploaders[batch.uploaded_by] : undefined}
                    errors={errorPreviewByBatchId[batch.id]}
                    onPreviewErrors={() => onPreviewErrors(batch)}
                    onOpenImport={() => onOpenImport({ batchId: batch.id, fileType: batch.file_type, dataDate: batchDateKey(batch), activeTab: "flow" })}
                  />
                ))
              ) : (
                <p className="m-0 rounded-lg bg-slate-50 px-3 py-4 text-sm font-bold text-slate-500">当天暂无关联批次。</p>
              )}
            </div>
          </section>
        ) : null}

        {activeTab === "rules" ? (
          <section className="rounded-lg border border-slate-200 bg-white p-4">
            <div className="flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between">
              <div>
                <h4 className="m-0 text-sm font-black text-slate-950">当天全部表单规则</h4>
                <p className="m-0 mt-1 text-xs font-bold text-slate-500">已联动导入批次、上传人、错误行预览和批次工作台入口。</p>
              </div>
              <Button onClick={() => onOpenImport({ dataDate: day.iso })}><UploadCloud className="mr-1.5 h-4 w-4" />打开导入</Button>
            </div>
            <div className="mt-4 grid gap-2">
              {day.requirements.map((item) => (
                <CalendarRequirementDetail
                  key={item.rule.code}
                  requirement={item}
                  users={uploaders}
                  errorsByBatchId={errorPreviewByBatchId}
                  onPreviewErrors={onPreviewErrors}
                  onOpenBatch={(batch) => onOpenImport({ batchId: batch.id, fileType: batch.file_type, dataDate: batchDateKey(batch), activeTab: "flow" })}
                />
              ))}
            </div>
          </section>
        ) : null}
      </div>
    </Drawer>
  );
}

function CalendarReminderAuditPanel({
  focusCount,
  blockingCount,
  audits,
  auditLoading,
  canSendReminders,
  canViewAudit,
  reminderSending,
  message,
  onSendReminder,
  onRefreshAudits
}: {
  focusCount: number;
  blockingCount: number;
  audits: AuditLog[];
  auditLoading: boolean;
  canSendReminders: boolean;
  canViewAudit: boolean;
  reminderSending: boolean;
  message: string;
  onSendReminder: () => void;
  onRefreshAudits: () => void;
}) {
  const latestReminder = audits.find((row) => row.action_type === "send_data_calendar_reminder");
  return (
    <section className="rounded-lg border border-slate-200 bg-white p-4">
      <div className="flex items-start justify-between gap-3">
        <div>
          <h4 className="m-0 text-sm font-black text-slate-950">提醒与审计</h4>
          <p className="m-0 mt-1 text-xs font-bold leading-5 text-slate-500">提醒记录会写入审计日志，便于后续追踪谁在什么时间提醒了哪些表单与 CRM 跟进责任。</p>
        </div>
        <Badge tone={latestReminder ? "ok" : focusCount > 0 ? "warn" : "neutral"}>{latestReminder ? "已提醒" : "待记录"}</Badge>
      </div>
      <div className="mt-3 grid gap-2">
        <div className="grid grid-cols-2 gap-2">
          <InsightMetric label="待提醒" value={focusCount} tone={focusCount > 0 ? "neutral" : "ok"} />
          <InsightMetric label="阻塞" value={blockingCount} tone={blockingCount > 0 ? "bad" : "ok"} />
        </div>
        <Button onClick={onSendReminder} disabled={!canSendReminders || reminderSending || focusCount === 0}>
          <Bell className="mr-1.5 h-4 w-4" />{reminderSending ? "记录中" : "记录提醒"}
        </Button>
        {!canSendReminders ? <p className="m-0 rounded-lg bg-slate-50 px-3 py-2 text-xs font-bold text-slate-500">当前账号没有提醒记录权限。</p> : null}
        {message ? <p className="m-0 rounded-lg bg-muted px-3 py-2 text-xs font-black text-slate-600">{message}</p> : null}
      </div>
      <div className="mt-4 border-t border-slate-200 pt-3">
        <div className="flex items-center justify-between gap-2">
          <span className="text-xs font-black text-slate-500">当天审计</span>
          <button type="button" onClick={onRefreshAudits} disabled={!canViewAudit || auditLoading} className="text-xs font-black text-primary disabled:text-slate-300">
            {auditLoading ? "刷新中" : "刷新"}
          </button>
        </div>
        {!canViewAudit ? (
          <p className="m-0 mt-2 rounded-lg bg-slate-50 px-3 py-2 text-xs font-bold text-slate-500">当前账号没有审计查看权限。</p>
        ) : audits.length > 0 ? (
          <div className="mt-2 grid gap-2">
            {audits.slice(0, 4).map((row) => (
              <div key={row.id} className="rounded-lg border border-slate-200 bg-slate-50 px-3 py-2">
                <div className="flex items-center justify-between gap-2">
                  <strong className="truncate text-xs font-black text-slate-800">{calendarAuditActionLabel(row.action_type)}</strong>
                  <span className="text-[11px] font-bold text-slate-400">#{row.id}</span>
                </div>
                <p className="m-0 mt-1 text-xs font-bold text-slate-500">{formatDateTime(row.created_at)}</p>
              </div>
            ))}
          </div>
        ) : (
          <p className="m-0 mt-2 rounded-lg bg-slate-50 px-3 py-2 text-xs font-bold text-slate-500">当天暂无日历相关审计。</p>
        )}
      </div>
    </section>
  );
}

