function calendarRequirementPriority(requirement: DataCalendarRequirement) {
  if (requirement.status === "missing" || requirement.missingResponsibleUserIds.length > 0) return 1;
  if (requirement.status === "abnormal") return 2;
  if (requirement.status === "pending" || requirement.status === "uploaded") return 3;
  if (requirement.uploadedByResponsible === false) return 4;
  return 9;
}

function dataCalendarActionableRequirements(day: DataCalendarDay) {
  return day.requirements
    .filter((item) => item.status === "missing" || item.status === "abnormal" || item.status === "pending" || item.status === "uploaded" || item.missingResponsibleUserIds.length > 0 || item.uploadedByResponsible === false)
    .sort((left, right) => calendarRequirementPriority(left) - calendarRequirementPriority(right));
}

function calendarAuditActionLabel(action: string) {
  const labels: Record<string, string> = {
    send_data_calendar_reminder: "记录日历提醒",
    view_data_calendar_day: "查看日期详情",
    update_data_calendar_rule: "修改上传规则",
    refresh_data_calendar_status: "刷新日历状态",
    exempt_data_calendar_requirement: "标记上传豁免",
    cancel_data_calendar_exemption: "取消上传豁免"
  };
  return labels[action] ?? action;
}

function CalendarBatchCard({
  batch,
  uploader,
  errors,
  onPreviewErrors,
  onOpenImport
}: {
  batch: ImportBatch;
  uploader?: UserPublic;
  errors?: ImportErrorRow[];
  onPreviewErrors: () => void;
  onOpenImport: () => void;
}) {
  const isAbnormal = batch.error_rows > 0 || ["partial_error", "failed", "error"].includes(batch.status);
  const isPending = !["committed", "failed", "error", "partial_error"].includes(batch.status);
  const tone: ContextTone = isAbnormal ? "bad" : isPending ? "warn" : "ok";
  return (
    <div className="rounded-lg border border-slate-200 bg-white p-3 shadow-sm">
      <div className="flex flex-col gap-3 lg:flex-row lg:items-start lg:justify-between">
        <div className="min-w-0">
          <div className="flex flex-wrap items-center gap-2">
            <strong className="truncate text-sm font-black text-slate-950">{batch.batch_no}</strong>
            <Badge tone={tone}>{importBatchStatusLabel(batch.status)}</Badge>
            <Badge tone={batch.error_rows > 0 ? "bad" : "ok"}>错误 {batch.error_rows}</Badge>
          </div>
          <p className="m-0 mt-1 truncate text-xs font-bold text-slate-500">{batch.file_name}</p>
          <div className="mt-2 flex flex-wrap gap-x-4 gap-y-1 text-xs font-bold text-slate-500">
            <span>上传人：{uploader?.real_name || uploader?.username || (batch.uploaded_by ? `用户 ${batch.uploaded_by}` : "-")}</span>
            <span>上传时间：{formatDateTime(batch.uploaded_at)}</span>
            <span>数据日期：{formatDate(batchDateKey(batch))}</span>
          </div>
        </div>
        <div className="flex shrink-0 flex-wrap gap-2">
          <button
            type="button"
            onClick={onPreviewErrors}
            disabled={batch.error_rows <= 0}
            className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-xs font-black text-slate-600 transition hover:bg-slate-50 disabled:cursor-not-allowed disabled:opacity-50"
          >
            错误预览
          </button>
          <button
            type="button"
            onClick={onOpenImport}
            className="rounded-lg bg-primary px-3 py-2 text-xs font-black text-white shadow-sm transition hover:bg-primary-hover"
          >
            打开批次
          </button>
        </div>
      </div>
      <div className="mt-3 grid gap-2 md:grid-cols-4">
        <InsightMetric label="总行数" value={batch.total_rows} tone="neutral" />
        <InsightMetric label="成功行" value={batch.success_rows} tone="ok" />
        <InsightMetric label="错误行" value={batch.error_rows} tone={batch.error_rows > 0 ? "bad" : "ok"} />
        <InsightMetric label="映射字段" value={Object.keys(batch.mapping_json ?? {}).length} tone="neutral" />
      </div>
      {errors && errors.length > 0 ? (
        <div className="mt-3 overflow-hidden rounded-lg border border-red-100 bg-red-50">
          <div className="border-b border-red-100 px-3 py-2 text-xs font-black text-red-700">错误行预览</div>
          <div className="divide-y divide-red-100">
            {errors.map((error) => (
              <div key={error.id} className="grid gap-1 px-3 py-2 text-xs font-bold text-red-700 md:grid-cols-[80px_140px_minmax(0,1fr)]">
                <span>第 {error.row_number} 行</span>
                <span>{error.error_type}</span>
                <span className="truncate">{error.error_message}</span>
              </div>
            ))}
          </div>
        </div>
      ) : errors && batch.error_rows > 0 ? (
        <p className="m-0 mt-3 rounded-lg bg-slate-50 px-3 py-2 text-xs font-bold text-slate-500">未读取到错误行明细，可能已被清理或无查看权限。</p>
      ) : null}
    </div>
  );
}

