function fallbackCalendarRuleRow(rule: DataCalendarRule, index: number): DataCalendarRuleRow {
  return {
    id: -index - 1,
    rule_code: rule.code,
    file_type: rule.fileType,
    label: rule.label,
    action_layer: rule.layer,
    frequency: rule.frequency,
    deadline_hour: rule.deadlineHour ?? null,
    owner_role: rule.ownerRole,
    owner_user_ids: rule.ownerUserIds,
    is_required: rule.frequency === "daily",
    is_enabled: rule.enabled,
    sort_order: index * 10,
    remark: null,
    created_at: "",
    updated_at: ""
  };
}

function buildDataCalendarDays(month: Date, rows: ImportBatch[], rules: DataCalendarRule[], coverageRows: DataCalendarCoverageRow[] = []): DataCalendarDay[] {
  const monthStart = startOfMonth(month);
  const firstGridDay = addDays(monthStart, -mondayIndex(monthStart));
  return Array.from({ length: 42 }, (_, index) => {
    const date = addDays(firstGridDay, index);
    return buildDataCalendarDay(date, monthStart, rows, rules, coverageRows);
  });
}

function buildDataCalendarDay(date: Date, monthStart: Date, rows: ImportBatch[], rules: DataCalendarRule[], coverageRows: DataCalendarCoverageRow[] = []): DataCalendarDay {
  const iso = toDateKey(date);
  const requirements = rules
    .filter((rule) => rule.enabled)
    .map((rule) => buildDataCalendarRequirement(rule, iso, rows, coverageRows));
  const expected = requirements.filter((item) => item.rule.frequency === "daily").length;
  const complete = requirements.filter((item) => item.rule.frequency === "daily" && item.status === "complete").length;
  const missing = requirements.filter((item) => item.status === "missing").length;
  const abnormal = requirements.filter((item) => item.status === "abnormal").length;
  const pending = requirements.filter((item) => item.status === "pending" || item.status === "uploaded").length;
  const optional = requirements.filter((item) => item.rule.frequency === "ondemand" && item.batches.length > 0).length;
  const batchCount = requirements.reduce((sum, item) => sum + item.batches.length, 0);
  const errorRows = requirements.reduce((sum, item) => sum + item.batches.reduce((batchSum, batch) => batchSum + batch.error_rows, 0), 0);
  const missingResponsibleCount = requirements.reduce((sum, item) => sum + item.missingResponsibleUserIds.length, 0);
  const offDutyUploadCount = requirements.filter((item) => item.uploadedByResponsible === false).length;
  const tone: ContextTone = missing > 0 ? "bad" : abnormal > 0 ? "bad" : pending > 0 ? "warn" : expected > 0 && complete === expected ? "ok" : "neutral";
  const label = missing > 0 ? "缺失" : abnormal > 0 ? "异常" : pending > 0 ? "未闭环" : expected > 0 && complete === expected ? "完成" : optional > 0 ? "按需" : "无要求";
  return {
    date,
    iso,
    inMonth: date.getMonth() === monthStart.getMonth(),
    requirements,
    expected,
    complete,
    missing,
    abnormal,
    pending,
    optional,
    batchCount,
    errorRows,
    missingResponsibleCount,
    offDutyUploadCount,
    tone,
    label
  };
}

function buildDataCalendarRequirement(rule: DataCalendarRule, iso: string, rows: ImportBatch[], coverageRows: DataCalendarCoverageRow[] = []): DataCalendarRequirement {
  const batchesForDay = rows
    .filter((row) => row.file_type === rule.fileType && batchDateKey(row) === iso)
    .sort((left, right) => String(right.uploaded_at ?? "").localeCompare(String(left.uploaded_at ?? "")));
  const coverage = coverageRows.find((row) => row.file_type === rule.fileType && String(row.data_date).slice(0, 10) === iso);
  const coveredBatch = coverage?.latest_batch_id ? rows.find((row) => row.id === coverage.latest_batch_id) : undefined;
  const committed = batchesForDay.find((row) => row.status === "committed");
  const abnormal = batchesForDay.find((row) => row.status === "partial_error" || row.error_rows > 0);
  const validated = batchesForDay.find((row) => row.status === "validated");
  const uploaded = batchesForDay.find((row) => row.status === "uploaded");
  const latest = batchesForDay[0] ?? coveredBatch;
  const responsibleUserIds = rule.ownerUserIds ?? [];
  const responsibilityBatch = committed ?? validated ?? uploaded ?? latest;
  const uploadedByResponsible = responsibleUserIds.length > 0 && responsibilityBatch?.uploaded_by
    ? responsibleUserIds.includes(Number(responsibilityBatch.uploaded_by))
    : responsibleUserIds.length > 0 && responsibilityBatch
      ? false
      : null;
  let status: CalendarRequirementStatus = "optional";
  let tone: ContextTone = "neutral";
  let detail = "按需上传，未发生批次。";
  let missingResponsibleUserIds: number[] = [];

  if (committed) {
    status = "complete";
    tone = uploadedByResponsible === false ? "warn" : "ok";
    detail = uploadedByResponsible === false ? `已由非责任人入库：${committed.batch_no}` : `已入库：${committed.batch_no}`;
  } else if (coverage?.status === "complete") {
    status = "complete";
    tone = uploadedByResponsible === false ? "warn" : "ok";
    detail = `已覆盖：${coverage.row_count} 行，来源批次 ${coverage.latest_batch_no ?? coverage.batch_nos[0] ?? "-"}`;
  } else if (abnormal) {
    status = "abnormal";
    tone = "bad";
    detail = `异常批次：${abnormal.batch_no}，错误 ${abnormal.error_rows}`;
  } else if (validated) {
    status = "pending";
    tone = "warn";
    detail = `已校验未入库：${validated.batch_no}`;
  } else if (uploaded) {
    status = "uploaded";
    tone = "warn";
    detail = `已上传未校验：${uploaded.batch_no}`;
  } else if (rule.frequency === "daily") {
    const deadline = deadlineForDate(iso, rule.deadlineHour ?? 18);
    if (new Date() > deadline) {
      status = "missing";
      tone = "bad";
      detail = `超过 ${rule.deadlineHour ?? 18}:00 仍未上传。`;
      missingResponsibleUserIds = responsibleUserIds;
    } else {
      status = "not_due";
      tone = "neutral";
      detail = `尚未到 ${rule.deadlineHour ?? 18}:00 截止时间。`;
    }
  }

  return {
    rule,
    status,
    tone,
    batches: batchesForDay,
    coverage,
    responsibleUserIds,
    missingResponsibleUserIds,
    uploadedByResponsible,
    completedBatch: committed ?? (coverage?.status === "complete" ? coveredBatch : undefined),
    latestBatch: latest,
    detail
  };
}

function requirementPillClass(item: DataCalendarRequirement) {
  if (item.status === "missing") return "border-red-100 bg-red-50 text-red-600";
  if (item.status === "abnormal") return "border-orange-100 bg-orange-50 text-orange-700";
  if (item.status === "complete") return calendarLayerMeta[item.rule.layer].className;
  if (item.status === "pending" || item.status === "uploaded") return "border-cyan-100 bg-cyan-50 text-cyan-700";
  return "border-slate-200 bg-slate-50 text-slate-500";
}

function calendarRequirementStatusLabel(status: CalendarRequirementStatus) {
  const labels: Record<CalendarRequirementStatus, string> = {
    complete: "已完成",
    missing: "缺失",
    abnormal: "异常",
    pending: "已校验未入库",
    uploaded: "已上传未校验",
    optional: "按需",
    not_due: "未到期"
  };
  return labels[status];
}

function importBatchStatusLabel(status: string) {
  const labels: Record<string, string> = {
    uploaded: "已上传",
    validated: "已校验",
    committed: "已入库",
    partial_error: "部分错误",
    failed: "失败",
    error: "错误"
  };
  return labels[status] ?? status;
}

function batchDateKey(batch: ImportBatch) {
  if (batch.data_date) return String(batch.data_date).slice(0, 10);
  if (batch.uploaded_at) return String(batch.uploaded_at).slice(0, 10);
  return "";
}

function startOfMonth(value: Date) {
  return new Date(value.getFullYear(), value.getMonth(), 1);
}

function addMonths(value: Date, months: number) {
  return new Date(value.getFullYear(), value.getMonth() + months, 1);
}

function addDays(value: Date, days: number) {
  return new Date(value.getFullYear(), value.getMonth(), value.getDate() + days);
}

function mondayIndex(value: Date) {
  return (value.getDay() + 6) % 7;
}

function toDateKey(value: Date) {
  const year = value.getFullYear();
  const month = String(value.getMonth() + 1).padStart(2, "0");
  const day = String(value.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function deadlineForDate(iso: string, hour: number) {
  const [year, month, day] = iso.split("-").map((part) => Number.parseInt(part, 10));
  return new Date(year, month - 1, day, hour, 0, 0);
}

function isTodayIso(iso: string) {
  return iso === toDateKey(new Date());
}

function formatCalendarMonth(value: Date) {
  return `${value.getFullYear()}年${String(value.getMonth() + 1).padStart(2, "0")}月`;
}

function MasterPagination({
  currentPage,
  totalPages,
  totalItems,
  pageSize,
  rangeStart,
  rangeEnd,
  onPageChange
}: {
  currentPage: number;
  totalPages: number;
  totalItems: number;
  pageSize: number;
  rangeStart: number;
  rangeEnd: number;
  onPageChange: (page: number) => void;
}) {
  const [jumpValue, setJumpValue] = useState(String(currentPage));

  useEffect(() => {
    setJumpValue(String(currentPage));
  }, [currentPage]);

  const goToPage = (page: number) => {
    const nextPage = Math.max(1, Math.min(totalPages, page));
    onPageChange(nextPage);
  };

  const submitJump = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const parsed = Number.parseInt(jumpValue, 10);
    if (Number.isNaN(parsed)) {
      setJumpValue(String(currentPage));
      return;
    }
    goToPage(parsed);
  };

  return (
    <div className="flex flex-col gap-3 border-t border-border bg-card px-4 py-3 md:flex-row md:items-center md:justify-between">
      <div className="text-sm font-bold text-muted-foreground">
        每页最多 <span className="text-foreground">{pageSize}</span> 条
        <span className="mx-2 text-border">/</span>
        当前 <span className="text-foreground">{rangeStart}-{rangeEnd}</span>
        <span className="mx-2 text-border">/</span>
        共 <span className="text-foreground">{totalItems}</span> 条
      </div>
      <div className="flex flex-wrap items-center gap-2">
        <button
          type="button"
          disabled={currentPage <= 1}
          onClick={() => goToPage(currentPage - 1)}
          className="project-button-secondary px-3 disabled:opacity-45"
        >
          上一页
        </button>
        <span className="rounded-lg bg-muted px-3 py-2 text-sm font-black text-foreground ring-1 ring-border">
          {currentPage} / {totalPages}
        </span>
        <button
          type="button"
          disabled={currentPage >= totalPages}
          onClick={() => goToPage(currentPage + 1)}
          className="project-button-secondary px-3 disabled:opacity-45"
        >
          下一页
        </button>
        <form onSubmit={submitJump} className="flex items-center gap-2">
          <label className="text-sm font-bold text-muted-foreground" htmlFor="master-page-jump">跳至</label>
          <input
            id="master-page-jump"
            value={jumpValue}
            onChange={(event) => setJumpValue(event.target.value.replace(/[^\d]/g, ""))}
            inputMode="numeric"
            className="project-input-sm w-16 px-2 text-center font-black"
            aria-label="跳转页码"
          />
          <button
            type="submit"
            className="project-button-primary px-3"
          >
            跳转
          </button>
        </form>
      </div>
    </div>
  );
}

