function masterCategoryNodeOptions(nodes: MasterCategoryNodeRow[], excludeId?: number | null) {
  const nodeById = new Map(nodes.map((node) => [node.id, node]));
  const pathFor = (node: MasterCategoryNodeRow) => {
    const labels = [node.label];
    let current = node;
    let guard = 0;
    while (current.parent_id && guard < 20) {
      const parent = nodeById.get(current.parent_id);
      if (!parent) break;
      labels.unshift(parent.label);
      current = parent;
      guard += 1;
    }
    return labels.join(" / ");
  };
  return nodes
    .filter((node) => node.id !== excludeId)
    .map((node) => ({ value: node.id, label: pathFor(node), disabled: !node.is_enabled }))
    .sort((left, right) => left.label.localeCompare(right.label, "zh-CN"));
}

function MasterCategoryDrawer({
  mode,
  kind,
  selectedCategory,
  editingCategory,
  nodes,
  onClose,
  onSaved
}: {
  mode: "create" | "edit";
  kind: HierarchyKind;
  selectedCategory: CategoryNode | null;
  editingCategory: MasterCategoryNodeRow | null;
  nodes: MasterCategoryNodeRow[];
  onClose: () => void;
  onSaved: (message: string, savedNode: MasterCategoryNodeRow | null) => void | Promise<void>;
}) {
  const [form, setForm] = useState<Required<Pick<MasterCategoryNodePayload, "label" | "sort_order" | "is_enabled">> & { parent_id: number | null; remark: string }>({
    label: editingCategory?.label ?? "",
    parent_id: mode === "create" ? selectedCategory?.category_id ?? null : editingCategory?.parent_id ?? null,
    sort_order: editingCategory?.sort_order ?? 0,
    is_enabled: editingCategory?.is_enabled ?? true,
    remark: editingCategory?.remark ?? ""
  });
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const kindLabel = kind === "products" ? "商品分类" : "客户分类";
  const parentOptions = masterCategoryNodeOptions(nodes, editingCategory?.id);
  const title = mode === "create" ? `新增${kindLabel}` : `编辑${kindLabel}`;

  const payload = (): MasterCategoryNodePayload => ({
    label: form.label.trim(),
    parent_id: form.parent_id,
    sort_order: Number(form.sort_order) || 0,
    is_enabled: form.is_enabled,
    remark: form.remark.trim() || null
  });

  const save = async () => {
    if (!form.label.trim()) {
      setError("分类名称不能为空。");
      return;
    }
    setSaving(true);
    setError("");
    try {
      const saved = mode === "create"
        ? await createMasterCategoryNode(kind, payload())
        : editingCategory
          ? await updateMasterCategoryNode(editingCategory.id, payload())
          : null;
      if (!saved) throw new Error("未找到可编辑的分类。");
      await onSaved(`${mode === "create" ? "已新增" : "已保存"}分类「${saved.label}」。`, saved);
    } catch (saveError) {
      setError(saveError instanceof Error ? saveError.message : "保存分类失败。");
    } finally {
      setSaving(false);
    }
  };

  const remove = async () => {
    if (!editingCategory) return;
    if (!window.confirm(`确认删除分类「${editingCategory.label}」及其子分类绑定吗？档案本身不会被删除。`)) return;
    setSaving(true);
    setError("");
    try {
      const result = await deleteMasterCategoryNode(editingCategory.id);
      await onSaved(`已删除 ${result.deleted_category_ids.length} 个分类节点，并移除 ${result.deleted_bindings} 条绑定。`, null);
    } catch (deleteError) {
      setError(deleteError instanceof Error ? deleteError.message : "删除分类失败。");
    } finally {
      setSaving(false);
    }
  };

  return (
    <Drawer title={title} subtitle={`${kindLabel} · 支持父级、排序、启停和备注`} onClose={onClose}>
      <div className="grid gap-4">
        <section className="rounded-lg border border-slate-200 bg-white p-4">
          <p className="m-0 text-xs font-black uppercase tracking-[0.16em] text-primary">CATEGORY TREE</p>
          <h3 className="m-0 mt-1 text-xl font-black text-slate-950">{title}</h3>
          <p className="m-0 mt-2 text-sm leading-6 text-slate-500">分类节点会持久化到数据库；未绑定档案仍会按基础字段出现在动态兜底分类里。</p>
        </section>
        {error ? <div className="rounded-lg border border-red-200 bg-red-50 px-3 py-2 text-sm font-bold text-red-600">{error}</div> : null}
        <section className="rounded-lg border border-slate-200 bg-white p-4">
          <div className="grid gap-3 md:grid-cols-2">
            <label className="grid gap-2 text-sm font-black text-slate-700">
              分类名称
              <input value={form.label} onChange={(event) => setForm((current) => ({ ...current, label: event.target.value }))} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold outline-none transition focus:border-primary focus:ring-2 focus:ring-primary/15" />
            </label>
            <label className="grid gap-2 text-sm font-black text-slate-700">
              父级分类
              <select value={form.parent_id ?? ""} onChange={(event) => setForm((current) => ({ ...current, parent_id: event.target.value ? Number(event.target.value) : null }))} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold outline-none transition focus:border-primary focus:ring-2 focus:ring-primary/15">
                <option value="">根分类</option>
                {parentOptions.map((option) => <option key={option.value} value={option.value} disabled={option.disabled}>{option.label}{option.disabled ? "（停用）" : ""}</option>)}
              </select>
            </label>
            <label className="grid gap-2 text-sm font-black text-slate-700">
              排序
              <input type="number" value={form.sort_order} onChange={(event) => setForm((current) => ({ ...current, sort_order: Number(event.target.value) }))} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold outline-none transition focus:border-primary focus:ring-2 focus:ring-primary/15" />
            </label>
            <label className="flex min-h-10 items-center gap-2 self-end rounded-lg border border-slate-200 px-3 text-sm font-black text-slate-700">
              <input type="checkbox" checked={form.is_enabled} onChange={(event) => setForm((current) => ({ ...current, is_enabled: event.target.checked }))} />
              启用分类
            </label>
          </div>
          <label className="mt-3 grid gap-2 text-sm font-black text-slate-700">
            备注
            <textarea value={form.remark} onChange={(event) => setForm((current) => ({ ...current, remark: event.target.value }))} className="min-h-[88px] rounded-lg border border-slate-200 px-3 py-2 text-sm font-bold leading-6 outline-none transition focus:border-primary focus:ring-2 focus:ring-primary/15" />
          </label>
        </section>
        <div className="sticky bottom-0 flex justify-between gap-2 border-t border-slate-200 bg-white/95 py-4 backdrop-blur">
          <div>{mode === "edit" ? <Button secondary disabled={saving} onClick={() => void remove()}>删除分类</Button> : null}</div>
          <div className="flex gap-2">
            <Button secondary disabled={saving} onClick={onClose}>关闭</Button>
            <Button disabled={saving} onClick={() => void save()}>{saving ? "保存中" : "保存"}</Button>
          </div>
        </div>
      </div>
    </Drawer>
  );
}

