function MasterDetailTabs({
  tabs,
  activeTab,
  onChange
}: {
  tabs: Array<{ key: string; label: string }>;
  activeTab: string;
  onChange: (tab: string) => void;
}) {
  return (
    <div className="flex gap-1 overflow-x-auto border-b border-border px-3 py-2">
      {tabs.map((tab) => (
        <button
          key={tab.key}
          type="button"
          onClick={() => onChange(tab.key)}
          className={`project-tab-button ${activeTab === tab.key ? "project-tab-button-active" : ""}`}
        >
          {tab.label}
        </button>
      ))}
    </div>
  );
}

type EmployeeFormState = {
  employee_name: string;
  department: string;
  position: string;
  role_code: string;
  manager_employee_code: string;
  status: string;
  phone: string;
};

type ProductFormState = {
  product_name: string;
  spec: string;
  unit: string;
  category: string;
  brand: string;
  barcode: string;
  reference_sale_price: string;
  reference_cost: string;
  status: string;
};

type SupplierFormState = {
  supplier_name: string;
  supplier_short_name: string;
  supplier_type: string;
  region: string;
  contact_name: string;
  contact_phone: string;
  address: string;
  status: string;
};

const masterStatusOptions = [
  { value: "active", label: "正常" },
  { value: "disabled", label: "停用" }
];

function employeeToForm(employee: MasterRow): EmployeeFormState {
  return {
    employee_name: displayValueForInput(employee.employee_name),
    department: displayValueForInput(employee.department),
    position: displayValueForInput(employee.position),
    role_code: displayValueForInput(employee.role_code),
    manager_employee_code: displayValueForInput(employee.manager_employee_code),
    status: displayValueForInput(employee.status) || "active",
    phone: displayValueForInput(employee.phone)
  };
}

function productToForm(product: MasterRow): ProductFormState {
  return {
    product_name: displayValueForInput(product.product_name),
    spec: displayValueForInput(product.spec),
    unit: displayValueForInput(product.unit),
    category: displayValueForInput(product.category),
    brand: displayValueForInput(product.brand),
    barcode: displayValueForInput(product.barcode),
    reference_sale_price: displayValueForInput(product.reference_sale_price),
    reference_cost: displayValueForInput(product.reference_cost),
    status: displayValueForInput(product.status) || "active"
  };
}

function supplierToForm(supplier: MasterRow): SupplierFormState {
  return {
    supplier_name: displayValueForInput(supplier.supplier_name),
    supplier_short_name: displayValueForInput(supplier.supplier_short_name),
    supplier_type: displayValueForInput(supplier.supplier_type),
    region: displayValueForInput(supplier.region),
    contact_name: displayValueForInput(supplier.contact_name),
    contact_phone: displayValueForInput(supplier.contact_phone),
    address: displayValueForInput(supplier.address),
    status: displayValueForInput(supplier.status) || "active"
  };
}

function employeeFormToPayload(form: EmployeeFormState): EmployeeUpdatePayload {
  return {
    employee_name: normalizeFormValue(form.employee_name),
    department: normalizeFormValue(form.department),
    position: normalizeFormValue(form.position),
    role_code: normalizeFormValue(form.role_code),
    manager_employee_code: normalizeFormValue(form.manager_employee_code),
    status: form.status,
    phone: normalizeFormValue(form.phone)
  };
}

function productFormToPayload(form: ProductFormState): ProductUpdatePayload {
  return {
    product_name: normalizeFormValue(form.product_name),
    spec: normalizeFormValue(form.spec),
    unit: normalizeFormValue(form.unit),
    category: normalizeFormValue(form.category),
    brand: normalizeFormValue(form.brand),
    barcode: normalizeFormValue(form.barcode),
    reference_sale_price: normalizeDecimalFormValue(form.reference_sale_price),
    reference_cost: normalizeDecimalFormValue(form.reference_cost),
    status: form.status
  };
}

function supplierFormToPayload(form: SupplierFormState): SupplierUpdatePayload {
  return {
    supplier_name: normalizeFormValue(form.supplier_name),
    supplier_short_name: normalizeFormValue(form.supplier_short_name),
    supplier_type: normalizeFormValue(form.supplier_type),
    region: normalizeFormValue(form.region),
    contact_name: normalizeFormValue(form.contact_name),
    contact_phone: normalizeFormValue(form.contact_phone),
    address: normalizeFormValue(form.address),
    status: form.status
  };
}

function normalizeDecimalFormValue(value: string) {
  const cleaned = value.trim();
  return cleaned || null;
}

function isMasterFormDirty<T extends object>(current: T, original: T) {
  return (Object.keys(current) as Array<keyof T>).some((key) => String(current[key] ?? "") !== String(original[key] ?? ""));
}

function MasterEditInput({
  label,
  value,
  onChange,
  required = false,
  type = "text"
}: {
  label: string;
  value: string;
  onChange: (value: string) => void;
  required?: boolean;
  type?: string;
}) {
  return (
    <label className="grid gap-2 text-sm font-black text-foreground">
      {label}{required ? <span className="text-red-500"> *</span> : null}
      <input
        value={value}
        type={type}
        onChange={(event) => onChange(event.target.value)}
        className="project-input"
        required={required}
      />
    </label>
  );
}

function MasterEditTextarea({
  label,
  value,
  onChange
}: {
  label: string;
  value: string;
  onChange: (value: string) => void;
}) {
  return (
    <label className="grid gap-2 text-sm font-black text-foreground">
      {label}
      <textarea
        value={value}
        onChange={(event) => onChange(event.target.value)}
        className="project-textarea"
      />
    </label>
  );
}

function MasterEditStatusSelect({ value, onChange }: { value: string; onChange: (value: string) => void }) {
  return (
    <label className="grid gap-2 text-sm font-black text-foreground">
      状态
      <select
        value={value}
        onChange={(event) => onChange(event.target.value)}
        className="project-input"
      >
        {masterStatusOptions.map((option) => <option key={option.value} value={option.value}>{option.label}</option>)}
      </select>
    </label>
  );
}

function MasterEditSection({ title, children }: { title: string; children: React.ReactNode }) {
  return (
    <section className="project-drawer-section">
      <h4 className="project-drawer-section-title">{title}</h4>
      <div className="mt-3 grid gap-3 md:grid-cols-2">{children}</div>
    </section>
  );
}

function MasterEditActions({ saving, onCancel }: { saving: boolean; onCancel: () => void }) {
  return (
    <div className="project-drawer-sticky-actions">
      <Button secondary disabled={saving} onClick={onCancel}>取消</Button>
      <Button type="submit" disabled={saving}>{saving ? "保存中" : "保存"}</Button>
    </div>
  );
}

function EmployeeEditForm({
  form,
  error,
  saving,
  onChange,
  onCancel,
  onSave
}: {
  form: EmployeeFormState;
  error: string;
  saving: boolean;
  onChange: (field: keyof EmployeeFormState, value: string) => void;
  onCancel: () => void;
  onSave: () => void;
}) {
  return (
    <form className="grid gap-4" noValidate onSubmit={(event) => { event.preventDefault(); onSave(); }}>
      {error ? <div className="rounded-lg border border-red-200 bg-red-50 px-3 py-2 text-sm font-bold text-red-600">{error}</div> : null}
      <MasterEditSection title="基础资料">
        <MasterEditInput label="员工姓名" value={form.employee_name} onChange={(value) => onChange("employee_name", value)} required />
        <MasterEditStatusSelect value={form.status} onChange={(value) => onChange("status", value)} />
        <MasterEditInput label="部门" value={form.department} onChange={(value) => onChange("department", value)} />
        <MasterEditInput label="岗位" value={form.position} onChange={(value) => onChange("position", value)} />
      </MasterEditSection>
      <MasterEditSection title="组织角色">
        <MasterEditInput label="角色" value={form.role_code} onChange={(value) => onChange("role_code", value)} />
        <MasterEditInput label="上级编号" value={form.manager_employee_code} onChange={(value) => onChange("manager_employee_code", value)} />
      </MasterEditSection>
      <MasterEditSection title="联系信息">
        <MasterEditInput label="联系电话" value={form.phone} onChange={(value) => onChange("phone", value)} />
      </MasterEditSection>
      <MasterEditActions saving={saving} onCancel={onCancel} />
    </form>
  );
}

