function buildEmployeeActivities(employee: MasterRow, extraActivity?: CustomerActivity | null): CustomerActivity[] {
  const activities: CustomerActivity[] = [
    {
      title: "导入更新",
      detail: `员工档案已进入主数据中心，部门为「${displayValue(employee.department)}」，角色为「${displayValue(employee.role_code)}」。`,
      time: formatDateTime(employee.created_at ?? employee.updated_at),
      tone: "ok"
    }
  ];
  if (extraActivity) activities.unshift(extraActivity);
  if (employee.phone) {
    activities.push({
      title: "联系信息",
      detail: `联系电话：${displayValue(employee.phone)}。`,
      time: formatDateTime(employee.updated_at ?? employee.created_at),
      tone: "neutral"
    });
  }
  if (String(employee.status ?? "active") !== "active") {
    activities.unshift({
      title: "状态提醒",
      detail: `当前员工状态为「${customerStatusLabels[String(employee.status)] ?? displayValue(employee.status)}」，账号和业务归属需要复核。`,
      time: formatDateTime(employee.updated_at ?? employee.created_at),
      tone: "warn"
    });
  }
  return activities;
}

