function formatMoney(value: unknown) {
  if (value === null || value === undefined || value === "") return "-";
  const numeric = Number(value);
  if (Number.isNaN(numeric)) return String(value);
  return numeric.toLocaleString("zh-CN", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

function formatNumber(value: unknown) {
  if (value === null || value === undefined || value === "") return "-";
  const numeric = Number(value);
  if (Number.isNaN(numeric)) return String(value);
  return numeric.toLocaleString("zh-CN", { maximumFractionDigits: 4 });
}

function formatPercent(value: unknown) {
  if (value === null || value === undefined || value === "") return "-";
  const numeric = Number(value);
  if (Number.isNaN(numeric)) return String(value);
  return `${numeric.toFixed(1)}%`;
}

function formatDate(value: unknown) {
  if (!value) return "-";
  const date = new Date(String(value));
  if (Number.isNaN(date.getTime())) return String(value);
  return date.toLocaleDateString("zh-CN");
}

function formatMargin(salePrice: unknown, cost: unknown) {
  const sale = Number(salePrice);
  const costValue = Number(cost);
  if (Number.isNaN(sale) || Number.isNaN(costValue) || sale === 0) return "-";
  const margin = ((sale - costValue) / sale) * 100;
  return `${margin.toFixed(1)}%`;
}

type CustomerDetailTab = "activity" | "profile" | "businessProfile" | "trades" | "crm" | "portrait" | "logs" | "tags";
const crmLinkedCustomerMasterTabs: readonly CustomerDetailTab[] = ["activity", "profile", "businessProfile", "logs"];

function CustomerDetailDrawer({
  customer,
  canEdit,
  permissions,
  jumpTools,
  onSaved,
  onClose,
  initialTab = "activity",
  initialBusinessProfileEdit = false,
  allowedTabs
}: {
  customer: MasterRow;
  canEdit: boolean;
  permissions: PermissionCode[];
  jumpTools: BusinessJumpTools;
  onSaved: (customer: MasterRow) => void;
  onClose: () => void;
  initialTab?: CustomerDetailTab;
  initialBusinessProfileEdit?: boolean;
  allowedTabs?: readonly CustomerDetailTab[];
}) {
  const safeInitialTab = allowedTabs && !allowedTabs.includes(initialTab) ? allowedTabs[0] ?? "activity" : initialTab;
  const [activeTab, setActiveTab] = useState<CustomerDetailTab>(safeInitialTab);
  const [currentCustomer, setCurrentCustomer] = useState(customer);
  const [mode, setMode] = useState<"view" | "edit">("view");
  const [form, setForm] = useState<CustomerFormState>(() => customerToForm(customer));
  const [saving, setSaving] = useState(false);
  const [formError, setFormError] = useState("");
  const [lastEditActivity, setLastEditActivity] = useState<CustomerActivity | null>(null);
  const [contextLoading, setContextLoading] = useState(false);
  const [contextError, setContextError] = useState("");
  const [salesContext, setSalesContext] = useState<SalesDetailPageData | null>(null);
  const [balanceContext, setBalanceContext] = useState<AccountBalancePageData | null>(null);
  const [businessProfileData, setBusinessProfileData] = useState<CustomerBusinessProfileResponse | null>(null);
  const [businessProfileHistory, setBusinessProfileHistory] = useState<CustomerBusinessProfileHistory[]>([]);
  const [businessProfileAudits, setBusinessProfileAudits] = useState<AuditLog[]>([]);
  const [customerAuditRows, setCustomerAuditRows] = useState<AuditLog[]>([]);
  const [businessProfileLoading, setBusinessProfileLoading] = useState(false);
  const [businessProfileError, setBusinessProfileError] = useState("");
  const [businessProfileTimelineLoading, setBusinessProfileTimelineLoading] = useState(false);
  const [businessProfileTimelineError, setBusinessProfileTimelineError] = useState("");
  const [customerAuditLoading, setCustomerAuditLoading] = useState(false);
  const [customerAuditError, setCustomerAuditError] = useState("");
  const [businessProfileEditOpen, setBusinessProfileEditOpen] = useState(initialBusinessProfileEdit);
  const [crmContextData, setCrmContextData] = useState<CustomerContextResult | null>(null);
  const [crmContextLoading, setCrmContextLoading] = useState(false);
  const [crmContextError, setCrmContextError] = useState("");
  const [selectedCrmProject, setSelectedCrmProject] = useState<CrmProjectRow | null>(null);
  const customerName = displayValue(currentCustomer.customer_name);
  const customerCode = displayValue(currentCustomer.customer_code);
  const incomingCustomerCode = displayValue(customer.customer_code);
  const lastCustomerCodeRef = useRef(incomingCustomerCode);
  const completeness = displayValue(currentCustomer.base_info_completeness);
  const status = String(currentCustomer.status ?? "active");
  const statusTone = status === "active" ? "ok" : status === "disabled" ? "warn" : "bad";
  const activities = buildCustomerActivities(currentCustomer, lastEditActivity);
  const customerLogRows = useMemo(() => {
    return [...customerAuditRows, ...businessProfileAudits].sort((left, right) => {
      const timeDiff = new Date(right.created_at).getTime() - new Date(left.created_at).getTime();
      return timeDiff || right.id - left.id;
    });
  }, [customerAuditRows, businessProfileAudits]);
  const dirty = mode === "edit" && isCustomerFormDirty(form, currentCustomer);
  const relatedActions = buildCustomerRelatedActions(currentCustomer, jumpTools);
  const canViewSalesContext = hasPermission(permissions, "sales_detail.view");
  const canViewBalanceContext = hasPermission(permissions, "account_balance.view");
  const canViewBusinessProfile = hasPermission(permissions, "customer_business.view");
  const canViewBusinessHistory = hasPermission(permissions, "customer_business.history");
  const canEditBusinessProfile = hasPermission(permissions, "customer_business.edit");
  const canViewAudit = hasPermission(permissions, "audit.view");
  const canViewPortrait = hasPermission(permissions, "customer_portrait.view");
  const canRefreshPortrait = hasPermission(permissions, "customer_portrait.refresh");
  const canViewCustomerTags = hasPermission(permissions, "customer.view");
  const canViewCrmContext = hasAnyPermission(permissions, ["crm_project.view", "crm_task.view", "crm_followup.view", "crm_issue.view", "approval.view"]);
  const crmStats = crmContextData?.crm.stats;
  const crmTaskTotal = crmStats?.task_total ?? crmContextData?.crm.tasks.length ?? 0;
  const crmOpenWorkItems = crmStats?.work_item_open ?? crmContextData?.crm.work_items.filter((item) => ["open", "processing"].includes(item.status)).length ?? 0;
  const allContextTabs: Array<ContextDrawerTab<CustomerDetailTab>> = [
    { key: "activity", label: "动态", count: activities.length },
    { key: "profile", label: "基础资料" },
    ...(canViewBusinessProfile ? [{ key: "businessProfile" as const, label: "经营资料", count: businessProfileData?.products.length ?? 0 }] : []),
    { key: "trades", label: "经营聚合", count: (salesContext?.total ?? 0) + (balanceContext?.total ?? 0) },
    ...(canViewCrmContext ? [{ key: "crm" as const, label: "CRM 关联", count: crmTaskTotal }] : []),
    ...(canViewPortrait ? [{ key: "portrait" as const, label: "客户画像" }] : []),
    { key: "logs", label: "日志" },
    ...(canViewCustomerTags ? [{ key: "tags" as const, label: "标签管理" }] : [])
  ];
  const contextTabs = allowedTabs ? allContextTabs.filter((tab) => allowedTabs.includes(tab.key)) : allContextTabs;
  const salesAmount = salesContext?.summary.amount_tax_total;
  const grossProfit = salesContext?.summary.gross_profit;
  const arBalance = balanceContext?.summary.ar_balance;
  const advanceReceiptBalance = balanceContext?.summary.advance_receipt_balance;
  const contextMetrics: ContextDrawerMetric[] = [
    { label: "资料状态", value: completeness, tone: completeness === "完整" ? "ok" : "warn", icon: ClipboardList },
    { label: "销售额", value: canViewSalesContext ? formatMoney(salesAmount) : "无权限", detail: canViewSalesContext ? `${salesContext?.summary.documents ?? 0} 单` : "销售明细不可见", icon: CircleDollarSign },
    { label: "应收余额", value: canViewBalanceContext ? formatMoney(arBalance) : "无权限", detail: canViewBalanceContext ? `预收 ${formatMoney(advanceReceiptBalance)}` : "往来对账不可见", tone: Number(arBalance ?? 0) > 0 ? "warn" : "neutral", icon: Building2 },
    { label: "毛利", value: canViewSalesContext ? formatMoney(grossProfit) : "无权限", detail: canViewSalesContext ? formatPercent(salesContext?.summary.gross_margin_rate) : "销售明细不可见", tone: Number(grossProfit ?? 0) < 0 ? "bad" : "neutral", icon: FileWarning },
    { label: "CRM 关联", value: canViewCrmContext ? crmTaskTotal : "无权限", detail: canViewCrmContext ? `待支持 ${crmOpenWorkItems} / 待审批 ${crmStats?.approval_pending ?? 0}` : "CRM 项目不可见", tone: crmOpenWorkItems > 0 || Number(crmStats?.approval_pending ?? 0) > 0 ? "warn" : "neutral", icon: BriefcaseBusiness }
  ];
  const sideContext = (
    <>
      <CustomerSideCard title="联系人" icon={UserRound}>
        <CustomerSideRow label="联系人" value={displayValue(currentCustomer.contact_name)} />
        <CustomerSideRow label="联系电话" value={displayValue(currentCustomer.contact_phone)} />
        <CustomerSideRow label="微信/对接方式" value={displayValue(currentCustomer.contact_channel)} />
        <CustomerSideRow label="客户群名称" value={displayValue(currentCustomer.customer_group_name)} />
      </CustomerSideCard>
      <CustomerSideCard title="关联职员" icon={UserCheck}>
        <CustomerEmployeeRow label="业务员（可多选）" value={currentCustomer.salesperson_name} />
        <CustomerSideRow label="开单员" value={displayValue(getCustomerBillingClerk(currentCustomer))} />
        <CustomerEmployeeRow label="历史业务员" value={currentCustomer.historical_salespersons} />
      </CustomerSideCard>
      <CustomerSideCard title="资料完整度" icon={ClipboardList}>
        <div className="flex items-center justify-between gap-3">
          <span className="text-sm font-bold text-slate-500">当前状态</span>
          <Badge tone={completeness === "完整" ? "ok" : "warn"}>{completeness}</Badge>
        </div>
        <CustomerSideRow label="最近更新" value={formatDateTime(currentCustomer.profile_updated_at ?? currentCustomer.updated_at)} />
        <CustomerSideRow label="更新来源" value={customerUpdateSourceLabel(currentCustomer.source)} />
      </CustomerSideCard>
      <CustomerSideCard title="地址与备注" icon={MapPin}>
        <CustomerSideRow label="详细地址" value={displayValue(currentCustomer.address)} multiline />
        <CustomerSideRow label="备注" value={displayValue(currentCustomer.base_remark)} multiline />
      </CustomerSideCard>
      {canViewCrmContext ? (
        <CustomerSideCard title="CRM 推进" icon={BriefcaseBusiness}>
          <CustomerSideRow label="关联项目" value={displayValue(crmStats?.project_total ?? crmContextData?.crm.projects.length ?? 0)} />
          <CustomerSideRow label="客户任务" value={displayValue(crmTaskTotal)} />
          <CustomerSideRow label="待支持" value={displayValue(crmOpenWorkItems)} />
          <CustomerSideRow label="最近跟进" value={formatDateTime(crmContextData?.crm.followups[0]?.created_at)} />
        </CustomerSideCard>
      ) : null}
      <RelatedDataCard title="关联数据" actions={relatedActions} />
    </>
  );

  const loadBusinessProfileTimeline = async (code = businessFilterValue(currentCustomer.customer_code)) => {
    setBusinessProfileTimelineError("");
    if (!code || !canViewBusinessProfile) {
      setBusinessProfileHistory([]);
      setBusinessProfileAudits([]);
      return;
    }
    setBusinessProfileTimelineLoading(true);
    try {
      const [historyResult, auditResult] = await Promise.allSettled([
        canViewBusinessHistory ? customerBusinessProfileHistory(code, { limit: 30, offset: 0 }) : Promise.resolve([]),
        canViewAudit ? auditLogs({ limit: 30, resource_type: "customer_business_profile", resource_id: code }) : Promise.resolve([])
      ]);
      setBusinessProfileHistory(historyResult.status === "fulfilled" ? historyResult.value : []);
      setBusinessProfileAudits(auditResult.status === "fulfilled" ? auditResult.value : []);
      if (historyResult.status === "rejected" || auditResult.status === "rejected") {
        setBusinessProfileTimelineError("部分历史或审计记录加载失败，可以稍后刷新。");
      }
    } finally {
      setBusinessProfileTimelineLoading(false);
    }
  };

  const loadCustomerAuditRows = async (code = businessFilterValue(currentCustomer.customer_code)) => {
    setCustomerAuditError("");
    if (!code || !canViewAudit) {
      setCustomerAuditRows([]);
      return;
    }
    setCustomerAuditLoading(true);
    try {
      const rows = await auditLogs({ limit: 30, resource_type: "customer", resource_id: code });
      setCustomerAuditRows(rows);
    } catch {
      setCustomerAuditRows([]);
      setCustomerAuditError("客户资料审计加载失败，可以稍后刷新。");
    } finally {
      setCustomerAuditLoading(false);
    }
  };

  const loadCustomerCrmContext = async (code = businessFilterValue(currentCustomer.customer_code)) => {
    setCrmContextError("");
    if (!code || !canViewCrmContext) {
      setCrmContextData(null);
      return;
    }
    setCrmContextLoading(true);
    try {
      const data = await customerContext(code);
      setCrmContextData(data);
    } catch (error) {
      setCrmContextError(error instanceof Error ? error.message : "客户 CRM 关联上下文加载失败。");
    } finally {
      setCrmContextLoading(false);
    }
  };

  useEffect(() => {
    const isSameCustomer = lastCustomerCodeRef.current === incomingCustomerCode;
    setCurrentCustomer(customer);
    setForm(customerToForm(customer));
    setFormError("");
    if (!isSameCustomer) {
      setMode("view");
      setLastEditActivity(null);
      setBusinessProfileData(null);
      setBusinessProfileHistory([]);
      setBusinessProfileAudits([]);
      setCustomerAuditRows([]);
      setBusinessProfileError("");
      setBusinessProfileTimelineError("");
      setCustomerAuditError("");
      setBusinessProfileEditOpen(initialBusinessProfileEdit);
      setCrmContextData(null);
      setCrmContextError("");
      setSelectedCrmProject(null);
      setActiveTab(safeInitialTab);
      lastCustomerCodeRef.current = incomingCustomerCode;
    }
  }, [customer, incomingCustomerCode, safeInitialTab, initialBusinessProfileEdit]);

  useEffect(() => {
    if (contextTabs.length > 0 && !contextTabs.some((tab) => tab.key === activeTab)) {
      setActiveTab(contextTabs[0].key);
    }
  }, [activeTab, contextTabs.map((tab) => tab.key).join("|")]);

  useEffect(() => {
    const code = businessFilterValue(customer.customer_code);
    let ignore = false;
    setCrmContextData(null);
    setCrmContextError("");
    if (!code || !canViewCrmContext) return;
    setCrmContextLoading(true);
    customerContext(code)
      .then((data) => {
        if (!ignore) setCrmContextData(data);
      })
      .catch((error) => {
        if (!ignore) setCrmContextError(error instanceof Error ? error.message : "客户 CRM 关联上下文加载失败。");
      })
      .finally(() => {
        if (!ignore) setCrmContextLoading(false);
      });
    return () => {
      ignore = true;
    };
  }, [customer.customer_code, canViewCrmContext]);

  useEffect(() => {
    const code = businessFilterValue(customer.customer_code);
    let ignore = false;
    setBusinessProfileData(null);
    setBusinessProfileError("");
    if (!code || !canViewBusinessProfile) return;
    setBusinessProfileLoading(true);
    customerBusinessProfile(code)
      .then((data) => {
        if (!ignore) setBusinessProfileData(data);
      })
      .catch((error) => {
        if (!ignore) setBusinessProfileError(error instanceof Error ? error.message : "客户经营资料加载失败。");
      })
      .finally(() => {
        if (!ignore) setBusinessProfileLoading(false);
      });
    return () => {
      ignore = true;
    };
  }, [customer.customer_code, canViewBusinessProfile]);

  useEffect(() => {
    const code = businessFilterValue(customer.customer_code);
    if (!code || !canViewBusinessProfile) {
      setBusinessProfileHistory([]);
      setBusinessProfileAudits([]);
      setBusinessProfileTimelineError("");
      return;
    }
    void loadBusinessProfileTimeline(code);
  }, [customer.customer_code, canViewBusinessProfile, canViewBusinessHistory, canViewAudit]);

  useEffect(() => {
    const code = businessFilterValue(customer.customer_code);
    if (!code || !canViewAudit) {
      setCustomerAuditRows([]);
      setCustomerAuditError("");
      return;
    }
    void loadCustomerAuditRows(code);
  }, [customer.customer_code, canViewAudit]);

  useEffect(() => {
    const customerCodeForQuery = businessFilterValue(customer.customer_code);
    const customerNameForQuery = businessFilterValue(customer.customer_name);
    let ignore = false;
    setSalesContext(null);
    setBalanceContext(null);
    setContextError("");
    if (!customerCodeForQuery && !customerNameForQuery) return;
    if (!canViewSalesContext && !canViewBalanceContext) return;
    setContextLoading(true);
    const requests: Array<Promise<void>> = [];
    if (canViewSalesContext) {
      requests.push(
        salesDetailsPage({
          customerCode: customerCodeForQuery,
          q: customerCodeForQuery ? undefined : customerNameForQuery,
          limit: 12,
          offset: 0
        }).then((page) => {
          if (!ignore) setSalesContext(page);
        })
      );
    }
    if (canViewBalanceContext) {
      requests.push(
        accountBalancesPage({
          settlementUnitCode: customerCodeForQuery,
          settlementUnitName: customerNameForQuery,
          limit: 12,
          offset: 0
        }).then((page) => {
          if (!ignore) setBalanceContext(page);
        })
      );
    }
    void Promise.allSettled(requests).then((results) => {
      if (ignore) return;
      const rejected = results.find((result) => result.status === "rejected");
      setContextError(rejected ? "部分经营数据加载失败，可以稍后重试或打开完整过程表查看。" : "");
      setContextLoading(false);
    });
    return () => {
      ignore = true;
    };
  }, [customer.customer_code, customer.customer_name, canViewSalesContext, canViewBalanceContext]);

  const requestClose = () => {
    if (selectedCrmProject) {
      setSelectedCrmProject(null);
      return;
    }
    if (businessProfileEditOpen) {
      setBusinessProfileEditOpen(false);
      return;
    }
    if (dirty && !window.confirm("当前客户资料尚未保存，确认关闭吗？")) return;
    onClose();
  };

  const cancelEdit = () => {
    if (dirty && !window.confirm("当前修改尚未保存，确认取消吗？")) return;
    setForm(customerToForm(currentCustomer));
    setFormError("");
    setMode("view");
  };

  const saveCustomer = async () => {
    if (!form.customer_name.trim()) {
      setFormError("客户名称不能为空。");
      return;
    }
    setSaving(true);
    setFormError("");
    try {
      const updatedCustomer = await updateCustomer(customerCode, customerFormToPayload(form));
      setCurrentCustomer(updatedCustomer);
      setForm(customerToForm(updatedCustomer));
      setMode("view");
      const savedAt = formatDateTime(updatedCustomer.updated_at ?? new Date().toISOString());
      setLastEditActivity({
        title: "手动编辑资料",
        detail: `客户资料已保存，最新资料完整度为「${displayValue(updatedCustomer.base_info_completeness)}」。`,
        time: savedAt,
        tone: "ok"
      });
      onSaved(updatedCustomer);
      setActiveTab("activity");
    } catch (error) {
      setFormError(error instanceof Error ? error.message : "保存客户资料失败。");
    } finally {
      setSaving(false);
    }
  };

  const saveBusinessProfile = async (payload: CustomerBusinessProfilePayload) => {
    const updated = await updateCustomerBusinessProfile(customerCode, payload);
    setBusinessProfileData(updated);
    await loadBusinessProfileTimeline(customerCode);
    setBusinessProfileEditOpen(false);
    setActiveTab("businessProfile");
    setLastEditActivity({
      title: "更新经营资料",
      detail: `客户经营资料已保存为版本 ${updated.profile?.version_no ?? "-"}，经营产品 ${updated.products.length} 项。`,
      time: formatDateTime(new Date().toISOString()),
      tone: "ok"
    });
  };

  return (
    <Drawer title={mode === "edit" ? "编辑客户资料" : "客户详情"} subtitle={`${customerName} · ${customerCode}`} onClose={requestClose}>
      {mode === "edit" ? (
        <div className="grid gap-4">
          <section className="project-drawer-overview">
            <div className="flex flex-col gap-3 xl:flex-row xl:items-start xl:justify-between">
              <div className="min-w-0">
                <p className="m-0 text-xs font-black uppercase tracking-[0.18em] text-primary">CUSTOMER EDIT</p>
                <h3 className="m-0 mt-1 truncate text-2xl font-black leading-tight text-foreground">{customerName}</h3>
                <p className="m-0 mt-2 text-sm font-medium text-muted-foreground">{customerCode} · 修改后会同步到当前客户档案。</p>
              </div>
              <Button secondary disabled={saving} onClick={cancelEdit}>退出编辑</Button>
            </div>
          </section>
          <CustomerEditForm
            form={form}
            error={formError}
            saving={saving}
            onChange={(field, value) => setForm((current) => ({ ...current, [field]: value }))}
            onCancel={cancelEdit}
            onSave={() => void saveCustomer()}
          />
        </div>
      ) : (
        <>
        <AttentionDetailNotice title="客户资料待补全" row={currentCustomer} />
        <ContextDrawerFrame
          eyebrow="CUSTOMER CONTEXT"
          title={customerName}
          subtitle={`${customerCode} · ${displayValue(currentCustomer.region)} · ${formatEmployeeNames(currentCustomer.salesperson_name)}`}
          badges={[
            { label: customerStatusLabels[status] ?? status, tone: statusTone },
            ...(customer.customer_type ? [{ label: displayValue(customer.customer_type), tone: "neutral" as const }] : [])
          ]}
          metrics={contextMetrics}
          tabs={contextTabs}
          activeTab={activeTab}
          onTabChange={setActiveTab}
          sidebar={sideContext}
          actions={(
            <>
              <button
                type="button"
                disabled={!canEdit}
                onClick={() => canEdit && setMode("edit")}
                className="inline-flex min-h-9 items-center justify-center rounded-lg border border-slate-200 bg-white px-3.5 text-sm font-bold text-slate-700 transition hover:bg-slate-50 disabled:cursor-not-allowed disabled:opacity-50"
                title={canEdit ? "编辑客户资料" : "当前账号暂无客户编辑权限"}
              >
                <Pencil className="mr-1.5 h-4 w-4" />
                编辑
              </button>
              <Button secondary onClick={requestClose}>关闭</Button>
            </>
          )}
        >
          {activeTab === "activity" ? <CustomerActivityTimeline activities={activities} /> : null}
          {activeTab === "profile" ? <CustomerProfilePanel customer={currentCustomer} /> : null}
          {activeTab === "businessProfile" ? (
            <CustomerBusinessProfilePanel
              data={businessProfileData}
              historyRows={businessProfileHistory}
              auditRows={businessProfileAudits}
              salesPage={salesContext}
              balancePage={balanceContext}
              loading={businessProfileLoading}
              error={businessProfileError}
              contextLoading={contextLoading}
              contextError={contextError}
              timelineLoading={businessProfileTimelineLoading}
              timelineError={businessProfileTimelineError}
              canEdit={canEditBusinessProfile}
              canViewSales={canViewSalesContext}
              canViewBalance={canViewBalanceContext}
              canViewAudit={canViewAudit}
              customer={currentCustomer}
              jumpTools={jumpTools}
              onEdit={() => setBusinessProfileEditOpen(true)}
              onRefreshTimeline={() => void loadBusinessProfileTimeline(customerCode)}
            />
          ) : null}
          {activeTab === "trades" ? (
            <CustomerBusinessContextPanel
              customer={currentCustomer}
              loading={contextLoading}
              error={contextError}
              canViewSales={canViewSalesContext}
              canViewBalance={canViewBalanceContext}
              salesPage={salesContext}
              balancePage={balanceContext}
              jumpTools={jumpTools}
            />
          ) : null}
          {activeTab === "crm" ? (
            <CustomerCrmContextPanel
              data={crmContextData}
              loading={crmContextLoading}
              error={crmContextError}
              permissions={permissions}
              onOpenProject={setSelectedCrmProject}
              onRefresh={() => void loadCustomerCrmContext(customerCode)}
            />
          ) : null}
          {activeTab === "portrait" && canViewPortrait ? (
            <CustomerPortraitPanel customer={currentCustomer} canRefresh={canRefreshPortrait} />
          ) : null}
          {activeTab === "logs" ? (
            <CustomerAuditLogPanel
              rows={customerLogRows}
              loading={businessProfileTimelineLoading || customerAuditLoading}
              error={[businessProfileTimelineError, customerAuditError].filter(Boolean).join("；")}
              canViewAudit={canViewAudit}
              onRefresh={() => {
                void loadBusinessProfileTimeline(customerCode);
                void loadCustomerAuditRows(customerCode);
              }}
            />
          ) : null}
          {activeTab === "tags" && canViewCustomerTags ? (
            <CustomerTaggingWorkspace
              permissions={permissions}
              initialCustomer={{ customer_code: customerCode, customer_name: customerName }}
              embedded
            />
          ) : null}
        </ContextDrawerFrame>
        </>
      )}
      <AnimatePresence>
        {businessProfileEditOpen ? (
          <CustomerBusinessProfileEditDrawer
            customer={currentCustomer}
            data={businessProfileData}
            onClose={() => setBusinessProfileEditOpen(false)}
            onSave={(payload) => saveBusinessProfile(payload)}
          />
        ) : null}
        {selectedCrmProject ? (
          <CrmProjectDetailDrawer
            key={`customer-crm-project-${selectedCrmProject.id}`}
            project={selectedCrmProject}
            permissions={permissions}
            onChanged={() => void loadCustomerCrmContext(customerCode)}
            onClose={() => setSelectedCrmProject(null)}
          />
        ) : null}
      </AnimatePresence>
    </Drawer>
  );
}

const customerTagColorOptions: Array<{ key: CustomerTagColorKey; label: string; hex: string }> = [
  { key: "blue", label: "蓝色", hex: "#2563eb" },
  { key: "green", label: "绿色", hex: "#16a34a" },
  { key: "cyan", label: "青色", hex: "#0891b2" },
  { key: "yellow", label: "黄色", hex: "#d97706" },
  { key: "red", label: "红色", hex: "#dc2626" },
  { key: "purple", label: "紫色", hex: "#7c3aed" },
  { key: "pink", label: "粉色", hex: "#db2777" },
  { key: "gray", label: "灰色", hex: "#64748b" }
];

function customerTagColor(colorKey?: string | null) {
  return customerTagColorOptions.find((item) => item.key === colorKey) ?? customerTagColorOptions[7];
}

function CustomerTagPill({ name, tag, onRemove }: { name: string; tag?: CustomerTagRow | null; onRemove?: () => void }) {
  const color = customerTagColor(tag?.color_key);
  return (
    <span
      className="inline-flex min-h-7 max-w-full items-center gap-1 rounded-md border px-2 py-1 text-xs font-black"
      style={{ color: color.hex, borderColor: `${color.hex}55`, backgroundColor: `${color.hex}12` }}
    >
      <span className="h-2 w-2 shrink-0 rounded-full" style={{ backgroundColor: color.hex }} />
      <span className="break-all">{name}</span>
      {onRemove ? (
        <button type="button" onClick={onRemove} className="ml-0.5 grid h-4 w-4 shrink-0 place-items-center rounded hover:bg-black/5" title={`移除 ${name}`}>
          <X className="h-3 w-3" />
        </button>
      ) : null}
    </span>
  );
}

function CustomerTagSelector({ value, onChange }: { value: string[]; onChange: (value: string[]) => void }) {
  const [catalog, setCatalog] = useState<CustomerTagRow[]>([]);
  const [search, setSearch] = useState("");
  const [newColor, setNewColor] = useState<CustomerTagColorKey>("blue");
  const [managing, setManaging] = useState(false);
  const [editingId, setEditingId] = useState<number | null>(null);
  const [editingName, setEditingName] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");

  const loadCatalog = async () => {
    try {
      setCatalog(await customerTags(true));
    } catch (loadError) {
      setError(loadError instanceof Error ? loadError.message : "客户标签加载失败");
    }
  };
  useEffect(() => { void loadCatalog(); }, []);

  const activeOptions = catalog.filter((item) => item.is_active);
  const selectedKeys = new Set(value.map((item) => item.trim().toLocaleLowerCase()));
  const normalizedSearch = search.trim().toLocaleLowerCase();
  const atLimit = value.length >= 20;
  const available = activeOptions.filter((item) => !selectedKeys.has(item.name.toLocaleLowerCase()) && (!normalizedSearch || item.name.toLocaleLowerCase().includes(normalizedSearch)));
  const exactMatch = catalog.some((item) => item.name.toLocaleLowerCase() === normalizedSearch);
  const catalogByName = new Map(catalog.map((item) => [item.name.toLocaleLowerCase(), item]));

  const createTag = async () => {
    const name = search.trim();
    if (!name || name.length > 30) {
      setError("标签名称需要 1-30 个字符。");
      return;
    }
    if (atLimit) {
      setError("每位客户最多选择 20 个标签。");
      return;
    }
    setBusy(true);
    setError("");
    try {
      const created = await createCustomerTag({ name, color_key: newColor });
      setCatalog((current) => [...current, created]);
      onChange([...value, created.name]);
      setSearch("");
    } catch (createError) {
      setError(createError instanceof Error ? createError.message : "新增标签失败");
    } finally {
      setBusy(false);
    }
  };

  const patchTag = async (tag: CustomerTagRow, patch: { name?: string; color_key?: CustomerTagColorKey; is_active?: boolean }) => {
    setBusy(true);
    setError("");
    try {
      const updated = await updateCustomerTag(tag.id, patch);
      setCatalog((current) => current.map((item) => item.id === tag.id ? updated : item));
      if (patch.name && patch.name !== tag.name) onChange(value.map((item) => item === tag.name ? updated.name : item));
      if (patch.is_active === false) onChange(value.filter((item) => item !== tag.name));
      setEditingId(null);
    } catch (updateError) {
      setError(updateError instanceof Error ? updateError.message : "维护标签失败");
    } finally {
      setBusy(false);
    }
  };

  return (
    <div className="rounded-lg border border-slate-200 bg-white p-3">
      <div className="flex flex-wrap gap-2">
        {value.length > 0 ? value.map((name) => (
          <CustomerTagPill key={name} name={name} tag={catalogByName.get(name.toLocaleLowerCase())} onRemove={() => onChange(value.filter((item) => item !== name))} />
        )) : <span className="text-xs font-bold text-slate-400">暂未选择标签</span>}
      </div>
      <div className="mt-3 flex flex-col gap-2 sm:flex-row">
        <label className="relative min-w-0 flex-1">
          <Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" />
          <input value={search} onChange={(event) => setSearch(event.target.value)} className="h-10 w-full rounded-lg border border-slate-200 pl-9 pr-3 text-sm font-bold outline-none focus:border-primary" placeholder="搜索或输入新标签" />
        </label>
        <button type="button" onClick={() => setManaging((current) => !current)} className="inline-flex h-10 items-center justify-center gap-1.5 rounded-lg border border-slate-200 px-3 text-sm font-black text-slate-600 hover:border-primary hover:text-primary">
          <Settings className="h-4 w-4" />管理标签
        </button>
      </div>
      {available.length > 0 ? (
        <div className="mt-2 flex max-h-36 flex-wrap gap-2 overflow-auto rounded-lg bg-slate-50 p-2">
          {available.map((tag) => <button type="button" key={tag.id} disabled={atLimit} onClick={() => { onChange([...value, tag.name]); setSearch(""); }} className="disabled:cursor-not-allowed disabled:opacity-45"><CustomerTagPill name={tag.name} tag={tag} /></button>)}
        </div>
      ) : null}
      {normalizedSearch && !exactMatch ? (
        <div className="mt-2 flex flex-wrap items-center gap-2 rounded-lg border border-dashed border-slate-300 p-2">
          <span className="text-xs font-bold text-slate-500">创建“{search.trim()}”</span>
          <div className="flex flex-wrap gap-1">
            {customerTagColorOptions.map((color) => (
              <button key={color.key} type="button" title={color.label} onClick={() => setNewColor(color.key)} className={`h-6 w-6 rounded-full border-2 ${newColor === color.key ? "border-slate-900" : "border-white"}`} style={{ backgroundColor: color.hex }} />
            ))}
          </div>
          <button type="button" disabled={busy || atLimit} onClick={() => void createTag()} className="inline-flex h-8 items-center gap-1 rounded-lg bg-primary px-3 text-xs font-black text-white disabled:opacity-50"><Plus className="h-3.5 w-3.5" />新增并选中</button>
        </div>
      ) : null}
      {managing ? (
        <div className="mt-3 border-t border-slate-200 pt-3">
          <div className="mb-2 flex items-center justify-between"><strong className="text-sm text-slate-900">共享标签库</strong><span className="text-xs font-bold text-slate-400">{catalog.length} 个</span></div>
          <div className="grid max-h-72 gap-2 overflow-auto">
            {catalog.map((tag) => (
              <div key={tag.id} className="flex flex-wrap items-center gap-2 rounded-lg bg-slate-50 px-2 py-2">
                {editingId === tag.id ? (
                  <input value={editingName} maxLength={30} onChange={(event) => setEditingName(event.target.value)} className="h-8 min-w-32 flex-1 rounded-md border border-slate-200 px-2 text-sm font-bold" />
                ) : <div className="min-w-32 flex-1"><CustomerTagPill name={tag.name} tag={tag} /></div>}
                <span className="text-xs font-bold text-slate-400">{tag.usage_count} 位客户</span>
                <select value={tag.color_key} disabled={busy} onChange={(event) => void patchTag(tag, { color_key: event.target.value as CustomerTagColorKey })} className="h-8 rounded-md border border-slate-200 bg-white px-2 text-xs font-bold">
                  {customerTagColorOptions.map((color) => <option key={color.key} value={color.key}>{color.label}</option>)}
                </select>
                {editingId === tag.id ? (
                  <button type="button" disabled={busy} onClick={() => void patchTag(tag, { name: editingName.trim() })} className="h-8 rounded-md bg-primary px-2 text-xs font-black text-white">保存</button>
                ) : (
                  <button type="button" title="重命名" onClick={() => { setEditingId(tag.id); setEditingName(tag.name); }} className="grid h-8 w-8 place-items-center rounded-md border border-slate-200 bg-white text-slate-600"><Pencil className="h-3.5 w-3.5" /></button>
                )}
                <button
                  type="button"
                  disabled={busy}
                  title={tag.is_active ? "禁用标签" : "重新启用"}
                  onClick={() => {
                    if (tag.is_active && !window.confirm(`禁用“${tag.name}”后，将从 ${tag.usage_count} 位客户中移除，确认继续？`)) return;
                    void patchTag(tag, { is_active: !tag.is_active });
                  }}
                  className={`grid h-8 w-8 place-items-center rounded-md border bg-white ${tag.is_active ? "border-red-200 text-red-600" : "border-emerald-200 text-emerald-600"}`}
                ><Power className="h-3.5 w-3.5" /></button>
              </div>
            ))}
          </div>
        </div>
      ) : null}
      {error ? <p className="m-0 mt-2 text-xs font-bold text-red-600">{error}</p> : null}
    </div>
  );
}

function CustomerTagFilterControl({ catalog, value, onChange }: { catalog: CustomerTagRow[]; value: string[]; onChange: (value: string[]) => void }) {
  return (
    <details className="relative">
      <summary className="flex min-h-10 cursor-pointer list-none items-center gap-2 rounded-lg border border-input bg-white px-3 text-xs font-black text-muted-foreground">
        <Tag className="h-4 w-4" />客户标签{value.length > 0 ? <span className="rounded bg-primary px-1.5 py-0.5 text-white">{value.length}</span> : null}
      </summary>
      <div className="absolute left-0 top-12 z-40 w-72 rounded-lg border border-slate-200 bg-white p-3 shadow-xl">
        <div className="flex max-h-64 flex-wrap gap-2 overflow-auto">
          {catalog.filter((tag) => tag.is_active).map((tag) => {
            const selected = value.includes(tag.name);
            return (
              <button type="button" key={tag.id} onClick={() => onChange(selected ? value.filter((name) => name !== tag.name) : [...value, tag.name])} className={selected ? "ring-2 ring-primary ring-offset-1 rounded-md" : "rounded-md"}>
                <CustomerTagPill name={tag.name} tag={tag} />
              </button>
            );
          })}
        </div>
        {value.length > 0 ? <button type="button" onClick={() => onChange([])} className="mt-3 inline-flex items-center gap-1 text-xs font-black text-primary"><X className="h-3.5 w-3.5" />清空标签筛选</button> : null}
      </div>
    </details>
  );
}

type CustomerFormState = {
  customer_name: string;
  customer_short_name: string;
  customer_type: string;
  status: string;
  region: string;
  address: string;
  contact_name: string;
  contact_phone: string;
  contact_channel: string;
  customer_group_name: string;
  customer_tags: string;
  salesperson_employee_code: string;
  salesperson_name: string;
  base_remark: string;
};

const customerStatusOptions = [
  { value: "active", label: "正常" },
  { value: "dormant", label: "休眠" },
  { value: "lost", label: "流失" },
  { value: "pending", label: "待确认" },
  { value: "closed", label: "停业" },
  { value: "disabled", label: "停用" }
];

function customerToForm(customer: MasterRow): CustomerFormState {
  return {
    customer_name: displayValueForInput(customer.customer_name),
    customer_short_name: displayValueForInput(customer.customer_short_name),
    customer_type: displayValueForInput(customer.customer_type),
    status: displayValueForInput(customer.status) || "active",
    region: displayValueForInput(customer.region),
    address: displayValueForInput(customer.address),
    contact_name: displayValueForInput(customer.contact_name),
    contact_phone: displayValueForInput(customer.contact_phone),
    contact_channel: displayValueForInput(customer.contact_channel),
    customer_group_name: displayValueForInput(customer.customer_group_name),
    customer_tags: Array.isArray(customer.customer_tags) ? customer.customer_tags.join("、") : displayValueForInput(customer.customer_tags),
    salesperson_employee_code: displayValueForInput(customer.salesperson_employee_code),
    salesperson_name: displayValueForInput(customer.salesperson_name),
    base_remark: displayValueForInput(customer.base_remark)
  };
}

function customerFormToPayload(form: CustomerFormState): CustomerUpdatePayload {
  return {
    customer_name: normalizeFormValue(form.customer_name),
    customer_short_name: normalizeFormValue(form.customer_short_name),
    customer_type: normalizeFormValue(form.customer_type),
    status: form.status,
    region: normalizeFormValue(form.region),
    address: normalizeFormValue(form.address),
    contact_name: normalizeFormValue(form.contact_name),
    contact_phone: normalizeFormValue(form.contact_phone),
    contact_channel: normalizeFormValue(form.contact_channel),
    customer_group_name: normalizeFormValue(form.customer_group_name),
    customer_tags: parseTagText(form.customer_tags),
    salesperson_employee_code: normalizeFormValue(form.salesperson_employee_code),
    salesperson_name: normalizeFormValue(form.salesperson_name),
    base_remark: normalizeFormValue(form.base_remark)
  };
}

function customerFormToChangedPayload(form: CustomerFormState, customer: MasterRow): CustomerUpdatePayload {
  const original = customerToForm(customer);
  const fullPayload = customerFormToPayload(form);
  const changedPayload: CustomerUpdatePayload = {};
  (Object.keys(form) as Array<keyof CustomerFormState>).forEach((field) => {
    if (form[field] === original[field]) return;
    (changedPayload as Record<string, unknown>)[field] = fullPayload[field as keyof CustomerUpdatePayload];
  });
  return changedPayload;
}

function isCustomerFormDirty(form: CustomerFormState, customer: MasterRow) {
  const original = customerToForm(customer);
  return Object.keys(form).some((key) => form[key as keyof CustomerFormState] !== original[key as keyof CustomerFormState]);
}

function normalizeFormValue(value: string) {
  const cleaned = value.trim();
  return cleaned || null;
}

function displayValueForInput(value: unknown) {
  if (value === null || value === undefined) return "";
  return String(value);
}

function CustomerEditForm({
  form,
  error,
  saving,
  onChange,
  onCancel,
  onSave,
  submitLabel = "保存",
  savingLabel = "保存中",
  cancelLabel = "取消"
}: {
  form: CustomerFormState;
  error: string;
  saving: boolean;
  onChange: (field: keyof CustomerFormState, value: string) => void;
  onCancel: () => void;
  onSave: () => void;
  submitLabel?: string;
  savingLabel?: string;
  cancelLabel?: string;
}) {
  const inputClass = "h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold outline-none transition focus:border-primary focus:ring-2 focus:ring-primary/15";
  const textareaClass = "min-h-[86px] rounded-lg border border-slate-200 px-3 py-2 text-sm font-bold leading-6 outline-none transition focus:border-primary focus:ring-2 focus:ring-primary/15";
  const field = (name: keyof CustomerFormState, label: string, required = false) => (
    <label className="grid gap-2 text-sm font-black text-slate-700">
      {label}{required ? <span className="text-red-500"> *</span> : null}
      <input value={form[name]} onChange={(event) => onChange(name, event.target.value)} className={inputClass} required={required} />
    </label>
  );
  return (
    <form
      className="grid gap-4"
      noValidate
      onSubmit={(event) => {
        event.preventDefault();
        onSave();
      }}
    >
      {error ? <div className="rounded-lg border border-red-200 bg-red-50 px-3 py-2 text-sm font-bold text-red-600">{error}</div> : null}
      <section className="rounded-lg border border-slate-200 bg-white p-4">
        <h4 className="m-0 text-sm font-black text-slate-950">基础身份</h4>
        <div className="mt-3 grid gap-3 md:grid-cols-2">
          {field("customer_name", "客户名称", true)}
          {field("customer_short_name", "客户简称")}
          {field("customer_type", "客户类型")}
          <label className="grid gap-2 text-sm font-black text-slate-700">
            客户状态
            <select value={form.status} onChange={(event) => onChange("status", event.target.value)} className={inputClass}>
              {customerStatusOptions.map((option) => <option key={option.value} value={option.value}>{option.label}</option>)}
            </select>
          </label>
          <label className="grid gap-2 text-sm font-black text-slate-700 md:col-span-2">
            客户标签
            <CustomerTagSelector
              value={parseTagText(form.customer_tags)}
              onChange={(tags) => onChange("customer_tags", tags.join("、"))}
            />
          </label>
        </div>
      </section>
      <section className="rounded-lg border border-slate-200 bg-white p-4">
        <h4 className="m-0 text-sm font-black text-slate-950">区域地址</h4>
        <div className="mt-3 grid gap-3">
          {field("region", "所属区域")}
          <label className="grid gap-2 text-sm font-black text-slate-700">
            详细地址
            <textarea value={form.address} onChange={(event) => onChange("address", event.target.value)} className={textareaClass} />
          </label>
        </div>
      </section>
      <section className="rounded-lg border border-slate-200 bg-white p-4">
        <h4 className="m-0 text-sm font-black text-slate-950">联系信息</h4>
        <div className="mt-3 grid gap-3 md:grid-cols-2">
          {field("contact_name", "联系人")}
          {field("contact_phone", "联系电话")}
          {field("contact_channel", "微信/对接方式")}
          {field("customer_group_name", "客户群名称")}
        </div>
      </section>
      <section className="rounded-lg border border-slate-200 bg-white p-4">
        <h4 className="m-0 text-sm font-black text-slate-950">关联职员</h4>
        <div className="mt-3 grid gap-3 md:grid-cols-2">
          {field("salesperson_name", "业务员（可多选，逗号分隔）")}
          {field("salesperson_employee_code", "业务员编号")}
        </div>
      </section>
      <section className="rounded-lg border border-slate-200 bg-white p-4">
        <h4 className="m-0 text-sm font-black text-slate-950">资料维护</h4>
        <div className="mt-3 grid gap-3">
          <label className="grid gap-2 text-sm font-black text-slate-700">
            备注
            <textarea value={form.base_remark} onChange={(event) => onChange("base_remark", event.target.value)} className={textareaClass} />
          </label>
        </div>
      </section>
      <div className="sticky bottom-0 -mx-4 flex justify-end gap-2 border-t border-slate-200 bg-white/95 px-4 py-3 backdrop-blur">
        <Button secondary disabled={saving} onClick={onCancel}>{cancelLabel}</Button>
        <Button type="submit" disabled={saving}>{saving ? savingLabel : submitLabel}</Button>
      </div>
    </form>
  );
}

function CustomerMeta({ label, value }: { label: string; value: string }) {
  return (
    <div className="min-w-0">
      <span className="block text-xs font-bold text-slate-400">{label}</span>
      <strong className="mt-1 block truncate text-sm text-slate-800">{value}</strong>
    </div>
  );
}

function CustomerSideCard({ title, icon: Icon, children }: { title: string; icon: LucideIcon; children: React.ReactNode }) {
  return (
    <section className="project-drawer-side-card">
      <div className="project-drawer-side-card-header">
        <span className="project-drawer-side-card-icon">
          <Icon className="h-4 w-4" />
        </span>
        <h4 className="project-drawer-side-card-title">{title}</h4>
      </div>
      <div className="grid gap-2">{children}</div>
    </section>
  );
}

function CustomerSideRow({ label, value, multiline = false }: { label: string; value: string; multiline?: boolean }) {
  return (
    <div className={`project-drawer-side-row ${multiline ? "" : "project-drawer-side-row-inline"}`}>
      <span className="project-drawer-field-label">{label}</span>
      <span className={`project-drawer-field-value ${multiline ? "project-drawer-field-value-block" : "project-drawer-field-value-inline"}`}>{value}</span>
    </div>
  );
}

type ContextTone = "ok" | "warn" | "bad" | "neutral";

function customerDimensionText(value: unknown, emptyLabel: string) {
  const rawText = Array.isArray(value)
    ? value.map((item) => String(item ?? "").trim()).filter(Boolean).join("、")
    : String(value ?? "").trim();
  return {
    text: rawText || emptyLabel,
    title: rawText || emptyLabel,
    isEmpty: !rawText
  };
}

function CustomerDimensionTag({
  label,
  value,
  emptyLabel,
  tone,
  compact = false
}: {
  label: string;
  value: unknown;
  emptyLabel: string;
  tone: "region" | "type";
  compact?: boolean;
}) {
  const normalized = customerDimensionText(value, emptyLabel);
  const toneClass = normalized.isEmpty
    ? "border-slate-200 bg-slate-50 text-slate-400"
    : tone === "region"
      ? "border-cyan-100 bg-cyan-50 text-cyan-700"
      : "border-blue-100 bg-blue-50 text-blue-700";
  return (
    <span
      className={`inline-flex max-w-full items-center rounded-md border px-2 font-black leading-none ${compact ? "min-h-6 text-[11px]" : "min-h-7 text-xs"} ${toneClass}`}
      title={`${label}：${normalized.title}`}
    >
      <span className="shrink-0 opacity-70">{label}：</span>
      <span className={`min-w-0 truncate ${compact ? "max-w-[150px]" : "max-w-[260px]"}`}>{normalized.text}</span>
    </span>
  );
}

function CustomerDimensionTags({
  region,
  customerType,
  compact = false,
  className = "",
  showRegion = true,
  showType = true
}: {
  region?: unknown;
  customerType?: unknown;
  compact?: boolean;
  className?: string;
  showRegion?: boolean;
  showType?: boolean;
}) {
  return (
    <div className={`flex min-w-0 max-w-full flex-wrap items-center gap-1.5 ${className}`}>
      {showRegion ? <CustomerDimensionTag label="区域" value={region} emptyLabel="区域未填" tone="region" compact={compact} /> : null}
      {showType ? <CustomerDimensionTag label="类型" value={customerType} emptyLabel="类型未填" tone="type" compact={compact} /> : null}
    </div>
  );
}

function CustomerDimensionSummaryCard({
  label,
  detail,
  icon: Icon,
  children
}: {
  label: string;
  detail: React.ReactNode;
  icon: LucideIcon;
  children: React.ReactNode;
}) {
  return (
    <section className="min-w-0 rounded-lg border border-border bg-card p-3 shadow-card">
      <div className="flex items-center gap-2">
        <span className="grid h-8 w-8 shrink-0 place-items-center rounded-md bg-muted text-primary ring-1 ring-border">
          <Icon className="h-4 w-4" />
        </span>
        <span className="truncate text-xs font-black text-muted-foreground">{label}</span>
      </div>
      <div className="mt-2 min-w-0">{children}</div>
      <span className="mt-2 block truncate text-xs font-bold text-muted-foreground">{detail}</span>
    </section>
  );
}

function CustomerSideTagRow({ label, children }: { label: string; children: React.ReactNode }) {
  return (
    <div className="project-drawer-side-row">
      <span className="project-drawer-field-label">{label}</span>
      <div className="min-w-0">{children}</div>
    </div>
  );
}

type ContextDrawerMetric = {
  label: string;
  value: React.ReactNode;
  detail?: React.ReactNode;
  tone?: ContextTone;
  icon?: LucideIcon;
};
type ContextDrawerTab<T extends string = string> = {
  key: T;
  label: string;
  count?: number;
};
type ContextInlineColumn<T> = {
  key: keyof T | string;
  label: string;
  render?: (row: T) => React.ReactNode;
};

function ContextDrawerFrame<T extends string>({
  eyebrow,
  title,
  subtitle,
  badges = [],
  metrics,
  tabs,
  activeTab,
  onTabChange,
  actions,
  sidebar,
  children
}: {
  eyebrow: string;
  title: string;
  subtitle: string;
  badges?: Array<{ label: string; tone?: ContextTone }>;
  metrics: ContextDrawerMetric[];
  tabs: Array<ContextDrawerTab<T>>;
  activeTab: T;
  onTabChange: (tab: T) => void;
  actions?: React.ReactNode;
  sidebar?: React.ReactNode;
  children: React.ReactNode;
}) {
  return (
    <div className="grid gap-4">
      <section className="project-drawer-overview">
        <div className="project-drawer-responsive-row">
          <div className="min-w-0">
            <p className="m-0 text-xs font-black uppercase tracking-[0.18em] text-primary">{eyebrow}</p>
            <div className="mt-1 flex min-w-0 flex-wrap items-center gap-2">
              <h3 className="m-0 max-w-full truncate text-2xl font-black leading-tight text-foreground">{title}</h3>
              {badges.map((badge) => <Badge key={`${badge.label}-${badge.tone ?? "neutral"}`} tone={badge.tone ?? "neutral"}>{badge.label}</Badge>)}
            </div>
            <p className="m-0 mt-2 line-clamp-2 text-sm font-medium leading-6 text-muted-foreground">{subtitle}</p>
          </div>
          {actions ? <div className="flex shrink-0 flex-wrap gap-2">{actions}</div> : null}
        </div>
        <ContextMetricGrid metrics={metrics} />
      </section>

      <div className="project-drawer-split">
        <section className="project-drawer-content-section">
          <ContextTabBar tabs={tabs} activeTab={activeTab} onTabChange={onTabChange} />
          <div className="p-4">{children}</div>
        </section>
        {sidebar ? <aside className="project-drawer-sidebar">{sidebar}</aside> : null}
      </div>
    </div>
  );
}

function ContextMetricGrid({ metrics }: { metrics: ContextDrawerMetric[] }) {
  return (
    <div className="project-drawer-metric-grid">
      {metrics.map((metric) => {
        const Icon = metric.icon;
        const toneClass =
          metric.tone === "ok"
            ? "border-emerald-200 bg-emerald-50 text-emerald-700"
            : metric.tone === "warn"
              ? "border-amber-200 bg-amber-50 text-amber-700"
              : metric.tone === "bad"
                ? "border-red-200 bg-red-50 text-red-700"
                : "border-slate-200 bg-slate-50 text-slate-700";
        return (
          <div key={metric.label} className={`min-w-0 rounded-lg border px-3 py-3 ${toneClass}`}>
            <div className="flex items-center gap-2">
              {Icon ? <Icon className="h-4 w-4 shrink-0" /> : null}
              <span className="truncate text-xs font-black text-muted-foreground">{metric.label}</span>
            </div>
            <strong className="mt-2 block truncate text-lg font-black text-foreground">{metric.value}</strong>
            {metric.detail ? <span className="mt-1 block truncate text-xs font-bold text-muted-foreground">{metric.detail}</span> : null}
          </div>
        );
      })}
    </div>
  );
}

function ContextTabBar<T extends string>({
  tabs,
  activeTab,
  onTabChange
}: {
  tabs: Array<ContextDrawerTab<T>>;
  activeTab: T;
  onTabChange: (tab: T) => void;
}) {
  return (
    <div className="flex gap-1 overflow-x-auto border-b border-border bg-muted/50 px-3 py-2" role="tablist" aria-label="详情分区">
      {tabs.map((tab) => (
        <button
          key={tab.key}
          type="button"
          role="tab"
          aria-selected={activeTab === tab.key}
          onClick={() => onTabChange(tab.key)}
          className={`project-tab-button ${activeTab === tab.key ? "project-tab-button-active" : ""}`}
        >
          {tab.label}
          {typeof tab.count === "number" ? <span className="ml-1 text-xs opacity-70">({tab.count})</span> : null}
        </button>
      ))}
    </div>
  );
}

function ContextInlineTable<T extends Record<string, unknown>>({
  title,
  description,
  rows,
  columns,
  emptyMessage = "暂无关联数据",
  loading = false,
  totalCount
}: {
  title: string;
  description?: string;
  rows: T[];
  columns: Array<ContextInlineColumn<T>>;
  emptyMessage?: string;
  loading?: boolean;
  totalCount?: number;
}) {
  const visibleCount = rows.length;
  const countLabel = typeof totalCount === "number" ? `${visibleCount}/${totalCount} 条` : `${visibleCount} 条`;
  return (
    <section className="rounded-lg border border-border bg-card shadow-card">
      <div className="flex items-start justify-between gap-3 border-b border-border px-4 py-3">
        <div className="min-w-0">
          <h4 className="m-0 truncate text-sm font-black text-foreground">{title}</h4>
          {description ? <p className="m-0 mt-1 text-xs font-bold text-muted-foreground">{description}</p> : null}
        </div>
        <Badge tone={loading ? "warn" : "neutral"}>{loading ? "加载中" : countLabel}</Badge>
      </div>
      <div className="overflow-auto">
        <UiTable className="min-w-[560px]">
          <TableHeader>
            <TableRow>{columns.map((column) => <TableHead key={String(column.key)}>{column.label}</TableHead>)}</TableRow>
          </TableHeader>
          <TableBody>
            {loading ? (
              Array.from({ length: 3 }).map((_, rowIndex) => (
                <TableRow key={`context-loading-${rowIndex}`}>
                  {columns.map((column, columnIndex) => (
                    <TableCell key={`${String(column.key)}-${columnIndex}`}>
                      <span className="block h-4 w-full max-w-[120px] animate-pulse rounded bg-muted" />
                    </TableCell>
                  ))}
                </TableRow>
              ))
            ) : rows.length > 0 ? rows.map((row, index) => (
              <TableRow key={String(row.id ?? index)}>
                {columns.map((column) => (
                  <TableCell key={String(column.key)}>{column.render ? column.render(row) : displayValue(row[column.key])}</TableCell>
                ))}
              </TableRow>
            )) : (
              <TableRow>
                <TableCell colSpan={columns.length} className="py-8">
                  <div className="project-empty-panel mx-auto max-w-md px-5 py-6">
                    <span className="project-empty-icon">
                      <Search className="h-4 w-4" />
                    </span>
                    <strong className="mt-3 block text-sm font-black text-foreground">{emptyMessage}</strong>
                    <p className="m-0 mt-1 text-xs font-bold leading-5 text-muted-foreground">当前上下文没有命中可展示记录，切换标签或返回列表可继续排查。</p>
                  </div>
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </UiTable>
      </div>
    </section>
  );
}

type RelatedDataAction = {
  label: string;
  detail: string;
  icon: LucideIcon;
  disabled?: boolean;
  onClick: () => void;
};

function RelatedDataCard({ title, actions }: { title: string; actions: RelatedDataAction[] }) {
  return (
    <CustomerSideCard title={title} icon={Database}>
      <div className="grid gap-2">
        {actions.map((action) => {
          const Icon = action.icon;
          return (
            <button
              key={action.label}
              type="button"
              disabled={action.disabled}
              onClick={action.onClick}
              className="group flex min-h-[58px] items-center gap-3 rounded-lg border border-slate-200 bg-slate-50 px-3 py-2 text-left transition hover:border-primary/30 hover:bg-primary-soft disabled:cursor-not-allowed disabled:opacity-45"
            >
              <span className="grid h-9 w-9 shrink-0 place-items-center rounded-md bg-white text-slate-500 shadow-sm group-hover:text-primary">
                <Icon className="h-4 w-4" />
              </span>
              <span className="min-w-0 flex-1">
                <span className="block truncate text-sm font-black text-slate-900">{action.label}</span>
                <span className="mt-0.5 block truncate text-xs font-bold text-slate-500">{action.detail}</span>
              </span>
              <ChevronRight className="h-4 w-4 shrink-0 text-slate-300 group-hover:text-primary" />
            </button>
          );
        })}
      </div>
    </CustomerSideCard>
  );
}

function businessFilterValue(value: unknown) {
  const text = displayValue(value);
  return text === "-" ? undefined : text;
}

function buildCustomerRelatedActions(customer: MasterRow, jumpTools: BusinessJumpTools): RelatedDataAction[] {
  const customerCode = businessFilterValue(customer.customer_code);
  const customerName = businessFilterValue(customer.customer_name);
  const salesperson = businessFilterValue(customer.salesperson_name);
  return [
    {
      label: "查看关联客户底盘",
      detail: customerCode ? `打开 ${customerCode} 的项目、任务和跟进上下文` : "按客户名称进入 CRM 关联客户底盘",
      icon: BriefcaseBusiness,
      disabled: !customerCode && !customerName,
      onClick: () => jumpTools.openCrmCustomer({ code: customerCode, name: customerName })
    },
    {
      label: "查看销售明细",
      detail: customerCode ? `按客户 ${customerCode} 聚焦` : "按客户名称聚焦",
      icon: CircleDollarSign,
      disabled: !customerCode && !customerName,
      onClick: () => jumpTools.openProcessPage("sales", { customer_code: customerCode, q: customerCode ? undefined : customerName })
    },
    {
      label: "查看往来对账",
      detail: "应收、预收和往来余额",
      icon: Building2,
      disabled: !customerCode && !customerName,
      onClick: () => jumpTools.openProcessPage("account-balance", { settlement_unit_code: customerCode, settlement_unit_name: customerName })
    },
    {
      label: "查看业务员销售",
      detail: salesperson ? `业务员 ${salesperson}` : "当前客户未绑定业务员",
      icon: UserCheck,
      disabled: !salesperson,
      onClick: () => jumpTools.openProcessPage("sales", { employee_name: salesperson })
    }
  ];
}

function buildProductRelatedActions(product: MasterRow, jumpTools: BusinessJumpTools): RelatedDataAction[] {
  const productCode = businessFilterValue(product.product_code);
  const productName = businessFilterValue(product.product_name);
  return [
    {
      label: "查看销售明细",
      detail: productCode ? `按商品 ${productCode} 聚焦` : "按商品名称聚焦",
      icon: CircleDollarSign,
      disabled: !productCode && !productName,
      onClick: () => jumpTools.openProcessPage("sales", { product_code: productCode, q: productCode ? undefined : productName })
    },
    {
      label: "查看采购明细",
      detail: "采购数量、金额和供应商",
      icon: ClipboardList,
      disabled: !productCode && !productName,
      onClick: () => jumpTools.openProcessPage("purchase", { product_code: productCode, q: productCode ? undefined : productName })
    },
    {
      label: "查看库存快照",
      detail: "库存数量、成本和锁定",
      icon: Package,
      disabled: !productCode && !productName,
      onClick: () => jumpTools.openProcessPage("inventory", { product_code: productCode, q: productCode ? undefined : productName })
    }
  ];
}

function buildSupplierRelatedActions(supplier: MasterRow, jumpTools: BusinessJumpTools): RelatedDataAction[] {
  const supplierCode = businessFilterValue(supplier.supplier_code);
  const supplierName = businessFilterValue(supplier.supplier_name);
  return [
    {
      label: "查看采购明细",
      detail: supplierCode ? `按供应商 ${supplierCode} 聚焦` : "按供应商名称聚焦",
      icon: ClipboardList,
      disabled: !supplierCode && !supplierName,
      onClick: () => jumpTools.openProcessPage("purchase", { supplier_code: supplierCode, q: supplierCode ? undefined : supplierName })
    },
    {
      label: "查看往来对账",
      detail: "应付、预付和往来余额",
      icon: Building2,
      disabled: !supplierCode && !supplierName,
      onClick: () => jumpTools.openProcessPage("account-balance", { settlement_unit_code: supplierCode, settlement_unit_name: supplierName })
    },
    {
      label: "查看库存供货",
      detail: "按默认供货商筛选库存",
      icon: Package,
      disabled: !supplierName,
      onClick: () => jumpTools.openProcessPage("inventory", { default_supplier: supplierName })
    }
  ];
}

function buildEmployeeRelatedActions(employee: MasterRow, jumpTools: BusinessJumpTools): RelatedDataAction[] {
  const employeeName = businessFilterValue(employee.employee_name);
  return [
    {
      label: "查看销售明细",
      detail: employeeName ? `业务员 ${employeeName}` : "员工姓名为空",
      icon: CircleDollarSign,
      disabled: !employeeName,
      onClick: () => jumpTools.openProcessPage("sales", { employee_name: employeeName })
    },
    {
      label: "查看采购明细",
      detail: employeeName ? `采购员 ${employeeName}` : "员工姓名为空",
      icon: ClipboardList,
      disabled: !employeeName,
      onClick: () => jumpTools.openProcessPage("purchase", { employee_name: employeeName })
    },
    {
      label: "查看名下客户",
      detail: "按员工姓名搜索客户档案",
      icon: UsersRound,
      disabled: !employeeName,
      onClick: () => jumpTools.openMasterRecord("customers", { name: employeeName, open: "" })
    }
  ];
}

function buildSalesDetailRelatedActions(row: SalesDetailRow, jumpTools: BusinessJumpTools): RelatedDataAction[] {
  const customerCode = businessFilterValue(row.customer_code);
  const productCode = businessFilterValue(row.product_code);
  const employeeName = businessFilterValue(row.employee_name);
  const settlementCode = businessFilterValue(row.settlement_unit_code ?? row.customer_code);
  const settlementName = businessFilterValue(row.settlement_unit_name ?? row.customer_name);
  return [
    {
      label: "打开客户档案",
      detail: customerCode ? `客户 ${customerCode}` : "按客户名称定位",
      icon: Building2,
      disabled: !customerCode && !businessFilterValue(row.customer_name),
      onClick: () => jumpTools.openMasterRecord("customers", { code: row.customer_code, name: row.customer_name })
    },
    {
      label: "打开商品档案",
      detail: productCode ? `商品 ${productCode}` : "按商品名称定位",
      icon: Package,
      disabled: !productCode && !businessFilterValue(row.product_name),
      onClick: () => jumpTools.openMasterRecord("products", { code: row.product_code, name: row.product_name })
    },
    {
      label: "打开员工档案",
      detail: employeeName ? `业务员 ${employeeName}` : "业务员为空",
      icon: UserCheck,
      disabled: !employeeName,
      onClick: () => jumpTools.openMasterRecord("employees", { code: row.employee_code, name: row.employee_name })
    },
    {
      label: "查看结算往来",
      detail: settlementCode ? `结算单位 ${settlementCode}` : "按结算单位名称聚焦",
      icon: CircleDollarSign,
      disabled: !settlementCode && !settlementName,
      onClick: () => jumpTools.openProcessPage("account-balance", { settlement_unit_code: settlementCode, settlement_unit_name: settlementName })
    }
  ];
}

function buildInventorySnapshotRelatedActions(row: InventorySnapshotRow, jumpTools: BusinessJumpTools): RelatedDataAction[] {
  const productCode = businessFilterValue(row.product_code);
  const productName = businessFilterValue(row.product_name);
  const supplierName = businessFilterValue(row.default_supplier);
  return [
    {
      label: "打开商品档案",
      detail: productCode ? `商品 ${productCode}` : "按商品名称定位",
      icon: Package,
      disabled: !productCode && !productName,
      onClick: () => jumpTools.openMasterRecord("products", { code: row.product_code, name: row.product_name })
    },
    {
      label: "打开供应商档案",
      detail: supplierName ? `默认供货商 ${supplierName}` : "默认供货商为空",
      icon: Building2,
      disabled: !supplierName,
      onClick: () => jumpTools.openMasterRecord("suppliers", { name: row.default_supplier })
    },
    {
      label: "查看销售明细",
      detail: "按该商品聚焦销售",
      icon: CircleDollarSign,
      disabled: !productCode && !productName,
      onClick: () => jumpTools.openProcessPage("sales", { product_code: productCode, q: productCode ? undefined : productName })
    },
    {
      label: "查看采购明细",
      detail: "按该商品聚焦采购",
      icon: ClipboardList,
      disabled: !productCode && !productName,
      onClick: () => jumpTools.openProcessPage("purchase", { product_code: productCode, q: productCode ? undefined : productName })
    }
  ];
}

function buildPurchaseDetailRelatedActions(row: PurchaseDetailRow, jumpTools: BusinessJumpTools): RelatedDataAction[] {
  const supplierCode = businessFilterValue(row.supplier_code);
  const productCode = businessFilterValue(row.product_code);
  const employeeName = businessFilterValue(row.employee_name);
  const settlementCode = businessFilterValue(row.settlement_unit_code ?? row.supplier_code);
  const settlementName = businessFilterValue(row.settlement_unit_name ?? row.supplier_name);
  return [
    {
      label: "打开供应商档案",
      detail: supplierCode ? `供应商 ${supplierCode}` : "按供应商名称定位",
      icon: Building2,
      disabled: !supplierCode && !businessFilterValue(row.supplier_name),
      onClick: () => jumpTools.openMasterRecord("suppliers", { code: row.supplier_code, name: row.supplier_name })
    },
    {
      label: "打开商品档案",
      detail: productCode ? `商品 ${productCode}` : "按商品名称定位",
      icon: Package,
      disabled: !productCode && !businessFilterValue(row.product_name),
      onClick: () => jumpTools.openMasterRecord("products", { code: row.product_code, name: row.product_name })
    },
    {
      label: "打开员工档案",
      detail: employeeName ? `采购员 ${employeeName}` : "采购员为空",
      icon: UserCheck,
      disabled: !employeeName,
      onClick: () => jumpTools.openMasterRecord("employees", { code: row.employee_code, name: row.employee_name })
    },
    {
      label: "查看结算往来",
      detail: settlementCode ? `结算单位 ${settlementCode}` : "按结算单位名称聚焦",
      icon: CircleDollarSign,
      disabled: !settlementCode && !settlementName,
      onClick: () => jumpTools.openProcessPage("account-balance", { settlement_unit_code: settlementCode, settlement_unit_name: settlementName })
    }
  ];
}

function buildAccountBalanceRelatedActions(row: AccountBalanceRow, jumpTools: BusinessJumpTools): RelatedDataAction[] {
  const unitCode = businessFilterValue(row.settlement_unit_code);
  const unitName = businessFilterValue(row.settlement_unit_name);
  const kindHint = inferSettlementUnitKind(row);
  const masterLabel = kindHint === "supplier" ? "打开供应商档案" : kindHint === "customer" ? "打开客户档案" : "聚焦结算单位";
  return [
    {
      label: masterLabel,
      detail: unitCode ? `结算单位 ${unitCode}` : "按结算单位名称定位",
      icon: Building2,
      disabled: !unitCode && !unitName,
      onClick: () => jumpTools.openSettlementUnit({
        code: unitCode,
        name: unitName,
        kindHint,
        arBalance: row.ar_balance,
        apBalance: row.ap_balance,
        advanceReceiptBalance: row.advance_receipt_balance,
        advancePaymentBalance: row.advance_payment_balance
      })
    },
    {
      label: "查看销售明细",
      detail: "按结算单位名称搜索销售",
      icon: CircleDollarSign,
      disabled: !unitName,
      onClick: () => jumpTools.openProcessPage("sales", { q: unitName })
    },
    {
      label: "查看采购明细",
      detail: "按结算单位名称搜索采购",
      icon: ClipboardList,
      disabled: !unitName,
      onClick: () => jumpTools.openProcessPage("purchase", { q: unitName })
    }
  ];
}

function CustomerEmployeeRow({ label, value }: { label: string; value: unknown }) {
  const employees = splitEmployeeNames(value);
  return (
    <div className="grid gap-1">
      <span className="text-xs font-bold text-slate-400">{label}</span>
      {employees.length > 0 ? (
        <div className="flex flex-wrap gap-1.5">
          {employees.map((employee) => (
            <span key={employee} className="inline-flex max-w-full items-center rounded-md bg-primary-soft px-2 py-1 text-xs font-black text-primary">
              <span className="truncate">{employee}</span>
            </span>
          ))}
        </div>
      ) : (
        <span className="text-right text-sm font-bold text-slate-700">-</span>
      )}
    </div>
  );
}

function CustomerActivityTimeline({ activities }: { activities: CustomerActivity[] }) {
  if (activities.length === 0) return <CustomerEmptyPanel title="暂无动态" description="当前客户还没有可展示的资料动态。" />;
  return (
    <div className="relative grid gap-0 pl-3">
      {activities.map((activity, index) => (
        <div key={`${activity.title}-${index}`} className="relative grid grid-cols-[24px_minmax(0,1fr)] gap-3 pb-5 last:pb-0">
          <div className="relative flex justify-center">
            <span className={`mt-1 h-2.5 w-2.5 rounded-full ${activity.tone === "warn" ? "bg-amber-500" : activity.tone === "bad" ? "bg-red-500" : "bg-primary"}`} />
            {index < activities.length - 1 ? <span className="absolute left-1/2 top-5 h-[calc(100%-0.5rem)] w-px -translate-x-1/2 bg-slate-200" /> : null}
          </div>
          <article className="min-w-0 rounded-lg border border-slate-200 bg-slate-50/70 px-4 py-3">
            <div className="flex flex-wrap items-center justify-between gap-2">
              <h4 className="m-0 text-sm font-black text-slate-950">{activity.title}</h4>
              <span className="text-xs font-bold text-slate-400">{activity.time}</span>
            </div>
            <p className="m-0 mt-2 text-sm leading-6 text-slate-600">{activity.detail}</p>
          </article>
        </div>
      ))}
    </div>
  );
}

function CustomerProfilePanel({ customer }: { customer: MasterRow }) {
  const groups = [
    {
      title: "基础身份",
      icon: Tag,
      fields: [
        ["客户编号", customer.customer_code],
        ["客户名称", customer.customer_name],
        ["客户简称", customer.customer_short_name],
        ["客户类型", customer.customer_type],
        ["客户状态", customerStatusLabels[String(customer.status ?? "active")] ?? customer.status]
      ]
    },
    {
      title: "区域地址",
      icon: MapPin,
      fields: [
        ["所属区域", customer.region],
        ["详细地址", customer.address]
      ]
    },
    {
      title: "联系信息",
      icon: UserRound,
      fields: [
        ["联系人", customer.contact_name],
        ["联系电话", customer.contact_phone],
        ["微信/对接方式", customer.contact_channel],
        ["客户群名称", customer.customer_group_name]
      ]
    },
    {
      title: "关联职员",
      icon: UserCheck,
      fields: [
        ["业务员（可多选）", formatEmployeeNames(customer.salesperson_name)],
        ["开单员", getCustomerBillingClerk(customer)],
        ["历史业务员", customer.historical_salespersons]
      ]
    },
    {
      title: "资料维护",
      icon: ClipboardList,
      fields: [
        ["基础信息完整度", customer.base_info_completeness],
        ["最近基础信息更新时间", formatDateTime(customer.profile_updated_at)],
        ["最近更新", formatDateTime(customer.updated_at)],
        ["备注", customer.base_remark]
      ]
    }
  ];

  return (
    <div className="grid gap-3">
      {groups.map((group) => {
        const Icon = group.icon;
        return (
          <section key={group.title} className="project-drawer-section">
            <div className="project-drawer-side-card-header">
              <span className="project-drawer-side-card-icon">
                <Icon className="h-4 w-4" />
              </span>
              <h4 className="project-drawer-side-card-title">{group.title}</h4>
            </div>
            <div className="grid gap-x-6 gap-y-3 md:grid-cols-2">
              {group.fields.map(([label, value]) => (
                <DetailField key={String(label)} label={String(label)} value={displayValue(value)} />
              ))}
            </div>
          </section>
        );
      })}
    </div>
  );
}

function CustomerBusinessProfilePanel({
  data,
  historyRows,
  auditRows,
  salesPage,
  balancePage,
  loading,
  error,
  contextLoading,
  contextError,
  timelineLoading,
  timelineError,
  canEdit,
  canViewSales,
  canViewBalance,
  canViewAudit,
  customer,
  jumpTools,
  onEdit,
  onRefreshTimeline
}: {
  data: CustomerBusinessProfileResponse | null;
  historyRows: CustomerBusinessProfileHistory[];
  auditRows: AuditLog[];
  salesPage: SalesDetailPageData | null;
  balancePage: AccountBalancePageData | null;
  loading: boolean;
  error: string;
  contextLoading: boolean;
  contextError: string;
  timelineLoading: boolean;
  timelineError: string;
  canEdit: boolean;
  canViewSales: boolean;
  canViewBalance: boolean;
  canViewAudit: boolean;
  customer: MasterRow;
  jumpTools: BusinessJumpTools;
  onEdit: () => void;
  onRefreshTimeline: () => void;
}) {
  if (loading && !data) {
    return (
      <div className="grid gap-3">
        {Array.from({ length: 4 }).map((_, index) => (
          <section key={`business-profile-loading-${index}`} className="rounded-lg border border-slate-200 bg-white p-4">
            <span className="block h-4 w-28 animate-pulse rounded bg-slate-100" />
            <div className="mt-4 grid gap-3 md:grid-cols-2">
              <span className="block h-12 animate-pulse rounded bg-slate-100" />
              <span className="block h-12 animate-pulse rounded bg-slate-100" />
            </div>
          </section>
        ))}
      </div>
    );
  }

  if (error) {
    return <ContextNotice tone="bad" title="经营资料加载失败" description={error} />;
  }

  const profile = data?.profile ?? null;
  const products = data?.products ?? [];
  const currentSalesProducts = data?.current_sales_products ?? [];
  const history = historyRows.length > 0 ? historyRows : data?.history_summary ?? [];
  const activeProducts = products.filter((product) => product.is_active);
  const inactiveProducts = products.filter((product) => !product.is_active);

  if (!profile) {
    return (
      <div className="grid gap-4">
        <CustomerEmptyPanel
          title="暂无客户经营资料"
          description="当前客户还没有人工确认后的经营资料，可通过“发起资料更新”补充经营概况、经营状态和经营产品清单。"
        />
        <CurrentSalesProductsTable
          rows={currentSalesProducts}
          canViewSales={canViewSales}
          jumpTools={jumpTools}
        />
        <section className="rounded-lg border border-slate-200 bg-white p-4">
          <div className="flex flex-col gap-3 md:flex-row md:items-center md:justify-between">
            <div>
              <h4 className="m-0 text-sm font-black text-slate-950">经营资料更新</h4>
              <p className="m-0 mt-1 text-xs font-bold leading-5 text-slate-500">维护客户经营概况、状态、销售渠道和经营产品清单。</p>
            </div>
            <button
              type="button"
              disabled={!canEdit}
              onClick={onEdit}
              className="inline-flex min-h-9 items-center justify-center rounded-lg border border-primary bg-primary px-3.5 text-sm font-bold text-white shadow-sm transition hover:bg-primary-hover disabled:cursor-not-allowed disabled:border-slate-200 disabled:bg-slate-50 disabled:text-slate-400 disabled:shadow-none"
              title={canEdit ? "发起客户经营资料更新" : "当前账号暂无经营资料编辑权限"}
            >
              <Plus className="mr-1.5 h-4 w-4" />
              发起资料更新
            </button>
          </div>
        </section>
      </div>
    );
  }

  const salesChannels = profile.sales_channels?.filter(Boolean) ?? [];
  const lastHistory = history[0];

  return (
    <div className="grid gap-4">
      <section className="rounded-lg border border-slate-200 bg-white p-4">
        <div className="mb-3 flex flex-col gap-3 md:flex-row md:items-start md:justify-between">
          <div>
            <div className="flex items-center gap-2">
              <span className="grid h-7 w-7 place-items-center rounded-md bg-primary-soft text-primary">
                <ClipboardList className="h-4 w-4" />
              </span>
              <h4 className="m-0 text-sm font-black text-slate-950">经营概况</h4>
            </div>
            <p className="m-0 mt-2 text-xs font-bold leading-5 text-slate-500">人工确认后的当前经营资料版本，过程数据不会自动覆盖。</p>
          </div>
          <div className="flex flex-wrap items-center gap-2">
            <Badge tone="neutral">版本 {profile.version_no}</Badge>
            <button
              type="button"
              disabled={!canEdit}
              onClick={onEdit}
              className="inline-flex min-h-8 items-center justify-center rounded-lg border border-slate-200 bg-white px-3 text-xs font-black text-slate-700 transition hover:bg-slate-50 disabled:cursor-not-allowed disabled:opacity-50"
              title={canEdit ? "更新客户经营资料" : "当前账号暂无经营资料编辑权限"}
            >
              <Pencil className="mr-1.5 h-3.5 w-3.5" />
              更新经营资料
            </button>
          </div>
        </div>
        <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-4">
          <BusinessProfileMetric label="客户类型" value={profile.business_customer_type} />
          <BusinessProfileMetric label="资料确认日期" value={formatDate(profile.confirmed_at)} />
          <BusinessProfileMetric label="本次更新类型" value={profile.update_type} />
          <BusinessProfileMetric label="填写人" value={profile.filled_by} />
          <BusinessProfileMetric label="最近更新来源" value={profile.update_source} />
          <BusinessProfileMetric label="当前业务员" value={profile.current_salesperson} />
        </div>
        <div className="mt-4 grid gap-4 lg:grid-cols-2">
          <BusinessTagList label="销售渠道" values={salesChannels} />
          <BusinessTagList label="经营状态标签" values={profile.business_status_tags?.filter(Boolean) ?? []} />
        </div>
      </section>

      <CustomerBusinessDataLinkPanel
        customer={customer}
        products={products}
        salesPage={salesPage}
        balancePage={balancePage}
        loading={contextLoading}
        error={contextError}
        canViewSales={canViewSales}
        canViewBalance={canViewBalance}
        jumpTools={jumpTools}
      />

      <CurrentSalesProductsTable
        rows={currentSalesProducts}
        canViewSales={canViewSales}
        jumpTools={jumpTools}
      />

      <section className="rounded-lg border border-slate-200 bg-white p-4">
        <div className="mb-3 flex items-center gap-2">
          <span className="grid h-7 w-7 place-items-center rounded-md bg-slate-100 text-primary">
            <Tag className="h-4 w-4" />
          </span>
          <h4 className="m-0 text-sm font-black text-slate-950">经营状态</h4>
        </div>
        <div className="grid gap-3 md:grid-cols-2">
          <BusinessStatusCard title={profile.business_status_label} description={profile.business_status_note} />
          <BusinessStatusCard title="其他经营状态" description={profile.other_status_note || profile.other_status_label} muted />
        </div>
      </section>

      <section className="rounded-lg border border-slate-200 bg-white">
        <div className="flex flex-col gap-3 border-b border-slate-200 px-4 py-3 lg:flex-row lg:items-start lg:justify-between">
          <div>
            <h4 className="m-0 text-sm font-black text-slate-950">经营产品清单</h4>
            <p className="m-0 mt-1 text-xs font-bold text-slate-500">客户实际经营或关注的品类、规格、品牌和机会点。有效 {activeProducts.length} 项，停用 {inactiveProducts.length} 项。</p>
          </div>
          <div className="flex flex-wrap items-center gap-2">
            <Badge tone={products.length > 0 ? "ok" : "neutral"}>{products.length} 项</Badge>
            <button
              type="button"
              disabled={!canEdit}
              onClick={onEdit}
              className="inline-flex min-h-8 items-center justify-center rounded-lg border border-slate-200 bg-white px-3 text-xs font-black text-slate-700 transition hover:bg-slate-50 disabled:cursor-not-allowed disabled:opacity-50"
              title={canEdit ? "编辑经营产品清单" : "当前账号暂无经营资料编辑权限"}
            >
              <Pencil className="mr-1.5 h-3.5 w-3.5" />
              编辑产品清单
            </button>
          </div>
        </div>
        {products.length > 0 ? (
          <div className="overflow-auto">
            <UiTable className="min-w-[1020px]">
              <TableHeader>
                <TableRow>
                  <TableHead>状态</TableHead>
                  <TableHead>本次变化</TableHead>
                  <TableHead>产品品类</TableHead>
                  <TableHead>规格</TableHead>
                  <TableHead>常用品牌</TableHead>
                  <TableHead>月用量</TableHead>
                  <TableHead>价格敏感</TableHead>
                  <TableHead>合作状态</TableHead>
                  <TableHead>机会说明</TableHead>
                  <TableHead>最后确认</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {products.map((product) => (
                  <TableRow key={product.id} className={!product.is_active ? "opacity-60" : ""}>
                    <TableCell><Badge tone={product.is_active ? "ok" : "neutral"}>{product.is_active ? "有效" : "停用"}</Badge></TableCell>
                    <TableCell><Badge tone={businessProductChangeTone(product.change_type)}>{displayValue(product.change_type || "无变化")}</Badge></TableCell>
                    <TableCell className="font-black text-slate-900">{displayValue(product.product_category)}</TableCell>
                    <TableCell>{displayValue(product.spec)}</TableCell>
                    <TableCell>{displayValue(product.common_brand)}</TableCell>
                    <TableCell>{displayValue(product.monthly_usage)}</TableCell>
                    <TableCell>{displayValue(product.price_sensitivity)}</TableCell>
                    <TableCell>
                      <Badge tone={businessCooperationTone(product.cooperation_status)}>{displayValue(product.cooperation_status)}</Badge>
                    </TableCell>
                    <TableCell className="max-w-[260px] whitespace-normal leading-6">{displayValue(product.opportunity_note)}</TableCell>
                    <TableCell>{formatDate(product.last_confirmed_at)}</TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </UiTable>
          </div>
        ) : (
          <div className="p-4">
            <CustomerEmptyPanel title="暂无经营产品" description="当前经营资料还没有维护具体产品清单，可点击编辑产品清单补充。" />
          </div>
        )}
      </section>

      <section className="rounded-lg border border-slate-200 bg-white p-4">
        <div className="mb-3 flex items-center gap-2">
          <span className="grid h-7 w-7 place-items-center rounded-md bg-slate-100 text-primary">
            <FileWarning className="h-4 w-4" />
          </span>
          <h4 className="m-0 text-sm font-black text-slate-950">最近一次更新说明</h4>
        </div>
        <p className="m-0 rounded-lg border border-dashed border-slate-200 bg-slate-50 px-4 py-3 text-sm font-bold leading-6 text-slate-600">
          {displayValue(profile.latest_update_note)}
        </p>
      </section>

      <CustomerBusinessHistoryAuditPanel
        historyRows={history}
        auditRows={auditRows}
        latestHistory={lastHistory}
        loading={timelineLoading}
        error={timelineError}
        canViewAudit={canViewAudit}
        onRefresh={onRefreshTimeline}
      />
    </div>
  );
}

function CurrentSalesProductsTable({
  rows,
  canViewSales,
  jumpTools
}: {
  rows: CustomerCurrentSalesProduct[];
  canViewSales: boolean;
  jumpTools: BusinessJumpTools;
}) {
  return (
    <section className="rounded-lg border border-slate-200 bg-white">
      <div className="flex flex-col gap-3 border-b border-slate-200 px-4 py-3 lg:flex-row lg:items-start lg:justify-between">
        <div className="flex items-start gap-2">
          <span className="mt-0.5 grid h-7 w-7 place-items-center rounded-md bg-primary-soft text-primary">
            <Package className="h-4 w-4" />
          </span>
          <div>
            <h4 className="m-0 text-sm font-black text-slate-950">现在销售商品集合</h4>
            <p className="m-0 mt-1 text-xs font-bold leading-5 text-slate-500">由销售明细自动统计，最多展示前 10 个商品。</p>
          </div>
        </div>
        <Badge tone={canViewSales && rows.length > 0 ? "ok" : "neutral"}>{canViewSales ? `${rows.length} 行` : "无权限"}</Badge>
      </div>
      {!canViewSales ? (
        <div className="p-4">
          <ContextNotice title="销售明细不可见" description="当前账号暂无销售明细查看权限。" />
        </div>
      ) : rows.length > 0 ? (
        <div className="overflow-auto">
          <UiTable className="min-w-[720px]">
            <TableHeader>
              <TableRow>
                <TableHead>商品编号</TableHead>
                <TableHead>商品名称</TableHead>
                <TableHead>月销售量</TableHead>
                <TableHead>季度销量</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {rows.map((row, index) => {
                const productCode = businessFilterValue(row.product_code);
                const productName = businessFilterValue(row.product_name);
                return (
                  <TableRow
                    key={`${productCode || productName || "product"}-${index}`}
                    className="cursor-pointer transition hover:bg-primary-soft"
                    onClick={() => jumpTools.openMasterRecord("products", { code: productCode, name: productName })}
                  >
                    <TableCell className="font-black text-primary">{displayValue(row.product_code)}</TableCell>
                    <TableCell className="font-bold text-slate-900">{displayValue(row.product_name)}</TableCell>
                    <TableCell>{formatNumber(row.monthly_sales_qty)}</TableCell>
                    <TableCell>{formatNumber(row.quarter_sales_qty)}</TableCell>
                  </TableRow>
                );
              })}
            </TableBody>
          </UiTable>
        </div>
      ) : (
        <div className="p-4">
          <CustomerEmptyPanel title="暂无可统计的销售商品" description="当前客户没有可用于统计的销售商品记录。" />
        </div>
      )}
    </section>
  );
}

