function businessAuditActionLabel(action: string) {
  const labels: Record<string, string> = {
    update_customer: "手动编辑客户资料",
    approval_update_customer_profile: "CRM 客户资料审批同步",
    view_customer_business_profile: "查看经营资料",
    update_customer_business_profile: "更新经营资料",
    approval_update_customer_business_profile: "CRM 经营资料审批同步",
    view_customer_business_history: "查看历史记录"
  };
  return labels[action] ?? auditActionLabels[action] ?? actionLabels[action] ?? action;
}

function businessHistoryProductCount(item: CustomerBusinessProfileHistory) {
  const snapshot = item.snapshot_json;
  if (!snapshot || Array.isArray(snapshot)) return 0;
  const products = (snapshot as { products?: unknown }).products;
  return Array.isArray(products) ? products.length : 0;
}

function businessHistoryProductChangeCounts(item: CustomerBusinessProfileHistory) {
  const snapshot = item.snapshot_json;
  if (!snapshot || Array.isArray(snapshot)) return {};
  const products = (snapshot as { products?: unknown }).products;
  if (!Array.isArray(products)) return {};
  return productChangeTypeOptions.reduce<Record<string, number>>((acc, changeType) => {
    acc[changeType] = products.filter((product) => {
      if (!product || typeof product !== "object" || Array.isArray(product)) return false;
      return ((product as { change_type?: unknown }).change_type || "无变化") === changeType;
    }).length;
    return acc;
  }, {});
}

function businessHistoryProfileSnapshot(item: CustomerBusinessProfileHistory) {
  const snapshot = item.snapshot_json;
  if (!snapshot || Array.isArray(snapshot)) return null;
  const profile = (snapshot as { profile?: unknown }).profile;
  return profile && typeof profile === "object" && !Array.isArray(profile) ? profile as Record<string, unknown> : null;
}

function BusinessProfileMetric({ label, value }: { label: string; value: unknown }) {
  return (
    <div className="rounded-lg border border-slate-200 bg-slate-50 px-3 py-3">
      <span className="block text-xs font-bold text-slate-400">{label}</span>
      <strong className="mt-1 block truncate text-sm font-black text-slate-900">{displayValue(value)}</strong>
    </div>
  );
}

function BusinessTagList({ label, values }: { label: string; values: string[] }) {
  return (
    <div>
      <span className="block text-xs font-bold text-slate-400">{label}</span>
      {values.length > 0 ? (
        <div className="mt-2 flex flex-wrap gap-2">
          {values.map((value) => (
            <span key={value} className="inline-flex min-h-7 items-center rounded-md bg-primary-soft px-2.5 text-xs font-black text-primary">
              {value}
            </span>
          ))}
        </div>
      ) : (
        <span className="mt-2 block text-sm font-bold text-slate-500">-</span>
      )}
    </div>
  );
}

function BusinessStatusCard({ title, description, muted = false }: { title: unknown; description: unknown; muted?: boolean }) {
  return (
    <div className={`rounded-lg border px-4 py-3 ${muted ? "border-slate-200 bg-slate-50" : "border-primary/20 bg-primary-soft"}`}>
      <strong className="block text-sm font-black text-slate-950">{displayValue(title)}</strong>
      <span className="mt-1 block text-xs font-bold leading-5 text-slate-500">{displayValue(description)}</span>
    </div>
  );
}

function businessCooperationTone(value: unknown): ContextTone {
  const status = String(value ?? "");
  if (status === "已合作") return "ok";
  if (status === "可开发") return "warn";
  if (status === "竞品占用") return "bad";
  return "neutral";
}

function businessProductChangeTone(value: unknown): ContextTone {
  const status = String(value ?? "");
  if (status === "新增") return "ok";
  if (status === "修改") return "warn";
  if (status === "停用") return "bad";
  return "neutral";
}

type CustomerBusinessProductFormState = {
  localId: string;
  product_category: string;
  spec: string;
  common_brand: string;
  monthly_usage: string;
  price_sensitivity: string;
  cooperation_status: string;
  change_type: string;
  opportunity_note: string;
  last_confirmed_at: string;
  is_active: boolean;
};

type CustomerRecommendedProductFormState = {
  localId: string;
  product_name: string;
  spec: string;
  recommended_quote: string;
  recommend_reason: string;
  customer_feedback: string;
  next_action: string;
};

type CustomerBusinessProfileFormState = {
  business_customer_type: string;
  confirmed_at: string;
  filled_by: string;
  update_source: string;
  update_type: string;
  current_salesperson: string;
  sales_channels: string[];
  business_status_tags: string[];
  business_status_label: string;
  business_status_note: string;
  other_status_label: string;
  other_status_note: string;
  latest_update_note: string;
  confirmed_by: string;
  products: CustomerBusinessProductFormState[];
  recommended_products: CustomerRecommendedProductFormState[];
};

const businessCustomerTypeOptions = ["餐饮", "批发", "零售", "团餐", "冻品店", "其他"];
const businessUpdateSourceOptions = ["业务员反馈", "现场拜访", "客户群信息", "订单变化", "人工核实", "电话沟通", "微信沟通", "客户群反馈", "系统整理", "其他"];
const businessUpdateTypeOptions = ["新增资料", "修正资料", "定期复核", "客户变化"];
const businessSalesChannelOptions = ["食堂", "烧烤", "麻辣烫", "卤菜", "炸鸡", "火锅", "快餐", "其他"];
const businessStatusTagOptions = [
  { value: "传统夫妻老婆店", detail: "等客上门，经营氛围随缘。" },
  { value: "现代夫妻老婆店", detail: "主动改变，愿意尝试新品或活动。" },
  { value: "完善团队经营", detail: "有分工、有规模、有稳定采购机制。" },
  { value: "批发型客户", detail: "重价格、重周转、重货源稳定。" }
];
const priceSensitivityOptions = ["未确认", "高", "一般", "低"];
const cooperationStatusOptions = ["未确认", "已合作", "可开发", "竞品占用", "暂不做", "暂停"];
const productChangeTypeOptions = ["新增", "修改", "无变化", "停用"];

function todayDateInput() {
  return new Date().toISOString().slice(0, 10);
}

function dateInputValue(value: unknown) {
  if (!value) return "";
  return String(value).slice(0, 10);
}

function businessProfileToForm(data: CustomerBusinessProfileResponse | null, customer: MasterRow): CustomerBusinessProfileFormState {
  const profile = data?.profile;
  const products = data?.products ?? [];
  const rawCustomerType = displayValueForInput(profile?.business_customer_type ?? customer.customer_type);
  const businessCustomerType = rawCustomerType && businessCustomerTypeOptions.includes(rawCustomerType) ? rawCustomerType : rawCustomerType ? "其他" : "";
  return {
    business_customer_type: businessCustomerType,
    confirmed_at: dateInputValue(profile?.confirmed_at) || todayDateInput(),
    filled_by: displayValueForInput(profile?.filled_by),
    update_source: displayValueForInput(profile?.update_source) || "系统整理",
    update_type: displayValueForInput(profile?.update_type) || (profile ? "修正资料" : "新增资料"),
    current_salesperson: displayValueForInput(profile?.current_salesperson ?? customer.salesperson_name),
    sales_channels: normalizeStringArray(profile?.sales_channels),
    business_status_tags: normalizeStringArray(profile?.business_status_tags),
    business_status_label: displayValueForInput(profile?.business_status_label),
    business_status_note: displayValueForInput(profile?.business_status_note),
    other_status_label: displayValueForInput(profile?.other_status_label),
    other_status_note: displayValueForInput(profile?.other_status_note),
    latest_update_note: displayValueForInput(profile?.latest_update_note),
    confirmed_by: displayValueForInput(profile?.confirmed_by),
    products: products.map((product, index) => ({
      localId: `existing-${product.id}-${index}`,
      product_category: displayValueForInput(product.product_category),
      spec: displayValueForInput(product.spec),
      common_brand: displayValueForInput(product.common_brand),
      monthly_usage: displayValueForInput(product.monthly_usage),
      price_sensitivity: displayValueForInput(product.price_sensitivity) || "未确认",
      cooperation_status: displayValueForInput(product.cooperation_status) || "未确认",
      change_type: displayValueForInput(product.change_type) || "无变化",
      opportunity_note: displayValueForInput(product.opportunity_note),
      last_confirmed_at: dateInputValue(product.last_confirmed_at),
      is_active: product.is_active
    })),
    recommended_products: []
  };
}

function emptyBusinessProductForm(): CustomerBusinessProductFormState {
  return {
    localId: `new-${Date.now()}-${Math.random().toString(36).slice(2)}`,
    product_category: "",
    spec: "",
    common_brand: "",
    monthly_usage: "",
    price_sensitivity: "未确认",
    cooperation_status: "未确认",
    change_type: "新增",
    opportunity_note: "",
    last_confirmed_at: todayDateInput(),
    is_active: true
  };
}

function emptyRecommendedProductForm(): CustomerRecommendedProductFormState {
  return {
    localId: `recommended-${Date.now()}-${Math.random().toString(36).slice(2)}`,
    product_name: "",
    spec: "",
    recommended_quote: "",
    recommend_reason: "",
    customer_feedback: "",
    next_action: ""
  };
}

function normalizeStringArray(value: unknown) {
  return Array.isArray(value) ? value.map((item) => String(item).trim()).filter(Boolean) : [];
}

function toggleStringListValue(values: string[], value: string) {
  return values.includes(value) ? values.filter((item) => item !== value) : [...values, value];
}

function normalizedBusinessProductKey(product: CustomerBusinessProductFormState) {
  return [product.product_category, product.spec, product.common_brand]
    .map((value) => value.trim().toLowerCase())
    .join("|");
}

function hasBusinessProductContent(product: CustomerBusinessProductFormState) {
  return Boolean(product.product_category || product.spec || product.common_brand || product.monthly_usage || product.opportunity_note);
}

function hasRecommendedProductContent(product: CustomerRecommendedProductFormState) {
  return Boolean(product.product_name || product.spec || product.recommended_quote || product.recommend_reason || product.customer_feedback || product.next_action);
}

function countBusinessProductChanges(products: Array<CustomerBusinessProductFormState | CustomerBusinessProduct>) {
  return productChangeTypeOptions.reduce<Record<string, number>>((acc, changeType) => {
    acc[changeType] = products.filter((product) => (product.change_type || "无变化") === changeType).length;
    return acc;
  }, {});
}

function businessProfileFormToPayload(form: CustomerBusinessProfileFormState): CustomerBusinessProfilePayload {
  const products: CustomerBusinessProductPayload[] = form.products
    .map((product, index) => ({
      product_category: normalizeFormValue(product.product_category),
      spec: normalizeFormValue(product.spec),
      common_brand: normalizeFormValue(product.common_brand),
      monthly_usage: normalizeFormValue(product.monthly_usage),
      price_sensitivity: product.price_sensitivity || "未确认",
      cooperation_status: product.cooperation_status || "未确认",
      change_type: product.change_type || "无变化",
      opportunity_note: normalizeFormValue(product.opportunity_note),
      last_confirmed_at: normalizeFormValue(product.last_confirmed_at),
      sort_order: index + 1,
      is_active: product.change_type === "停用" ? false : product.is_active
    }))
    .filter((product) => Boolean(product.product_category || product.spec || product.common_brand || product.monthly_usage || product.opportunity_note));
  const recommended_products: CustomerRecommendedProductPayload[] = form.recommended_products
    .map((product) => ({
      product_name: normalizeFormValue(product.product_name),
      spec: normalizeFormValue(product.spec),
      recommended_quote: normalizeFormValue(product.recommended_quote),
      recommend_reason: normalizeFormValue(product.recommend_reason),
      customer_feedback: normalizeFormValue(product.customer_feedback),
      next_action: normalizeFormValue(product.next_action)
    }))
    .filter((product) => Boolean(product.product_name || product.spec || product.recommended_quote || product.recommend_reason || product.customer_feedback || product.next_action));

  return {
    business_customer_type: normalizeFormValue(form.business_customer_type),
    confirmed_at: normalizeFormValue(form.confirmed_at),
    filled_by: normalizeFormValue(form.filled_by),
    update_source: normalizeFormValue(form.update_source),
    update_type: normalizeFormValue(form.update_type),
    current_salesperson: normalizeFormValue(form.current_salesperson),
    sales_channels: form.sales_channels,
    business_status_tags: form.business_status_tags,
    business_status_label: normalizeFormValue(form.business_status_label || form.business_status_tags[0] || ""),
    business_status_note: normalizeFormValue(form.business_status_note),
    other_status_label: normalizeFormValue(form.other_status_label),
    other_status_note: normalizeFormValue(form.other_status_note),
    latest_update_note: normalizeFormValue(form.latest_update_note),
    confirmed_by: normalizeFormValue(form.confirmed_by),
    products,
    recommended_products
  };
}

function CustomerBusinessProfileEditDrawer({
  customer,
  data,
  onClose,
  onSave,
  title = "更新经营资料",
  eyebrow = "BUSINESS PROFILE UPDATE",
  heading = "客户经营资料更新",
  description = "保存后会生成新的当前版本、历史快照和审计日志；过程数据不会自动覆盖这里的人工确认资料。",
  submitLabel = "保存并同步客户资料",
  savingLabel = "保存中",
  errorPrefix = "经营资料保存失败。"
}: {
  customer: MasterRow;
  data: CustomerBusinessProfileResponse | null;
  onClose: () => void;
  onSave: (payload: CustomerBusinessProfilePayload) => Promise<void>;
  title?: string;
  eyebrow?: string;
  heading?: string;
  description?: string;
  submitLabel?: string;
  savingLabel?: string;
  errorPrefix?: string;
}) {
  const [form, setForm] = useState<CustomerBusinessProfileFormState>(() => businessProfileToForm(data, customer));
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const customerName = displayValue(customer.customer_name);
  const customerCode = displayValue(customer.customer_code);
  const updateField = (field: keyof CustomerBusinessProfileFormState, value: string | string[]) => {
    setForm((current) => ({ ...current, [field]: value }));
  };
  const updateProduct = (localId: string, field: keyof CustomerBusinessProductFormState, value: string | boolean) => {
    setForm((current) => ({
      ...current,
      products: current.products.map((product) => {
        if (product.localId !== localId) return product;
        const nextProduct = { ...product, [field]: value };
        if (field === "change_type" && value === "停用") nextProduct.is_active = false;
        if (field === "is_active" && value === false && nextProduct.change_type !== "停用") nextProduct.change_type = "停用";
        return nextProduct;
      })
    }));
  };
  const updateRecommendedProduct = (localId: string, field: keyof CustomerRecommendedProductFormState, value: string) => {
    setForm((current) => ({
      ...current,
      recommended_products: current.recommended_products.map((product) => (
        product.localId === localId ? { ...product, [field]: value } : product
      ))
    }));
  };
  const addProduct = () => {
    setForm((current) => ({ ...current, products: [...current.products, emptyBusinessProductForm()] }));
  };
  const addRecommendedProduct = () => {
    setForm((current) => ({ ...current, recommended_products: [...current.recommended_products, emptyRecommendedProductForm()] }));
  };
  const removeProduct = (localId: string) => {
    setForm((current) => ({ ...current, products: current.products.filter((product) => product.localId !== localId) }));
  };
  const removeRecommendedProduct = (localId: string) => {
    setForm((current) => ({ ...current, recommended_products: current.recommended_products.filter((product) => product.localId !== localId) }));
  };
  const duplicateProduct = (localId: string) => {
    setForm((current) => {
      const target = current.products.find((product) => product.localId === localId);
      if (!target) return current;
      const copy = {
        ...target,
        localId: `copy-${Date.now()}-${Math.random().toString(36).slice(2)}`,
        product_category: `${target.product_category} 副本`.trim(),
        change_type: "新增",
        is_active: false
      };
      const index = current.products.findIndex((product) => product.localId === localId);
      const nextProducts = [...current.products];
      nextProducts.splice(index + 1, 0, copy);
      return { ...current, products: nextProducts };
    });
  };
  const moveProduct = (localId: string, direction: -1 | 1) => {
    setForm((current) => {
      const index = current.products.findIndex((product) => product.localId === localId);
      const nextIndex = index + direction;
      if (index < 0 || nextIndex < 0 || nextIndex >= current.products.length) return current;
      const nextProducts = [...current.products];
      const [item] = nextProducts.splice(index, 1);
      nextProducts.splice(nextIndex, 0, item);
      return { ...current, products: nextProducts };
    });
  };
  const submit = async () => {
    setError("");
    if (!form.confirmed_at) {
      setError("资料确认日期不能为空。");
      return;
    }
    if (!form.update_source) {
      setError("更新来源不能为空。");
      return;
    }
    if (!form.update_type) {
      setError("本次更新类型不能为空。");
      return;
    }
    const incompleteProduct = form.products.find((product) => {
      const hasContent = hasBusinessProductContent(product);
      return hasContent && !product.product_category.trim();
    });
    if (incompleteProduct) {
      setError("经营产品行只要填写了内容，就必须填写产品品类。");
      return;
    }
    const incompleteRecommendedProduct = form.recommended_products.find((product) => hasRecommendedProductContent(product) && !product.product_name.trim());
    if (incompleteRecommendedProduct) {
      setError("拜访推荐产品行只要填写了内容，就必须填写产品名称。");
      return;
    }
    const activeKeys = form.products
      .filter((product) => product.is_active && product.product_category.trim())
      .map((product) => normalizedBusinessProductKey(product));
    const duplicateKey = activeKeys.find((key, index) => key && activeKeys.indexOf(key) !== index);
    if (duplicateKey) {
      setError("有效产品中存在重复的品类、规格和品牌组合，请停用或调整重复产品行。");
      return;
    }
    setSaving(true);
    try {
      await onSave(businessProfileFormToPayload(form));
    } catch (err) {
      setError(err instanceof Error ? err.message : errorPrefix);
    } finally {
      setSaving(false);
    }
  };
  const inputClass = "h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold outline-none transition focus:border-primary focus:ring-2 focus:ring-primary/15";
  const textareaClass = "min-h-[86px] rounded-lg border border-slate-200 px-3 py-2 text-sm font-bold leading-6 outline-none transition focus:border-primary focus:ring-2 focus:ring-primary/15";
  const filledProductCount = form.products.filter(hasBusinessProductContent).length;
  const activeProductCount = form.products.filter((product) => hasBusinessProductContent(product) && product.is_active).length;
  const inactiveProductCount = form.products.filter((product) => hasBusinessProductContent(product) && !product.is_active).length;
  const changeCounts = countBusinessProductChanges(form.products.filter(hasBusinessProductContent));
  const clearForm = () => {
    setError("");
    setForm({
      ...businessProfileToForm(null, customer),
      filled_by: "",
      confirmed_by: "",
      business_customer_type: "",
      current_salesperson: "",
      update_source: "业务员反馈",
      update_type: data?.profile ? "修正资料" : "新增资料",
      sales_channels: [],
      business_status_tags: [],
      business_status_label: "",
      business_status_note: "",
      other_status_label: "",
      other_status_note: "",
      latest_update_note: "",
      products: [],
      recommended_products: []
    });
  };

  return (
    <Drawer title={title} subtitle={`${customerName} · ${customerCode}`} onClose={onClose}>
      <form
        className="grid gap-4"
        noValidate
        onSubmit={(event) => {
          event.preventDefault();
          void submit();
        }}
      >
        <section className="rounded-lg border border-slate-200 bg-white p-4">
          <div className="flex flex-col gap-2 md:flex-row md:items-start md:justify-between">
            <div>
              <p className="m-0 text-xs font-black uppercase tracking-[0.18em] text-primary">{eyebrow}</p>
              <h3 className="m-0 mt-1 text-xl font-black text-slate-950">{heading}</h3>
              <p className="m-0 mt-2 text-sm font-bold leading-6 text-slate-500">{description}</p>
            </div>
            <Badge tone={data?.profile ? "neutral" : "warn"}>{data?.profile ? `当前版本 ${data.profile.version_no}` : "首次维护"}</Badge>
          </div>
        </section>

        {error ? <ContextNotice tone="bad" title="保存前检查" description={error} /> : null}

        <section className="rounded-lg border border-slate-200 bg-white p-4">
          <div className="flex items-center gap-2">
            <span className="grid h-7 w-7 place-items-center rounded-md bg-primary-soft text-xs font-black text-primary">1</span>
            <h4 className="m-0 text-sm font-black text-slate-950">本次确认信息</h4>
          </div>
          <div className="mt-3 grid gap-3 md:grid-cols-2 xl:grid-cols-3">
            <BusinessEditField label="客户编号">
              <input className={`${inputClass} bg-slate-50 text-slate-500`} value={customerCode} readOnly />
            </BusinessEditField>
            <BusinessEditField label="系统开单名称">
              <input className={`${inputClass} bg-slate-50 text-slate-500`} value={customerName} readOnly />
            </BusinessEditField>
            <BusinessEditField label="资料确认日期" required>
              <input className={inputClass} type="date" value={form.confirmed_at} onChange={(event) => updateField("confirmed_at", event.target.value)} />
            </BusinessEditField>
            <BusinessEditField label="填写人">
              <input className={inputClass} value={form.filled_by} onChange={(event) => updateField("filled_by", event.target.value)} placeholder="例：业务员/内勤" />
            </BusinessEditField>
            <BusinessEditField label="更新来源" required>
              <select className={inputClass} value={form.update_source} onChange={(event) => updateField("update_source", event.target.value)}>
                {businessUpdateSourceOptions.map((option) => <option key={option} value={option}>{option}</option>)}
              </select>
            </BusinessEditField>
            <BusinessEditField label="本次更新类型" required>
              <select className={inputClass} value={form.update_type} onChange={(event) => updateField("update_type", event.target.value)}>
                {businessUpdateTypeOptions.map((option) => <option key={option} value={option}>{option}</option>)}
              </select>
            </BusinessEditField>
          </div>
        </section>

        <section className="rounded-lg border border-slate-200 bg-white p-4">
          <div className="flex items-center gap-2">
            <span className="grid h-7 w-7 place-items-center rounded-md bg-primary-soft text-xs font-black text-primary">2</span>
            <h4 className="m-0 text-sm font-black text-slate-950">经营概况变化</h4>
          </div>
          <div className="mt-3 grid gap-3 md:grid-cols-3">
            <BusinessEditField label="客户类型">
              <select className={inputClass} value={form.business_customer_type} onChange={(event) => updateField("business_customer_type", event.target.value)}>
                <option value="">请选择</option>
                {businessCustomerTypeOptions.map((option) => <option key={option} value={option}>{option}</option>)}
              </select>
            </BusinessEditField>
            <div className="md:col-span-2">
              <BusinessEditField label="销售渠道（可多选）">
                <div className="flex flex-wrap gap-2">
                  {businessSalesChannelOptions.map((option) => (
                    <label key={option} className={`inline-flex min-h-9 cursor-pointer items-center gap-2 rounded-full border px-3 text-xs font-black transition ${form.sales_channels.includes(option) ? "border-primary bg-primary-soft text-primary" : "border-slate-200 bg-white text-slate-600 hover:bg-slate-50"}`}>
                      <input type="checkbox" className="h-3.5 w-3.5 accent-primary" checked={form.sales_channels.includes(option)} onChange={() => updateField("sales_channels", toggleStringListValue(form.sales_channels, option))} />
                      {option}
                    </label>
                  ))}
                </div>
              </BusinessEditField>
            </div>
          </div>

          <div className="mt-4">
            <BusinessEditField label="经营状态（可多选）">
              <div className="grid gap-2 md:grid-cols-2">
                {businessStatusTagOptions.map((option) => (
                  <label key={option.value} className={`flex cursor-pointer gap-2 rounded-lg border p-3 transition ${form.business_status_tags.includes(option.value) ? "border-primary bg-primary-soft" : "border-slate-200 bg-slate-50 hover:bg-white"}`}>
                    <input type="checkbox" className="mt-1 h-4 w-4 accent-primary" checked={form.business_status_tags.includes(option.value)} onChange={() => updateField("business_status_tags", toggleStringListValue(form.business_status_tags, option.value))} />
                    <span>
                      <strong className="block text-sm font-black text-slate-900">{option.value}</strong>
                      <span className="mt-0.5 block text-xs font-bold leading-5 text-slate-500">{option.detail}</span>
                    </span>
                  </label>
                ))}
              </div>
            </BusinessEditField>
          </div>
          <div className="mt-3 grid gap-3 md:grid-cols-2">
            <BusinessEditField label="经营状态说明">
              <textarea className={textareaClass} value={form.business_status_note} onChange={(event) => updateField("business_status_note", event.target.value)} placeholder="补充本次经营状态变化。" />
            </BusinessEditField>
            <BusinessEditField label="其他经营状态">
              <textarea className={textareaClass} value={form.other_status_note} onChange={(event) => updateField("other_status_note", event.target.value)} placeholder="例：新开门店、准备转型、淡季停业、换老板经营等" />
            </BusinessEditField>
          </div>
        </section>

        <section className="rounded-lg border border-slate-200 bg-white">
          <div className="flex flex-col gap-3 border-b border-slate-200 px-4 py-3 md:flex-row md:items-center md:justify-between">
            <div>
              <div className="flex items-center gap-2">
                <span className="grid h-7 w-7 place-items-center rounded-md bg-primary-soft text-xs font-black text-primary">3</span>
                <h4 className="m-0 text-sm font-black text-slate-950">经营产品变化</h4>
              </div>
              <p className="m-0 mt-2 text-xs font-bold text-slate-500">逐项记录本次产品变化。已填写 {filledProductCount} 行，有效 {activeProductCount} 行，停用 {inactiveProductCount} 行。</p>
              <div className="mt-2 flex flex-wrap gap-2">
                {productChangeTypeOptions.map((type) => (
                  <span key={type} className="inline-flex min-h-7 items-center rounded-md bg-slate-50 px-2.5 text-xs font-black text-slate-500">
                    {type} {changeCounts[type] ?? 0}
                  </span>
                ))}
              </div>
            </div>
            <div className="flex flex-wrap gap-2">
              <button type="button" onClick={addProduct} className="inline-flex min-h-8 items-center justify-center rounded-lg border border-slate-200 bg-white px-3 text-xs font-black text-slate-700 transition hover:bg-slate-50">
                <Plus className="mr-1.5 h-3.5 w-3.5" />
                新增产品
              </button>
              <button type="button" onClick={() => setForm((current) => ({ ...current, products: [...current.products, emptyBusinessProductForm(), emptyBusinessProductForm(), emptyBusinessProductForm()] }))} className="inline-flex min-h-8 items-center justify-center rounded-lg border border-slate-200 bg-white px-3 text-xs font-black text-slate-700 transition hover:bg-slate-50">
                批量加 3 行
              </button>
            </div>
          </div>
          <div className="grid gap-3 p-4">
            {form.products.length > 0 ? form.products.map((product, index) => (
              <div key={product.localId} className="rounded-lg border border-slate-200 bg-slate-50 p-3">
                <div className="mb-3 flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between">
                  <div className="flex flex-wrap items-center gap-2">
                    <strong className="text-sm text-slate-900">产品行 {index + 1}</strong>
                    <Badge tone={businessProductChangeTone(product.change_type)}>{product.change_type || "无变化"}</Badge>
                    <Badge tone={product.is_active ? "ok" : "neutral"}>{product.is_active ? "有效" : "停用"}</Badge>
                  </div>
                  <div className="flex flex-wrap gap-2">
                    <button type="button" disabled={index === 0} onClick={() => moveProduct(product.localId, -1)} className="inline-flex h-8 items-center justify-center rounded-lg border border-slate-200 bg-white px-2.5 text-xs font-black text-slate-600 hover:bg-slate-50 disabled:cursor-not-allowed disabled:opacity-40">
                      <ArrowUp className="mr-1 h-3.5 w-3.5" />
                      上移
                    </button>
                    <button type="button" disabled={index === form.products.length - 1} onClick={() => moveProduct(product.localId, 1)} className="inline-flex h-8 items-center justify-center rounded-lg border border-slate-200 bg-white px-2.5 text-xs font-black text-slate-600 hover:bg-slate-50 disabled:cursor-not-allowed disabled:opacity-40">
                      <ArrowDown className="mr-1 h-3.5 w-3.5" />
                      下移
                    </button>
                    <button type="button" onClick={() => duplicateProduct(product.localId)} className="inline-flex h-8 items-center justify-center rounded-lg border border-slate-200 bg-white px-2.5 text-xs font-black text-slate-600 hover:bg-slate-50">
                      <Copy className="mr-1 h-3.5 w-3.5" />
                      复制
                    </button>
                    <button type="button" onClick={() => removeProduct(product.localId)} className="inline-flex h-8 items-center justify-center rounded-lg border border-red-100 bg-white px-2.5 text-xs font-black text-red-600 hover:bg-red-50">
                      <Trash2 className="mr-1 h-3.5 w-3.5" />
                      删除
                    </button>
                  </div>
                </div>
                <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-4">
                  <BusinessEditField label="产品品类">
                    <input className={inputClass} value={product.product_category} onChange={(event) => updateProduct(product.localId, "product_category", event.target.value)} placeholder="如：鸡腿" />
                  </BusinessEditField>
                  <BusinessEditField label="规格">
                    <input className={inputClass} value={product.spec} onChange={(event) => updateProduct(product.localId, "spec", event.target.value)} placeholder="如：80/100" />
                  </BusinessEditField>
                  <BusinessEditField label="常用品牌">
                    <input className={inputClass} value={product.common_brand} onChange={(event) => updateProduct(product.localId, "common_brand", event.target.value)} placeholder="如：六和" />
                  </BusinessEditField>
                  <BusinessEditField label="月用量">
                    <input className={inputClass} value={product.monthly_usage} onChange={(event) => updateProduct(product.localId, "monthly_usage", event.target.value)} placeholder="如：20件/月" />
                  </BusinessEditField>
                  <BusinessEditField label="价格敏感">
                    <select className={inputClass} value={product.price_sensitivity} onChange={(event) => updateProduct(product.localId, "price_sensitivity", event.target.value)}>
                      {priceSensitivityOptions.map((option) => <option key={option} value={option}>{option}</option>)}
                    </select>
                  </BusinessEditField>
                  <BusinessEditField label="合作状态">
                    <select className={inputClass} value={product.cooperation_status} onChange={(event) => updateProduct(product.localId, "cooperation_status", event.target.value)}>
                      {cooperationStatusOptions.map((option) => <option key={option} value={option}>{option}</option>)}
                    </select>
                  </BusinessEditField>
                  <BusinessEditField label="本次变化">
                    <select className={inputClass} value={product.change_type} onChange={(event) => updateProduct(product.localId, "change_type", event.target.value)}>
                      {productChangeTypeOptions.map((option) => <option key={option} value={option}>{option}</option>)}
                    </select>
                  </BusinessEditField>
                  <BusinessEditField label="最后确认">
                    <input className={inputClass} type="date" value={product.last_confirmed_at} onChange={(event) => updateProduct(product.localId, "last_confirmed_at", event.target.value)} />
                  </BusinessEditField>
                  <label className="flex min-h-10 items-center gap-2 rounded-lg border border-slate-200 bg-white px-3 text-sm font-black text-slate-700">
                    <input type="checkbox" checked={product.is_active} onChange={(event) => updateProduct(product.localId, "is_active", event.target.checked)} />
                    有效
                  </label>
                  <div className="md:col-span-2 xl:col-span-4">
                    <BusinessEditField label="机会说明">
                      <textarea className={textareaClass} value={product.opportunity_note} onChange={(event) => updateProduct(product.localId, "opportunity_note", event.target.value)} />
                    </BusinessEditField>
                  </div>
                </div>
              </div>
            )) : (
              <CustomerEmptyPanel title="暂无经营产品" description="可以先保存经营概况，也可以点击新增产品补充经营产品清单。" />
            )}
          </div>
        </section>

        <section className="rounded-lg border border-slate-200 bg-white p-4">
          <div className="flex flex-col gap-3 md:flex-row md:items-center md:justify-between">
            <div className="flex items-center gap-2">
              <span className="grid h-7 w-7 place-items-center rounded-md bg-primary-soft text-xs font-black text-primary">4</span>
              <div>
                <h4 className="m-0 text-sm font-black text-slate-950">本次拜访推荐产品</h4>
                <p className="m-0 mt-1 text-xs font-bold text-slate-500">记录本次拜访推荐、报价和客户反馈，不覆盖长期经营产品资料。</p>
              </div>
            </div>
            <button type="button" onClick={addRecommendedProduct} className="inline-flex min-h-8 items-center justify-center rounded-lg border border-slate-200 bg-white px-3 text-xs font-black text-slate-700 transition hover:bg-slate-50">
              <Plus className="mr-1.5 h-3.5 w-3.5" />
              新增推荐
            </button>
          </div>
          <div className="mt-3 grid gap-3">
            {form.recommended_products.length > 0 ? form.recommended_products.map((product, index) => (
              <div key={product.localId} className="rounded-lg border border-slate-200 bg-slate-50 p-3">
                <div className="mb-3 flex items-center justify-between gap-3">
                  <strong className="text-sm text-slate-900">推荐行 {index + 1}</strong>
                  <button type="button" onClick={() => removeRecommendedProduct(product.localId)} className="inline-flex h-8 items-center justify-center rounded-lg border border-red-100 bg-white px-2.5 text-xs font-black text-red-600 hover:bg-red-50">
                    <Trash2 className="mr-1 h-3.5 w-3.5" />
                    删除
                  </button>
                </div>
                <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">
                  <BusinessEditField label="产品名称">
                    <input className={inputClass} value={product.product_name} onChange={(event) => updateRecommendedProduct(product.localId, "product_name", event.target.value)} placeholder="如：九联冻120-130g腿" />
                  </BusinessEditField>
                  <BusinessEditField label="规格">
                    <input className={inputClass} value={product.spec} onChange={(event) => updateRecommendedProduct(product.localId, "spec", event.target.value)} placeholder="如：120-130g" />
                  </BusinessEditField>
                  <BusinessEditField label="推荐报价">
                    <input className={inputClass} value={product.recommended_quote} onChange={(event) => updateRecommendedProduct(product.localId, "recommended_quote", event.target.value)} placeholder="如：165 元/箱" />
                  </BusinessEditField>
                  <BusinessEditField label="推荐原因">
                    <textarea className={textareaClass} value={product.recommend_reason} onChange={(event) => updateRecommendedProduct(product.localId, "recommend_reason", event.target.value)} />
                  </BusinessEditField>
                  <BusinessEditField label="客户反馈">
                    <textarea className={textareaClass} value={product.customer_feedback} onChange={(event) => updateRecommendedProduct(product.localId, "customer_feedback", event.target.value)} />
                  </BusinessEditField>
                  <BusinessEditField label="后续动作">
                    <textarea className={textareaClass} value={product.next_action} onChange={(event) => updateRecommendedProduct(product.localId, "next_action", event.target.value)} />
                  </BusinessEditField>
                </div>
              </div>
            )) : (
              <CustomerEmptyPanel title="暂无拜访推荐产品" description="如本次拜访有推荐、报价或试样安排，可点击新增推荐记录。" />
            )}
          </div>
        </section>

        <section className="rounded-lg border border-slate-200 bg-white p-4">
          <div className="mb-3 flex items-center gap-2">
            <span className="grid h-7 w-7 place-items-center rounded-md bg-primary-soft text-xs font-black text-primary">5</span>
            <h4 className="m-0 text-sm font-black text-slate-950">本次说明</h4>
          </div>
          <div className="grid gap-3 md:grid-cols-2">
            <BusinessEditField label="本次说明">
              <textarea className={textareaClass} value={form.latest_update_note} onChange={(event) => updateField("latest_update_note", event.target.value)} placeholder="概括本次新增或调整的经营资料。" />
            </BusinessEditField>
            <BusinessEditField label="确认人">
              <input className={inputClass} value={form.confirmed_by} onChange={(event) => updateField("confirmed_by", event.target.value)} placeholder="如：业务员姓名" />
            </BusinessEditField>
          </div>
        </section>

        <div className="sticky bottom-0 -mx-5 flex flex-wrap justify-end gap-2 border-t border-slate-200 bg-white/95 px-5 py-4 backdrop-blur">
          <Button secondary disabled={saving} onClick={clearForm}>清空本次编辑</Button>
          <Button secondary disabled={saving} onClick={onClose}>取消</Button>
          <Button type="submit" disabled={saving}>{saving ? savingLabel : submitLabel}</Button>
        </div>
      </form>
    </Drawer>
  );
}

function BusinessEditField({ label, required = false, children }: { label: string; required?: boolean; children: React.ReactNode }) {
  return (
    <label className="grid gap-2 text-sm font-black text-slate-700">
      <span>{label}{required ? <span className="text-red-500"> *</span> : null}</span>
      {children}
    </label>
  );
}

function CustomerPortraitPanel({ customer, canRefresh }: { customer: MasterRow; canRefresh: boolean }) {
  const customerCode = displayValue(customer.customer_code);
  const customerName = displayValue(customer.customer_name);
  const customerType = displayValue(customer.customer_type);
  const region = displayValue(customer.region);
  const salesperson = formatEmployeeNames(customer.salesperson_name);
  const completeness = displayValue(customer.base_info_completeness);
  const profileUpdatedAt = formatDateTime(customer.profile_updated_at ?? customer.updated_at);
  const [portrait, setPortrait] = useState<CustomerPortraitTagsResult | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const loadPortrait = async (forceRefresh = false) => {
    if (customerCode === "-") return;
    setLoading(true);
    setError("");
    try {
      setPortrait(forceRefresh ? await refreshCustomerPortraitTags(customerCode) : await customerPortraitTags(customerCode));
    } catch (err) {
      setError(err instanceof Error ? err.message : "客户标签画像加载失败。");
    } finally {
      setLoading(false);
    }
  };
  useEffect(() => {
    void loadPortrait();
  }, [customerCode]);
  const tags = portrait?.tags ?? [];
  const payment = portrait?.payment;
  const profile = portrait?.profile;
  const paymentTags = payment?.tags ?? [];
  const qualityIssues = portrait?.quality.issues ?? [];
  const metric = (key: string) => portrait?.metrics?.[key];
  const dataCutoff = portrait?.data_cutoff_date ? formatDate(portrait.data_cutoff_date) : "暂无";
  const generatedAt = portrait?.generated_at ? formatDateTime(portrait.generated_at) : profileUpdatedAt;
  const portraitStatus = loading ? "计算中" : portrait ? (portrait.quality.status === "ok" ? "已生成" : "部分生成") : "待生成";
  const portraitStatusTone: ContextTone = loading ? "neutral" : portrait?.quality.status === "ok" ? "ok" : portrait ? "warn" : "neutral";

  return (
    <div className="grid gap-4">
      <ContextNotice
        tone={portrait?.quality.status === "partial" ? "neutral" : "ok"}
        title="客户画像自动生成已启用"
        description="进入客户画像时会读取最新快照；若没有快照则自动生成。手动刷新会重新生成快照，并写入生成任务与审计日志。"
      />
      {error ? <ContextNotice tone="bad" title="标签画像加载失败" description={error} /> : null}
      {qualityIssues.length > 0 ? (
        <div className="grid gap-2">
          {qualityIssues.map((issue) => <ContextNotice key={issue} tone="warn" title="数据质量提醒" description={issue} />)}
        </div>
      ) : null}

      <section className="rounded-lg border border-slate-200 bg-white p-4">
        <div className="flex flex-col gap-3 lg:flex-row lg:items-start lg:justify-between">
          <div className="min-w-0">
            <p className="m-0 text-xs font-black uppercase tracking-[0.18em] text-primary">CUSTOMER PORTRAIT</p>
            <div className="mt-2 flex flex-wrap items-center gap-2">
              <h4 className="m-0 truncate text-xl font-black text-slate-950">{customerName}</h4>
              <Badge tone="neutral">{customerCode}</Badge>
              <Badge tone={completeness === "完整" ? "ok" : "warn"}>{completeness}</Badge>
            </div>
            <p className="m-0 mt-2 text-sm font-bold leading-6 text-slate-500">
              {customerType} · {region} · {salesperson}
            </p>
          </div>
          <button
            type="button"
            disabled={!canRefresh || loading}
            onClick={() => void loadPortrait(true)}
            title={canRefresh ? "重新生成当前客户画像快照" : "当前账号暂无刷新客户画像权限"}
            className="inline-flex min-h-9 items-center justify-center rounded-lg border border-slate-200 bg-white px-3.5 text-sm font-bold text-slate-700 transition hover:bg-slate-50 disabled:cursor-not-allowed disabled:bg-slate-50 disabled:text-slate-400"
          >
            <RefreshCcw className="mr-1.5 h-4 w-4" />
            {loading ? "生成中" : "刷新画像"}
          </button>
        </div>

        <div className="mt-4 grid gap-3 lg:grid-cols-4">
          <ContextSummaryCard label="画像状态" value={portraitStatus} detail={portrait ? `匹配 ${portrait.match_confidence === "weak" ? "弱" : "强"} · ${portrait.snapshot?.source === "auto_generated" ? "自动生成" : portrait.snapshot?.source === "manual_refresh" ? "手动刷新" : "快照读取"}` : "等待首次生成"} icon={ShieldCheck} tone={portraitStatusTone} />
          <ContextSummaryCard label="规则版本" value={portrait?.rule_version ?? "v0.1"} detail={portrait?.snapshot ? `快照 #${portrait.snapshot.id}` : "规则模板生成"} icon={ClipboardList} />
          <ContextSummaryCard label="数据截止" value={dataCutoff} detail={`生成 ${generatedAt}`} icon={Clock3} />
          <ContextSummaryCard label="回款风险" value={payment ? `${payment.score} 分` : "待计算"} detail={payment ? `${payment.level} · ${payment.action}` : `往来 ${formatNumber(metric("balance_rows") ?? 0)} 行`} icon={Siren} tone={payment?.level_tone ?? "neutral"} />
        </div>
      </section>

      <section className="rounded-lg border border-slate-200 bg-white p-4">
        <div className="mb-3 flex items-center justify-between gap-3">
          <div>
            <h4 className="m-0 text-sm font-black text-slate-950">标签画像</h4>
            <p className="m-0 mt-1 text-xs font-bold text-slate-500">按当前画像口径生成客户规模、RFM、品类、毛利、退货、稳定性、生命周期等 12 维标签，并保存为快照。</p>
          </div>
          <Badge tone={portrait?.quality.status === "ok" ? "ok" : "neutral"}>{loading ? "计算中" : `${tags.length || 12} 维口径`}</Badge>
        </div>
        {loading && !portrait ? (
          <div className="rounded-lg border border-slate-200 bg-slate-50 p-4 text-sm font-bold text-slate-500">正在计算客户标签画像...</div>
        ) : null}
        <div className="grid gap-2 md:grid-cols-2 xl:grid-cols-3">
          {tags.map((item) => (
            <div key={item.key} className="rounded-lg border border-slate-200 bg-slate-50 p-3">
              <div className="flex items-center justify-between gap-2">
                <span className="text-xs font-black text-slate-500">{item.label}</span>
                <Badge tone={item.tone}>{item.value}</Badge>
              </div>
              <p className="m-0 mt-2 text-xs font-bold leading-5 text-slate-500">{item.detail}</p>
            </div>
          ))}
        </div>
        {!loading && tags.length === 0 ? (
          <CustomerEmptyPanel title="暂无标签画像" description="当前客户画像接口尚未返回标签结果，可以刷新重试或确认客户是否仍在可见数据范围内。" />
        ) : null}
      </section>

      <section className="grid gap-4">
        <div className="rounded-lg border border-slate-200 bg-white p-4">
          <div className="mb-3 flex items-center gap-2">
            <span className="grid h-8 w-8 place-items-center rounded-md bg-slate-100 text-primary">
              <CircleDollarSign className="h-4 w-4" />
            </span>
            <div className="min-w-0 flex-1">
              <h4 className="m-0 text-sm font-black text-slate-950">回款标签</h4>
              <p className="m-0 mt-1 text-xs font-bold text-slate-500">6+1 回款风险标签，基于往来快照、近 30 天销售和当前预警规则计算。</p>
            </div>
            {payment ? <Badge tone={payment.level_tone}>{payment.level} · {payment.score} 分</Badge> : <Badge tone="neutral">待计算</Badge>}
          </div>
          {payment ? (
            <div className="mb-3 grid gap-3 lg:grid-cols-3">
              <ContextSummaryCard label="风险等级" value={payment.level} detail={payment.action} icon={Siren} tone={payment.level_tone} />
              <ContextSummaryCard label="最新应收" value={formatMoney(payment.metrics.latest_ar_balance)} detail={`预收 ${formatMoney(payment.metrics.latest_advance_receipt_balance)}`} icon={Building2} tone={Number(payment.metrics.latest_ar_balance ?? 0) > 0 ? "neutral" : "ok"} />
              <ContextSummaryCard label="近似账龄" value={payment.metrics.aging_days === null || payment.metrics.aging_days === undefined ? "-" : `${payment.metrics.aging_days} 天`} detail={`近 30 天销售 ${formatMoney(payment.metrics.recent_30_sales_amount)}`} icon={Clock3} tone={Number(payment.metrics.aging_days ?? 0) >= 30 ? "warn" : "neutral"} />
            </div>
          ) : null}
          {payment?.score_reasons?.length ? (
            <div className="mb-3 rounded-lg border border-slate-200 bg-slate-50 px-3 py-2">
              <p className="m-0 text-xs font-black text-slate-500">评分依据</p>
              <div className="mt-2 flex flex-wrap gap-2">
                {payment.score_reasons.map((reason) => (
                  <span key={reason} className="inline-flex min-h-6 items-center rounded-md bg-white px-2 text-xs font-bold text-slate-600 ring-1 ring-slate-200">
                    {reason}
                  </span>
                ))}
              </div>
            </div>
          ) : null}
          {!payment && loading ? (
            <div className="rounded-lg border border-slate-200 bg-slate-50 p-4 text-sm font-bold text-slate-500">正在计算回款风险...</div>
          ) : null}
          {!payment && !loading ? (
            <CustomerEmptyPanel title="暂无回款风险结果" description="当前客户画像接口尚未返回回款风险结果，可以刷新重试。" />
          ) : null}
          <div className="grid gap-2 md:grid-cols-2">
            {paymentTags.map((item) => (
              <div key={item.key} className="rounded-lg border border-slate-200 px-3 py-2">
                <div className="flex items-center justify-between gap-2">
                  <span className="text-sm font-black text-slate-700">{item.label}</span>
                  <Badge tone={item.tone}>{item.value}</Badge>
                </div>
                <p className="m-0 mt-1 text-xs font-bold leading-5 text-slate-500">{item.detail}</p>
              </div>
            ))}
          </div>
        </div>

        <div className="rounded-lg border border-slate-200 bg-white p-4">
          <div className="mb-3 flex flex-col gap-3 lg:flex-row lg:items-start lg:justify-between">
            <span className="grid h-8 w-8 place-items-center rounded-md bg-slate-100 text-primary">
              <Tag className="h-4 w-4" />
            </span>
            <div className="min-w-0 flex-1">
              <h4 className="m-0 text-sm font-black text-slate-950">深度画像</h4>
              <p className="m-0 mt-1 text-xs font-bold text-slate-500">规则模板生成 9 段客户经营画像，所有判断都基于当前标签、销售和往来数据。</p>
            </div>
            {profile ? <Badge tone="neutral">{profile.rule_version}</Badge> : <Badge tone="neutral">待生成</Badge>}
          </div>
          {profile ? (
            <div className="grid gap-4">
              <div className="rounded-lg border border-slate-200 bg-slate-50 p-3">
                <div className="flex flex-wrap items-center gap-2">
                  <h5 className="m-0 text-lg font-black text-slate-950">{profile.headline}</h5>
                  <Badge tone={payment?.level_tone ?? "neutral"}>{profile.positioning}</Badge>
                </div>
                <div className="mt-3 grid gap-2">
                  {profile.conclusions.map((conclusion, index) => (
                    <p key={`${conclusion}-${index}`} className="m-0 rounded-md bg-white px-3 py-2 text-sm font-bold leading-6 text-slate-700 ring-1 ring-slate-200">
                      {index + 1}. {conclusion}
                    </p>
                  ))}
                </div>
                <div className="mt-3 flex flex-wrap gap-2">
                  {profile.keywords.map((keyword) => (
                    <span key={keyword} className="inline-flex min-h-7 items-center rounded-md bg-white px-2.5 text-xs font-bold text-slate-600 ring-1 ring-slate-200">
                      {keyword}
                    </span>
                  ))}
                </div>
              </div>
              <div className="grid gap-3">
                {profile.sections.map((section) => (
                  <article key={section.key} className="rounded-lg border border-slate-200 bg-white p-4">
                    <h5 className="m-0 text-sm font-black text-slate-950">{section.title}</h5>
                    <p className="m-0 mt-2 text-sm font-bold leading-6 text-slate-600">{section.summary}</p>
                    {section.items?.length ? (
                      <div className="mt-3 grid gap-2 md:grid-cols-2 xl:grid-cols-3">
                        {section.items.map((item) => (
                          <div key={`${section.key}-${item.label}`} className="rounded-lg border border-slate-200 bg-slate-50 px-3 py-2">
                            <div className="flex items-center justify-between gap-2">
                              <span className="text-xs font-black text-slate-500">{item.label}</span>
                              <span className="text-sm font-black text-slate-900">{item.value}</span>
                            </div>
                            {item.detail ? <p className="m-0 mt-1 text-xs font-bold leading-5 text-slate-500">{item.detail}</p> : null}
                          </div>
                        ))}
                      </div>
                    ) : null}
                    {section.bullets?.length ? (
                      <div className="mt-3 grid gap-2">
                        {section.bullets.map((bullet) => (
                          <p key={`${section.key}-${bullet}`} className="m-0 rounded-md bg-slate-50 px-3 py-2 text-sm font-bold leading-6 text-slate-600">
                            {bullet}
                          </p>
                        ))}
                      </div>
                    ) : null}
                  </article>
                ))}
              </div>
            </div>
          ) : loading ? (
            <div className="rounded-lg border border-slate-200 bg-slate-50 p-4 text-sm font-bold text-slate-500">正在生成 9 段深度画像...</div>
          ) : (
            <CustomerEmptyPanel title="暂无深度画像" description="当前客户画像接口尚未返回 9 段深度画像，可以刷新重试。" />
          )}
        </div>
      </section>

      <section className="rounded-lg border border-slate-200 bg-white p-4">
        <div className="mb-3 flex items-center gap-2">
          <span className="grid h-8 w-8 place-items-center rounded-md bg-slate-100 text-primary">
            <Database className="h-4 w-4" />
          </span>
          <div>
            <h4 className="m-0 text-sm font-black text-slate-950">画像数据来源</h4>
            <p className="m-0 mt-1 text-xs font-bold text-slate-500">当前画像由客户档案、销售明细、往来对账和商品档案生成，结果已进入快照、任务和审计闭环。</p>
          </div>
        </div>
        <div className="grid gap-2 md:grid-cols-2">
          {[
            ["客户档案", "基础资料、区域、联系人、业务员归属"],
            ["销售明细", "交易频次、销售额、品类偏好、毛利表现"],
            ["往来对账", "应收、预收、账龄、余额风险"],
            ["商品档案", "品类、品牌、规格和商品结构"]
          ].map(([source, detail]) => (
            <div key={source} className="rounded-lg border border-slate-200 bg-slate-50 px-3 py-2">
              <span className="block text-sm font-black text-slate-800">{source}</span>
              <span className="mt-1 block text-xs font-bold leading-5 text-slate-500">{detail}</span>
            </div>
          ))}
        </div>
      </section>

      {portrait?.snapshot ? (
        <section className="rounded-lg border border-slate-200 bg-white p-4">
          <div className="mb-3 flex items-center gap-2">
            <span className="grid h-8 w-8 place-items-center rounded-md bg-slate-100 text-primary">
              <History className="h-4 w-4" />
            </span>
            <div>
              <h4 className="m-0 text-sm font-black text-slate-950">画像快照与闭环记录</h4>
              <p className="m-0 mt-1 text-xs font-bold text-slate-500">本次查看与刷新均受权限控制，并写入审计日志。</p>
            </div>
          </div>
          <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-4">
            <ContextSummaryCard label="快照编号" value={`#${portrait.snapshot.id}`} detail={portrait.snapshot.status === "partial" ? "部分生成" : "已生成"} icon={ClipboardList} tone={portrait.snapshot.status === "partial" ? "neutral" : "ok"} />
            <ContextSummaryCard label="生成来源" value={portrait.snapshot.source === "manual_refresh" ? "手动刷新" : portrait.snapshot.source === "auto_generated" ? "自动生成" : "读取快照"} detail={portrait.snapshot.task_no ? `任务 ${portrait.snapshot.task_no}` : "无任务号"} icon={RefreshCcw} />
            <ContextSummaryCard label="生成周期" value={portrait.snapshot.period_start || portrait.snapshot.period_end ? `${formatDate(portrait.snapshot.period_start)} - ${formatDate(portrait.snapshot.period_end)}` : "暂无周期"} detail={`生成 ${formatDateTime(portrait.snapshot.generated_at)}`} icon={Clock3} />
            <ContextSummaryCard label="审计闭环" value="已记录" detail={portrait.task ? `${portrait.task.task_type} · ${portrait.task.status}` : "view_customer_portrait"} icon={ShieldCheck} tone="ok" />
          </div>
        </section>
      ) : (
        <CustomerEmptyPanel title="暂无画像快照" description="当前客户画像尚未生成快照；进入本页会自动生成，或点击刷新画像重试。" />
      )}
    </div>
  );
}

function DetailField({ label, value }: { label: string; value: string }) {
  return (
    <div className="min-w-0">
      <span className="block text-xs font-bold text-slate-400">{label}</span>
      <span className="mt-1 block break-words text-sm font-bold leading-6 text-slate-700">{value}</span>
    </div>
  );
}

const hiddenProductionCopyTerms = [
  ["8", "0", "8", "2"].join(""),
  ["端", "口"].join(""),
  ["测", "试"].join(""),
  ["施", "工"].join(""),
  ["临", "时", "编", "号"].join(""),
  ["迁", "移", "细", "节"].join(""),
  ["后", "续"].join(""),
  ["项", "目", "底", "座"].join("")
];

function shouldShowSupportCopy(value: string | null | undefined) {
  const text = String(value ?? "").trim();
  return Boolean(text) && !hiddenProductionCopyTerms.some((term) => text.includes(term));
}

function CustomerEmptyPanel({ title, description }: { title: string; description: string }) {
  const showDescription = shouldShowSupportCopy(description);
  return (
    <div className="project-empty-panel">
      <span className="project-empty-icon">
        <Clock3 className="h-5 w-5" />
      </span>
      <h4 className="mb-1 mt-3 text-sm font-black text-foreground">{title}</h4>
      {showDescription ? <p className="m-0 text-sm leading-6 text-muted-foreground">{description}</p> : null}
    </div>
  );
}

function ContextNotice({
  tone = "neutral",
  title,
  description
}: {
  tone?: ContextTone;
  title: string;
  description: string;
}) {
  const showDescription = shouldShowSupportCopy(description);
  const toneClass =
    tone === "warn"
      ? "border-amber-200 bg-amber-50 text-amber-800"
      : tone === "bad"
        ? "border-red-200 bg-red-50 text-red-700"
        : tone === "ok"
          ? "border-emerald-200 bg-emerald-50 text-emerald-800"
          : "border-primary/15 bg-primary-soft text-primary";
  return (
    <div className={`rounded-lg border px-3 py-2 ${toneClass}`}>
      <p className="m-0 text-sm font-black">{title}</p>
      {showDescription ? <p className="m-0 mt-0.5 text-xs font-bold leading-5 opacity-80">{description}</p> : null}
    </div>
  );
}

function ContextFilterChips({ items }: { items: Array<{ label: string; value?: string }> }) {
  const visibleItems = items.filter((item) => item.value);
  if (visibleItems.length === 0) {
    return <ContextNotice title="暂无明确聚合依据" description="当前明细缺少客户、供应商、商品或结算单位字段，系统会避免无条件展示全表数据。" />;
  }
  return (
    <div className="flex flex-wrap gap-2 rounded-lg border border-border bg-muted px-3 py-2">
      <span className="mr-1 inline-flex items-center text-xs font-black text-muted-foreground">聚合依据</span>
      {visibleItems.map((item) => (
        <span key={`${item.label}-${item.value}`} className="inline-flex min-h-6 items-center rounded-md bg-card px-2 text-xs font-bold text-foreground ring-1 ring-border">
          {item.label}：{item.value}
        </span>
      ))}
    </div>
  );
}

function ContextBlockStatusGrid({
  items
}: {
  items: Array<{ label: string; available: boolean; total?: number; preview?: number }>;
}) {
  return (
    <div className="grid gap-2 md:grid-cols-2 xl:grid-cols-4">
      {items.map((item) => (
        <div key={item.label} className="rounded-lg border border-border bg-muted px-3 py-2">
          <div className="flex items-center justify-between gap-2">
            <span className="text-xs font-black text-muted-foreground">{item.label}</span>
            <Badge tone={item.available ? "ok" : "neutral"}>{item.available ? "可见" : "无权限"}</Badge>
          </div>
          <p className="m-0 mt-1 text-xs font-bold text-muted-foreground">
            {item.available ? `命中 ${item.total ?? 0} 条，预览 ${item.preview ?? 0} 条` : "当前账号不可查看"}
          </p>
        </div>
      ))}
    </div>
  );
}

function CustomerBusinessContextPanel({
  customer,
  loading,
  error,
  canViewSales,
  canViewBalance,
  salesPage,
  balancePage,
  jumpTools
}: {
  customer: MasterRow;
  loading: boolean;
  error: string;
  canViewSales: boolean;
  canViewBalance: boolean;
  salesPage: SalesDetailPageData | null;
  balancePage: AccountBalancePageData | null;
  jumpTools: BusinessJumpTools;
}) {
  const customerCode = businessFilterValue(customer.customer_code);
  const customerName = businessFilterValue(customer.customer_name);
  const salesSummary = salesPage?.summary;
  const balanceSummary = balancePage?.summary;
  if (!canViewSales && !canViewBalance) {
    return <CustomerEmptyPanel title="暂无可见经营数据" description="当前账号没有销售明细和往来对账查看权限，因此无法在客户上下文中聚合业务数据。" />;
  }

  return (
    <div className="grid gap-4">
      {error ? <div className="rounded-lg border border-amber-200 bg-amber-50 px-3 py-2 text-sm font-bold text-amber-700">{error}</div> : null}
      {loading ? (
        <div className="rounded-lg border border-slate-200 bg-slate-50 p-4 text-sm font-bold text-slate-500">正在加载客户经营数据...</div>
      ) : null}
      <div className="grid gap-3 lg:grid-cols-4">
        <ContextSummaryCard label="销售单据" value={canViewSales ? formatNumber(salesSummary?.documents ?? 0) : "无权限"} detail={canViewSales ? `${salesSummary?.rows ?? 0} 行明细` : "销售明细不可见"} icon={CircleDollarSign} />
        <ContextSummaryCard label="销售额" value={canViewSales ? formatMoney(salesSummary?.amount_tax_total) : "无权限"} detail={canViewSales ? `毛利 ${formatMoney(salesSummary?.gross_profit)}` : "销售明细不可见"} icon={ClipboardList} />
        <ContextSummaryCard label="应收余额" value={canViewBalance ? formatMoney(balanceSummary?.ar_balance) : "无权限"} detail={canViewBalance ? `风险行 ${balanceSummary?.risk_rows ?? 0}` : "往来对账不可见"} icon={Building2} tone={Number(balanceSummary?.ar_balance ?? 0) > 0 ? "warn" : "neutral"} />
        <ContextSummaryCard label="预收余额" value={canViewBalance ? formatMoney(balanceSummary?.advance_receipt_balance) : "无权限"} detail={canViewBalance ? `${balancePage?.total ?? 0} 条往来` : "往来对账不可见"} icon={CircleDollarSign} />
      </div>

      {canViewSales ? (
        <ContextInlineTable<SalesDetailRow>
          title="最近销售明细"
          description="直接在客户抽屉内查看该客户近期销售，不必跳转离开当前列表。"
          rows={salesPage?.items ?? []}
          columns={[
            { key: "document_date", label: "日期", render: (row) => formatDate(row.document_date) },
            { key: "document_no", label: "单号" },
            { key: "product_name", label: "商品" },
            { key: "sale_qty_base", label: "数量", render: (row) => formatNumber(row.sale_qty_base) },
            { key: "amount_tax_total", label: "价税合计", render: (row) => formatMoney(row.amount_tax_total) },
            { key: "gross_profit", label: "毛利", render: (row) => formatMoney(row.gross_profit) }
          ]}
          emptyMessage="当前客户暂无可展示的销售明细。"
        />
      ) : null}

      {canViewBalance ? (
        <ContextInlineTable<AccountBalanceRow>
          title="往来对账摘要"
          description="聚合该客户的应收、预收和期末余额，先看风险再决定是否打开完整表。"
          rows={balancePage?.items ?? []}
          columns={[
            { key: "data_date", label: "日期", render: (row) => formatDate(row.data_date) },
            { key: "settlement_unit_name", label: "结算单位" },
            { key: "ar_balance", label: "应收", render: (row) => formatMoney(row.ar_balance) },
            { key: "advance_receipt_balance", label: "预收", render: (row) => formatMoney(row.advance_receipt_balance) },
            { key: "current_closing_balance", label: "期末余额", render: (row) => formatMoney(row.current_closing_balance) },
            { key: "balance_type", label: "类型" }
          ]}
          emptyMessage="当前客户暂无可展示的往来对账数据。"
        />
      ) : null}

      <div className="flex flex-wrap justify-end gap-2">
        {canViewSales ? (
          <Button secondary onClick={() => jumpTools.openProcessPage("sales", { customer_code: customerCode, q: customerCode ? undefined : customerName })}>
            打开完整销售明细
          </Button>
        ) : null}
        {canViewBalance ? (
          <Button secondary onClick={() => jumpTools.openProcessPage("account-balance", { settlement_unit_code: customerCode, settlement_unit_name: customerName })}>
            打开完整往来对账
          </Button>
        ) : null}
      </div>
    </div>
  );
}

function CustomerCrmContextPanel({
  data,
  loading,
  error,
  permissions,
  onOpenProject,
  onRefresh
}: {
  data: CustomerContextResult | null;
  loading: boolean;
  error: string;
  permissions: PermissionCode[];
  onOpenProject: (project: CrmProjectRow) => void;
  onRefresh: () => void;
}) {
  const crm = data?.crm;
  const stats = crm?.stats;
  const projects = crm?.projects ?? [];
  const tasks = crm?.tasks ?? [];
  const followups = crm?.followups ?? [];
  const workItems = crm?.work_items ?? [];
  const approvals = crm?.approvals ?? [];
  const projectById = new Map(projects.map((project) => [project.id, project]));
  const [selectedWorkItem, setSelectedWorkItem] = useState<WorkItemRow | null>(null);
  const canOperateWorkItem = hasAnyPermission(permissions, ["crm_issue.handle", "crm_issue.close"]);
  const workItemColumns: Array<CrmInlineColumn<WorkItemRow>> = [
    ...crmWorkItemColumns,
    {
      label: "操作",
      render: (row) => canOperateWorkItem ? (
        <button
          type="button"
          onClick={(event) => { event.stopPropagation(); setSelectedWorkItem(row); }}
          className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-xs font-black text-slate-700 hover:bg-slate-50"
        >
          处理
        </button>
      ) : <span className="text-xs font-bold text-slate-400">只读</span>
    }
  ];

  if (loading && !data) {
    return (
      <div className="grid gap-3">
        {Array.from({ length: 4 }).map((_, index) => (
          <section key={`customer-crm-loading-${index}`} className="rounded-lg border border-slate-200 bg-white p-4">
            <span className="block h-4 w-28 animate-pulse rounded bg-slate-100" />
            <span className="mt-4 block h-16 animate-pulse rounded bg-slate-100" />
          </section>
        ))}
      </div>
    );
  }

  if (error) {
    return <ContextNotice tone="bad" title="CRM 关联加载失败" description={error} />;
  }

  if (!crm?.available) {
    return <CustomerEmptyPanel title="暂无可见 CRM 关联数据" description="当前账号没有 CRM 项目、任务、跟进、审批或事项查看权限，无法在客户详情中展示关联上下文。" />;
  }

  const activeTasks = tasks.filter((task) => !task.is_closed && task.status !== "closed");
  const riskTasks = tasks.filter((task) => task.need_support || task.need_manager_support || task.need_boss_decision || task.is_blocked);
  const pendingApprovals = approvals.filter((approval) => ["submitted", "under_review", "need_supplement"].includes(approval.status));

  return (
    <div className="grid gap-4">
      {loading ? <ContextNotice title="正在刷新 CRM 关联" description="客户 CRM 上下文正在更新，列表会自动替换为最新数据。" /> : null}
      <div className="grid gap-3 lg:grid-cols-4">
        <ContextSummaryCard label="关联项目" value={stats?.project_total ?? projects.length} detail={`可打开 ${projects.length} 个项目详情`} icon={BriefcaseBusiness} />
        <ContextSummaryCard label="任务明细" value={stats?.task_total ?? tasks.length} detail={`未闭环 ${stats?.task_open ?? activeTasks.length}`} icon={UsersRound} tone={(stats?.task_open ?? activeTasks.length) > 0 ? "neutral" : "ok"} />
        <ContextSummaryCard label="风险事项" value={(stats?.task_need_support ?? 0) + (stats?.task_blocked ?? 0)} detail={`待支持 ${stats?.work_item_open ?? 0} / 阻塞 ${stats?.task_blocked ?? 0}`} icon={FileWarning} tone={riskTasks.length > 0 || Number(stats?.work_item_open ?? 0) > 0 ? "warn" : "neutral"} />
        <ContextSummaryCard label="待审批" value={stats?.approval_pending ?? pendingApprovals.length} detail={`审批记录 ${approvals.length} 条`} icon={ShieldCheck} tone={pendingApprovals.length > 0 ? "warn" : "neutral"} />
      </div>

      <section className="rounded-lg border border-slate-200 bg-white">
        <div className="flex flex-col gap-3 border-b border-slate-200 px-4 py-3 md:flex-row md:items-center md:justify-between">
          <div>
            <h4 className="m-0 text-sm font-black text-slate-950">关联项目</h4>
            <p className="m-0 mt-1 text-xs font-bold leading-5 text-slate-500">点击项目查看项目概览、闭环状态和关联入口。</p>
          </div>
          <Button secondary onClick={onRefresh}><RefreshCcw className="mr-1.5 h-4 w-4" />刷新</Button>
        </div>
        {projects.length > 0 ? (
          <div className="grid gap-3 p-4 xl:grid-cols-2">
            {projects.map((project) => (
              <button
                key={project.id}
                type="button"
                onClick={() => onOpenProject(project)}
                className="min-w-0 rounded-lg border border-slate-200 bg-white p-4 text-left transition hover:border-primary hover:bg-primary-soft"
              >
                <div className="flex flex-wrap items-start justify-between gap-2">
                  <div className="min-w-0">
                    <strong className="block truncate text-sm font-black text-slate-950">{project.project_name}</strong>
                    <span className="mt-1 block text-xs font-bold text-slate-400">{project.project_code}</span>
                  </div>
                  <Badge tone={crmStatusTone(project.status)}>{crmProjectStatusLabels[project.status] ?? project.status}</Badge>
                </div>
                <div className="mt-3 grid gap-2 text-xs font-bold text-slate-500 md:grid-cols-2">
                  <span>任务 {project.task_closed ?? 0}/{project.task_total ?? 0}</span>
                  <span>待支持 {project.support_item_open ?? 0}</span>
                  <span>审批 {crmApprovalStatusLabels[project.approval_status] ?? project.approval_status}</span>
                  <span>最近跟进 {formatDateTime(project.latest_followup_at)}</span>
                </div>
              </button>
            ))}
          </div>
        ) : (
          <div className="p-4">
            <CustomerEmptyPanel title="暂无关联项目" description="该客户当前没有命中的 CRM 项目任务，或项目列表超出当前账号的数据范围。" />
          </div>
        )}
      </section>

      <CrmInlineTable
        rows={tasks}
        columns={[
          { label: "所属项目", render: (row) => displayValue(projectById.get(row.project_id)?.project_name ?? row.project_id) },
          ...crmTaskColumns.filter((column) => column.label !== "客户")
        ]}
        emptyMessage="暂无任务明细。"
      />

      <CustomerCrmFollowupTimeline rows={followups} projectById={projectById} />

      <div className="grid gap-4 xl:grid-cols-2">
        <CrmInlineTable rows={workItems} columns={workItemColumns} emptyMessage="暂无待支持事项。" />
        <CrmInlineTable rows={approvals} columns={crmApprovalColumns} emptyMessage="暂无审批记录。" />
      </div>
      <AnimatePresence>
        {selectedWorkItem ? (
          <WorkItemDetailDrawer
            key={`customer-work-item-${selectedWorkItem.id}`}
            item={selectedWorkItem}
            permissions={permissions}
            onClose={() => setSelectedWorkItem(null)}
            onChanged={(updated) => {
              setSelectedWorkItem(updated);
              onRefresh();
            }}
          />
        ) : null}
      </AnimatePresence>
    </div>
  );
}

function CustomerCrmFollowupTimeline({ rows, projectById }: { rows: CrmFollowupRow[]; projectById: Map<number, CrmProjectRow> }) {
  if (rows.length === 0) {
    return <CustomerEmptyPanel title="暂无跟进记录" description="该客户还没有已写入的项目跟进记录，或跟进记录超出当前账号的数据范围。" />;
  }
  return (
    <section className="rounded-lg border border-slate-200 bg-white p-4">
      <div className="mb-4 flex items-center gap-2">
        <span className="grid h-8 w-8 place-items-center rounded-md bg-primary-soft text-primary">
          <History className="h-4 w-4" />
        </span>
        <div>
          <h4 className="m-0 text-sm font-black text-slate-950">近期跟进时间线</h4>
          <p className="m-0 mt-1 text-xs font-bold text-slate-500">按最新写入时间展示，帮助判断客户在项目中的真实推进状态。</p>
        </div>
      </div>
      <div className="relative grid gap-0 pl-3">
        {rows.slice(0, 10).map((row, index) => (
          <div key={row.id} className="relative grid grid-cols-[24px_minmax(0,1fr)] gap-3 pb-5 last:pb-0">
            <div className="relative flex justify-center">
              <span className={`mt-1 h-2.5 w-2.5 rounded-full ${row.need_support || row.need_manager_support || row.need_boss_decision ? "bg-amber-500" : row.is_closed ? "bg-emerald-500" : "bg-primary"}`} />
              {index < Math.min(rows.length, 10) - 1 ? <span className="absolute left-1/2 top-5 h-[calc(100%-0.5rem)] w-px -translate-x-1/2 bg-slate-200" /> : null}
            </div>
            <article className="min-w-0 rounded-lg border border-slate-200 bg-slate-50/70 px-4 py-3">
              <div className="flex flex-wrap items-center justify-between gap-2">
                <h5 className="m-0 text-sm font-black text-slate-950">{projectById.get(row.project_id)?.project_name ?? `项目 ${row.project_id}`}</h5>
                <span className="text-xs font-bold text-slate-400">{formatDateTime(row.created_at ?? row.followup_date)}</span>
              </div>
              <div className="mt-2 flex flex-wrap gap-2">
                <Badge tone={crmStatusTone(row.review_status)}>{crmApprovalStatusLabels[row.review_status] ?? row.review_status}</Badge>
                {row.need_support ? <Badge tone="warn">需支持</Badge> : null}
                {row.is_closed ? <Badge tone="ok">已闭环</Badge> : null}
              </div>
              <p className="m-0 mt-3 text-sm leading-6 text-slate-600">{displayValue(row.customer_feedback)}</p>
              <p className="m-0 mt-2 text-xs font-bold leading-5 text-slate-500">下一步：{displayValue(row.owner_next_action ?? row.next_action)}</p>
            </article>
          </div>
        ))}
      </div>
    </section>
  );
}

function ProductBusinessContextPanel({
  product,
  loading,
  error,
  canViewSales,
  canViewPurchase,
  canViewInventory,
  salesPage,
  purchasePage,
  inventoryPage,
  jumpTools
}: {
  product: MasterRow;
  loading: boolean;
  error: string;
  canViewSales: boolean;
  canViewPurchase: boolean;
  canViewInventory: boolean;
  salesPage: SalesDetailPageData | null;
  purchasePage: PurchaseDetailPageData | null;
  inventoryPage: InventorySnapshotPageData | null;
  jumpTools: BusinessJumpTools;
}) {
  const productCode = businessFilterValue(product.product_code);
  const productName = businessFilterValue(product.product_name);
  const salesSummary = salesPage?.summary;
  const purchaseSummary = purchasePage?.summary;
  const inventorySummary = inventoryPage?.summary;
  if (!canViewSales && !canViewPurchase && !canViewInventory) {
    return <CustomerEmptyPanel title="暂无可见经营数据" description="当前账号没有销售、采购和库存过程数据查看权限，因此无法在商品上下文中聚合业务数据。" />;
  }

  return (
    <div className="grid gap-4">
      {error ? <div className="rounded-lg border border-amber-200 bg-amber-50 px-3 py-2 text-sm font-bold text-amber-700">{error}</div> : null}
      {loading ? (
        <div className="rounded-lg border border-slate-200 bg-slate-50 p-4 text-sm font-bold text-slate-500">正在加载商品经营数据...</div>
      ) : null}
      <div className="grid gap-3 lg:grid-cols-4">
        <ContextSummaryCard label="销售额" value={canViewSales ? formatMoney(salesSummary?.amount_tax_total) : "无权限"} detail={canViewSales ? `${salesSummary?.documents ?? 0} 单 / ${salesSummary?.rows ?? 0} 行` : "销售明细不可见"} icon={CircleDollarSign} />
        <ContextSummaryCard label="采购额" value={canViewPurchase ? formatMoney(purchaseSummary?.amount_tax_total ?? purchaseSummary?.purchase_amount) : "无权限"} detail={canViewPurchase ? `${purchaseSummary?.documents ?? 0} 单 / ${purchaseSummary?.rows ?? 0} 行` : "采购明细不可见"} icon={ClipboardList} />
        <ContextSummaryCard label="库存数量" value={canViewInventory ? formatNumber(inventorySummary?.stock_qty) : "无权限"} detail={canViewInventory ? `库存行 ${inventorySummary?.rows ?? 0}` : "库存快照不可见"} icon={Package} tone={Number(inventorySummary?.negative_rows ?? 0) > 0 ? "bad" : "neutral"} />
        <ContextSummaryCard label="库存成本" value={canViewInventory ? formatMoney(inventorySummary?.cost_amount) : "无权限"} detail={canViewInventory ? `锁定行 ${inventorySummary?.locked_rows ?? 0}` : "库存快照不可见"} icon={Database} tone={Number(inventorySummary?.abnormal_rows ?? 0) > 0 ? "warn" : "neutral"} />
      </div>

      {canViewSales ? (
        <ContextInlineTable<SalesDetailRow>
          title="最近销售明细"
          description="从商品维度直接查看近期销售客户、数量、金额和毛利。"
          rows={salesPage?.items ?? []}
          columns={[
            { key: "document_date", label: "日期", render: (row) => formatDate(row.document_date) },
            { key: "customer_name", label: "客户" },
            { key: "sale_qty_base", label: "数量", render: (row) => formatNumber(row.sale_qty_base) },
            { key: "amount_tax_total", label: "价税合计", render: (row) => formatMoney(row.amount_tax_total) },
            { key: "gross_profit", label: "毛利", render: (row) => formatMoney(row.gross_profit) },
            { key: "warehouse_name", label: "仓库" }
          ]}
          emptyMessage="当前商品暂无可展示的销售明细。"
        />
      ) : null}

      {canViewPurchase ? (
        <ContextInlineTable<PurchaseDetailRow>
          title="最近采购明细"
          description="从商品维度直接查看近期采购供应商、数量、金额和入库仓库。"
          rows={purchasePage?.items ?? []}
          columns={[
            { key: "document_date", label: "日期", render: (row) => formatDate(row.document_date) },
            { key: "supplier_name", label: "供应商" },
            { key: "purchase_qty_base", label: "数量", render: (row) => formatNumber(row.purchase_qty_base) },
            { key: "unit_price", label: "单价", render: (row) => formatMoney(row.unit_price) },
            { key: "amount_tax_total", label: "价税合计", render: (row) => formatMoney(row.amount_tax_total) },
            { key: "warehouse_name", label: "仓库" }
          ]}
          emptyMessage="当前商品暂无可展示的采购明细。"
        />
      ) : null}

      {canViewInventory ? (
        <ContextInlineTable<InventorySnapshotRow>
          title="库存快照"
          description="查看当前商品库存、锁定、成本和默认供货商。"
          rows={inventoryPage?.items ?? []}
          columns={[
            { key: "data_date", label: "日期", render: (row) => formatDate(row.data_date) },
            { key: "default_supplier", label: "默认供货商" },
            { key: "stock_qty", label: "账面数量", render: (row) => formatNumber(row.stock_qty) },
            { key: "stock_inventory_qty", label: "库存数量", render: (row) => formatNumber(row.stock_inventory_qty) },
            { key: "locked_base_qty", label: "锁定", render: (row) => formatNumber(row.locked_base_qty) },
            { key: "cost_amount", label: "成本金额", render: (row) => formatMoney(row.cost_amount) }
          ]}
          emptyMessage="当前商品暂无可展示的库存快照。"
        />
      ) : null}

      <div className="flex flex-wrap justify-end gap-2">
        {canViewSales ? (
          <Button secondary onClick={() => jumpTools.openProcessPage("sales", { product_code: productCode, q: productCode ? undefined : productName })}>
            打开完整销售明细
          </Button>
        ) : null}
        {canViewPurchase ? (
          <Button secondary onClick={() => jumpTools.openProcessPage("purchase", { product_code: productCode, q: productCode ? undefined : productName })}>
            打开完整采购明细
          </Button>
        ) : null}
        {canViewInventory ? (
          <Button secondary onClick={() => jumpTools.openProcessPage("inventory", { product_code: productCode, q: productCode ? undefined : productName })}>
            打开完整库存快照
          </Button>
        ) : null}
      </div>
    </div>
  );
}

