type ProcessDetailKind = "sales" | "purchase" | "inventory" | "account";
type ProcessDetailContextRow = SalesDetailRow | PurchaseDetailRow | InventorySnapshotRow | AccountBalanceRow;

function ProcessDetailContextPanel({
  kind,
  row,
  permissions,
  jumpTools
}: {
  kind: ProcessDetailKind;
  row: ProcessDetailContextRow;
  permissions: PermissionCode[];
  jumpTools: BusinessJumpTools;
}) {
  const source = row as Record<string, unknown>;
  const canViewSales = hasPermission(permissions, "sales_detail.view");
  const canViewPurchase = hasPermission(permissions, "purchase_detail.view");
  const canViewInventory = hasPermission(permissions, "inventory_snapshot.view");
  const canViewBalance = hasPermission(permissions, "account_balance.view");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [contextResult, setContextResult] = useState<ProcessDetailContextResult | null>(null);
  const [refreshKey, setRefreshKey] = useState(0);

  const customerCode = businessFilterValue(source.customer_code);
  const customerName = businessFilterValue(source.customer_name);
  const supplierCode = businessFilterValue(source.supplier_code);
  const supplierName = businessFilterValue(source.supplier_name ?? source.default_supplier);
  const productCode = businessFilterValue(source.product_code);
  const productName = businessFilterValue(source.product_name);
  const settlementCode = businessFilterValue(source.settlement_unit_code ?? source.customer_code ?? source.supplier_code);
  const settlementName = businessFilterValue(source.settlement_unit_name ?? source.customer_name ?? source.supplier_name);
  const unitName = businessFilterValue(source.settlement_unit_name);
  const unitCode = businessFilterValue(source.settlement_unit_code);
  const querySignature = [
    kind,
    customerCode,
    customerName,
    supplierCode,
    supplierName,
    productCode,
    productName,
    settlementCode,
    settlementName,
    unitCode,
    unitName
  ].join("|");

  useEffect(() => {
    let ignore = false;
    setContextResult(null);
    setError("");
    setLoading(true);
    void processDetailContext({
      kind,
      limit: 4,
      customerCode,
      customerName,
      supplierCode,
      supplierName,
      productCode,
      productName,
      settlementCode,
      settlementName,
      unitCode,
      unitName
    })
      .then((result) => {
        if (!ignore) setContextResult(result);
      })
      .catch(() => {
        if (!ignore) setError("关联上下文加载失败，可以稍后重试或打开完整过程表查看。");
      })
      .finally(() => {
        if (!ignore) setLoading(false);
      });
    return () => {
      ignore = true;
    };
  }, [querySignature, refreshKey]);

  const salesPage = contextResult?.sales.page ?? null;
  const purchasePage = contextResult?.purchase.page ?? null;
  const inventoryPage = contextResult?.inventory.page ?? null;
  const balancePage = contextResult?.account.page ?? null;
  const salesAvailable = contextResult?.sales.available ?? canViewSales;
  const purchaseAvailable = contextResult?.purchase.available ?? canViewPurchase;
  const inventoryAvailable = contextResult?.inventory.available ?? canViewInventory;
  const balanceAvailable = contextResult?.account.available ?? canViewBalance;
  const contextLoaded = contextResult !== null;
  const filterItems = [
    { label: "客户", value: customerCode ?? customerName },
    { label: "供应商", value: supplierCode ?? supplierName },
    { label: "商品", value: productCode ?? productName },
    { label: "结算单位", value: settlementCode ?? settlementName ?? unitCode ?? unitName }
  ];
  const statusItems = [
    { label: "销售", available: salesAvailable, total: salesPage?.total, preview: salesPage?.items.length },
    { label: "采购", available: purchaseAvailable, total: purchasePage?.total, preview: purchasePage?.items.length },
    { label: "库存", available: inventoryAvailable, total: inventoryPage?.total, preview: inventoryPage?.items.length },
    { label: "往来", available: balanceAvailable, total: balancePage?.total, preview: balancePage?.items.length }
  ];

  const canSeeAnyContext =
    (salesAvailable && salesPage !== null)
    || (purchaseAvailable && purchasePage !== null)
    || (inventoryAvailable && inventoryPage !== null)
    || (balanceAvailable && balancePage !== null)
    || loading;

  if (!canViewSales && !canViewPurchase && !canViewInventory && !canViewBalance) {
    return <CustomerEmptyPanel title="关联上下文不可见" description="当前账号没有相关过程数据权限，无法在详情抽屉内聚合展示。" />;
  }

  return (
    <section className="grid gap-4 rounded-lg border border-slate-200 bg-white p-4">
      <div className="flex flex-col gap-2 md:flex-row md:items-start md:justify-between">
        <div className="min-w-0">
          <p className="m-0 text-xs font-black uppercase tracking-[0.16em] text-primary">RELATED CONTEXT</p>
          <h4 className="m-0 mt-1 text-base font-black text-slate-950">关联上下文</h4>
          <p className="m-0 mt-1 text-sm font-bold leading-6 text-slate-500">在当前详情内直接查看相关销售、采购、库存和往来摘要，减少来回跳转。</p>
        </div>
        <div className="flex shrink-0 flex-wrap items-center gap-2">
          {loading ? <Badge tone="warn">加载中</Badge> : error ? <Badge tone="warn">部分异常</Badge> : <Badge tone={canSeeAnyContext ? "ok" : "neutral"}>{canSeeAnyContext ? "已聚合" : "暂无数据"}</Badge>}
          <Button secondary disabled={loading} onClick={() => setRefreshKey((key) => key + 1)}>
            <RefreshCcw className="mr-1.5 h-4 w-4" />
            刷新
          </Button>
        </div>
      </div>
      <ContextFilterChips items={filterItems} />
      {error ? <ContextNotice tone="warn" title="关联上下文加载异常" description={error} /> : null}
      {!error && contextLoaded && !canSeeAnyContext ? (
        <ContextNotice title="暂无命中的关联数据" description="系统已按当前明细字段完成聚合查询，但销售、采购、库存和往来暂时没有可展示记录。" />
      ) : null}
      <ContextBlockStatusGrid items={statusItems} />
      <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-4">
        <ContextSummaryCard label="相关销售" value={salesAvailable ? formatMoney(salesPage?.summary.amount_tax_total) : "无权限"} detail={salesAvailable ? `${salesPage?.summary.rows ?? 0} 行 / ${salesPage?.summary.documents ?? 0} 单` : "销售明细不可见"} icon={CircleDollarSign} />
        <ContextSummaryCard label="相关采购" value={purchaseAvailable ? formatMoney(purchasePage?.summary.amount_tax_total ?? purchasePage?.summary.purchase_amount) : "无权限"} detail={purchaseAvailable ? `${purchasePage?.summary.rows ?? 0} 行 / ${purchasePage?.summary.documents ?? 0} 单` : "采购明细不可见"} icon={ClipboardList} />
        <ContextSummaryCard label="相关库存" value={inventoryAvailable ? formatNumber(inventoryPage?.summary.stock_qty) : "无权限"} detail={inventoryAvailable ? `成本 ${formatMoney(inventoryPage?.summary.cost_amount)}` : "库存快照不可见"} icon={Package} tone={Number(inventoryPage?.summary.abnormal_rows ?? 0) > 0 ? "warn" : "neutral"} />
        <ContextSummaryCard label="相关往来" value={balanceAvailable ? formatMoney(balancePage?.summary.current_closing_balance) : "无权限"} detail={balanceAvailable ? `应收 ${formatMoney(balancePage?.summary.ar_balance)} / 应付 ${formatMoney(balancePage?.summary.ap_balance)}` : "往来对账不可见"} icon={Building2} />
      </div>

      {salesAvailable ? <ProcessContextSalesTable page={salesPage} loading={loading} /> : null}
      {purchaseAvailable ? <ProcessContextPurchaseTable page={purchasePage} loading={loading} /> : null}
      {inventoryAvailable ? <ProcessContextInventoryTable page={inventoryPage} loading={loading} /> : null}
      {balanceAvailable ? <ProcessContextBalanceTable page={balancePage} loading={loading} /> : null}

      <div className="flex flex-wrap justify-end gap-2">
        {canViewSales ? (
          <Button secondary onClick={() => jumpTools.openProcessPage("sales", { customer_code: customerCode, product_code: productCode, q: kind === "account" ? unitName : undefined })}>打开完整销售明细</Button>
        ) : null}
        {canViewPurchase ? (
          <Button secondary onClick={() => jumpTools.openProcessPage("purchase", { supplier_code: supplierCode, product_code: productCode, q: kind === "account" ? unitName : undefined })}>打开完整采购明细</Button>
        ) : null}
        {canViewInventory ? (
          <Button secondary onClick={() => jumpTools.openProcessPage("inventory", { product_code: productCode, default_supplier: kind === "inventory" || kind === "purchase" ? supplierName : undefined })}>打开完整库存快照</Button>
        ) : null}
        {canViewBalance ? (
          <Button secondary onClick={() => jumpTools.openProcessPage("account-balance", { settlement_unit_code: settlementCode ?? unitCode, settlement_unit_name: settlementName ?? unitName })}>打开完整往来对账</Button>
        ) : null}
      </div>
    </section>
  );
}

