function ContextSummaryCard({
  label,
  value,
  detail,
  icon: Icon,
  tone = "neutral"
}: {
  label: string;
  value: React.ReactNode;
  detail: React.ReactNode;
  icon: LucideIcon;
  tone?: ContextTone;
}) {
  const toneClass =
    tone === "warn"
      ? "border-amber-200 bg-amber-50"
      : tone === "bad"
        ? "border-red-200 bg-red-50"
        : tone === "ok"
          ? "border-emerald-200 bg-emerald-50"
          : "border-border bg-card";
  return (
    <section className={`min-w-0 rounded-lg border p-3 shadow-card ${toneClass}`}>
      <div className="flex items-center gap-2">
        <span className="grid h-8 w-8 shrink-0 place-items-center rounded-md bg-muted text-primary ring-1 ring-border">
          <Icon className="h-4 w-4" />
        </span>
        <span className="truncate text-xs font-black text-muted-foreground">{label}</span>
      </div>
      <strong className="mt-2 block truncate text-xl font-black text-foreground">{value}</strong>
      <span className="mt-1 block truncate text-xs font-bold text-muted-foreground">{detail}</span>
    </section>
  );
}

type CustomerActivity = {
  title: string;
  detail: string;
  time: string;
  tone: "ok" | "warn" | "bad" | "neutral";
};

function buildCustomerActivities(customer: MasterRow, extraActivity?: CustomerActivity | null): CustomerActivity[] {
  const activities: CustomerActivity[] = [];
  if (extraActivity) activities.push(extraActivity);
  const completeness = displayValue(customer.base_info_completeness);
  if (completeness !== "完整" && completeness !== "-") {
    activities.push({
      title: "资料完整度提醒",
      detail: `当前客户基础资料为「${completeness}」，建议补齐后再开展后续业务。`,
      time: formatDateTime(customer.updated_at ?? customer.profile_updated_at),
      tone: "warn"
    });
  }
  activities.push({
    title: "导入更新",
    detail: `客户档案已进入主数据中心，客户类型为「${displayValue(customer.customer_type)}」，所属区域为「${displayValue(customer.region)}」。`,
    time: formatDateTime(customer.profile_updated_at ?? customer.created_at ?? customer.updated_at),
    tone: "ok"
  });
  if (customer.salesperson_name || customer.historical_salespersons || getCustomerBillingClerk(customer)) {
    activities.push({
      title: "关联职员",
      detail: `业务员：${formatEmployeeNames(customer.salesperson_name)}；开单员：${displayValue(getCustomerBillingClerk(customer))}；历史业务员：${displayValue(customer.historical_salespersons)}。`,
      time: formatDateTime(customer.updated_at ?? customer.profile_updated_at),
      tone: "neutral"
    });
  }
  if (customer.contact_phone || customer.contact_name) {
    activities.push({
      title: "联系人资料",
      detail: `联系人：${displayValue(customer.contact_name)}；联系电话：${displayValue(customer.contact_phone)}。`,
      time: formatDateTime(customer.profile_updated_at ?? customer.updated_at),
      tone: "neutral"
    });
  }
  return activities;
}

function displayValue(value: unknown) {
  if (value === null || value === undefined || value === "") return "-";
  if (Array.isArray(value)) return value.length > 0 ? value.map((item) => String(item).trim()).filter(Boolean).join("、") : "-";
  return String(value);
}

function crmProjectPurposeText(value: unknown) {
  const purpose = String(value ?? "").trim();
  return purpose || "未填写";
}

function customerUpdateSourceLabel(value: unknown) {
  const normalized = String(value ?? "").trim();
  if (!normalized) return "-";
  const labels: Record<string, string> = {
    crm_approval: "CRM审批同步",
    manual: "手动编辑",
    import: "导入更新",
    imported: "导入更新",
    system: "系统生成"
  };
  return labels[normalized] ?? normalized;
}

function parseTagText(value: string) {
  return value
    .replace(/[，、；;|\n\t/\\]+/g, ",")
    .split(",")
    .map((item) => item.trim())
    .filter(Boolean)
    .filter((item, index, array) => array.indexOf(item) === index)
    .slice(0, 20);
}

function splitEmployeeNames(value: unknown) {
  const text = displayValue(value);
  if (text === "-") return [];
  return text
    .split(/[、,，;；/]+/)
    .map((item) => item.trim())
    .filter(Boolean);
}

function formatEmployeeNames(value: unknown) {
  const names = splitEmployeeNames(value);
  return names.length > 0 ? names.join("、") : "-";
}

function getCustomerBillingClerk(customer: MasterRow) {
  return customer.billing_clerk_name ?? customer.billing_clerk ?? customer.invoice_clerk_name ?? customer.order_clerk_name ?? null;
}

function MasterDataImportDrawer({
  defaultKind,
  visibleKinds,
  permissions,
  initialContext,
  onClose,
  onCommitted
}: {
  defaultKind: MasterKind;
  visibleKinds: MasterKind[];
  permissions: PermissionCode[];
  initialContext?: ImportDrawerContext | null;
  onClose: () => void;
  onCommitted: () => void;
}) {
  const canViewBatches = hasPermission(permissions, "import.view");
  const canUpload = hasPermission(permissions, "import.upload");
  const canCommit = hasPermission(permissions, "import.commit");
  const canUseFileType = (targetFileType: string) => {
    if (blockedGenericImportTypes.has(targetFileType)) return false;
    const requiredPermission = importFileTypeExtraPermissions[targetFileType];
    return !requiredPermission || hasPermission(permissions, requiredPermission);
  };
  const availableProcessImportTypes = processImportTypes.filter((type) => !type.permission || hasPermission(permissions, type.permission));
  const selectableKinds = visibleKinds.length > 0 ? visibleKinds : (Object.keys(masterKinds) as MasterKind[]);
  const initialKind = selectableKinds.includes(defaultKind) ? defaultKind : selectableKinds[0] ?? "customers";
  const [selectedKind, setSelectedKind] = useState<MasterKind>(initialKind);
  const contextKind = initialContext?.fileType ? masterKindByImportFileType[initialContext.fileType] : undefined;
  const initialFileType = initialContext?.fileType && canUseFileType(initialContext.fileType)
    ? initialContext.fileType
    : importFileTypeByKind[contextKind ?? initialKind];
  const [selectedFileType, setSelectedFileType] = useState<string>(initialFileType);
  const [dataDate, setDataDate] = useState(initialContext?.dataDate ?? "");
  const [systemDateMessage, setSystemDateMessage] = useState(initialContext?.dataDate ? `当前导入日期：${initialContext.dataDate}，可手动修改。` : "");
  const [dataDateAuto, setDataDateAuto] = useState(false);
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [current, setCurrent] = useState<ImportBatch | null>(null);
  const [rows, setRows] = useState<ImportBatch[]>([]);
  const [errors, setErrors] = useState<ImportErrorRow[]>([]);
  const [masterIssues, setMasterIssues] = useState<MasterLinkIssue[]>([]);
  const [quickCreateIssue, setQuickCreateIssue] = useState<MasterLinkIssue | null>(null);
  const [message, setMessage] = useState("选择主数据类型并上传文件。");
  const [loading, setLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<"flow" | "history">(initialContext?.activeTab ?? "flow");
  const fileType = selectedFileType;
  const canUseSelectedFileType = canUseFileType(fileType);
  const canUploadSelectedFileType = canUpload && canUseSelectedFileType;
  const canCommitCurrentBatch = canCommit && (!current || canUseFileType(current.file_type));

  const loadBatches = async () => {
    if (!canViewBatches) {
      setRows([]);
      return;
    }
    const batchRows = await batches(initialContext?.dataDate ? { data_date_from: initialContext.dataDate, data_date_to: initialContext.dataDate, limit: 1000 } : {});
    setRows(batchRows);
    if (initialContext?.batchId) {
      const matched = batchRows.find((batch) => batch.id === initialContext.batchId);
      if (matched) await selectBatch(matched, "context");
    }
  };

  const loadErrors = async (batch: ImportBatch) => {
    if (!canViewBatches || batch.error_rows <= 0) {
      setErrors([]);
      return;
    }
    setErrors(await importErrors(batch.id));
  };

  const loadMasterIssues = async (batch: ImportBatch | null) => {
    if (!batch || !canViewBatches) {
      setMasterIssues([]);
      return;
    }
    if (!["sales_detail", "purchase_detail", "account_ledger"].includes(batch.file_type)) {
      setMasterIssues([]);
      return;
    }
    setMasterIssues(await batchMasterLinkIssues(batch.id));
  };

  useEffect(() => {
    void loadBatches().catch(() => setRows([]));
  }, [canViewBatches]);

  useEffect(() => {
    if (initialContext?.fileType) {
      if (blockedGenericImportTypes.has(initialContext.fileType)) {
        setMessage(genericImportBlockedMessage(initialContext.fileType));
        return;
      }
      if (!canUseFileType(initialContext.fileType)) {
        setMessage(`当前账号缺少 ${importFileTypeExtraPermissions[initialContext.fileType]} 权限，不能处理${importTypeLabels[initialContext.fileType] ?? "该类型"}导入。`);
        return;
      }
      const resolvedKind = masterKindByImportFileType[initialContext.fileType];
      if (resolvedKind && selectableKinds.includes(resolvedKind)) setSelectedKind(resolvedKind);
      setSelectedFileType(initialContext.fileType);
      if (initialContext.dataDate) {
        setDataDate(initialContext.dataDate);
        setSystemDateMessage(`当前导入日期：${initialContext.dataDate}，可手动修改。`);
        setDataDateAuto(false);
      }
      if (initialContext.activeTab) setActiveTab(initialContext.activeTab);
      return;
    }
    const nextKind = selectableKinds.includes(defaultKind) ? defaultKind : selectableKinds[0] ?? "customers";
    setSelectedKind(nextKind);
    setSelectedFileType(importFileTypeByKind[nextKind]);
  }, [defaultKind, selectableKinds.join("|"), initialContext?.fileType, initialContext?.dataDate, initialContext?.activeTab]);

  const upload = async () => {
    if (!selectedFile) {
      setMessage("请选择要导入的 csv、xls 或 xlsx 文件。");
      return;
    }
    if (!canUseSelectedFileType) {
      if (blockedGenericImportTypes.has(fileType)) {
        setMessage(genericImportBlockedMessage(fileType));
        return;
      }
      setMessage(`当前账号缺少 ${importFileTypeExtraPermissions[fileType]} 权限，不能上传${importTypeLabels[fileType] ?? "该类型"}。`);
      return;
    }
    setLoading(true);
    setMessage("正在上传文件并创建导入批次。");
    try {
      const form = new FormData();
      if (dataDate) form.set("data_date", dataDate);
      form.set("file", selectedFile);
      form.set("file_type", fileType);
      const submittedDataDate = dataDate;
      const submittedDataDateAuto = dataDateAuto;
      const batch = await uploadImport(form);
      const resolvedKind = masterKindByImportFileType[batch.file_type];
      if (resolvedKind) setSelectedKind(resolvedKind);
      setSelectedFileType(batch.file_type);
      setCurrent(batch);
      if (batch.data_date) {
        const nextDataDate = String(batch.data_date).slice(0, 10);
        setDataDate(nextDataDate);
        const nextAuto = !submittedDataDate || submittedDataDateAuto;
        setDataDateAuto(nextAuto);
        setSystemDateMessage(nextAuto ? `系统识别日期：${nextDataDate}，可手动修改。` : `当前导入日期：${nextDataDate}，可手动修改。`);
      } else {
        setDataDateAuto(false);
        setSystemDateMessage("系统暂未识别到日期，请手动选择数据日期。");
      }
      setMessage(
        batch.file_type !== fileType
          ? `已上传批次 ${batch.batch_no}，系统按表头自动识别为${importTypeLabels[batch.file_type] ?? batch.file_type}，可继续预校验。`
          : `已上传批次 ${batch.batch_no}，可继续预校验。`
      );
      setActiveTab("flow");
      await loadBatches();
      await loadErrors(batch);
      await loadMasterIssues(batch);
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "上传失败");
    } finally {
      setLoading(false);
    }
  };

  const validate = async () => {
    if (!current) return;
    setLoading(true);
    setMessage("正在执行预校验。");
    try {
      const batch = await validateImport(current.id);
      setCurrent(batch);
      const issues = await batchMasterLinkIssues(batch.id);
      setMasterIssues(issues);
      setMessage(batch.error_rows > 0 ? `校验完成，发现 ${batch.error_rows} 行错误。` : issues.length > 0 ? `校验通过，但发现 ${issues.length} 个待补主档提醒，可继续提交入库。` : "校验通过，可以提交入库。");
      await loadBatches();
      await loadErrors(batch);
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "校验失败");
    } finally {
      setLoading(false);
    }
  };

  const commit = async () => {
    if (!current) return;
    setLoading(true);
    setMessage("正在提交入库。");
    try {
      const batch = await commitImport(current.id);
      setCurrent(batch);
      setMessage(batch.status === "committed" ? "提交入库完成，数据已刷新。" : `当前批次状态：${batch.status}`);
      await loadBatches();
      await loadErrors(batch);
      await loadMasterIssues(batch);
      if (batch.status === "committed") onCommitted();
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "提交失败");
    } finally {
      setLoading(false);
    }
  };

  const selectBatch = async (batch: ImportBatch, source: "user" | "context" = "user") => {
    setCurrent(batch);
    if (blockedGenericImportTypes.has(batch.file_type)) {
      setMessage("该批次是库存相关历史数据；库存文件现在请在「库存快照 -> 库存校验」入口处理。");
      setActiveTab("flow");
      await loadErrors(batch);
      return;
    }
    const resolvedKind = masterKindByImportFileType[batch.file_type];
    if (resolvedKind) setSelectedKind(resolvedKind);
    setSelectedFileType(batch.file_type);
    setDataDate(batchDateKey(batch) || dataDate);
    setMessage(source === "context" ? `已从数据日历定位到批次 ${batch.batch_no}。` : `已切换到历史批次 ${batch.batch_no}。`);
    setActiveTab("flow");
    await loadErrors(batch);
    await loadMasterIssues(batch);
  };

  const refreshCurrentMasterIssues = async () => {
    if (!current) return;
    await rebuildMasterLinkIssues(current.id);
    await loadMasterIssues(current);
    await loadBatches();
  };

  const recentRows = rows.slice(0, 12);

  return (
    <Drawer title="主数据导入" subtitle="在当前页完成上传、预校验、错误查看和提交入库。" onClose={onClose}>
      <div className="grid gap-4">
        <div className="flex flex-col gap-3 rounded-lg border border-slate-200 bg-muted p-4 lg:flex-row lg:items-center lg:justify-between">
          <div>
            <p className="m-0 text-sm font-black text-slate-900">导入流程</p>
            <p className="m-0 mt-1 text-sm text-slate-500">{message}</p>
          </div>
          <div className="flex flex-wrap gap-2">
            {["选择类型", "上传文件", "预校验", "提交入库"].map((step, index) => (
              <span key={step} className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-xs font-black text-slate-600">{index + 1}. {step}</span>
            ))}
          </div>
        </div>

        <div className="flex flex-wrap gap-2">
          <button type="button" onClick={() => setActiveTab("flow")} className={`rounded-lg border px-4 py-2 text-sm font-black ${activeTab === "flow" ? "border-primary bg-primary-soft text-primary" : "border-slate-200 bg-white text-slate-600"}`}>导入操作</button>
          <button type="button" onClick={() => setActiveTab("history")} className={`rounded-lg border px-4 py-2 text-sm font-black ${activeTab === "history" ? "border-primary bg-primary-soft text-primary" : "border-slate-200 bg-white text-slate-600"}`}>最近批次</button>
        </div>

        {activeTab === "flow" ? (
          <div className="grid gap-4">
            <section className="grid gap-4">
              <div className="rounded-lg border border-slate-200 bg-white p-4">
                <div className="grid gap-3 md:grid-cols-3">
                  <AccountField label="导入类型">
                    <select
                      value={selectedFileType}
                      onChange={(event) => {
                        const nextFileType = event.target.value;
                        const resolvedKind = masterKindByImportFileType[nextFileType];
                        if (resolvedKind) setSelectedKind(resolvedKind);
                        setSelectedFileType(nextFileType);
                      }}
                      className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold"
                    >
                      <optgroup label="主数据">
                        {selectableKinds.map((kind) => (
                          <option key={kind} value={importFileTypeByKind[kind]}>{masterKinds[kind].label}</option>
                        ))}
                      </optgroup>
                      <optgroup label="过程数据">
                        {availableProcessImportTypes.map((type) => <option key={type.value} value={type.value}>{type.label}</option>)}
                      </optgroup>
                    </select>
                  </AccountField>
                  <AccountField label="数据日期">
                    <input
                      value={dataDate}
                      onChange={(event) => {
                        setDataDate(event.target.value);
                        setDataDateAuto(false);
                        setSystemDateMessage(event.target.value ? `当前导入日期：${event.target.value}，可手动修改。` : "系统会在上传后尝试从文件名和表格日期字段识别。");
                      }}
                      type="date"
                      className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold"
                    />
                    {systemDateMessage ? <span className="text-xs font-bold text-primary">{systemDateMessage}</span> : <span className="text-xs font-bold text-slate-500">上传后会自动识别表单日期，可手动修改。</span>}
                  </AccountField>
                  <AccountField label="文件">
                    <input
                      type="file"
                      accept=".csv,.xls,.xlsx"
                      disabled={!canUploadSelectedFileType || loading}
                      onChange={(event) => {
                        const file = event.target.files?.[0] ?? null;
                        setSelectedFile(file);
                        if (!file) return;
                        const inferredType = inferImportFileTypeFromFileName(file.name);
                        const inferredDate = inferImportDataDateFromFileName(file.name);
                        const inferredKind = inferredType ? masterKindByImportFileType[inferredType] : null;
                        if (inferredType && blockedGenericImportTypes.has(inferredType)) {
                          setMessage(genericImportBlockedMessage(inferredType));
                          if (inferredDate) {
                            setDataDate(inferredDate);
                            setDataDateAuto(true);
                            setSystemDateMessage(`系统识别日期：${inferredDate}，可手动修改。`);
                          }
                          return;
                        }
                        if (inferredType) {
                          if (canUseFileType(inferredType)) {
                            setSelectedFileType(inferredType);
                          } else {
                            setMessage(`文件识别为${importTypeLabels[inferredType] ?? inferredType}，当前账号缺少 ${importFileTypeExtraPermissions[inferredType]} 权限。`);
                          }
                        }
                        if (inferredDate) {
                          setDataDate(inferredDate);
                          setDataDateAuto(true);
                          setSystemDateMessage(`系统从文件名识别日期：${inferredDate}，可手动修改。`);
                        } else {
                          setDataDate("");
                          setDataDateAuto(false);
                          setSystemDateMessage("文件名未识别到日期，上传后会继续读取表格内日期字段。");
                        }
                        if (inferredKind && selectableKinds.includes(inferredKind)) {
                          setSelectedKind(inferredKind);
                          setMessage(`已根据文件名识别为${masterKinds[inferredKind].label}，上传后仍会按表头再次校验。`);
                        } else if (inferredType) {
                          setMessage(`已根据文件名识别为${importTypeLabels[inferredType] ?? inferredType}，上传后仍会按表头再次校验。`);
                        }
                      }}
                      className="h-10 rounded-lg border border-slate-200 px-3 py-1.5 text-sm font-bold disabled:bg-slate-50"
                    />
                  </AccountField>
                </div>
                <div className="mt-3 grid gap-3">
                  <p className="m-0 min-w-0 truncate text-xs font-bold text-slate-500">
                    {selectedFile ? `${selectedFile.name} · ${(selectedFile.size / 1024).toFixed(1)} KB` : "支持 csv、xls、xlsx。"}
                  </p>
                  <MasterDataImportActionBar
                    loading={loading}
                    canUpload={canUploadSelectedFileType}
                    canValidate={canCommitCurrentBatch && Boolean(current)}
                    canCommit={canCommitCurrentBatch && Boolean(current) && (current?.error_rows ?? 0) <= 0}
                    hasBlockingErrors={(current?.error_rows ?? 0) > 0}
                    hasMasterIssues={masterIssues.length > 0}
                    onUpload={() => void upload()}
                    onValidate={() => void validate()}
                    onCommit={() => void commit()}
                  />
                </div>
              </div>

              <ImportBatchSummary batch={current} />
              <MasterLinkIssuePanel
                batch={current}
                issues={masterIssues}
                permissions={permissions}
                onQuickCreate={setQuickCreateIssue}
                onIgnored={async (issue) => {
                  await resolveMasterLinkIssue(issue.id, { resolution_type: "ignore", note: "导入提醒中忽略" });
                  await loadMasterIssues(current);
                }}
                onExport={() => exportMasterLinkIssues(masterIssues)}
              />
              <ImportErrorTable errors={errors} />
            </section>

            <aside className="grid content-start gap-3">
              <div className="rounded-lg border border-slate-200 bg-white p-4">
                <p className="m-0 text-sm font-black text-slate-900">导入口径</p>
                <div className="mt-3 grid gap-2 text-xs font-bold text-slate-500">
                  <div className="rounded-lg bg-slate-50 p-3">按字段别名自动识别列名。</div>
                  <div className="rounded-lg bg-slate-50 p-3">如果类型选错，系统会按表头自动纠偏。</div>
                  <div className="rounded-lg bg-slate-50 p-3">主数据按唯一编号新增或更新。</div>
                  <div className="rounded-lg bg-slate-50 p-3">文件空值不覆盖系统已有值；文件未提供字段保持原值。</div>
                  <div className="rounded-lg bg-slate-50 p-3">客户标签导入采用合并策略，不清空原有标签。</div>
                  <div className="rounded-lg bg-slate-50 p-3">先生成批次，再做预校验。</div>
                  <div className="rounded-lg bg-slate-50 p-3">错误行为 0 后才允许提交入库。</div>
                  <div className="rounded-lg bg-slate-50 p-3">提交成功后刷新当前主数据列表。</div>
                </div>
              </div>
              <RecentBatchList rows={recentRows} currentId={current?.id} onSelect={(batch) => void selectBatch(batch)} />
            </aside>
          </div>
        ) : (
          <BatchTable
            rows={rows}
            query=""
            statusFilter=""
            typeFilter=""
            onQueryChange={() => undefined}
            onStatusFilterChange={() => undefined}
            onTypeFilterChange={() => undefined}
            onReset={() => undefined}
            onSelect={(batch) => void selectBatch(batch)}
        />
      )}
      </div>
      {quickCreateIssue ? (
        <QuickMasterCreateDialog
          issue={quickCreateIssue}
          onClose={() => setQuickCreateIssue(null)}
          onCreated={async () => {
            setQuickCreateIssue(null);
            await refreshCurrentMasterIssues();
            onCommitted();
          }}
        />
      ) : null}
    </Drawer>
  );
}

const masterLinkIssueLabels: Record<string, string> = {
  missing_customer: "缺客户档案",
  missing_supplier: "缺供应商档案",
  missing_product: "缺商品档案",
  cross_role_customer_in_supplier: "客户存在于供应商档案",
  cross_role_supplier_in_customer: "供应商存在于客户档案",
  missing_settlement_unit: "结算单位未匹配"
};

const masterKindActionLabels: Record<string, string> = {
  customers: "新增客户档案",
  products: "新增商品档案",
  suppliers: "新增供应商档案",
  settlement_units: "补结算单位"
};

function MasterLinkIssuePanel({
  batch,
  issues,
  permissions,
  onQuickCreate,
  onIgnored,
  onExport
}: {
  batch: ImportBatch | null;
  issues: MasterLinkIssue[];
  permissions: PermissionCode[];
  onQuickCreate: (issue: MasterLinkIssue) => void;
  onIgnored: (issue: MasterLinkIssue) => Promise<void>;
  onExport: () => void;
}) {
  if (!batch || issues.length === 0) return null;
  const counts = issues.reduce<Record<string, number>>((acc, issue) => {
    acc[issue.issue_type] = (acc[issue.issue_type] ?? 0) + 1;
    return acc;
  }, {});
  return (
    <div className="rounded-lg border border-amber-200 bg-amber-50 p-4">
      <div className="flex flex-wrap items-start justify-between gap-3">
        <div>
          <p className="m-0 text-sm font-black text-amber-900">待补主档提醒</p>
          <p className="m-0 mt-1 text-sm font-bold text-amber-700">
            发现 {issues.length} 个主档匹配问题，不阻止提交入库，建议补齐后再复核上下文联动。
          </p>
        </div>
        <div className="flex flex-wrap gap-2">
          {Object.entries(counts).map(([key, value]) => <Badge key={key} tone="warn">{masterLinkIssueLabels[key] ?? key} {value}</Badge>)}
          <Button secondary onClick={onExport}>导出清单</Button>
        </div>
      </div>
      <div className="mt-3 overflow-x-auto rounded-lg border border-amber-100 bg-white">
        <table className="min-w-[920px] w-full border-collapse text-left text-sm">
          <thead className="bg-amber-50 text-xs font-black text-amber-700">
            <tr>
              <th className="px-3 py-2">问题</th>
              <th className="px-3 py-2">编码/名称</th>
              <th className="px-3 py-2">来源</th>
              <th className="px-3 py-2">影响</th>
              <th className="px-3 py-2">对方主档</th>
              <th className="px-3 py-2">操作</th>
            </tr>
          </thead>
          <tbody>
            {issues.slice(0, 8).map((issue) => {
              const canCreate = canCreateMasterForIssue(issue, permissions);
              return (
                <tr key={issue.id} className="border-t border-amber-100">
                  <td className="px-3 py-2 font-black text-slate-900">{masterLinkIssueLabels[issue.issue_type] ?? issue.issue_type}</td>
                  <td className="px-3 py-2">
                    <strong className="block text-slate-900">{displayValue(issue.reference_code)}</strong>
                    <span className="text-xs font-bold text-slate-500">{displayValue(issue.reference_name)}</span>
                  </td>
                  <td className="px-3 py-2 text-xs font-bold text-slate-500">
                    {importTypeLabels[issue.source_file_type] ?? issue.source_file_type}<br />
                    {formatDate(issue.first_seen_date)} - {formatDate(issue.last_seen_date)}
                  </td>
                  <td className="px-3 py-2 text-xs font-bold text-slate-500">
                    {issue.affected_rows} 行 / {issue.affected_documents} 单<br />
                    金额 {formatMoney(issue.amount_total)}
                  </td>
                  <td className="px-3 py-2 text-xs font-bold text-slate-500">
                    {issue.counterpart_master_kind ? `${masterKindActionLabels[issue.counterpart_master_kind] ?? issue.counterpart_master_kind.replace("s", "")}：${displayValue(issue.counterpart_code)} ${displayValue(issue.counterpart_name)}` : "-"}
                  </td>
                  <td className="px-3 py-2">
                    <div className="flex flex-wrap gap-2">
                      {canCreate ? <Button secondary onClick={() => onQuickCreate(issue)}>{masterIssueActionText(issue)}</Button> : null}
                      <Button secondary onClick={() => void onIgnored(issue)}>忽略</Button>
                    </div>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
      {issues.length > 8 ? <p className="m-0 mt-2 text-xs font-bold text-amber-700">已显示前 8 条，完整清单可导出查看。</p> : null}
    </div>
  );
}

function QuickMasterCreateDialog({ issue, onClose, onCreated }: { issue: MasterLinkIssue; onClose: () => void; onCreated: () => Promise<void> }) {
  const titleId = useId();
  const panelRef = useRef<HTMLDivElement | null>(null);
  const targetKind = issue.expected_master_kind;
  const [code, setCode] = useState(issue.reference_code ?? "");
  const [name, setName] = useState(issue.reference_name ?? "");
  const [category, setCategory] = useState("");
  const [region, setRegion] = useState("");
  const [unit, setUnit] = useState("");
  const [phone, setPhone] = useState("");
  const [address, setAddress] = useState("");
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const overlayLayer = useOverlayLayer({ kind: "modal", panelRef, onEscape: onClose });
  const unitPrice = estimateIssueUnitPrice(issue);

  const submit = async () => {
    if (!code.trim() || !name.trim()) {
      setError("编码和名称不能为空。");
      return;
    }
    setSaving(true);
    setError("");
    try {
      if (targetKind === "products") {
        const payload: ProductCreatePayload = {
          product_code: code.trim(),
          product_name: name.trim(),
          category: category.trim() || null,
          unit: unit.trim() || null,
          status: "active"
        };
        if (unitPrice && issue.source_file_type === "purchase_detail") payload.reference_cost = unitPrice;
        if (unitPrice && issue.source_file_type === "sales_detail") payload.reference_sale_price = unitPrice;
        await createProduct(payload);
      } else if (targetKind === "customers") {
        const payload: CustomerCreatePayload = {
          customer_code: code.trim(),
          customer_name: name.trim(),
          customer_type: "普通客户",
          region: region.trim() || null,
          contact_phone: phone.trim() || null,
          address: address.trim() || null,
          status: "active"
        };
        await createCustomer(payload);
      } else if (targetKind === "suppliers") {
        const payload: SupplierCreatePayload = {
          supplier_code: code.trim(),
          supplier_name: name.trim(),
          supplier_type: "普通供应商",
          region: region.trim() || null,
          contact_phone: phone.trim() || null,
          address: address.trim() || null,
          status: "active"
        };
        await createSupplier(payload);
      } else {
        setError("该类型暂不支持快速新增，请到主数据中手动维护。");
        return;
      }
      await onCreated();
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : "新增失败");
    } finally {
      setSaving(false);
    }
  };

  return (
    <OverlayPortal>
      <div
        className="fixed inset-0 grid place-items-center bg-slate-950/30 p-4"
        data-overlay-kind="modal"
        data-overlay-top={overlayLayer.isTop ? "true" : "false"}
        aria-hidden={overlayLayer.isTop ? undefined : true}
        inert={overlayLayer.isTop ? undefined : true}
        style={{ zIndex: overlayLayer.zIndex }}
      >
      <div
        ref={panelRef}
        role="dialog"
        aria-modal={overlayLayer.isTop ? "true" : undefined}
        aria-labelledby={titleId}
        tabIndex={-1}
        className="w-full max-w-xl rounded-lg border border-slate-200 bg-white p-5 shadow-xl"
      >
        <div className="flex items-start justify-between gap-3">
          <div>
            <p id={titleId} className="m-0 text-lg font-black text-slate-950">{masterIssueActionText(issue)}</p>
            <p className="m-0 mt-1 text-sm font-bold text-slate-500">从待补主档提醒创建，创建后会自动重新校验。</p>
          </div>
          <button type="button" onClick={onClose} className="grid h-9 w-9 place-items-center rounded-lg border border-slate-200 text-slate-500" aria-label="关闭" title="关闭"><X className="h-4 w-4" /></button>
        </div>
        {error ? <div className="mt-3 rounded-lg border border-red-100 bg-red-50 p-3 text-sm font-bold text-red-600">{error}</div> : null}
        <div className="mt-4 grid gap-3 md:grid-cols-2">
          <AccountField label="编码">
            <input value={code} onChange={(event) => setCode(event.target.value)} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold" />
          </AccountField>
          <AccountField label="名称">
            <input value={name} onChange={(event) => setName(event.target.value)} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold" />
          </AccountField>
          {targetKind === "products" ? (
            <>
              <AccountField label="分类">
                <input value={category} onChange={(event) => setCategory(event.target.value)} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold" />
              </AccountField>
              <AccountField label="单位">
                <input value={unit} onChange={(event) => setUnit(event.target.value)} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold" />
              </AccountField>
              {unitPrice ? <div className="md:col-span-2 rounded-lg bg-slate-50 p-3 text-sm font-bold text-slate-500">系统根据本次单据预填参考价：{formatMoney(unitPrice)}</div> : null}
            </>
          ) : (
            <>
              <AccountField label="区域">
                <input value={region} onChange={(event) => setRegion(event.target.value)} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold" />
              </AccountField>
              <AccountField label="联系电话">
                <input value={phone} onChange={(event) => setPhone(event.target.value)} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold" />
              </AccountField>
              <AccountField label="地址">
                <input value={address} onChange={(event) => setAddress(event.target.value)} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold md:col-span-2" />
              </AccountField>
            </>
          )}
        </div>
        <div className="mt-5 flex justify-end gap-2">
          <Button secondary onClick={onClose} disabled={saving}>取消</Button>
          <Button onClick={() => void submit()} disabled={saving}>{saving ? "保存中" : "保存主档"}</Button>
        </div>
      </div>
      </div>
    </OverlayPortal>
  );
}

function canCreateMasterForIssue(issue: MasterLinkIssue, permissions: PermissionCode[]) {
  if (issue.expected_master_kind === "customers") return hasPermission(permissions, "customer.edit");
  if (issue.expected_master_kind === "suppliers") return hasPermission(permissions, "supplier.edit");
  if (issue.expected_master_kind === "products") return hasPermission(permissions, "product.edit");
  return false;
}

function masterIssueActionText(issue: MasterLinkIssue) {
  if (issue.issue_type === "cross_role_customer_in_supplier") return "复制为客户";
  if (issue.issue_type === "cross_role_supplier_in_customer") return "复制为供应商";
  return masterKindActionLabels[issue.expected_master_kind] ?? "补主档";
}

function estimateIssueUnitPrice(issue: MasterLinkIssue) {
  const amount = Number(issue.amount_total ?? 0);
  const quantity = Number(issue.quantity_total ?? 0);
  if (!Number.isFinite(amount) || !Number.isFinite(quantity) || quantity === 0) return null;
  return Number((amount / quantity).toFixed(4));
}

function exportMasterLinkIssues(issues: MasterLinkIssue[]) {
  const headers = ["问题类型", "来源表", "编码", "名称", "影响行数", "影响单据", "金额", "数量", "首次日期", "最近日期", "对方主档", "对方编码", "对方名称"];
  const rows = issues.map((issue) => [
    masterLinkIssueLabels[issue.issue_type] ?? issue.issue_type,
    importTypeLabels[issue.source_file_type] ?? issue.source_file_type,
    issue.reference_code ?? "",
    issue.reference_name ?? "",
    String(issue.affected_rows ?? 0),
    String(issue.affected_documents ?? 0),
    String(issue.amount_total ?? ""),
    String(issue.quantity_total ?? ""),
    issue.first_seen_date ?? "",
    issue.last_seen_date ?? "",
    issue.counterpart_master_kind ?? "",
    issue.counterpart_code ?? "",
    issue.counterpart_name ?? ""
  ]);
  const csv = [headers, ...rows]
    .map((row) => row.map((cell) => `"${String(cell).replace(/"/g, '""')}"`).join(","))
    .join("\n");
  const blob = new Blob([`\ufeff${csv}`], { type: "text/csv;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = `待补主档清单-${new Date().toISOString().slice(0, 10)}.csv`;
  link.click();
  URL.revokeObjectURL(url);
}

function MasterRiskAlertCenter({
  permissions,
  onOpenMasterRecord
}: {
  permissions: PermissionCode[];
  onOpenMasterRecord: (kind: MasterKind, lookup: string) => void;
}) {
  const [page, setPage] = useState<DataQualityRiskAlertPage | null>(null);
  const [rules, setRules] = useState<DataQualityRiskRule[]>([]);
  const [level, setLevel] = useState("");
  const [category, setCategory] = useState("");
  const [query, setQuery] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");
  const [quickCreateIssue, setQuickCreateIssue] = useState<MasterLinkIssue | null>(null);
  const pageSize = 50;
  const canExport = hasPermission(permissions, "import.view");

  const categoryOptions = useMemo(() => {
    const values = Array.from(new Set(rules.map((rule) => rule.category).filter(Boolean)));
    return [{ value: "", label: "全部类别" }, ...values.map((value) => ({ value, label: value }))];
  }, [rules]);

  const loadRules = async () => {
    try {
      const result = await dataQualityRiskRules();
      setRules(result.items);
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "加载风险规则失败");
    }
  };

  const loadAlerts = async () => {
    setLoading(true);
    try {
      const result = await dataQualityRiskAlerts({
        level,
        category,
        limit: pageSize,
        offset: (currentPage - 1) * pageSize
      });
      setPage(result);
      setMessage("");
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "加载风险提示失败");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { void loadRules(); }, []);
  useEffect(() => { void loadAlerts(); }, [level, category, currentPage]);

  const rows = (page?.items ?? []).filter((item) =>
    includesKeyword([item.code, item.name, item.category, item.rule_name, item.reason, item.action], query)
  );
  const summary = page?.summary;
  const totalPages = Math.max(1, Math.ceil((page?.total ?? 0) / pageSize));
  const levelOptions = [
    { value: "", label: "全部等级" },
    { value: "warning", label: "警告" },
    { value: "risk", label: "风险" }
  ];
  const visibleRules = rules.filter((rule) => (!level || rule.level === level) && (!category || rule.category === category));

  const reset = () => {
    setLevel("");
    setCategory("");
    setQuery("");
    setCurrentPage(1);
  };

  const handleRiskAction = (item: DataQualityRiskAlert) => {
    if (canQuickCreateRiskAlert(item, permissions)) {
      setQuickCreateIssue(riskAlertToMasterLinkIssue(item));
      return;
    }
    const targetKind = riskAlertTargetMasterKind(item);
    if (targetKind) {
      onOpenMasterRecord(targetKind, String(item.code ?? item.name ?? ""));
      return;
    }
    const targetPath = riskAlertTargetPath(item);
    if (targetPath) {
      window.location.href = targetPath;
      return;
    }
    setMessage("该风险暂时没有可直达的处理入口，请按建议手动处理。");
  };

  const closeRiskAlert = async (item: DataQualityRiskAlert) => {
    const issueIds = riskAlertIssueIds(item);
    if (issueIds.length === 0) {
      setMessage("该风险没有可关闭的台账记录，请通过补齐数据或重新校验完成闭环。");
      return;
    }
    setLoading(true);
    setMessage("正在关闭风险。");
    try {
      for (const issueId of issueIds) {
        await resolveMasterLinkIssue(issueId, { resolution_type: "ignore", note: "风险提示页忽略关闭" });
      }
      setMessage(`已关闭 ${issueIds.length} 条风险记录。`);
      await loadAlerts();
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "关闭风险失败");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="grid gap-4">
      <Card className="p-5">
        <div className="flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between">
          <div>
            <p className="m-0 text-xs font-bold uppercase tracking-[0.12em] text-primary">DATA QUALITY RISK</p>
            <h2 className="m-0 mt-1 text-xl font-black text-slate-950">风险提示</h2>
          </div>
          <div className="flex flex-wrap gap-2">
            <Button secondary onClick={() => void loadAlerts()} disabled={loading}><RefreshCcw className="mr-1.5 h-4 w-4" />刷新</Button>
            {canExport ? <Button secondary onClick={() => exportRiskAlerts(rows)} disabled={rows.length === 0}><Download className="mr-1.5 h-4 w-4" />导出当前页</Button> : null}
          </div>
        </div>
        <div className="mt-4 grid gap-3 md:grid-cols-4">
          <InsightMetric label="警告" value={summary?.warning_count ?? "-"} tone={(summary?.warning_count ?? 0) > 0 ? "bad" : "ok"} />
          <InsightMetric label="风险" value={summary?.risk_count ?? "-"} tone={(summary?.risk_count ?? 0) > 0 ? "warn" : "ok"} />
          <InsightMetric label="规则" value={rules.length || "-"} tone="neutral" />
          <InsightMetric label="当前列表" value={page?.total ?? "-"} tone="neutral" />
        </div>
        {message ? <p className="m-0 mt-3 text-sm font-bold text-red-600">{message}</p> : null}
      </Card>

      <div className="grid gap-4 xl:grid-cols-[minmax(0,1fr)_360px]">
        <DataTableShell
          title="风险清单"
          meta={`${page?.total ?? 0} 条 / 当前显示 ${rows.length} 条`}
          toolbar={
            <DataToolbar onReset={reset}>
              <ToolbarSearch value={query} onChange={setQuery} placeholder="搜索编码、名称、规则或原因" />
              <ToolbarSelect value={level} onChange={(value) => { setCurrentPage(1); setLevel(value); }} label="等级" options={levelOptions} />
              <ToolbarSelect value={category} onChange={(value) => { setCurrentPage(1); setCategory(value); }} label="类别" options={categoryOptions} />
            </DataToolbar>
          }
          actions={
            <div className="flex items-center gap-2 text-sm font-bold text-slate-500">
              <span>第 {currentPage} / {totalPages} 页</span>
              <button type="button" className="project-button-secondary px-3" disabled={currentPage <= 1} onClick={() => setCurrentPage((value) => Math.max(1, value - 1))}>上一页</button>
              <button type="button" className="project-button-secondary px-3" disabled={currentPage >= totalPages} onClick={() => setCurrentPage((value) => Math.min(totalPages, value + 1))}>下一页</button>
            </div>
          }
        >
          <Table headers={["等级", "状态", "规则", "对象", "影响", "原因", "建议", "处理"]}>
            {rows.map((item, index) => (
              <tr key={`${item.rule_code}-${item.code ?? item.name ?? index}-${index}`}>
                <td><Badge tone={riskAlertTone(item.level)}>{riskAlertLevelLabel(item.level)}</Badge></td>
                <td>
                  <Badge tone={riskStatusTone(item.status)}>{item.status_label || riskStatusLabel(item.status)}</Badge>
                  {item.closure_hint ? <span className="mt-1 block max-w-[180px] text-xs font-bold leading-5 text-slate-500">{item.closure_hint}</span> : null}
                </td>
                <td>
                  <strong className="block text-slate-900">{item.rule_name}</strong>
                  <span className="mt-1 block text-xs font-bold text-slate-500">{item.category}</span>
                </td>
                <td>
                  <strong className="block text-slate-900">{displayValue(item.code)}</strong>
                  <span className="mt-1 block text-xs font-bold text-slate-500">{displayValue(item.name)}</span>
                </td>
                <td className="text-xs font-bold text-slate-500">
                  {item.affected_rows ? `${item.affected_rows} 行` : "-"}
                  {item.affected_amount ? <span className="block">金额 {formatMoney(item.affected_amount)}</span> : null}
                  {item.first_seen_date || item.last_seen_date ? <span className="block">{formatDate(item.first_seen_date)} - {formatDate(item.last_seen_date)}</span> : null}
                </td>
                <td className="max-w-[360px] text-sm font-bold leading-6 text-slate-600">{item.reason}</td>
                <td className="text-sm font-black text-primary">{item.action ?? "-"}</td>
                <td>
                  <div className="flex flex-wrap gap-2">
                    <button
                      type="button"
                      className="project-inline-action"
                      onClick={() => handleRiskAction(item)}
                    >
                      {riskAlertActionLabel(item, permissions)}
                    </button>
                    {canCloseRiskAlert(item, permissions) ? (
                      <button
                        type="button"
                        className="project-inline-action"
                        onClick={() => void closeRiskAlert(item)}
                      >
                        忽略关闭
                      </button>
                    ) : null}
                  </div>
                </td>
              </tr>
            ))}
          </Table>
          {!loading && rows.length === 0 ? <div className="rounded-lg bg-slate-50 p-4 text-sm font-bold text-slate-500">暂无符合条件的风险提示。</div> : null}
        </DataTableShell>

        <Card className="p-4">
          <div className="flex items-center justify-between gap-3">
            <div>
              <p className="m-0 text-xs font-bold uppercase tracking-[0.12em] text-primary">RULES</p>
              <h3 className="m-0 mt-1 text-base font-black text-slate-950">规则说明</h3>
            </div>
            <Badge tone="neutral">{visibleRules.length} 条</Badge>
          </div>
          <div className="mt-3 grid max-h-[640px] gap-2 overflow-auto pr-1">
            {visibleRules.map((rule) => (
              <article key={rule.rule_code} className="rounded-lg border border-slate-200 bg-white p-3">
                <div className="flex items-start justify-between gap-2">
                  <strong className="text-sm font-black text-slate-950">{rule.rule_name}</strong>
                  <Badge tone={riskAlertTone(rule.level)}>{riskAlertLevelLabel(rule.level)}</Badge>
                </div>
                <p className="m-0 mt-2 text-xs font-bold leading-5 text-slate-500">{rule.description}</p>
                <div className="mt-2 grid gap-1 text-xs font-bold text-slate-500">
                  <span>范围：{rule.scope}</span>
                  <span>建议：{rule.action}</span>
                </div>
              </article>
            ))}
            {visibleRules.length === 0 ? <div className="rounded-lg bg-slate-50 p-3 text-sm font-bold text-slate-500">暂无匹配规则。</div> : null}
          </div>
        </Card>
      </div>
      {quickCreateIssue ? (
        <QuickMasterCreateDialog
          issue={quickCreateIssue}
          onClose={() => setQuickCreateIssue(null)}
          onCreated={async () => {
            setQuickCreateIssue(null);
            if (hasPermission(permissions, "import.commit") && quickCreateIssue.source_file_type !== "inventory_check") {
              await rebuildMasterLinkIssues();
            }
            await loadAlerts();
          }}
        />
      ) : null}
    </div>
  );
}

function riskAlertTone(level: string): "ok" | "warn" | "bad" | "neutral" {
  if (level === "warning") return "bad";
  if (level === "risk") return "warn";
  return "neutral";
}

function riskStatusTone(status: string): "ok" | "warn" | "bad" | "neutral" {
  if (status === "resolved" || status === "closed") return "ok";
  if (status === "open") return "warn";
  return "neutral";
}

function riskStatusLabel(status: string) {
  if (status === "open") return "待处理";
  if (status === "resolved") return "已处理";
  if (status === "closed") return "已关闭";
  return status || "待处理";
}

function riskAlertTargetMasterKind(item: DataQualityRiskAlert): MasterKind | null {
  if (item.resource_type === "customer") return "customers";
  if (item.resource_type === "supplier") return "suppliers";
  if (item.resource_type === "product") return "products";
  return null;
}

function riskAlertTargetPath(item: DataQualityRiskAlert) {
  if (item.rule_code.startsWith("check.inventory_")) return "/inventory?tab=check";
  if (item.rule_code.startsWith("check.receivable_")) return "/account-balance?tab=check";
  return "";
}

function riskAlertActionLabel(item: DataQualityRiskAlert, permissions: PermissionCode[]) {
  if (canQuickCreateRiskAlert(item, permissions)) return item.resource_type === "product" ? "新增商品" : item.resource_type === "customer" ? "新增客户" : "新增供应商";
  if (riskAlertTargetMasterKind(item)) return "打开档案";
  if (item.rule_code.startsWith("check.inventory_")) return "去库存核验";
  if (item.rule_code.startsWith("check.receivable_")) return "去应收校验";
  return "查看规则";
}

function canQuickCreateRiskAlert(item: DataQualityRiskAlert, permissions: PermissionCode[]) {
  const isMissingMaster =
    item.rule_code === "master_link.missing_customer"
    || item.rule_code === "master_link.missing_supplier"
    || item.rule_code === "master_link.missing_product"
    || item.rule_code === "check.inventory_missing_product_master";
  if (!isMissingMaster || !item.code || !item.name) return false;
  if (item.resource_type === "customer") return hasPermission(permissions, "customer.edit");
  if (item.resource_type === "supplier") return hasPermission(permissions, "supplier.edit");
  if (item.resource_type === "product") return hasPermission(permissions, "product.edit");
  return false;
}

function riskAlertIssueIds(item: DataQualityRiskAlert) {
  const issueIds = item.metadata?.issue_ids;
  if (!Array.isArray(issueIds)) return [];
  return issueIds.filter((value): value is number => typeof value === "number" && Number.isFinite(value));
}

function canCloseRiskAlert(item: DataQualityRiskAlert, permissions: PermissionCode[]) {
  return item.source === "master_link_issue" && riskAlertIssueIds(item).length > 0 && hasPermission(permissions, "import.commit");
}

function riskAlertToMasterLinkIssue(item: DataQualityRiskAlert): MasterLinkIssue {
  const targetKind = item.resource_type === "customer" ? "customers" : item.resource_type === "supplier" ? "suppliers" : item.resource_type === "product" ? "products" : "settlement_units";
  const metadata = item.metadata ?? {};
  const sourceFileTypes = Array.isArray(metadata.source_file_types) ? metadata.source_file_types : [];
  const sourceFileType = typeof sourceFileTypes[0] === "string" ? sourceFileTypes[0] : item.source === "latest_inventory_check" ? "inventory_check" : "risk_alert";
  const issueType =
    item.rule_code === "master_link.missing_customer" ? "missing_customer"
      : item.rule_code === "master_link.missing_supplier" ? "missing_supplier"
        : item.rule_code === "master_link.missing_product" || item.rule_code === "check.inventory_missing_product_master" ? "missing_product"
          : "missing_settlement_unit";
  return {
    id: -Date.now(),
    batch_id: typeof metadata.batch_id === "number" ? metadata.batch_id : null,
    source_file_type: sourceFileType,
    issue_type: issueType,
    expected_master_kind: targetKind,
    reference_code: item.code ?? null,
    reference_name: item.name ?? null,
    counterpart_master_kind: typeof metadata.counterpart_master_kind === "string" ? metadata.counterpart_master_kind : null,
    counterpart_code: typeof metadata.counterpart_code === "string" ? metadata.counterpart_code : null,
    counterpart_name: typeof metadata.counterpart_name === "string" ? metadata.counterpart_name : null,
    first_seen_date: item.first_seen_date ?? null,
    last_seen_date: item.last_seen_date ?? null,
    affected_rows: item.affected_rows ?? 0,
    affected_documents: item.affected_documents ?? 0,
    amount_total: item.affected_amount ?? null,
    quantity_total: item.affected_quantity ?? null,
    status: "open",
    source_json: metadata
  };
}

function riskAlertLevelLabel(level: string) {
  if (level === "warning") return "警告";
  if (level === "risk") return "风险";
  return level;
}

function exportRiskAlerts(alerts: DataQualityRiskAlert[]) {
  const headers = ["等级", "状态", "规则", "类别", "对象类型", "编码", "名称", "影响行数", "影响单据", "金额", "数量", "首次日期", "最近日期", "原因", "建议", "闭环提示"];
  const rows = alerts.map((item) => [
    riskAlertLevelLabel(item.level),
    item.status_label || riskStatusLabel(item.status),
    item.rule_name,
    item.category,
    item.resource_type ?? "",
    item.code ?? "",
    item.name ?? "",
    String(item.affected_rows ?? 0),
    String(item.affected_documents ?? 0),
    item.affected_amount ?? "",
    item.affected_quantity ?? "",
    item.first_seen_date ?? "",
    item.last_seen_date ?? "",
    item.reason,
    item.action ?? "",
    item.closure_hint ?? ""
  ]);
  const csv = [headers, ...rows]
    .map((row) => row.map((cell) => `"${String(cell).replace(/"/g, '""')}"`).join(","))
    .join("\n");
  const blob = new Blob([`\ufeff${csv}`], { type: "text/csv;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = `风险提示清单-${new Date().toISOString().slice(0, 10)}.csv`;
  link.click();
  URL.revokeObjectURL(url);
}

function MasterLinkIssueCenter({ permissions, onChanged }: { permissions: PermissionCode[]; onChanged: () => void }) {
  const [page, setPage] = useState<MasterLinkIssuePage | null>(null);
  const [query, setQuery] = useState("");
  const [issueType, setIssueType] = useState("");
  const [kind, setKind] = useState("");
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");
  const [quickCreateIssue, setQuickCreateIssue] = useState<MasterLinkIssue | null>(null);
  const rows = page?.items ?? [];

  const load = async () => {
    setLoading(true);
    try {
      const result = await masterLinkIssues({
        q: query,
        issue_type: issueType,
        expected_master_kind: kind,
        status: "open",
        limit: 100
      });
      setPage(result);
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "加载主档匹配问题失败");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void load();
  }, [query, issueType, kind]);

  const rebuildAll = async () => {
    setLoading(true);
    setMessage("正在重建主档匹配问题。");
    try {
      const result = await rebuildMasterLinkIssues();
      setMessage(`重建完成：扫描 ${result.batches} 个批次，当前发现 ${result.issues} 个问题。`);
      await load();
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "重建失败");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="grid gap-4">
      <Card className="p-5">
        <div className="flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between">
          <div>
            <p className="m-0 text-xs font-bold uppercase tracking-[0.12em] text-primary">MASTER LINK QUALITY</p>
            <h2 className="m-0 mt-1 text-xl font-black text-slate-950">主档匹配问题</h2>
          </div>
          <div className="flex flex-wrap gap-2">
            <Button secondary onClick={() => exportMasterLinkIssues(rows)} disabled={rows.length === 0}>导出清单</Button>
            {hasPermission(permissions, "import.commit") ? <Button onClick={() => void rebuildAll()} disabled={loading}>重建校验</Button> : null}
          </div>
        </div>
        <div className="mt-4 grid gap-3 md:grid-cols-4">
          <InsightMetric label="待处理" value={page?.summary.total ?? 0} tone={(page?.summary.total ?? 0) > 0 ? "warn" : "ok"} />
          <InsightMetric label="缺客户" value={(page?.summary.missing_customer ?? 0) + (page?.summary.cross_role_customer_in_supplier ?? 0)} tone="neutral" />
          <InsightMetric label="缺供应商" value={(page?.summary.missing_supplier ?? 0) + (page?.summary.cross_role_supplier_in_customer ?? 0)} tone="neutral" />
          <InsightMetric label="缺商品" value={page?.summary.missing_product ?? 0} tone="neutral" />
        </div>
        {message ? <p className="m-0 mt-3 text-sm font-bold text-slate-500">{message}</p> : null}
      </Card>
      <DataTableShell
        title="待补清单"
        meta={`${page?.total ?? 0} 个问题`}
        toolbar={
          <DataToolbar onReset={() => { setQuery(""); setIssueType(""); setKind(""); }}>
            <ToolbarSearch value={query} onChange={setQuery} placeholder="搜索编码或名称" />
            <ToolbarSelect
              value={issueType}
              onChange={setIssueType}
              label="问题类型"
              options={[
                { value: "", label: "全部问题" },
                ...Object.entries(masterLinkIssueLabels).map(([value, label]) => ({ value, label }))
              ]}
            />
            <ToolbarSelect
              value={kind}
              onChange={setKind}
              label="主档类型"
              options={[
                { value: "", label: "全部主档" },
                { value: "customers", label: "客户档案" },
                { value: "suppliers", label: "供应商档案" },
                { value: "products", label: "商品档案" },
                { value: "settlement_units", label: "结算单位" }
              ]}
            />
          </DataToolbar>
        }
      >
        <Table headers={["问题", "编码", "名称", "来源", "影响", "对方主档", "操作"]}>
          {rows.map((issue) => (
            <tr key={issue.id}>
              <td>{masterLinkIssueLabels[issue.issue_type] ?? issue.issue_type}</td>
              <td className="font-black text-slate-900">{displayValue(issue.reference_code)}</td>
              <td>{displayValue(issue.reference_name)}</td>
              <td>{importTypeLabels[issue.source_file_type] ?? issue.source_file_type}</td>
              <td>{issue.affected_rows} 行 · {formatMoney(issue.amount_total)}</td>
              <td>{issue.counterpart_master_kind ? `${displayValue(issue.counterpart_code)} ${displayValue(issue.counterpart_name)}` : "-"}</td>
              <td>
                <div className="flex flex-wrap gap-2">
                  {canCreateMasterForIssue(issue, permissions) ? <button type="button" className="project-inline-action" onClick={() => setQuickCreateIssue(issue)}>{masterIssueActionText(issue)}</button> : null}
                  {hasPermission(permissions, "import.commit") ? (
                    <button
                      type="button"
                      className="project-inline-action"
                      onClick={async () => {
                        await resolveMasterLinkIssue(issue.id, { resolution_type: "ignore", note: "主档匹配问题页忽略" });
                        await load();
                      }}
                    >
                      忽略
                    </button>
                  ) : null}
                </div>
              </td>
            </tr>
          ))}
        </Table>
        {!loading && rows.length === 0 ? <div className="rounded-lg bg-slate-50 p-4 text-sm font-bold text-slate-500">暂无待补主档问题。</div> : null}
      </DataTableShell>
      {quickCreateIssue ? (
        <QuickMasterCreateDialog
          issue={quickCreateIssue}
          onClose={() => setQuickCreateIssue(null)}
          onCreated={async () => {
            setQuickCreateIssue(null);
            await load();
            onChanged();
          }}
        />
      ) : null}
    </div>
  );
}

function MasterDataImportActionBar({
  loading,
  canUpload,
  canValidate,
  canCommit,
  hasBlockingErrors,
  hasMasterIssues,
  onUpload,
  onValidate,
  onCommit
}: {
  loading: boolean;
  canUpload: boolean;
  canValidate: boolean;
  canCommit: boolean;
  hasBlockingErrors: boolean;
  hasMasterIssues: boolean;
  onUpload: () => void;
  onValidate: () => void;
  onCommit: () => void;
}) {
  return (
    <div className="sticky bottom-0 z-10 rounded-lg border border-slate-200 bg-white/95 p-3 shadow-sm backdrop-blur">
      <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
        <p className="m-0 text-xs font-bold text-slate-500">
          {hasBlockingErrors
            ? "存在错误行时不能提交入库。"
            : hasMasterIssues
              ? "待补主档仅作提醒，不阻止提交入库。"
              : "预校验通过后即可提交入库。"}
        </p>
        <div className="flex flex-wrap gap-2 sm:justify-end">
          <Button onClick={onUpload} disabled={!canUpload || loading}>上传</Button>
          <Button secondary onClick={onValidate} disabled={!canValidate || loading}>预校验</Button>
          <Button secondary onClick={onCommit} disabled={!canCommit || loading}>提交入库</Button>
        </div>
      </div>
    </div>
  );
}

function ImportBatchSummary({ batch }: { batch: ImportBatch | null }) {
  if (!batch) {
    return <div className="rounded-lg border border-dashed border-slate-200 bg-slate-50 p-5 text-sm font-bold text-slate-500">尚未生成导入批次。</div>;
  }
  return (
    <div className="rounded-lg border border-slate-200 bg-white p-4">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div>
          <p className="m-0 text-sm font-black text-slate-900">{batch.batch_no}</p>
          <p className="m-0 mt-1 text-xs text-slate-500">{importTypeLabels[batch.file_type] ?? batch.file_type} · {batch.file_name}</p>
        </div>
        <Badge tone={batch.status === "committed" ? "ok" : batch.error_rows > 0 ? "bad" : "warn"}>{batch.status}</Badge>
      </div>
      <div className="mt-4 grid gap-2 md:grid-cols-4">
        <InsightMetric label="总行数" value={batch.total_rows} tone="neutral" />
        <InsightMetric label="成功行" value={batch.success_rows} tone="ok" />
        <InsightMetric label="错误行" value={batch.error_rows} tone={batch.error_rows > 0 ? "bad" : "ok"} />
        <InsightMetric label="映射字段" value={Object.keys(batch.mapping_json ?? {}).length} tone="neutral" />
      </div>
    </div>
  );
}

function ImportErrorTable({ errors }: { errors: ImportErrorRow[] }) {
  if (errors.length === 0) {
    return <div className="rounded-lg border border-slate-200 bg-white p-4 text-sm font-bold text-slate-500">暂无错误行。校验后如有错误会在这里显示。</div>;
  }
  return (
    <DataTableShell title="错误行" description="预校验发现的问题需要先修正后重新上传。" meta={`${errors.length} 条`}>
      <Table headers={["行号", "类型", "错误原因", "原始数据"]}>
        {errors.slice(0, 50).map((row) => (
          <tr key={row.id}>
            <td>{row.row_number}</td>
            <td>{row.error_type}</td>
            <td>{row.error_message}</td>
            <td className="max-w-md truncate">{row.raw_row_json ? JSON.stringify(row.raw_row_json) : "-"}</td>
          </tr>
        ))}
      </Table>
    </DataTableShell>
  );
}

function RecentBatchList({ rows, currentId, onSelect }: { rows: ImportBatch[]; currentId?: number; onSelect: (batch: ImportBatch) => void }) {
  return (
    <div className="rounded-lg border border-slate-200 bg-white p-4">
      <p className="m-0 text-sm font-black text-slate-900">最近导入批次</p>
      <div className="mt-3 grid gap-2">
        {rows.length > 0 ? rows.map((row) => (
          <button
            key={row.id}
            type="button"
            onClick={() => onSelect(row)}
            className={`rounded-lg border p-3 text-left text-sm hover:bg-slate-50 ${currentId === row.id ? "border-primary bg-primary-soft" : "border-slate-200 bg-white"}`}
          >
            <strong className="block truncate text-slate-900">{row.batch_no}</strong>
            <span className="mt-1 block text-xs text-slate-500">{importTypeLabels[row.file_type] ?? row.file_type} · {row.status} · 错误 {row.error_rows}</span>
          </button>
        )) : <div className="rounded-lg bg-slate-50 p-3 text-sm font-bold text-slate-500">暂无导入批次。</div>}
      </div>
    </div>
  );
}

function renderMasterCell(column: string, value: MasterRow[string]) {
  if (column === "status") {
    const status = String(value ?? "active");
    const tone = status === "active" ? "ok" : status === "disabled" ? "warn" : "bad";
    return <Badge tone={tone}>{customerStatusLabels[status] ?? status}</Badge>;
  }
  if (column === "base_info_completeness") {
    const text = String(value ?? "-");
    return <Badge tone={text === "完整" ? "ok" : "warn"}>{text}</Badge>;
  }
  if (column === "portrait_summary") {
    const text = String(value ?? "-");
    if (text === "-") return <span className="text-slate-400">-</span>;
    return (
      <span className="inline-flex max-w-[240px] items-center truncate rounded-md bg-slate-50 px-2 py-1 text-xs font-black text-slate-600 ring-1 ring-slate-200">
        {text}
      </span>
    );
  }
  if (column === "crm_project_count") {
    const count = Number(value ?? 0);
    return <Badge tone={count > 0 ? "ok" : "neutral"}>{count > 0 ? `${count} 次` : "未分配"}</Badge>;
  }
  if (column === "missing_fields") {
    const fields = Array.isArray(value) ? value.map((item) => String(item)).filter(Boolean) : [];
    if (fields.length === 0) return <Badge tone="ok">资料完整</Badge>;
    return (
      <div className="flex max-w-[260px] flex-wrap gap-1">
        {fields.slice(0, 3).map((field) => <Badge key={field} tone={field.includes("经营") ? "neutral" : "warn"}>{field}</Badge>)}
        {fields.length > 3 ? <Badge tone="neutral">+{fields.length - 3}</Badge> : null}
      </div>
    );
  }
  if (column === "profile_updated_at") {
    return formatDateTime(value);
  }
  return Array.isArray(value) ? value.map(String).join("、") || "-" : value ?? "-";
}

function accountAttentionReasonLabel(reason: AttentionReason, row: AccountLedgerRow) {
  const values: Record<string, unknown> = {
    ar_non_zero: row.ar_amount,
    ap_non_zero: row.ap_amount,
    advance_receipt_non_zero: row.advance_receipt_amount,
    advance_payment_non_zero: row.advance_payment_amount
  };
  return Object.prototype.hasOwnProperty.call(values, reason.code) ? `${reason.label}（${formatMoney(values[reason.code])}）` : reason.label;
}

function isDateBeforeToday(value: unknown) {
  if (!value) return false;
  const dateKey = String(value).slice(0, 10);
  const now = new Date();
  const todayKey = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}-${String(now.getDate()).padStart(2, "0")}`;
  return dateKey < todayKey;
}

function inventoryAttentionReasonLabel(reason: AttentionReason, row: InventorySnapshotRow) {
  if (reason.code === "negative_stock") return `${reason.label}（账面数量 ${formatNumber(row.stock_qty)}）`;
  if (reason.code === "locked_stock") return `${reason.label}（锁定数量 ${formatNumber(row.locked_base_qty)}）`;
  return reason.label;
}

function formatDateTime(value: unknown) {
  if (!value) return "-";
  const date = new Date(String(value));
  if (Number.isNaN(date.getTime())) return String(value);
  return date.toLocaleString("zh-CN", { hour12: false });
}

const CRM_PROJECT_PAGE_SIZE = 50;
const CRM_WORK_ITEM_PAGE_SIZE = 50;

const crmProjectStatusLabels: Record<string, string> = {
  draft: "草稿",
  submitted: "已提交",
  active: "进行中",
  paused: "暂停",
  closed: "已闭环",
  cancelled: "已取消"
};

const crmApprovalStatusLabels: Record<string, string> = {
  draft: "草稿",
  submitted: "待审批",
  under_review: "审批中",
  need_supplement: "需补充",
  approved: "已通过",
  rejected: "已驳回",
  cancelled: "已取消",
  completed: "已完成"
};

function approvalUserLabel(approval: ApprovalRow, field: "applicant" | "handler") {
  const label = field === "applicant" ? approval.applicant_user_label : approval.current_handler_user_label;
  if (label) return label;
  const idValue = field === "applicant" ? approval.applicant_user_id : approval.current_handler_user_id;
  return idValue ? "账号信息缺失" : "未指定";
}

function canEditApprovalSubmission(approval: ApprovalRow, currentUser: UserPublic) {
  return ["draft", "need_supplement"].includes(approval.status) && approval.applicant_user_id === currentUser.id;
}

function approvalRowNextActionLabel(approval: ApprovalRow, currentUser: UserPublic) {
  if (canEditApprovalSubmission(approval, currentUser)) {
    return approval.status === "need_supplement" ? "补充并提交" : "继续编辑";
  }
  if (["submitted", "under_review"].includes(approval.status) && approval.current_handler_user_id === currentUser.id) return "去审批";
  if (["submitted", "under_review"].includes(approval.status)) return "等待审批";
  if (approval.status === "completed" || approval.status === "approved") return "查看结果";
  if (approval.status === "rejected") return "查看驳回";
  if (approval.status === "cancelled") return "已撤回";
  return "查看详情";
}

function approvalNextActionTone(approval: ApprovalRow, currentUser: UserPublic): ContextTone {
  if (canEditApprovalSubmission(approval, currentUser)) return approval.status === "need_supplement" ? "warn" : "neutral";
  if (["submitted", "under_review"].includes(approval.status) && approval.current_handler_user_id === currentUser.id) return "warn";
  if (approval.status === "completed" || approval.status === "approved") return "ok";
  if (approval.status === "rejected" || approval.status === "cancelled") return "bad";
  return "neutral";
}

function approvalReturnFeedbackPresentation(approval: ApprovalRow) {
  if (!['need_supplement', 'rejected'].includes(approval.status)) return null;
  const feedback = approval.latest_return_feedback;
  const isRejected = approval.status === 'rejected';
  return {
    title: isRejected ? '驳回原因' : '补充要求',
    reason: feedback?.comment?.trim() || '未填写具体原因，请联系审批人',
    operatorLabel: feedback?.operator_user_label || approval.current_handler_user_label || '审批人信息缺失',
    createdAt: feedback?.created_at ?? null,
    tone: isRejected ? 'bad' as ContextTone : 'warn' as ContextTone
  };
}

function ApprovalReturnFeedbackPanel({ approval }: { approval: ApprovalRow }) {
  const presentation = approvalReturnFeedbackPresentation(approval);
  if (!presentation) return null;
  const rejected = presentation.tone === 'bad';
  return (
    <section className={`rounded-lg border p-4 ${rejected ? 'border-red-200 bg-red-50' : 'border-amber-200 bg-amber-50'}`}>
      <div className="flex items-start gap-3">
        <FileWarning className={`mt-0.5 h-5 w-5 shrink-0 ${rejected ? 'text-red-600' : 'text-amber-600'}`} />
        <div className="min-w-0 flex-1">
          <div className="flex flex-wrap items-center justify-between gap-2">
            <h3 className={`m-0 text-sm font-black ${rejected ? 'text-red-800' : 'text-amber-800'}`}>{presentation.title}</h3>
            <Badge tone={presentation.tone}>{crmApprovalStatusLabels[approval.status] ?? approval.status}</Badge>
          </div>
          <p className={`m-0 mt-2 whitespace-pre-wrap break-words text-sm font-bold leading-6 ${rejected ? 'text-red-700' : 'text-amber-700'}`}>
            {presentation.reason}
          </p>
          <p className={`m-0 mt-2 text-xs font-bold ${rejected ? 'text-red-500' : 'text-amber-600'}`}>
            审批人 {presentation.operatorLabel}{presentation.createdAt ? ` · ${formatDateTime(presentation.createdAt)}` : ''}
          </p>
        </div>
      </div>
    </section>
  );
}

function ApprovalStatusCell({
  approval,
  currentUser,
  showReturnFeedback = false
}: {
  approval: ApprovalRow;
  currentUser: UserPublic;
  showReturnFeedback?: boolean;
}) {
  const returnFeedback = showReturnFeedback ? approvalReturnFeedbackPresentation(approval) : null;
  return (
    <div className="grid gap-1">
      <Badge tone={crmStatusTone(approval.status)}>{crmApprovalStatusLabels[approval.status] ?? approval.status}</Badge>
      <span className={`text-xs font-black ${
        approvalNextActionTone(approval, currentUser) === "warn"
          ? "text-amber-600"
          : approvalNextActionTone(approval, currentUser) === "ok"
            ? "text-emerald-600"
            : approvalNextActionTone(approval, currentUser) === "bad"
              ? "text-red-600"
              : "text-primary"
      }`}>
        {approvalRowNextActionLabel(approval, currentUser)}
      </span>
      {returnFeedback ? (
        <span
          title={`${returnFeedback.title}：${returnFeedback.reason}`}
          className={`mt-1 max-w-[320px] overflow-hidden text-xs font-bold leading-5 ${returnFeedback.tone === 'bad' ? 'text-red-600' : 'text-amber-700'}`}
          style={{ display: '-webkit-box', WebkitBoxOrient: 'vertical', WebkitLineClamp: 2 }}
        >
          {returnFeedback.title}：{returnFeedback.reason}
        </span>
      ) : null}
    </div>
  );
}

