  if (!statusValue) return "无";
  if (statusValue === "completed" || statusValue === "approved" || statusValue === "synced") return "已同步";
  if (statusValue === "submitted" || statusValue === "under_review") return "待审";
  if (statusValue === "need_supplement") return "需补充";
  if (statusValue === "rejected") return "驳回";
  if (statusValue === "cancelled") return "撤回";
  if (statusValue === "draft") return "草稿";
  return crmApprovalStatusLabels[statusValue] ?? statusValue;
