function crmTaskDataUpdateTone(statusValue?: string | null): ContextTone {
  if (!statusValue) return "neutral";
  if (statusValue === "completed" || statusValue === "approved" || statusValue === "synced") return "ok";
  if (statusValue === "rejected" || statusValue === "cancelled") return "bad";
  if (statusValue === "need_supplement" || statusValue === "submitted" || statusValue === "under_review") return "warn";
  return "neutral";
}

