function CrmEntryCard({
  entry,
  navigate,
  compact = false
}: {
  entry: CrmNavEntry;
  navigate: (page: Page, path?: string) => void;
  compact?: boolean;
}) {
  const Icon = entry.icon;
  return (
    <button
      type="button"
      onClick={() => navigate(entry.targetPage ?? "crm", entry.path)}
      className={`crm-entry-card ${compact ? "p-3" : "p-5"}`}
    >
      <span className="crm-entry-card-icon">
        <Icon className="h-4 w-4" />
      </span>
      <span className="min-w-0">
        <strong className="block truncate text-base font-black text-foreground">{entry.label}</strong>
        <span className="mt-1 block truncate text-sm leading-6 text-muted-foreground">{entry.desc}</span>
      </span>
    </button>
  );
}

function CrmFrontlineWorkbenchSection({
  permissions,
  currentUser,
  navigate
}: {
  permissions: PermissionCode[];
  currentUser: UserPublic;
  navigate: (page: Page, path?: string) => void;
}) {
  const canViewTasks = hasPermission(permissions, "crm_task.view");
  const canSubmitFollowup = hasPermission(permissions, "crm_followup.submit");
  const canSubmitBusinessProfile = hasPermission(permissions, "crm_business_profile.view") && hasPermission(permissions, "crm_business_profile.submit");
  const canSubmitCustomerProfile = hasPermission(permissions, "crm_customer_profile.view") && hasPermission(permissions, "crm_customer_profile.submit");
  const canOpenTaskDetails = canAccessCrmPath("/crm/tasks", permissions);
  const canCreateProject = hasPermission(permissions, "crm_project.create");
  const canApprove = hasPermission(permissions, "approval.approve");
  const [dailyData, setDailyData] = useState<CrmDailySummary | null>(null);
  const [taskRows, setTaskRows] = useState<CrmTaskRow[]>([]);
  const [supplementRows, setSupplementRows] = useState<ApprovalRow[]>([]);
  const [selectedTask, setSelectedTask] = useState<CrmTaskRow | null>(null);
  const [selectedApprovalId, setSelectedApprovalId] = useState<number | null>(() => {
    const approvalId = Number(initialQueryParam("approval_id"));
    return Number.isFinite(approvalId) && approvalId > 0 ? approvalId : null;
  });
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");

  const taskBelongsToCurrentUser = (task: Pick<CrmTaskRow, "executor_user_id" | "executor_employee_code"> | Pick<CrmDailySummaryTask, "executor_user_id" | "executor_employee_code">) =>
    task.executor_user_id === currentUser.id || Boolean(currentUser.employee_code && task.executor_employee_code === currentUser.employee_code);

  const loadFrontline = async () => {
    setLoading(true);
    setMessage("");
    const jobs: Promise<unknown>[] = [
      myApprovalSubmissionsPage({ status_value: "need_supplement", limit: 20, offset: 0 })
        .then((data) => setSupplementRows(data.items))
        .catch((error) => {
          setSupplementRows([]);
          throw error;
        })
    ];
    if (canViewTasks) {
      jobs.push(
        crmDailySummary({ date: todayDateInput(), limit: 80 })
          .then((data) => setDailyData(data))
          .catch((error) => {
            setDailyData(null);
            throw error;
          })
      );
      jobs.push(
        crmTasksPage({ executor_user_id: currentUser.id, limit: 30, offset: 0, ...crmTaskScopeFilters("open") })
          .then((data) => setTaskRows(data.items.filter(taskBelongsToCurrentUser)))
          .catch((error) => {
            setTaskRows([]);
            throw error;
          })
      );
    } else {
      setDailyData(null);
      setTaskRows([]);
    }
    const results = await Promise.allSettled(jobs);
    if (results.some((result) => result.status === "rejected")) {
      setMessage("部分一线工作台数据加载失败，已展示当前账号可读取的数据。");
    }
    setLoading(false);
  };

  useEffect(() => {
    void loadFrontline();
  }, [canViewTasks, currentUser.id, currentUser.employee_code]);

  const myDueTasks = (dailyData?.due_tasks ?? []).filter(taskBelongsToCurrentUser);
  const myOverdueTasks = myDueTasks.filter((task) => task.overdue);
  const overdueTaskIds = new Set(myOverdueTasks.map((task) => task.id));
  const isTaskRisky = (task: CrmTaskRow) =>
    overdueTaskIds.has(task.id) || task.is_blocked || task.need_support || task.need_manager_support || task.need_boss_decision;
  const sortedTasks = [...taskRows].sort((left, right) => {
    const leftScore = (isTaskRisky(left) ? 10 : 0) + (left.is_blocked ? 10 : 0) + (left.need_boss_decision || left.need_manager_support ? 5 : 0);
    const rightScore = (isTaskRisky(right) ? 10 : 0) + (right.is_blocked ? 10 : 0) + (right.need_boss_decision || right.need_manager_support ? 5 : 0);
    if (rightScore !== leftScore) return rightScore - leftScore;
    return String(left.feedback_due_at ?? "").localeCompare(String(right.feedback_due_at ?? ""));
  });
  const riskyTaskCount = sortedTasks.filter(isTaskRisky).length;
  const todaySubmitReadyCount = sortedTasks.filter((task) => !task.is_closed && canSubmitFollowup).length;

  return (
    <>
      <Header
        eyebrow="CRM FRONTLINE"
        title="一线工作台"
        description={`${currentUser.real_name || currentUser.username} 的任务、跟进和补充材料集中在这里。`}
        actions={
          <>
            <Button secondary onClick={() => void loadFrontline()} disabled={loading}><RefreshCcw className="mr-1.5 h-4 w-4" />刷新</Button>
            {canSubmitFollowup && canOpenTaskDetails ? <Button secondary onClick={() => navigate("crm", "/crm/tasks?scope=open")}>跟进填写</Button> : null}
            {canSubmitCustomerProfile || canSubmitBusinessProfile ? <Button secondary onClick={() => navigate("crm", "/crm/customers")}>关联客户底盘</Button> : null}
            {canCreateProject ? <Button secondary onClick={() => navigate("crm", "/crm/submit?mode=project")}>项目申请</Button> : null}
            <Button secondary onClick={() => navigate("crm", "/crm/submissions")}>我的提交</Button>
            <Button onClick={() => navigate("crm", "/crm/tasks")}>任务明细</Button>
          </>
        }
      />
      {message ? <Card className="mb-4 border-amber-200 bg-amber-50 px-4 py-3 text-sm font-bold text-amber-700">{message}</Card> : null}
      <div className="mb-4 grid gap-3 md:grid-cols-2 xl:grid-cols-4">
        <CrmProjectMetricCard label="今日应跟" value={canViewTasks ? myDueTasks.length : "无权限"} detail={`超期 ${myOverdueTasks.length} 条`} tone={myOverdueTasks.length > 0 ? "bad" : myDueTasks.length > 0 ? "neutral" : "ok"} icon={CalendarDays} />
        <CrmProjectMetricCard label="一线任务队列" value={canViewTasks ? sortedTasks.length : "无权限"} detail={`风险 ${riskyTaskCount} 条`} tone={riskyTaskCount > 0 ? "neutral" : "ok"} icon={ClipboardList} />
        <CrmProjectMetricCard label="待补充材料" value={supplementRows.length} detail="仅显示本人相关审批" tone={supplementRows.length > 0 ? "neutral" : "ok"} icon={UploadCloud} />
        <CrmProjectMetricCard label="跟进提交" value={canSubmitFollowup ? todaySubmitReadyCount : "无权限"} detail="进入任务详情处理" tone={canSubmitFollowup ? "ok" : "neutral"} icon={Phone} />
      </div>

      <section className="grid gap-4 xl:grid-cols-[minmax(0,1.32fr)_minmax(360px,0.68fr)]">
        <DataTableShell
          title="一线任务队列"
          description={loading ? "正在读取分配给当前账号的任务。" : "点击行查看任务详情；跟进填写、AI 草稿和支持事项在详情抽屉中处理。"}
          meta={`${sortedTasks.length} 条`}
          actions={<Button secondary onClick={() => navigate("crm", "/crm/tasks")}>完整列表</Button>}
        >
          <Table headers={["客户", "任务", "状态", "风险", "截止"]}>
            {sortedTasks.length > 0 ? sortedTasks.map((task) => {
              const riskLabel = task.is_blocked
                ? "阻塞"
                : task.need_boss_decision
                  ? "老板决策"
                  : task.need_manager_support
                    ? "主管支持"
                    : task.need_support
                      ? "需支持"
                      : overdueTaskIds.has(task.id)
                        ? "超期"
                        : "正常";
              const riskTone: ContextTone = task.is_blocked || task.need_boss_decision ? "bad" : riskLabel === "正常" ? "ok" : "warn";
              return (
                <tr key={task.id} onClick={() => setSelectedTask(task)} className="cursor-pointer transition hover:bg-primary-soft">
                  <td>
                    <strong className="block max-w-[240px] truncate text-slate-950">{task.customer_name_snapshot || task.customer_code}</strong>
                    <span className="mt-1 block text-xs font-bold text-slate-400">{task.customer_code}</span>
                  </td>
                  <td>
                    <strong className="block text-slate-950">{task.task_code}</strong>
                    <span className="mt-1 block max-w-[260px] truncate text-xs font-bold text-slate-400">{displayValue(task.round_target || task.business_issue_point)}</span>
                  </td>
                  <td><Badge tone={crmStatusTone(task.status)}>{crmTaskStatusLabels[task.status] ?? task.status}</Badge></td>
                  <td><Badge tone={riskTone}>{riskLabel}</Badge></td>
                  <td>{formatDateTime(task.feedback_due_at)}</td>
                </tr>
              );
            }) : (
              <CrmEmptyTableRow
                colSpan={5}
                icon={ClipboardList}
                message={canViewTasks ? "当前暂无分配给你的一线任务。" : "当前账号没有客户任务查看权限。"}
                description={canViewTasks ? "项目立项时分配执行人后，这里会自动出现待跟进客户。" : undefined}
                actions={canViewTasks ? [{ label: "查看任务明细", onClick: () => navigate("crm", "/crm/tasks"), icon: ClipboardList }] : []}
              />
            )}
          </Table>
        </DataTableShell>

        <div className="grid content-start gap-4">
          <DataTableShell title="待我补充" description="审批被退回补充时，会在这里显示；点击行打开详情抽屉补附件或重新提交。" meta={`${supplementRows.length} 条`}>
            <Table headers={["审批单", "类型", "状态", "处理人", "更新时间"]}>
              <CrmApprovalRows
                rows={supplementRows}
                compact
                emptyMessage="暂无需要你补充的审批材料。"
                navigate={navigate}
                onSelect={(row) => setSelectedApprovalId(row.id)}
              />
            </Table>
          </DataTableShell>

          <Card className="p-4">
            <div className="flex items-center justify-between gap-3">
              <div>
                <h2 className="m-0 text-base font-black text-slate-950">一线快捷动作</h2>
                <p className="m-0 mt-1 text-sm text-slate-500">表格只保留浏览，动作进入详情或独立页面。</p>
              </div>
              <Badge tone="neutral">角色模式</Badge>
            </div>
            <div className="mt-4 grid gap-2">
              <CrmFocusButton label="跟进填写" value="进入" detail="从任务明细记录反馈" tone={canSubmitFollowup ? "ok" : "neutral"} icon={Phone} onClick={() => navigate("crm", "/crm/tasks?scope=open")} />
              {canSubmitCustomerProfile || canSubmitBusinessProfile ? <CrmFocusButton label="客户资料" value="进入" detail="查看并维护基础与经营资料" tone="ok" icon={UserRound} onClick={() => navigate("crm", "/crm/customers")} /> : null}
              <CrmFocusButton label="我的工作台" value="查看" detail="待审批、支持事项和个人待办" icon={UserCheck} onClick={() => navigate("crm", "/crm/my-work")} />
            </div>
          </Card>
        </div>
      </section>

      <AnimatePresence>
        {selectedTask ? (
          <CrmTaskDetailDrawer
            key={`frontline-task-detail-${selectedTask.id}`}
            task={selectedTask}
            permissions={permissions}
            navigate={navigate}
            onClose={() => setSelectedTask(null)}
            onChanged={async (updatedTask) => {
              setSelectedTask(updatedTask);
              await loadFrontline();
            }}
          />
        ) : null}
        {selectedApprovalId ? (
          <CrmApprovalDetailDrawer
            key={`frontline-approval-${selectedApprovalId}`}
            approvalId={selectedApprovalId}
            canApprove={canApprove}
            currentUser={currentUser}
            navigate={navigate}
            onClose={() => setSelectedApprovalId(null)}
            onChanged={(nextMessage) => {
              setMessage(nextMessage);
              void loadFrontline();
            }}
          />
        ) : null}
      </AnimatePresence>
    </>
  );
}

type CrmSubmissionScope = "all" | "drafts" | "need_supplement" | "pending" | "completed" | "rejected" | "cancelled";

const crmSubmissionScopes: Array<{ key: CrmSubmissionScope; label: string; desc: string; icon: LucideIcon }> = [
  { key: "all", label: "全部", desc: "我的全部提交", icon: FolderOpen },
  { key: "drafts", label: "草稿", desc: "未提交审批", icon: Folder },
  { key: "need_supplement", label: "待补充", desc: "退回后需补充", icon: UploadCloud },
  { key: "pending", label: "审核中", desc: "待审批或审批中", icon: Clock3 },
  { key: "completed", label: "已通过", desc: "已完成审批", icon: ShieldCheck },
  { key: "rejected", label: "已驳回", desc: "审批被驳回", icon: FileWarning },
  { key: "cancelled", label: "已撤回", desc: "已取消提交", icon: X }
];

function CrmMySubmissionsSection({
  permissions,
  currentUser,
  navigate
}: {
  permissions: PermissionCode[];
  currentUser: UserPublic;
  navigate: (page: Page, path?: string) => void;
}) {
  const canCreateProject = hasPermission(permissions, "crm_project.create");
  const canSubmitFollowup = hasPermission(permissions, "crm_followup.submit");
  const canApprove = hasPermission(permissions, "approval.approve");
  const initialScope = (initialQueryParam("scope") as CrmSubmissionScope) || "all";
  const [scope, setScope] = useState<CrmSubmissionScope>(crmSubmissionScopes.some((item) => item.key === initialScope) ? initialScope : "all");
  const [query, setQuery] = useState(() => initialQueryParam("q"));
  const [currentPage, setCurrentPage] = useState(1);
  const [pageData, setPageData] = useState<ApprovalPage | null>(null);
  const [scopeCounts, setScopeCounts] = useState<Record<CrmSubmissionScope, number>>({
    all: 0,
    drafts: 0,
    need_supplement: 0,
    pending: 0,
    completed: 0,
    rejected: 0,
    cancelled: 0
  });
  const [selectedApprovalId, setSelectedApprovalId] = useState<number | null>(() => {
    const approvalId = Number(initialQueryParam("approval_id"));
    return Number.isFinite(approvalId) && approvalId > 0 ? approvalId : null;
  });
  const [editingApprovalId, setEditingApprovalId] = useState<number | null>(null);
  const [createProjectOpen, setCreateProjectOpen] = useState(false);
  const [followupDraftOpen, setFollowupDraftOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");

  const totalRows = pageData?.total ?? 0;
  const totalPages = Math.max(1, Math.ceil(totalRows / CRM_PROJECT_PAGE_SIZE));
  const safeCurrentPage = Math.min(currentPage, totalPages);
  const offset = (safeCurrentPage - 1) * CRM_PROJECT_PAGE_SIZE;
  const rangeStart = totalRows === 0 ? 0 : offset + 1;
  const rangeEnd = Math.min(offset + CRM_PROJECT_PAGE_SIZE, totalRows);
  const rows = pageData?.items ?? [];

  const loadSubmissions = async () => {
    setLoading(true);
    setMessage("");
    try {
      const filters = {
        q: query,
        scope: scope === "all" ? undefined : scope,
        limit: CRM_PROJECT_PAGE_SIZE,
        offset
      };
      const [nextPage, ...countPages] = await Promise.all([
        myApprovalSubmissionsPage(filters),
        ...crmSubmissionScopes.map((item) => myApprovalSubmissionsPage({ scope: item.key === "all" ? undefined : item.key, limit: 1, offset: 0 }))
      ]);
      setPageData(nextPage);
      setScopeCounts(
        crmSubmissionScopes.reduce((acc, item, index) => {
          acc[item.key] = countPages[index]?.total ?? 0;
          return acc;
        }, {} as Record<CrmSubmissionScope, number>)
      );
    } catch (error) {
      setPageData(null);
      setMessage(error instanceof Error ? error.message : "我的提交加载失败");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void loadSubmissions();
  }, [scope, query, offset]);

  useEffect(() => {
    if (currentPage !== safeCurrentPage) setCurrentPage(safeCurrentPage);
  }, [currentPage, safeCurrentPage]);

  const setScopeAndReset = (nextScope: CrmSubmissionScope) => {
    setScope(nextScope);
    setCurrentPage(1);
  };
  const resetFilters = () => {
    setScope("all");
    setQuery("");
    setCurrentPage(1);
  };
  const openDraftEditor = (row: ApprovalRow) => {
    setSelectedApprovalId(null);
    setEditingApprovalId(row.id);
  };
  const openApprovalDetail = (row: ApprovalRow) => {
    setEditingApprovalId(null);
    setSelectedApprovalId(row.id);
  };
  const openRecentApproval = (row: ApprovalRow) => {
    if (canEditApprovalSubmission(row, currentUser)) {
      openDraftEditor(row);
      return;
    }
    openApprovalDetail(row);
  };
  const statusMetrics = [
    { label: "草稿", value: scopeCounts.drafts, detail: "可继续编辑或撤回", tone: scopeCounts.drafts > 0 ? "warn" : "ok", icon: Folder },
    { label: "待补充", value: scopeCounts.need_supplement, detail: "需补材料后重提", tone: scopeCounts.need_supplement > 0 ? "warn" : "ok", icon: UploadCloud },
    { label: "审核中", value: scopeCounts.pending, detail: "已提交待处理", tone: scopeCounts.pending > 0 ? "neutral" : "ok", icon: Clock3 },
    { label: "已完成", value: scopeCounts.completed, detail: "审批通过/完成", tone: "ok", icon: ShieldCheck }
  ] satisfies Array<{ label: string; value: number; detail: string; tone?: ContextTone; icon: LucideIcon }>;

  return (
    <>
      <Header
        eyebrow="CRM MY SUBMISSIONS"
        title="我的提交"
        description="集中查看我发起的项目申请、跟进提交、草稿、待补充、审核中和历史审批。"
        actions={
          <>
            <Button secondary onClick={() => void loadSubmissions()} disabled={loading}><RefreshCcw className="mr-1.5 h-4 w-4" />刷新</Button>
            {canCreateProject ? <Button secondary onClick={() => setCreateProjectOpen(true)}><Plus className="mr-1.5 h-4 w-4" />项目草稿</Button> : null}
            {canSubmitFollowup ? <Button secondary onClick={() => setFollowupDraftOpen(true)}><History className="mr-1.5 h-4 w-4" />跟进草稿</Button> : null}
            {canCreateProject ? <Button onClick={() => navigate("crm", "/crm/submit?mode=project")}>项目申请</Button> : null}
          </>
        }
      />
      {message ? <Card className="mb-4 border-amber-200 bg-amber-50 px-4 py-3 text-sm font-bold text-amber-700">{message}</Card> : null}
      <div className="mb-4 grid gap-3 md:grid-cols-2 xl:grid-cols-4">
        {statusMetrics.map((metric) => <CrmProjectMetricCard key={metric.label} {...metric} />)}
      </div>

      <Card className="mb-4 p-3">
        <div className="grid gap-2 xl:grid-cols-7">
          {crmSubmissionScopes.map((item) => {
            const Icon = item.icon;
            const active = scope === item.key;
            return (
              <button
                key={item.key}
                type="button"
                onClick={() => setScopeAndReset(item.key)}
                className={`rounded-lg border px-3 py-3 text-left transition ${
                  active
                    ? "border-primary bg-primary-soft text-primary-hover shadow-sm"
                    : "border-slate-200 bg-white text-slate-600 hover:border-primary/30 hover:bg-primary-soft"
                }`}
              >
                <span className="flex items-center justify-between gap-2">
                  <span className="inline-flex items-center gap-2">
                    <Icon className="h-4 w-4" />
                    <strong className="text-sm">{item.label}</strong>
                  </span>
                  <strong className="text-sm text-slate-950">{scopeCounts[item.key] ?? 0}</strong>
                </span>
                <span className="mt-1 block truncate text-xs font-bold opacity-70">{item.desc}</span>
              </button>
            );
          })}
        </div>
      </Card>

      <DataTableShell
        title="我的提交列表"
        description={loading ? "正在读取我的提交。" : "草稿和待补充点击后继续编辑；审核中的提交点击后查看进度。"}
        meta={`${rangeStart}-${rangeEnd} / ${totalRows} 条`}
        toolbar={
          <DataToolbar onReset={resetFilters}>
            <ToolbarSearch value={query} onChange={(value) => { setCurrentPage(1); setQuery(value); }} placeholder="搜索审批号、标题、描述或资源 ID" />
          </DataToolbar>
        }
      >
        <Table headers={["提交单", "类型", "状态 / 下一步", "优先级", "处理人", "更新时间"]}>
          {rows.length > 0 ? rows.map((row) => {
            return (
              <tr key={row.id} onClick={() => openRecentApproval(row)} className="cursor-pointer transition hover:bg-primary-soft">
                <td>
                  <strong className="block max-w-[280px] truncate text-slate-950">{row.title}</strong>
                  <span className="mt-1 block text-xs font-bold text-slate-400">{row.approval_no} · {formatDateTime(row.submitted_at ?? row.created_at)}</span>
                </td>
                <td>{crmApprovalTypeLabel(row.approval_type)}</td>
                <td><ApprovalStatusCell approval={row} currentUser={currentUser} showReturnFeedback /></td>
                <td><Badge tone={row.priority === "urgent" ? "bad" : row.priority === "high" ? "warn" : "neutral"}>{crmPriorityLabels[row.priority] ?? row.priority}</Badge></td>
                <td>{approvalUserLabel(row, "handler")}</td>
                <td>{formatDateTime(row.updated_at)}</td>
              </tr>
            );
          }) : (
            <CrmEmptyTableRow
              colSpan={6}
              icon={FolderOpen}
              message={loading ? "正在加载我的提交。" : "当前筛选下暂无提交记录。"}
              description="新建项目申请草稿、跟进记录审批或审批退回补充后，都会汇总到这里。"
              actions={[
                ...(canCreateProject ? [{ label: "项目草稿", onClick: () => setCreateProjectOpen(true), icon: Plus }] : []),
                ...(canSubmitFollowup ? [{ label: "跟进草稿", onClick: () => setFollowupDraftOpen(true), icon: History, secondary: true }] : []),
                { label: "清空筛选", onClick: resetFilters, icon: X, secondary: true }
              ]}
            />
          )}
        </Table>
        <MasterPagination
          currentPage={safeCurrentPage}
          totalPages={totalPages}
          totalItems={totalRows}
          pageSize={CRM_PROJECT_PAGE_SIZE}
          rangeStart={rangeStart}
          rangeEnd={rangeEnd}
          onPageChange={setCurrentPage}
        />
      </DataTableShell>

      <AnimatePresence>
        {selectedApprovalId ? (
          <CrmApprovalDetailDrawer
            key={`my-submission-detail-${selectedApprovalId}`}
            approvalId={selectedApprovalId}
            canApprove={canApprove}
            currentUser={currentUser}
            navigate={navigate}
            onClose={() => setSelectedApprovalId(null)}
            onChanged={(nextMessage) => {
              setMessage(nextMessage);
              void loadSubmissions();
            }}
          />
        ) : null}
        {editingApprovalId ? (
          <CrmSubmissionDraftEditorDrawer
            key={`my-submission-edit-${editingApprovalId}`}
            approvalId={editingApprovalId}
            onClose={() => setEditingApprovalId(null)}
            onChanged={(nextMessage) => {
              setEditingApprovalId(null);
              setMessage(nextMessage);
              void loadSubmissions();
            }}
          />
        ) : null}
        {createProjectOpen ? (
          <CreateCrmProjectDrawer
            key="my-submissions-create-project"
            currentUser={currentUser}
            permissions={permissions}
            onClose={() => setCreateProjectOpen(false)}
            onCreated={(approvalRow) => {
              setCreateProjectOpen(false);
              setMessage(`${crmProjectApprovalFeedback(approvalRow)}。`);
              setScope(approvalRow.status === "draft" ? "drafts" : "pending");
              void loadSubmissions();
            }}
          />
        ) : null}
        {followupDraftOpen ? (
          <CrmFollowupDraftDrawer
            key="my-submissions-followup-draft"
            currentUser={currentUser}
            onClose={() => setFollowupDraftOpen(false)}
            onCreated={(approvalRow) => {
              setFollowupDraftOpen(false);
              setMessage(`已保存跟进草稿 ${approvalRow.approval_no}。`);
              setScope("drafts");
              void loadSubmissions();
            }}
          />
        ) : null}
      </AnimatePresence>
    </>
  );
}

function CrmSubmissionDraftEditorDrawer({
  approvalId,
  onClose,
  onChanged
}: {
  approvalId: number;
  onClose: () => void;
  onChanged: (message: string) => void;
}) {
  const [detail, setDetail] = useState<ApprovalDetail | null>(null);
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [handlerUserId, setHandlerUserId] = useState("");
  const [priority, setPriority] = useState("normal");
  const [payloadText, setPayloadText] = useState("{}");
  const [comment, setComment] = useState("");
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const [localMessage, setLocalMessage] = useState("");
  const [userRows, setUserRows] = useState<UserPublic[]>([]);

  const currentApproval = detail?.approval ?? null;
  const editable = currentApproval ? ["draft", "need_supplement"].includes(currentApproval.status) : false;
  const fixedCrmHandlerLabel = currentApproval?.approval_type === "crm_project_create"
    ? "施总 / admin"
    : ["crm_followup_submit", "customer_business_profile_update", "customer_profile_update"].includes(currentApproval?.approval_type ?? "")
      ? "细节审批人"
      : "";
  const usesFixedCrmHandler = fixedCrmHandlerLabel.length > 0;
  const fixedCrmHandlerDisplay = currentApproval?.current_handler_user_label ?? fixedCrmHandlerLabel;
  const editorActionTitle = currentApproval?.status === "need_supplement" ? "补充后重新提交" : "继续编辑草稿";
  const editorActionDetail = currentApproval?.status === "need_supplement"
    ? "补齐退回材料后点击“补充并提交”，单据会重新进入审批队列。"
    : "可以先保存草稿；确认无误后点击“提交审批”。";
  const parsedPayload = useMemo(() => {
    try {
      return { value: JSON.parse(payloadText || "{}") as Record<string, unknown> | unknown[], error: "" };
    } catch (parseError) {
      return { value: null, error: parseError instanceof Error ? parseError.message : "审批载荷不是合法 JSON" };
    }
  }, [payloadText]);

  const loadDraft = async () => {
    setLoading(true);
    setError("");
    try {
      const nextDetail = await approval(approvalId);
      setDetail(nextDetail);
      setTitle(nextDetail.approval.title ?? "");
      setDescription(nextDetail.approval.description ?? "");
      setHandlerUserId(nextDetail.approval.current_handler_user_id ? String(nextDetail.approval.current_handler_user_id) : "");
      setPriority(nextDetail.approval.priority || "normal");
      setPayloadText(JSON.stringify(nextDetail.approval.payload_json ?? {}, null, 2));
    } catch (loadError) {
      setError(loadError instanceof Error ? loadError.message : "草稿加载失败");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void loadDraft();
  }, [approvalId]);

  useEffect(() => {
    void users("", "active").then(setUserRows).catch(() => setUserRows([]));
  }, []);

  const draftPayload = (nextComment: string): ApprovalDraftUpdatePayload | null => {
    if (!title.trim()) {
      setError("请填写提交标题。");
      return null;
    }
    if (parsedPayload.error || parsedPayload.value === null) {
      setError(`审批载荷不是合法 JSON：${parsedPayload.error}`);
      return null;
    }
    const nextPayload: ApprovalDraftUpdatePayload = {
      title: title.trim(),
      description: cleanNullable(description),
      priority,
      payload_json: parsedPayload.value,
      comment: cleanNullable(nextComment)
    };
    if (!usesFixedCrmHandler) {
      nextPayload.current_handler_user_id = parseOptionalInt(handlerUserId);
    }
    return nextPayload;
  };

  const saveDraft = async () => {
    if (!currentApproval || !editable) return;
    const payload = draftPayload(comment || "保存我的提交草稿");
    if (!payload) return;
    setSaving(true);
    setError("");
    setLocalMessage("");
    try {
      const nextDetail = await updateApprovalDraft(currentApproval.id, payload);
      setDetail(nextDetail);
      setLocalMessage(`已保存 ${nextDetail.approval.approval_no}。`);
    } catch (saveError) {
      setError(saveError instanceof Error ? saveError.message : "草稿保存失败");
    } finally {
      setSaving(false);
    }
  };

  const submitDraft = async () => {
    if (!currentApproval || !editable) return;
    const payload = draftPayload(comment || (currentApproval.status === "need_supplement" ? "补充后重新提交" : "提交审批"));
    if (!payload || parsedPayload.value === null) return;
    if (currentApproval.approval_type === "crm_project_create") {
      const record = payloadRecord(parsedPayload.value);
      const project = payloadRecord(record?.project);
      const tasks = Array.isArray(record?.tasks) ? record.tasks.map((task) => payloadRecord(task) ?? {}) : [];
      if (!String(project?.project_name ?? "").trim()) {
        setError("请填写项目名称。");
        return;
      }
      if (tasks.length === 0) {
        setError("请至少保留 1 个客户任务。");
        return;
      }
      const customerCodes = tasks.map((task) => String(task.customer_code ?? "").trim()).filter(Boolean);
      if (customerCodes.length !== tasks.length) {
        setError("客户任务中存在未填写客户编号的行。");
        return;
      }
      if (new Set(customerCodes).size !== customerCodes.length) {
        setError("客户任务中存在重复客户，请删除重复行后再提交。");
        return;
      }
      const allowLaterAssignment = String(project?.assignment_mode ?? "") === "later" || Boolean(project?.allow_unassigned_tasks);
      if (!allowLaterAssignment && tasks.some((task) => !String(task.executor_user_id ?? "").trim() && !String(task.executor_employee_code ?? "").trim())) {
        setError("仍有客户任务未分配执行人。请补齐执行人，或在高级载荷中设置 allow_unassigned_tasks=true。");
        return;
      }
    }
    setSaving(true);
    setError("");
    try {
      await updateApprovalDraft(currentApproval.id, payload);
      const submitted = currentApproval.status === "need_supplement"
        ? await supplementApproval(currentApproval.id, { comment: payload.comment, payload_json: parsedPayload.value })
        : await submitApproval(currentApproval.id, { comment: payload.comment, payload_json: parsedPayload.value });
      onChanged(`已${currentApproval.status === "need_supplement" ? "补充并重新提交" : "提交"} ${submitted.approval.approval_no}。`);
    } catch (submitError) {
      setError(submitError instanceof Error ? submitError.message : "提交失败");
    } finally {
      setSaving(false);
    }
  };

  const cancelDraft = async () => {
    if (!currentApproval || !editable) return;
    if (!window.confirm(`确认撤回 ${currentApproval.approval_no}？撤回后该提交会进入已撤回列表。`)) return;
    setSaving(true);
    setError("");
    try {
      const cancelled = await cancelApproval(currentApproval.id, { comment: cleanNullable(comment) || "申请人撤回提交" });
      onChanged(`已撤回 ${cancelled.approval.approval_no}。`);
    } catch (cancelError) {
      setError(cancelError instanceof Error ? cancelError.message : "撤回失败");
    } finally {
      setSaving(false);
    }
  };

  return (
    <Drawer title="编辑我的提交" subtitle={currentApproval ? `${currentApproval.approval_no} · ${crmApprovalStatusLabels[currentApproval.status] ?? currentApproval.status}` : "正在加载提交"} onClose={onClose}>
      {loading ? <CrmDrawerLoading /> : null}
      {!loading && currentApproval ? (
        <div className="grid gap-4">
          <Card className={`${currentApproval.status === "need_supplement" ? "border-amber-200 bg-amber-50 text-amber-700" : "border-primary/20 bg-primary-soft text-primary"} p-4`}>
            <div className="flex flex-col gap-2 md:flex-row md:items-center md:justify-between">
              <div>
                <p className="m-0 text-sm font-black">{editorActionTitle}</p>
                <p className="m-0 mt-1 text-sm font-bold leading-5 opacity-80">{editorActionDetail}</p>
              </div>
              <Badge tone={currentApproval.status === "need_supplement" ? "warn" : "neutral"}>{crmApprovalStatusLabels[currentApproval.status] ?? currentApproval.status}</Badge>
            </div>
          </Card>
          <ApprovalReturnFeedbackPanel approval={currentApproval} />
          <div className="grid gap-4 lg:grid-cols-3">
            <CustomerSideCard title="提交信息" icon={FolderOpen}>
              <CustomerSideRow label="提交类型" value={crmApprovalTypeLabel(currentApproval.approval_type)} />
              <CustomerSideRow label="当前状态" value={crmApprovalStatusLabels[currentApproval.status] ?? currentApproval.status} />
              <CustomerSideRow label="申请人" value={approvalUserLabel(currentApproval, "applicant")} />
              <CustomerSideRow label="创建时间" value={formatDateTime(currentApproval.created_at)} />
            </CustomerSideCard>
            <CustomerSideCard title="审批处理" icon={ShieldCheck}>
              <CustomerSideRow label="处理人" value={approvalUserLabel(currentApproval, "handler")} />
              <CustomerSideRow label="优先级" value={crmPriorityLabels[currentApproval.priority] ?? currentApproval.priority} />
              <CustomerSideRow label="提交时间" value={formatDateTime(currentApproval.submitted_at)} />
              <CustomerSideRow label="更新时间" value={formatDateTime(currentApproval.updated_at)} />
            </CustomerSideCard>
            <CustomerSideCard title="编辑规则" icon={FileWarning}>
              <p className="m-0 text-sm font-bold leading-6 text-slate-500">
                保存只更新当前提交；提交后进入审批队列，审批通过后才写入正式 CRM 数据。
              </p>
            </CustomerSideCard>
          </div>

          <CrmSubmissionBusinessFields
            approvalType={currentApproval.approval_type}
            payload={parsedPayload.value ?? currentApproval.payload_json}
            disabled={!editable || saving || Boolean(parsedPayload.error)}
            onPayloadChange={(nextPayload) => setPayloadText(JSON.stringify(nextPayload, null, 2))}
          />

          <CrmSubmissionPayloadSummary payload={parsedPayload.value ?? currentApproval.payload_json} error={parsedPayload.error} />

          <section className="rounded-lg border border-slate-200 bg-white p-4">
            <h3 className="m-0 text-sm font-black text-slate-950">基础字段</h3>
            <div className="mt-4 grid gap-3 md:grid-cols-2">
              <AccountField label="标题">
                <input value={title} disabled={!editable || saving} onChange={(event) => setTitle(event.target.value)} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold" />
              </AccountField>
              {usesFixedCrmHandler ? (
                <AccountField label="审批处理人">
                  <input value={fixedCrmHandlerDisplay} disabled className="h-10 rounded-lg border border-slate-200 bg-slate-50 px-3 text-sm font-bold text-slate-700" />
                </AccountField>
              ) : (
                <CrmUserPicker label="审批处理人" value={handlerUserId} onChange={setHandlerUserId} users={userRows} disabled={!editable || saving} />
              )}
              <AccountField label="优先级">
                <select value={priority} disabled={!editable || saving} onChange={(event) => setPriority(event.target.value)} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold">
                  {Object.entries(crmPriorityLabels).map(([value, label]) => <option key={value} value={value}>{label}</option>)}
                </select>
              </AccountField>
              <AccountField label="处理说明">
                <input value={comment} disabled={!editable || saving} onChange={(event) => setComment(event.target.value)} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold" placeholder="保存、提交或撤回时写入审批时间线" />
              </AccountField>
              <AccountField label="描述">
                <textarea value={description} disabled={!editable || saving} onChange={(event) => setDescription(event.target.value)} rows={4} className="rounded-lg border border-slate-200 px-3 py-2 text-sm font-bold" />
              </AccountField>
              <AccountField label="审批载荷">
                <textarea value={payloadText} disabled={!editable || saving} onChange={(event) => setPayloadText(event.target.value)} rows={12} className="font-mono rounded-lg border border-slate-200 px-3 py-2 text-xs leading-5" />
              </AccountField>
            </div>
            {parsedPayload.error ? <p className="m-0 mt-3 rounded-lg bg-red-50 px-3 py-2 text-sm font-bold text-red-600">JSON 错误：{parsedPayload.error}</p> : null}
            {localMessage ? <p className="m-0 mt-3 rounded-lg bg-emerald-50 px-3 py-2 text-sm font-bold text-emerald-700">{localMessage}</p> : null}
          </section>

          {error ? <p className="m-0 rounded-lg bg-red-50 px-3 py-2 text-sm font-bold text-red-600">{error}</p> : null}
          <div className="sticky bottom-0 flex flex-wrap justify-end gap-2 border-t border-slate-200 bg-white/95 py-4 backdrop-blur">
            <Button secondary onClick={onClose} disabled={saving}>关闭</Button>
            {editable ? <Button secondary onClick={cancelDraft} disabled={saving}>撤回</Button> : null}
            {editable ? <Button secondary onClick={saveDraft} disabled={saving}>{saving ? "保存中" : "保存草稿"}</Button> : null}
            {editable ? <Button onClick={submitDraft} disabled={saving || Boolean(parsedPayload.error)}>{saving ? "提交中" : currentApproval.status === "need_supplement" ? "补充并提交" : "提交审批"}</Button> : null}
          </div>
        </div>
      ) : null}
      {!loading && !currentApproval && !error ? <CustomerEmptyPanel title="未找到提交" description="该审批单不存在，或当前账号没有查看权限。" /> : null}
      {error && !currentApproval ? <p className="m-0 rounded-lg bg-red-50 px-3 py-2 text-sm font-bold text-red-600">{error}</p> : null}
    </Drawer>
  );
}

function payloadRecord(value: unknown): Record<string, unknown> | null {
  return value && typeof value === "object" && !Array.isArray(value) ? value as Record<string, unknown> : null;
}

function payloadTextValue(value: unknown) {
  return value === null || value === undefined ? "" : String(value);
}

function CrmSubmissionBusinessFields({
  approvalType,
  payload,
  disabled,
  onPayloadChange
}: {
  approvalType: string;
  payload: Record<string, unknown> | unknown[] | null | undefined;
  disabled: boolean;
  onPayloadChange: (payload: Record<string, unknown>) => void;
}) {
  const record = payloadRecord(payload);
  if (!record) return null;

  const sectionRecord = approvalType === "crm_project_create"
    ? payloadRecord(record.project)
    : approvalType === "crm_followup_submit"
      ? payloadRecord(record.followup)
      : null;
  if (!sectionRecord) return null;

  const sectionKey = approvalType === "crm_project_create" ? "project" : "followup";
  const updateField = (field: string, value: unknown) => {
    onPayloadChange({
      ...record,
      [sectionKey]: {
        ...sectionRecord,
        [field]: value
      }
    });
  };
  const updateNullableText = (field: string, value: string) => updateField(field, value.trim() ? value : null);

  if (approvalType === "crm_project_create") {
    const tasks = Array.isArray(record.tasks) ? record.tasks : [];
    const taskRecords = tasks.map((task) => payloadRecord(task) ?? {});
    const updateTask = (index: number, field: string, value: unknown) => {
      onPayloadChange({
        ...record,
        tasks: taskRecords.map((task, taskIndex) => taskIndex === index ? { ...task, [field]: value } : task)
      });
    };
    const removeTask = (index: number) => {
      onPayloadChange({
        ...record,
        tasks: taskRecords.filter((_, taskIndex) => taskIndex !== index)
      });
    };
    const addTask = () => {
      onPayloadChange({
        ...record,
        tasks: [
          ...taskRecords,
          {
            customer_code: "",
            customer_name_snapshot: "",
            executor_user_id: null,
            executor_employee_code: null,
            business_issue_point: null,
            round_target: null,
            feedback_due_at: null,
            status: "not_started"
          }
        ]
      });
    };
    return (
      <section className="rounded-lg border border-primary/15 bg-primary-soft p-4">
        <div className="flex flex-col gap-2 md:flex-row md:items-center md:justify-between">
          <div>
            <h3 className="m-0 text-sm font-black text-slate-950">项目申请快改</h3>
            <p className="m-0 mt-1 text-xs font-bold text-slate-500">修改常用项目字段和客户任务清单；高级载荷仍保留完整兜底。</p>
          </div>
          <Badge tone="neutral">客户任务 {tasks.length}</Badge>
        </div>
        <div className="mt-4 grid gap-3 md:grid-cols-2">
          <AccountField label="项目名称">
            <input value={payloadTextValue(sectionRecord.project_name)} disabled={disabled} onChange={(event) => updateNullableText("project_name", event.target.value)} className="project-input" />
          </AccountField>
          <AccountField label="项目类型">
            <input value={payloadTextValue(sectionRecord.project_type)} disabled={disabled} onChange={(event) => updateNullableText("project_type", event.target.value)} className="project-input" />
          </AccountField>
          <AccountField label="业务线">
            <input value={payloadTextValue(sectionRecord.business_line)} disabled={disabled} onChange={(event) => updateNullableText("business_line", event.target.value)} className="project-input" />
          </AccountField>
          <AccountField label="截止日期">
            <input type="date" value={payloadTextValue(sectionRecord.due_date)} disabled={disabled} onChange={(event) => updateNullableText("due_date", event.target.value)} className="project-input" />
          </AccountField>
          <AccountField label="项目目的">
            <textarea value={payloadTextValue(sectionRecord.purpose)} disabled={disabled} onChange={(event) => updateNullableText("purpose", event.target.value)} rows={3} className="rounded-lg border border-input bg-white px-3 py-2 text-sm font-bold text-foreground disabled:bg-muted disabled:text-muted-foreground" />
          </AccountField>
          <AccountField label="客户范围">
            <textarea value={payloadTextValue(sectionRecord.customer_scope_note)} disabled={disabled} onChange={(event) => updateNullableText("customer_scope_note", event.target.value)} rows={3} className="rounded-lg border border-input bg-white px-3 py-2 text-sm font-bold text-foreground disabled:bg-muted disabled:text-muted-foreground" />
          </AccountField>
          <AccountField label="最小动作">
            <textarea value={payloadTextValue(sectionRecord.minimum_action)} disabled={disabled} onChange={(event) => updateNullableText("minimum_action", event.target.value)} rows={3} className="rounded-lg border border-input bg-white px-3 py-2 text-sm font-bold text-foreground disabled:bg-muted disabled:text-muted-foreground" />
          </AccountField>
          <AccountField label="闭环标准">
            <textarea value={payloadTextValue(sectionRecord.closure_standard)} disabled={disabled} onChange={(event) => updateNullableText("closure_standard", event.target.value)} rows={3} className="rounded-lg border border-input bg-white px-3 py-2 text-sm font-bold text-foreground disabled:bg-muted disabled:text-muted-foreground" />
          </AccountField>
        </div>
        <div className="mt-4 rounded-lg border border-slate-200 bg-white">
          <div className="flex flex-col gap-2 border-b border-slate-200 px-3 py-3 md:flex-row md:items-center md:justify-between">
            <div>
              <h4 className="m-0 text-sm font-black text-slate-950">客户任务清单</h4>
              <p className="m-0 mt-1 text-xs font-bold text-slate-500">草稿可继续新增、删除和修改客户任务。</p>
            </div>
            <Button secondary onClick={addTask} disabled={disabled}>新增客户任务</Button>
          </div>
          <div className="overflow-x-auto">
            <UiTable className="project-table min-w-[960px]">
              <TableHeader>
                <TableRow>
                  <TableHead>客户编号</TableHead>
                  <TableHead>客户名称</TableHead>
                  <TableHead>执行人ID</TableHead>
                  <TableHead>员工编号</TableHead>
                  <TableHead>反馈截止</TableHead>
                  <TableHead>问题点</TableHead>
                  <TableHead>轮次目标</TableHead>
                  <TableHead>操作</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {taskRecords.length > 0 ? taskRecords.map((task, index) => (
                  <TableRow key={index}>
                    <TableCell><input value={payloadTextValue(task.customer_code)} disabled={disabled} onChange={(event) => updateTask(index, "customer_code", event.target.value)} className="h-9 w-32 rounded-lg border border-slate-200 px-2 text-sm font-bold" /></TableCell>
                    <TableCell><input value={payloadTextValue(task.customer_name_snapshot)} disabled={disabled} onChange={(event) => updateTask(index, "customer_name_snapshot", event.target.value)} className="h-9 w-44 rounded-lg border border-slate-200 px-2 text-sm font-bold" /></TableCell>
                    <TableCell><input value={payloadTextValue(task.executor_user_id)} disabled={disabled} onChange={(event) => updateTask(index, "executor_user_id", event.target.value ? Number(event.target.value) : null)} className="h-9 w-28 rounded-lg border border-slate-200 px-2 text-sm font-bold" /></TableCell>
                    <TableCell><input value={payloadTextValue(task.executor_employee_code)} disabled={disabled} onChange={(event) => updateTask(index, "executor_employee_code", event.target.value.trim() ? event.target.value : null)} className="h-9 w-32 rounded-lg border border-slate-200 px-2 text-sm font-bold" /></TableCell>
                    <TableCell><input type="datetime-local" value={payloadTextValue(task.feedback_due_at)} disabled={disabled} onChange={(event) => updateTask(index, "feedback_due_at", event.target.value || null)} className="h-9 w-52 rounded-lg border border-slate-200 px-2 text-sm font-bold" /></TableCell>
                    <TableCell><input value={payloadTextValue(task.business_issue_point)} disabled={disabled} onChange={(event) => updateTask(index, "business_issue_point", event.target.value.trim() ? event.target.value : null)} className="h-9 w-44 rounded-lg border border-slate-200 px-2 text-sm font-bold" /></TableCell>
                    <TableCell><input value={payloadTextValue(task.round_target)} disabled={disabled} onChange={(event) => updateTask(index, "round_target", event.target.value.trim() ? event.target.value : null)} className="h-9 w-44 rounded-lg border border-slate-200 px-2 text-sm font-bold" /></TableCell>
                    <TableCell>
                      <button type="button" disabled={disabled} onClick={() => removeTask(index)} className="grid h-9 w-9 place-items-center rounded-lg border border-red-100 bg-red-50 text-red-600 disabled:opacity-40" aria-label="删除客户任务">
                        <Trash2 className="h-4 w-4" />
                      </button>
                    </TableCell>
                  </TableRow>
                )) : (
                  <TableRow>
                    <TableCell colSpan={8} className="project-table-empty">暂无客户任务，可点击“新增客户任务”补充。</TableCell>
                  </TableRow>
                )}
              </TableBody>
            </UiTable>
          </div>
        </div>
      </section>
    );
  }

  return (
    <section className="rounded-lg border border-primary/15 bg-primary-soft p-4">
      <div className="flex flex-col gap-2 md:flex-row md:items-center md:justify-between">
        <div>
          <h3 className="m-0 text-sm font-black text-slate-950">跟进记录快改</h3>
          <p className="m-0 mt-1 text-xs font-bold text-slate-500">修改跟进事实常用字段；提交后进入细节审批人审核。</p>
        </div>
        <Badge tone="neutral">任务 {payloadTextValue(sectionRecord.task_id) || "-"}</Badge>
      </div>
      <div className="mt-4 grid gap-3 md:grid-cols-3">
        <AccountField label="跟进日期">
          <input type="date" value={payloadTextValue(sectionRecord.followup_date)} disabled={disabled} onChange={(event) => updateNullableText("followup_date", event.target.value)} className="project-input" />
        </AccountField>
        <AccountField label="方式">
          <input value={payloadTextValue(sectionRecord.method)} disabled={disabled} onChange={(event) => updateNullableText("method", event.target.value)} className="project-input" />
        </AccountField>
        <AccountField label="下次跟进">
          <input type="datetime-local" value={payloadTextValue(sectionRecord.next_followup_at)} disabled={disabled} onChange={(event) => updateNullableText("next_followup_at", event.target.value)} className="project-input" />
        </AccountField>
      </div>
      <div className="mt-3 grid gap-3 md:grid-cols-2">
        <AccountField label="执行动作">
          <textarea value={payloadTextValue(sectionRecord.frontline_action)} disabled={disabled} onChange={(event) => updateNullableText("frontline_action", event.target.value)} rows={4} className="rounded-lg border border-input bg-white px-3 py-2 text-sm font-bold text-foreground disabled:bg-muted disabled:text-muted-foreground" />
        </AccountField>
        <AccountField label="客户反馈">
          <textarea value={payloadTextValue(sectionRecord.customer_feedback)} disabled={disabled} onChange={(event) => updateNullableText("customer_feedback", event.target.value)} rows={4} className="rounded-lg border border-input bg-white px-3 py-2 text-sm font-bold text-foreground disabled:bg-muted disabled:text-muted-foreground" />
        </AccountField>
        <AccountField label="当前需求">
          <textarea value={payloadTextValue(sectionRecord.current_need)} disabled={disabled} onChange={(event) => updateNullableText("current_need", event.target.value)} rows={3} className="rounded-lg border border-input bg-white px-3 py-2 text-sm font-bold text-foreground disabled:bg-muted disabled:text-muted-foreground" />
        </AccountField>
        <AccountField label="下一步动作">
          <textarea value={payloadTextValue(sectionRecord.next_action)} disabled={disabled} onChange={(event) => updateNullableText("next_action", event.target.value)} rows={3} className="rounded-lg border border-input bg-white px-3 py-2 text-sm font-bold text-foreground disabled:bg-muted disabled:text-muted-foreground" />
        </AccountField>
      </div>
      <div className="mt-3 flex flex-wrap gap-2">
        {[
          ["need_support", "需要支持"],
          ["is_closed", "本轮已闭环"]
        ].map(([field, label]) => (
          <label key={field} className="flex items-center gap-2 rounded-lg border border-slate-200 bg-white px-3 py-2 text-sm font-black text-slate-600">
            <input
              type="checkbox"
              disabled={disabled}
              checked={field === "need_support" ? Boolean(sectionRecord.need_support || sectionRecord.need_manager_support || sectionRecord.need_boss_decision) : Boolean(sectionRecord[field])}
              onChange={(event) => {
                updateField(field, event.target.checked);
                if (field === "need_support") {
                  updateField("need_manager_support", false);
                  updateField("need_boss_decision", false);
                }
              }}
              className="h-4 w-4 accent-primary"
            />
            {label}
          </label>
        ))}
      </div>
      {Boolean(sectionRecord.need_support || sectionRecord.need_manager_support || sectionRecord.need_boss_decision) ? (
        <div className="mt-3 grid gap-3 md:grid-cols-[240px_minmax(0,1fr)]">
          <AccountField label="支持类型">
            <select value={payloadTextValue(sectionRecord.need_type) || "业务协同"} disabled={disabled} onChange={(event) => updateNullableText("need_type", event.target.value)} className="project-input">
              {["业务协同", "价格政策", "资料问题", "客户异常", "管理决策", "其他"].map((option) => <option key={option} value={option}>{option}</option>)}
            </select>
          </AccountField>
          <AccountField label="支持事项说明">
            <input value={payloadTextValue(sectionRecord.current_need)} disabled={disabled} onChange={(event) => updateNullableText("current_need", event.target.value)} className="project-input" />
          </AccountField>
        </div>
      ) : null}
    </section>
  );
}

function CrmSubmissionPayloadSummary({
  payload,
  error
}: {
  payload: Record<string, unknown> | unknown[] | null | undefined;
  error?: string;
}) {
  const record = payload && !Array.isArray(payload) ? payload as Record<string, unknown> : {};
  const project = record.project && typeof record.project === "object" && !Array.isArray(record.project) ? record.project as Record<string, unknown> : null;
  const followup = record.followup && typeof record.followup === "object" && !Array.isArray(record.followup) ? record.followup as Record<string, unknown> : null;
  const tasks = Array.isArray(record.tasks) ? record.tasks : [];
  if (error) {
    return (
      <Card className="border-red-200 bg-red-50 p-4">
        <h3 className="m-0 text-sm font-black text-red-700">载荷预览不可用</h3>
        <p className="m-0 mt-2 text-sm font-bold text-red-600">请先修正 JSON 后再保存或提交。</p>
      </Card>
    );
  }
  return (
    <section className="grid gap-4 lg:grid-cols-3">
      <CustomerSideCard title="项目申请摘要" icon={BriefcaseBusiness}>
        <CustomerSideRow label="项目名称" value={displayValue(project?.project_name)} />
        <CustomerSideRow label="项目类型" value={displayValue(project?.project_type)} />
        <CustomerSideRow label="业务线" value={displayValue(project?.business_line)} />
        <CustomerSideRow label="任务数量" value={String(tasks.length)} />
      </CustomerSideCard>
      <CustomerSideCard title="跟进提交摘要" icon={History}>
        <CustomerSideRow label="项目ID" value={displayValue(followup?.project_id)} />
        <CustomerSideRow label="任务ID" value={displayValue(followup?.task_id)} />
        <CustomerSideRow label="跟进方式" value={displayValue(followup?.method)} />
        <CustomerSideRow label="是否支持" value={followup ? String(Boolean(followup.need_support || followup.need_manager_support || followup.need_boss_decision)) : "-"} />
      </CustomerSideCard>
      <CustomerSideCard title="关键内容" icon={ClipboardList}>
        <CustomerSideRow label="执行动作" value={displayValue(followup?.frontline_action)} multiline />
        <CustomerSideRow label="客户反馈" value={displayValue(followup?.customer_feedback)} multiline />
        <CustomerSideRow label="下一步" value={displayValue(followup?.next_action ?? project?.minimum_action)} multiline />
      </CustomerSideCard>
    </section>
  );
}

function CrmFollowupDraftDrawer({
  currentUser,
  onClose,
  onCreated
}: {
  currentUser: UserPublic;
  onClose: () => void;
  onCreated: (approval: ApprovalRow) => void;
}) {
  const [taskRows, setTaskRows] = useState<CrmTaskRow[]>([]);
  const [selectedTaskId, setSelectedTaskId] = useState("");
  const [followupDate, setFollowupDate] = useState(todayDateInput());
  const [method, setMethod] = useState("电话");
  const [frontlineAction, setFrontlineAction] = useState("");
  const [customerFeedback, setCustomerFeedback] = useState("");
  const [currentNeed, setCurrentNeed] = useState("");
  const [nextAction, setNextAction] = useState("");
  const [nextFollowupAt, setNextFollowupAt] = useState(datetimeLocalAfterDays(3));
  const [needSupport, setNeedSupport] = useState(false);
  const [supportType, setSupportType] = useState("业务协同");
  const [isClosed, setIsClosed] = useState(false);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");

  const selectedTask = taskRows.find((task) => String(task.id) === selectedTaskId) ?? null;

  useEffect(() => {
    let ignore = false;
    setLoading(true);
    setError("");
    crmTasksPage({ executor_user_id: currentUser.id, limit: 50, offset: 0, ...crmTaskScopeFilters("open") })
      .then((data) => {
        if (ignore) return;
        const rows = data.items.filter((task) => task.executor_user_id === currentUser.id || Boolean(currentUser.employee_code && task.executor_employee_code === currentUser.employee_code));
        setTaskRows(rows);
        if (!selectedTaskId && rows[0]) setSelectedTaskId(String(rows[0].id));
      })
      .catch((loadError) => {
        if (!ignore) {
          setTaskRows([]);
          setError(loadError instanceof Error ? loadError.message : "客户任务加载失败");
        }
      })
      .finally(() => { if (!ignore) setLoading(false); });
    return () => {
      ignore = true;
    };
  }, [currentUser.id, currentUser.employee_code]);

  const saveDraft = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setError("");
    if (!selectedTask) {
      setError("请先选择一条客户任务。");
      return;
    }
    if (!frontlineAction.trim() && !customerFeedback.trim()) {
      setError("请至少填写执行动作或客户反馈，方便后续继续编辑。");
      return;
    }
    if (needSupport && !currentNeed.trim()) {
      setError("勾选“需要支持”后，请填写支持事项说明。");
      return;
    }
    setSaving(true);
    try {
      const approvalRow = await createCrmFollowupApprovalDraft({
        title: `跟进记录草稿：${selectedTask.customer_name_snapshot}`,
        description: `客户任务 ${selectedTask.task_code} 的一线跟进草稿。`,
        priority: needSupport ? "high" : "normal",
        submit: false,
        followup: {
          project_id: selectedTask.project_id,
          task_id: selectedTask.id,
          followup_date: followupDate || null,
          method: cleanNullable(method),
          frontline_action: cleanNullable(frontlineAction),
          customer_feedback: cleanNullable(customerFeedback),
          current_need: cleanNullable(currentNeed),
          need_type: needSupport ? cleanNullable(supportType) : null,
          next_action: cleanNullable(nextAction),
          next_followup_at: nextFollowupAt || null,
          minimum_action_done: Boolean(frontlineAction.trim()),
          need_support: needSupport,
          need_manager_support: false,
          need_boss_decision: false,
          is_closed: isClosed,
          valid_feedback: Boolean(customerFeedback.trim()),
          review_status: "pending"
        }
      });
      onCreated(approvalRow);
    } catch (saveError) {
      setError(saveError instanceof Error ? saveError.message : "跟进草稿保存失败");
    } finally {
      setSaving(false);
    }
  };

  return (
    <Drawer title="新增跟进草稿" subtitle="先保存为我的提交草稿，确认后再提交审批" onClose={onClose}>
      <form className="grid gap-4" onSubmit={saveDraft}>
        <section className="rounded-lg border border-slate-200 bg-white p-4">
          <div className="flex items-start justify-between gap-3">
            <div>
              <h3 className="m-0 text-sm font-black text-slate-950">选择客户任务</h3>
              <p className="m-0 mt-1 text-sm font-bold text-slate-500">{loading ? "正在加载我的未闭环任务。" : `当前可选 ${taskRows.length} 条任务。`}</p>
            </div>
            <Badge tone={selectedTask ? "ok" : "warn"}>{selectedTask ? "已选择" : "待选择"}</Badge>
          </div>
          <div className="mt-4 grid gap-3 md:grid-cols-[minmax(0,1fr)_260px]">
            <AccountField label="客户任务">
              <select value={selectedTaskId} onChange={(event) => setSelectedTaskId(event.target.value)} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold">
                <option value="">请选择任务</option>
                {taskRows.map((task) => <option key={task.id} value={task.id}>{task.customer_name_snapshot || task.customer_code} · {task.task_code}</option>)}
              </select>
            </AccountField>
            <AccountField label="跟进日期">
              <input type="date" value={followupDate} onChange={(event) => setFollowupDate(event.target.value)} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold" />
            </AccountField>
          </div>
          {selectedTask ? (
            <div className="mt-3 grid gap-3 md:grid-cols-3">
              <CustomerSideRow label="客户编号" value={selectedTask.customer_code} />
              <CustomerSideRow label="轮次目标" value={displayValue(selectedTask.round_target)} />
              <CustomerSideRow label="反馈截止" value={formatDateTime(selectedTask.feedback_due_at)} />
            </div>
          ) : null}
        </section>

        <section className="rounded-lg border border-slate-200 bg-white p-4">
          <h3 className="m-0 text-sm font-black text-slate-950">跟进草稿内容</h3>
          <div className="mt-4 grid gap-3 md:grid-cols-3">
            <AccountField label="方式">
              <input value={method} onChange={(event) => setMethod(event.target.value)} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold" />
            </AccountField>
            <AccountField label="下次跟进">
              <input type="datetime-local" value={nextFollowupAt} onChange={(event) => setNextFollowupAt(event.target.value)} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold" />
            </AccountField>
            <label className="flex items-center gap-2 rounded-lg border border-slate-200 px-3 text-sm font-black text-slate-600">
              <input type="checkbox" checked={isClosed} onChange={(event) => setIsClosed(event.target.checked)} className="h-4 w-4 accent-primary" />
              本轮已闭环
            </label>
          </div>
          <div className="mt-3 grid gap-3 md:grid-cols-2">
            <AccountField label="执行动作">
              <textarea value={frontlineAction} onChange={(event) => setFrontlineAction(event.target.value)} rows={4} className="rounded-lg border border-slate-200 px-3 py-2 text-sm font-bold" />
            </AccountField>
            <AccountField label="客户反馈">
              <textarea value={customerFeedback} onChange={(event) => setCustomerFeedback(event.target.value)} rows={4} className="rounded-lg border border-slate-200 px-3 py-2 text-sm font-bold" />
            </AccountField>
            <AccountField label="当前需求">
              <textarea value={currentNeed} onChange={(event) => setCurrentNeed(event.target.value)} rows={3} className="rounded-lg border border-slate-200 px-3 py-2 text-sm font-bold" />
            </AccountField>
            <AccountField label="下一步动作">
              <textarea value={nextAction} onChange={(event) => setNextAction(event.target.value)} rows={3} className="rounded-lg border border-slate-200 px-3 py-2 text-sm font-bold" />
            </AccountField>
          </div>
          <div className="mt-3 flex flex-wrap gap-2">
            <label className="flex items-center gap-2 rounded-lg border border-slate-200 px-3 py-2 text-sm font-black text-slate-600">
              <input type="checkbox" checked={needSupport} onChange={(event) => setNeedSupport(event.target.checked)} className="h-4 w-4 accent-primary" />
              需要支持
            </label>
          </div>
          {needSupport ? (
            <div className="mt-3 grid gap-3 md:grid-cols-[240px_minmax(0,1fr)]">
              <AccountField label="支持类型">
                <select value={supportType} onChange={(event) => setSupportType(event.target.value)} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold">
                  {["业务协同", "价格政策", "资料问题", "客户异常", "管理决策", "其他"].map((option) => <option key={option} value={option}>{option}</option>)}
                </select>
              </AccountField>
              <AccountField label="支持事项说明">
                <input value={currentNeed} onChange={(event) => setCurrentNeed(event.target.value)} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold" />
              </AccountField>
            </div>
          ) : null}
        </section>

        {error ? <p className="m-0 rounded-lg bg-red-50 px-3 py-2 text-sm font-bold text-red-600">{error}</p> : null}
        <div className="sticky bottom-0 flex justify-end gap-2 border-t border-slate-200 bg-white/95 py-4 backdrop-blur">
          <Button secondary onClick={onClose} disabled={saving}>关闭</Button>
          <Button type="submit" disabled={saving || !selectedTask}>{saving ? "保存中" : "保存跟进草稿"}</Button>
        </div>
      </form>
    </Drawer>
  );
}

function CrmMyWorkSection({
  permissions,
  currentUser,
  navigate
}: {
  permissions: PermissionCode[];
  currentUser: UserPublic;
  navigate: (page: Page, path?: string) => void;
}) {
  const canViewTasks = hasPermission(permissions, "crm_task.view");
  const canViewApprovals = hasAnyPermission(permissions, CRM_APPROVAL_ACCESS_PERMISSIONS);
  const canCreateProject = hasPermission(permissions, "crm_project.create");
  const canSubmitCustomerProfile = hasPermission(permissions, "crm_customer_profile.view") && hasPermission(permissions, "crm_customer_profile.submit");
  const canSubmitBusinessProfile = hasPermission(permissions, "crm_business_profile.view") && hasPermission(permissions, "crm_business_profile.submit");
  const [dailyData, setDailyData] = useState<CrmDailySummary | null>(null);
  const [approvalRows, setApprovalRows] = useState<ApprovalRow[]>([]);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");

  useEffect(() => {
    let ignore = false;
    const jobs: Promise<void>[] = [];
    setLoading(true);
    setMessage("");
    if (canViewTasks) {
      jobs.push(crmDailySummary({ date: todayDateInput(), limit: 50 }).then((data) => { if (!ignore) setDailyData(data); }).catch(() => { if (!ignore) setDailyData(null); }));
    } else {
      setDailyData(null);
    }
    if (canViewApprovals) {
      jobs.push(approvalsPage({ applicant_user_id: currentUser.id, status_value: "need_supplement", limit: 10, offset: 0 }).then((data) => { if (!ignore) setApprovalRows(data.items); }).catch(() => { if (!ignore) setApprovalRows([]); }));
    } else {
      setApprovalRows([]);
    }
    Promise.allSettled(jobs)
      .then((results) => {
        if (!ignore && results.some((result) => result.status === "rejected")) setMessage("部分个人待办加载失败，已展示可读取的数据。");
      })
      .finally(() => { if (!ignore) setLoading(false); });
    return () => {
      ignore = true;
    };
  }, [canViewTasks, canViewApprovals, currentUser.id]);

  const allDueTasks = dailyData?.due_tasks ?? [];
  const myDueTasks = allDueTasks.filter((task) => task.executor_user_id === currentUser.id || (currentUser.employee_code && task.executor_employee_code === currentUser.employee_code));
  const myClosedTasks = myDueTasks.filter((task) => task.is_closed);
  const completionRate = myDueTasks.length > 0 ? Math.round((myClosedTasks.length / myDueTasks.length) * 100) : 0;

  return (
    <>
      <Header
        eyebrow="CRM MY WORK"
        title="我的工作台"
        description={`${currentUser.real_name} 的今日任务、待补充申请和个人完成情况集中在这里。审批与支持统一在执行中心处理。`}
        actions={
          <>
            {canCreateProject ? <Button secondary onClick={() => navigate("crm", "/crm/submit?mode=project")}>项目申请</Button> : null}
            {canSubmitCustomerProfile || canSubmitBusinessProfile ? <Button secondary onClick={() => navigate("crm", "/crm/customers")}>关联客户底盘</Button> : null}
            <Button onClick={() => navigate("crm", "/crm/work")}>执行中心</Button>
          </>
        }
      />
      {message ? <Card className="mb-4 border-amber-200 bg-amber-50 px-4 py-3 text-sm font-bold text-amber-700">{message}</Card> : null}
      <div className="mb-4 grid gap-3 md:grid-cols-3">
        <CrmProjectMetricCard label="今日任务" value={canViewTasks ? myDueTasks.length : "无权限"} detail={`全量可见 ${allDueTasks.length} 条`} tone={myDueTasks.length > 0 ? "neutral" : "ok"} icon={CalendarDays} onClick={() => navigate("crm", "/crm/tasks?scope=open")} />
        <CrmProjectMetricCard label="待我补充" value={canViewApprovals ? approvalRows.length : "无权限"} detail="退回后由我补充的申请" tone={approvalRows.length > 0 ? "warn" : "ok"} icon={UploadCloud} onClick={() => navigate("crm", "/crm/work?approval_scope=need_supplement")} />
        <CrmProjectMetricCard label="我的闭环率" value={canViewTasks ? `${completionRate}%` : "无权限"} detail={`今日已闭环 ${myClosedTasks.length} / ${myDueTasks.length}`} tone={completionRate >= 80 ? "ok" : "neutral"} icon={ShieldCheck} />
      </div>

      <section className="grid gap-4 xl:grid-cols-[1.35fr_0.85fr]">
        <DataTableShell title="今日任务" description={loading ? "正在读取任务。" : "只显示执行人为当前账号的今日任务。"} actions={<Button secondary onClick={() => navigate("crm", "/crm/tasks")}>任务明细</Button>}>
          <Table headers={["客户", "负责人", "状态", "反馈截止", "最近反馈"]}>
            <CrmDailyTaskRows rows={myDueTasks.slice(0, 10)} emptyMessage={canViewTasks ? "今天暂无分配给你的跟进任务。" : "当前账号没有客户任务查看权限。"} navigate={navigate} />
          </Table>
        </DataTableShell>
        <DataTableShell title="我的待补充" description="只展示由你发起、当前需要补充后重新提交的申请。" actions={<Button secondary onClick={() => navigate("crm", "/crm/work?approval_scope=need_supplement")}>继续补充</Button>}>
          <Table headers={["审批单", "类型", "状态", "处理人", "更新时间"]}>
            <CrmApprovalRows rows={approvalRows.slice(0, 10)} compact emptyMessage={canViewApprovals ? "暂无需要你补充的申请。" : "当前账号没有审批查看权限。"} navigate={navigate} />
          </Table>
        </DataTableShell>
      </section>
    </>
  );
}

type ExecutionCenterView = "approvals" | "support";

function CrmExecutionCenterSection({
  permissions,
  currentUser,
  navigate
}: {
  permissions: PermissionCode[];
  currentUser: UserPublic;
  navigate: (page: Page, path?: string) => void;
}) {
  const canListApprovals = hasAnyPermission(permissions, CRM_APPROVAL_ACCESS_PERMISSIONS);
  const canViewIssues = hasPermission(permissions, "crm_issue.view");
  const requestedApprovalId = initialPositiveQueryId("approval_id");
  const canViewApprovals = canListApprovals || Boolean(requestedApprovalId);
  const [executionView, setExecutionView] = useState<ExecutionCenterView>(() => requestedApprovalId ? "approvals" : initialQueryParam("view") === "support" || !canViewApprovals ? "support" : "approvals");
  const [approvalScope, setApprovalScope] = useState(() => initialQueryParam("approval_scope") || "my_pending");
  const [approvalStatus, setApprovalStatus] = useState(() => initialQueryParam("approval_status") || "submitted");
  const [approvalType, setApprovalType] = useState("");
  const [approvalQuery, setApprovalQuery] = useState("");
  const [issuePriority, setIssuePriority] = useState(() => initialQueryParam("priority"));
  const [approvalPageData, setApprovalPageData] = useState<ApprovalPage | null>(null);
  const [workItemPageData, setWorkItemPageData] = useState<WorkItemPage | null>(null);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");
  const [selectedApprovalId, setSelectedApprovalId] = useState<number | null>(requestedApprovalId);
  const [delayDrawerOpen, setDelayDrawerOpen] = useState(false);
  const [reloadKey, setReloadKey] = useState(0);
  const [queueCounts, setQueueCounts] = useState({ approvals: 0, support: 0, supplement: 0, completed: 0, urgentSupport: 0 });

  useEffect(() => {
    let ignore = false;
    const jobs: Promise<void>[] = [];
    setLoading(true);
    setMessage("");
    if (canListApprovals) {
      const statusValue = approvalScope === "need_supplement"
        ? "need_supplement"
        : approvalScope === "completed"
          ? "completed"
          : approvalStatus;
      jobs.push(approvalsPage({
        q: approvalQuery,
        status_value: statusValue,
        approval_type: approvalType,
        current_handler_user_id: approvalScope === "my_pending" || approvalScope === "completed" ? currentUser.id : undefined,
        applicant_user_id: approvalScope === "need_supplement" ? currentUser.id : undefined,
        limit: 12,
        offset: 0
      }).then((data) => { if (!ignore) setApprovalPageData(data); }).catch(() => { if (!ignore) setApprovalPageData(null); }));
      jobs.push(Promise.all([
        approvalsPage({ status_value: "submitted", current_handler_user_id: currentUser.id, limit: 1, offset: 0 }),
        approvalsPage({ status_value: "need_supplement", applicant_user_id: currentUser.id, limit: 1, offset: 0 }),
        approvalsPage({ status_value: "completed", current_handler_user_id: currentUser.id, limit: 1, offset: 0 })
      ]).then(([pending, supplement, completed]) => {
        if (!ignore) {
          setQueueCounts((current) => ({
            ...current,
            approvals: pending.total,
            supplement: supplement.total,
            completed: completed.total
          }));
        }
      }).catch(() => {
        if (!ignore) setQueueCounts((current) => ({ ...current, approvals: 0, supplement: 0, completed: 0 }));
      }));
    } else {
      setApprovalPageData(null);
      setQueueCounts((current) => ({ ...current, approvals: 0, supplement: 0, completed: 0 }));
    }
    if (canViewIssues) {
      jobs.push(workItemsPage({ open_only: true, priority: issuePriority, assignee_user_id: currentUser.id, limit: 12, offset: 0 }).then((data) => { if (!ignore) setWorkItemPageData(data); }).catch(() => { if (!ignore) setWorkItemPageData(null); }));
      jobs.push(Promise.all([
        workItemsPage({ open_only: true, assignee_user_id: currentUser.id, limit: 1, offset: 0 }),
        workItemsPage({ open_only: true, assignee_user_id: currentUser.id, priority: "urgent", limit: 1, offset: 0 }),
        workItemsPage({ open_only: true, assignee_user_id: currentUser.id, priority: "high", limit: 1, offset: 0 })
      ]).then(([allSupport, urgentSupport, highSupport]) => {
        if (!ignore) {
          setQueueCounts((current) => ({
            ...current,
            support: allSupport.total,
            urgentSupport: urgentSupport.total + highSupport.total
          }));
        }
      }).catch(() => {
        if (!ignore) setQueueCounts((current) => ({ ...current, support: 0, urgentSupport: 0 }));
      }));
    } else {
      setWorkItemPageData(null);
      setQueueCounts((current) => ({ ...current, support: 0, urgentSupport: 0 }));
    }
    Promise.allSettled(jobs)
      .then((results) => {
        if (!ignore && results.some((result) => result.status === "rejected")) setMessage("部分执行队列加载失败，已展示可读取的数据。");
      })
      .finally(() => { if (!ignore) setLoading(false); });
    return () => {
      ignore = true;
    };
  }, [canListApprovals, canViewIssues, approvalScope, approvalStatus, approvalType, approvalQuery, issuePriority, currentUser.id, reloadKey]);

  const approvals = approvalPageData?.items ?? [];
  const workItems = workItemPageData?.items ?? [];
  const approvalTypeOptions = [
    { value: "", label: "全部类型" },
    ...[
      "crm_project_create",
      "crm_followup_submit",
      "crm_project_extension",
      "crm_task_extension",
      "crm_project_update",
      "crm_project_close",
      "customer_profile_update",
      "customer_business_profile_update"
    ].map((value) => ({ value, label: crmApprovalTypeLabel(value) }))
  ];
  const openApprovalDetail = (approvalId: number) => {
    replaceCurrentQueryParams({ view: "approvals", approval_id: approvalId });
    setExecutionView("approvals");
    setSelectedApprovalId(approvalId);
  };
  const closeApprovalDetail = () => {
    replaceCurrentQueryParams({ approval_id: null });
    setSelectedApprovalId(null);
  };

  return (
    <>
      <Header
        eyebrow="CRM EXECUTION"
        title="执行中心"
        description="把审批、补充、待支持和闭环事项集中在一个处理队列里，减少在多个页面来回跳。"
        actions={
          <>
            <Button secondary onClick={() => navigate("crm", "/crm/my-work")}>我的工作台</Button>
            <Button secondary onClick={() => setDelayDrawerOpen(true)}>发起延期</Button>
            <Button onClick={() => navigate("crm", "/crm/issues")}>待支持事项</Button>
          </>
        }
      />
      {message ? <Card className="mb-4 border-amber-200 bg-amber-50 px-4 py-3 text-sm font-bold text-amber-700">{message}</Card> : null}
      <div className="mb-4 grid gap-3 md:grid-cols-2 xl:grid-cols-4">
        <CrmProjectMetricCard label="待我审核" value={canListApprovals ? queueCounts.approvals : "无权限"} detail="当前处理人为我" tone={queueCounts.approvals > 0 ? "neutral" : "ok"} icon={ShieldCheck} onClick={() => { setExecutionView("approvals"); setApprovalScope("my_pending"); setApprovalStatus("submitted"); }} active={executionView === "approvals" && approvalScope === "my_pending"} />
        <CrmProjectMetricCard label="待我支持" value={canViewIssues ? queueCounts.support : "无权限"} detail={`高优先 ${queueCounts.urgentSupport}`} tone={queueCounts.urgentSupport > 0 ? "bad" : queueCounts.support > 0 ? "neutral" : "ok"} icon={FileWarning} onClick={() => setExecutionView("support")} active={executionView === "support"} />
        <CrmProjectMetricCard label="待我补充" value={canListApprovals ? queueCounts.supplement : "无权限"} detail="由我发起、退回后待补充" tone={queueCounts.supplement > 0 ? "warn" : "ok"} icon={UploadCloud} onClick={() => { setExecutionView("approvals"); setApprovalScope("need_supplement"); }} active={executionView === "approvals" && approvalScope === "need_supplement"} />
        <CrmProjectMetricCard label="已完成" value={canListApprovals ? queueCounts.completed : "无权限"} detail={loading ? "正在刷新" : "由我处理完成的审批"} tone="ok" icon={ShieldCheck} onClick={() => { setExecutionView("approvals"); setApprovalScope("completed"); }} active={executionView === "approvals" && approvalScope === "completed"} />
      </div>

      {executionView === "approvals" ? <Card className="mb-4 p-3">
        <div className="flex flex-wrap gap-2">
          {[
            { value: "my_pending", label: "待我处理", desc: "处理人为我" },
            { value: "all", label: "全部审批", desc: "按权限查看" },
            { value: "need_supplement", label: "待补充", desc: "退回补充" },
            { value: "completed", label: "已完成", desc: "完成/通过" }
          ].map((item) => (
            <button
              key={item.value}
              type="button"
              onClick={() => {
                setApprovalScope(item.value);
                if (item.value === "my_pending") setApprovalStatus("submitted");
                if (item.value === "all") setApprovalStatus("");
              }}
              className={`rounded-lg border px-3 py-2 text-left transition ${approvalScope === item.value ? "border-primary bg-primary-soft text-primary-hover" : "border-slate-200 bg-white text-slate-600 hover:bg-slate-50"}`}
            >
              <span className="block text-sm font-black">{item.label}</span>
              <span className="mt-0.5 block text-xs font-bold opacity-70">{item.desc}</span>
            </button>
          ))}
        </div>
      </Card> : null}

      {executionView === "approvals" ? (
        <DataTableShell
          title="审批处理队列"
          description={loading ? "正在加载审批。" : "立项审批、跟进审核和补充请求。"}
          meta={`${approvals.length} / ${approvalPageData?.total ?? 0} 条`}
          toolbar={
            <DataToolbar onReset={() => { setApprovalStatus(""); setApprovalType(""); setApprovalQuery(""); setApprovalScope("all"); }}>
              <ToolbarSearch value={approvalQuery} onChange={setApprovalQuery} placeholder="搜索审批号、标题、说明或资源 ID" />
              <ToolbarSelect
                label="审批状态"
                value={approvalStatus}
                onChange={setApprovalStatus}
                disabled={approvalScope === "need_supplement" || approvalScope === "completed"}
                options={[{ value: "", label: "全部审批" }, ...Object.entries(crmApprovalStatusLabels).map(([value, label]) => ({ value, label }))]}
              />
              <ToolbarSelect label="审批类型" value={approvalType} onChange={setApprovalType} options={approvalTypeOptions} />
            </DataToolbar>
          }
        >
          <Table headers={["审批单", "类型", "状态", "申请人", "处理人", "更新时间"]}>
            <CrmApprovalRows
              rows={approvals}
              emptyMessage={canListApprovals ? "当前状态暂无审批单。" : "当前账号仅可查看链接指向且经后端授权的审批详情。"}
              navigate={navigate}
              onSelect={(row) => openApprovalDetail(row.id)}
            />
          </Table>
        </DataTableShell>
      ) : (
        <DataTableShell
          title="支持事项队列"
          description={loading ? "正在加载事项。" : "优先处理紧急和高优先级未闭环事项。"}
          meta={`${workItems.length} / ${workItemPageData?.total ?? 0} 条`}
          actions={<Button secondary onClick={() => navigate("crm", "/crm/issues")}>打开完整待支持页面</Button>}
          toolbar={
            <DataToolbar onReset={() => setIssuePriority("")}>
              <ToolbarSelect
                label="优先级"
                value={issuePriority}
                onChange={setIssuePriority}
                options={[{ value: "", label: "全部优先级" }, ...Object.entries(crmPriorityLabels).map(([value, label]) => ({ value, label }))]}
              />
            </DataToolbar>
          }
        >
          <Table headers={["事项", "优先级", "状态", "项目", "负责人", "到期", "更新时间"]}>
            <CrmWorkItemRows rows={workItems} emptyMessage={canViewIssues ? "暂无未闭环支持事项。" : "当前账号没有事项查看权限。"} navigate={navigate} />
          </Table>
        </DataTableShell>
      )}
      {selectedApprovalId ? (
        <CrmApprovalDetailDrawer
          approvalId={selectedApprovalId}
          canApprove={hasAnyPermission(permissions, CRM_APPROVAL_REVIEW_PERMISSIONS)}
          currentUser={currentUser}
          navigate={navigate}
          onClose={closeApprovalDetail}
          onChanged={(nextMessage) => {
            setMessage(nextMessage);
            setReloadKey((value) => value + 1);
          }}
        />
      ) : null}
      {delayDrawerOpen ? (
        <CrmDelayApprovalDrawer
          currentUser={currentUser}
          onClose={() => setDelayDrawerOpen(false)}
          onCreated={(nextMessage) => {
            setDelayDrawerOpen(false);
            setMessage(nextMessage);
            setReloadKey((value) => value + 1);
          }}
        />
      ) : null}
    </>
  );
}

function CrmApprovalDetailDrawer({
  approvalId,
  canApprove,
  currentUser,
  navigate,
  onClose,
  onChanged
}: {
  approvalId: number;
  canApprove: boolean;
  currentUser: UserPublic;
  navigate: (page: Page, path?: string) => void;
  onClose: () => void;
  onChanged: (message: string) => void;
}) {
  const [detail, setDetail] = useState<ApprovalDetail | null>(null);
  const [loading, setLoading] = useState(true);
  const [actionLoading, setActionLoading] = useState(false);
  const [comment, setComment] = useState("");
  const [supplementPayloadText, setSupplementPayloadText] = useState("");
  const [previewAttachment, setPreviewAttachment] = useState<ApprovalAttachmentRow | null>(null);
  const [previewUrl, setPreviewUrl] = useState("");
  const [previewText, setPreviewText] = useState("");
  const [previewLoading, setPreviewLoading] = useState(false);
  const [withdrawalPreview, setWithdrawalPreview] = useState<ApprovalWithdrawalPreview | null>(null);
  const [withdrawalPreviewLoading, setWithdrawalPreviewLoading] = useState(false);
  const [withdrawalDialogOpen, setWithdrawalDialogOpen] = useState(false);
  const [withdrawalReason, setWithdrawalReason] = useState("");
  const [error, setError] = useState("");

  const loadDetail = async () => {
    setError("");
    setLoading(true);
    try {
      const nextDetail = await approval(approvalId);
      setDetail(nextDetail);
      setSupplementPayloadText(JSON.stringify(nextDetail.approval.payload_json ?? {}, null, 2));
    } catch (loadError) {
      setError(loadError instanceof Error ? loadError.message : "审批详情加载失败");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    let ignore = false;
    setError("");
    setLoading(true);
    approval(approvalId)
      .then((nextDetail) => {
        if (!ignore) {
          setDetail(nextDetail);
          setSupplementPayloadText(JSON.stringify(nextDetail.approval.payload_json ?? {}, null, 2));
        }
      })
      .catch((loadError) => {
        if (!ignore) setError(loadError instanceof Error ? loadError.message : "审批详情加载失败");
      })
      .finally(() => {
        if (!ignore) setLoading(false);
      });
    return () => {
      ignore = true;
    };
  }, [approvalId]);

  useEffect(() => () => {
    if (previewUrl) URL.revokeObjectURL(previewUrl);
  }, [previewUrl]);

  const currentApproval = detail?.approval;
  const isLeadConversion = currentApproval?.approval_type === "crm_lead_convert";
  const isFollowupApproval = currentApproval?.approval_type === "crm_followup_submit";
  const isActor = currentApproval?.applicant_user_id === currentUser.id;
  const canAttach = !!currentApproval && !crmApprovalTerminal(currentApproval.status) && (isActor || canApprove);
  const canSupplement = !!currentApproval && currentApproval.status === "need_supplement" && (isActor || canApprove);
  const canReview = !!currentApproval && ["submitted", "under_review"].includes(currentApproval.status) && canApprove;
  const isCompletedProjectApproval = currentApproval?.approval_type === "crm_project_create" && currentApproval.status === "completed";

  useEffect(() => {
    let ignore = false;
    if (!isCompletedProjectApproval) {
      setWithdrawalPreview(null);
      setWithdrawalPreviewLoading(false);
      return () => {
        ignore = true;
      };
    }
    setWithdrawalPreviewLoading(true);
    approvedProjectWithdrawalPreview(approvalId)
      .then((nextPreview) => {
        if (!ignore) setWithdrawalPreview(nextPreview);
      })
      .catch((previewError) => {
        if (!ignore) setError(previewError instanceof Error ? previewError.message : "撤回资格检查失败");
      })
      .finally(() => {
        if (!ignore) setWithdrawalPreviewLoading(false);
      });
    return () => {
      ignore = true;
    };
  }, [approvalId, isCompletedProjectApproval]);

  const handleUpload = async (event: ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file || !currentApproval) return;
    setActionLoading(true);
    setError("");
    try {
      await uploadApprovalAttachment(currentApproval.id, file);
      await loadDetail();
      onChanged(`审批单 ${currentApproval.approval_no} 已上传附件。`);
    } catch (uploadError) {
      setError(uploadError instanceof Error ? uploadError.message : "附件上传失败");
    } finally {
      event.target.value = "";
      setActionLoading(false);
    }
  };

  const handleDownload = async (attachment: ApprovalAttachmentRow) => {
    if (!currentApproval) return;
    setActionLoading(true);
    setError("");
    try {
      const blob = await downloadApprovalAttachment(currentApproval.id, attachment.id);
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.download = attachment.file_name;
      document.body.appendChild(link);
      link.click();
      link.remove();
      URL.revokeObjectURL(url);
    } catch (downloadError) {
      setError(downloadError instanceof Error ? downloadError.message : "附件下载失败");
    } finally {
      setActionLoading(false);
    }
  };

  const handlePreviewAttachment = async (attachment: ApprovalAttachmentRow) => {
    if (!currentApproval || !approvalAttachmentPreviewKind(attachment)) return;
    setPreviewLoading(true);
    setError("");
    try {
      const blob = await downloadApprovalAttachment(currentApproval.id, attachment.id);
      const previewKind = approvalAttachmentPreviewKind(attachment);
      if (previewUrl) URL.revokeObjectURL(previewUrl);
      setPreviewAttachment(attachment);
      setPreviewText("");
      if (previewKind === "text") {
        setPreviewUrl("");
        setPreviewText(await blob.text());
      } else {
        setPreviewUrl(URL.createObjectURL(blob));
      }
    } catch (previewError) {
      setError(previewError instanceof Error ? previewError.message : "附件预览失败");
    } finally {
      setPreviewLoading(false);
    }
  };

  const handleDeleteAttachment = async (attachment: ApprovalAttachmentRow) => {
    if (!currentApproval) return;
    setActionLoading(true);
    setError("");
    try {
      await deleteApprovalAttachment(currentApproval.id, attachment.id);
      await loadDetail();
      onChanged(`审批单 ${currentApproval.approval_no} 已删除附件。`);
    } catch (deleteError) {
      setError(deleteError instanceof Error ? deleteError.message : "附件删除失败");
    } finally {
      setActionLoading(false);
    }
  };

  const handleReviewAction = async (mode: "approve" | "supplement" | "reject") => {
    if (!currentApproval) return;
    const trimmedComment = comment.trim();
    if (mode !== "approve" && !trimmedComment) {
      setError(mode === "supplement" ? "请填写需要申请人补充的具体内容。" : "请填写具体驳回原因。");
      return;
    }
    setActionLoading(true);
    setError("");
    try {
      let nextDetail: ApprovalDetail;
      if (mode === "approve") {
        nextDetail = await approveApproval(currentApproval.id, { comment: cleanNullable(comment) });
      } else if (mode === "supplement") {
        nextDetail = await requestApprovalSupplement(currentApproval.id, { comment: trimmedComment });
      } else {
        nextDetail = await rejectApproval(currentApproval.id, { comment: trimmedComment });
      }
      setDetail(nextDetail);
      setComment("");
      const isProfileSyncApproval = ["customer_profile_update", "customer_business_profile_update"].includes(nextDetail.approval.approval_type);
      onChanged(
        mode === "approve" && isProfileSyncApproval
          ? `审批单 ${nextDetail.approval.approval_no} 已通过，客户主数据已更新，可在主数据客户档案查看。`
          : `审批单 ${nextDetail.approval.approval_no} 已${mode === "approve" ? "通过" : mode === "supplement" ? "退回补充" : "驳回"}。`
      );
    } catch (actionError) {
      setError(actionError instanceof Error ? actionError.message : "审批处理失败");
    } finally {
      setActionLoading(false);
    }
  };

  const handleSupplement = async () => {
    if (!currentApproval) return;
    setActionLoading(true);
    setError("");
    try {
      const payloadText = supplementPayloadText.trim();
      const parsedPayload = payloadText ? JSON.parse(payloadText) as Record<string, unknown> | unknown[] : currentApproval.payload_json ?? undefined;
      const nextDetail = await supplementApproval(currentApproval.id, {
        comment: cleanNullable(comment) || "已补充审批材料",
        payload_json: parsedPayload
      });
      setDetail(nextDetail);
      setComment("");
      onChanged(`审批单 ${nextDetail.approval.approval_no} 已补充并重新提交。`);
    } catch (supplementError) {
      setError(supplementError instanceof SyntaxError ? "补充载荷不是合法 JSON。" : supplementError instanceof Error ? supplementError.message : "补充提交失败");
    } finally {
      setActionLoading(false);
    }
  };

  const handleWithdrawApprovedProject = async () => {
    if (!currentApproval || !withdrawalPreview?.can_withdraw) return;
    const reason = withdrawalReason.trim();
    if (reason.length < 5) {
      setError("撤回原因至少需要 5 个字符。");
      return;
    }
    setActionLoading(true);
    setError("");
    try {
      const nextDetail = await withdrawApprovedProject(currentApproval.id, reason);
      setDetail(nextDetail);
      setWithdrawalDialogOpen(false);
      setWithdrawalReason("");
      setWithdrawalPreview(null);
      onChanged(`审批单 ${nextDetail.approval.approval_no} 已撤回，项目已冻结并退回申请人补充。`);
    } catch (withdrawError) {
      setError(withdrawError instanceof Error ? withdrawError.message : "撤回审核失败");
    } finally {
      setActionLoading(false);
    }
  };

  return (
    <Drawer title="审批详情" subtitle={currentApproval ? `${currentApproval.approval_no} · ${currentApproval.title}` : "正在加载审批单"} onClose={onClose}>
      {loading ? <CrmDrawerLoading /> : null}
      {!loading && detail && currentApproval ? (
        <div className="grid gap-4">
          <ApprovalBusinessHeader approval={currentApproval} />
          <ApprovalReturnFeedbackPanel approval={currentApproval} />
          {currentApproval.approval_type === "crm_project_create" ? <ProjectApplicationApprovalSummary approval={currentApproval} navigate={navigate} /> : null}
          {isFollowupApproval ? <FollowupApprovalBusinessSummary approval={currentApproval} navigate={navigate} /> : null}
          {isLeadConversion ? <CrmLeadConversionApprovalSummary approval={currentApproval} /> : null}

          {isCompletedProjectApproval ? (
            <section className="rounded-lg border border-amber-200 bg-amber-50 p-4" data-testid="project-approval-withdrawal-panel">
              <div className="flex flex-wrap items-start justify-between gap-3">
                <div className="min-w-0">
                  <h3 className="m-0 text-sm font-black text-amber-950">撤回已通过审核</h3>
                  <p className="m-0 mt-1 text-xs font-bold leading-5 text-amber-800">
                    撤回后项目、任务和历史记录不会删除；项目会冻结并退回申请人补充，重新通过后更新原项目。
                  </p>
                  {withdrawalPreview?.deadline ? <p className="m-0 mt-2 text-xs font-black text-amber-900">普通撤回截止：{formatDateTime(withdrawalPreview.deadline)}</p> : null}
                  {withdrawalPreview?.is_override ? <p className="m-0 mt-1 text-xs font-black text-red-700">当前操作将按管理员越权撤回执行，不受 24 小时时限限制。</p> : null}
                  {!withdrawalPreviewLoading && withdrawalPreview && !withdrawalPreview.can_withdraw ? (
                    <p className="m-0 mt-2 text-xs font-bold text-red-700">不可撤回：{withdrawalPreview.blockers.join("；") || "当前审批不满足撤回条件"}</p>
                  ) : null}
                </div>
                <Button
                  secondary
                  disabled={actionLoading || withdrawalPreviewLoading || !withdrawalPreview?.can_withdraw}
                  onClick={() => setWithdrawalDialogOpen(true)}
                >
                  {withdrawalPreviewLoading ? "检查资格中" : "撤回审核"}
                </Button>
              </div>
            </section>
          ) : null}

          <CustomerProfileApprovalDiff approval={currentApproval} navigate={navigate} />
          <BusinessProfileApprovalDiff approval={currentApproval} navigate={navigate} />

          {!isLeadConversion && !isFollowupApproval && currentApproval.approval_type !== "crm_project_create" ? <ApprovalContextSummary approval={currentApproval} events={detail.events} attachments={detail.attachments} navigate={navigate} /> : null}

          <section className="grid gap-4 xl:grid-cols-[1fr_0.9fr]">
            <div className="rounded-lg border border-slate-200 bg-white p-4">
              <div className="flex flex-wrap items-center justify-between gap-3">
                <div>
                  <h3 className="m-0 text-sm font-black text-slate-950">审批附件</h3>
                  <p className="m-0 mt-1 text-xs font-bold text-slate-500">用于补充报价、截图、说明文件和延期依据。</p>
                </div>
                {canAttach ? (
                  <label className="inline-flex cursor-pointer items-center gap-2 rounded-lg border border-primary px-3 py-2 text-sm font-black text-primary-hover transition hover:bg-primary-soft">
                    <UploadCloud className="h-4 w-4" />
                    上传附件
                    <input type="file" className="hidden" disabled={actionLoading} onChange={handleUpload} />
                  </label>
                ) : null}
              </div>
              <div className="mt-3 grid gap-2">
                {detail.attachments.length === 0 ? (
                  <p className="m-0 rounded-lg bg-slate-50 px-3 py-4 text-sm font-bold text-slate-500">暂无附件。</p>
                ) : detail.attachments.map((attachmentItem) => (
                  <div key={attachmentItem.id} className="flex flex-wrap items-center justify-between gap-3 rounded-lg border border-slate-200 px-3 py-2">
                    <div className="min-w-0">
                      <strong className="block max-w-[360px] truncate text-sm text-slate-950">{attachmentItem.file_name}</strong>
                      <span className="mt-1 block text-xs font-bold text-slate-400">
                        {imageFormatBytes(attachmentItem.size_bytes)} · 上传人 {attachmentItem.created_by_user_label || (attachmentItem.created_by_user_id ? "账号信息缺失" : "系统")} · {formatDateTime(attachmentItem.created_at)}
                      </span>
                    </div>
                    <div className="flex items-center gap-2">
                      {approvalAttachmentPreviewKind(attachmentItem) ? <Button secondary onClick={() => handlePreviewAttachment(attachmentItem)} disabled={actionLoading || previewLoading}>预览</Button> : null}
                      <Button secondary onClick={() => handleDownload(attachmentItem)} disabled={actionLoading}>下载</Button>
                      {canAttach ? <Button secondary onClick={() => handleDeleteAttachment(attachmentItem)} disabled={actionLoading}>删除</Button> : null}
                    </div>
                  </div>
                ))}
              </div>
              {previewAttachment ? (
                <div className="mt-4 rounded-lg border border-primary/20 bg-primary-soft p-3">
                  <div className="flex flex-wrap items-center justify-between gap-3">
                    <div>
                      <strong className="block text-sm text-slate-950">附件预览</strong>
                      <span className="mt-1 block text-xs font-bold text-slate-500">{previewAttachment.file_name}</span>
                    </div>
                    <button
                      type="button"
                      onClick={() => {
                        if (previewUrl) URL.revokeObjectURL(previewUrl);
                        setPreviewAttachment(null);
                        setPreviewUrl("");
                        setPreviewText("");
                      }}
                      className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-xs font-black text-slate-600 hover:bg-slate-50"
                    >
                      关闭预览
                    </button>
                  </div>
                  {previewLoading ? <p className="m-0 mt-3 rounded-lg bg-white px-3 py-4 text-sm font-bold text-slate-500">正在生成预览。</p> : null}
                  {!previewLoading && approvalAttachmentPreviewKind(previewAttachment) === "image" && previewUrl ? (
                    <img src={previewUrl} alt={previewAttachment.file_name} className="mt-3 max-h-[420px] w-full rounded-lg border border-slate-200 bg-white object-contain" />
                  ) : null}
                  {!previewLoading && approvalAttachmentPreviewKind(previewAttachment) === "pdf" && previewUrl ? (
                    <iframe title={previewAttachment.file_name} src={previewUrl} className="mt-3 h-[420px] w-full rounded-lg border border-slate-200 bg-white" />
                  ) : null}
                  {!previewLoading && approvalAttachmentPreviewKind(previewAttachment) === "text" ? (
                    <pre className="mt-3 max-h-[420px] overflow-auto whitespace-pre-wrap rounded-lg border border-slate-200 bg-white p-3 text-xs leading-5 text-slate-700">{previewText || "该文本附件为空。"}</pre>
                  ) : null}
                </div>
              ) : null}
            </div>

            <div className="rounded-lg border border-slate-200 bg-white p-4">
              <h3 className="m-0 text-sm font-black text-slate-950">审批动作</h3>
              <AccountField label="处理意见（要求补充或驳回时必填）">
                <textarea value={comment} onChange={(event) => setComment(event.target.value)} rows={4} className="mt-3 rounded-lg border border-slate-200 px-3 py-2 text-sm font-bold" placeholder="请具体说明需要补充的内容或驳回原因；审批通过时可选填。" />
              </AccountField>
              {canSupplement ? (
                <details className="mt-3 rounded-lg border border-slate-200 bg-slate-50 p-3">
                  <summary className="cursor-pointer text-sm font-black text-slate-700">高级补充数据（一般无需修改）</summary>
                  <AccountField label="补充后的系统载荷">
                    <textarea value={supplementPayloadText} onChange={(event) => setSupplementPayloadText(event.target.value)} rows={7} className="mt-3 rounded-lg border border-slate-200 bg-white px-3 py-2 font-mono text-xs" />
                  </AccountField>
                </details>
              ) : null}
              <div className="mt-4 flex flex-wrap justify-end gap-2">
                {canSupplement ? <Button onClick={handleSupplement} disabled={actionLoading}>补充并重新提交</Button> : null}
                {canReview ? (
                  <>
                    <Button secondary onClick={() => handleReviewAction("supplement")} disabled={actionLoading}>要求补充</Button>
                    <Button secondary onClick={() => handleReviewAction("reject")} disabled={actionLoading}>驳回</Button>
                    <Button onClick={() => handleReviewAction("approve")} disabled={actionLoading}>审批通过</Button>
                  </>
                ) : null}
                {!canReview && !canSupplement ? <span className="text-sm font-bold text-slate-400">当前状态暂无可执行审批动作。</span> : null}
              </div>
            </div>
          </section>

          <section className="grid gap-4 xl:grid-cols-[0.9fr_1.1fr]">
            <div className="rounded-lg border border-slate-200 bg-white p-4">
              <h3 className="m-0 text-sm font-black text-slate-950">审批时间线</h3>
              <div className="mt-4 grid gap-3">
                {detail.events.length > 0 ? detail.events.map((eventItem) => (
                  <div key={eventItem.id} className="relative border-l-2 border-slate-200 pl-4">
                    <span className="absolute -left-[7px] top-1 h-3 w-3 rounded-full border-2 border-white bg-primary" />
                    <div className="flex flex-wrap items-center justify-between gap-2">
                      <strong className="text-sm text-slate-950">{approvalEventLabel(eventItem.event_type)}</strong>
                      <span className="text-xs font-bold text-slate-400">{formatDateTime(eventItem.created_at)}</span>
                    </div>
                    <p className="m-0 mt-1 text-xs font-bold text-slate-500">
                      操作人 {eventItem.operator_user_label || (eventItem.operator_user_id ? "账号信息缺失" : "系统")} · {crmApprovalStatusLabels[eventItem.from_status ?? ""] ?? displayValue(eventItem.from_status)} → {crmApprovalStatusLabels[eventItem.to_status ?? ""] ?? displayValue(eventItem.to_status)}
                    </p>
                    {eventItem.comment ? <p className="m-0 mt-2 rounded-lg bg-slate-50 px-3 py-2 text-sm font-bold text-slate-600">{eventItem.comment}</p> : null}
                  </div>
                )) : <p className="m-0 rounded-lg bg-slate-50 px-3 py-4 text-sm font-bold text-slate-500">暂无审批处理记录。</p>}
              </div>
            </div>
            <CrmJsonPreview title={isLeadConversion ? "系统信息（原始载荷）" : "系统信息"} payload={currentApproval.payload_json} result={currentApproval.result_json} />
          </section>
        </div>
      ) : null}
      {error ? <p className="mt-4 rounded-lg bg-red-50 px-3 py-2 text-sm font-bold text-red-600">{error}</p> : null}
      {withdrawalDialogOpen && withdrawalPreview ? (
        <Modal title="确认撤回已通过项目审核" onClose={() => !actionLoading && setWithdrawalDialogOpen(false)}>
          <div className="grid gap-4" data-testid="project-approval-withdrawal-dialog">
            <div className="rounded-lg border border-red-200 bg-red-50 p-4">
              <strong className="block text-sm font-black text-red-900">撤回后项目立即冻结</strong>
              <p className="m-0 mt-1 text-sm font-bold leading-6 text-red-700">全部历史继续保留，但任务、跟进、待办和关联审批在重新通过前不能继续处理。</p>
            </div>
            <div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-4">
              {[
                ["任务", withdrawalPreview.impact_counts.tasks ?? 0],
                ["跟进", withdrawalPreview.impact_counts.followups ?? 0],
                ["待办", withdrawalPreview.impact_counts.work_items ?? 0],
                ["待处理审批", withdrawalPreview.impact_counts.pending_approvals ?? 0]
              ].map(([label, value]) => (
                <div key={String(label)} className="rounded-lg border border-slate-200 bg-slate-50 p-3">
                  <span className="block text-xs font-black text-slate-500">{label}</span>
                  <strong className="mt-1 block text-xl font-black text-slate-950">{value}</strong>
                </div>
              ))}
            </div>
            <AccountField label="撤回原因（必填，5–1000 字）">
              <textarea
                value={withdrawalReason}
                onChange={(event) => setWithdrawalReason(event.target.value.slice(0, 1000))}
                rows={5}
                autoFocus
                className="mt-2 rounded-lg border border-slate-200 px-3 py-2 text-sm font-bold leading-6"
                placeholder="说明审批通过后发现的问题，以及申请人需要补充或修正的内容。"
              />
              <span className="mt-1 text-right text-xs font-bold text-slate-400">{withdrawalReason.trim().length}/1000</span>
            </AccountField>
            <div className="flex flex-wrap justify-end gap-2">
              <Button secondary disabled={actionLoading} onClick={() => setWithdrawalDialogOpen(false)}>取消</Button>
              <Button disabled={actionLoading || withdrawalReason.trim().length < 5} onClick={() => void handleWithdrawApprovedProject()}>
                {actionLoading ? "撤回处理中" : "确认撤回并冻结项目"}
              </Button>
            </div>
          </div>
        </Modal>
      ) : null}
    </Drawer>
  );
}

function CrmDelayApprovalDrawer({
  currentUser,
  onClose,
  onCreated
}: {
  currentUser: UserPublic;
  onClose: () => void;
  onCreated: (message: string) => void;
}) {
  const [approvalType, setApprovalType] = useState<"crm_project_extension" | "crm_task_extension">("crm_project_extension");
  const [targetId, setTargetId] = useState("");
  const [handlerUserId, setHandlerUserId] = useState(String(currentUser.id));
  const [projectDueDate, setProjectDueDate] = useState(dateInputAfterDays(7));
  const [taskDueAt, setTaskDueAt] = useState(datetimeLocalAfterDays(3));
  const [reason, setReason] = useState("");
  const [progressSummary, setProgressSummary] = useState("");
  const [priority, setPriority] = useState("normal");
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState("");

  const [userRows, setUserRows] = useState<UserPublic[]>([]);

  useEffect(() => {
    void users("", "active").then(setUserRows).catch(() => setUserRows([]));
  }, []);

  const submitDelay = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setError("");
    if (!targetId.trim()) {
      setError("请填写目标 ID。");
      return;
    }
    setSubmitting(true);
    try {
      const targetNumber = Number(targetId);
      const isProject = approvalType === "crm_project_extension";
      const payloadJson = isProject
        ? {
            project_id: targetNumber,
            requested_due_date: projectDueDate,
            reason: cleanNullable(reason),
            progress_summary: cleanNullable(progressSummary)
          }
        : {
            task_id: targetNumber,
            requested_feedback_due_at: taskDueAt,
            reason: cleanNullable(reason),
            progress_summary: cleanNullable(progressSummary)
          };
      const created = await createApproval({
        approval_type: approvalType,
        resource_type: isProject ? "crm_project" : "crm_project_customer_task",
        resource_id: targetId.trim(),
        title: `${isProject ? "项目" : "客户任务"}延期申请 #${targetId.trim()}`,
        description: cleanNullable(reason),
        current_handler_user_id: Number(handlerUserId) || currentUser.id,
        priority,
        payload_json: payloadJson,
        submit: true
      });
      onCreated(`延期审批 ${created.approval_no} 已提交。`);
    } catch (submitError) {
      setError(submitError instanceof Error ? submitError.message : "延期审批提交失败");
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <Drawer title="发起延期审批" subtitle="项目延期和客户任务延期统一进入审批中心" onClose={onClose}>
      <form className="grid gap-4" onSubmit={submitDelay}>
        <section className="rounded-lg border border-slate-200 bg-white p-4">
          <div className="grid gap-3 md:grid-cols-2">
            <AccountField label="延期类型">
              <select value={approvalType} onChange={(event) => setApprovalType(event.target.value as "crm_project_extension" | "crm_task_extension")} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold">
                <option value="crm_project_extension">项目延期</option>
                <option value="crm_task_extension">客户任务延期</option>
              </select>
            </AccountField>
            <AccountField label={approvalType === "crm_project_extension" ? "项目 ID" : "客户任务 ID"}>
              <input value={targetId} onChange={(event) => setTargetId(event.target.value)} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold" placeholder="填写系统内部 ID" />
            </AccountField>
            <CrmUserPicker label="审批处理人" value={handlerUserId} onChange={setHandlerUserId} users={userRows} disabled={submitting} />
            <AccountField label="优先级">
              <select value={priority} onChange={(event) => setPriority(event.target.value)} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold">
                <option value="normal">普通</option>
                <option value="high">高</option>
                <option value="urgent">紧急</option>
              </select>
            </AccountField>
            {approvalType === "crm_project_extension" ? (
              <AccountField label="新的项目截止日期">
                <input type="date" value={projectDueDate} onChange={(event) => setProjectDueDate(event.target.value)} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold" />
              </AccountField>
            ) : (
              <AccountField label="新的任务反馈截止时间">
                <input type="datetime-local" value={taskDueAt} onChange={(event) => setTaskDueAt(event.target.value)} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold" />
              </AccountField>
            )}
          </div>
          <div className="mt-3 grid gap-3 md:grid-cols-2">
            <AccountField label="延期原因">
              <textarea value={reason} onChange={(event) => setReason(event.target.value)} rows={5} className="rounded-lg border border-slate-200 px-3 py-2 text-sm font-bold" placeholder="说明延期的业务原因、客户状态或内部阻塞。" />
            </AccountField>
            <AccountField label="当前进展">
              <textarea value={progressSummary} onChange={(event) => setProgressSummary(event.target.value)} rows={5} className="rounded-lg border border-slate-200 px-3 py-2 text-sm font-bold" placeholder="说明已完成动作、待完成动作和新的闭环计划。" />
            </AccountField>
          </div>
        </section>
        {error ? <p className="m-0 rounded-lg bg-red-50 px-3 py-2 text-sm font-bold text-red-600">{error}</p> : null}
        <div className="sticky bottom-0 flex justify-end gap-2 border-t border-slate-200 bg-white/95 py-4 backdrop-blur">
          <Button secondary onClick={onClose}>关闭</Button>
          <Button type="submit" disabled={submitting}>{submitting ? "提交中" : "提交延期审批"}</Button>
        </div>
      </form>
    </Drawer>
  );
}

function CrmJsonPreview({
  title,
  payload,
  result
}: {
  title: string;
  payload?: Record<string, unknown> | unknown[] | null;
  result?: Record<string, unknown> | unknown[] | null;
}) {
  return (
    <details className="rounded-lg border border-slate-200 bg-white p-4">
      <summary className="cursor-pointer text-sm font-black text-slate-950">{title}</summary>
      <div className="mt-3 grid gap-3">
        <div>
          <span className="text-xs font-black uppercase tracking-[0.12em] text-slate-400">PAYLOAD</span>
          <pre className="mt-2 max-h-52 overflow-auto rounded-lg bg-slate-950 p-3 text-xs leading-5 text-slate-100">{JSON.stringify(payload ?? {}, null, 2)}</pre>
        </div>
        <div>
          <span className="text-xs font-black uppercase tracking-[0.12em] text-slate-400">RESULT</span>
          <pre className="mt-2 max-h-52 overflow-auto rounded-lg bg-slate-950 p-3 text-xs leading-5 text-slate-100">{JSON.stringify(result ?? {}, null, 2)}</pre>
        </div>
      </div>
    </details>
  );
}

