function ApprovalBusinessHeader({ approval }: { approval: ApprovalRow }) {
  const isTerminal = crmApprovalTerminal(approval.status);
  const statusLabel = crmApprovalStatusLabels[approval.status] ?? approval.status;
  return (
    <section className="rounded-lg border border-slate-200 bg-white p-4 shadow-sm">
      <div className="flex flex-wrap items-start justify-between gap-3">
        <div className="min-w-0">
          <p className="m-0 text-xs font-black uppercase tracking-[0.16em] text-primary">{crmApprovalTypeLabel(approval.approval_type)}</p>
          <h3 className="m-0 mt-1 break-words text-lg font-black text-slate-950">{approval.title}</h3>
          {approval.description ? <p className="m-0 mt-2 break-words text-sm font-bold leading-6 text-slate-500">{approval.description}</p> : null}
        </div>
        <Badge tone={crmStatusTone(approval.status)}>{statusLabel}</Badge>
      </div>
      <div className="mt-4 grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
        <CustomerMeta label="申请人" value={approvalUserLabel(approval, "applicant")} />
        <CustomerMeta label="当前处理人" value={approvalUserLabel(approval, "handler")} />
        <CustomerMeta label="提交时间" value={formatDateTime(approval.submitted_at ?? approval.created_at)} />
        <CustomerMeta label={isTerminal ? "完成时间" : "优先级"} value={isTerminal ? formatDateTime(approval.closed_at ?? approval.reviewed_at ?? approval.updated_at) : crmPriorityLabels[approval.priority] ?? approval.priority} />
      </div>
    </section>
  );
}

function approvalRecordList(value: unknown): Record<string, unknown>[] {
  if (!Array.isArray(value)) return [];
  return value.filter((item): item is Record<string, unknown> => !!item && !Array.isArray(item) && typeof item === "object");
}

function approvalStringList(value: unknown): string[] {
  return Array.isArray(value) ? value.map((item) => String(item ?? "").trim()).filter(Boolean) : [];
}

function ProjectApplicationApprovalSummary({ approval, navigate }: { approval: ApprovalRow; navigate: (page: Page, path?: string) => void }) {
  if (approval.approval_type !== "crm_project_create") return null;
  const summary = approvalBusinessSummaryRecord(approval);
  const payload = approvalPayloadRecord(approval.payload_json);
  const project = Object.keys(approvalNestedRecord(summary, "project")).length > 0
    ? approvalNestedRecord(summary, "project")
    : approvalNestedRecord(payload, "project");
  const people = approvalNestedRecord(summary, "people");
  const tasks = approvalRecordList(summary.tasks).length > 0 ? approvalRecordList(summary.tasks) : approvalRecordList(payload.tasks);
  const projectId = approvalFieldValue(project, ["project_id", "id"]);
  const frontline = approvalStringList(people.frontline);
  const progressCc = approvalStringList(people.progress_cc);
  const reviewWithdrawal = approvalNestedRecord(summary, "review_withdrawal");
  const withdrawalReason = String(reviewWithdrawal.reason ?? "").trim();

  return (
    <section className="grid gap-4">
      {reviewWithdrawal.state === "withdrawn" || withdrawalReason ? (
        <div className="rounded-lg border border-amber-200 bg-amber-50 p-4" data-testid="project-approval-frozen-banner">
          <div className="flex flex-wrap items-start justify-between gap-3">
            <div>
              <strong className="block text-sm font-black text-amber-950">项目审批已撤回，当前冻结</strong>
              <p className="m-0 mt-1 whitespace-pre-wrap text-sm font-bold leading-6 text-amber-800">撤回原因：{withdrawalReason || "未记录"}</p>
            </div>
            <Badge tone="warn">等待申请人补充</Badge>
          </div>
          <p className="m-0 mt-2 text-xs font-bold text-amber-700">
            撤回人：{displayValue(reviewWithdrawal.withdrawn_by_user_label)} · 撤回时间：{formatDateTime(reviewWithdrawal.withdrawn_at)}
          </p>
        </div>
      ) : null}
      <div className="grid gap-4 xl:grid-cols-2">
        <CustomerSideCard title="项目与人员" icon={BriefcaseBusiness}>
          <CustomerSideRow label="项目名称" value={displayValue(project.project_name)} multiline />
          <CustomerSideRow label="项目类型" value={displayValue(project.project_type)} />
          <CustomerSideRow label="项目目的" value={displayValue(project.purpose)} multiline />
          <CustomerSideRow label="业务线" value={displayValue(project.business_line)} />
          <CustomerSideRow label="申请人" value={displayValue(people.applicant ?? approvalUserLabel(approval, "applicant"))} />
          <CustomerSideRow label="项目落地审批人" value={displayValue(people.landing_approver ?? approvalUserLabel(approval, "handler"))} />
          <CustomerSideRow label="细节审批人" value={displayValue(people.detail_approver)} />
          <CustomerSideRow label="一线业务员" value={frontline.length > 0 ? frontline.join("、") : "未分配"} multiline />
          <CustomerSideRow label="项目进展抄送人" value={progressCc.length > 0 ? progressCc.join("、") : "未设置"} multiline />
        </CustomerSideCard>
        <CustomerSideCard title="推进与闭环口径" icon={Clock3}>
          <CustomerSideRow label="开始日期" value={formatDate(project.start_date)} />
          <CustomerSideRow label="截止日期" value={formatDate(project.due_date)} />
          <CustomerSideRow label="最小动作" value={displayValue(project.minimum_action)} multiline />
          <CustomerSideRow label="闭环标准" value={displayValue(project.closure_standard)} multiline />
          <CustomerSideRow label="客户任务数" value={`${tasks.length} 个客户`} />
          {projectId ? <div className="mt-3"><Button secondary onClick={() => navigate("crm", `/crm/projects/${projectId}`)}>打开项目详情</Button></div> : null}
        </CustomerSideCard>
      </div>
      <CustomerSideCard title="客户任务分配" icon={UsersRound}>
        <div className="mt-1 overflow-x-auto rounded-lg border border-slate-200">
          <table className="min-w-[820px] w-full text-left text-sm">
            <thead className="bg-slate-50 text-xs font-black text-slate-500">
              <tr><th className="px-3 py-2">客户</th><th className="px-3 py-2">执行人</th><th className="px-3 py-2">业务问题</th><th className="px-3 py-2">本轮目标</th><th className="px-3 py-2">反馈截止</th></tr>
            </thead>
            <tbody>
              {tasks.length > 0 ? tasks.map((task, index) => (
                <tr key={`${String(task.customer_code ?? "customer")}-${index}`} className="border-t border-slate-100 align-top">
                  <td className="px-3 py-2"><strong className="block text-slate-900">{displayValue(task.customer_name)}</strong><span className="text-xs font-bold text-slate-400">{displayValue(task.customer_code)}</span></td>
                  <td className="px-3 py-2 font-bold text-slate-700">{displayValue(task.executor)}</td>
                  <td className="max-w-[240px] break-words px-3 py-2 font-bold text-slate-600">{displayValue(task.business_issue_point)}</td>
                  <td className="max-w-[240px] break-words px-3 py-2 font-bold text-slate-600">{displayValue(task.round_target)}</td>
                  <td className="px-3 py-2 font-bold text-slate-600">{formatDateTime(task.feedback_due_at)}</td>
                </tr>
              )) : <tr><td colSpan={5} className="px-3 py-6 text-center font-bold text-slate-400">当前申请没有客户任务明细。</td></tr>}
            </tbody>
          </table>
        </div>
      </CustomerSideCard>
    </section>
  );
}

function CrmLeadConversionApprovalSummary({ approval }: { approval: ApprovalRow }) {
  const summary = approvalBusinessSummaryRecord(approval);
  const payload = approvalPayloadRecord(approval.payload_json);
  const result = approvalPayloadRecord(approval.result_json);
  const summaryBefore = approvalNestedRecord(summary, "before");
  const summaryAfter = approvalNestedRecord(summary, "after");
  const before = Object.keys(summaryBefore).length > 0 ? summaryBefore : approvalNestedRecord(payload, "before");
  const after = Object.keys(summaryAfter).length > 0 ? summaryAfter : approvalNestedRecord(payload, "after");
  const summaryPrefill = approvalNestedRecord(summary, "project_prefill");
  const resultPrefill = approvalNestedRecord(result, "project_prefill");
  const projectPrefill = Object.keys(summaryPrefill).length > 0 ? summaryPrefill : resultPrefill;
  const attribution = approvalNestedRecord(result, "attribution");
  const campaign = approvalNestedRecord(attribution, "campaign");
  const customerCode = displayValue(summary.customer_code ?? result.customer_code ?? projectPrefill.customer_code);
  const sync = crmLeadConversionSyncState(approval, summary, customerCode);
  const leadName = displayValue(summary.lead_name ?? before.lead_name);
  const companyName = displayValue(summary.company_name ?? before.company_name ?? before.lead_name);
  const contactName = displayValue(summary.contact_name ?? before.contact_name);
  const contactPhone = displayValue(summary.contact_phone ?? before.contact_phone);
  const address = displayValue(summary.address ?? before.address);
  const customerGroupName = displayValue(summary.customer_group_name ?? before.customer_group_name);
  const projectPrefillState = Object.keys(projectPrefill).length > 0
    ? "已生成，需人工确认创建项目"
    : sync.tone === "ok" ? "未提供项目预填" : "转正通过后自动生成";
  const changes = Object.entries(after)
    .map(([field, afterValue]) => ({
      field,
      label: crmLeadConversionChangeLabels[field] ?? field,
      before: field === "customer_name" ? before.company_name ?? before.lead_name : before[field],
      after: field === "customer_code_pattern" && customerCode !== "-" ? customerCode : afterValue
    }))
    .filter((item) => item.after !== null && item.after !== undefined && item.after !== "");

  return (
    <section className="rounded-lg border border-primary/20 bg-white p-4 shadow-sm">
      <div className="flex flex-wrap items-start justify-between gap-3">
        <div className="min-w-0">
          <h3 className="m-0 text-base font-black text-slate-950">线索转正结果</h3>
          <p className="m-0 mt-1 break-words text-xs font-bold text-slate-500">审批通过后建立客户主档；项目仅生成预填信息，仍需人工确认创建。</p>
        </div>
        <Badge tone={sync.tone}>{sync.label}</Badge>
      </div>
      <div className="mt-4 grid gap-4 lg:grid-cols-3">
        <CustomerSideCard title="线索与客户" icon={UsersRound}>
          <CustomerSideRow label="线索名称" value={leadName} />
          <CustomerSideRow label="公司" value={companyName} multiline />
          <CustomerSideRow label="联系人" value={contactName} />
          <CustomerSideRow label="联系电话" value={contactPhone} />
          <CustomerSideRow label="详细地址" value={address} multiline />
          <CustomerSideRow label="客户群名称" value={customerGroupName} multiline />
        </CustomerSideCard>
        <CustomerSideCard title="审批处理" icon={ShieldCheck}>
          <CustomerSideRow label="审批状态" value={crmApprovalStatusLabels[approval.status] ?? approval.status} />
          <CustomerSideRow label="转正状态" value={sync.label} multiline />
          <CustomerSideRow label="申请人" value={approvalUserLabel(approval, "applicant")} />
          <CustomerSideRow label="处理人" value={approvalUserLabel(approval, "handler")} />
        </CustomerSideCard>
        <CustomerSideCard title="建档与项目" icon={BriefcaseBusiness}>
          <CustomerSideRow label="结果客户编号" value={customerCode} />
          <CustomerSideRow label="客户主档同步" value={sync.label} multiline />
          <CustomerSideRow label="项目预填" value={projectPrefillState} multiline />
          <CustomerSideRow label="预填项目" value={displayValue(projectPrefill.project_name)} multiline />
        </CustomerSideCard>
        <CustomerSideCard title="归因信息" icon={Tag}>
          <CustomerSideRow label="归因来源" value={displayValue(attribution.source)} />
          <CustomerSideRow label="活动" value={displayValue(campaign.campaign_name ?? campaign.campaign_code)} multiline />
          <CustomerSideRow label="负责人" value={displayValue(attribution.owner_label ?? attribution.assigned_user_label)} />
        </CustomerSideCard>
      </div>
      <div className="mt-4 overflow-x-auto rounded-lg border border-slate-200">
        <table className="min-w-[640px] w-full text-left text-sm">
          <thead className="bg-slate-50 text-xs font-black text-slate-500">
            <tr><th className="px-3 py-2">变更字段</th><th className="px-3 py-2">申请前</th><th className="px-3 py-2">转正后</th></tr>
          </thead>
          <tbody>
            {changes.length > 0 ? changes.map((item) => (
              <tr key={item.field} className="border-t border-slate-100 align-top">
                <td className="px-3 py-2 font-black text-slate-800">{item.label}</td>
                <td className="max-w-[280px] break-words px-3 py-2 font-bold text-slate-500">{approvalDiffValue(item.before)}</td>
                <td className="max-w-[280px] break-words px-3 py-2 font-black text-primary">{approvalDiffValue(item.after)}</td>
              </tr>
            )) : <tr><td className="px-3 py-6 text-center font-bold text-slate-400" colSpan={3}>暂无可展示的转正变更字段。</td></tr>}
          </tbody>
        </table>
      </div>
    </section>
  );
}

function crmLeadConversionSyncState(approval: ApprovalRow, summary: Record<string, unknown>, customerCode: string): { label: string; tone: ContextTone } {
  if (summary.sync_status === "synced" || customerCode !== "-") return { label: "客户主档已建立并同步", tone: "ok" };
  if (summary.sync_status === "not_synced" || ["rejected", "cancelled"].includes(approval.status)) return { label: "审批未通过，未创建客户", tone: "bad" };
  return { label: "待审批，通过后自动建档", tone: "warn" };
}

