function CrmSkeletonSection({ section, permissions, navigate }: { section: typeof crmSections[number]; permissions: PermissionCode[]; navigate: (page: Page, path?: string) => void }) {
  const blueprint = crmSectionBlueprint(section.key);
  const Icon = section.icon;
  const canOpenProjects = canAccessCrmPath("/crm/projects", permissions);
  const canOpenIssues = canAccessCrmPath("/crm/issues", permissions);
  return (
    <>
      <Header
        eyebrow="CRM MODULE"
        title={blueprint.title}
        description={blueprint.description}
        actions={
          <div className="flex flex-wrap gap-2">
            {canOpenProjects ? <Button secondary onClick={() => navigate("crm", "/crm/projects")}>项目列表</Button> : null}
            {canOpenIssues ? <Button secondary onClick={() => navigate("crm", "/crm/issues")}>待支持事项</Button> : null}
          </div>
        }
      />
      <DataTableShell
        title={section.label}
        description={section.desc}
        actions={<Button secondary onClick={() => navigate("crm")}>返回 CRM 首页</Button>}
      >
        <Table headers={blueprint.columns}>
          <tr>
            <td colSpan={blueprint.columns.length}>
              <div className="flex flex-col gap-3 p-4 text-sm text-slate-500 lg:flex-row lg:items-center lg:justify-between">
                <div className="flex items-start gap-3">
                  <span className="grid h-10 w-10 shrink-0 place-items-center rounded-lg bg-primary-soft text-primary">
                    <Icon className="h-4 w-4" />
                  </span>
                  <span>
                    <strong className="block text-slate-900">{section.label}工作区</strong>
                    <span className="mt-1 block leading-6">{section.desc}</span>
                  </span>
                </div>
              </div>
            </td>
          </tr>
        </Table>
      </DataTableShell>
    </>
  );
}

function crmTaskScopeFilters(scope: string) {
  if (scope === "open") return { is_closed: false };
  if (scope === "support") return { need_support: true };
  if (scope === "blocked") return { is_blocked: true };
  if (scope === "overdue") return { overdue: true };
  if (scope === "closed") return { is_closed: true };
  return {};
}

function crmFollowupEntryScopeFilters(scope: string, currentUser: UserPublic): Record<string, string | number | boolean | undefined> {
  if (scope === "mine_open") return { executor_user_id: currentUser.id, is_closed: false };
  if (scope === "mine_all") return { executor_user_id: currentUser.id };
  return crmTaskScopeFilters(scope);
}

function dateTimeStartParam(value: string) {
  return value ? `${value}T00:00:00+08:00` : undefined;
}

function dateTimeEndParam(value: string) {
  return value ? `${value}T23:59:59+08:00` : undefined;
}

type CrmFollowupSubmissionFilter = "" | "unsubmitted" | "submitted" | "needs_action";

function crmTaskFollowupSubmissionState(task: CrmTaskRow): Exclude<CrmFollowupSubmissionFilter, ""> {
  if (task.followup_submission_state === "submitted" || task.followup_submission_state === "needs_action") {
    return task.followup_submission_state;
  }
  return task.last_followup_at || task.latest_followup_id ? "submitted" : "unsubmitted";
}

function crmTaskSubmissionPresentation(task: CrmTaskRow): { label: string; detail: string; tone: ContextTone } {
  const state = crmTaskFollowupSubmissionState(task);
  const approvalStatus = task.latest_followup_approval_status;
  if (state === "needs_action") {
    const detail = approvalStatus === "need_supplement"
      ? "待补充"
      : approvalStatus === "rejected"
        ? "已驳回"
        : approvalStatus === "cancelled"
          ? "已取消"
          : crmApprovalStatusLabels[approvalStatus ?? ""] ?? "状态异常";
    return { label: `需处理 · ${detail}`, detail, tone: "bad" };
  }
  if (state === "submitted") {
    const completed = !approvalStatus || ["approved", "completed"].includes(approvalStatus);
    return {
      label: completed ? "已提交 · 已完成" : "已提交 · 待审批",
      detail: approvalStatus ? crmApprovalStatusLabels[approvalStatus] ?? approvalStatus : "正式跟进已生成",
      tone: completed ? "ok" : "neutral"
    };
  }
  return { label: "未提交", detail: "尚未填写跟进", tone: "warn" };
}

function CrmTaskSubmissionCell({ task }: { task: CrmTaskRow }) {
  const presentation = crmTaskSubmissionPresentation(task);
  const submittedAt = task.latest_followup_submitted_at ?? task.last_followup_at;
  return (
    <div className="grid min-w-[132px] gap-1.5">
      <Badge tone={presentation.tone}>{presentation.label}</Badge>
      <span className="text-xs font-bold text-slate-400">{submittedAt ? formatDateTime(submittedAt) : "-"}</span>
    </div>
  );
}

function CrmFollowupEntryPage({
  permissions,
  currentUser,
  navigate
}: {
  permissions: PermissionCode[];
  currentUser: UserPublic;
  navigate: (page: Page, path?: string) => void;
}) {
  const canViewTasks = hasPermission(permissions, "crm_task.view");
  const canSubmitFollowup = hasPermission(permissions, "crm_followup.submit");
  const canOpenProjects = canAccessCrmPath("/crm/projects", permissions);
  const canOpenFollowups = canAccessCrmPath("/crm/followups", permissions);
  const canOpenMyWork = canAccessCrmPath("/crm/my-work", permissions);
  const [pageData, setPageData] = useState<{ items: CrmTaskRow[]; total: number; limit: number; offset: number } | null>(null);
  const [query, setQuery] = useState(() => initialQueryParam("q"));
  const [queueScope, setQueueScope] = useState(() => initialQueryParam("scope") || "mine_open");
  const [dueFrom, setDueFrom] = useState(() => initialQueryParam("due_from"));
  const [dueTo, setDueTo] = useState(() => initialQueryParam("due_to"));
  const [currentPage, setCurrentPage] = useState(1);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");
  const [selectedTask, setSelectedTask] = useState<CrmTaskRow | null>(null);
  const [followupProject, setFollowupProject] = useState<CrmProjectRow | null>(null);
  const [followupTask, setFollowupTask] = useState<CrmTaskRow | null>(null);
  const [loadingTaskId, setLoadingTaskId] = useState<number | null>(null);

  const totalRows = pageData?.total ?? 0;
  const totalPages = Math.max(1, Math.ceil(totalRows / CRM_PROJECT_PAGE_SIZE));
  const safeCurrentPage = Math.min(currentPage, totalPages);
  const offset = (safeCurrentPage - 1) * CRM_PROJECT_PAGE_SIZE;
  const rangeStart = totalRows === 0 ? 0 : offset + 1;
  const rangeEnd = Math.min(offset + CRM_PROJECT_PAGE_SIZE, totalRows);
  const rows = pageData?.items ?? [];
  const pageStats = {
    writable: rows.filter((row) => !row.is_closed).length,
    overdue: rows.filter((row) => Boolean(row.feedback_due_at) && !row.is_closed && new Date(String(row.feedback_due_at)).getTime() < Date.now()).length,
    support: rows.filter((row) => row.need_support || row.need_manager_support || row.need_boss_decision).length,
    noFeedback: rows.filter((row) => !row.last_followup_at && !row.is_closed).length
  };

  const loadRows = async () => {
    if (!canViewTasks) {
      setPageData(null);
      return;
    }
    setLoading(true);
    setMessage("");
    try {
      const nextPage = await crmTasksPage({
        q: query,
        due_from: dateTimeStartParam(dueFrom),
        due_to: dateTimeEndParam(dueTo),
        limit: CRM_PROJECT_PAGE_SIZE,
        offset,
        ...crmFollowupEntryScopeFilters(queueScope, currentUser)
      });
      setPageData(nextPage);
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "跟进填写队列加载失败");
      setPageData(null);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void loadRows();
  }, [canViewTasks, query, queueScope, dueFrom, dueTo, offset, currentUser.id]);

  useEffect(() => {
    if (currentPage !== safeCurrentPage) setCurrentPage(safeCurrentPage);
  }, [currentPage, safeCurrentPage]);

  const resetFilters = () => {
    setCurrentPage(1);
    setQuery("");
    setQueueScope("mine_open");
    setDueFrom("");
    setDueTo("");
  };

  const openFollowupSubmit = async (task: CrmTaskRow) => {
    if (!canSubmitFollowup) return;
    setLoadingTaskId(task.id);
    setMessage("");
    try {
      const context = await crmProjectContext(task.project_id);
      setFollowupProject(context.project_detail.project);
      setFollowupTask(task);
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "项目上下文加载失败，暂时无法提交跟进。");
    } finally {
      setLoadingTaskId(null);
    }
  };

  if (!canViewTasks || !canSubmitFollowup) {
    return <Card className="p-6 text-sm font-bold text-slate-500">当前账号缺少客户任务查看或跟进提交权限。</Card>;
  }

  return (
    <>
      <Header
        eyebrow="CRM FOLLOWUP ENTRY"
        title="任务明细"
        actions={
          <>
            <Button secondary onClick={() => void loadRows()} disabled={loading}><RefreshCcw className="mr-1.5 h-4 w-4" />刷新</Button>
            {canOpenFollowups ? <Button secondary onClick={() => navigate("crm", "/crm/followups")}>跟进记录</Button> : null}
            <Button secondary onClick={() => navigate("crm", "/crm/tasks")}>任务明细</Button>
          </>
        }
      />
      {message ? <Card className="mb-4 border-amber-200 bg-amber-50 px-4 py-3 text-sm font-bold text-amber-700">{message}</Card> : null}

      <div className="mb-4 grid gap-3 md:grid-cols-2 xl:grid-cols-4">
        <CrmProjectMetricCard label="可填写任务" value={pageStats.writable} detail={`当前范围 ${totalRows} 条`} tone={pageStats.writable > 0 ? "neutral" : "ok"} icon={Phone} />
        <CrmProjectMetricCard label="超期未反馈" value={pageStats.overdue} detail="当前页任务" tone={pageStats.overdue > 0 ? "bad" : "ok"} icon={Siren} />
        <CrmProjectMetricCard label="待支持" value={pageStats.support} detail="需协同或决策" tone={pageStats.support > 0 ? "neutral" : "ok"} icon={FileWarning} />
        <CrmProjectMetricCard label="无近期反馈" value={pageStats.noFeedback} detail="优先补充事实" tone={pageStats.noFeedback > 0 ? "neutral" : "ok"} icon={History} />
      </div>

      <section className="grid gap-4 xl:grid-cols-[minmax(0,1fr)_360px]">
        <DataTableShell
          title="待填写跟进队列"
          description="点击未闭环任务直接填写跟进；已闭环任务点击后查看详情。"
          meta={`${rangeStart}-${rangeEnd} / ${totalRows} 条记录`}
          toolbar={
            <DataToolbar onReset={resetFilters}>
              <ToolbarSearch value={query} onChange={(value) => { setCurrentPage(1); setQuery(value); }} placeholder="搜索客户、任务、执行人或目标" />
              <ToolbarSelect
                value={queueScope}
                onChange={(value) => { setCurrentPage(1); setQueueScope(value); }}
                label="队列"
                options={[
                  { value: "mine_open", label: "我的未闭环" },
                  { value: "mine_all", label: "我的全部" },
                  { value: "open", label: "全部未闭环" },
                  { value: "overdue", label: "超期" },
                  { value: "support", label: "待支持" },
                  { value: "blocked", label: "阻塞" },
                  { value: "closed", label: "已闭环" },
                  { value: "", label: "全部任务" }
                ]}
              />
              <CrmDateFilterInput label="到期从" value={dueFrom} onChange={(value) => { setCurrentPage(1); setDueFrom(value); }} />
              <CrmDateFilterInput label="到期至" value={dueTo} onChange={(value) => { setCurrentPage(1); setDueTo(value); }} />
            </DataToolbar>
          }
        >
          <Table headers={["客户", "任务目标", "项目", "状态", "风险", "截止", "最近反馈"]}>
            {rows.length > 0 ? rows.map((task) => (
              <tr
                key={task.id}
                onClick={() => {
                  if (loadingTaskId === task.id) return;
                  if (task.is_closed) {
                    setSelectedTask(task);
                    return;
                  }
                  void openFollowupSubmit(task);
                }}
                className="cursor-pointer transition hover:bg-primary-soft"
              >
                <td>
                  <strong className="block max-w-[220px] truncate text-slate-950">{task.customer_name_snapshot}</strong>
                  <span className="mt-1 block text-xs font-bold text-slate-400">{task.customer_code}</span>
                </td>
                <td>
                  <strong className="block max-w-[220px] truncate text-slate-950">{task.task_code}</strong>
                  <span className="mt-1 block max-w-[260px] truncate text-xs font-bold text-slate-500">{displayValue(task.round_target || task.business_issue_point)}</span>
                </td>
                <td>
                  {canOpenProjects ? (
                    <button
                      type="button"
                      onClick={(event) => { event.stopPropagation(); navigate("crm", `/crm/projects/${task.project_id}`); }}
                      className="inline-flex items-center rounded-lg border border-slate-200 bg-white px-3 py-2 text-xs font-black text-primary transition hover:bg-primary-soft"
                    >
                      项目 #{task.project_id}
                    </button>
                  ) : (
                    <span className="text-xs font-bold text-slate-400">项目 #{task.project_id}</span>
                  )}
                </td>
                <td><Badge tone={crmStatusTone(task.status)}>{crmTaskStatusLabels[task.status] ?? task.status}</Badge></td>
                <td><Badge tone={task.is_blocked ? "bad" : task.need_support || task.need_manager_support || task.need_boss_decision ? "warn" : task.is_closed ? "ok" : "neutral"}>{task.is_blocked ? "阻塞" : task.need_support ? "需支持" : task.need_manager_support ? "主管协同" : task.need_boss_decision ? "管理决策" : task.is_closed ? "已闭环" : "正常"}</Badge></td>
                <td>{formatDateTime(task.feedback_due_at)}</td>
                <td>{loadingTaskId === task.id ? "读取中" : formatDateTime(task.last_followup_at)}</td>
              </tr>
            )) : (
              <CrmEmptyTableRow
                colSpan={7}
                icon={Phone}
                message={loading ? "正在加载跟进填写队列。" : "当前队列暂无需要填写的客户任务"}
                actions={loading ? [] : [
                  { label: "查看全部任务", onClick: () => setQueueScope(""), icon: ClipboardList },
                  ...(canOpenFollowups ? [{ label: "跟进记录", onClick: () => navigate("crm", "/crm/followups"), icon: History, secondary: true }] : [])
                ]}
              />
            )}
          </Table>
          <MasterPagination
            currentPage={safeCurrentPage}
            totalPages={totalPages}
            totalItems={totalRows}
            pageSize={CRM_PROJECT_PAGE_SIZE}
            rangeStart={rangeStart}
            rangeEnd={rangeEnd}
            onPageChange={setCurrentPage}
          />
        </DataTableShell>

        <Card className="p-4">
          <div className="mb-3 flex items-center gap-2">
            <span className="grid h-9 w-9 place-items-center rounded-lg bg-primary-soft text-primary"><Phone className="h-4 w-4" /></span>
            <div>
              <h3 className="m-0 text-base font-black text-slate-950">填写动作</h3>
              <p className="m-0 text-xs font-bold text-slate-500">点击未闭环任务行即可填写反馈。</p>
            </div>
          </div>
          <div className="grid gap-2 text-sm">
            <CustomerSideRow label="当前账号" value={currentUser.real_name || currentUser.username} />
            <CustomerSideRow label="默认队列" value="我的未闭环" />
            <CustomerSideRow label="审核流向" value="细节审批人" />
          </div>
          <div className="mt-4 grid gap-2">
            {canOpenMyWork ? <Button secondary onClick={() => navigate("crm", "/crm/my-work")}>我的工作</Button> : null}
            {canOpenFollowups ? <Button secondary onClick={() => navigate("crm", "/crm/followups")}>历史跟进</Button> : null}
            <Button onClick={() => void loadRows()} disabled={loading}>刷新队列</Button>
          </div>
        </Card>
      </section>

      <AnimatePresence>
        {selectedTask ? (
          <CrmTaskDetailDrawer
            key={`followup-entry-task-detail-${selectedTask.id}`}
            task={selectedTask}
            permissions={permissions}
            navigate={navigate}
            onClose={() => setSelectedTask(null)}
            onChanged={async (updatedTask) => {
              setSelectedTask(updatedTask);
              await loadRows();
            }}
          />
        ) : null}
        {followupProject && followupTask ? (
          <CrmFollowupSubmitDrawer
            key={`followup-entry-submit-${followupTask.id}`}
            project={followupProject}
            task={followupTask}
            permissions={permissions}
            onClose={() => { setFollowupProject(null); setFollowupTask(null); }}
            onSubmitted={async (approval) => {
              setFollowupProject(null);
              setFollowupTask(null);
              setMessage(`已提交跟进记录审批单 ${approval.approval_no}，审核通过后会沉淀到跟进记录。`);
              await loadRows();
            }}
          />
        ) : null}
      </AnimatePresence>
    </>
  );
}

function CrmTasksPage({ permissions, navigate }: { permissions: PermissionCode[]; navigate: (page: Page, path?: string) => void }) {
  const canView = hasPermission(permissions, "crm_task.view");
  const canSubmitFollowup = hasPermission(permissions, "crm_followup.submit");
  const canOpenProjects = canAccessCrmPath("/crm/projects", permissions);
  const canOpenIssues = canAccessCrmPath("/crm/issues", permissions);
  const canOpenFollowups = canAccessCrmPath("/crm/followups", permissions);
  const [pageData, setPageData] = useState<CrmTaskPage | null>(null);
  const [query, setQuery] = useState(() => initialQueryParam("q"));
  const [projectId, setProjectId] = useState(() => initialQueryParam("project_id"));
  const [statusValue, setStatusValue] = useState(() => initialQueryParam("status_value"));
  const [scopeFilter, setScopeFilter] = useState(() => initialQueryParam("scope"));
  const [followupSubmissionState, setFollowupSubmissionState] = useState<CrmFollowupSubmissionFilter>(() => {
    const initial = initialQueryParam("followup_submission_state");
    return ["unsubmitted", "submitted", "needs_action"].includes(initial) ? initial as CrmFollowupSubmissionFilter : "";
  });
  const [customerCodeFilter, setCustomerCodeFilter] = useState(() => initialQueryParam("customer_code"));
  const [executorUserId, setExecutorUserId] = useState(() => initialQueryParam("executor_user_id"));
  const [dueFrom, setDueFrom] = useState(() => initialQueryParam("due_from"));
  const [dueTo, setDueTo] = useState(() => initialQueryParam("due_to"));
  const [currentPage, setCurrentPage] = useState(1);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");
  const [requestedTaskId] = useState<number | null>(() => initialPositiveQueryId("task_id"));
  const [selectedTask, setSelectedTask] = useState<CrmTaskRow | null>(null);
  const [directTaskDetail, setDirectTaskDetail] = useState<CrmTaskDetail | null>(null);
  const [directTaskLoading, setDirectTaskLoading] = useState(Boolean(requestedTaskId));
  const [directTaskError, setDirectTaskError] = useState<Error | null>(null);
  const [directTaskRetryKey, setDirectTaskRetryKey] = useState(0);
  const [followupProject, setFollowupProject] = useState<CrmProjectRow | null>(null);
  const [followupTask, setFollowupTask] = useState<CrmTaskRow | null>(null);

  const totalRows = pageData?.total ?? 0;
  const totalPages = Math.max(1, Math.ceil(totalRows / CRM_PROJECT_PAGE_SIZE));
  const safeCurrentPage = Math.min(currentPage, totalPages);
  const offset = (safeCurrentPage - 1) * CRM_PROJECT_PAGE_SIZE;
  const rangeStart = totalRows === 0 ? 0 : offset + 1;
  const rangeEnd = Math.min(offset + CRM_PROJECT_PAGE_SIZE, totalRows);
  const rows = pageData?.items ?? [];
  const pageStats = {
    open: rows.filter((row) => !row.is_closed).length,
    support: rows.filter((row) => row.need_support || row.need_manager_support || row.need_boss_decision).length,
    blocked: rows.filter((row) => row.is_blocked).length,
    closed: rows.filter((row) => row.is_closed).length
  };
  const submissionSummary = pageData?.submission_summary ?? {
    total: totalRows,
    submitted: rows.filter((row) => crmTaskFollowupSubmissionState(row) === "submitted").length,
    unsubmitted: rows.filter((row) => crmTaskFollowupSubmissionState(row) === "unsubmitted").length,
    needs_action: rows.filter((row) => crmTaskFollowupSubmissionState(row) === "needs_action").length
  };
  const submissionOptions: Array<{ value: CrmFollowupSubmissionFilter; label: string; count: number }> = [
    { value: "", label: "全部", count: submissionSummary.total },
    { value: "unsubmitted", label: "未提交", count: submissionSummary.unsubmitted },
    { value: "submitted", label: "已提交", count: submissionSummary.submitted },
    { value: "needs_action", label: "需处理", count: submissionSummary.needs_action }
  ];

  const loadRows = async () => {
    if (!canView) {
      setPageData(null);
      return;
    }
    setLoading(true);
    setMessage("");
    try {
      const nextPage = await crmTasksPage({
        q: query,
        project_id: numericFilterValue(projectId),
        customer_code: customerCodeFilter,
        status_value: statusValue,
        executor_user_id: numericFilterValue(executorUserId),
        due_from: dateTimeStartParam(dueFrom),
        due_to: dateTimeEndParam(dueTo),
        followup_submission_state: followupSubmissionState || undefined,
        limit: CRM_PROJECT_PAGE_SIZE,
        offset,
        ...crmTaskScopeFilters(scopeFilter)
      });
      setPageData(nextPage);
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "任务明细加载失败");
      setPageData(null);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void loadRows();
  }, [canView, query, projectId, customerCodeFilter, statusValue, scopeFilter, followupSubmissionState, executorUserId, dueFrom, dueTo, offset]);

  useEffect(() => {
    if (currentPage !== safeCurrentPage) setCurrentPage(safeCurrentPage);
  }, [currentPage, safeCurrentPage]);

  useEffect(() => {
    let cancelled = false;
    if (!canView || !requestedTaskId) {
      setDirectTaskLoading(false);
      return;
    }
    setDirectTaskLoading(true);
    setDirectTaskError(null);
    void crmTaskDetail(requestedTaskId)
      .then((detail) => {
        if (!cancelled) {
          setDirectTaskDetail(detail);
          setSelectedTask(detail.task);
        }
      })
      .catch((error) => {
        if (!cancelled) {
          setDirectTaskDetail(null);
          setSelectedTask(null);
          setDirectTaskError(normalizeUiError(error, "指定任务加载失败"));
        }
      })
      .finally(() => {
        if (!cancelled) setDirectTaskLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [canView, requestedTaskId, directTaskRetryKey]);

  const openTaskDetail = (task: CrmTaskRow) => {
    replaceCurrentQueryParams({ task_id: task.id });
    setDirectTaskError(null);
    setDirectTaskDetail(null);
    setSelectedTask(task);
  };
  const closeTaskDetail = () => {
    replaceCurrentQueryParams({ task_id: null });
    setDirectTaskError(null);
    setDirectTaskDetail(null);
    setSelectedTask(null);
  };

  const resetFilters = () => {
    setCurrentPage(1);
    setQuery("");
    setProjectId("");
    setCustomerCodeFilter("");
    setStatusValue("");
    setScopeFilter("");
    setFollowupSubmissionState("");
    setExecutorUserId("");
    setDueFrom("");
    setDueTo("");
  };
  const clearCustomerFilter = () => {
    setCurrentPage(1);
    setCustomerCodeFilter("");
  };
  function applyTaskMetricFilter(nextScope: "" | "open" | "support" | "closed") {
    setCurrentPage(1);
    setScopeFilter((currentScope) => currentScope === nextScope ? "" : nextScope);
  }
  function applyFollowupSubmissionFilter(nextState: CrmFollowupSubmissionFilter) {
    setCurrentPage(1);
    setFollowupSubmissionState((currentState) => currentState === nextState ? "" : nextState);
  }
  const openFollowupSubmit = async (task: CrmTaskRow) => {
    if (!canSubmitFollowup || task.is_closed) return;
    setMessage("");
    try {
      const context = await crmProjectContext(task.project_id);
      closeTaskDetail();
      setFollowupProject(context.project_detail.project);
      setFollowupTask(task);
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "项目上下文加载失败，暂时无法填写跟进。");
    }
  };
  const hasActiveTaskFilters = Boolean(query.trim() || projectId || customerCodeFilter || statusValue || scopeFilter || followupSubmissionState || executorUserId || dueFrom || dueTo);

  if (!canView) {
    return <Card className="p-6 text-sm font-bold text-slate-500">当前账号没有任务明细查看权限。</Card>;
  }

  return (
    <>
      <Header
        eyebrow="CRM TASKS"
        title="任务明细"
        description="独立查看客户在项目中的任务明细，按负责人、状态、到期和风险筛选，点击行查看项目与审批细节。"
        actions={
          <>
            {canOpenFollowups ? <Button secondary onClick={() => navigate("crm", "/crm/followups")}>跟进记录</Button> : null}
            {canOpenIssues ? <Button secondary onClick={() => navigate("crm", "/crm/issues")}>待支持事项</Button> : null}
            {canOpenProjects ? <Button onClick={() => navigate("crm", "/crm/projects")}>项目列表</Button> : null}
          </>
        }
      />
      {message ? <Card className="mb-4 border-amber-200 bg-amber-50 px-4 py-3 text-sm font-bold text-amber-700">{message}</Card> : null}
      {directTaskLoading ? <Card className="mb-4 border-primary/20 bg-primary-soft px-4 py-3 text-sm font-bold text-primary">正在打开指定任务 #{requestedTaskId}…</Card> : null}
      {directTaskError ? <div className="mb-4"><ApiErrorNotice error={directTaskError} navigate={navigate} onRetry={() => setDirectTaskRetryKey((value) => value + 1)} onClose={closeTaskDetail} /></div> : null}
      {customerCodeFilter ? (
        <Card className="mb-4 flex flex-wrap items-center justify-between gap-3 border-primary/20 bg-primary-soft px-4 py-3">
          <span className="text-sm font-black text-primary">当前只看客户：{customerCodeFilter}</span>
          <Button secondary onClick={clearCustomerFilter}>清除客户筛选</Button>
        </Card>
      ) : null}
      <div className="mb-4 grid gap-3 md:grid-cols-2 xl:grid-cols-4">
        <CrmProjectMetricCard label="当前范围" value={totalRows} detail={`当前页 ${rows.length} 条`} icon={ClipboardList} onClick={() => applyTaskMetricFilter("")} active={scopeFilter === ""} />
        <CrmProjectMetricCard label="未闭环" value={pageStats.open} detail="当前页待推进明细" tone={pageStats.open > 0 ? "neutral" : "ok"} icon={Clock3} onClick={() => applyTaskMetricFilter("open")} active={scopeFilter === "open"} />
        <CrmProjectMetricCard label="待支持" value={pageStats.support} detail={`阻塞 ${pageStats.blocked}`} tone={pageStats.support > 0 ? "bad" : "ok"} icon={Siren} onClick={() => applyTaskMetricFilter("support")} active={scopeFilter === "support"} />
        <CrmProjectMetricCard label="已闭环" value={pageStats.closed} detail="当前页 closed 明细" tone="ok" icon={ShieldCheck} onClick={() => applyTaskMetricFilter("closed")} active={scopeFilter === "closed"} />
      </div>

      <section className="mb-4 flex flex-col gap-3 border-y border-slate-200 bg-white px-4 py-3 sm:flex-row sm:items-center sm:justify-between">
        <div className="min-w-0">
          <h2 className="m-0 text-sm font-black text-slate-950">跟进提交</h2>
          <p className="m-0 mt-1 text-xs font-bold text-slate-500">按当前任务筛选范围统计，不受分页影响。</p>
        </div>
        <div className="grid w-full grid-cols-2 gap-1 rounded-lg bg-slate-100 p-1 sm:w-auto sm:min-w-[460px] sm:grid-cols-4" aria-label="跟进提交状态">
          {submissionOptions.map((option) => (
            <button
              key={option.value || "all"}
              type="button"
              onClick={() => applyFollowupSubmissionFilter(option.value)}
              aria-pressed={followupSubmissionState === option.value}
              className={`grid min-h-11 min-w-0 place-items-center rounded-md px-3 py-1.5 text-xs font-black transition ${followupSubmissionState === option.value ? "bg-white text-primary shadow-sm" : "text-slate-500 hover:bg-white/70 hover:text-slate-800"}`}
            >
              <span className="truncate">{option.label}</span>
              <strong className="text-sm text-slate-950">{option.count}</strong>
            </button>
          ))}
        </div>
      </section>

      <DataTableShell
        title="任务明细列表"
        description={loading ? "正在加载任务明细。" : "点击任务明细行查看客户、项目、审批、资料更新和跟进上下文。"}
        meta={`${rangeStart}-${rangeEnd} / ${totalRows} 条记录`}
        toolbar={
          <DataToolbar onReset={resetFilters}>
            <ToolbarSearch value={query} onChange={(value) => { setCurrentPage(1); setQuery(value); }} placeholder="搜索任务明细、客户、执行人或项目目的" />
            <CrmFilterInput label="项目ID" value={projectId} onChange={(value) => { setCurrentPage(1); setProjectId(value); }} />
            <ToolbarSelect
              value={statusValue}
              onChange={(value) => { setCurrentPage(1); setStatusValue(value); }}
              label="状态"
              options={[{ value: "", label: "全部状态" }, ...Object.entries(crmTaskStatusLabels).map(([value, label]) => ({ value, label }))]}
            />
            <ToolbarSelect
              value={scopeFilter}
              onChange={(value) => { setCurrentPage(1); setScopeFilter(value); }}
              label="范围"
              options={[
                { value: "", label: "全部任务明细" },
                { value: "open", label: "未闭环" },
                { value: "support", label: "待支持" },
                { value: "blocked", label: "阻塞" },
                { value: "overdue", label: "超期" },
                { value: "closed", label: "已闭环" }
              ]}
            />
            <ToolbarSelect
              value={followupSubmissionState}
              onChange={(value) => { setCurrentPage(1); setFollowupSubmissionState(value as CrmFollowupSubmissionFilter); }}
              label="提交状态"
              options={[
                { value: "", label: "全部提交状态" },
                { value: "unsubmitted", label: "未提交" },
                { value: "submitted", label: "已提交" },
                { value: "needs_action", label: "需处理" }
              ]}
            />
            <CrmFilterInput label="执行人ID" value={executorUserId} onChange={(value) => { setCurrentPage(1); setExecutorUserId(value); }} />
            <CrmDateFilterInput label="到期从" value={dueFrom} onChange={(value) => { setCurrentPage(1); setDueFrom(value); }} />
            <CrmDateFilterInput label="到期至" value={dueTo} onChange={(value) => { setCurrentPage(1); setDueTo(value); }} />
          </DataToolbar>
        }
      >
        <Table headers={["客户", "任务明细", "项目", "执行人", "状态", "跟进提交", "资料更新", "风险", "反馈截止", "最近反馈"]}>
          {rows.length > 0 ? rows.map((task) => (
            <tr
              key={task.id}
              onClick={() => openTaskDetail(task)}
              className="cursor-pointer transition hover:bg-primary-soft"
            >
              <td>
                <strong className="block max-w-[220px] truncate text-slate-950">{task.customer_name_snapshot}</strong>
                <span className="mt-1 block text-xs font-bold text-slate-400">{task.customer_code}</span>
              </td>
              <td>
                <strong className="block max-w-[220px] truncate text-slate-950">{task.task_code}</strong>
                <span className="mt-1 line-clamp-2 max-w-[280px] whitespace-normal break-words text-xs font-bold leading-5 text-slate-500">
                  本次项目的目的：{crmProjectPurposeText(task.project_purpose)}
                </span>
              </td>
              <td>
                {canOpenProjects ? (
                  <button
                    type="button"
                    onClick={(event) => { event.stopPropagation(); navigate("crm", `/crm/projects/${task.project_id}`); }}
                    className="inline-flex items-center rounded-lg border border-slate-200 bg-white px-3 py-2 text-xs font-black text-primary transition hover:bg-primary-soft"
                  >
                    项目 #{task.project_id}
                  </button>
                ) : (
                  <span className="text-xs font-bold text-slate-400">项目 #{task.project_id}</span>
                )}
              </td>
              <td>{displayValue(task.executor_name_snapshot ?? task.executor_user_id)}</td>
              <td><Badge tone={crmStatusTone(task.status)}>{crmTaskStatusLabels[task.status] ?? task.status}</Badge></td>
              <td><CrmTaskSubmissionCell task={task} /></td>
              <td><CrmTaskDataUpdateCell task={task} /></td>
              <td><Badge tone={task.is_blocked ? "bad" : task.need_support || task.need_manager_support || task.need_boss_decision ? "warn" : task.is_closed ? "ok" : "neutral"}>{task.is_blocked ? "阻塞" : task.need_support ? "需支持" : task.need_manager_support ? "主管协同" : task.need_boss_decision ? "管理决策" : task.is_closed ? "已闭环" : "正常"}</Badge></td>
              <td>{formatDateTime(task.feedback_due_at)}</td>
              <td>{formatDateTime(task.last_followup_at)}</td>
            </tr>
          )) : (
            <CrmEmptyTableRow
              colSpan={10}
              icon={ClipboardList}
              message={loading ? "正在加载任务明细。" : hasActiveTaskFilters ? "没有符合筛选的任务明细" : "暂无任务明细"}
              description={loading ? undefined : hasActiveTaskFilters ? "当前筛选条件没有命中任务明细，可以清空筛选后重新查看。" : "任务明细通常由项目申请审批通过后生成，也可以先进入项目列表确认项目是否已创建。"}
              actions={loading ? [] : [
                ...(hasActiveTaskFilters ? [{ label: "清空筛选", onClick: resetFilters, icon: X, secondary: true }] : []),
                ...(canSubmitFollowup ? [{ label: "查看未闭环任务", onClick: () => applyTaskMetricFilter("open"), icon: Phone, secondary: true }] : []),
                ...(canOpenProjects ? [{ label: "项目列表", onClick: () => navigate("crm", "/crm/projects"), icon: BriefcaseBusiness }] : []),
                ...(canOpenIssues ? [{ label: "待支持事项", onClick: () => navigate("crm", "/crm/issues"), icon: FileWarning, secondary: true }] : [])
              ]}
            />
          )}
        </Table>
        <MasterPagination
          currentPage={safeCurrentPage}
          totalPages={totalPages}
          totalItems={totalRows}
          pageSize={CRM_PROJECT_PAGE_SIZE}
          rangeStart={rangeStart}
          rangeEnd={rangeEnd}
          onPageChange={setCurrentPage}
        />
      </DataTableShell>

      <AnimatePresence>
        {selectedTask ? (
          <CrmTaskDetailDrawer
            key={`task-detail-${selectedTask.id}`}
            task={selectedTask}
            initialDetail={directTaskDetail?.task.id === selectedTask.id ? directTaskDetail : undefined}
            permissions={permissions}
            navigate={navigate}
            onStartFollowup={canSubmitFollowup && !selectedTask.is_closed ? (task) => void openFollowupSubmit(task) : undefined}
            onClose={closeTaskDetail}
            onChanged={async (updatedTask) => {
              setSelectedTask(updatedTask);
              await loadRows();
            }}
          />
        ) : null}
        {followupProject && followupTask ? (
          <CrmFollowupSubmitDrawer
            key={`task-followup-submit-${followupTask.id}`}
            project={followupProject}
            task={followupTask}
            permissions={permissions}
            onClose={() => { setFollowupProject(null); setFollowupTask(null); }}
            onSubmitted={async (approval) => {
              setFollowupProject(null);
              setFollowupTask(null);
              setMessage(`已提交跟进记录审批单 ${approval.approval_no}，审核通过后会沉淀到跟进记录。`);
              await loadRows();
            }}
          />
        ) : null}
      </AnimatePresence>
    </>
  );
}

function CrmFollowupsPage({ permissions, navigate }: { permissions: PermissionCode[]; navigate: (page: Page, path?: string) => void }) {
  const canView = hasPermission(permissions, "crm_followup.view");
  const canOpenTasks = canAccessCrmPath("/crm/tasks", permissions);
  const canOpenIssues = canAccessCrmPath("/crm/issues", permissions);
  const canOpenProjects = canAccessCrmPath("/crm/projects", permissions);
  const [pageData, setPageData] = useState<{ items: CrmFollowupRow[]; total: number; limit: number; offset: number } | null>(null);
  const [query, setQuery] = useState(() => initialQueryParam("q"));
  const [projectId, setProjectId] = useState(() => initialQueryParam("project_id"));
  const [customerCodeFilter, setCustomerCodeFilter] = useState(() => initialQueryParam("customer_code"));
  const [reviewStatus, setReviewStatus] = useState(() => initialQueryParam("review_status"));
  const [reviewScope, setReviewScope] = useState(() => initialQueryParam("review_scope"));
  const [executorUserId, setExecutorUserId] = useState(() => initialQueryParam("executor_user_id"));
  const [needSupport, setNeedSupport] = useState(() => initialQueryParam("need_support"));
  const [validFeedback, setValidFeedback] = useState(() => initialQueryParam("valid_feedback"));
  const [dateFrom, setDateFrom] = useState(() => initialQueryParam("date_from"));
  const [dateTo, setDateTo] = useState(() => initialQueryParam("date_to"));
  const [metricFilter, setMetricFilter] = useState<"" | "valid" | "support" | "pending">("");
  const [currentPage, setCurrentPage] = useState(1);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");
  const [selectedFollowupId, setSelectedFollowupId] = useState<number | null>(() => initialPositiveQueryId("followup_id"));
  const [selectedFollowup, setSelectedFollowup] = useState<CrmFollowupRow | null>(null);
  const [followupLoading, setFollowupLoading] = useState(false);
  const [followupError, setFollowupError] = useState("");

  const totalRows = pageData?.total ?? 0;
  const totalPages = Math.max(1, Math.ceil(totalRows / CRM_PROJECT_PAGE_SIZE));
  const safeCurrentPage = Math.min(currentPage, totalPages);
  const offset = (safeCurrentPage - 1) * CRM_PROJECT_PAGE_SIZE;
  const rangeStart = totalRows === 0 ? 0 : offset + 1;
  const rangeEnd = Math.min(offset + CRM_PROJECT_PAGE_SIZE, totalRows);
  const rows = pageData?.items ?? [];
  const pageStats = {
    valid: rows.filter((row) => row.valid_feedback).length,
    invalid: rows.filter((row) => !row.valid_feedback).length,
    support: rows.filter((row) => row.need_support || row.need_manager_support || row.need_boss_decision).length,
    pending: rows.filter((row) => ["pending", "need_supplement"].includes(row.review_status)).length
  };

  const loadRows = async () => {
    if (!canView) {
      setPageData(null);
      return;
    }
    setLoading(true);
    setMessage("");
    try {
      const nextPage = await crmFollowupsPage({
        q: query,
        project_id: numericFilterValue(projectId),
        customer_code: customerCodeFilter,
        review_status: reviewStatus,
        review_scope: reviewScope,
        executor_user_id: numericFilterValue(executorUserId),
        need_support: booleanFilterValue(needSupport),
        valid_feedback: booleanFilterValue(validFeedback),
        date_from: dateFrom || undefined,
        date_to: dateTo || undefined,
        limit: CRM_PROJECT_PAGE_SIZE,
        offset
      });
      setPageData(nextPage);
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "跟进记录加载失败");
      setPageData(null);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void loadRows();
  }, [canView, query, projectId, customerCodeFilter, reviewStatus, reviewScope, executorUserId, needSupport, validFeedback, dateFrom, dateTo, offset]);

  useEffect(() => {
    if (currentPage !== safeCurrentPage) setCurrentPage(safeCurrentPage);
  }, [currentPage, safeCurrentPage]);

  useEffect(() => {
    let cancelled = false;
    if (!canView || !selectedFollowupId) {
      setSelectedFollowup(null);
      setFollowupLoading(false);
      setFollowupError("");
      return;
    }
    setSelectedFollowup(null);
    setFollowupLoading(true);
    setFollowupError("");
    void crmFollowup(selectedFollowupId)
      .then((nextFollowup) => {
        if (!cancelled) setSelectedFollowup(nextFollowup);
      })
      .catch((loadError) => {
        if (!cancelled) {
          setFollowupError(loadError instanceof Error ? loadError.message : "跟进记录加载失败");
          setSelectedFollowup(null);
        }
      })
      .finally(() => {
        if (!cancelled) setFollowupLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [canView, selectedFollowupId]);

  const openFollowupDetail = (followupId: number) => {
    replaceCurrentQueryParams({ followup_id: followupId });
    setSelectedFollowupId(followupId);
  };
  const closeFollowupDetail = () => {
    replaceCurrentQueryParams({ followup_id: null });
    setSelectedFollowupId(null);
  };

  const resetFilters = () => {
    setCurrentPage(1);
    setQuery("");
    setProjectId("");
    setCustomerCodeFilter("");
    setReviewStatus("");
    setReviewScope("");
    setExecutorUserId("");
    setNeedSupport("");
    setValidFeedback("");
    setDateFrom("");
    setDateTo("");
    setMetricFilter("");
  };
  const clearCustomerFilter = () => {
    setCurrentPage(1);
    setCustomerCodeFilter("");
  };
  const applyFollowupMetricFilter = (scope: "" | "valid" | "support" | "pending") => {
    setCurrentPage(1);
    const nextScope = metricFilter === scope ? "" : scope;
    setMetricFilter(nextScope);
    setValidFeedback(nextScope === "valid" ? "true" : "");
    setNeedSupport(nextScope === "support" ? "true" : "");
    setReviewStatus("");
    setReviewScope(nextScope === "pending" ? "pending" : "");
  };
  const hasActiveFollowupFilters = Boolean(query.trim() || projectId || customerCodeFilter || reviewStatus || reviewScope || executorUserId || needSupport || validFeedback || dateFrom || dateTo);

  if (!canView) {
    return <Card className="p-6 text-sm font-bold text-slate-500">当前账号没有跟进记录查看权限。</Card>;
  }

  return (
    <>
      <Header
        eyebrow="CRM FOLLOWUPS"
        title="跟进记录"
        description="独立查看拜访、电话、微信和客户群等跟进记录，按审核、反馈质量、支持需求和日期筛选。"
        actions={
          <>
            {canOpenTasks ? <Button secondary onClick={() => navigate("crm", "/crm/tasks")}>任务明细</Button> : null}
            {canOpenIssues ? <Button secondary onClick={() => navigate("crm", "/crm/issues")}>待支持事项</Button> : null}
            {canOpenProjects ? <Button onClick={() => navigate("crm", "/crm/projects")}>项目列表</Button> : null}
          </>
        }
      />
      {message ? <Card className="mb-4 border-amber-200 bg-amber-50 px-4 py-3 text-sm font-bold text-amber-700">{message}</Card> : null}
      {customerCodeFilter ? (
        <Card className="mb-4 flex flex-wrap items-center justify-between gap-3 border-primary/20 bg-primary-soft px-4 py-3">
          <span className="text-sm font-black text-primary">当前只看客户：{customerCodeFilter}</span>
          <Button secondary onClick={clearCustomerFilter}>清除客户筛选</Button>
        </Card>
      ) : null}
      <div className="mb-4 grid gap-3 md:grid-cols-2 xl:grid-cols-4">
        <CrmProjectMetricCard label="当前范围" value={totalRows} detail={`当前页 ${rows.length} 条`} icon={History} active={!metricFilter} onClick={() => applyFollowupMetricFilter("")} />
        <CrmProjectMetricCard label="有效反馈" value={pageStats.valid} detail={`无效 ${pageStats.invalid}`} tone={pageStats.invalid > 0 ? "neutral" : "ok"} icon={UserCheck} active={metricFilter === "valid"} onClick={() => applyFollowupMetricFilter("valid")} />
        <CrmProjectMetricCard label="待支持" value={pageStats.support} detail="当前页支持需求" tone={pageStats.support > 0 ? "bad" : "ok"} icon={Siren} active={metricFilter === "support"} onClick={() => applyFollowupMetricFilter("support")} />
        <CrmProjectMetricCard label="待审核/补充" value={pageStats.pending} detail="当前页审核状态" tone={pageStats.pending > 0 ? "neutral" : "ok"} icon={ShieldCheck} active={metricFilter === "pending"} onClick={() => applyFollowupMetricFilter("pending")} />
      </div>

      <DataTableShell
        title="跟进记录列表"
        description={loading ? "正在加载跟进记录。" : "点击任意记录直接查看跟进详情；需要时可从详情进入所属项目。"}
        meta={`${rangeStart}-${rangeEnd} / ${totalRows} 条记录`}
        toolbar={
          <DataToolbar onReset={resetFilters}>
            <ToolbarSearch value={query} onChange={(value) => { setCurrentPage(1); setQuery(value); }} placeholder="搜索跟进编号、客户、反馈或需求" />
            <CrmFilterInput label="项目ID" value={projectId} onChange={(value) => { setCurrentPage(1); setProjectId(value); }} />
            <ToolbarSelect
              value={reviewStatus}
              onChange={(value) => { setCurrentPage(1); setMetricFilter(""); setReviewScope(""); setReviewStatus(value); }}
              label="审核"
              options={[{ value: "", label: "全部审核" }, ...Object.entries(crmApprovalStatusLabels).map(([value, label]) => ({ value, label }))]}
            />
            <ToolbarSelect
              value={needSupport}
              onChange={(value) => { setCurrentPage(1); setMetricFilter(""); setNeedSupport(value); }}
              label="支持"
              options={[{ value: "", label: "全部" }, { value: "true", label: "需支持" }, { value: "false", label: "无支持" }]}
            />
            <ToolbarSelect
              value={validFeedback}
              onChange={(value) => { setCurrentPage(1); setMetricFilter(""); setValidFeedback(value); }}
              label="反馈"
              options={[{ value: "", label: "全部反馈" }, { value: "true", label: "有效反馈" }, { value: "false", label: "无效反馈" }]}
            />
            <CrmFilterInput label="执行人ID" value={executorUserId} onChange={(value) => { setCurrentPage(1); setExecutorUserId(value); }} />
            <CrmDateFilterInput label="日期从" value={dateFrom} onChange={(value) => { setCurrentPage(1); setDateFrom(value); }} />
            <CrmDateFilterInput label="日期至" value={dateTo} onChange={(value) => { setCurrentPage(1); setDateTo(value); }} />
          </DataToolbar>
        }
      >
        <Table headers={["跟进", "客户", "项目", "方式", "反馈", "支持", "审核", "下一步", "时间"]}>
          {rows.length > 0 ? rows.map((followup) => (
            <tr
              key={followup.id}
              role="button"
              tabIndex={0}
              aria-label={`查看跟进记录 ${followup.followup_no}`}
              onClick={() => openFollowupDetail(followup.id)}
              onKeyDown={(event) => {
                if (event.key === "Enter" || event.key === " ") {
                  event.preventDefault();
                  openFollowupDetail(followup.id);
                }
              }}
              className="cursor-pointer transition hover:bg-primary-soft"
            >
              <td>
                <strong className="block max-w-[180px] truncate text-slate-950">{followup.followup_no}</strong>
                <span className="mt-1 block text-xs font-bold text-slate-400">{displayValue(followup.executor_name_snapshot ?? followup.executor_user_id)}</span>
              </td>
              <td><strong className="block max-w-[220px] truncate text-slate-950">{displayValue(followup.customer_name)}</strong><span className="mt-1 block text-xs font-bold text-slate-400">{displayValue(followup.customer_code)}</span></td>
              <td>{followup.project_id}</td>
              <td>{displayValue(followup.method)}</td>
              <td>
                <span className="line-clamp-2 max-w-[260px] whitespace-normal leading-5">{displayValue(followup.customer_feedback)}</span>
                <Badge tone={followup.valid_feedback ? "ok" : "warn"}>{followup.valid_feedback ? "有效" : "待确认"}</Badge>
              </td>
              <td><Badge tone={followup.need_boss_decision || followup.need_manager_support ? "bad" : followup.need_support ? "warn" : "neutral"}>{followup.need_boss_decision ? "管理决策" : followup.need_manager_support ? "主管协同" : followup.need_support ? "需支持" : "无"}</Badge></td>
              <td><Badge tone={crmStatusTone(followup.review_status)}>{crmApprovalStatusLabels[followup.review_status] ?? followup.review_status}</Badge></td>
              <td><span className="line-clamp-2 max-w-[220px] whitespace-normal leading-5">{displayValue(followup.next_action)}</span></td>
              <td>{formatDateTime(followup.followup_date ?? followup.created_at)}</td>
            </tr>
          )) : (
            <CrmEmptyTableRow
              colSpan={9}
              icon={History}
              message={loading ? "正在加载跟进记录。" : hasActiveFollowupFilters ? "没有符合筛选的跟进记录" : "暂无跟进记录"}
              description={loading ? undefined : hasActiveFollowupFilters ? "当前筛选没有命中跟进记录，可以清空筛选或缩短限制条件。" : "跟进记录从客户任务提交并审核后沉淀，建议先进入客户任务找到需要反馈的事项。"}
              actions={loading ? [] : [
                ...(hasActiveFollowupFilters ? [{ label: "清空筛选", onClick: resetFilters, icon: X, secondary: true }] : []),
                ...(canOpenTasks ? [{ label: "任务明细", onClick: () => navigate("crm", "/crm/tasks"), icon: ClipboardList }] : []),
                ...(canOpenProjects ? [{ label: "项目列表", onClick: () => navigate("crm", "/crm/projects"), icon: BriefcaseBusiness, secondary: true }] : [])
              ]}
            />
          )}
        </Table>
        <MasterPagination
          currentPage={safeCurrentPage}
          totalPages={totalPages}
          totalItems={totalRows}
          pageSize={CRM_PROJECT_PAGE_SIZE}
          rangeStart={rangeStart}
          rangeEnd={rangeEnd}
          onPageChange={setCurrentPage}
        />
      </DataTableShell>
      <AnimatePresence>
        {selectedFollowupId ? (
          <CrmFollowupDetailDrawer
            key={`list-followup-detail-${selectedFollowupId}`}
            followupId={selectedFollowupId}
            followup={selectedFollowup}
            projectName={selectedFollowup?.project_name ?? undefined}
            loading={followupLoading}
            error={followupError}
            navigate={navigate}
            canOpenProject={canOpenProjects}
            onClose={closeFollowupDetail}
          />
        ) : null}
      </AnimatePresence>
    </>
  );
}

function CrmProjectCustomerDetailWorkbench({
  project,
  permissions,
  navigate,
  reloadKey,
  onTaskClick
}: {
  project: CrmProjectRow;
  permissions: PermissionCode[];
  navigate: (page: Page, path?: string) => void;
  reloadKey: number;
  onTaskClick: (task: CrmTaskRow) => void;
}) {
  const canViewTasks = hasPermission(permissions, "crm_task.view");
  const [pageData, setPageData] = useState<CrmProjectCustomerDetailPage | null>(null);
  const [query, setQuery] = useState("");
  const [customerGroupName, setCustomerGroupName] = useState("");
  const [salespersonName, setSalespersonName] = useState("");
  const [region, setRegion] = useState("");
  const [customerType, setCustomerType] = useState("");
  const [customerStatus, setCustomerStatus] = useState("");
  const [taskStatus, setTaskStatus] = useState("");
  const [blockerReason, setBlockerReason] = useState("");
  const [overdueFilter, setOverdueFilter] = useState("");
  const [supportFilter, setSupportFilter] = useState("");
  const [blockedFilter, setBlockedFilter] = useState("");
  const [closedFilter, setClosedFilter] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");

  const totalRows = pageData?.total ?? 0;
  const totalPages = Math.max(1, Math.ceil(totalRows / CRM_PROJECT_PAGE_SIZE));
  const safeCurrentPage = Math.min(currentPage, totalPages);
  const offset = (safeCurrentPage - 1) * CRM_PROJECT_PAGE_SIZE;
  const rangeStart = totalRows === 0 ? 0 : offset + 1;
  const rangeEnd = Math.min(offset + CRM_PROJECT_PAGE_SIZE, totalRows);
  const rows = pageData?.items ?? [];
  const summary = pageData?.summary;
  const optionItems = (defaultLabel: string, values: string[] | undefined) => [
    { value: "", label: defaultLabel },
    ...(values ?? []).map((value) => ({ value, label: value }))
  ];

  const resetRiskFilters = () => {
    setOverdueFilter("");
    setSupportFilter("");
    setBlockedFilter("");
    setClosedFilter("");
  };

  const resetFilters = () => {
    setCurrentPage(1);
    setQuery("");
    setCustomerGroupName("");
    setSalespersonName("");
    setRegion("");
    setCustomerType("");
    setCustomerStatus("");
    setTaskStatus("");
    setBlockerReason("");
    resetRiskFilters();
  };

  const applyMetricFilter = (scope: "all" | "open" | "overdue" | "support" | "blocked" | "closed") => {
    setCurrentPage(1);
    if (scope === "all") {
      resetFilters();
      return;
    }
    resetRiskFilters();
    if (scope === "open") setClosedFilter("false");
    if (scope === "overdue") setOverdueFilter("true");
    if (scope === "support") setSupportFilter("true");
    if (scope === "blocked") setBlockedFilter("true");
    if (scope === "closed") setClosedFilter("true");
  };

  const loadRows = async () => {
    if (!canViewTasks) {
      setPageData(null);
      return;
    }
    setLoading(true);
    setMessage("");
    try {
      const nextPage = await crmProjectCustomerDetailsPage(project.id, {
        q: query,
        customer_group_name: customerGroupName,
        salesperson_name: salespersonName,
        region,
        customer_type: customerType,
        customer_status: customerStatus,
        status_value: taskStatus,
        latest_blocker_reason: blockerReason,
        overdue: booleanFilterValue(overdueFilter),
        need_support: booleanFilterValue(supportFilter),
        is_blocked: booleanFilterValue(blockedFilter),
        is_closed: booleanFilterValue(closedFilter),
        limit: CRM_PROJECT_PAGE_SIZE,
        offset
      });
      setPageData(nextPage);
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "项目客户明细加载失败");
      setPageData(null);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void loadRows();
  }, [
    canViewTasks,
    project.id,
    query,
    customerGroupName,
    salespersonName,
    region,
    customerType,
    customerStatus,
    taskStatus,
    blockerReason,
    overdueFilter,
    supportFilter,
    blockedFilter,
    closedFilter,
    offset,
    reloadKey
  ]);

  useEffect(() => {
    if (currentPage !== safeCurrentPage) setCurrentPage(safeCurrentPage);
  }, [currentPage, safeCurrentPage]);

  const toTaskRow = (row: CrmProjectCustomerDetailRow): CrmTaskRow => ({
    ...row,
    status: row.status || row.task_status
  });
  const hasActiveFilters = Boolean(
    query.trim() ||
    customerGroupName ||
    salespersonName ||
    region ||
    customerType ||
    customerStatus ||
    taskStatus ||
    blockerReason ||
    overdueFilter ||
    supportFilter ||
    blockedFilter ||
    closedFilter
  );

  if (!canViewTasks) {
    return <Card className="p-6 text-sm font-bold text-slate-500">当前账号没有客户任务查看权限，无法查看项目客户明细。</Card>;
  }

  return (
    <div className="grid gap-4">
      {message ? <Card className="border-amber-200 bg-amber-50 px-4 py-3 text-sm font-bold text-amber-700">{message}</Card> : null}
      <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-5">
        <button type="button" onClick={() => applyMetricFilter("all")} className="text-left transition hover:-translate-y-0.5">
          <CrmProjectMetricCard label="项目客户" value={summary?.total ?? totalRows} detail={`当前筛选 ${totalRows} 条`} icon={UsersRound} />
        </button>
        <button type="button" onClick={() => applyMetricFilter("open")} className="text-left transition hover:-translate-y-0.5">
          <CrmProjectMetricCard label="未闭环" value={summary?.open ?? 0} detail="点击查看待推进客户" tone={(summary?.open ?? 0) > 0 ? "neutral" : "ok"} icon={Clock3} />
        </button>
        <button type="button" onClick={() => applyMetricFilter("overdue")} className="text-left transition hover:-translate-y-0.5">
          <CrmProjectMetricCard label="超期" value={summary?.overdue ?? 0} detail="反馈截止已过" tone={(summary?.overdue ?? 0) > 0 ? "bad" : "ok"} icon={CalendarDays} />
        </button>
        <button type="button" onClick={() => applyMetricFilter("support")} className="text-left transition hover:-translate-y-0.5">
          <CrmProjectMetricCard label="待支持" value={summary?.need_support ?? 0} detail={`主管 ${summary?.need_manager_support ?? 0} / 决策 ${summary?.need_boss_decision ?? 0}`} tone={(summary?.need_support ?? 0) > 0 ? "bad" : "ok"} icon={Siren} />
        </button>
        <button type="button" onClick={() => applyMetricFilter("blocked")} className="text-left transition hover:-translate-y-0.5">
          <CrmProjectMetricCard label="卡点阻塞" value={summary?.blocked ?? 0} detail="点击查看阻塞原因" tone={(summary?.blocked ?? 0) > 0 ? "bad" : "ok"} icon={FileWarning} />
        </button>
      </div>

      <DataTableShell
        title="项目客户明细"
        description={loading ? "正在加载项目客户明细。" : "按客户群、业务员、区域、类型、状态和卡点原因筛选；点击客户行打开任务详情，跟进填写在抽屉内进入。"}
        meta={`${rangeStart}-${rangeEnd} / ${totalRows} 条记录`}
        actions={
          <>
            <Button secondary onClick={() => navigate("crm", `/crm/tasks?project_id=${project.id}`)}>任务列表</Button>
            <Button secondary onClick={() => void loadRows()} disabled={loading}><RefreshCcw className="mr-1.5 h-4 w-4" />刷新</Button>
          </>
        }
        toolbar={
          <DataToolbar onReset={resetFilters}>
            <ToolbarSearch value={query} onChange={(value) => { setCurrentPage(1); setQuery(value); }} placeholder="搜索客户、客户群、业务员、问题点或电话" />
            <ToolbarSelect value={customerGroupName} onChange={(value) => { setCurrentPage(1); setCustomerGroupName(value); }} label="客户群" options={optionItems("全部客户群", summary?.customer_groups)} />
            <ToolbarSelect value={salespersonName} onChange={(value) => { setCurrentPage(1); setSalespersonName(value); }} label="业务员" options={optionItems("全部业务员", summary?.salespersons)} />
            <ToolbarSelect value={region} onChange={(value) => { setCurrentPage(1); setRegion(value); }} label="区域" options={optionItems("全部区域", summary?.regions)} />
            <ToolbarSelect value={customerType} onChange={(value) => { setCurrentPage(1); setCustomerType(value); }} label="客户类型" options={optionItems("全部类型", summary?.customer_types)} />
            <ToolbarSelect value={customerStatus} onChange={(value) => { setCurrentPage(1); setCustomerStatus(value); }} label="客户状态" options={optionItems("全部客户状态", summary?.customer_statuses)} />
            <ToolbarSelect value={taskStatus} onChange={(value) => { setCurrentPage(1); setTaskStatus(value); }} label="任务状态" options={[{ value: "", label: "全部任务状态" }, ...Object.entries(crmTaskStatusLabels).map(([value, label]) => ({ value, label }))]} />
            <ToolbarSelect value={blockerReason} onChange={(value) => { setCurrentPage(1); setBlockerReason(value); }} label="卡点" options={optionItems("全部卡点", summary?.blocker_reasons)} />
            <ToolbarSelect value={overdueFilter} onChange={(value) => { setCurrentPage(1); setOverdueFilter(value); }} label="超期" options={[{ value: "", label: "全部" }, { value: "true", label: "仅超期" }, { value: "false", label: "未超期" }]} />
            <ToolbarSelect value={supportFilter} onChange={(value) => { setCurrentPage(1); setSupportFilter(value); }} label="支持" options={[{ value: "", label: "全部" }, { value: "true", label: "待支持" }, { value: "false", label: "无支持" }]} />
            <ToolbarSelect value={closedFilter} onChange={(value) => { setCurrentPage(1); setClosedFilter(value); }} label="闭环" options={[{ value: "", label: "全部" }, { value: "false", label: "未闭环" }, { value: "true", label: "已闭环" }]} />
          </DataToolbar>
        }
      >
        <Table headers={["客户", "分组/标签", "业务员", "任务状态", "风险", "卡点原因", "反馈截止", "最近跟进"]}>
          {rows.length > 0 ? rows.map((row) => {
            const task = toTaskRow(row);
            return (
              <tr key={row.id} onClick={() => onTaskClick(task)} className="cursor-pointer transition hover:bg-primary-soft">
                <td>
                  <strong className="block max-w-[240px] truncate text-slate-950">{row.customer_name || row.customer_name_snapshot}</strong>
                  <span className="mt-1 block text-xs font-bold text-slate-400">{row.customer_code}</span>
                  {row.contact_phone ? <span className="mt-1 block text-xs font-bold text-slate-500">{row.contact_phone}</span> : null}
                </td>
                <td>
                  <span className="block max-w-[220px] truncate text-sm font-black text-slate-700">{displayValue(row.customer_group_name)}</span>
                  <CustomerDimensionTags region={row.region} customerType={row.customer_type} compact className="mt-2" />
                </td>
                <td>
                  <span className="block text-sm font-bold text-slate-700">{displayValue(row.salesperson_name ?? row.executor_name_snapshot)}</span>
                  <span className="mt-1 block text-xs font-bold text-slate-400">{displayValue(row.executor_employee_code)}</span>
                </td>
                <td>
                  <Badge tone={crmStatusTone(row.task_status)}>{crmTaskStatusLabels[row.task_status] ?? row.task_status}</Badge>
                  <span className="mt-2 block text-xs font-bold text-slate-400">{row.is_closed ? "已闭环" : "未闭环"}</span>
                </td>
                <td>
                  <Badge tone={row.overdue ? "bad" : crmTaskRiskTone(task)}>{row.overdue ? "超期" : crmTaskRiskLabel(task)}</Badge>
                </td>
                <td>
                  <span className="line-clamp-2 max-w-[220px] whitespace-normal text-sm font-bold leading-5 text-slate-600">{displayValue(row.latest_blocker_reason || row.latest_blocker_note)}</span>
                </td>
                <td>{formatDateTime(row.feedback_due_at)}</td>
                <td>{formatDateTime(row.last_followup_at)}</td>
              </tr>
            );
          }) : (
            <CrmEmptyTableRow
              colSpan={8}
              icon={UsersRound}
              message={loading ? "正在加载项目客户明细。" : hasActiveFilters ? "没有符合筛选的项目客户" : "暂无项目客户任务"}
              description={loading ? undefined : hasActiveFilters ? "当前高频筛选没有命中客户，可以清空筛选或切换统计卡查看。" : "项目客户明细来自项目客户任务，项目审批通过或手动分配后会出现在这里。"}
              actions={loading ? [] : [
                ...(hasActiveFilters ? [{ label: "清空筛选", onClick: resetFilters, icon: X, secondary: true }] : []),
                { label: "刷新明细", onClick: () => void loadRows(), icon: RefreshCcw, secondary: true }
              ]}
            />
          )}
        </Table>
        <MasterPagination
          currentPage={safeCurrentPage}
          totalPages={totalPages}
          totalItems={totalRows}
          pageSize={CRM_PROJECT_PAGE_SIZE}
          rangeStart={rangeStart}
          rangeEnd={rangeEnd}
          onPageChange={setCurrentPage}
        />
      </DataTableShell>
    </div>
  );
}

function CrmProjectDetailPage({
  projectId,
  permissions,
  navigate
}: {
  projectId: number;
  permissions: PermissionCode[];
  navigate: (page: Page, path?: string) => void;
}) {
  const canView = hasPermission(permissions, "crm_project.view");
  const canOpenTasks = canAccessCrmPath("/crm/tasks", permissions);
  const canOpenFollowups = canAccessCrmPath("/crm/followups", permissions);
  const canOpenIssues = canAccessCrmPath("/crm/issues", permissions);
  const canOpenWork = canAccessCrmPath("/crm/work", permissions);
  const followupIdParam = Number(initialQueryParam("followup_id"));
  const requestedFollowupId = Number.isInteger(followupIdParam) && followupIdParam > 0 ? followupIdParam : null;
  const [context, setContext] = useState<CrmProjectContext | null>(null);
  const [activeTab, setActiveTab] = useState<CrmProjectTab>("overview");
  const [selectedTask, setSelectedTask] = useState<CrmTaskRow | null>(null);
  const [selectedFollowup, setSelectedFollowup] = useState<CrmFollowupRow | null>(null);
  const [followupLoading, setFollowupLoading] = useState(Boolean(requestedFollowupId));
  const [followupError, setFollowupError] = useState("");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  const loadContext = async () => {
    if (!canView) {
      setContext(null);
      setLoading(false);
      return;
    }
    setLoading(true);
    setError("");
    try {
      const nextContext = await crmProjectContext(projectId);
      setContext(nextContext);
    } catch (loadError) {
      setError(loadError instanceof Error ? loadError.message : "项目详情加载失败");
      setContext(null);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    let cancelled = false;
    if (!canView) {
      setLoading(false);
      setContext(null);
      return;
    }
    setLoading(true);
    setError("");
    void crmProjectContext(projectId)
      .then((nextContext) => {
        if (!cancelled) setContext(nextContext);
      })
      .catch((loadError) => {
        if (!cancelled) {
          setError(loadError instanceof Error ? loadError.message : "项目详情加载失败");
          setContext(null);
        }
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [canView, projectId]);

  useEffect(() => {
    let cancelled = false;
    if (!canView || !requestedFollowupId) {
      setSelectedFollowup(null);
      setFollowupLoading(false);
      setFollowupError("");
      return;
    }
    setSelectedFollowup(null);
    setFollowupLoading(true);
    setFollowupError("");
    void crmFollowup(requestedFollowupId)
      .then((nextFollowup) => {
        if (nextFollowup.project_id !== projectId) throw new Error("该跟进记录不属于当前项目，无法在此处打开。");
        if (!cancelled) setSelectedFollowup(nextFollowup);
      })
      .catch((loadError) => {
        if (!cancelled) {
          setFollowupError(loadError instanceof Error ? loadError.message : "跟进记录加载失败");
          setSelectedFollowup(null);
        }
      })
      .finally(() => {
        if (!cancelled) setFollowupLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [canView, projectId, requestedFollowupId]);

  if (!canView) {
    return (
      <Card className="p-6">
        <CustomerEmptyPanel title="项目详情不可见" description="当前账号没有客户项目查看权限，无法打开项目详情完整页。" />
      </Card>
    );
  }

  const currentProject = context?.project_detail.project ?? null;
  const detail = context?.project_detail ?? null;
  const closureSummary = detail?.closure_summary ?? null;
  const metrics: ContextDrawerMetric[] = currentProject ? [
    { label: "收口判断", value: closureSummary ? crmClosureStateLabels[closureSummary.closure_state] ?? closureSummary.closure_state : "读取中", detail: closureSummary?.closure_ready ? "已满足闭环口径" : "仍需处理阻塞项", tone: crmClosureStateTone(closureSummary?.closure_state), icon: ShieldCheck },
    { label: "客户任务", value: closureSummary?.task_total ?? currentProject.task_total ?? detail?.task_summary.total ?? 0, detail: `未闭环 ${closureSummary?.task_open ?? currentProject.task_open ?? detail?.task_summary.open ?? 0}`, tone: (closureSummary?.task_open ?? currentProject.task_open ?? 0) > 0 ? "warn" : "ok", icon: UsersRound },
    { label: "待支持", value: closureSummary?.support_open_count ?? currentProject.support_item_open ?? detail?.support_item_count ?? 0, detail: `阻塞 ${closureSummary?.task_blocked ?? currentProject.task_blocked ?? detail?.task_summary.blocked ?? 0}`, tone: crmRiskTone(currentProject), icon: FileWarning },
    { label: "待审批", value: closureSummary?.pending_approval_count ?? currentProject.pending_approval_count ?? 0, detail: crmApprovalStatusLabels[currentProject.approval_status] ?? currentProject.approval_status, tone: crmStatusTone(currentProject.approval_status), icon: KeyRound }
  ] : [];
  const tabs: Array<ContextDrawerTab<CrmProjectTab>> = [
    { key: "overview", label: "概览" },
    { key: "closure", label: "闭环", count: closureSummary?.closure_ready ? 1 : 0 },
    { key: "related", label: "关联入口", count: (context?.tasks.length ?? currentProject?.task_total ?? 0) + (context?.followups.length ?? 0) + (context?.work_items.length ?? currentProject?.support_item_open ?? 0) }
  ];

  return (
    <>
      <Header
        eyebrow="CRM PROJECT DETAIL"
        title={currentProject?.project_name ?? "项目详情"}
        description={currentProject ? `${currentProject.project_code} · ${displayValue(currentProject.project_type)} · ${displayValue(currentProject.business_line)}` : "正在读取项目完整上下文。"}
        actions={
          <>
            <Button secondary onClick={() => navigate("crm", "/crm/projects")}>返回项目列表</Button>
            <Button secondary onClick={() => void loadContext()} disabled={loading}><RefreshCcw className="mr-1.5 h-4 w-4" />刷新</Button>
          </>
        }
      />
      {error ? <Card className="mb-4 border-red-200 bg-red-50 p-4 text-sm font-bold text-red-600">{error}</Card> : null}
      {loading && !currentProject ? <Card className="p-5"><CrmDrawerLoading /></Card> : null}
      {!loading && !currentProject && !error ? <Card className="p-6"><CustomerEmptyPanel title="项目不存在" description="没有找到该项目，或该项目超出当前账号可见范围。" /></Card> : null}
      {currentProject ? (
        <ContextDrawerFrame
          eyebrow="CRM PROJECT"
          title={currentProject.project_name}
          subtitle={`${displayValue(currentProject.project_type)} · ${displayValue(currentProject.business_line)} · ${formatDate(currentProject.start_date)} - ${formatDate(currentProject.due_date)}`}
          badges={[
            { label: crmProjectStatusLabels[currentProject.status] ?? currentProject.status, tone: crmStatusTone(currentProject.status) },
            { label: crmApprovalStatusLabels[currentProject.approval_status] ?? currentProject.approval_status, tone: crmStatusTone(currentProject.approval_status) }
          ]}
          metrics={metrics}
          tabs={tabs}
          activeTab={activeTab}
          onTabChange={setActiveTab}
          sidebar={
            <>
              <CustomerSideCard title="推进判断" icon={Clock3}>
                <CustomerSideRow label="下一步状态" value={displayValue(currentProject.next_step_status)} />
                <CustomerSideRow label="下一步动作" value={displayValue(currentProject.next_step_action)} multiline />
              <CustomerSideRow label="下次跟进" value={formatDateTime(currentProject.next_step_followup_at)} />
            </CustomerSideCard>
              <CustomerSideCard title="关联入口" icon={LayoutDashboard}>
                {canOpenTasks ? <button type="button" onClick={() => navigate("crm", withQuery("/crm/tasks", { project_id: currentProject.id }))} className="w-full rounded-lg border border-slate-200 bg-white px-3 py-2 text-left text-xs font-black text-primary hover:bg-primary-soft">任务明细</button> : null}
                {canOpenFollowups ? <button type="button" onClick={() => navigate("crm", withQuery("/crm/followups", { project_id: currentProject.id }))} className="mt-2 w-full rounded-lg border border-slate-200 bg-white px-3 py-2 text-left text-xs font-black text-primary hover:bg-primary-soft">跟进记录</button> : null}
                {canOpenIssues ? <button type="button" onClick={() => navigate("crm", withQuery("/crm/issues", { project_id: currentProject.id }))} className="mt-2 w-full rounded-lg border border-slate-200 bg-white px-3 py-2 text-left text-xs font-black text-primary hover:bg-primary-soft">待支持事项</button> : null}
                {canOpenWork ? <button type="button" onClick={() => navigate("crm", "/crm/work")} className="mt-2 w-full rounded-lg border border-slate-200 bg-white px-3 py-2 text-left text-xs font-black text-primary hover:bg-primary-soft">审批处理</button> : null}
                {!canOpenTasks && !canOpenFollowups && !canOpenIssues && !canOpenWork ? <p className="m-0 rounded-lg bg-slate-50 px-3 py-2 text-xs font-bold text-slate-500">当前账号暂无可跳转的关联入口。</p> : null}
              </CustomerSideCard>
            </>
          }
        >
          {loading ? <CrmDrawerLoading /> : null}
          {!loading && activeTab === "overview" ? <CrmProjectOverview project={currentProject} detail={detail} /> : null}
          {!loading && activeTab === "closure" ? <CrmProjectClosureView project={currentProject} detail={detail} context={context} onTaskClick={setSelectedTask} /> : null}
          {!loading && activeTab === "related" ? <CrmProjectRelatedSummary project={currentProject} detail={detail} context={context} permissions={permissions} navigate={navigate} /> : null}
        </ContextDrawerFrame>
      ) : null}
      <AnimatePresence>
        {selectedTask ? (
          <CrmTaskDetailDrawer
            key={`project-page-task-detail-${selectedTask.id}`}
            task={selectedTask}
            permissions={permissions}
            navigate={navigate}
            onClose={() => setSelectedTask(null)}
            onChanged={async (updatedTask) => {
              setSelectedTask(updatedTask);
              setActiveTab("closure");
              await loadContext();
            }}
          />
        ) : null}
      </AnimatePresence>
      <AnimatePresence>
        {requestedFollowupId ? (
          <CrmFollowupDetailDrawer
            key={`project-followup-detail-${requestedFollowupId}`}
            followupId={requestedFollowupId}
            followup={selectedFollowup}
            projectName={currentProject?.project_name}
            loading={followupLoading}
            error={followupError}
            navigate={navigate}
            canOpenProject
            onClose={() => navigate("crm", `/crm/projects/${projectId}`)}
          />
        ) : null}
      </AnimatePresence>
    </>
  );
}

function followupFlagLabel(value: boolean) {
  return value ? "是" : "否";
}

function CrmFollowupDetailDrawer({
  followupId,
  followup,
  projectName,
  loading,
  error,
  navigate,
  canOpenProject = false,
  onClose
}: {
  followupId: number;
  followup: CrmFollowupRow | null;
  projectName?: string;
  loading: boolean;
  error: string;
  navigate: (page: Page, path?: string) => void;
  canOpenProject?: boolean;
  onClose: () => void;
}) {
  const supportRequested = Boolean(followup && (followup.need_support || followup.need_manager_support || followup.need_boss_decision));
  const customerName = displayValue(followup?.customer_name);
  const customerCode = displayValue(followup?.customer_code);
  const taskCode = followup ? `任务 #${followup.task_id}` : "-";

  return (
    <Drawer
      title={followup ? `跟进记录 ${followup.followup_no}` : "跟进记录"}
      subtitle={followup ? `${displayValue(followup.executor_name_snapshot ?? followup.executor_user_id)} · ${customerName}` : `记录 #${followupId}`}
      onClose={onClose}
    >
      {loading ? <CrmDrawerLoading /> : null}
      {!loading && error ? (
        <Card className="border-red-200 bg-red-50 p-5">
          <h3 className="m-0 text-base font-black text-red-700">跟进记录无法打开</h3>
          <p className="m-0 mt-2 text-sm font-bold leading-6 text-red-600">{error}</p>
          <div className="mt-4"><Button secondary onClick={onClose}>关闭详情</Button></div>
        </Card>
      ) : null}
      {!loading && !error && followup ? (
        <div className="grid gap-5">
          <section className="rounded-lg border border-primary/20 bg-primary-soft p-4">
            <div className="flex flex-wrap items-start justify-between gap-3">
              <div>
                <p className="m-0 text-xs font-black uppercase tracking-[0.18em] text-primary">FOLLOWUP DETAIL</p>
                <h3 className="m-0 mt-1 text-lg font-black text-slate-950">销售跟进记录</h3>
                <p className="m-0 mt-1 text-xs font-bold text-slate-500">展示本次点击的原始跟进内容及审核、支持和闭环状态。</p>
              </div>
              <div className="flex flex-wrap gap-2">
                <Badge tone={followup.valid_feedback ? "ok" : "warn"}>{followup.valid_feedback ? "有效反馈" : "反馈待确认"}</Badge>
                <Badge tone={supportRequested ? "warn" : "neutral"}>{supportRequested ? "需要支持" : "常规跟进"}</Badge>
                <Badge tone={crmStatusTone(followup.review_status)}>{crmApprovalStatusLabels[followup.review_status] ?? followup.review_status}</Badge>
              </div>
            </div>
            <div className="mt-4 grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
              <CustomerMeta label="跟进编号" value={followup.followup_no} />
              <CustomerMeta label="销售 / 执行人" value={displayValue(followup.executor_name_snapshot ?? followup.executor_user_id)} />
              <CustomerMeta label="客户" value={`${customerName} / ${customerCode}`} />
              <CustomerMeta label="记录时间" value={formatDateTime(followup.followup_date ?? followup.created_at)} />
            </div>
          </section>

          <section>
            <div className="mb-3 flex flex-wrap items-end justify-between gap-2">
              <div>
                <h3 className="m-0 text-base font-black text-slate-950">跟进内容</h3>
                <p className="m-0 mt-1 text-xs font-bold text-slate-500">重点呈现销售填写的执行动作、客户反馈和当前需求。</p>
              </div>
            </div>
            <FollowupBusinessSummaryCards
              followup={followup}
              customerName={customerName}
              customerCode={customerCode}
              projectName={displayValue(projectName ?? followup.project_id)}
              taskCode={taskCode}
              onOpenCustomer={customerCode !== "-" ? () => navigate("crm", `/crm/customers?q=${encodeURIComponent(customerCode)}`) : undefined}
              onOpenProject={canOpenProject ? () => navigate("crm", `/crm/projects/${followup.project_id}`) : undefined}
            />
          </section>

          <section>
            <h3 className="m-0 text-base font-black text-slate-950">完整记录</h3>
            <div className="mt-3 grid gap-4 lg:grid-cols-2">
              <CustomerSideCard title="卡点与下一步" icon={Clock3}>
                <CustomerSideRow label="卡点原因" value={displayValue(followup.blocker_reason)} multiline />
                <CustomerSideRow label="卡点说明" value={displayValue(followup.blocker_note)} multiline />
                <CustomerSideRow label="下一步类型" value={displayValue(followup.next_action_type)} />
                <CustomerSideRow label="下一步动作" value={displayValue(followup.next_action)} multiline />
                <CustomerSideRow label="下次跟进" value={formatDateTime(followup.next_followup_at)} />
              </CustomerSideCard>
              <CustomerSideCard title="支持与闭环" icon={ShieldCheck}>
                <CustomerSideRow label="需要支持" value={followupFlagLabel(followup.need_support)} />
                <CustomerSideRow label="支持类型" value={supportRequested ? displayValue(followup.need_type) : "无需支持"} />
                <CustomerSideRow label="主管协同" value={followupFlagLabel(followup.need_manager_support)} />
                <CustomerSideRow label="管理决策" value={followupFlagLabel(followup.need_boss_decision)} />
                <CustomerSideRow label="最小动作完成" value={followupFlagLabel(followup.minimum_action_done)} />
                <CustomerSideRow label="客户资料更新" value={followupFlagLabel(followup.customer_profile_updated)} />
                <CustomerSideRow label="经营资料更新" value={followupFlagLabel(followup.business_profile_updated)} />
                <CustomerSideRow label="已闭环" value={followupFlagLabel(followup.is_closed)} />
              </CustomerSideCard>
              <CustomerSideCard title="审核结果" icon={ClipboardList}>
                <CustomerSideRow label="有效反馈" value={followupFlagLabel(followup.valid_feedback)} />
                <CustomerSideRow label="审核状态" value={crmApprovalStatusLabels[followup.review_status] ?? followup.review_status} />
                <CustomerSideRow label="审核结果" value={displayValue(followup.review_result)} />
                <CustomerSideRow label="审核意见" value={displayValue(followup.review_note)} multiline />
                <CustomerSideRow label="审核人" value={displayValue(followup.reviewed_by_user_id)} />
                <CustomerSideRow label="审核时间" value={formatDateTime(followup.reviewed_at)} />
              </CustomerSideCard>
              <CustomerSideCard title="负责人安排" icon={UserCheck}>
                <CustomerSideRow label="下一步状态" value={displayValue(followup.owner_next_status)} />
                <CustomerSideRow label="负责人动作" value={displayValue(followup.owner_next_action)} multiline />
                <CustomerSideRow label="负责人跟进时间" value={formatDateTime(followup.owner_next_followup_at)} />
                <CustomerSideRow label="审批编号" value={displayValue(followup.approval_id)} />
                <CustomerSideRow label="创建时间" value={formatDateTime(followup.created_at)} />
                <CustomerSideRow label="更新时间" value={formatDateTime(followup.updated_at)} />
              </CustomerSideCard>
            </div>
          </section>
        </div>
      ) : null}
    </Drawer>
  );
}

function CrmGovernanceSection({ permissions, navigate }: { permissions: PermissionCode[]; navigate: (page: Page, path?: string) => void }) {
  const canView = hasPermission(permissions, "crm_project.view");
  const canVoid = hasPermission(permissions, "crm_project.edit");
  const [pageData, setPageData] = useState<CrmTestProjectPage | null>(null);
  const [marker, setMarker] = useState(() => initialQueryParam("marker") || "E2E");
  const [includeCancelled, setIncludeCancelled] = useState(true);
  const [currentPage, setCurrentPage] = useState(1);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");
  const [voidCandidate, setVoidCandidate] = useState<CrmTestProjectCandidate | null>(null);

  const totalRows = pageData?.total ?? 0;
  const totalPages = Math.max(1, Math.ceil(totalRows / CRM_PROJECT_PAGE_SIZE));
  const safeCurrentPage = Math.min(currentPage, totalPages);
  const offset = (safeCurrentPage - 1) * CRM_PROJECT_PAGE_SIZE;
  const rangeStart = totalRows === 0 ? 0 : offset + 1;
  const rangeEnd = Math.min(offset + CRM_PROJECT_PAGE_SIZE, totalRows);
  const rows = pageData?.items ?? [];
  const pageStats = {
    active: rows.filter((item) => item.project.status !== "cancelled").length,
    cancelled: rows.filter((item) => item.project.status === "cancelled").length,
    pendingWork: rows.reduce((sum, item) => sum + item.counts.open_work_item_total + item.counts.pending_approval_total, 0),
    linkedRecords: rows.reduce((sum, item) => sum + item.counts.task_total + item.counts.followup_total + item.counts.review_total + item.counts.approval_total + item.counts.work_item_total, 0)
  };

  const loadRows = async () => {
    if (!canView) {
      setPageData(null);
      return;
    }
    setLoading(true);
    setMessage("");
    try {
      const nextPage = await crmTestProjectsPage({
        marker,
        include_cancelled: includeCancelled,
        limit: CRM_PROJECT_PAGE_SIZE,
        offset
      });
      setPageData(nextPage);
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "临时数据候选加载失败");
      setPageData(null);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void loadRows();
  }, [canView, marker, includeCancelled, offset]);

  useEffect(() => {
    if (currentPage !== safeCurrentPage) setCurrentPage(safeCurrentPage);
  }, [currentPage, safeCurrentPage]);

  const resetFilters = () => {
    setCurrentPage(1);
    setMarker("E2E");
    setIncludeCancelled(true);
  };
  const hasActiveGovernanceFilters = Boolean(marker.trim() !== "E2E" || !includeCancelled);

  if (!canView) {
    return <Card className="p-6 text-sm font-bold text-slate-500">当前账号没有客户项目查看权限，无法进入 CRM 数据治理。</Card>;
  }

  return (
    <>
      <Header
        eyebrow="CRM GOVERNANCE"
        title="临时数据与作废治理"
        description="识别带临时标识的 CRM 项目，按受控流程软作废，保留审批、跟进、复盘和审计证据。"
        actions={<Button secondary onClick={() => void loadRows()} disabled={loading}><RefreshCcw className="mr-1.5 h-4 w-4" />刷新</Button>}
      />

      <div className="mb-4 grid gap-3 md:grid-cols-2 xl:grid-cols-4">
        <CrmProjectMetricCard label="候选项目" value={totalRows} detail={`当前页 ${rows.length} 条`} icon={Trash2} />
        <CrmProjectMetricCard label="待作废" value={pageStats.active} detail="尚未进入 cancelled 状态" tone={pageStats.active > 0 ? "neutral" : "ok"} icon={FileWarning} />
        <CrmProjectMetricCard label="已作废" value={pageStats.cancelled} detail="已进入软作废状态" tone="ok" icon={ShieldCheck} />
        <CrmProjectMetricCard label="关联记录" value={pageStats.linkedRecords} detail={`待处理 ${pageStats.pendingWork}`} tone={pageStats.pendingWork > 0 ? "warn" : "neutral"} icon={Database} />
      </div>

      <DataTableShell
        title="临时项目候选"
        description={loading ? "正在扫描临时数据候选。" : message || "仅展示命中临时标识的项目；作废会关闭未处理事项和未终态审批，不会硬删除历史记录。"}
        meta={`${rangeStart}-${rangeEnd} / ${totalRows} 条记录`}
        toolbar={
          <DataToolbar onReset={resetFilters}>
            <ToolbarSearch value={marker} onChange={(value) => { setCurrentPage(1); setMarker(value); }} placeholder="临时标识，例如 TEMP、E2E" />
            <label className="inline-flex h-9 items-center gap-2 rounded-lg border border-slate-200 bg-white px-3 text-xs font-black text-slate-600">
              <input
                type="checkbox"
                checked={includeCancelled}
                onChange={(event) => { setCurrentPage(1); setIncludeCancelled(event.target.checked); }}
                className="h-4 w-4 accent-primary"
              />
              包含已作废
            </label>
          </DataToolbar>
        }
      >
        <Table headers={["项目", "识别原因", "状态", "关联数据", "待处理", "最近活动", "操作"]}>
          {rows.length > 0 ? rows.map((item) => (
            <tr
              key={item.project.id}
              onClick={() => navigate("crm", `/crm/projects/${item.project.id}`)}
              className="cursor-pointer transition hover:bg-primary-soft"
            >
              <td>
                <strong className="block max-w-[280px] truncate text-slate-950">{item.project.project_name}</strong>
                <span className="mt-1 block text-xs font-bold text-slate-400">{item.project.project_code}</span>
              </td>
              <td>
                <span className="line-clamp-2 max-w-[260px] whitespace-normal text-sm font-bold leading-5 text-slate-600">
                  {item.test_reasons.length ? item.test_reasons.slice(0, 3).join("；") : "-"}
                </span>
              </td>
              <td>
                <Badge tone={crmStatusTone(item.project.status)}>{crmProjectStatusLabels[item.project.status] ?? item.project.status}</Badge>
              </td>
              <td>
                <span className="block text-sm font-black text-slate-800">任务 {item.counts.task_total} / 跟进 {item.counts.followup_total}</span>
                <span className="mt-1 block text-xs font-bold text-slate-400">审批 {item.counts.approval_total} / 复盘 {item.counts.review_total} / 事项 {item.counts.work_item_total}</span>
              </td>
              <td>
                <Badge tone={item.counts.open_work_item_total + item.counts.pending_approval_total > 0 ? "neutral" : "ok"}>
                  事项 {item.counts.open_work_item_total} / 审批 {item.counts.pending_approval_total}
                </Badge>
              </td>
              <td>{formatDateTime(item.counts.latest_activity_at ?? item.project.updated_at)}</td>
              <td>
                {item.project.status === "cancelled" ? (
                  <span className="text-xs font-bold text-slate-400">已作废</span>
                ) : canVoid && item.can_void ? (
                  <button
                    type="button"
                    onClick={(event) => { event.stopPropagation(); setVoidCandidate(item); }}
                    className="rounded-lg border border-red-200 bg-red-50 px-3 py-2 text-xs font-black text-red-600 transition hover:bg-red-100"
                  >
                    作废
                  </button>
                ) : (
                  <span className="text-xs font-bold text-slate-400">无权限</span>
                )}
              </td>
            </tr>
          )) : (
            <CrmEmptyTableRow
              colSpan={7}
              icon={ShieldCheck}
              message={loading ? "正在扫描临时项目候选。" : "没有命中临时标识的数据"}
              description={loading ? undefined : hasActiveGovernanceFilters ? "当前治理筛选没有匹配候选项目，可以恢复默认临时标识后重新扫描。" : "默认临时标识下没有待治理项目，当前数据作废治理处于清爽状态。"}
              actions={loading ? [] : [
                ...(hasActiveGovernanceFilters ? [{ label: "恢复默认筛选", onClick: resetFilters, icon: RefreshCcw, secondary: true }] : []),
                { label: "查看项目列表", onClick: () => navigate("crm", "/crm/projects"), icon: BriefcaseBusiness }
              ]}
            />
          )}
        </Table>
        <MasterPagination
          currentPage={safeCurrentPage}
          totalPages={totalPages}
          totalItems={totalRows}
          pageSize={CRM_PROJECT_PAGE_SIZE}
          rangeStart={rangeStart}
          rangeEnd={rangeEnd}
          onPageChange={setCurrentPage}
        />
      </DataTableShell>

      <AnimatePresence>
        {voidCandidate ? (
          <CrmVoidTestProjectDrawer
            key={voidCandidate.project.id}
            candidate={voidCandidate}
            onClose={() => setVoidCandidate(null)}
            onVoided={(resultMessage) => {
              setVoidCandidate(null);
              setMessage(resultMessage);
              void loadRows();
            }}
          />
        ) : null}
      </AnimatePresence>
    </>
  );
}

function CrmVoidTestProjectDrawer({
  candidate,
  onClose,
  onVoided
}: {
  candidate: CrmTestProjectCandidate;
  onClose: () => void;
  onVoided: (message: string) => void;
}) {
  const [reason, setReason] = useState("临时数据治理作废");
  const [confirmText, setConfirmText] = useState("");
  const [saving, setSaving] = useState(false);
  const [message, setMessage] = useState("");
  const canSubmit = reason.trim().length >= 2 && confirmText.trim() === "作废临时项目";

  const submit = async () => {
    if (!canSubmit) return;
    setSaving(true);
    setMessage("");
    try {
      const result = await voidCrmTestProject(candidate.project.id, {
        reason: reason.trim(),
        confirmation: "VOID_TEST_PROJECT"
      });
      onVoided(result.message);
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "临时项目作废失败");
    } finally {
      setSaving(false);
    }
  };

  return (
    <Drawer title="作废临时项目" subtitle={`${candidate.project.project_code} · ${candidate.project.project_name}`} onClose={onClose}>
      <div className="grid gap-4 xl:grid-cols-[minmax(0,1fr)_320px]">
        <section className="grid gap-4">
          <Card className="border-red-200 bg-red-50 p-4">
            <p className="m-0 text-xs font-black uppercase tracking-[0.18em] text-red-600">VOID TEMP DATA</p>
            <h3 className="m-0 mt-1 text-xl font-black text-slate-950">确认软作废临时项目</h3>
            <p className="m-0 mt-2 text-sm font-bold leading-6 text-slate-600">系统会将项目置为已取消，关闭未闭环任务、未处理事项和未终态审批；跟进、复盘、审批事件和审计日志会保留。</p>
          </Card>

          <Card className="p-4">
            <h4 className="m-0 text-sm font-black text-slate-950">作废信息</h4>
            <div className="mt-4 grid gap-3">
              <AccountField label="作废原因">
                <textarea
                  value={reason}
                  onChange={(event) => setReason(event.target.value)}
                  rows={4}
                  className="resize-none rounded-lg border border-slate-200 px-3 py-2 text-sm font-bold"
                />
              </AccountField>
              <AccountField label="确认口令">
                <input
                  value={confirmText}
                  onChange={(event) => setConfirmText(event.target.value)}
                  placeholder="输入：作废临时项目"
                  className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold"
                />
              </AccountField>
              {message ? <p className="m-0 rounded-lg bg-red-50 px-3 py-2 text-sm font-bold text-red-600">{message}</p> : null}
              <div className="flex justify-end gap-2">
                <Button secondary disabled={saving} onClick={onClose}>取消</Button>
                <Button disabled={!canSubmit || saving} onClick={() => void submit()}><Trash2 className="mr-1.5 h-4 w-4" />确认作废</Button>
              </div>
            </div>
          </Card>
        </section>

        <aside className="grid content-start gap-3">
          <CustomerSideCard title="识别原因" icon={FileWarning}>
            {candidate.test_reasons.length ? candidate.test_reasons.slice(0, 6).map((reasonItem) => (
              <CustomerSideRow key={reasonItem} label="命中" value={reasonItem} />
            )) : <CustomerSideRow label="命中" value="-" />}
          </CustomerSideCard>
          <CustomerSideCard title="关联数据" icon={Database}>
            <CustomerSideRow label="客户任务" value={String(candidate.counts.task_total)} />
            <CustomerSideRow label="跟进记录" value={String(candidate.counts.followup_total)} />
            <CustomerSideRow label="项目复盘" value={String(candidate.counts.review_total)} />
            <CustomerSideRow label="审批记录" value={String(candidate.counts.approval_total)} />
            <CustomerSideRow label="待支持项" value={`${candidate.counts.open_work_item_total}/${candidate.counts.work_item_total}`} />
          </CustomerSideCard>
          <CustomerSideCard title="当前状态" icon={Shield}>
            <CustomerSideRow label="项目状态" value={crmProjectStatusLabels[candidate.project.status] ?? candidate.project.status} />
            <CustomerSideRow label="审批状态" value={crmApprovalStatusLabels[candidate.project.approval_status] ?? candidate.project.approval_status} />
            <CustomerSideRow label="最近活动" value={formatDateTime(candidate.counts.latest_activity_at ?? candidate.project.updated_at)} />
          </CustomerSideCard>
        </aside>
      </div>
    </Drawer>
  );
}

function CrmProjectsPage({ permissions, currentUser, navigate }: { permissions: PermissionCode[]; currentUser: UserPublic; navigate: (page: Page, path?: string) => void }) {
  const canView = hasPermission(permissions, "crm_project.view");
  const canViewAnalysis = hasAnyPermission(permissions, ["crm_insight.view", "crm_project.view"]);
  const canCreate = hasPermission(permissions, "crm_project.create");
  const canOpenIssues = canAccessCrmPath("/crm/issues", permissions);
  const canOpenCustomers = canAccessCrmPath("/crm/customers", permissions);
  const initialWorkspaceTab = normalizeCrmPath(window.location.pathname) === "/crm/insights" || initialQueryParam("view") === "analysis" || (!canView && canViewAnalysis) ? "analysis" : "list";
  const [activeWorkspaceTab, setActiveWorkspaceTab] = useState<"list" | "analysis">(initialWorkspaceTab);
  const [pageData, setPageData] = useState<{ items: CrmProjectRow[]; total: number; limit: number; offset: number } | null>(null);
  const [query, setQuery] = useState(() => initialQueryParam("q"));
  const [statusValue, setStatusValue] = useState(() => initialQueryParam("status_value"));
  const [approvalStatus, setApprovalStatus] = useState(() => initialQueryParam("approval_status"));
  const [ownerUserId, setOwnerUserId] = useState(() => initialQueryParam("owner_user_id"));
  const [executorUserId, setExecutorUserId] = useState(() => initialQueryParam("executor_user_id"));
  const [currentPage, setCurrentPage] = useState(1);
  const [createDrawerOpen, setCreateDrawerOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");

  const totalRows = pageData?.total ?? 0;
  const totalPages = Math.max(1, Math.ceil(totalRows / CRM_PROJECT_PAGE_SIZE));
  const safeCurrentPage = Math.min(currentPage, totalPages);
  const offset = (safeCurrentPage - 1) * CRM_PROJECT_PAGE_SIZE;
  const rangeStart = totalRows === 0 ? 0 : offset + 1;
  const rangeEnd = Math.min(offset + CRM_PROJECT_PAGE_SIZE, totalRows);
  const rows = pageData?.items ?? [];
  const pageStats = {
    active: rows.filter((row) => row.status === "active").length,
    pendingApproval: rows.filter((row) => (row.pending_approval_count ?? 0) > 0 || ["submitted", "under_review", "need_supplement"].includes(row.approval_status)).length,
    risky: rows.filter((row) => crmRiskTone(row) !== "ok").length,
    closed: rows.filter((row) => row.status === "closed").length
  };

  const loadRows = async () => {
    if (!canView) {
      setPageData(null);
      return;
    }
    setLoading(true);
    setMessage("");
    try {
      const nextPage = await crmProjectsPage({
        q: query,
        status_value: statusValue,
        approval_status: approvalStatus,
        owner_user_id: numericFilterValue(ownerUserId),
        executor_user_id: numericFilterValue(executorUserId),
        limit: CRM_PROJECT_PAGE_SIZE,
        offset
      });
      setPageData(nextPage);
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "客户项目加载失败");
      setPageData(null);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void loadRows();
  }, [canView, query, statusValue, approvalStatus, ownerUserId, executorUserId, offset]);

  useEffect(() => {
    if (currentPage !== safeCurrentPage) setCurrentPage(safeCurrentPage);
  }, [currentPage, safeCurrentPage]);

  useEffect(() => {
    if (activeWorkspaceTab === "list" && !canView && canViewAnalysis) setActiveWorkspaceTab("analysis");
  }, [activeWorkspaceTab, canView, canViewAnalysis]);

  const resetFilters = () => {
    setCurrentPage(1);
    setQuery("");
    setStatusValue("");
    setApprovalStatus("");
    setOwnerUserId("");
    setExecutorUserId("");
  };
  const hasActiveProjectFilters = Boolean(query.trim() || statusValue || approvalStatus || ownerUserId || executorUserId);
  const switchWorkspaceTab = (tab: "list" | "analysis") => {
    setActiveWorkspaceTab(tab);
    window.history.replaceState(null, "", tab === "analysis" ? "/crm/projects?view=analysis" : "/crm/projects");
  };

  return (
    <>
      <Header
        eyebrow="CRM PROJECTS"
        title="项目列表"
        description="集中查看项目状态、客户范围、推进质量和风险分析。"
        actions={
          <>
            {activeWorkspaceTab === "analysis" ? (
              <>
                <Button secondary onClick={() => navigate("crm", "/crm/data")}>数据中心</Button>
                <Button secondary onClick={() => navigate("crm", "/crm/daily-board")}>每日看板</Button>
              </>
            ) : (
              <>
                {canOpenIssues ? <Button secondary onClick={() => navigate("crm", "/crm/issues")}>待支持事项</Button> : null}
                <Button secondary onClick={() => void loadRows()} disabled={loading}><RefreshCcw className="mr-1.5 h-4 w-4" />刷新</Button>
                {canCreate ? <Button onClick={() => setCreateDrawerOpen(true)}><Plus className="mr-1.5 h-4 w-4" />新增项目</Button> : null}
              </>
            )}
          </>
        }
      />

      <div className="mb-4 flex flex-wrap gap-2">
        {canView ? (
          <button type="button" onClick={() => switchWorkspaceTab("list")} className={`rounded-lg border px-4 py-2 text-sm font-black ${activeWorkspaceTab === "list" ? "border-primary bg-primary-soft text-primary" : "border-slate-200 bg-white text-slate-600"}`}>项目列表</button>
        ) : null}
        {canViewAnalysis ? (
          <button type="button" onClick={() => switchWorkspaceTab("analysis")} className={`rounded-lg border px-4 py-2 text-sm font-black ${activeWorkspaceTab === "analysis" ? "border-primary bg-primary-soft text-primary" : "border-slate-200 bg-white text-slate-600"}`}>经营分析</button>
        ) : null}
      </div>

      {activeWorkspaceTab === "analysis" ? (
        <CrmInsightsSection permissions={permissions} navigate={navigate} embedded />
      ) : canView ? (
        <>
          <div className="mb-4 grid gap-3 md:grid-cols-2 xl:grid-cols-5">
            <CrmProjectMetricCard label="项目总数" value={totalRows} detail={`当前页 ${rows.length} 条`} icon={BriefcaseBusiness} />
            <CrmProjectMetricCard label="进行中" value={pageStats.active} detail="当前页 active 项目" tone="ok" icon={Clock3} />
            <CrmProjectMetricCard label="待审批" value={pageStats.pendingApproval} detail="需负责人或审批人处理" tone={pageStats.pendingApproval > 0 ? "neutral" : "ok"} icon={ShieldCheck} />
            <CrmProjectMetricCard label="风险项目" value={pageStats.risky} detail="含阻塞、支持项或审批卡点" tone={pageStats.risky > 0 ? "bad" : "ok"} icon={FileWarning} />
            <CrmProjectMetricCard label="已闭环" value={pageStats.closed} detail="当前页 closed 项目" icon={Shield} />
          </div>

          <DataTableShell
            title="项目列表"
            description={loading ? "正在加载客户项目。" : message || "点击项目行查看项目概览、闭环状态和关联入口。"}
            meta={`${rangeStart}-${rangeEnd} / ${totalRows} 条记录`}
            toolbar={
              <DataToolbar onReset={resetFilters}>
                <ToolbarSearch value={query} onChange={(value) => { setCurrentPage(1); setQuery(value); }} placeholder="搜索项目编号、名称、类型或业务线" />
                <ToolbarSelect
                  value={statusValue}
                  onChange={(value) => { setCurrentPage(1); setStatusValue(value); }}
                  label="状态"
                  options={[{ value: "", label: "全部状态" }, ...Object.entries(crmProjectStatusLabels).map(([value, label]) => ({ value, label }))]}
                />
                <ToolbarSelect
                  value={approvalStatus}
                  onChange={(value) => { setCurrentPage(1); setApprovalStatus(value); }}
                  label="审批"
                  options={[{ value: "", label: "全部审批" }, ...Object.entries(crmApprovalStatusLabels).map(([value, label]) => ({ value, label }))]}
                />
                <CrmFilterInput label="细节审批人ID" value={ownerUserId} onChange={(value) => { setCurrentPage(1); setOwnerUserId(value); }} />
                <CrmFilterInput label="执行人ID" value={executorUserId} onChange={(value) => { setCurrentPage(1); setExecutorUserId(value); }} />
              </DataToolbar>
            }
          >
            <Table headers={["项目", "类型", "状态", "细节审批人", "一线业务员", "项目进度", "风险", "审批", "最近跟进", "更新时间", "操作"]}>
              {rows.length > 0 ? rows.map((project) => {
                  const taskTotal = project.task_total ?? 0;
                  const taskClosed = project.task_closed ?? 0;
                  const progress = taskTotal > 0 ? Math.round((taskClosed / taskTotal) * 100) : 0;
                  return (
                    <tr
                      key={project.id}
                      onClick={() => navigate("crm", `/crm/projects/${project.id}`)}
                      className="cursor-pointer transition hover:bg-primary-soft"
                    >
                      <td>
                        <strong className="block text-slate-950">{project.project_name}</strong>
                        <span className="mt-1 block text-xs font-bold text-slate-400">{project.project_code}</span>
                      </td>
                      <td>{displayValue(project.project_type)}</td>
                      <td><Badge tone={crmStatusTone(project.status)}>{crmProjectStatusLabels[project.status] ?? project.status}</Badge></td>
                      <td>{crmUserDisplayLabel(project.owner_user_label, project.owner_user_id)}</td>
                      <td>{crmUserListDisplay(project.participant_user_labels, project.participant_user_ids)}</td>
                      <td>
                        <div className="min-w-36">
                          <div className="flex items-center justify-between gap-2 text-xs font-black text-slate-500">
                            <span>{taskClosed}/{taskTotal}</span>
                            <span>{taskTotal > 0 ? `${progress}%` : "-"}</span>
                          </div>
                          <span className="mt-1 block h-2 overflow-hidden rounded-full bg-slate-100">
                            <span className="block h-full rounded-full bg-primary" style={{ width: `${Math.min(100, progress)}%` }} />
                          </span>
                          <span className="mt-1 block text-xs font-bold text-slate-400">
                            未闭环 {project.task_open ?? 0} · 支持 {project.task_need_support ?? 0} · 超期 {project.task_overdue ?? 0}
                          </span>
                        </div>
                      </td>
                      <td>
                        <Badge tone={crmRiskTone(project)}>支持 {project.task_need_support ?? 0} / 阻塞 {project.task_blocked ?? 0}</Badge>
                      </td>
                      <td><Badge tone={crmStatusTone(project.approval_status)}>{crmApprovalStatusLabels[project.approval_status] ?? project.approval_status}</Badge></td>
                      <td>{formatDateTime(project.latest_followup_at)}</td>
                      <td>{formatDateTime(project.updated_at)}</td>
                      <td>
                        <button
                          type="button"
                          onClick={(event) => {
                            event.stopPropagation();
                            navigate("crm", withQuery("/crm/tasks", { project_id: project.id }));
                          }}
                          className="inline-flex items-center rounded-lg border border-primary/20 bg-primary-soft px-3 py-2 text-xs font-black text-primary transition hover:border-primary/40 hover:bg-blue-100"
                        >任务明细</button>
                      </td>
                    </tr>
                  );
              }) : (
                <CrmEmptyTableRow
                  colSpan={11}
                  icon={BriefcaseBusiness}
                  message={loading ? "正在加载客户项目。" : hasActiveProjectFilters ? "没有符合筛选的客户项目" : "暂无客户项目"}
                  description={loading ? undefined : hasActiveProjectFilters ? "当前筛选没有命中项目，可以清空筛选后查看完整项目池。" : "客户项目由项目申请审批通过后生成，后续任务、跟进、审批和复盘都会围绕项目沉淀。"}
                  actions={loading ? [] : [
                    ...(hasActiveProjectFilters ? [{ label: "清空筛选", onClick: resetFilters, icon: X, secondary: true }] : []),
                    ...(canCreate ? [{ label: "新增项目", onClick: () => setCreateDrawerOpen(true), icon: Plus }] : []),
                    ...(canOpenCustomers ? [{ label: "关联客户底盘", onClick: () => navigate("crm", "/crm/customers"), icon: UsersRound, secondary: true }] : [])
                  ]}
                />
              )}
            </Table>
            <MasterPagination
              currentPage={safeCurrentPage}
              totalPages={totalPages}
              totalItems={totalRows}
              pageSize={CRM_PROJECT_PAGE_SIZE}
              rangeStart={rangeStart}
              rangeEnd={rangeEnd}
              onPageChange={setCurrentPage}
            />
          </DataTableShell>
        </>
      ) : <Card className="p-6 text-sm font-bold text-slate-500">当前账号没有客户项目查看权限。</Card>}

      <AnimatePresence>
        {createDrawerOpen ? (
          <CreateCrmProjectDrawer
            key="create-crm-project"
            currentUser={currentUser}
            permissions={permissions}
            onClose={() => setCreateDrawerOpen(false)}
            onCreated={(approval) => {
              setCreateDrawerOpen(false);
              setMessage(`${crmProjectApprovalFeedback(approval)}，审批通过后会自动生成客户项目和任务底盘。`);
              setCurrentPage(1);
              void loadRows();
            }}
          />
        ) : null}
      </AnimatePresence>
    </>
  );
}

function CrmFilterInput({ label, value, onChange }: { label: string; value: string; onChange: (value: string) => void }) {
  return (
    <label className="crm-filter-label">
      <span className="crm-filter-label-text">{label}</span>
      <input
        value={value}
        onChange={(event) => onChange(event.target.value.replace(/[^\d]/g, ""))}
        inputMode="numeric"
        className="project-input-sm min-w-[92px]"
      />
    </label>
  );
}

function CrmDateFilterInput({ label, value, onChange }: { label: string; value: string; onChange: (value: string) => void }) {
  return (
    <label className="crm-filter-label min-w-[168px]">
      <span className="crm-filter-label-text">{label}</span>
      <input
        type="date"
        value={value}
        onChange={(event) => onChange(event.target.value)}
        className="project-input-sm min-w-[132px]"
      />
    </label>
  );
}

function CrmWorkItemsPanel({ permissions, navigate }: { permissions: PermissionCode[]; navigate: (page: Page, path?: string) => void }) {
  const canView = hasPermission(permissions, "crm_issue.view");
  const canOpenTasks = canAccessCrmPath("/crm/tasks", permissions);
  const [pageData, setPageData] = useState<{ items: WorkItemRow[]; total: number; limit: number; offset: number } | null>(null);
  const [query, setQuery] = useState(() => initialQueryParam("q"));
  const [projectId, setProjectId] = useState(() => initialQueryParam("project_id"));
  const [statusValue, setStatusValue] = useState(() => initialQueryParam("status_value"));
  const [priority, setPriority] = useState(() => initialQueryParam("priority"));
  const [openOnly, setOpenOnly] = useState(() => initialQueryParam("status_value") === "");
  const [currentPage, setCurrentPage] = useState(1);
  const [selectedItem, setSelectedItem] = useState<WorkItemRow | null>(null);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");
  const initialItemIdRef = useRef<number | null>(Number.parseInt(initialQueryParam("item_id"), 10) || null);

  const totalRows = pageData?.total ?? 0;
  const totalPages = Math.max(1, Math.ceil(totalRows / CRM_WORK_ITEM_PAGE_SIZE));
  const safeCurrentPage = Math.min(currentPage, totalPages);
  const offset = (safeCurrentPage - 1) * CRM_WORK_ITEM_PAGE_SIZE;
  const rangeStart = totalRows === 0 ? 0 : offset + 1;
  const rangeEnd = Math.min(offset + CRM_WORK_ITEM_PAGE_SIZE, totalRows);
  const rows = pageData?.items ?? [];
  const pageStats = {
    open: rows.filter((row) => row.status === "open").length,
    processing: rows.filter((row) => row.status === "processing").length,
    urgent: rows.filter((row) => row.priority === "urgent" || row.priority === "high").length,
    closed: rows.filter((row) => row.status === "resolved" || row.status === "closed").length
  };

  const loadRows = async () => {
    if (!canView) {
      setPageData(null);
      return;
    }
    setLoading(true);
    setMessage("");
    try {
      const nextPage = await workItemsPage({
        q: query,
        project_id: numericFilterValue(projectId),
        status_value: statusValue,
        priority,
        open_only: openOnly,
        limit: CRM_WORK_ITEM_PAGE_SIZE,
        offset
      });
      setPageData(nextPage);
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "待支持事项加载失败");
      setPageData(null);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void loadRows();
  }, [canView, query, projectId, statusValue, priority, openOnly, offset]);

  useEffect(() => {
    if (currentPage !== safeCurrentPage) setCurrentPage(safeCurrentPage);
  }, [currentPage, safeCurrentPage]);

  useEffect(() => {
    const itemId = initialItemIdRef.current;
    if (!canView || !itemId) return;
    initialItemIdRef.current = null;
    void workItem(itemId).then(setSelectedItem).catch(() => undefined);
  }, [canView]);

  const resetFilters = () => {
    setCurrentPage(1);
    setQuery("");
    setProjectId("");
    setStatusValue("");
    setPriority("");
    setOpenOnly(true);
  };
  const showAllItems = () => {
    setCurrentPage(1);
    setQuery("");
    setStatusValue("");
    setPriority("");
    setOpenOnly(false);
  };
  const hasActiveWorkItemFilters = Boolean(query.trim() || projectId || statusValue || priority);

  if (!canView) {
    return <Card className="p-6 text-sm font-bold text-slate-500">当前账号没有待支持事项查看权限。</Card>;
  }

  return (
    <>
      <div className="mb-4 grid gap-3 md:grid-cols-2 xl:grid-cols-4">
        <CrmProjectMetricCard label="当前范围" value={totalRows} detail={`当前页 ${rows.length} 条`} icon={FileWarning} />
        <CrmProjectMetricCard label="待处理" value={pageStats.open} detail="open 状态事项" tone={pageStats.open > 0 ? "neutral" : "ok"} icon={Clock3} />
        <CrmProjectMetricCard label="处理中" value={pageStats.processing} detail="已进入处理流" tone={pageStats.processing > 0 ? "warn" : "neutral"} icon={RefreshCcw} />
        <CrmProjectMetricCard label="高优先" value={pageStats.urgent} detail={`已解决/关闭 ${pageStats.closed}`} tone={pageStats.urgent > 0 ? "bad" : "ok"} icon={Siren} />
      </div>

      <DataTableShell
        title="待支持 / 未闭环事项"
        description={loading ? "正在加载事项。" : message || "点击任意事项行，从右侧处理、分配、解决或关闭。"}
        meta={`${rangeStart}-${rangeEnd} / ${totalRows} 条记录`}
        toolbar={
          <DataToolbar onReset={resetFilters}>
            <ToolbarSearch value={query} onChange={(value) => { setCurrentPage(1); setQuery(value); }} placeholder="搜索事项编号、标题、客户或来源" />
            <CrmFilterInput label="项目ID" value={projectId} onChange={(value) => { setCurrentPage(1); setProjectId(value); }} />
            <ToolbarSelect
              value={statusValue}
              onChange={(value) => { setCurrentPage(1); setStatusValue(value); }}
              label="状态"
              options={[{ value: "", label: "全部状态" }, ...Object.entries(crmWorkItemStatusLabels).map(([value, label]) => ({ value, label }))]}
            />
            <ToolbarSelect
              value={priority}
              onChange={(value) => { setCurrentPage(1); setPriority(value); }}
              label="优先级"
              options={[{ value: "", label: "全部优先级" }, ...Object.entries(crmPriorityLabels).map(([value, label]) => ({ value, label }))]}
            />
            <label className="inline-flex h-9 items-center gap-2 rounded-lg border border-slate-200 bg-white px-3 text-xs font-black text-slate-600">
              <input
                type="checkbox"
                checked={openOnly}
                onChange={(event) => { setCurrentPage(1); setOpenOnly(event.target.checked); }}
                className="h-4 w-4 accent-primary"
              />
              仅未闭环
            </label>
          </DataToolbar>
        }
      >
        <Table headers={["事项", "支持内容", "优先级", "状态", "客户", "项目", "负责人", "到期", "更新时间"]}>
          {rows.length > 0 ? rows.map((item) => (
            <tr
              key={item.id}
              onClick={() => setSelectedItem(item)}
              className={`cursor-pointer transition hover:bg-primary-soft ${selectedItem?.id === item.id ? "bg-primary-soft" : ""}`}
            >
              <td>
                <strong className="block max-w-[280px] truncate text-slate-950">{workItemPrimaryTitle(item)}</strong>
                <span className="mt-1 block text-xs font-bold text-slate-400">{item.item_no} · {crmWorkItemTypeLabels[item.item_type] ?? item.item_type}</span>
                {item.needs_next_action ? <span className="mt-1 inline-flex rounded-md bg-amber-50 px-2 py-0.5 text-xs font-black text-amber-700">待补下一步</span> : null}
              </td>
              <td>
                <span className="block max-w-[260px] truncate text-sm font-bold text-slate-700">{workItemSupportDetail(item) || "未填写支持说明"}</span>
                <span className="mt-1 block text-xs font-bold text-slate-400">{workItemSupportTypeLabel(item)}</span>
              </td>
              <td><Badge tone={crmWorkItemPriorityTone(item.priority)}>{crmPriorityLabels[item.priority] ?? item.priority}</Badge></td>
              <td><Badge tone={crmWorkItemStatusTone(item.status)}>{crmWorkItemStatusLabels[item.status] ?? item.status}</Badge></td>
              <td>{workItemCustomerLabel(item)}</td>
              <td>{workItemProjectLabel(item)}</td>
              <td>{item.assignee_name || displayValue(item.assignee_user_id)}</td>
              <td>{formatDateTime(item.due_at)}</td>
              <td>{formatDateTime(item.updated_at)}</td>
            </tr>
          )) : (
            <CrmEmptyTableRow
              colSpan={9}
              icon={FileWarning}
              message={loading ? "正在加载待支持事项。" : hasActiveWorkItemFilters ? "没有符合筛选的待支持事项" : openOnly ? "暂无未闭环支持事项" : "暂无待支持事项"}
                  description={loading ? undefined : hasActiveWorkItemFilters ? "当前筛选没有命中事项，可以清空筛选或查看全部事项。" : "当跟进反馈需要业务协同、价格政策、资料处理或其他支持时，会在这里形成待处理事项。"}
              actions={loading ? [] : [
                ...(hasActiveWorkItemFilters ? [{ label: "清空筛选", onClick: resetFilters, icon: X, secondary: true }] : []),
                ...(openOnly ? [{ label: "查看全部事项", onClick: showAllItems, icon: FolderOpen, secondary: true }] : []),
                ...(canOpenTasks ? [{ label: "任务明细", onClick: () => navigate("crm", "/crm/tasks"), icon: ClipboardList }] : [])
              ]}
            />
          )}
        </Table>
        <MasterPagination
          currentPage={safeCurrentPage}
          totalPages={totalPages}
          totalItems={totalRows}
          pageSize={CRM_WORK_ITEM_PAGE_SIZE}
          rangeStart={rangeStart}
          rangeEnd={rangeEnd}
          onPageChange={setCurrentPage}
        />
      </DataTableShell>

      <AnimatePresence>
        {selectedItem ? (
          <WorkItemDetailDrawer
            key={selectedItem.id}
            item={selectedItem}
            permissions={permissions}
            onClose={() => setSelectedItem(null)}
            onChanged={(updated) => {
              setSelectedItem(updated);
              void loadRows();
            }}
          />
        ) : null}
      </AnimatePresence>
    </>
  );
}

function toDatetimeLocalInput(value?: string | null) {
  if (!value) return "";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "";
  return new Date(date.getTime() - date.getTimezoneOffset() * 60000).toISOString().slice(0, 16);
}

function fromDatetimeLocalInput(value: string) {
  if (!value) return null;
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? null : date.toISOString();
}

function workItemCustomerLabel(item: WorkItemRow) {
  return item.customer_name ? `${item.customer_name} / ${item.customer_code ?? "-"}` : displayValue(item.customer_code);
}

function workItemProjectLabel(item: WorkItemRow) {
  return item.project_name ? `${item.project_name}${item.project_id ? ` / ${item.project_id}` : ""}` : `项目 ${displayValue(item.project_id)}`;
}

function workItemSupportTypeLabel(item: WorkItemRow) {
  return item.support_type || crmWorkItemTypeLabels[item.item_type] || item.item_type;
}

function workItemSupportDetail(item: WorkItemRow) {
  return item.support_detail || item.detail || item.source_followup_summary || "";
}

function workItemPrimaryTitle(item: WorkItemRow) {
  const customer = item.customer_name || item.customer_code || "待支持事项";
  if (item.item_type === "crm_support_needed" || item.support_type) return `${customer} · ${workItemSupportTypeLabel(item)}`;
  return item.title;
}

function WorkItemDetailDrawer({
  item,
  permissions,
  onClose,
  onChanged
}: {
  item: WorkItemRow;
  permissions: PermissionCode[];
  onClose: () => void;
  onChanged: (item: WorkItemRow) => void;
}) {
  const canHandlePermission = hasPermission(permissions, "crm_issue.handle");
  const canClosePermission = hasPermission(permissions, "crm_issue.close");
  const [currentItem, setCurrentItem] = useState(item);
  const [title, setTitle] = useState(item.title);
  const [detail, setDetail] = useState(item.detail ?? "");
  const [priority, setPriority] = useState(item.priority);
  const [statusValue, setStatusValue] = useState(item.status === "closed" ? "resolved" : item.status);
  const [assigneeUserId, setAssigneeUserId] = useState(item.assignee_user_id ? String(item.assignee_user_id) : "");
  const [userRows, setUserRows] = useState<UserPublic[]>([]);
  const [dueAt, setDueAt] = useState(toDatetimeLocalInput(item.due_at));
  const [resolutionNote, setResolutionNote] = useState(item.resolution_note ?? "");
  const [saving, setSaving] = useState(false);
  const [message, setMessage] = useState("");
  const projectApprovalFrozen = !!currentItem.project_approval_frozen;
  const canHandle = canHandlePermission && !projectApprovalFrozen;
  const canClose = canClosePermission && !projectApprovalFrozen;

  useEffect(() => {
    setCurrentItem(item);
    setTitle(item.title);
    setDetail(item.detail ?? "");
    setPriority(item.priority);
    setStatusValue(item.status === "closed" ? "resolved" : item.status);
    setAssigneeUserId(item.assignee_user_id ? String(item.assignee_user_id) : "");
    setDueAt(toDatetimeLocalInput(item.due_at));
    setResolutionNote(item.resolution_note ?? "");
    setMessage("");
  }, [item]);

  useEffect(() => {
    if (!canHandle) return;
    void users("", "active").then(setUserRows).catch(() => setUserRows([]));
  }, [canHandle]);

  const commit = async (action: "save" | "processing" | "resolve" | "close") => {
    if (!canHandle && action !== "close") return;
    if (action === "close" && !canClose) return;
    setSaving(true);
    setMessage("");
    try {
      let updated: WorkItemRow;
      if (action === "resolve") {
        updated = await resolveWorkItem(currentItem.id, { resolution_note: cleanNullable(resolutionNote) });
      } else if (action === "close") {
        updated = await closeWorkItem(currentItem.id, { resolution_note: cleanNullable(resolutionNote) });
      } else {
        updated = await updateWorkItem(currentItem.id, {
          title: title.trim(),
          detail: cleanNullable(detail),
          priority,
          status: action === "processing" ? "processing" : statusValue,
          assignee_user_id: parseOptionalInt(assigneeUserId),
          due_at: fromDatetimeLocalInput(dueAt)
        });
      }
      setCurrentItem(updated);
      onChanged(updated);
      setMessage(action === "close" ? "事项已关闭。" : action === "resolve" ? "事项已标记为已解决。" : "事项已保存。");
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "事项处理失败");
    } finally {
      setSaving(false);
    }
  };

  const selectedAssignee = userRows.find((user) => String(user.id) === assigneeUserId);
  const assigneeLabel = selectedAssignee ? crmUserOptionLabel(selectedAssignee) : currentItem.assignee_name || displayValue(currentItem.assignee_user_id);
  const supportDetail = workItemSupportDetail(currentItem);

  return (
    <Drawer title="处理待支持事项" subtitle={`${currentItem.item_no} · ${crmWorkItemTypeLabels[currentItem.item_type] ?? currentItem.item_type}`} onClose={onClose}>
      <div className="grid gap-4 xl:grid-cols-[minmax(0,1fr)_320px]">
        <section className="grid gap-4">
          {projectApprovalFrozen ? (
            <div className="rounded-lg border border-amber-200 bg-amber-50 p-4" data-testid="work-item-project-frozen-banner">
              <div className="flex flex-wrap items-start justify-between gap-3">
                <div>
                  <strong className="block text-sm font-black text-amber-950">所属项目审批已撤回，事项当前只读</strong>
                  <p className="m-0 mt-1 whitespace-pre-wrap text-sm font-bold leading-6 text-amber-800">撤回原因：{currentItem.project_approval_withdrawn_reason || "未记录"}</p>
                </div>
                <Badge tone="warn">已冻结</Badge>
              </div>
            </div>
          ) : null}
          <div className="rounded-lg border border-slate-200 bg-white p-4">
            <div className="flex flex-wrap items-start justify-between gap-3">
              <div className="min-w-0">
                <p className="m-0 text-xs font-black uppercase tracking-[0.18em] text-primary">WORK ITEM</p>
                <h3 className="m-0 mt-1 text-2xl font-black leading-tight text-slate-950">{workItemPrimaryTitle(currentItem)}</h3>
                <p className="m-0 mt-2 text-sm font-bold text-slate-500">{workItemCustomerLabel(currentItem)} · {workItemProjectLabel(currentItem)} · 来源跟进</p>
              </div>
              <div className="flex flex-wrap gap-2">
                {currentItem.needs_next_action ? <Badge tone="warn">待补下一步</Badge> : null}
                <Badge tone={crmWorkItemPriorityTone(currentItem.priority)}>{crmPriorityLabels[currentItem.priority] ?? currentItem.priority}</Badge>
                <Badge tone={crmWorkItemStatusTone(currentItem.status)}>{crmWorkItemStatusLabels[currentItem.status] ?? currentItem.status}</Badge>
              </div>
            </div>
          </div>

          <div className="rounded-lg border border-blue-100 bg-blue-50/50 p-4">
            <div className="flex flex-wrap items-center justify-between gap-2">
              <h4 className="m-0 text-sm font-black text-slate-950">需要什么支持</h4>
              <Badge tone={currentItem.needs_next_action ? "warn" : "neutral"}>{workItemSupportTypeLabel(currentItem)}</Badge>
            </div>
            <div className="mt-3 grid gap-3 md:grid-cols-2">
              <div className="rounded-lg bg-white p-3">
                <p className="m-0 text-xs font-black text-slate-400">支持说明</p>
                <p className="m-0 mt-1 whitespace-pre-wrap text-sm font-bold leading-6 text-slate-700">{supportDetail || "一线未填写支持说明，请退回补充或电话确认。"}</p>
              </div>
              <div className="rounded-lg bg-white p-3">
                <p className="m-0 text-xs font-black text-slate-400">来源跟进摘要</p>
                <p className="m-0 mt-1 whitespace-pre-wrap text-sm font-bold leading-6 text-slate-700">{currentItem.source_followup_summary || "历史事项上下文不完整。"}</p>
              </div>
            </div>
            {currentItem.needs_next_action ? <p className="m-0 mt-3 rounded-lg border border-amber-200 bg-amber-50 px-3 py-2 text-sm font-black text-amber-700">该事项缺少下一步动作，处理时请补充后续处理安排。</p> : null}
          </div>

          <div className="rounded-lg border border-slate-200 bg-white p-4">
            <h4 className="m-0 text-sm font-black text-slate-950">处理信息</h4>
            <div className="mt-4 grid gap-3 md:grid-cols-2">
              <AccountField label="事项标题">
                <input value={title} disabled={!canHandle} onChange={(event) => setTitle(event.target.value)} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold disabled:bg-slate-50" />
              </AccountField>
              <AccountField label="负责人">
                {canHandle ? (
                  <select value={assigneeUserId} onChange={(event) => setAssigneeUserId(event.target.value)} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold disabled:bg-slate-50">
                    <option value="">{assigneeLabel === "-" ? "未分配" : assigneeLabel}</option>
                    {userRows.map((user) => <option key={user.id} value={user.id}>{crmUserOptionLabel(user)}</option>)}
                  </select>
                ) : (
                  <div className="flex h-10 items-center rounded-lg border border-slate-200 bg-slate-50 px-3 text-sm font-bold text-slate-600">{assigneeLabel}</div>
                )}
              </AccountField>
              <AccountField label="优先级">
                <select value={priority} disabled={!canHandle} onChange={(event) => setPriority(event.target.value)} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold disabled:bg-slate-50">
                  {Object.entries(crmPriorityLabels).map(([value, label]) => <option key={value} value={value}>{label}</option>)}
                </select>
              </AccountField>
              <AccountField label="处理状态">
                <select value={statusValue} disabled={!canHandle} onChange={(event) => setStatusValue(event.target.value)} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold disabled:bg-slate-50">
                  {["open", "processing", "resolved"].map((value) => <option key={value} value={value}>{crmWorkItemStatusLabels[value]}</option>)}
                </select>
              </AccountField>
              <AccountField label="到期时间">
                <input value={dueAt} disabled={!canHandle} type="datetime-local" onChange={(event) => setDueAt(event.target.value)} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold disabled:bg-slate-50" />
              </AccountField>
            </div>
            <div className="mt-3 grid gap-3">
              <AccountField label="事项说明">
                <textarea value={detail} disabled={!canHandle} onChange={(event) => setDetail(event.target.value)} rows={5} className="rounded-lg border border-slate-200 px-3 py-2 text-sm font-bold leading-6 disabled:bg-slate-50" />
              </AccountField>
              <AccountField label="处理说明">
                <textarea value={resolutionNote} disabled={!canHandle && !canClose} onChange={(event) => setResolutionNote(event.target.value)} rows={3} className="rounded-lg border border-slate-200 px-3 py-2 text-sm font-bold leading-6 disabled:bg-slate-50" />
              </AccountField>
            </div>
            {message ? <div className="mt-3 rounded-lg border border-slate-200 bg-slate-50 p-3 text-sm font-bold text-slate-600">{message}</div> : null}
          </div>
        </section>

        <aside className="grid content-start gap-3">
          <CustomerSideCard title="关联对象" icon={BriefcaseBusiness}>
            <CustomerSideRow label="客户" value={workItemCustomerLabel(currentItem)} />
            <CustomerSideRow label="项目" value={workItemProjectLabel(currentItem)} />
            <CustomerSideRow label="客户任务" value={currentItem.task_title || currentItem.task_no || "历史事项上下文不完整"} />
            <CustomerSideRow label="来源跟进" value={currentItem.source_type === "crm_followup" ? `跟进记录 ${displayValue(currentItem.source_id)}` : displayValue(currentItem.source_type)} />
          </CustomerSideCard>
          <CustomerSideCard title="处理轨迹" icon={History}>
            <CustomerSideRow label="创建时间" value={formatDateTime(currentItem.created_at)} />
            <CustomerSideRow label="更新时间" value={formatDateTime(currentItem.updated_at)} />
            <CustomerSideRow label="解决人" value={currentItem.resolved_by_name || displayValue(currentItem.resolved_by_user_id)} />
            <CustomerSideRow label="解决时间" value={formatDateTime(currentItem.resolved_at)} />
          </CustomerSideCard>
          <details className="rounded-lg border border-slate-200 bg-white p-3 text-xs font-bold text-slate-500">
            <summary className="cursor-pointer text-sm font-black text-slate-700">系统信息</summary>
            <div className="mt-3 grid gap-2">
              <CustomerSideRow label="客户编号" value={displayValue(currentItem.customer_code)} />
              <CustomerSideRow label="项目 ID" value={displayValue(currentItem.project_id)} />
              <CustomerSideRow label="资源类型" value={displayValue(currentItem.resource_type)} />
              <CustomerSideRow label="资源 ID" value={displayValue(currentItem.resource_id)} />
              <CustomerSideRow label="负责人 ID" value={displayValue(currentItem.assignee_user_id)} />
            </div>
          </details>
          <div className="grid gap-2 rounded-lg border border-slate-200 bg-white p-3">
            {canHandle ? <Button secondary disabled={saving || currentItem.status === "processing"} onClick={() => void commit("processing")}>标记处理中</Button> : null}
            {canHandle ? <Button secondary disabled={saving || currentItem.status === "closed"} onClick={() => void commit("save")}>保存调整</Button> : null}
            {canHandle ? <Button disabled={saving || currentItem.status === "closed" || currentItem.status === "resolved"} onClick={() => void commit("resolve")}>处理完成</Button> : null}
            {canClose ? <Button secondary disabled={saving || currentItem.status === "closed"} onClick={() => void commit("close")}>关闭事项</Button> : null}
            {!canHandle && !canClose ? <p className="m-0 rounded-lg bg-slate-50 p-3 text-sm font-bold text-slate-500">当前账号只能查看，不能处理或关闭事项。</p> : null}
          </div>
        </aside>
      </div>
    </Drawer>
  );
}

function CrmProjectMetricCard({
  label,
  value,
  detail,
  tone = "neutral",
  icon: Icon,
  active = false,
  onClick
}: {
  label: string;
  value: React.ReactNode;
  detail: string;
  tone?: ContextTone;
  icon: LucideIcon;
  active?: boolean;
  onClick?: () => void;
}) {
  const toneClass =
    tone === "ok"
      ? "border-emerald-200 bg-emerald-50"
      : tone === "warn"
        ? "border-amber-200 bg-amber-50"
        : tone === "bad"
          ? "border-red-200 bg-red-50"
          : "border-border bg-card";
  const content = (
    <>
      <div className="flex items-center justify-between gap-3">
        <span className="text-sm font-black text-muted-foreground">{label}</span>
        <span className="grid h-8 w-8 place-items-center rounded-md bg-card/80 text-primary ring-1 ring-border"><Icon className="h-4 w-4" /></span>
      </div>
      <strong className="mt-3 block text-2xl font-black text-foreground">{value}</strong>
      <span className="mt-1 block text-xs font-bold text-muted-foreground">{detail}</span>
    </>
  );
  const className = `w-full rounded-lg border p-4 text-left shadow-card transition ${toneClass} ${active ? "border-primary ring-1 ring-primary/20" : ""}`;
  if (onClick) {
    return <button type="button" onClick={onClick} aria-pressed={active} className={`${className} hover:-translate-y-0.5 hover:border-primary/50 hover:shadow-md`}>{content}</button>;
  }
  return <section className={className}>{content}</section>;
}

type CrmDraftTaskRow = {
  id: string;
  customer_code: string;
  customer_name_snapshot: string;
  executor_user_id: string;
  executor_employee_code: string;
  business_issue_point: string;
  round_target: string;
  feedback_due_at: string;
};

type CrmFormNotice = {
  tone: "ok" | "warn" | "bad" | "neutral";
  title: string;
  detail: string;
};

type CrmAssignmentMode = "salesperson" | "uniform" | "later";

const CRM_CUSTOMER_PICKER_PAGE_SIZE = 20;

function crmDraftRowId() {
  return `draft-${Date.now()}-${Math.random().toString(16).slice(2)}`;
}

function parseOptionalInt(value: string) {
  const trimmed = value.trim();
  if (!trimmed) return null;
  const parsed = Number.parseInt(trimmed, 10);
  return Number.isNaN(parsed) ? null : parsed;
}

function normalizeNullableText(value: string) {
  const trimmed = value.trim();
  return trimmed ? trimmed : null;
}

function crmProjectApprovalFeedback(approval: ApprovalRow) {
  const isDraft = approval.status === "draft";
  return `${isDraft ? "保存成功" : "提交成功"}：${isDraft ? "项目申请草稿" : "项目申请审批单"} ${approval.approval_no}`;
}

function selectedCustomerCategoryOptions(root: CategoryNode | null) {
  if (!root) return [{ id: "customers:root", label: "全部客户" }];
  const options: Array<{ id: string; label: string }> = [];
  const walk = (node: CategoryNode, depth: number) => {
    const prefix = depth === 0 ? "" : `${"　".repeat(Math.min(depth, 3))}└ `;
    options.push({ id: node.id, label: `${prefix}${node.label}（${node.count}）` });
    node.children.forEach((child) => walk(child, depth + 1));
  };
  walk(root, 0);
  return options;
}

function CreateCrmProjectDrawer({
  currentUser,
  permissions,
  onClose,
  onCreated
}: {
  currentUser: UserPublic;
  permissions: PermissionCode[];
  onClose: () => void;
  onCreated: (approval: ApprovalRow) => void;
}) {
  const [projectName, setProjectName] = useState("");
  const [projectType, setProjectType] = useState("客户项目");
  const [businessLine, setBusinessLine] = useState("");
  const [purpose, setPurpose] = useState("");
  const [customerScopeNote, setCustomerScopeNote] = useState("");
  const [startDate, setStartDate] = useState(new Date().toISOString().slice(0, 10));
  const [dueDate, setDueDate] = useState("");
  const [minimumAction, setMinimumAction] = useState("完成一次有效客户跟进并提交反馈");
  const [closureStandard, setClosureStandard] = useState("客户任务已闭环，负责人确认下一步动作");
  const [ownerUserId, setOwnerUserId] = useState("");
  const [landingApproverUserId, setLandingApproverUserId] = useState("");
  const [frontlineUserIds, setFrontlineUserIds] = useState<string[]>([]);
  const [progressCcUserIds, setProgressCcUserIds] = useState<string[]>([]);
  const [allowUnassignedTasks, setAllowUnassignedTasks] = useState(false);
  const [priority, setPriority] = useState("normal");
  const [customerQuery, setCustomerQuery] = useState("");
  const [customerPage, setCustomerPage] = useState(1);
  const [customerResult, setCustomerResult] = useState<{ items: MasterRow[]; total: number; limit: number; offset: number } | null>(null);
  const [customerHierarchy, setCustomerHierarchy] = useState<CategoryNode | null>(null);
  const [selectedCustomerCategoryId, setSelectedCustomerCategoryId] = useState("customers:root");
  const [customerLoading, setCustomerLoading] = useState(false);
  const [taskRows, setTaskRows] = useState<CrmDraftTaskRow[]>([]);
  const [userRows, setUserRows] = useState<UserPublic[]>([]);
  const [bulkDueAt, setBulkDueAt] = useState("");
  const [message, setMessage] = useState("选择客户并补齐执行人、问题点、轮次目标和反馈截止时间。");
  const [notice, setNotice] = useState<CrmFormNotice | null>(null);
  const [saving, setSaving] = useState(false);
  const [aiDraftBusy, setAiDraftBusy] = useState(false);
  const canGenerateAiDraft = hasPermission(permissions, "crm_insight.view") && hasPermission(permissions, "crm_insight.generate");

  const customerTotal = customerResult?.total ?? 0;
  const customerTotalPages = Math.max(1, Math.ceil(customerTotal / CRM_CUSTOMER_PICKER_PAGE_SIZE));
  const safeCustomerPage = Math.min(customerPage, customerTotalPages);
  const customerOffset = (safeCustomerPage - 1) * CRM_CUSTOMER_PICKER_PAGE_SIZE;
  const missingExecutorCount = taskRows.filter((row) => !row.executor_user_id.trim() && !row.executor_employee_code.trim()).length;
  const assignmentAllowsUnassigned = allowUnassignedTasks;
  const missingDueCount = taskRows.filter((row) => !row.feedback_due_at.trim()).length;
  const duplicateCustomerCount = taskRows.length - new Set(taskRows.map((row) => row.customer_code)).size;
  const duplicateCustomerCodes = useMemo(() => {
    const counts = new Map<string, number>();
    taskRows.forEach((row) => counts.set(row.customer_code, (counts.get(row.customer_code) ?? 0) + 1));
    return new Set(Array.from(counts.entries()).filter(([, count]) => count > 1).map(([code]) => code));
  }, [taskRows]);
  const selectedCustomerCategory = customerHierarchy ? findCategoryNode(customerHierarchy, selectedCustomerCategoryId) ?? customerHierarchy : null;
  const customerCategoryOptions = useMemo(() => selectedCustomerCategoryOptions(customerHierarchy), [customerHierarchy]);
  const userById = useMemo(() => new Map(userRows.map((user) => [String(user.id), user])), [userRows]);
  const frontlineUserSet = useMemo(() => new Set(frontlineUserIds), [frontlineUserIds]);
  const frontlineUsers = useMemo(() => userRows.filter((user) => frontlineUserSet.has(String(user.id))), [frontlineUserSet, userRows]);
  const applicantLabel = crmUserOptionLabel(currentUser);

  const userEmployeeCode = (userId: string) => userById.get(userId)?.employee_code ?? "";
  const executorFields = (userId: string) => ({
    executor_user_id: userId,
    executor_employee_code: userEmployeeCode(userId)
  });
  const showNotice = (tone: CrmFormNotice["tone"], title: string, detail: string) => {
    setMessage(detail);
    setNotice({ tone, title, detail });
  };
  const resolveInitialExecutorUserId = (customer: MasterRow) => {
    if (allowUnassignedTasks) return "";
    if (frontlineUserIds.length === 1) return frontlineUserIds[0];
    if (frontlineUserIds.length > 1) {
      const salespersonCode = String(customer.salesperson_employee_code ?? "").trim();
      const salespersonName = String(customer.salesperson_name ?? "").trim();
      const matchedUser = frontlineUsers.find((user) =>
        (salespersonCode && user.employee_code === salespersonCode) ||
        (salespersonName && (user.real_name === salespersonName || user.username === salespersonName))
      );
      if (matchedUser) return String(matchedUser.id);
    }
    return "";
  };
  const changeFrontlineUsers = (nextUserIds: string[]) => {
    const normalized = Array.from(new Set(nextUserIds));
    setFrontlineUserIds(normalized);
    setTaskRows((rows) => rows.map((row) => {
      if (normalized.length === 1) return { ...row, ...executorFields(normalized[0]) };
      if (row.executor_user_id && normalized.includes(row.executor_user_id)) return row;
      return { ...row, executor_user_id: "", executor_employee_code: "" };
    }));
    if (normalized.length === 1) {
      const user = userById.get(normalized[0]);
      setMessage(`已将客户任务默认分配给 ${user?.real_name || user?.username || "所选一线业务员"}。`);
    } else if (normalized.length > 1) {
      setMessage("已选择多名一线业务员，请在客户任务清单中逐行确认执行人。");
    } else {
      setMessage("请先选择一线业务员，或勾选稍后分配执行人。");
    }
  };

  useEffect(() => {
    if (!ownerUserId && currentUser.id) setOwnerUserId(String(currentUser.id));
  }, [currentUser.id, ownerUserId]);

  useEffect(() => {
    if (landingApproverUserId || userRows.length === 0) return;
    const defaultApprover = userRows.find((user) => user.username === "admin" || user.real_name === "施总");
    if (defaultApprover) setLandingApproverUserId(String(defaultApprover.id));
  }, [landingApproverUserId, userRows]);

  useEffect(() => {
    let cancelled = false;
    const loadCustomers = async () => {
      setCustomerLoading(true);
      try {
        const nextPage = await masterDataPage("customers", {
          q: customerQuery,
          limit: CRM_CUSTOMER_PICKER_PAGE_SIZE,
          offset: customerOffset,
          categoryPath: selectedCustomerCategory?.path ?? []
        });
        if (!cancelled) setCustomerResult(nextPage);
      } catch (error) {
        if (!cancelled) {
          setCustomerResult(null);
          setMessage(error instanceof Error ? error.message : "客户搜索失败");
        }
      } finally {
        if (!cancelled) setCustomerLoading(false);
      }
    };
    void loadCustomers();
    return () => {
      cancelled = true;
    };
  }, [customerQuery, customerOffset, selectedCustomerCategoryId, selectedCustomerCategory?.path.join("|")]);

  useEffect(() => {
    void masterHierarchy("customers").then((root) => setCustomerHierarchy(root as CategoryNode)).catch(() => setCustomerHierarchy(null));
  }, []);

  useEffect(() => {
    void users("", "active").then(setUserRows).catch(() => setUserRows([]));
  }, []);

  useEffect(() => {
    const rawDraft = window.sessionStorage.getItem("crm_project_ai_draft");
    if (!rawDraft) return;
    const textValue = (value: unknown) => (value === null || value === undefined ? "" : String(value));
    try {
      const draft = JSON.parse(rawDraft) as CrmAssistantProjectDraft;
      const project = draft.project ?? {};
      setProjectName(textValue(project.project_name));
      setProjectType(textValue(project.project_type) || "客户项目");
      setBusinessLine(textValue(project.business_line));
      setPurpose(textValue(project.purpose));
      setCustomerScopeNote(textValue(project.customer_scope_note));
      setStartDate(textValue(project.start_date) || new Date().toISOString().slice(0, 10));
      setDueDate(textValue(project.due_date));
      setMinimumAction(textValue(project.minimum_action) || "完成一次有效客户跟进并提交反馈");
      setClosureStandard(textValue(project.closure_standard) || "客户任务已闭环，负责人确认下一步动作");
      setPriority(draft.suggestions?.recommended_priority === "high" ? "high" : "normal");
      setMessage("已带入 AI 项目申请草稿。请继续选择客户、补齐执行人和反馈截止时间，再保存或提交审批。");
    } catch {
      setMessage("AI 项目申请草稿解析失败，请重新生成。");
    } finally {
      window.sessionStorage.removeItem("crm_project_ai_draft");
    }
  }, []);

  useEffect(() => {
    if (customerPage !== safeCustomerPage) setCustomerPage(safeCustomerPage);
  }, [customerPage, safeCustomerPage]);

  const addCustomer = (customer: MasterRow) => {
    const customerCode = displayValue(customer.customer_code);
    if (customerCode === "-") return;
    if (taskRows.some((row) => row.customer_code === customerCode)) {
      showNotice("bad", "添加失败", `客户 ${customerCode} 已在任务底盘中，不能重复选择。`);
      return;
    }
    const initialExecutorUserId = resolveInitialExecutorUserId(customer);
    const initialExecutorFields = executorFields(initialExecutorUserId);
    setTaskRows((rows) => [
      ...rows,
      {
        id: crmDraftRowId(),
        customer_code: customerCode,
        customer_name_snapshot: displayValue(customer.customer_name),
        ...initialExecutorFields,
        business_issue_point: "",
        round_target: "",
        feedback_due_at: bulkDueAt
      }
    ]);
    setMessage(`已加入客户 ${displayValue(customer.customer_name)}。`);
  };

  const addCurrentPageCustomers = () => {
    const candidates = customerResult?.items ?? [];
    let added = 0;
    setTaskRows((rows) => {
      const existingCodes = new Set(rows.map((row) => row.customer_code));
      const nextRows = [...rows];
      candidates.forEach((customer) => {
        const customerCode = displayValue(customer.customer_code);
        if (customerCode === "-" || existingCodes.has(customerCode)) return;
        existingCodes.add(customerCode);
        added += 1;
        const initialExecutorUserId = resolveInitialExecutorUserId(customer);
        nextRows.push({
          id: crmDraftRowId(),
          customer_code: customerCode,
          customer_name_snapshot: displayValue(customer.customer_name),
          ...executorFields(initialExecutorUserId),
          business_issue_point: "",
          round_target: "",
          feedback_due_at: bulkDueAt
        });
      });
      return nextRows;
    });
    setMessage(added > 0 ? `已批量加入当前页 ${added} 个客户。` : "当前页客户均已在任务底盘中。");
  };

  const updateTaskRow = (rowId: string, changes: Partial<CrmDraftTaskRow>) => {
    setTaskRows((rows) => rows.map((row) => row.id === rowId ? { ...row, ...changes } : row));
  };

  const updateTaskExecutor = (rowId: string, executorUserId: string) => {
    updateTaskRow(rowId, executorFields(executorUserId));
  };

  const removeTaskRow = (rowId: string) => {
    setTaskRows((rows) => rows.filter((row) => row.id !== rowId));
  };

  const applyBulkDueAt = () => {
    if (!bulkDueAt.trim()) {
      setMessage("请先选择批量反馈截止时间。");
      return;
    }
    setTaskRows((rows) => rows.map((row) => ({ ...row, feedback_due_at: bulkDueAt })));
    setMessage(`已批量更新 ${taskRows.length} 条客户任务截止时间。`);
  };

  const generateProjectAiDraft = async () => {
    if (!canGenerateAiDraft || aiDraftBusy) return;
    setAiDraftBusy(true);
    setNotice(null);
    try {
      const response = await generateCrmAssistantProjectDraft({
        project_name: normalizeNullableText(projectName),
        project_type: normalizeNullableText(projectType),
        business_line: normalizeNullableText(businessLine),
        purpose: normalizeNullableText(purpose),
        customer_scope_note: normalizeNullableText(customerScopeNote),
        target: normalizeNullableText(minimumAction),
        risk_note: null,
        due_days: dueDate ? Math.max(1, Math.ceil((new Date(dueDate).getTime() - Date.now()) / 86_400_000)) : 7,
        channel: "web"
      });
      const draft = response.draft;
      const project = draft.project ?? {};
      const text = (value: unknown) => value === null || value === undefined ? "" : String(value).trim();
      setProjectName((current) => current.trim() || text(project.project_name));
      setProjectType((current) => current.trim() || text(project.project_type) || "客户项目");
      setBusinessLine((current) => current.trim() || text(project.business_line));
      setPurpose((current) => current.trim() || text(project.purpose));
      setCustomerScopeNote((current) => current.trim() || text(project.customer_scope_note));
      setStartDate((current) => current.trim() || text(project.start_date) || new Date().toISOString().slice(0, 10));
      setDueDate((current) => current.trim() || text(project.due_date));
      setMinimumAction((current) => current.trim() || text(project.minimum_action));
      setClosureStandard((current) => current.trim() || text(project.closure_standard));
      if (priority === "normal" && draft.suggestions?.recommended_priority === "high") setPriority("high");
      showNotice("ok", "AI 草稿已生成", "只补全了当前表单中的空字段。请人工核对后再保存或提交审批。");
    } catch (error) {
      showNotice("bad", "AI 草稿生成失败", error instanceof Error ? error.message : "请稍后重试或继续手工填写。");
    } finally {
      setAiDraftBusy(false);
    }
  };

  const submitProject = async (submitImmediately: boolean) => {
    if (!projectName.trim()) {
      showNotice("bad", "提交失败", "请填写项目名称。");
      return;
    }
    if (!landingApproverUserId.trim()) {
      showNotice("bad", "提交失败", "请选择项目落地审批人。");
      return;
    }
    if (!ownerUserId.trim()) {
      showNotice("bad", "提交失败", "请选择细节审批人。跟进记录会流转给该人员审批；客户资料由具备权限的人员直接保存并留痕。");
      return;
    }
    if (!assignmentAllowsUnassigned && frontlineUserIds.length === 0) {
      showNotice("bad", "提交失败", "请选择至少 1 名一线业务员，或勾选“稍后分配客户任务执行人”。");
      return;
    }
    if (taskRows.length === 0) {
      showNotice("bad", "提交失败", "请至少从客户主数据中选择 1 个客户。");
      return;
    }
    if (duplicateCustomerCount > 0) {
      showNotice("bad", "提交失败", "客户任务底盘存在重复客户，请删除重复行后再提交。");
      return;
    }
    if (!assignmentAllowsUnassigned && missingExecutorCount > 0) {
      showNotice("bad", "提交失败", `仍有 ${missingExecutorCount} 条任务未分配执行人。请选择统一执行人、逐行补齐执行人，或改为“稍后分配”。`);
      return;
    }

    setSaving(true);
    showNotice("warn", submitImmediately ? "正在提交" : "正在保存", submitImmediately ? "正在提交项目申请审批。" : "正在保存项目申请草稿。");
    try {
      const participantIds = Array.from(new Set(
        frontlineUserIds
          .map((userId) => parseOptionalInt(userId))
          .filter((id): id is number => id !== null)
      ));
      const progressCcIds = Array.from(new Set(
        progressCcUserIds
          .map((userId) => parseOptionalInt(userId))
          .filter((id): id is number => id !== null)
      ));
      const approval = await createCrmProjectApprovalDraft({
        title: `客户项目立项：${projectName.trim()}`,
        description: normalizeNullableText(purpose),
        priority,
        submit: submitImmediately,
        project: {
          project_name: projectName.trim(),
          project_type: normalizeNullableText(projectType),
          business_line: normalizeNullableText(businessLine),
          purpose: normalizeNullableText(purpose),
          customer_scope_note: normalizeNullableText(customerScopeNote),
          applicant_user_id: currentUser.id,
          landing_approver_user_id: parseOptionalInt(landingApproverUserId),
          owner_user_id: parseOptionalInt(ownerUserId),
          project_manager_user_id: null,
          participant_user_ids: participantIds,
          progress_cc_user_ids: progressCcIds,
          assignment_mode: "flow_roles",
          allow_unassigned_tasks: assignmentAllowsUnassigned,
          start_date: normalizeNullableText(startDate),
          due_date: normalizeNullableText(dueDate),
          minimum_action: normalizeNullableText(minimumAction),
          closure_standard: normalizeNullableText(closureStandard),
          status: "submitted",
          approval_status: submitImmediately ? "submitted" : "draft"
        },
        tasks: taskRows.map((row) => ({
          customer_code: row.customer_code,
          executor_user_id: parseOptionalInt(row.executor_user_id),
          executor_employee_code: normalizeNullableText(row.executor_employee_code),
          business_issue_point: normalizeNullableText(row.business_issue_point),
          round_target: normalizeNullableText(row.round_target),
          feedback_due_at: normalizeNullableText(row.feedback_due_at),
          status: "not_started"
        }))
      });
      onCreated(approval);
    } catch (error) {
      showNotice("bad", submitImmediately ? "提交失败" : "保存失败", error instanceof Error ? error.message : "项目申请提交失败");
    } finally {
      setSaving(false);
    }
  };

  return (
    <Drawer title="新增客户项目" subtitle="提交项目申请审批，审批通过后自动生成项目和客户任务底盘。" onClose={onClose}>
      <form onSubmit={(event) => event.preventDefault()} className="grid gap-4">
        <section className="rounded-lg border border-slate-200 bg-muted p-4">
          <div className="flex flex-col gap-3 xl:flex-row xl:items-center xl:justify-between">
            <div className="min-w-0 flex-1">
              <p className="m-0 text-sm font-black text-slate-950">项目申请流程</p>
              <p className="m-0 mt-1 text-sm font-bold text-slate-500">{message}</p>
            </div>
            {canGenerateAiDraft ? <Button secondary disabled={aiDraftBusy || saving} onClick={() => void generateProjectAiDraft()}><Sparkles className="mr-1.5 h-4 w-4" />{aiDraftBusy ? "生成中" : "AI 生成草稿"}</Button> : null}
            <div className="grid gap-2 sm:grid-cols-4">
              <InsightMetric label="客户任务" value={taskRows.length} tone={taskRows.length > 0 ? "ok" : "warn"} />
              <InsightMetric label="未分配" value={missingExecutorCount} tone={missingExecutorCount > 0 && !assignmentAllowsUnassigned ? "bad" : "ok"} />
              <InsightMetric label="缺截止" value={missingDueCount} tone={missingDueCount > 0 ? "neutral" : "ok"} />
              <InsightMetric label="重复客户" value={duplicateCustomerCount} tone={duplicateCustomerCount > 0 ? "bad" : "ok"} />
            </div>
          </div>
          {notice ? <CrmFormNoticeBar notice={notice} onClose={() => setNotice(null)} /> : null}
        </section>

        <section className="rounded-lg border border-slate-200 bg-white p-4">
          <div className="mb-3 flex items-center gap-2">
            <span className="grid h-8 w-8 place-items-center rounded-md bg-primary-soft text-primary"><BriefcaseBusiness className="h-4 w-4" /></span>
            <h3 className="m-0 text-sm font-black text-slate-950">项目基本信息</h3>
          </div>
          <div className="grid gap-3 lg:grid-cols-2">
            <AccountField label="项目名称">
              <input value={projectName} onChange={(event) => setProjectName(event.target.value)} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold" />
            </AccountField>
            <AccountField label="项目类型">
              <input value={projectType} onChange={(event) => setProjectType(event.target.value)} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold" />
            </AccountField>
            <AccountField label="业务线">
              <input value={businessLine} onChange={(event) => setBusinessLine(event.target.value)} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold" />
            </AccountField>
            <AccountField label="客户范围说明">
              <input value={customerScopeNote} onChange={(event) => setCustomerScopeNote(event.target.value)} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold" />
            </AccountField>
            <AccountField label="开始日期">
              <input type="date" value={startDate} onChange={(event) => setStartDate(event.target.value)} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold" />
            </AccountField>
            <AccountField label="截止日期">
              <input type="date" value={dueDate} onChange={(event) => setDueDate(event.target.value)} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold" />
            </AccountField>
          </div>
          <div className="mt-3 grid gap-3">
            <AccountField label="项目目的">
              <textarea value={purpose} onChange={(event) => setPurpose(event.target.value)} rows={3} className="rounded-lg border border-slate-200 px-3 py-2 text-sm font-bold" />
            </AccountField>
            <div className="grid gap-3 lg:grid-cols-2">
              <AccountField label="最小动作">
                <textarea value={minimumAction} onChange={(event) => setMinimumAction(event.target.value)} rows={3} className="rounded-lg border border-slate-200 px-3 py-2 text-sm font-bold" />
              </AccountField>
              <AccountField label="闭环标准">
                <textarea value={closureStandard} onChange={(event) => setClosureStandard(event.target.value)} rows={3} className="rounded-lg border border-slate-200 px-3 py-2 text-sm font-bold" />
              </AccountField>
            </div>
          </div>
        </section>

        <section className="rounded-lg border border-slate-200 bg-white p-4">
          <div className="mb-3 flex flex-wrap items-center justify-between gap-3">
            <div className="flex items-center gap-2">
              <span className="grid h-8 w-8 place-items-center rounded-md bg-primary-soft text-primary"><UserCog className="h-4 w-4" /></span>
              <h3 className="m-0 text-sm font-black text-slate-950">流程式人员配置</h3>
            </div>
            <Badge tone={landingApproverUserId ? "ok" : "warn"}>{landingApproverUserId ? "流程已配置" : "待选择审批人"}</Badge>
          </div>
          <div className="grid gap-3">
            <CrmFlowStep
              index={1}
              title="申请人"
              detail="由当前登录账号自动带出"
              icon={UserRound}
            >
              <div className="flex min-h-10 items-center rounded-lg border border-slate-200 bg-slate-50 px-3 text-sm font-black text-slate-700">
                {applicantLabel}
              </div>
            </CrmFlowStep>
            <CrmFlowStep
              index={2}
              title="项目落地审批人"
              detail="项目申请提交后，审批单流转给该人员"
              icon={ShieldCheck}
            >
              <CrmUserPicker label="项目落地审批人" value={landingApproverUserId} onChange={setLandingApproverUserId} users={userRows} compact hideLabel />
            </CrmFlowStep>
            <CrmFlowStep
              index={3}
              title="一线业务员"
              detail="用于客户任务执行和项目可见范围；选 1 人时自动分配全部任务"
              icon={UsersRound}
            >
              <div className="grid gap-2">
                <CrmUserMultiSelect label="一线业务员" value={frontlineUserIds} onChange={changeFrontlineUsers} users={userRows} placeholder="请选择一线业务员" hideLabel />
                <label className="inline-flex items-center gap-2 rounded-lg border border-slate-200 bg-slate-50 px-3 py-2 text-xs font-black text-slate-600">
                  <input type="checkbox" checked={allowUnassignedTasks} onChange={(event) => setAllowUnassignedTasks(event.target.checked)} />
                  稍后分配客户任务执行人
                </label>
              </div>
            </CrmFlowStep>
            <CrmFlowStep
              index={4}
              title="细节审批人"
              detail="跟进记录由该人员审批；客户资料由具备权限的人员直接保存"
              icon={UserCheck}
            >
              <CrmUserPicker label="细节审批人" value={ownerUserId} onChange={setOwnerUserId} users={userRows} compact hideLabel />
            </CrmFlowStep>
            <CrmFlowStep
              index={5}
              title="项目进展抄送人"
              detail="只接收进展和查看项目，不参与审批处理"
              icon={Bell}
            >
              <CrmUserMultiSelect label="项目进展抄送人" value={progressCcUserIds} onChange={setProgressCcUserIds} users={userRows} placeholder="请选择抄送人" hideLabel />
            </CrmFlowStep>
            <div className="grid gap-3 rounded-lg border border-slate-200 bg-slate-50 p-3 md:grid-cols-2">
              <AccountField label="优先级">
                <select value={priority} onChange={(event) => setPriority(event.target.value)} className="h-10 rounded-lg border border-slate-200 bg-white px-3 text-sm font-bold">
                  <option value="normal">普通</option>
                  <option value="high">高</option>
                  <option value="urgent">紧急</option>
                </select>
              </AccountField>
              <div className="flex items-center rounded-lg bg-white px-3 text-xs font-bold leading-5 text-slate-500 ring-1 ring-slate-200">
                审批人负责处理流程；一线业务员负责客户任务；抄送人仅查看项目进展。
              </div>
            </div>
          </div>
        </section>

        <section className="grid gap-4 xl:grid-cols-[360px_minmax(0,1fr)]">
          <div className="rounded-lg border border-slate-200 bg-white p-4">
            <div className="mb-3 flex items-center justify-between gap-3">
              <div>
                <h3 className="m-0 text-sm font-black text-slate-950">客户搜索</h3>
                <p className="m-0 mt-1 text-xs font-bold text-slate-500">只能选择已存在的客户主数据。</p>
              </div>
              <Badge tone={customerLoading ? "warn" : "neutral"}>{customerLoading ? "加载中" : `${customerTotal} 条`}</Badge>
            </div>
            <div className="grid gap-2">
              <label className="grid gap-1.5 text-xs font-black text-slate-500">
                客户层级
                <select
                  value={selectedCustomerCategoryId}
                  onChange={(event) => {
                    setCustomerPage(1);
                    setSelectedCustomerCategoryId(event.target.value);
                  }}
                  className="h-10 rounded-lg border border-slate-200 bg-white px-3 text-sm font-bold text-slate-700"
                >
                  {customerCategoryOptions.map((option) => <option key={option.id} value={option.id}>{option.label}</option>)}
                </select>
              </label>
              <ToolbarSearch value={customerQuery} onChange={(value) => { setCustomerPage(1); setCustomerQuery(value); }} placeholder="搜索客户编号或名称" />
              <Button secondary onClick={addCurrentPageCustomers} disabled={(customerResult?.items ?? []).length === 0}>加入当前页未选客户</Button>
            </div>
            <div className="mt-3 grid gap-2">
              {(customerResult?.items ?? []).map((customer) => {
                const customerCode = displayValue(customer.customer_code);
                const selected = taskRows.some((row) => row.customer_code === customerCode);
                return (
                  <button
                    key={customerCode}
                    type="button"
                    disabled={selected}
                    onClick={() => addCustomer(customer)}
                    className={`rounded-lg border p-3 text-left transition ${selected ? "border-emerald-200 bg-emerald-50 text-emerald-700" : "border-slate-200 bg-white hover:border-primary/30 hover:bg-primary-soft"}`}
                  >
                    <strong className="block truncate text-sm">{displayValue(customer.customer_name)}</strong>
                    <span className="mt-1 block truncate text-xs font-bold text-slate-500">{customerCode} · {displayValue(customer.region)} · {displayValue(customer.customer_type)}</span>
                  </button>
                );
              })}
              {!customerLoading && (customerResult?.items ?? []).length === 0 ? <div className="rounded-lg bg-slate-50 p-3 text-sm font-bold text-slate-500">未找到客户。请先在主数据中导入或补充客户资料。</div> : null}
            </div>
            <div className="mt-3 flex items-center justify-between gap-2">
              <button type="button" disabled={safeCustomerPage <= 1} onClick={() => setCustomerPage((page) => Math.max(1, page - 1))} className="h-9 rounded-lg border border-slate-200 px-3 text-sm font-black disabled:opacity-40">上一页</button>
              <span className="text-xs font-black text-slate-500">{safeCustomerPage} / {customerTotalPages}</span>
              <button type="button" disabled={safeCustomerPage >= customerTotalPages} onClick={() => setCustomerPage((page) => Math.min(customerTotalPages, page + 1))} className="h-9 rounded-lg border border-slate-200 px-3 text-sm font-black disabled:opacity-40">下一页</button>
            </div>
          </div>

          <div className="min-w-0 rounded-lg border border-slate-200 bg-white">
            <div className="flex flex-col gap-3 border-b border-slate-200 p-4 xl:flex-row xl:items-end xl:justify-between">
              <div>
                <h3 className="m-0 text-sm font-black text-slate-950">客户任务清单</h3>
                <Badge tone={missingExecutorCount > 0 && !assignmentAllowsUnassigned ? "bad" : "neutral"}>{taskRows.length} 个客户</Badge>
              </div>
              <div className="flex flex-col gap-2 sm:flex-row sm:items-end">
                <AccountField label="批量截止时间">
                  <input type="datetime-local" value={bulkDueAt} onChange={(event) => setBulkDueAt(event.target.value)} className="h-10 w-full rounded-lg border border-slate-200 px-3 text-sm font-bold sm:w-64" />
                </AccountField>
                <Button secondary onClick={applyBulkDueAt} disabled={taskRows.length === 0}>应用截止</Button>
              </div>
            </div>
            <div className="project-table-card border-0 shadow-none">
              <div className="project-table-scroll">
                <UiTable className="project-table min-w-[760px]">
                  <TableHeader>
                    <TableRow>
                      <TableHead>客户</TableHead>
                      <TableHead>执行人</TableHead>
                      <TableHead>截止时间</TableHead>
                      <TableHead>操作</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {taskRows.length > 0 ? taskRows.map((row) => (
                      <TableRow key={row.id} className={`${!assignmentAllowsUnassigned && !row.executor_user_id.trim() && !row.executor_employee_code.trim() ? "bg-red-50/60" : ""} ${duplicateCustomerCodes.has(row.customer_code) ? "bg-amber-50/70" : ""}`}>
                        <TableCell>
                          <strong className="block text-slate-950">{row.customer_name_snapshot}</strong>
                          <span className="text-xs font-bold text-slate-400">{row.customer_code}</span>
                        </TableCell>
                        <TableCell>
                          <CrmUserPicker label="执行人" value={row.executor_user_id} onChange={(value) => updateTaskExecutor(row.id, value)} users={frontlineUsers} compact hideLabel disabled={frontlineUsers.length === 0} />
                        </TableCell>
                        <TableCell>
                          <input type="datetime-local" value={row.feedback_due_at} onChange={(event) => updateTaskRow(row.id, { feedback_due_at: event.target.value })} className="h-9 w-52 rounded-lg border border-slate-200 px-2 text-sm font-bold" />
                        </TableCell>
                        <TableCell>
                          <button type="button" onClick={() => removeTaskRow(row.id)} className="grid h-9 w-9 place-items-center rounded-lg border border-red-100 bg-red-50 text-red-600 hover:bg-red-100" aria-label="移除客户任务">
                            <Trash2 className="h-4 w-4" />
                          </button>
                        </TableCell>
                      </TableRow>
                    )) : (
                      <TableRow>
                        <TableCell colSpan={4} className="project-table-empty">请从左侧客户搜索结果中选择客户。</TableCell>
                      </TableRow>
                    )}
                  </TableBody>
                </UiTable>
              </div>
            </div>
          </div>
        </section>

        <section className="flex flex-col gap-3 rounded-lg border border-slate-200 bg-white p-4 md:flex-row md:items-center md:justify-between">
          <div className="text-sm font-bold text-slate-500">
            提交后生成审批单；审批通过时才会创建客户项目和任务底盘。
          </div>
          <div className="flex flex-wrap justify-end gap-2">
            <Button secondary onClick={onClose} disabled={saving}>关闭</Button>
            <Button secondary onClick={() => void submitProject(false)} disabled={saving}>{saving ? "处理中" : "保存草稿"}</Button>
            <Button onClick={() => void submitProject(true)} disabled={saving}>{saving ? "处理中" : "提交审批"}</Button>
          </div>
        </section>
      </form>
    </Drawer>
  );
}

function CrmUserPicker({
  label,
  value,
  onChange,
  users: userRows,
  compact = false,
  disabled = false,
  hideLabel = false
}: {
  label: string;
  value: string;
  onChange: (value: string) => void;
  users: UserPublic[];
  compact?: boolean;
  disabled?: boolean;
  hideLabel?: boolean;
}) {
  const control = userRows.length > 0 ? (
    <select value={value} disabled={disabled} onChange={(event) => onChange(event.target.value)} className="h-10 w-full rounded-lg border border-slate-200 bg-white px-3 text-sm font-bold disabled:cursor-not-allowed disabled:bg-slate-50 disabled:text-slate-400">
      <option value="">{compact ? "不设置" : "请选择"}</option>
      {userRows.map((user) => <option key={user.id} value={String(user.id)}>{crmUserOptionLabel(user)}</option>)}
    </select>
  ) : (
    <input value={value} disabled={disabled} onChange={(event) => onChange(event.target.value.replace(/[^\d]/g, ""))} inputMode="numeric" placeholder="账号 ID" className="h-10 w-full rounded-lg border border-slate-200 px-3 text-sm font-bold disabled:cursor-not-allowed disabled:bg-slate-50 disabled:text-slate-400" />
  );
  return hideLabel ? control : <AccountField label={label}>{control}</AccountField>;
}

function CrmFlowStep({
  index,
  title,
  detail,
  icon: Icon,
  children
}: {
  index: number;
  title: string;
  detail: string;
  icon: LucideIcon;
  children: ReactNode;
}) {
  return (
    <div className="grid gap-3 rounded-lg border border-slate-200 bg-white p-3 md:grid-cols-[220px_minmax(0,1fr)] md:items-center">
      <div className="flex min-w-0 items-start gap-3">
        <span className="grid h-9 w-9 shrink-0 place-items-center rounded-lg bg-primary-soft text-primary">
          <Icon className="h-4 w-4" />
        </span>
        <div className="min-w-0">
          <p className="m-0 text-sm font-black text-slate-950">{index}、{title}</p>
          <p className="m-0 mt-1 text-xs font-bold leading-5 text-slate-500">{detail}</p>
        </div>
      </div>
      <div className="min-w-0">{children}</div>
    </div>
  );
}

function CrmFormNoticeBar({ notice, onClose }: { notice: CrmFormNotice; onClose: () => void }) {
  const toneClass =
    notice.tone === "ok"
      ? "border-emerald-200 bg-emerald-50 text-emerald-700"
      : notice.tone === "bad"
        ? "border-red-200 bg-red-50 text-red-600"
        : notice.tone === "warn"
          ? "border-amber-200 bg-amber-50 text-amber-700"
          : "border-slate-200 bg-white text-slate-600";
  const Icon = notice.tone === "bad" ? FileWarning : notice.tone === "ok" ? ShieldCheck : Clock3;
  return (
    <div className={`mt-3 flex items-start justify-between gap-3 rounded-lg border px-3 py-3 shadow-sm ${toneClass}`} role={notice.tone === "bad" ? "alert" : "status"}>
      <div className="flex min-w-0 items-start gap-2">
        <Icon className="mt-0.5 h-4 w-4 shrink-0" />
        <div className="min-w-0">
          <strong className="block text-sm font-black">{notice.title}</strong>
          <span className="mt-0.5 block text-sm font-bold leading-5">{notice.detail}</span>
        </div>
      </div>
      <button type="button" onClick={onClose} className="grid h-7 w-7 shrink-0 place-items-center rounded-md bg-white/70 text-current ring-1 ring-current/10 hover:bg-white" aria-label="关闭提示">
        <X className="h-4 w-4" />
      </button>
    </div>
  );
}

function CrmAssignmentOption({
  checked,
  title,
  detail,
  onClick
}: {
  checked: boolean;
  title: string;
  detail: string;
  onClick: () => void;
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      className={`min-h-20 rounded-lg border px-3 py-3 text-left transition ${checked ? "border-primary bg-primary-soft text-primary shadow-sm" : "border-slate-200 bg-white text-slate-700 hover:border-primary/30 hover:bg-slate-50"}`}
    >
      <span className="flex items-center gap-2 text-sm font-black">
        <span className={`grid h-5 w-5 place-items-center rounded-full border ${checked ? "border-primary bg-primary text-white" : "border-slate-300 bg-white text-transparent"}`}>
          <span className="h-2 w-2 rounded-full bg-current" />
        </span>
        {title}
      </span>
      <span className={`mt-1 block text-xs font-bold leading-5 ${checked ? "text-primary/80" : "text-slate-400"}`}>{detail}</span>
    </button>
  );
}

function crmUserOptionLabel(user: UserPublic) {
  const displayName = user.real_name || user.username;
  const employeeCode = user.employee_code ? ` · ${user.employee_code}` : "";
  return `${displayName} / ${user.username}${employeeCode} · ${user.role}`;
}

function crmUserDisplayLabel(label?: string | null, id?: number | null) {
  if (label) return label;
  return id ? "账号信息缺失" : "-";
}

function crmUserListDisplay(labels?: string[] | null, ids?: number[] | null) {
  if (labels && labels.length > 0) return labels.join("、");
  if (ids && ids.length > 0) return `${ids.length} 人`;
  return "-";
}

function CrmUserMultiSelect({
  label,
  value,
  onChange,
  users: userRows,
  placeholder = "请选择参与执行人",
  hideLabel = false
}: {
  label: string;
  value: string[];
  onChange: (value: string[]) => void;
  users: UserPublic[];
  placeholder?: string;
  hideLabel?: boolean;
}) {
  const [query, setQuery] = useState("");
  const selectedSet = new Set(value);
  const normalizedQuery = query.trim().toLowerCase();
  const selectedUsers = value.map((id) => userRows.find((user) => String(user.id) === id)).filter(Boolean) as UserPublic[];
  const filteredUsers = userRows.filter((user) => crmUserOptionLabel(user).toLowerCase().includes(normalizedQuery));
  const toggleUser = (userId: string) => {
    onChange(selectedSet.has(userId) ? value.filter((id) => id !== userId) : [...value, userId]);
  };
  return (
    <div className="relative grid gap-1.5 text-xs font-black text-muted-foreground">
      {hideLabel ? null : <span>{label}</span>}
      <details className="group [&>summary::-webkit-details-marker]:hidden">
        <summary className="flex min-h-10 cursor-pointer list-none items-center justify-between gap-3 rounded-lg border border-slate-200 bg-white px-3 text-sm font-bold text-slate-700">
          <span className="min-w-0 truncate">{selectedUsers.length > 0 ? `已选 ${selectedUsers.length} 人` : placeholder}</span>
          <ChevronRight className="h-4 w-4 shrink-0 text-slate-400 transition group-open:rotate-90" />
        </summary>
        <div className="absolute z-30 mt-2 w-full overflow-hidden rounded-lg border border-slate-200 bg-white shadow-xl">
          <div className="border-b border-slate-100 p-2">
            <input
              value={query}
              onChange={(event) => setQuery(event.target.value)}
              placeholder="搜索姓名、账号、员工编号"
              className="h-9 w-full rounded-lg border border-slate-200 px-3 text-sm font-bold text-slate-700"
            />
          </div>
          <div className="max-h-64 overflow-auto p-2">
            {filteredUsers.length > 0 ? filteredUsers.map((user) => {
              const userId = String(user.id);
              const checked = selectedSet.has(userId);
              return (
                <label key={user.id} className={`flex cursor-pointer items-center gap-2 rounded-lg px-2 py-2 text-sm font-bold ${checked ? "bg-primary-soft text-primary" : "text-slate-700 hover:bg-slate-50"}`}>
                  <input type="checkbox" checked={checked} onChange={() => toggleUser(userId)} className="h-4 w-4 accent-primary" />
                  <span className="min-w-0 flex-1 truncate">{crmUserOptionLabel(user)}</span>
                </label>
              );
            }) : <div className="rounded-lg bg-slate-50 p-3 text-sm font-bold text-slate-400">没有匹配的账号</div>}
          </div>
        </div>
      </details>
      {selectedUsers.length > 0 ? (
        <div className="flex flex-wrap gap-1.5">
          {selectedUsers.slice(0, 4).map((user) => (
            <button
              key={user.id}
              type="button"
              onClick={() => toggleUser(String(user.id))}
              className="inline-flex items-center gap-1 rounded-md bg-primary-soft px-2 py-1 text-xs font-black text-primary"
            >
              {user.real_name || user.username}
              <X className="h-3 w-3" />
            </button>
          ))}
          {selectedUsers.length > 4 ? <span className="rounded-md bg-slate-100 px-2 py-1 text-xs font-black text-slate-500">+{selectedUsers.length - 4}</span> : null}
        </div>
      ) : null}
    </div>
  );
}

function CrmProjectDetailDrawer({
  project,
  permissions,
  onClose,
  onChanged
}: {
  project: CrmProjectRow;
  permissions: PermissionCode[];
  onClose: () => void;
  onChanged: () => void;
}) {
  const [context, setContext] = useState<CrmProjectContext | null>(null);
  const [activeTab, setActiveTab] = useState<CrmProjectTab>("overview");
  const [selectedTask, setSelectedTask] = useState<CrmTaskRow | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  const loadContext = async () => {
    setLoading(true);
    setError("");
    try {
      const nextContext = await crmProjectContext(project.id);
      setContext(nextContext);
    } catch (loadError) {
      setError(loadError instanceof Error ? loadError.message : "项目详情加载失败");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError("");
    void crmProjectContext(project.id)
      .then((nextContext) => {
        if (!cancelled) setContext(nextContext);
      })
      .catch((loadError) => {
        if (!cancelled) setError(loadError instanceof Error ? loadError.message : "项目详情加载失败");
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [project.id]);

  const currentProject = context?.project_detail.project ?? project;
  const projectApprovalFrozen = currentProject.approval_status === "need_supplement" && !!currentProject.approval_withdrawn_at;
  const detail = context?.project_detail;
  const closureSummary = detail?.closure_summary ?? null;
  const metrics: ContextDrawerMetric[] = [
    { label: "收口判断", value: closureSummary ? crmClosureStateLabels[closureSummary.closure_state] ?? closureSummary.closure_state : "读取中", detail: closureSummary?.closure_ready ? "已满足闭环口径" : "仍需处理阻塞项", tone: crmClosureStateTone(closureSummary?.closure_state), icon: ShieldCheck },
    { label: "客户任务", value: closureSummary?.task_total ?? currentProject.task_total ?? detail?.task_summary.total ?? 0, detail: `未闭环 ${closureSummary?.task_open ?? currentProject.task_open ?? detail?.task_summary.open ?? 0}`, tone: (closureSummary?.task_open ?? currentProject.task_open ?? 0) > 0 ? "warn" : "ok", icon: UsersRound },
    { label: "待支持", value: closureSummary?.support_open_count ?? currentProject.support_item_open ?? detail?.support_item_count ?? 0, detail: `阻塞 ${closureSummary?.task_blocked ?? currentProject.task_blocked ?? detail?.task_summary.blocked ?? 0}`, tone: crmRiskTone(currentProject), icon: FileWarning },
    { label: "待审批", value: closureSummary?.pending_approval_count ?? currentProject.pending_approval_count ?? 0, detail: crmApprovalStatusLabels[currentProject.approval_status] ?? currentProject.approval_status, tone: crmStatusTone(currentProject.approval_status), icon: KeyRound }
  ];
  const tabs: Array<ContextDrawerTab<CrmProjectTab>> = [
    { key: "overview", label: "概览" },
    { key: "closure", label: "闭环", count: closureSummary?.closure_ready ? 1 : 0 },
    { key: "related", label: "关联入口", count: (context?.tasks.length ?? currentProject.task_total ?? 0) + (context?.followups.length ?? 0) + (context?.work_items.length ?? currentProject.support_item_open ?? 0) }
  ];

  return (
    <Drawer title="客户项目详情" subtitle={`${currentProject.project_code} · ${currentProject.project_name}`} onClose={onClose}>
      <ContextDrawerFrame
        eyebrow="CRM PROJECT"
        title={currentProject.project_name}
        subtitle={`${displayValue(currentProject.project_type)} · ${displayValue(currentProject.business_line)} · ${formatDate(currentProject.start_date)} - ${formatDate(currentProject.due_date)}`}
        badges={[
          { label: crmProjectStatusLabels[currentProject.status] ?? currentProject.status, tone: crmStatusTone(currentProject.status) },
          { label: crmApprovalStatusLabels[currentProject.approval_status] ?? currentProject.approval_status, tone: crmStatusTone(currentProject.approval_status) }
        ]}
        metrics={metrics}
        tabs={tabs}
        activeTab={activeTab}
        onTabChange={setActiveTab}
        sidebar={
          <>
            <CustomerSideCard title="推进判断" icon={Clock3}>
              <CustomerSideRow label="下一步状态" value={displayValue(currentProject.next_step_status)} />
              <CustomerSideRow label="下一步动作" value={displayValue(currentProject.next_step_action)} multiline />
              <CustomerSideRow label="下次跟进" value={formatDateTime(currentProject.next_step_followup_at)} />
            </CustomerSideCard>
            <CustomerSideCard title="关联数据" icon={LayoutDashboard}>
              <CustomerSideRow label="客户任务" value={displayValue(context?.tasks.length ?? currentProject.task_total)} />
              <CustomerSideRow label="跟进记录" value={displayValue(context?.followups.length)} />
              <CustomerSideRow label="待支持项" value={displayValue(context?.work_items.length ?? currentProject.support_item_open)} />
              <CustomerSideRow label="审批记录" value={displayValue(context?.approvals.length ?? currentProject.pending_approval_count)} />
            </CustomerSideCard>
            {error ? <Card className="p-4 text-sm font-bold text-red-600">{error}</Card> : null}
          </>
        }
      >
        {projectApprovalFrozen ? (
          <div className="mb-4 rounded-lg border border-amber-200 bg-amber-50 p-4" data-testid="project-frozen-banner">
            <div className="flex flex-wrap items-start justify-between gap-3">
              <div>
                <strong className="block text-sm font-black text-amber-950">项目审批已撤回，当前冻结</strong>
                <p className="m-0 mt-1 whitespace-pre-wrap text-sm font-bold leading-6 text-amber-800">撤回原因：{currentProject.approval_withdrawn_reason || "未记录"}</p>
                <p className="m-0 mt-1 text-xs font-bold text-amber-700">等待申请人补充并重新通过审批后恢复业务操作。</p>
              </div>
              <Badge tone="warn">只读</Badge>
            </div>
          </div>
        ) : null}
        {loading ? <CrmDrawerLoading /> : null}
        {!loading && activeTab === "overview" ? <CrmProjectOverview project={currentProject} detail={detail} /> : null}
        {!loading && activeTab === "closure" ? <CrmProjectClosureView project={currentProject} detail={detail} context={context} onTaskClick={setSelectedTask} /> : null}
        {!loading && activeTab === "related" ? <CrmProjectRelatedSummary project={currentProject} detail={detail} context={context} permissions={permissions} /> : null}
      </ContextDrawerFrame>
      <AnimatePresence>
        {selectedTask ? (
          <CrmTaskDetailDrawer
            key={`project-drawer-task-detail-${selectedTask.id}`}
            task={selectedTask}
            permissions={permissions}
            onClose={() => setSelectedTask(null)}
            onChanged={async (updatedTask) => {
              setSelectedTask(updatedTask);
              setActiveTab("closure");
              await loadContext();
              onChanged();
            }}
          />
        ) : null}
      </AnimatePresence>
    </Drawer>
  );
}

function crmTaskRiskLabel(task: CrmTaskRow) {
  if (task.is_blocked) return "阻塞";
  if (task.need_boss_decision) return "管理决策";
  if (task.need_manager_support) return "主管协同";
  if (task.need_support) return "需支持";
  if (task.is_closed) return "已闭环";
  return "正常";
}

function crmTaskRiskTone(task: CrmTaskRow): ContextTone {
  if (task.is_blocked || task.need_boss_decision) return "bad";
  if (task.need_support || task.need_manager_support) return "warn";
  return task.is_closed ? "ok" : "neutral";
}

function isCrmTaskOverdue(task: CrmTaskRow) {
  if (!task.feedback_due_at || task.is_closed) return false;
  const dueAt = new Date(task.feedback_due_at);
  return !Number.isNaN(dueAt.getTime()) && dueAt.getTime() < Date.now();
}

function CrmTaskDetailDrawer({
  task,
  initialDetail,
  permissions,
  navigate,
  onStartFollowup,
  onClose,
  onChanged
}: {
  task: CrmTaskRow;
  initialDetail?: CrmTaskDetail;
  permissions: PermissionCode[];
  navigate?: (page: Page, path?: string) => void;
  onStartFollowup?: (task: CrmTaskRow) => void;
  onClose: () => void;
  onChanged?: (task: CrmTaskRow) => void | Promise<void>;
}) {
  const canEditPermission = hasPermission(permissions, "crm_task.edit");
  const canSubmitFollowupPermission = hasPermission(permissions, "crm_followup.submit");
  const canUseAssistant = hasAnyPermission(permissions, ["crm_insight.view", "crm_project.view"]);
  const canOpenProjects = canAccessCrmPath("/crm/projects", permissions);
  const canOpenIssues = canAccessCrmPath("/crm/issues", permissions);
  const [detail, setDetail] = useState<CrmTaskDetail | null>(initialDetail ?? null);
  const [currentTask, setCurrentTask] = useState<CrmTaskRow>(initialDetail?.task ?? task);
  const [activeTab, setActiveTab] = useState<CrmTaskDetailTab>("overview");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [message, setMessage] = useState("");
  const [saving, setSaving] = useState(false);
  const [editIssuePoint, setEditIssuePoint] = useState(task.business_issue_point ?? "");
  const [editRoundTarget, setEditRoundTarget] = useState(task.round_target ?? "");
  const [editFeedbackDueAt, setEditFeedbackDueAt] = useState(datetimeLocalInputValue(task.feedback_due_at));
  const [editStatus, setEditStatus] = useState(task.status);
  const [editMinimumActionDone, setEditMinimumActionDone] = useState(task.minimum_action_done);
  const [editNeedSupport, setEditNeedSupport] = useState(task.need_support);
  const [editNeedManagerSupport, setEditNeedManagerSupport] = useState(task.need_manager_support);
  const [editNeedBossDecision, setEditNeedBossDecision] = useState(task.need_boss_decision);
  const [editIsBlocked, setEditIsBlocked] = useState(task.is_blocked);
  const [editIsClosed, setEditIsClosed] = useState(task.is_closed);
  const [editBlockerReason, setEditBlockerReason] = useState(task.latest_blocker_reason ?? "");
  const [editBlockerNote, setEditBlockerNote] = useState(task.latest_blocker_note ?? "");
  const [aiLoading, setAiLoading] = useState(false);
  const [aiDraft, setAiDraft] = useState<{ text: string; source: string } | null>(null);
  const projectApprovalFrozen = detail?.project?.approval_status === "need_supplement" && !!detail.project.approval_withdrawn_at;
  const canEdit = canEditPermission && !projectApprovalFrozen;
  const canSubmitFollowup = canSubmitFollowupPermission && !projectApprovalFrozen;

  const loadDetail = async () => {
    setLoading(true);
    setError("");
    try {
      const nextDetail = await crmTaskDetail(task.id);
      setDetail(nextDetail);
      setCurrentTask(nextDetail.task);
    } catch (loadError) {
      setError(loadError instanceof Error ? loadError.message : "任务明细加载失败");
      setDetail(null);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (initialDetail?.task.id === task.id) {
      setDetail(initialDetail);
      setCurrentTask(initialDetail.task);
      setLoading(false);
      setError("");
      return;
    }
    let cancelled = false;
    setLoading(true);
    setError("");
    void crmTaskDetail(task.id)
      .then((nextDetail) => {
        if (!cancelled) {
          setDetail(nextDetail);
          setCurrentTask(nextDetail.task);
        }
      })
      .catch((loadError) => {
        if (!cancelled) {
          setError(loadError instanceof Error ? loadError.message : "任务明细加载失败");
          setDetail(null);
        }
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [initialDetail, task.id]);

  useEffect(() => {
    setEditIssuePoint(currentTask.business_issue_point ?? "");
    setEditRoundTarget(currentTask.round_target ?? "");
    setEditFeedbackDueAt(datetimeLocalInputValue(currentTask.feedback_due_at));
    setEditStatus(currentTask.status);
    setEditMinimumActionDone(currentTask.minimum_action_done);
    setEditNeedSupport(currentTask.need_support);
    setEditNeedManagerSupport(currentTask.need_manager_support);
    setEditNeedBossDecision(currentTask.need_boss_decision);
    setEditIsBlocked(currentTask.is_blocked);
    setEditIsClosed(currentTask.is_closed);
    setEditBlockerReason(currentTask.latest_blocker_reason ?? "");
    setEditBlockerNote(currentTask.latest_blocker_note ?? "");
  }, [currentTask]);

  const saveTask = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!canEdit) return;
    setSaving(true);
    setMessage("");
    setError("");
    try {
      const updatedTask = await updateCrmTask(currentTask.id, {
        business_issue_point: cleanNullable(editIssuePoint),
        round_target: cleanNullable(editRoundTarget),
        feedback_due_at: editFeedbackDueAt || null,
        status: editStatus,
        minimum_action_done: editMinimumActionDone,
        need_support: editNeedSupport,
        need_manager_support: false,
        need_boss_decision: false,
        is_blocked: editIsBlocked,
        is_closed: editIsClosed,
        latest_blocker_reason: cleanNullable(editBlockerReason),
        latest_blocker_note: cleanNullable(editBlockerNote)
      });
      setCurrentTask(updatedTask);
      setDetail((current) => current ? { ...current, task: updatedTask } : current);
      setMessage("任务明细已保存。");
      await onChanged?.(updatedTask);
      void loadDetail();
    } catch (saveError) {
      setError(saveError instanceof Error ? saveError.message : "任务明细保存失败");
    } finally {
      setSaving(false);
    }
  };

  const generateFollowupDraft = async () => {
    if (!canUseAssistant) return;
    setAiLoading(true);
    setMessage("");
    setError("");
    try {
      const result = await sendCrmAssistantMessage({
        operation: "followup.draft",
        channel: "frontline",
        context_type: "crm_task",
        context_id: String(currentTask.id),
        message: [
          `请为任务明细 ${currentTask.task_code} 生成一份一线跟进草稿。`,
          `客户：${currentTask.customer_name_snapshot || currentTask.customer_code}`,
          `问题点：${currentTask.business_issue_point || "-"}`,
          `本轮目标：${currentTask.round_target || "-"}`,
          "要求：语气真实、适合业务员复制后修改，不直接提交入库。"
        ].join("\n")
      });
      setAiDraft({ text: result.message.assistant_message, source: result.message.source });
      setMessage(result.message.source === "hermes" ? "Hermes 已生成跟进草稿。" : "已生成规则兜底草稿。");
    } catch (draftError) {
      setError(draftError instanceof Error ? draftError.message : "AI 跟进草稿生成失败");
    } finally {
      setAiLoading(false);
    }
  };

  const project = detail?.project;
  const dataUpdateApprovals = (detail?.approvals ?? []).filter((approval) => crmTaskDataUpdateApprovalTypes.has(approval.approval_type));
  const projectApprovals = (detail?.approvals ?? []).filter((approval) => approval.resource_type === "crm_project" || approval.approval_type.startsWith("crm_project_"));
  const followupApprovals = (detail?.approvals ?? []).filter((approval) => approval.approval_type === "crm_followup_submit");
  const supportApprovals = (detail?.approvals ?? []).filter((approval) => ["crm_task_extension", "crm_project_extension", "crm_project_close"].includes(approval.approval_type));
  const tabs: Array<ContextDrawerTab<CrmTaskDetailTab>> = [
    { key: "overview", label: "概览" },
    { key: "followups", label: "近期跟进", count: detail?.followups.length ?? 0 },
    { key: "issues", label: "待支持", count: detail?.work_items.length ?? 0 },
    { key: "approvals", label: "审批明细", count: detail?.approvals.length ?? 0 },
    ...(canEdit ? [{ key: "edit" as const, label: "编辑" }] : [])
  ];
  const overdue = isCrmTaskOverdue(currentTask);
  const metrics: ContextDrawerMetric[] = [
    { label: "明细状态", value: crmTaskStatusLabels[currentTask.status] ?? currentTask.status, detail: currentTask.is_closed ? "已闭环" : "推进中", tone: crmStatusTone(currentTask.status), icon: ClipboardList },
    { label: "风险", value: crmTaskRiskLabel(currentTask), detail: overdue ? "反馈已超期" : "风险标记", tone: overdue ? "bad" : crmTaskRiskTone(currentTask), icon: Siren },
    { label: "近期跟进", value: detail?.followups.length ?? "-", detail: `最近 ${formatDateTime(currentTask.last_followup_at)}`, tone: (detail?.followups.length ?? 0) > 0 ? "ok" : "neutral", icon: History },
    { label: "资料审批", value: currentTask.data_update_total ?? dataUpdateApprovals.length, detail: (currentTask.data_update_pending ?? 0) > 0 ? `待审 ${currentTask.data_update_pending}` : `最近 ${formatDateTime(currentTask.latest_data_update_at)}`, tone: (currentTask.data_update_pending ?? 0) > 0 ? "warn" : (currentTask.data_update_total ?? 0) > 0 ? "ok" : "neutral", icon: ShieldCheck },
    { label: "待支持", value: detail?.work_items.length ?? "-", detail: "当前任务相关事项", tone: (detail?.work_items.length ?? 0) > 0 ? "warn" : "ok", icon: FileWarning }
  ];

  return (
    <Drawer title="任务明细" subtitle={`${currentTask.customer_name_snapshot} · ${currentTask.task_code}`} onClose={onClose}>
      <ContextDrawerFrame
        eyebrow="CRM TASK"
        title={currentTask.customer_name_snapshot}
        subtitle={`${project?.project_name ? `${project.project_name} · ` : ""}${currentTask.task_code} · ${displayValue(currentTask.executor_name_snapshot ?? currentTask.executor_user_id)} · 截止 ${formatDateTime(currentTask.feedback_due_at)}`}
        badges={[
          { label: crmTaskStatusLabels[currentTask.status] ?? currentTask.status, tone: crmStatusTone(currentTask.status) },
          { label: crmTaskRiskLabel(currentTask), tone: overdue ? "bad" : crmTaskRiskTone(currentTask) }
        ]}
        metrics={metrics}
        tabs={tabs}
        activeTab={activeTab}
        onTabChange={setActiveTab}
        sidebar={
          <>
            <CustomerSideCard title="所属项目" icon={BriefcaseBusiness}>
              <CustomerSideRow label="项目" value={displayValue(project?.project_name)} />
              <CustomerSideRow label="项目编号" value={displayValue(project?.project_code)} />
              <CustomerSideRow label="项目状态" value={project ? crmProjectStatusLabels[project.status] ?? project.status : "-"} />
              <CustomerSideRow label="项目落地审批人" value={crmUserDisplayLabel(project?.landing_approver_user_label, project?.landing_approver_user_id)} />
              <CustomerSideRow label="细节审批人" value={crmUserDisplayLabel(project?.owner_user_label, project?.owner_user_id)} />
              {navigate && project && canOpenProjects ? (
                <Button secondary onClick={() => navigate("crm", `/crm/projects/${project.id}`)}>打开项目完整页</Button>
              ) : null}
            </CustomerSideCard>
            <CustomerSideCard title="负责人判断" icon={Clock3}>
              <CustomerSideRow label="下一步状态" value={displayValue(currentTask.latest_owner_next_status)} />
              <CustomerSideRow label="下一步动作" value={displayValue(currentTask.latest_owner_next_action)} multiline />
              <CustomerSideRow label="下次跟进" value={formatDateTime(currentTask.latest_owner_next_followup_at)} />
            </CustomerSideCard>
            <CustomerSideCard title="任务动作" icon={ShieldCheck}>
              <CustomerSideRow label="最小动作" value={currentTask.minimum_action_done ? "已完成" : "未完成"} />
              <CustomerSideRow label="最近反馈" value={formatDateTime(currentTask.last_followup_at)} />
              <div className="grid gap-2">
                {canSubmitFollowup && (onStartFollowup || navigate) && !currentTask.is_closed ? (
                  <DetailAction
                    icon={Phone}
                    label={onStartFollowup ? "进入跟进填写" : "打开任务明细"}
                    detail={onStartFollowup ? "带入当前任务" : "定位当前任务后填写"}
                    onClick={() => onStartFollowup ? onStartFollowup(currentTask) : navigate?.("crm", withQuery("/crm/tasks", { q: currentTask.task_code }))}
                  />
                ) : null}
                {canUseAssistant ? (
                  <DetailAction
                    icon={UserCog}
                    label={aiLoading ? "生成中" : "生成 AI 草稿"}
                    detail="生成后人工确认"
                    onClick={() => void generateFollowupDraft()}
                    disabled={aiLoading}
                  />
                ) : null}
                {canOpenIssues && navigate ? (
                  <DetailAction
                    icon={FileWarning}
                    label="查看支持事项"
                    detail="按项目和客户过滤"
                    onClick={() => navigate("crm", withQuery("/crm/issues", { project_id: currentTask.project_id, q: currentTask.customer_code }))}
                  />
                ) : null}
              </div>
            </CustomerSideCard>
            {canUseAssistant ? (
              <CustomerSideCard title="AI 跟进草稿" icon={UserCog}>
                <CustomerSideRow label="生成来源" value={aiDraft?.source ?? (aiLoading ? "生成中" : "未生成")} />
                {aiDraft ? (
                  <pre className="m-0 max-h-72 overflow-auto whitespace-pre-wrap rounded-lg border border-slate-200 bg-slate-50 p-3 text-xs font-bold leading-5 text-slate-700">{aiDraft.text}</pre>
                ) : (
                  <p className="m-0 rounded-lg border border-dashed border-slate-200 bg-slate-50 px-3 py-4 text-xs font-bold leading-5 text-slate-500">
                    点击“生成 AI 草稿”后，这里会显示可复制、可人工修改的跟进文本。
                  </p>
                )}
              </CustomerSideCard>
            ) : null}
          </>
        }
      >
        {projectApprovalFrozen ? (
          <Card className="mb-4 border-amber-200 bg-amber-50 p-4" data-testid="task-project-frozen-banner">
            <div className="flex flex-wrap items-start justify-between gap-3">
              <div>
                <strong className="block text-sm font-black text-amber-950">所属项目审批已撤回，任务当前只读</strong>
                <p className="m-0 mt-1 whitespace-pre-wrap text-sm font-bold leading-6 text-amber-800">撤回原因：{detail?.project?.approval_withdrawn_reason || "未记录"}</p>
                <p className="m-0 mt-1 text-xs font-bold text-amber-700">重新审批通过前不能编辑任务、填写跟进或处理关联事项。</p>
              </div>
              <Badge tone="warn">已冻结</Badge>
            </div>
          </Card>
        ) : null}
        {loading ? <CrmDrawerLoading /> : null}
        {error ? <Card className="mb-4 border-red-200 bg-red-50 p-4 text-sm font-bold text-red-600">{error}</Card> : null}
        {message ? <Card className="mb-4 border-emerald-200 bg-emerald-50 p-4 text-sm font-bold text-emerald-700">{message}</Card> : null}

        {!loading && activeTab === "overview" ? (
          <div className="grid gap-4 lg:grid-cols-2">
            {project ? (
              <CustomerSideCard title="所属项目与审批配置" icon={BriefcaseBusiness}>
                <CustomerSideRow label="项目名称" value={project.project_name} multiline />
                <CustomerSideRow label="项目编号" value={project.project_code} />
                <CustomerSideRow label="本次项目的目的" value={crmProjectPurposeText(project.purpose)} multiline />
                <CustomerSideRow label="项目类型" value={displayValue(project.project_type)} />
                <CustomerSideRow label="业务线" value={displayValue(project.business_line)} />
                <CustomerSideRow label="申请人" value={crmUserDisplayLabel(project.applicant_user_label, project.applicant_user_id)} />
                <CustomerSideRow label="项目落地审批人" value={crmUserDisplayLabel(project.landing_approver_user_label, project.landing_approver_user_id)} />
                <CustomerSideRow label="细节审批人" value={crmUserDisplayLabel(project.owner_user_label, project.owner_user_id)} />
                <CustomerSideRow label="一线业务员" value={crmUserListDisplay(project.participant_user_labels, project.participant_user_ids)} multiline />
                <CustomerSideRow label="项目进展抄送人" value={crmUserListDisplay(project.progress_cc_user_labels, project.progress_cc_user_ids)} multiline />
              </CustomerSideCard>
            ) : null}
            <CustomerSideCard title="客户与任务" icon={UsersRound}>
              <CustomerSideRow label="客户" value={currentTask.customer_name_snapshot} />
              <CustomerSideRow label="客户编号" value={currentTask.customer_code} />
              <CustomerSideRow label="任务编号" value={currentTask.task_code} />
              <CustomerSideRow label="执行人" value={displayValue(currentTask.executor_name_snapshot ?? currentTask.executor_user_id)} />
              <CustomerSideRow label="员工编号" value={displayValue(currentTask.executor_employee_code)} />
            </CustomerSideCard>
            <CustomerSideCard title="本轮推进口径" icon={ClipboardList}>
              <CustomerSideRow label="业务问题点" value={displayValue(currentTask.business_issue_point)} multiline />
              <CustomerSideRow label="轮次目标" value={displayValue(currentTask.round_target)} multiline />
              <CustomerSideRow label="反馈截止" value={formatDateTime(currentTask.feedback_due_at)} />
              <CustomerSideRow label="最小动作" value={displayValue(project?.minimum_action)} multiline />
              <CustomerSideRow label="闭环标准" value={displayValue(project?.closure_standard)} multiline />
            </CustomerSideCard>
            <CustomerSideCard title="风险与卡点" icon={FileWarning}>
              <CustomerSideRow label="风险状态" value={crmTaskRiskLabel(currentTask)} />
              <CustomerSideRow label="卡点原因" value={displayValue(currentTask.latest_blocker_reason)} />
              <CustomerSideRow label="卡点说明" value={displayValue(currentTask.latest_blocker_note)} multiline />
            </CustomerSideCard>
            <CustomerSideCard title="系统记录" icon={History}>
              <CustomerSideRow label="创建时间" value={formatDateTime(currentTask.created_at)} />
              <CustomerSideRow label="更新时间" value={formatDateTime(currentTask.updated_at)} />
              <CustomerSideRow label="最近跟进ID" value={displayValue(currentTask.latest_followup_id)} />
            </CustomerSideCard>
            <CustomerSideCard title="资料审批记录" icon={ShieldCheck}>
              <CustomerSideRow label="基本资料" value={crmTaskDataUpdateLabel(currentTask.customer_profile_approval_status)} />
              <CustomerSideRow label="经营资料" value={crmTaskDataUpdateLabel(currentTask.business_profile_approval_status)} />
              <CustomerSideRow label="最近资料提交" value={formatDateTime(currentTask.latest_data_update_at)} />
              <div className="mt-3 grid gap-2">
                {dataUpdateApprovals.length > 0 ? dataUpdateApprovals.map((approval) => (
                  <button
                    key={approval.id}
                    type="button"
                    onClick={() => navigate?.("crm", `/crm/work?approval_id=${approval.id}`)}
                    className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-left transition hover:border-primary hover:bg-primary-soft"
                  >
                    <strong className="block truncate text-xs font-black text-slate-950">{crmApprovalTypeLabel(approval.approval_type)}</strong>
                    <span className="mt-1 block text-xs font-bold text-slate-500">{approval.approval_no} · {crmTaskDataUpdateLabel(approval.status)}</span>
                  </button>
                )) : (
                  <p className="m-0 rounded-lg border border-dashed border-slate-200 bg-slate-50 px-3 py-4 text-xs font-bold text-slate-500">
                    暂无客户基本资料或经营资料审批记录。
                  </p>
                )}
              </div>
            </CustomerSideCard>
          </div>
        ) : null}

        {!loading && activeTab === "followups" ? (
          <CrmInlineTable rows={detail?.followups ?? []} columns={crmFollowupColumns} emptyMessage="暂无该任务的跟进记录。" />
        ) : null}
        {!loading && activeTab === "issues" ? (
          <CrmInlineTable rows={detail?.work_items ?? []} columns={crmWorkItemColumns} emptyMessage="暂无该任务的待支持事项。" />
        ) : null}
        {!loading && activeTab === "approvals" ? (
          <div className="grid gap-4">
            <CrmApprovalGroup title="项目审批明细" rows={projectApprovals} emptyMessage="暂无项目落地审批记录。" />
            <CrmApprovalGroup title="跟进审批明细" rows={followupApprovals} emptyMessage="暂无跟进审批记录。" />
            <CrmApprovalGroup title="客户基本资料更新记录 / 经营资料审批" rows={dataUpdateApprovals} emptyMessage="暂无资料更新记录。" />
            <CrmApprovalGroup title="待支持 / 延期 / 补充审批" rows={supportApprovals} emptyMessage="暂无支持、延期或补充审批。" />
          </div>
        ) : null}
        {!loading && activeTab === "edit" && canEdit ? (
          <form className="grid gap-4" onSubmit={saveTask}>
            <section className="rounded-lg border border-slate-200 bg-white p-4">
              <h3 className="m-0 text-sm font-black text-slate-950">推进口径</h3>
              <div className="mt-4 grid gap-3 md:grid-cols-2">
                <AccountField label="业务问题点">
                  <textarea value={editIssuePoint} onChange={(event) => setEditIssuePoint(event.target.value)} rows={4} className="rounded-lg border border-slate-200 px-3 py-2 text-sm font-bold" />
                </AccountField>
                <AccountField label="轮次目标">
                  <textarea value={editRoundTarget} onChange={(event) => setEditRoundTarget(event.target.value)} rows={4} className="rounded-lg border border-slate-200 px-3 py-2 text-sm font-bold" />
                </AccountField>
              </div>
              <div className="mt-3 grid gap-3 md:grid-cols-3">
                <AccountField label="反馈截止">
                  <input type="datetime-local" value={editFeedbackDueAt} onChange={(event) => setEditFeedbackDueAt(event.target.value)} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold" />
                </AccountField>
                <AccountField label="任务状态">
                  <select value={editStatus} onChange={(event) => setEditStatus(event.target.value)} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold">
                    {Object.entries(crmTaskStatusLabels).map(([value, label]) => <option key={value} value={value}>{label}</option>)}
                  </select>
                </AccountField>
                <AccountField label="卡点原因">
                  <input value={editBlockerReason} onChange={(event) => setEditBlockerReason(event.target.value)} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold" placeholder="价格、账期、竞品、需求不明确等" />
                </AccountField>
              </div>
              <AccountField label="卡点说明">
                <textarea value={editBlockerNote} onChange={(event) => setEditBlockerNote(event.target.value)} rows={3} className="mt-3 rounded-lg border border-slate-200 px-3 py-2 text-sm font-bold" />
              </AccountField>
            </section>
            <section className="rounded-lg border border-slate-200 bg-white p-4">
              <h3 className="m-0 text-sm font-black text-slate-950">状态标记</h3>
              <div className="mt-3 grid gap-2 md:grid-cols-3">
                <CrmCheck label="完成最小动作" checked={editMinimumActionDone} onChange={setEditMinimumActionDone} />
                <CrmCheck label="需要支持" checked={editNeedSupport} onChange={setEditNeedSupport} />
                <CrmCheck label="当前存在阻塞" checked={editIsBlocked} onChange={setEditIsBlocked} />
                <CrmCheck label="本任务已闭环" checked={editIsClosed} onChange={setEditIsClosed} />
              </div>
            </section>
            <div className="sticky bottom-0 flex justify-end gap-2 border-t border-slate-200 bg-white/95 py-4 backdrop-blur">
              <Button secondary onClick={() => setActiveTab("overview")}>取消</Button>
              <Button type="submit" disabled={saving}>{saving ? "保存中" : "保存任务"}</Button>
            </div>
          </form>
        ) : null}
      </ContextDrawerFrame>
    </Drawer>
  );
}

function datetimeLocalAfterDays(days: number) {
  const date = new Date();
  date.setDate(date.getDate() + days);
  date.setHours(18, 0, 0, 0);
  return new Date(date.getTime() - date.getTimezoneOffset() * 60000).toISOString().slice(0, 16);
}

function dateInputAfterDays(days: number) {
  const date = new Date();
  date.setDate(date.getDate() + days);
  return new Date(date.getTime() - date.getTimezoneOffset() * 60000).toISOString().slice(0, 10);
}

function datetimeLocalInputValue(value: unknown) {
  if (!value) return "";
  const date = new Date(String(value));
  if (Number.isNaN(date.getTime())) return "";
  return new Date(date.getTime() - date.getTimezoneOffset() * 60000).toISOString().slice(0, 16);
}

function cleanNullable(value: string) {
  const trimmed = value.trim();
  return trimmed ? trimmed : null;
}

function CrmFollowupSubmitDrawer({
  project,
  task,
  permissions,
  onClose,
  onSubmitted
}: {
  project: CrmProjectRow;
  task: CrmTaskRow;
  permissions: PermissionCode[];
  onClose: () => void;
  onSubmitted: (approval: ApprovalRow) => void | Promise<void>;
}) {
  const [followupDate, setFollowupDate] = useState(todayDateInput());
  const [method, setMethod] = useState("电话");
  const [frontlineAction, setFrontlineAction] = useState("");
  const [customerFeedback, setCustomerFeedback] = useState("");
  const [currentNeed, setCurrentNeed] = useState("");
  const [blockerReason, setBlockerReason] = useState("");
  const [blockerNote, setBlockerNote] = useState("");
  const [minimumActionDone, setMinimumActionDone] = useState(true);
  const [businessProfileUpdated, setBusinessProfileUpdated] = useState(false);
  const [customerProfileUpdated, setCustomerProfileUpdated] = useState(false);
  const [customerProfileApprovalId, setCustomerProfileApprovalId] = useState<number | null>(null);
  const [customerProfileNotice, setCustomerProfileNotice] = useState("");
  const [customerProfileEditing, setCustomerProfileEditing] = useState(false);
  const [businessProfileApprovalId, setBusinessProfileApprovalId] = useState<number | null>(null);
  const [businessProfileNotice, setBusinessProfileNotice] = useState("");
  const [businessProfileEditing, setBusinessProfileEditing] = useState(false);
  const [needSupport, setNeedSupport] = useState(false);
  const [supportType, setSupportType] = useState("业务协同");
  const [isClosed, setIsClosed] = useState(false);
  const [nextAction, setNextAction] = useState("");
  const [nextFollowupAt, setNextFollowupAt] = useState(datetimeLocalAfterDays(3));
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState("");
  const canViewCustomerProfile = hasPermission(permissions, "crm_customer_profile.view");
  const canSubmitCustomerProfile = hasPermission(permissions, "crm_customer_profile.submit");
  const canViewBusinessProfile = hasPermission(permissions, "crm_business_profile.view");
  const canSubmitBusinessProfile = hasPermission(permissions, "crm_business_profile.submit");

  const submitFollowup = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setError("");
    if (!frontlineAction.trim() || !customerFeedback.trim()) {
      setError("请至少填写执行动作和客户反馈。");
      return;
    }
    const hasSavedCustomerProfile = Boolean(customerProfileNotice) || task.customer_profile_approval_status === "synced";
    if (customerProfileUpdated && !hasSavedCustomerProfile && !customerProfileApprovalId) {
      setError("请先通过本页保存客户基本资料，或取消“完成客户基本资料更新”。");
      return;
    }
    const hasSavedBusinessProfile = Boolean(businessProfileNotice) || task.business_profile_approval_status === "synced";
    if (businessProfileUpdated && !hasSavedBusinessProfile && !businessProfileApprovalId) {
      setError("请先通过本页保存客户经营资料，或取消“完成客户经营资料更新”。");
      return;
    }
    if (needSupport && !currentNeed.trim()) {
      setError("勾选“需要支持”后，请填写支持事项说明。");
      return;
    }
    setSubmitting(true);
    try {
      const approval = await createCrmFollowupApprovalDraft({
        title: `跟进记录审核：${task.customer_name_snapshot}`,
        description: `客户任务 ${task.task_code} 的一线跟进记录。`,
        priority: needSupport ? "high" : "normal",
        submit: true,
        followup: {
          project_id: project.id,
          task_id: task.id,
          followup_date: followupDate || null,
          method: cleanNullable(method),
          frontline_action: cleanNullable(frontlineAction),
          customer_feedback: cleanNullable(customerFeedback),
          current_need: needSupport ? cleanNullable(currentNeed) : cleanNullable(currentNeed),
          need_type: needSupport ? cleanNullable(supportType) : null,
          blocker_reason: cleanNullable(blockerReason),
          blocker_note: cleanNullable(blockerNote),
          next_action: cleanNullable(nextAction),
          next_followup_at: nextFollowupAt || null,
          minimum_action_done: minimumActionDone,
          business_profile_updated: businessProfileUpdated,
          business_profile_approval_id: businessProfileApprovalId,
          customer_profile_updated: customerProfileUpdated,
          customer_profile_approval_id: customerProfileApprovalId,
          need_support: needSupport,
          need_manager_support: false,
          need_boss_decision: false,
          is_closed: isClosed,
          valid_feedback: true,
          review_status: "pending"
        }
      });
      await onSubmitted(approval);
    } catch (submitError) {
      setError(submitError instanceof Error ? submitError.message : "跟进记录提交失败");
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <>
      <Drawer title="提交跟进记录" subtitle={`${task.customer_name_snapshot} · ${task.task_code}`} onClose={onClose}>
        <form className="grid gap-4" onSubmit={submitFollowup}>
        <div className="grid gap-4 lg:grid-cols-3">
          <CustomerSideCard title="任务对象" icon={UsersRound}>
            <CustomerSideRow label="客户" value={task.customer_name_snapshot} />
            <CustomerSideRow label="客户编号" value={task.customer_code} />
            <CustomerSideRow label="任务状态" value={crmTaskStatusLabels[task.status] ?? task.status} />
            <CustomerSideRow label="反馈截止" value={formatDateTime(task.feedback_due_at)} />
            {canViewCustomerProfile ? (
              <Button secondary onClick={() => setCustomerProfileEditing(true)}>
                <Pencil className="mr-1.5 h-4 w-4" />
                编辑客户基本资料
              </Button>
            ) : null}
            {canViewBusinessProfile ? (
              <Button secondary onClick={() => setBusinessProfileEditing(true)}>
                <ClipboardList className="mr-1.5 h-4 w-4" />
                填写经营资料
              </Button>
            ) : null}
          </CustomerSideCard>
          <CustomerSideCard title="本轮目标" icon={ClipboardList}>
            <CustomerSideRow label="问题点" value={displayValue(task.business_issue_point)} multiline />
            <CustomerSideRow label="轮次目标" value={displayValue(task.round_target)} multiline />
            <CustomerSideRow label="最近跟进" value={formatDateTime(task.last_followup_at)} />
          </CustomerSideCard>
          <CustomerSideCard title="提交说明" icon={ShieldCheck}>
            <CustomerSideRow label="审核人" value="细节审批人" />
            <p className="m-0 mt-3 text-sm leading-6 text-slate-500">提交后会先生成审批单，审核通过后才写入正式跟进记录，并刷新客户任务状态。</p>
          </CustomerSideCard>
        </div>

        {customerProfileNotice ? <ContextNotice tone="ok" title="客户基本资料" description={customerProfileNotice} /> : null}
        {businessProfileNotice ? <ContextNotice tone="ok" title="客户经营资料" description={businessProfileNotice} /> : null}

        <section className="rounded-lg border border-slate-200 bg-white p-4">
          <h3 className="m-0 text-sm font-black text-slate-950">一线跟进记录</h3>
          <div className="mt-4 grid gap-3 md:grid-cols-3">
            <AccountField label="跟进日期">
              <input type="date" value={followupDate} onChange={(event) => setFollowupDate(event.target.value)} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold" />
            </AccountField>
            <AccountField label="跟进方式">
              <select value={method} onChange={(event) => setMethod(event.target.value)} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold">
                <option value="电话">电话</option>
                <option value="微信">微信</option>
                <option value="拜访">拜访</option>
                <option value="客户群">客户群</option>
                <option value="其他">其他</option>
              </select>
            </AccountField>
            <AccountField label="建议下次跟进">
              <input type="datetime-local" value={nextFollowupAt} onChange={(event) => setNextFollowupAt(event.target.value)} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold" />
            </AccountField>
          </div>
          <div className="mt-3 grid gap-3 md:grid-cols-2">
            <AccountField label="执行动作">
              <textarea value={frontlineAction} onChange={(event) => setFrontlineAction(event.target.value)} required rows={4} className="rounded-lg border border-slate-200 px-3 py-2 text-sm font-bold" placeholder="实际做了什么，例如电话确认、报价、发送资料、现场拜访。" />
            </AccountField>
            <AccountField label="客户反馈">
              <textarea value={customerFeedback} onChange={(event) => setCustomerFeedback(event.target.value)} required rows={4} className="rounded-lg border border-slate-200 px-3 py-2 text-sm font-bold" placeholder="保留客户原话或关键反馈。" />
            </AccountField>
            <AccountField label="当前需求">
              <textarea value={currentNeed} onChange={(event) => setCurrentNeed(event.target.value)} rows={3} className="rounded-lg border border-slate-200 px-3 py-2 text-sm font-bold" />
            </AccountField>
            <AccountField label="一线建议下一步">
              <textarea value={nextAction} onChange={(event) => setNextAction(event.target.value)} rows={3} className="rounded-lg border border-slate-200 px-3 py-2 text-sm font-bold" />
            </AccountField>
          </div>
          <div className="mt-3 grid gap-3 md:grid-cols-2">
            <AccountField label="卡点原因">
              <input value={blockerReason} onChange={(event) => setBlockerReason(event.target.value)} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold" placeholder="价格、账期、竞品、需求不明确等" />
            </AccountField>
            <AccountField label="卡点说明">
              <input value={blockerNote} onChange={(event) => setBlockerNote(event.target.value)} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold" />
            </AccountField>
          </div>
        </section>

        <section className="rounded-lg border border-slate-200 bg-white p-4">
          <h3 className="m-0 text-sm font-black text-slate-950">状态标记</h3>
          <div className="mt-3 grid gap-2 md:grid-cols-3">
            <CrmCheck label="完成最小动作" checked={minimumActionDone} onChange={setMinimumActionDone} />
            <CrmCheck label="完成客户经营资料更新" checked={businessProfileUpdated} onChange={setBusinessProfileUpdated} />
            <CrmCheck label="完成客户基本资料更新" checked={customerProfileUpdated} onChange={setCustomerProfileUpdated} />
            <CrmCheck label="需要支持" checked={needSupport} onChange={setNeedSupport} />
            <CrmCheck label="本任务已闭环" checked={isClosed} onChange={setIsClosed} />
          </div>
          {needSupport ? (
            <div className="mt-3 grid gap-3 md:grid-cols-[240px_minmax(0,1fr)]">
              <AccountField label="支持类型">
                <select value={supportType} onChange={(event) => setSupportType(event.target.value)} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold">
                  {["业务协同", "价格政策", "资料问题", "客户异常", "管理决策", "其他"].map((option) => <option key={option} value={option}>{option}</option>)}
                </select>
              </AccountField>
              <AccountField label="支持事项说明">
                <input value={currentNeed} onChange={(event) => setCurrentNeed(event.target.value)} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold" placeholder="请说明需要谁协助、协助什么、期望结果" />
              </AccountField>
            </div>
          ) : null}
        </section>

        {error ? <p className="m-0 rounded-lg bg-red-50 px-3 py-2 text-sm font-bold text-red-600">{error}</p> : null}

        <div className="sticky bottom-0 flex justify-end gap-2 border-t border-slate-200 bg-white/95 py-4 backdrop-blur">
          <Button secondary onClick={onClose}>关闭</Button>
          <Button type="submit" disabled={submitting}>{submitting ? "提交中" : "提交审核"}</Button>
        </div>
        </form>
      </Drawer>
      <AnimatePresence>
        {customerProfileEditing ? (
          <CrmCustomerProfileApprovalDrawer
            key={`followup-customer-profile-${task.customer_code}`}
            customerCode={task.customer_code}
            customerName={task.customer_name_snapshot}
            canSubmit={canSubmitCustomerProfile}
            onClose={() => setCustomerProfileEditing(false)}
            onSubmitted={async (result) => {
              setCustomerProfileApprovalId(null);
              setCustomerProfileUpdated(true);
              setCustomerProfileNotice(`客户基本资料已保存并同步主数据，更新 ${result.changed_fields.length} 项。`);
              setCustomerProfileEditing(false);
            }}
          />
        ) : null}
        {businessProfileEditing ? (
          <CrmBusinessProfileApprovalDrawer
            key={`followup-business-profile-${task.customer_code}`}
            customerCode={task.customer_code}
            customerName={task.customer_name_snapshot}
            canSubmit={canSubmitBusinessProfile}
            onClose={() => setBusinessProfileEditing(false)}
            onSubmitted={async (result) => {
              setBusinessProfileApprovalId(null);
              setBusinessProfileUpdated(true);
              setBusinessProfileNotice(`客户经营资料已保存并同步主数据，更新 ${result.changed_fields.length} 项。`);
              setBusinessProfileEditing(false);
            }}
          />
        ) : null}
      </AnimatePresence>
    </>
  );
}

function approvalFollowupPayload(approval: ApprovalRow) {
  const payload = approval.payload_json;
  if (!payload || Array.isArray(payload) || typeof payload !== "object") return null;
  const followup = (payload as { followup?: unknown }).followup;
  if (!followup || Array.isArray(followup) || typeof followup !== "object") return null;
  return followup as Record<string, unknown>;
}

function CrmFollowupReviewDrawer({
  approval,
  tasks,
  onClose,
  onReviewed
}: {
  approval: ApprovalRow;
  tasks: CrmTaskRow[];
  onClose: () => void;
  onReviewed: (message: string) => void | Promise<void>;
}) {
  const followupPayload = approvalFollowupPayload(approval);
  const taskId = Number(followupPayload?.task_id ?? 0);
  const task = tasks.find((row) => row.id === taskId);
  const [reviewMode, setReviewMode] = useState<"approve" | "supplement" | "reject">("approve");
  const [reviewResult, setReviewResult] = useState("通过");
  const [validFeedback, setValidFeedback] = useState(true);
  const [ownerNextStatus, setOwnerNextStatus] = useState("待再次联系");
  const [ownerNextAction, setOwnerNextAction] = useState("");
  const [ownerNextFollowupAt, setOwnerNextFollowupAt] = useState(datetimeLocalAfterDays(3));
  const [reviewNote, setReviewNote] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState("");

  const submitReview = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setError("");
    const trimmedReviewNote = reviewNote.trim();
    if (reviewMode !== "approve" && !trimmedReviewNote) {
      setError(reviewMode === "supplement" ? "请填写需要一线补充的具体内容。" : "请填写具体驳回原因。");
      return;
    }
    setSubmitting(true);
    try {
      if (reviewMode === "approve") {
        const detail = await approveApproval(approval.id, {
          comment: cleanNullable(reviewNote),
          result_json: {
            review_status: "approved",
            review_result: reviewResult,
            valid_feedback: validFeedback,
            review_note: cleanNullable(reviewNote),
            owner_next_status: cleanNullable(ownerNextStatus),
            owner_next_action: cleanNullable(ownerNextAction),
            owner_next_followup_at: ownerNextFollowupAt || null
          }
        });
        await onReviewed(`审批单 ${detail.approval.approval_no} 已审核通过，跟进记录已写入。`);
      } else if (reviewMode === "supplement") {
        const detail = await requestApprovalSupplement(approval.id, {
          comment: trimmedReviewNote
        });
        await onReviewed(`审批单 ${detail.approval.approval_no} 已退回补充，未写入正式跟进记录。`);
      } else {
        const detail = await rejectApproval(approval.id, {
          comment: trimmedReviewNote
        });
        await onReviewed(`审批单 ${detail.approval.approval_no} 已驳回，未写入正式跟进记录。`);
      }
    } catch (reviewError) {
      setError(reviewError instanceof Error ? reviewError.message : "跟进审核失败");
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <Drawer title="跟进审核" subtitle={`${approval.approval_no} · ${approval.title}`} onClose={onClose}>
      <form className="grid gap-4" onSubmit={submitReview}>
        <div className="grid gap-4 lg:grid-cols-3">
          <CustomerSideCard title="审批信息" icon={ShieldCheck}>
            <CustomerSideRow label="审批状态" value={crmApprovalStatusLabels[approval.status] ?? approval.status} />
            <CustomerSideRow label="申请人" value={approvalUserLabel(approval, "applicant")} />
            <CustomerSideRow label="处理人" value={approvalUserLabel(approval, "handler")} />
            <CustomerSideRow label="提交时间" value={formatDateTime(approval.submitted_at ?? approval.created_at)} />
          </CustomerSideCard>
          <CustomerSideCard title="客户任务" icon={UsersRound}>
            <CustomerSideRow label="客户" value={displayValue(task?.customer_name_snapshot)} />
            <CustomerSideRow label="客户编号" value={displayValue(task?.customer_code)} />
            <CustomerSideRow label="任务状态" value={task ? crmTaskStatusLabels[task.status] ?? task.status : "-"} />
            <CustomerSideRow label="轮次目标" value={displayValue(task?.round_target)} multiline />
          </CustomerSideCard>
          <CustomerSideCard title="一线事实摘要" icon={History}>
            <CustomerSideRow label="跟进方式" value={displayValue(followupPayload?.method)} />
            <CustomerSideRow label="执行动作" value={displayValue(followupPayload?.frontline_action)} multiline />
            <CustomerSideRow label="客户反馈" value={displayValue(followupPayload?.customer_feedback)} multiline />
            <CustomerSideRow label="当前需求" value={displayValue(followupPayload?.current_need)} multiline />
          </CustomerSideCard>
        </div>

        <section className="rounded-lg border border-slate-200 bg-white p-4">
          <h3 className="m-0 text-sm font-black text-slate-950">审核动作</h3>
          <div className="mt-4 grid gap-3 md:grid-cols-3">
            <AccountField label="处理结果">
              <select value={reviewMode} onChange={(event) => setReviewMode(event.target.value as "approve" | "supplement" | "reject")} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold">
                <option value="approve">审核通过并写入跟进</option>
                <option value="supplement">退回补充</option>
                <option value="reject">驳回</option>
              </select>
            </AccountField>
            <AccountField label="审核结果">
              <select value={reviewResult} onChange={(event) => setReviewResult(event.target.value)} disabled={reviewMode !== "approve"} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold disabled:bg-slate-50">
                <option value="通过">通过</option>
                <option value="调整方向">调整方向</option>
                <option value="转支持">转支持</option>
                <option value="暂停">暂停</option>
              </select>
            </AccountField>
            <AccountField label="负责人下次跟进">
              <input type="datetime-local" value={ownerNextFollowupAt} onChange={(event) => setOwnerNextFollowupAt(event.target.value)} disabled={reviewMode !== "approve"} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold disabled:bg-slate-50" />
            </AccountField>
          </div>
          <div className="mt-3 grid gap-3 md:grid-cols-2">
            <AccountField label="负责人下一步状态">
              <input value={ownerNextStatus} onChange={(event) => setOwnerNextStatus(event.target.value)} disabled={reviewMode !== "approve"} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold disabled:bg-slate-50" />
            </AccountField>
            <AccountField label="负责人下一步动作">
              <input value={ownerNextAction} onChange={(event) => setOwnerNextAction(event.target.value)} disabled={reviewMode !== "approve"} className="h-10 rounded-lg border border-slate-200 px-3 text-sm font-bold disabled:bg-slate-50" placeholder="例如补报价、约拜访、转主管协同。" />
            </AccountField>
          </div>
          <div className="mt-3">
            <CrmCheck label="有效反馈" checked={validFeedback} disabled={reviewMode !== "approve"} onChange={setValidFeedback} />
          </div>
          <AccountField label={reviewMode === "approve" ? "审核意见" : reviewMode === "supplement" ? "补充要求（必填）" : "驳回原因（必填）"}>
            <textarea value={reviewNote} onChange={(event) => setReviewNote(event.target.value)} rows={4} className="mt-3 rounded-lg border border-slate-200 px-3 py-2 text-sm font-bold" placeholder={reviewMode === "supplement" ? "说明需要一线补充什么。" : "记录负责人判断、下一步安排或驳回原因。"} />
          </AccountField>
        </section>

        {error ? <p className="m-0 rounded-lg bg-red-50 px-3 py-2 text-sm font-bold text-red-600">{error}</p> : null}

        <div className="sticky bottom-0 flex justify-end gap-2 border-t border-slate-200 bg-white/95 py-4 backdrop-blur">
          <Button secondary onClick={onClose}>关闭</Button>
          <Button type="submit" disabled={submitting}>{submitting ? "处理中" : "提交审核结果"}</Button>
        </div>
      </form>
    </Drawer>
  );
}

function CrmCheck({
  label,
  checked,
  disabled = false,
  onChange
}: {
  label: string;
  checked: boolean;
  disabled?: boolean;
  onChange: (checked: boolean) => void;
}) {
  return (
    <label className={`inline-flex items-center gap-2 rounded-lg border border-slate-200 px-3 py-2 text-sm font-black ${disabled ? "bg-slate-50 text-slate-400" : "bg-white text-slate-700"}`}>
      <input type="checkbox" checked={checked} disabled={disabled} onChange={(event) => onChange(event.target.checked)} />
      {label}
    </label>
  );
}

function CrmDrawerLoading() {
  return (
    <div className="grid gap-3">
      {Array.from({ length: 4 }).map((_, index) => <span key={index} className="h-14 animate-pulse rounded-lg bg-slate-100" />)}
    </div>
  );
}

function CrmProjectOverview({ project, detail }: { project: CrmProjectRow; detail?: CrmProjectContext["project_detail"] | null }) {
  return (
    <div className="grid gap-4 lg:grid-cols-2">
      <CustomerSideCard title="项目基础" icon={BriefcaseBusiness}>
        <CustomerSideRow label="项目编号" value={project.project_code} />
        <CustomerSideRow label="项目类型" value={displayValue(project.project_type)} />
        <CustomerSideRow label="业务线" value={displayValue(project.business_line)} />
        <CustomerSideRow label="申请人" value={crmUserDisplayLabel(project.applicant_user_label, project.applicant_user_id)} />
        <CustomerSideRow label="项目落地审批人" value={crmUserDisplayLabel(project.landing_approver_user_label, project.landing_approver_user_id)} />
        <CustomerSideRow label="细节审批人" value={crmUserDisplayLabel(project.owner_user_label, project.owner_user_id)} />
        <CustomerSideRow label="项目进展抄送人" value={crmUserListDisplay(project.progress_cc_user_labels, project.progress_cc_user_ids)} />
      </CustomerSideCard>
      <CustomerSideCard title="推进口径" icon={ClipboardList}>
        <CustomerSideRow label="客户范围" value={displayValue(project.customer_scope_note)} multiline />
        <CustomerSideRow label="最小动作" value={displayValue(project.minimum_action)} multiline />
        <CustomerSideRow label="闭环标准" value={displayValue(project.closure_standard)} multiline />
        <CustomerSideRow label="项目目的" value={displayValue(project.purpose)} multiline />
      </CustomerSideCard>
      <CustomerSideCard title="任务摘要" icon={UsersRound}>
        <CustomerSideRow label="任务总数" value={displayValue(detail?.task_summary.total ?? project.task_total)} />
        <CustomerSideRow label="已闭环" value={displayValue(detail?.task_summary.closed ?? project.task_closed)} />
        <CustomerSideRow label="未闭环" value={displayValue(detail?.task_summary.open ?? project.task_open)} />
        <CustomerSideRow label="需支持" value={displayValue(detail?.task_summary.need_support ?? project.task_need_support)} />
      </CustomerSideCard>
      <CustomerSideCard title="系统记录" icon={History}>
        <CustomerSideRow label="创建时间" value={formatDateTime(project.created_at)} />
        <CustomerSideRow label="更新时间" value={formatDateTime(project.updated_at)} />
        <CustomerSideRow label="最近跟进" value={formatDateTime(project.latest_followup_at)} />
        <CustomerSideRow label="当前审批ID" value={displayValue(project.current_approval_id)} />
      </CustomerSideCard>
    </div>
  );
}

function CrmProjectRelatedSummary({
  project,
  detail,
  context,
  permissions,
  navigate
}: {
  project: CrmProjectRow;
  detail?: CrmProjectContext["project_detail"] | null;
  context?: CrmProjectContext | null;
  permissions: PermissionCode[];
  navigate?: (page: Page, path?: string) => void;
}) {
  const taskTotal = detail?.task_summary.total ?? project.task_total ?? context?.tasks.length ?? 0;
  const taskOpen = detail?.task_summary.open ?? project.task_open ?? context?.tasks.filter((task) => !task.is_closed).length ?? 0;
  const followupTotal = context?.followups.length ?? (detail?.latest_followup ? 1 : 0);
  const approvalTotal = context?.approvals.length ?? project.pending_approval_count ?? 0;
  const pendingApproval = context?.approvals.filter((approval) => ["submitted", "under_review", "need_supplement"].includes(approval.status)).length ?? project.pending_approval_count ?? 0;
  const workItemTotal = context?.work_items.length ?? detail?.support_item_count ?? project.support_item_open ?? 0;
  const openWorkItem = context?.work_items.filter((item) => ["open", "processing"].includes(item.status)).length ?? project.support_item_open ?? 0;
  const reviewTotal = context?.reviews.length ?? 0;
  const reviewConfirmed = context?.reviews.filter((review) => review.status === "confirmed").length ?? 0;
  const canNavigate = Boolean(navigate);
  const openCrmPath = (path: string) => navigate?.("crm", path);

  const allCards: Array<{ title: string; value: string | number; detail: string; tone: ContextTone; icon: LucideIcon; path?: string }> = [
    { title: "任务明细", value: taskTotal, detail: `未闭环 ${taskOpen}`, tone: taskOpen > 0 ? "warn" : "ok", icon: ClipboardList, path: withQuery("/crm/tasks", { project_id: project.id }) },
    { title: "跟进记录", value: followupTotal, detail: `最近 ${formatDateTime(project.latest_followup_at)}`, tone: followupTotal > 0 ? "ok" : "neutral", icon: History, path: withQuery("/crm/followups", { project_id: project.id }) },
    { title: "审批处理", value: approvalTotal, detail: `待处理 ${pendingApproval}`, tone: pendingApproval > 0 ? "warn" : "ok", icon: ShieldCheck, path: "/crm/work" },
    { title: "待支持事项", value: workItemTotal, detail: `未闭环 ${openWorkItem}`, tone: openWorkItem > 0 ? "bad" : "ok", icon: FileWarning, path: withQuery("/crm/issues", { project_id: project.id }) },
    { title: "项目复盘", value: reviewTotal, detail: `已确认 ${reviewConfirmed}`, tone: reviewConfirmed > 0 ? "ok" : "warn", icon: Shield, path: "/crm/projects" },
    { title: "关联客户底盘", value: taskTotal, detail: "按项目客户任务形成客户底盘", tone: "neutral", icon: UsersRound, path: withQuery("/crm/customers", { q: project.project_name }) }
  ];
  const cards = allCards.filter((card) => !card.path || canAccessCrmPath(card.path, permissions));

  return (
    <div className="grid gap-4">
      <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">
        {cards.map((card) => {
          const Icon = card.icon;
          return (
            <button
              key={card.title}
              type="button"
              disabled={!canNavigate || !card.path}
              onClick={() => card.path ? openCrmPath(card.path) : undefined}
              className="group rounded-lg border border-slate-200 bg-white p-4 text-left transition hover:border-primary/40 hover:bg-primary-soft disabled:cursor-default disabled:hover:border-slate-200 disabled:hover:bg-white"
            >
              <div className="flex items-start justify-between gap-3">
                <span className="grid h-10 w-10 place-items-center rounded-lg bg-slate-100 text-slate-500 group-hover:bg-white group-hover:text-primary">
                  <Icon className="h-5 w-5" />
                </span>
                <Badge tone={card.tone}>{card.detail}</Badge>
              </div>
              <strong className="mt-4 block text-2xl font-black text-slate-950">{card.value}</strong>
              <span className="mt-1 block text-sm font-black text-slate-700">{card.title}</span>
            </button>
          );
        })}
      </div>

      <section className="rounded-lg border border-slate-200 bg-white">
        <div className="flex items-center justify-between gap-3 border-b border-slate-200 px-4 py-3">
          <h4 className="m-0 text-sm font-black text-slate-950">项目边界</h4>
          <Badge tone={crmRiskTone(project)}>{crmRiskTone(project) === "ok" ? "稳定" : "需关注"}</Badge>
        </div>
        <div className="grid gap-3 p-4 md:grid-cols-2">
          <CustomerSideRow label="细节审批人" value={crmUserDisplayLabel(project.owner_user_label, project.owner_user_id)} />
          <CustomerSideRow label="项目进展抄送人" value={crmUserListDisplay(project.progress_cc_user_labels, project.progress_cc_user_ids)} />
          <CustomerSideRow label="客户范围" value={displayValue(project.customer_scope_note)} multiline />
          <CustomerSideRow label="闭环标准" value={displayValue(project.closure_standard)} multiline />
        </div>
      </section>
    </div>
  );
}

function crmClosurePercent(done: number, total: number) {
  if (!total) return "-";
  return `${Math.round((done / total) * 100)}%`;
}

function CrmProjectClosureView({
  project,
  detail,
  context,
  onTaskClick
}: {
  project: CrmProjectRow;
  detail?: CrmProjectContext["project_detail"] | null;
  context?: CrmProjectContext | null;
  onTaskClick?: (task: CrmTaskRow) => void;
}) {
  const summary = detail?.closure_summary;
  const taskTotal = summary?.task_total ?? detail?.task_summary.total ?? project.task_total ?? 0;
  const taskClosed = summary?.task_closed ?? detail?.task_summary.closed ?? project.task_closed ?? 0;
  const taskOpen = summary?.task_open ?? detail?.task_summary.open ?? project.task_open ?? 0;
  const closureState = summary?.closure_state ?? "not_ready";
  const closureTone = crmClosureStateTone(closureState);
  const blockers: Array<{ label: string; value: number; detail: string; tone: ContextTone }> = [
    {
      label: "未闭环任务",
      value: taskOpen,
      detail: "客户任务仍需继续推进",
      tone: taskOpen > 0 ? "warn" : "ok"
    },
    {
      label: "未反馈客户",
      value: summary?.no_feedback_task_count ?? 0,
      detail: "还没有形成跟进记录",
      tone: (summary?.no_feedback_task_count ?? 0) > 0 ? "warn" : "ok"
    },
    {
      label: "超期任务",
      value: summary?.task_overdue ?? 0,
      detail: "已超过跟进截止时间",
      tone: (summary?.task_overdue ?? 0) > 0 ? "bad" : "ok"
    },
    {
      label: "待支持事项",
      value: summary?.support_open_count ?? detail?.support_item_count ?? project.support_item_open ?? 0,
      detail: "需要主管或管理层处理",
      tone: (summary?.support_open_count ?? detail?.support_item_count ?? project.support_item_open ?? 0) > 0 ? "bad" : "ok"
    },
    {
      label: "待审批",
      value: summary?.pending_approval_count ?? project.pending_approval_count ?? 0,
      detail: "项目或跟进审批未完成",
      tone: (summary?.pending_approval_count ?? project.pending_approval_count ?? 0) > 0 ? "warn" : "ok"
    },
    {
      label: "待复盘确认",
      value: summary && summary.review_confirmed > 0 ? 0 : 1,
      detail: summary && summary.review_confirmed > 0 ? "已有确认复盘" : "需要负责人确认收口",
      tone: summary && summary.review_confirmed > 0 ? "ok" : "warn"
    }
  ];
  const riskyTasks = (context?.tasks ?? [])
    .filter((task) => !task.is_closed || task.is_blocked || task.need_support || task.need_manager_support || task.need_boss_decision || isCrmTaskOverdue(task))
    .slice(0, 6);
  const blockerCount = blockers.filter((item) => item.value > 0).length;

  return (
    <div className="grid gap-4">
      <section className={`rounded-lg border px-4 py-4 ${closureTone === "ok" ? "border-emerald-200 bg-emerald-50" : closureTone === "bad" ? "border-red-200 bg-red-50" : closureTone === "warn" ? "border-amber-200 bg-amber-50" : "border-slate-200 bg-slate-50"}`}>
        <div className="flex flex-col gap-3 lg:flex-row lg:items-start lg:justify-between">
          <div className="min-w-0">
            <p className="m-0 text-xs font-black uppercase tracking-[0.18em] text-slate-500">CLOSURE VIEW</p>
            <h4 className="m-0 mt-1 text-xl font-black text-slate-950">项目闭环视图</h4>
            <p className="m-0 mt-2 text-sm font-bold leading-6 text-slate-600">{crmClosureStateHints[closureState] ?? crmClosureStateHints.not_ready}</p>
          </div>
          <Badge tone={closureTone}>{crmClosureStateLabels[closureState] ?? closureState}</Badge>
        </div>
      </section>

      <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
        <CrmClosureMetric title="任务闭环率" value={crmClosurePercent(taskClosed, taskTotal)} detail={`${taskClosed}/${taskTotal} 个客户任务`} tone={taskOpen > 0 ? "neutral" : "ok"} />
        <CrmClosureMetric title="有效反馈率" value={crmClosurePercent(summary?.valid_feedback_task_count ?? 0, taskTotal)} detail={`${summary?.valid_feedback_task_count ?? 0}/${taskTotal} 个客户`} tone={(summary?.valid_feedback_task_count ?? 0) < taskTotal ? "neutral" : "ok"} />
        <CrmClosureMetric title="支持处理" value={`${summary?.support_closed_count ?? 0}/${(summary?.support_closed_count ?? 0) + (summary?.support_open_count ?? 0)}`} detail="已关闭/全部支持事项" tone={(summary?.support_open_count ?? 0) > 0 ? "bad" : "ok"} />
        <CrmClosureMetric title="复盘确认" value={`${summary?.review_confirmed ?? 0}/${summary?.review_total ?? 0}`} detail={summary?.latest_review_conclusion ? `最近结论：${summary.latest_review_conclusion}` : "等待复盘沉淀"} tone={(summary?.review_confirmed ?? 0) > 0 ? "ok" : "warn"} />
      </div>

      <div className="grid gap-4 xl:grid-cols-[minmax(0,1fr)_320px]">
        <section className="rounded-lg border border-slate-200 bg-white">
          <div className="flex items-start justify-between gap-3 border-b border-slate-200 px-4 py-3">
            <div>
              <h4 className="m-0 text-sm font-black text-slate-950">收口阻塞项</h4>
              <p className="m-0 mt-1 text-xs font-bold text-slate-500">系统按任务、反馈、审批、支持和复盘口径自动归类。</p>
            </div>
            <Badge tone={blockerCount > 0 ? "neutral" : "ok"}>{blockerCount > 0 ? `${blockerCount} 项待处理` : "无阻塞"}</Badge>
          </div>
          <div className="grid gap-3 p-4 md:grid-cols-2">
            {blockers.map((item) => <CrmClosureBlocker key={item.label} {...item} />)}
          </div>
        </section>

        <section className="rounded-lg border border-slate-200 bg-white p-4">
          <div className="mb-3 flex items-center gap-2">
            <span className="grid h-8 w-8 place-items-center rounded-md bg-primary-soft text-primary"><ClipboardList className="h-4 w-4" /></span>
            <h4 className="m-0 text-sm font-black text-slate-950">收口判断</h4>
          </div>
          <div className="grid gap-2">
            <CustomerSideRow label="当前状态" value={crmClosureStateLabels[closureState] ?? closureState} />
            <CustomerSideRow label="最近复盘" value={summary?.latest_review_status ? crmProjectReviewStatusLabels[summary.latest_review_status] ?? summary.latest_review_status : "-"} />
            <CustomerSideRow label="任务总数" value={String(taskTotal)} />
            <CustomerSideRow label="有效反馈" value={String(summary?.valid_feedback_task_count ?? 0)} />
            <CustomerSideRow label="项目审批" value={crmApprovalStatusLabels[project.approval_status] ?? project.approval_status} />
          </div>
        </section>
      </div>

      <section className="grid gap-3">
        <div className="flex items-center justify-between gap-3">
          <div>
            <h4 className="m-0 text-sm font-black text-slate-950">待推进客户任务</h4>
            <p className="m-0 mt-1 text-xs font-bold text-slate-500">点击任务查看任务详情；跟进和支持处理进入独立页面。</p>
          </div>
          <Badge tone={riskyTasks.length > 0 ? "neutral" : "ok"}>{riskyTasks.length > 0 ? `${riskyTasks.length} 条` : "已清空"}</Badge>
        </div>
        <CrmInlineTable rows={riskyTasks} columns={crmTaskColumns} emptyMessage="当前展示范围内没有未闭环或风险任务。" onRowClick={onTaskClick} />
      </section>
    </div>
  );
}

function CrmClosureMetric({ title, value, detail, tone }: { title: string; value: string; detail: string; tone: ContextTone }) {
  const toneClass = tone === "ok" ? "border-emerald-200 bg-emerald-50" : tone === "bad" ? "border-red-200 bg-red-50" : tone === "warn" ? "border-amber-200 bg-amber-50" : "border-slate-200 bg-slate-50";
  return (
    <div className={`rounded-lg border px-4 py-3 ${toneClass}`}>
      <p className="m-0 text-xs font-black text-slate-500">{title}</p>
      <strong className="mt-2 block text-2xl font-black text-slate-950">{value}</strong>
      <span className="mt-1 block truncate text-xs font-bold text-slate-500">{detail}</span>
    </div>
  );
}

function CrmClosureBlocker({ label, value, detail, tone }: { label: string; value: number; detail: string; tone: ContextTone }) {
  return (
    <div className="rounded-lg border border-slate-200 bg-slate-50 px-3 py-3">
      <div className="flex items-center justify-between gap-3">
        <strong className="text-sm font-black text-slate-900">{label}</strong>
        <Badge tone={tone}>{value > 0 ? value : "OK"}</Badge>
      </div>
      <p className="m-0 mt-2 text-xs font-bold leading-5 text-slate-500">{detail}</p>
    </div>
  );
}

type CrmInlineColumn<T> = {
  label: string;
  render: (row: T) => React.ReactNode;
};

function CrmInlineTable<T>({
  rows,
  columns,
  emptyMessage,
  onRowClick
}: {
  rows: T[];
  columns: Array<CrmInlineColumn<T>>;
  emptyMessage: string;
  onRowClick?: (row: T) => void;
}) {
  return (
    <div className="overflow-hidden rounded-lg border border-slate-200 bg-white">
      <div className="overflow-auto">
        <UiTable className="min-w-[720px]">
          <TableHeader>
            <TableRow>{columns.map((column) => <TableHead key={column.label}>{column.label}</TableHead>)}</TableRow>
          </TableHeader>
          <TableBody>
            {rows.length > 0 ? rows.map((row, index) => (
              <TableRow
                key={String((row as { id?: unknown }).id ?? index)}
                onClick={onRowClick ? () => onRowClick(row) : undefined}
                className={onRowClick ? "cursor-pointer hover:bg-primary-soft" : undefined}
              >
                {columns.map((column) => <TableCell key={column.label}>{column.render(row)}</TableCell>)}
              </TableRow>
            )) : (
              <TableRow>
                <TableCell colSpan={columns.length} className="py-8 text-center text-sm font-bold text-slate-400">{emptyMessage}</TableCell>
              </TableRow>
            )}
          </TableBody>
        </UiTable>
      </div>
    </div>
  );
}

function crmApprovalCoreSummary(row: ApprovalRow) {
  const summary = row.business_summary;
  if (summary && typeof summary.core_content === "string" && summary.core_content.trim()) return summary.core_content;
  if (summary && typeof summary.change_summary === "string" && summary.change_summary.trim()) return summary.change_summary;
  if (row.description) return row.description;
  return row.title;
}

function crmApprovalChangeCount(row: ApprovalRow) {
  if (!["customer_profile_update", "customer_business_profile_update"].includes(row.approval_type)) return null;
  return approvalDiffItems(
    row,
    row.approval_type === "customer_business_profile_update" ? businessProfileApprovalLabels : customerProfileApprovalLabels,
    "profile",
    row.approval_type === "customer_business_profile_update" ? "before_business_profile" : "before_profile"
  ).length;
}

function CrmApprovalGroup({ title, rows, emptyMessage }: { title: string; rows: ApprovalRow[]; emptyMessage: string }) {
  return (
    <section className="overflow-hidden rounded-lg border border-slate-200 bg-white">
      <div className="flex items-center justify-between gap-3 border-b border-slate-200 px-4 py-3">
        <h4 className="m-0 text-sm font-black text-slate-950">{title}</h4>
        <Badge tone="neutral">{rows.length} 条</Badge>
      </div>
      {rows.length > 0 ? (
        <div className="overflow-x-auto">
          <table className="min-w-[920px] w-full border-collapse text-left text-sm">
            <thead className="bg-slate-50 text-xs font-black text-slate-500">
              <tr>
                <th className="px-4 py-3">审批</th>
                <th className="px-4 py-3">状态</th>
                <th className="px-4 py-3">申请人</th>
                <th className="px-4 py-3">处理人</th>
                <th className="px-4 py-3">核心内容</th>
                <th className="px-4 py-3">同步/变更</th>
                <th className="px-4 py-3">时间</th>
              </tr>
            </thead>
            <tbody>
              {rows.map((row) => {
                const changeCount = crmApprovalChangeCount(row);
                const sync = approvalSyncState(row);
                return (
                  <tr key={row.id} className="border-t border-slate-200 align-top">
                    <td className="px-4 py-3">
                      <strong className="block max-w-[220px] truncate text-slate-950">{crmApprovalTypeLabel(row.approval_type)}</strong>
                      <span className="mt-1 block text-xs font-bold text-slate-400">{row.approval_no}</span>
                    </td>
                    <td className="px-4 py-3"><Badge tone={crmStatusTone(row.status)}>{crmApprovalStatusLabels[row.status] ?? row.status}</Badge></td>
                    <td className="px-4 py-3">{approvalUserLabel(row, "applicant")}</td>
                    <td className="px-4 py-3">{approvalUserLabel(row, "handler")}</td>
                    <td className="px-4 py-3"><span className="line-clamp-2 max-w-[260px] whitespace-normal leading-5">{crmApprovalCoreSummary(row)}</span></td>
                    <td className="px-4 py-3">
                      {changeCount === null ? <span className="text-slate-400">-</span> : <Badge tone={sync.tone}>{changeCount} 项 · {sync.shortLabel}</Badge>}
                    </td>
                    <td className="px-4 py-3">{formatDateTime(row.reviewed_at ?? row.submitted_at ?? row.created_at)}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      ) : (
        <div className="px-4 py-8 text-center text-sm font-bold text-slate-400">{emptyMessage}</div>
      )}
    </section>
  );
}

const crmTaskColumns: Array<CrmInlineColumn<CrmTaskRow>> = [
  { label: "客户", render: (row) => <span><strong className="block">{row.customer_name_snapshot}</strong><span className="text-xs font-bold text-slate-400">{row.customer_code}</span></span> },
  { label: "问题点", render: (row) => <span className="line-clamp-2 max-w-[240px] whitespace-normal leading-5">{displayValue(row.business_issue_point)}</span> },
  { label: "轮次目标", render: (row) => <span className="line-clamp-2 max-w-[240px] whitespace-normal leading-5">{displayValue(row.round_target)}</span> },
  { label: "执行人", render: (row) => displayValue(row.executor_name_snapshot ?? row.executor_user_id) },
  { label: "状态", render: (row) => <Badge tone={crmStatusTone(row.status)}>{crmTaskStatusLabels[row.status] ?? row.status}</Badge> },
  { label: "资料更新", render: (row) => <CrmTaskDataUpdateCell task={row} /> },
  { label: "截止", render: (row) => formatDateTime(row.feedback_due_at) },
  { label: "风险", render: (row) => <Badge tone={row.is_blocked ? "bad" : row.need_support ? "neutral" : "ok"}>{row.is_blocked ? "阻塞" : row.need_support ? "需支持" : row.is_closed ? "已闭环" : "正常"}</Badge> }
];

const crmFollowupColumns: Array<CrmInlineColumn<CrmFollowupRow>> = [
  { label: "日期", render: (row) => formatDate(row.followup_date) },
  { label: "客户", render: (row) => row.customer_code },
  { label: "执行人", render: (row) => displayValue(row.executor_name_snapshot ?? row.executor_user_id) },
  { label: "反馈", render: (row) => <span className="line-clamp-2 max-w-[260px] whitespace-normal leading-5">{displayValue(row.customer_feedback)}</span> },
  { label: "审核", render: (row) => <Badge tone={crmStatusTone(row.review_status)}>{crmApprovalStatusLabels[row.review_status] ?? row.review_status}</Badge> }
];

const crmApprovalColumns: Array<CrmInlineColumn<ApprovalRow>> = [
  { label: "审批号", render: (row) => row.approval_no },
  { label: "标题", render: (row) => <span className="line-clamp-2 max-w-[280px] whitespace-normal leading-5">{row.title}</span> },
  { label: "类型", render: (row) => crmApprovalTypeLabel(row.approval_type) },
  { label: "状态", render: (row) => <Badge tone={crmStatusTone(row.status)}>{crmApprovalStatusLabels[row.status] ?? row.status}</Badge> },
  { label: "处理人", render: (row) => approvalUserLabel(row, "handler") },
  { label: "提交时间", render: (row) => formatDateTime(row.submitted_at ?? row.created_at) }
];

const crmWorkItemColumns: Array<CrmInlineColumn<WorkItemRow>> = [
  { label: "事项", render: (row) => <span><strong className="block max-w-[260px] truncate">{workItemPrimaryTitle(row)}</strong><span className="text-xs font-bold text-slate-400">{workItemCustomerLabel(row)}</span>{row.needs_next_action ? <span className="mt-1 inline-flex rounded-md bg-amber-50 px-2 py-0.5 text-xs font-black text-amber-700">待补下一步</span> : null}</span> },
  { label: "支持内容", render: (row) => <span className="line-clamp-2 max-w-[260px] whitespace-normal leading-5">{workItemSupportDetail(row) || "未填写支持说明"}</span> },
  { label: "优先级", render: (row) => <Badge tone={row.priority === "urgent" ? "bad" : row.priority === "high" ? "warn" : "neutral"}>{crmPriorityLabels[row.priority] ?? row.priority}</Badge> },
  { label: "状态", render: (row) => <Badge tone={crmWorkItemStatusTone(row.status)}>{crmWorkItemStatusLabels[row.status] ?? row.status}</Badge> },
  { label: "负责人", render: (row) => row.assignee_name || displayValue(row.assignee_user_id) },
  { label: "到期", render: (row) => formatDateTime(row.due_at) }
];

const crmReviewColumns: Array<CrmInlineColumn<CrmProjectReviewRow>> = [
  { label: "复盘号", render: (row) => row.review_no },
  { label: "状态", render: (row) => <Badge tone={crmStatusTone(row.status)}>{crmProjectReviewStatusLabels[row.status] ?? row.status}</Badge> },
  { label: "客户数", render: (row) => row.customer_total },
  { label: "未闭环", render: (row) => row.unclosed_customer_count },
  { label: "结论", render: (row) => displayValue(row.conclusion) }
];

type AccountTab = "accounts" | "roles" | "permissions" | "root-rules" | "data-scopes" | "field-permissions" | "external-api" | "audit";

const accountTabs: Array<{ tab: AccountTab; label: string; permissions: PermissionCode[] }> = [
  { tab: "accounts", label: "账号列表", permissions: ["user.view", "user.create", "user.edit", "user.reset_password", "user.disable", "user.restore", "user.cancel", "user.permission_config"] },
  { tab: "roles", label: "角色模板", permissions: ["authority.view"] },
  { tab: "permissions", label: "权限清单", permissions: ["authority.view", "user.permission_config"] },
  { tab: "root-rules", label: "权根规则", permissions: ["authority.view", "user.permission_config"] },
  { tab: "data-scopes", label: "数据范围", permissions: ["authority.view", "user.permission_config"] },
  { tab: "field-permissions", label: "字段权限", permissions: ["authority.view", "user.permission_config"] },
  { tab: "external-api", label: "外部 API", permissions: ["external_api_key.view", "external_api_key.create", "external_api_key.revoke"] },
  { tab: "audit", label: "审计日志", permissions: ["audit.view"] }
];

const accountTabFromPath = (path: string): AccountTab => {
  if (path.startsWith("/authority")) return "roles";
  if (path.startsWith("/users/roles")) return "roles";
  if (path.startsWith("/users/permissions")) return "permissions";
  if (path.startsWith("/users/root-rules")) return "root-rules";
  if (path.startsWith("/users/data-scopes")) return "data-scopes";
  if (path.startsWith("/users/field-permissions")) return "field-permissions";
  if (path.startsWith("/users/external-api")) return "external-api";
  if (path.startsWith("/users/audit")) return "audit";
  return "accounts";
};

const pathForAccountTab = (tab: AccountTab) => tab === "accounts" ? "/users" : `/users/${tab}`;

const canAccessAccountTab = (tab: AccountTab, permissions: PermissionCode[]) => {
  const item = accountTabs.find((accountTab) => accountTab.tab === tab);
  return !!item && hasAnyPermission(permissions, item.permissions);
};

const firstAccessibleAccountTab = (permissions: PermissionCode[]) => accountTabs.find((tab) => canAccessAccountTab(tab.tab, permissions))?.tab ?? "accounts";

function AccountAuthorityPanel({ activeTab, permissions: currentPermissions }: { activeTab: AccountTab; permissions: PermissionCode[] }) {
  const canViewAuthority = hasPermission(currentPermissions, "authority.view");
  const canEditAuthority = hasPermission(currentPermissions, "authority.edit");
  const canConfigureUserPermissions = hasPermission(currentPermissions, "user.permission_config");
  const canViewPermissionArtifacts = canViewAuthority || canConfigureUserPermissions;
  const canViewAudit = hasPermission(currentPermissions, "audit.view");
  const [roleRows, setRoleRows] = useState<RoleRow[]>([]);
  const [permissionRows, setPermissionRows] = useState<PermissionRow[]>([]);
  const [selectedRole, setSelectedRole] = useState<string>("admin");
  const [selectedPermissionCodes, setSelectedPermissionCodes] = useState<string[]>([]);
  const [permissionMessage, setPermissionMessage] = useState("选择角色后可维护该角色的权限模板。");
  const [rules, setRules] = useState<AuthorityRule[]>([]);
  const [scopeRules, setScopeRules] = useState<DataScopeRule[]>([]);
  const [fieldRules, setFieldRules] = useState<FieldPermissionRule[]>([]);
  const [audits, setAudits] = useState<AuditLog[]>([]);
  const [explainTarget, setExplainTarget] = useState<PermissionExplainTarget | null>(null);
  const [createRoleOpen, setCreateRoleOpen] = useState(false);
  const [authorityQuery, setAuthorityQuery] = useState("");
  const [authorityResourceFilter, setAuthorityResourceFilter] = useState("");
  const [authorityActionFilter, setAuthorityActionFilter] = useState("");
  const [authorityStatusFilter, setAuthorityStatusFilter] = useState("");

  useEffect(() => {
    if (canViewPermissionArtifacts) {
      void Promise.all([roles(), permissions(), authorityRules(), dataScopeRules(), fieldPermissionRules()]).then(([roleData, permissionData, ruleData, scopeData, fieldData]) => {
        setRoleRows(roleData);
        setPermissionRows(permissionData);
        setSelectedRole(roleData[0]?.role_code ?? "admin");
        setRules(ruleData);
        setScopeRules(scopeData);
        setFieldRules(fieldData);
      });
    }
    if (canViewAudit) {
      void auditLogs().then(setAudits);
    }
  }, [canViewPermissionArtifacts, canViewAudit]);

  useEffect(() => {
    if (!selectedRole || !canViewPermissionArtifacts) return;
    void rolePermissions(selectedRole).then((data) => {
      setSelectedPermissionCodes(data.permission_codes);
      setPermissionMessage(`${data.role.role_name} 当前拥有 ${data.permission_codes.length} 个权限。`);
    });
  }, [selectedRole, canViewPermissionArtifacts]);

  const togglePermission = (permissionCode: string) => {
    setSelectedPermissionCodes((current) =>
      current.includes(permissionCode) ? current.filter((code) => code !== permissionCode) : [...current, permissionCode].sort()
    );
  };

  const saveRolePermissions = async () => {
    if (!selectedRole) return;
    try {
      const data = await updateRolePermissions(selectedRole, selectedPermissionCodes);
      setSelectedPermissionCodes(data.permission_codes);
      setPermissionMessage(`已保存 ${data.role.role_name} 的 ${data.permission_codes.length} 个权限。`);
      if (canViewAudit) setAudits(await auditLogs());
    } catch (error) {
      setPermissionMessage(error instanceof Error ? error.message : "保存角色权限失败");
    }
  };

  const createRoleFromDrawer = async (payload: { role_code: string; role_name: string; description?: string | null; permission_codes?: string[] }) => {
    const data = await createRoleTemplate(payload);
    const nextRoles = await roles();
    setRoleRows(nextRoles);
    setSelectedRole(data.role.role_code);
    setSelectedPermissionCodes(data.permission_codes);
    setPermissionMessage(`已新增 ${data.role.role_name}，当前拥有 ${data.permission_codes.length} 个权限。`);
    setCreateRoleOpen(false);
    if (canViewAudit) setAudits(await auditLogs());
  };

  const resourceOptions = Array.from(new Set(permissionRows.map((permission) => permission.resource_type))).sort();
  const actionOptions = Array.from(new Set(permissionRows.map((permission) => permission.action_type))).sort();
  const filteredPermissionRows = permissionRows.filter((permission) =>
    includesKeyword([permission.permission_code, permission.permission_name, permission.resource_type, permission.action_type, permission.description], authorityQuery)
    && (!authorityResourceFilter || permission.resource_type === authorityResourceFilter)
    && (!authorityActionFilter || permission.action_type === authorityActionFilter)
  );
  const filteredRules = rules.filter((rule) =>
    includesKeyword([rule.rule_name, rule.resource_type, rule.action_type, rule.allowed_roles.join(", "), rule.requires_approval ? "需要" : "不需要"], authorityQuery)
    && (!authorityResourceFilter || rule.resource_type === authorityResourceFilter)
    && (!authorityActionFilter || rule.action_type === authorityActionFilter)
    && (!authorityStatusFilter || String(rule.is_active) === authorityStatusFilter)
  );
  const filteredScopeRules = scopeRules.filter((rule) =>
    includesKeyword([rule.subject_type, rule.subject_id, rule.resource_type, rule.scope_mode, JSON.stringify(rule.scope_value ?? {})], authorityQuery)
    && (!authorityResourceFilter || rule.resource_type === authorityResourceFilter)
    && (!authorityStatusFilter || String(rule.is_active) === authorityStatusFilter)
  );
  const filteredFieldRules = fieldRules.filter((rule) =>
    includesKeyword([rule.subject_type, rule.subject_id, rule.resource_type, rule.field_name, rule.permission_type, rule.mask_rule], authorityQuery)
    && (!authorityResourceFilter || rule.resource_type === authorityResourceFilter)
  );
  const filteredAudits = audits.filter((audit) =>
    includesKeyword([audit.id, audit.role_code, audit.action_type, audit.resource_type, audit.resource_id, audit.created_at], authorityQuery)
    && (!authorityResourceFilter || audit.resource_type === authorityResourceFilter)
    && (!authorityActionFilter || audit.action_type === authorityActionFilter)
  );
  const resetAuthorityFilters = () => {
    setAuthorityQuery("");
    setAuthorityResourceFilter("");
    setAuthorityActionFilter("");
    setAuthorityStatusFilter("");
  };
  const authorityToolbar = (
    <DataToolbar onReset={resetAuthorityFilters}>
      <ToolbarSearch value={authorityQuery} onChange={setAuthorityQuery} placeholder="搜索名称、编码、资源或动作" />
      <ToolbarSelect value={authorityResourceFilter} onChange={setAuthorityResourceFilter} label="资源" options={[{ value: "", label: "全部资源" }, ...resourceOptions.map((value) => ({ value, label: resourceLabels[value] ?? value }))]} />
      <ToolbarSelect value={authorityActionFilter} onChange={setAuthorityActionFilter} label="动作" options={[{ value: "", label: "全部动作" }, ...actionOptions.map((value) => ({ value, label: actionLabels[value] ?? value }))]} />
    </DataToolbar>
  );
  const statusToolbar = (
    <DataToolbar onReset={resetAuthorityFilters}>
      <ToolbarSearch value={authorityQuery} onChange={setAuthorityQuery} placeholder="搜索名称、主体、资源或范围" />
      <ToolbarSelect value={authorityResourceFilter} onChange={setAuthorityResourceFilter} label="资源" options={[{ value: "", label: "全部资源" }, ...resourceOptions.map((value) => ({ value, label: resourceLabels[value] ?? value }))]} />
      <ToolbarSelect
        value={authorityStatusFilter}
        onChange={setAuthorityStatusFilter}
        label="状态"
        options={[
          { value: "", label: "全部状态" },
          { value: "true", label: "启用" },
          { value: "false", label: "停用" }
        ]}
      />
    </DataToolbar>
  );
  const selectedRoleRow = roleRows.find((role) => role.role_code === selectedRole);

  if (activeTab === "roles") {
    return canViewAuthority ? (
      <>
        <div className="grid gap-5 xl:grid-cols-[320px_minmax(0,1fr)]">
          <Card>
            <div className="flex items-center justify-between gap-3 border-b border-slate-200 p-5">
              <h2 className="m-0 text-xl font-black">角色模板</h2>
              {canEditAuthority ? <Button secondary onClick={() => setCreateRoleOpen(true)}>新增模板</Button> : null}
            </div>
            <div className="grid gap-3 p-5">
              {roleRows.map((role) => (
                <button
                  key={role.id}
                  type="button"
                  onClick={() => setSelectedRole(role.role_code)}
                  className={`rounded-2xl border p-4 text-left transition ${
                    selectedRole === role.role_code ? "border-primary bg-primary-soft text-primary" : "border-slate-200 bg-slate-50 hover:bg-white"
                  }`}
                >
                  <strong>{role.role_name}</strong>
                  <p className="m-0 mt-1 text-sm text-slate-500">{role.role_code}</p>
                </button>
              ))}
            </div>
          </Card>
          <Card>
            <div className="flex flex-col gap-3 border-b border-slate-200 p-5 md:flex-row md:items-center md:justify-between">
              <div><h2 className="text-xl font-black">角色权限模板</h2><p className="mt-1 text-sm text-slate-500">{permissionMessage}</p></div>
              <div className="flex gap-2">
                {canEditAuthority ? <Button secondary onClick={() => setSelectedPermissionCodes(permissionRows.map((permission) => permission.permission_code).sort())}>全选</Button> : null}
                {canEditAuthority ? <Button secondary onClick={() => setSelectedPermissionCodes([])}>清空</Button> : null}
                {canEditAuthority ? <Button onClick={() => void saveRolePermissions()}>保存模板</Button> : null}
              </div>
            </div>
            <div className="grid gap-4 p-5">
              <section className="rounded-lg border border-slate-200 bg-slate-50 p-4">
                <p className="m-0 text-xs font-black uppercase tracking-[0.16em] text-primary">ROLE MATRIX</p>
                <h3 className="m-0 mt-1 text-lg font-black text-slate-950">{selectedRoleRow?.role_name ?? selectedRole} · 模块级权限</h3>
                <p className="m-0 mt-1 text-sm font-bold text-slate-500">角色模板是账号默认权限包，账号级允许/拒绝仍会在最终权限中覆盖它。</p>
              </section>
              {permissionModules.map((module) => {
                const moduleRows = permissionRowsForModule(permissionRows, module).sort(sortPermissionsByAction);
                if (moduleRows.length === 0) return null;
                const selectedCount = moduleRows.filter((permission) => selectedPermissionCodes.includes(permission.permission_code)).length;
                const riskCount = moduleRows.filter((permission) => selectedPermissionCodes.includes(permission.permission_code) && isHighRiskPermission(permission)).length;
                const entryEnabled = module.entryPermissions.some((permissionCode) => selectedPermissionCodes.includes(permissionCode));
                return (
                  <section key={module.code} className="rounded-lg border border-slate-200 bg-white p-4">
                    <div className="mb-4 flex flex-col gap-3 lg:flex-row lg:items-start lg:justify-between">
                      <div className="min-w-0">
                        <h3 className="m-0 text-base font-black text-slate-950">{module.label}</h3>
                        <p className="m-0 mt-1 text-xs font-bold leading-5 text-slate-500">{module.description}</p>
                      </div>
                      <div className="flex flex-wrap gap-2">
                        <Badge tone={entryEnabled ? "ok" : "bad"}>{entryEnabled ? "入口开启" : "入口关闭"}</Badge>
                        <Badge tone="neutral">{selectedCount}/{moduleRows.length}</Badge>
                        <Badge tone={riskCount > 0 ? "warn" : "neutral"}>高风险 {riskCount}</Badge>
                      </div>
                    </div>
                    <div className="grid gap-3">
                      {module.children.map((child) => {
                        const childRows = permissionRowsForNode(permissionRows, child).sort(sortPermissionsByAction);
                        if (childRows.length === 0) return null;
                        return (
                          <div key={child.code} className="rounded-lg border border-slate-100 bg-slate-50 p-3">
                            <div className="mb-2 flex items-center justify-between gap-3">
                              <strong className="text-sm font-black text-slate-800">{child.label}</strong>
                              <span className="text-xs font-bold text-slate-400">{childRows.filter((permission) => selectedPermissionCodes.includes(permission.permission_code)).length}/{childRows.length}</span>
                            </div>
                            <div className="grid gap-2 md:grid-cols-2 xl:grid-cols-3">
                              {childRows.map((permission) => (
                                <div key={permission.id} className="relative flex min-h-12 items-center gap-3 rounded-lg bg-white px-3 py-2 pr-10 text-sm font-semibold ring-1 ring-slate-200">
                                  <label className="flex min-w-0 flex-1 cursor-pointer items-center gap-3">
                                    <input
                                      type="checkbox"
                                      checked={selectedPermissionCodes.includes(permission.permission_code)}
                                      onChange={() => togglePermission(permission.permission_code)}
                                      className="h-4 w-4 accent-primary"
                                    />
                                    <span className="min-w-0">
                                      <strong className="flex items-center gap-2 truncate">
                                        <span className="truncate">{permission.permission_name}</span>
                                        {isHighRiskPermission(permission) ? <span className="rounded bg-amber-100 px-1.5 py-0.5 text-[10px] text-amber-700">风险</span> : null}
                                      </strong>
                                      <small className="block truncate text-xs text-slate-500">{permission.permission_code} / {actionLabels[permission.action_type] ?? permission.action_type}</small>
                                    </span>
                                  </label>
                                  <button
                                    type="button"
                                    aria-label="查看权限说明"
                                    title="查看权限说明"
                                    onClick={() => setExplainTarget({ permission, module, child })}
                                    className="absolute right-2 top-2 grid h-7 w-7 place-items-center rounded-md text-slate-400 transition hover:bg-slate-100 hover:text-slate-700"
                                  >
                                    <MoreHorizontal className="h-4 w-4" />
                                  </button>
                                </div>
                              ))}
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  </section>
                );
              })}
            </div>
          </Card>
        </div>
        <AnimatePresence>
          {createRoleOpen ? (
            <CreateRoleTemplateDrawer
              sourceRole={selectedRoleRow}
              sourcePermissionCodes={selectedPermissionCodes}
              onClose={() => setCreateRoleOpen(false)}
              onSubmit={createRoleFromDrawer}
            />
          ) : null}
          {explainTarget ? <PermissionExplainDrawer target={explainTarget} onClose={() => setExplainTarget(null)} /> : null}
        </AnimatePresence>
      </>
    ) : <Card className="p-6 text-sm font-bold text-slate-500">当前账号没有角色模板查看权限。</Card>;
  }

  if (activeTab === "permissions") {
    return canViewPermissionArtifacts ? (
      <DataTableShell
        title="权限清单"
        description="系统已注册的权限码、资源和动作类型。"
        meta={`${filteredPermissionRows.length} / ${permissionRows.length} 条`}
        toolbar={authorityToolbar}
      >
        <Table headers={["权限码", "权限名称", "资源", "动作", "说明"]}>
          {filteredPermissionRows.map((permission) => (
            <tr key={permission.id}>
              <td>{permission.permission_code}</td>
              <td>{permission.permission_name}</td>
              <td>{resourceLabels[permission.resource_type] ?? permission.resource_type}</td>
              <td>{actionLabels[permission.action_type] ?? permission.action_type}</td>
              <td>{permission.description ?? "-"}</td>
            </tr>
          ))}
        </Table>
      </DataTableShell>
    ) : <Card className="p-6 text-sm font-bold text-slate-500">当前账号没有权限清单查看权限。</Card>;
  }

  if (activeTab === "root-rules") {
    return canViewPermissionArtifacts ? (
      <DataTableShell
        title="权根规则"
        description="维护资源动作与角色边界、审批要求和启停状态。"
        meta={`${filteredRules.length} / ${rules.length} 条`}
        toolbar={statusToolbar}
      >
        <Table headers={["规则", "资源", "动作", "角色", "审批", "状态"]}>
          {filteredRules.map((rule) => <tr key={rule.id}><td>{rule.rule_name}</td><td>{resourceLabels[rule.resource_type] ?? rule.resource_type}</td><td>{actionLabels[rule.action_type] ?? rule.action_type}</td><td>{rule.allowed_roles.join(", ")}</td><td>{rule.requires_approval ? "需要" : "不需要"}</td><td><Badge tone={rule.is_active ? "ok" : "bad"}>{rule.is_active ? "启用" : "停用"}</Badge></td></tr>)}
        </Table>
      </DataTableShell>
    ) : <Card className="p-6 text-sm font-bold text-slate-500">当前账号没有权根规则查看权限。</Card>;
  }

  if (activeTab === "data-scopes") {
    return canViewPermissionArtifacts ? (
      <DataTableShell
        title="数据范围"
        description="按主体、资源和范围模式管理行级数据可见范围。"
        meta={`${filteredScopeRules.length} / ${scopeRules.length} 条`}
        toolbar={statusToolbar}
      >
        <Table headers={["主体", "资源", "范围模式", "范围值", "状态"]}>
          {filteredScopeRules.map((rule) => (
            <tr key={rule.id}>
              <td>{rule.subject_type}:{rule.subject_id}</td>
              <td>{resourceLabels[rule.resource_type] ?? rule.resource_type}</td>
              <td>{scopeModeLabels[rule.scope_mode] ?? rule.scope_mode}</td>
              <td>{rule.scope_value ? JSON.stringify(rule.scope_value) : "-"}</td>
              <td><Badge tone={rule.is_active ? "ok" : "bad"}>{rule.is_active ? "启用" : "停用"}</Badge></td>
            </tr>
          ))}
        </Table>
      </DataTableShell>
    ) : <Card className="p-6 text-sm font-bold text-slate-500">当前账号没有数据范围查看权限。</Card>;
  }

  if (activeTab === "field-permissions") {
    return canViewPermissionArtifacts ? (
      <DataTableShell
        title="字段权限"
        description="管理敏感字段的隐藏、脱敏和只读策略。"
        meta={`${filteredFieldRules.length} / ${fieldRules.length} 条`}
        toolbar={
          <DataToolbar onReset={resetAuthorityFilters}>
            <ToolbarSearch value={authorityQuery} onChange={setAuthorityQuery} placeholder="搜索主体、资源、字段或处理方式" />
            <ToolbarSelect value={authorityResourceFilter} onChange={setAuthorityResourceFilter} label="资源" options={[{ value: "", label: "全部资源" }, ...resourceOptions.map((value) => ({ value, label: resourceLabels[value] ?? value }))]} />
          </DataToolbar>
        }
      >
        <Table headers={["主体", "资源", "字段", "处理方式", "脱敏规则"]}>
          {filteredFieldRules.map((rule) => (
            <tr key={rule.id}>
              <td>{rule.subject_type}:{rule.subject_id}</td>
              <td>{resourceLabels[rule.resource_type] ?? rule.resource_type}</td>
              <td>{fieldLabels[rule.field_name] ?? rule.field_name}</td>
              <td>{fieldPermissionLabels[rule.permission_type] ?? rule.permission_type}</td>
              <td>{rule.mask_rule ?? "-"}</td>
            </tr>
          ))}
        </Table>
      </DataTableShell>
    ) : <Card className="p-6 text-sm font-bold text-slate-500">当前账号没有字段权限查看权限。</Card>;
  }

  if (activeTab === "audit") {
    return canViewAudit ? (
      <AuditTable
        rows={filteredAudits}
        total={audits.length}
        toolbar={authorityToolbar}
      />
    ) : <Card className="p-6 text-sm font-bold text-slate-500">当前账号没有审计日志查看权限。</Card>;
  }

  return null;
}

