type PermissionGroupNode = {
  code: string;
  label: string;
  description?: string;
  resources?: string[];
  permissionCodes?: PermissionCode[];
  scopeResources?: string[];
};

type PermissionModuleConfig = PermissionGroupNode & {
  entryPermissions: PermissionCode[];
  highRiskPermissionCodes?: PermissionCode[];
  children: PermissionGroupNode[];
};

type PermissionExplainTarget = {
  permission: PermissionRow;
  module: PermissionModuleConfig;
  child?: PermissionGroupNode | null;
};

