const permissionActionOrder = [
  "view",
  "create",
  "edit",
  "delete",
  "assign",
  "import",
  "export",
  "check",
  "refresh",
  "submit",
  "convert",
  "approve",
  "review",
  "handle",
  "process",
  "download",
  "close",
  "config",
  "disable",
  "restore",
  "cancel",
  "reset_password",
  "permission_config",
  "rule_manage",
  "revoke",
  "generate",
  "agent_write_judgement"
];

const highRiskActionTypes = new Set(["delete", "cancel", "disable", "reset_password", "permission_config", "approve", "config", "revoke", "agent_write_judgement"]);
const highRiskResourceTypes = new Set(["user", "approval", "external_api_key", "crm_insight", "system_config"]);

function permissionMatchesNode(permission: PermissionRow, node: PermissionGroupNode) {
  const codeMatched = node.permissionCodes?.includes(permission.permission_code) ?? false;
  const resourceMatched = node.resources?.includes(permission.resource_type) ?? false;
  return codeMatched || resourceMatched;
}

function permissionRowsForNode(permissionRows: PermissionRow[], node: PermissionGroupNode) {
  return permissionRows.filter((permission) => permissionMatchesNode(permission, node));
}

function permissionRowsForModule(permissionRows: PermissionRow[], module: PermissionModuleConfig) {
  const rows = [
    ...permissionRowsForNode(permissionRows, module),
    ...module.children.flatMap((child) => permissionRowsForNode(permissionRows, child))
  ];
  return Array.from(new Map(rows.map((permission) => [permission.permission_code, permission])).values());
}

function scopeResourcesForNode(node: PermissionGroupNode) {
  return Array.from(new Set([...(node.resources ?? []), ...(node.scopeResources ?? [])]));
}

function scopeResourcesForModule(module: PermissionModuleConfig) {
  return Array.from(new Set([...(module.resources ?? []), ...(module.scopeResources ?? []), ...module.children.flatMap(scopeResourcesForNode)]));
}

function sortPermissionsByAction(left: PermissionRow, right: PermissionRow) {
  const leftIndex = permissionActionOrder.indexOf(left.action_type);
  const rightIndex = permissionActionOrder.indexOf(right.action_type);
  const normalizedLeft = leftIndex === -1 ? 99 : leftIndex;
  const normalizedRight = rightIndex === -1 ? 99 : rightIndex;
  return normalizedLeft - normalizedRight || left.resource_type.localeCompare(right.resource_type) || left.permission_code.localeCompare(right.permission_code);
}

function isHighRiskPermission(permission: PermissionRow) {
  return highRiskActionTypes.has(permission.action_type)
    || (highRiskResourceTypes.has(permission.resource_type) && permission.action_type !== "view")
    || permissionModules.some((module) => module.highRiskPermissionCodes?.includes(permission.permission_code));
}

function permissionRiskReason(permission: PermissionRow) {
  if (permission.permission_code.includes("external_api_key")) return "外部接口凭证";
  if (permission.action_type === "permission_config") return "可变更账号权限";
  if (["crm_lead.convert", "crm_lead.approve"].includes(permission.permission_code)) return "客户转正会创建正式客户档案，并影响后续项目申请与客户数据归属";
  if (permission.action_type === "approve" || permission.resource_type === "approval") return "可处理审批";
  if (permission.action_type === "agent_write_judgement" || permission.permission_code === "crm_insight.generate") return "AI 写入或生成判断";
  if (["delete", "cancel", "disable", "revoke"].includes(permission.action_type)) return "删除、归档或撤销类动作";
  if (permission.action_type === "reset_password") return "重置密码";
  if (permission.action_type === "config") return "系统或审批配置";
  return "高风险权限";
}

function permissionMeaningText(permission: PermissionRow) {
  const action = actionLabels[permission.action_type] ?? permission.action_type;
  const resource = resourceLabels[permission.resource_type] ?? permission.resource_type;
  if (permission.description) return permission.description;
  if (permission.action_type === "view") return `允许查看「${resource}」列表、详情和相关上下文入口。`;
  if (permission.action_type === "create") return `允许在「${resource}」中新增记录或发起对应业务。`;
  if (permission.action_type === "edit") return `允许修改「${resource}」已有记录的可编辑字段。`;
  if (permission.action_type === "delete") return `允许删除或作废「${resource}」记录，会影响后续数据追溯。`;
  if (permission.permission_code === "crm_lead.convert") return "允许发起客户线索转正审批；审批通过后系统会创建正式客户档案。";
  if (permission.permission_code === "crm_lead.approve") return "允许审批客户线索转正，审批通过会创建正式客户档案并结束线索开发阶段。";
  if (permission.action_type === "approve") return `允许处理「${resource}」审批节点，推动业务流程通过、退回或拒绝。`;
  if (permission.action_type === "assign") return `允许调整「${resource}」负责人、执行人或协同人员。`;
  if (permission.action_type === "import") return `允许向「${resource}」导入外部数据。`;
  if (permission.action_type === "export") return `允许导出「${resource}」数据。`;
  if (permission.action_type === "download") return `允许下载「${resource}」处理结果或附件。`;
  if (permission.action_type === "process") return `允许执行「${resource}」处理任务。`;
  if (permission.action_type === "close") return `允许关闭「${resource}」流程或事项。`;
  if (permission.action_type === "permission_config") return "允许调整账号级权限覆盖，直接影响账号能看什么和能做什么。";
  return `允许对「${resource}」执行「${action}」动作。`;
}

function permissionScopeText(target: PermissionExplainTarget) {
  const resource = resourceLabels[target.permission.resource_type] ?? target.permission.resource_type;
  const modulePath = [target.module.label, target.child?.label].filter(Boolean).join(" / ");
  return `作用于「${modulePath}」下的「${resource}」资源。最终可见数据还会继续受到数据范围、字段权限和接口权限校验约束。`;
}

function permissionRiskText(permission: PermissionRow) {
  if (isHighRiskPermission(permission)) return `${permissionRiskReason(permission)}。授权前请确认该账号确实承担对应职责，保存后会进入审计留痕。`;
  if (["export", "download"].includes(permission.action_type)) return "该权限可能带来数据外流风险，建议只授权给需要下载或导出结果的岗位。";
  if (["create", "edit", "import", "process", "assign", "close"].includes(permission.action_type)) return "该权限会改变业务数据或流程状态，建议结合岗位职责和数据范围一起配置。";
  return "该权限主要影响查看入口，风险较低；仍需配合数据范围与字段权限控制敏感信息。";
}

