function exceptionEvidenceSectionsFor(domain: string, source: Record<string, unknown>) {
  if (domain === "crm") {
    return source.kind === "crm_followup_binding" || Object.prototype.hasOwnProperty.call(source, "followup_id")
      ? crmFollowupExceptionEvidenceSections
      : crmTaskExceptionEvidenceSections;
  }
  if (domain === "approval") return approvalExceptionEvidenceSections;
  return exceptionEvidenceSections[domain] ?? [];
}

function exceptionEvidenceValue(source: Record<string, unknown>, path: string): unknown {
  return path.split(".").reduce<unknown>((current, part) => {
    if (!current || typeof current !== "object" || Array.isArray(current)) return undefined;
    return (current as Record<string, unknown>)[part];
  }, source);
}

function hasExceptionEvidencePath(source: Record<string, unknown>, path: string): boolean {
  let current: unknown = source;
  for (const part of path.split(".")) {
    if (!current || typeof current !== "object" || Array.isArray(current) || !Object.prototype.hasOwnProperty.call(current, part)) return false;
    current = (current as Record<string, unknown>)[part];
  }
  return true;
}

function firstExceptionEvidenceValue(source: Record<string, unknown>, paths: string[]) {
  for (const path of paths) {
    const value = exceptionEvidenceValue(source, path);
    if (value !== undefined && value !== null && value !== "") return value;
  }
  return undefined;
}

function formatExceptionBusinessValue(value: unknown) {
  if (value === null || value === undefined || value === "") return "未提供";
  if (typeof value === "boolean") return value ? "是" : "否";
  if (typeof value === "number" || typeof value === "string") return String(value);
  if (Array.isArray(value)) {
    const readable = value.filter((item) => ["string", "number"].includes(typeof item)).map(String);
    return readable.length > 0 ? readable.slice(0, 12).join("、") : `${value.length} 项`;
  }
  if (typeof value === "object") {
    const record = value as Record<string, unknown>;
    for (const key of ["name", "label", "code", "summary", "value", "status"]) {
      if (["string", "number"].includes(typeof record[key])) return String(record[key]);
    }
    return `${Object.keys(record).length} 项结构化信息`;
  }
  return String(value);
}

function ExceptionBusinessEvidence({ domain, value }: { domain: string; value: Record<string, unknown> | null | undefined }) {
  const source = value ?? {};
  const sections = exceptionEvidenceSectionsFor(domain, source);
  const evaluatedSections = sections.map((section) => ({
    ...section,
    fields: section.fields.map((field) => ({
      ...field,
      value: firstExceptionEvidenceValue(source, field.paths),
      mapped: field.paths.some((path) => hasExceptionEvidencePath(source, path))
    }))
  }));
  const hasMappedEvidence = evaluatedSections.some((section) => section.fields.some((field) => field.mapped));
  if (!hasMappedEvidence) {
    return <p className="m-0 rounded-lg border border-dashed border-border bg-secondary px-4 py-5 text-sm font-bold text-muted-foreground">当前证据已留存，但没有可按业务口径展示的标准字段。请查看原记录或联系数据中台补充证据映射。</p>;
  }
  const populatedSections = evaluatedSections.map((section) => ({
    ...section,
    fields: section.fields
      .filter((field) => field.value !== undefined || field.expected)
      .map((field) => ({ ...field, missing: field.value === undefined }))
  })).filter((section) => section.fields.length > 0);
  return (
    <div className="grid gap-4" data-testid={`exception-business-evidence-${domain}`}>
      {populatedSections.map((section) => (
        <section key={section.title} className="border-t border-border pt-3 first:border-t-0 first:pt-0">
          <h4 className="m-0 text-xs font-black text-foreground">{section.title}</h4>
          <dl className="mt-2 grid gap-x-5 gap-y-3 sm:grid-cols-2 xl:grid-cols-3">
            {section.fields.map((field) => (
              <div key={field.label} className={`min-w-0 ${field.missing ? "rounded-md border border-amber-300 bg-amber-50 px-3 py-2" : ""}`} data-evidence-missing={field.missing ? "true" : undefined}>
                <dt className={`text-xs font-bold ${field.missing ? "text-amber-800" : "text-muted-foreground"}`}>{field.label}</dt>
                <dd className={`m-0 mt-0.5 break-words text-sm font-black ${field.missing ? "text-red-700" : "text-foreground"}`}>{formatExceptionBusinessValue(field.value)}</dd>
                {field.expected ? <span className={`mt-0.5 block text-xs font-bold ${field.missing ? "text-amber-800" : "text-slate-500"}`}>正常口径：{field.expected}</span> : null}
              </div>
            ))}
          </dl>
        </section>
      ))}
    </div>
  );
}

