function ExceptionDiagnosisProgress({ status }: { status: "queued" | "processing" }) {
  const queued = status === "queued";
  const label = queued ? "等待诊断资源" : "正在分析证据并生成诊断";
  return (
    <div className="mt-3" data-testid="exception-diagnosis-progress" data-status={status} role="status" aria-live="polite">
      <div className="flex items-center justify-between gap-3 text-xs font-black text-muted-foreground">
        <span>{label}</span>
        <span>{queued ? "排队中" : "诊断中"}</span>
      </div>
      <div
        className="exception-diagnosis-progress-track mt-2"
        role="progressbar"
        aria-label="智能诊断进度"
        aria-valuemin={0}
        aria-valuemax={100}
        aria-valuenow={queued ? 25 : 70}
        aria-valuetext={label}
      >
        <span className="exception-diagnosis-progress-fill" />
        <span className="exception-diagnosis-progress-runner" aria-hidden="true" />
      </div>
      <p className="m-0 mt-1.5 text-xs font-bold text-muted-foreground">页面会自动刷新，完成后展示中文诊断结果。</p>
    </div>
  );
}

function ExceptionDiagnosisView({ diagnosis }: { diagnosis: ExceptionDiagnosis }) {
  const confidence = diagnosis.confidence == null ? null : Math.round(Number(diagnosis.confidence) * 100);
  const impact = typeof diagnosis.impact === "string"
    ? diagnosis.impact
    : diagnosis.impact && typeof diagnosis.impact === "object"
      ? String((diagnosis.impact as Record<string, unknown>).summary ?? "已记录影响范围")
      : "未说明";
  return (
    <div className="mt-3 grid gap-4" data-testid="exception-diagnosis-structured">
      <div className="grid gap-3 rounded-lg border border-border bg-secondary px-4 py-3 sm:grid-cols-[minmax(0,1fr)_auto]">
        <div className="min-w-0">
          <span className="text-xs font-black text-muted-foreground">最可能根因</span>
          <strong className="mt-1 block text-base font-black text-foreground">{exceptionRootCauseLabels[diagnosis.root_cause_code ?? ""] ?? diagnosis.root_cause_code ?? "尚未归类"}</strong>
          <p className="m-0 mt-1 text-sm font-bold leading-6 text-slate-700">{diagnosis.summary ?? "暂无诊断摘要"}</p>
        </div>
        <div className="flex min-w-24 flex-col items-start gap-1 sm:items-end">
          <Badge tone={diagnosis.disposition === "blocked" ? "warn" : "ok"}>{exceptionDispositionLabels[diagnosis.disposition ?? ""] ?? diagnosis.disposition ?? "待判断"}</Badge>
          <span className="font-mono text-sm font-black text-foreground">可信度 {confidence == null || Number.isNaN(confidence) ? "未提供" : `${confidence}%`}</span>
        </div>
      </div>
      <div className="grid gap-4 lg:grid-cols-2">
        <div>
          <h4 className="m-0 text-xs font-black text-muted-foreground">影响范围</h4>
          <p className="m-0 mt-1 text-sm font-bold leading-6 text-foreground">{impact}</p>
        </div>
        <div>
          <h4 className="m-0 text-xs font-black text-muted-foreground">证据引用</h4>
          <div className="mt-1 flex flex-wrap gap-1.5">{(diagnosis.evidence_refs ?? []).length > 0 ? diagnosis.evidence_refs?.map((item) => <span key={item} className="rounded border border-border bg-white px-2 py-1 font-mono text-xs font-bold text-slate-600">{item}</span>) : <span className="text-sm font-bold text-muted-foreground">未提供</span>}</div>
        </div>
      </div>
      <div>
        <h4 className="m-0 text-xs font-black text-muted-foreground">建议处理步骤</h4>
        {(diagnosis.recommended_steps ?? []).length > 0 ? <ol className="m-0 mt-2 grid gap-2 pl-5 text-sm font-bold leading-6 text-foreground">{diagnosis.recommended_steps?.map((item, index) => <li key={`${index}-${String(item)}`}>{String(item)}</li>)}</ol> : <p className="m-0 mt-1 text-sm font-bold text-muted-foreground">暂无可执行步骤。</p>}
      </div>
      {(diagnosis.missing_evidence ?? []).length > 0 ? <div className="rounded-lg border border-amber-200 bg-amber-50 px-4 py-3"><h4 className="m-0 text-xs font-black text-amber-800">仍缺少的证据</h4><ul className="m-0 mt-1 grid gap-1 pl-5 text-sm font-bold text-amber-900">{diagnosis.missing_evidence?.map((item, index) => <li key={`${index}-${String(item)}`}>{String(item)}</li>)}</ul></div> : null}
    </div>
  );
}

function ExceptionVerificationView({ result }: { result: ExceptionVerificationResult }) {
  const snapshots = [["复检前", result.before], ["复检后", result.after]] as const;
  return (
    <div className={`mt-3 rounded-lg border px-4 py-3 ${result.resolved ? "border-emerald-200 bg-emerald-50" : "border-amber-200 bg-amber-50"}`} data-testid="exception-verification-result" role="status">
      <div className="flex flex-wrap items-center justify-between gap-2"><strong className="text-sm font-black text-foreground">{result.resolved ? "复检通过，异常已消失" : "复检未通过，异常仍然存在"}</strong><Badge tone={result.resolved ? "ok" : "warn"}>{result.resolved ? "已解决" : "需要继续处理"}</Badge></div>
      <div className="mt-3 grid gap-3 sm:grid-cols-2">
        {snapshots.map(([label, snapshot]) => <div key={label} className="rounded-md border border-black/5 bg-white/70 px-3 py-2"><span className="text-xs font-black text-muted-foreground">{label}</span><strong className="mt-1 block text-sm text-foreground">{snapshot?.summary ?? exceptionStatusLabels[(snapshot?.status ?? "") as ExceptionCaseStatus] ?? snapshot?.status ?? "未返回"}</strong><span className="mt-1 block text-xs font-bold text-slate-600">影响 {snapshot?.affected_rows ?? "-"} 条 · 数量 {snapshot?.affected_quantity ?? "-"}</span></div>)}
      </div>
      <p className="m-0 mt-2 text-xs font-bold text-slate-700">证据版本{result.evidence_changed ? "已更新" : "未变化"}{result.scan_result ? ` · 扫描新建 ${result.scan_result.created ?? 0}、更新 ${result.scan_result.updated ?? 0}、解决 ${result.scan_result.resolved ?? 0}` : ""}</p>
      {result.note ? <p className="m-0 mt-2 text-xs font-bold text-slate-700">复检说明：{result.note}</p> : null}
    </div>
  );
}

type ExceptionPolicyMutableKey = Exclude<keyof ExceptionPolicy, "policy_key" | "updated_at">;

const exceptionPolicyMutableFields: ExceptionPolicyMutableKey[] = [
  "is_enabled",
  "manual_ai_enabled",
  "scheduled_ai_enabled",
  "full_scan_enabled",
  "digest_enabled",
  "full_scan_cron",
  "digest_cron",
  "ai_daily_limit",
  "ai_batch_limit",
  "manual_ai_daily_limit",
  "scheduled_ai_daily_limit",
  "scheduled_ai_batch_limit",
  "ai_concurrency",
  "stale_diagnosis_hours",
  "domain_modes",
  "settings"
];

type ExceptionRolloutDomain = "crm" | "approval";

const exceptionRolloutDomains: Array<{ domain: ExceptionRolloutDomain; label: string }> = [
  { domain: "crm", label: "客户 CRM" },
  { domain: "approval", label: "审批" }
];

const exceptionDomainModeLabels: Record<ExceptionDomainMode, string> = {
  off: "关闭",
  shadow: "影子",
  visible: "可见"
};

const exceptionDomainModeDescriptions: Record<ExceptionDomainMode, string> = {
  off: "不扫描、不创建案件，也不向业务用户展示。",
  shadow: "执行确定性扫描并保存案件，仅授权验收人员可见；不发送通知、不调用 AI、不执行修复。",
  visible: "按来源权限和数据范围向业务用户展示。切换前必须完成影子验收。"
};

function exceptionPolicyChanges(current: ExceptionPolicy, original: ExceptionPolicy) {
  const changes: Partial<Omit<ExceptionPolicy, "policy_key" | "updated_at">> = {};
  exceptionPolicyMutableFields.forEach((key) => {
    if (JSON.stringify(current[key]) !== JSON.stringify(original[key])) {
      Object.assign(changes, { [key]: current[key] });
    }
  });
  return changes;
}

function ExceptionPolicyDrawer({ permissions, onClose }: { permissions: PermissionCode[]; onClose: () => void }) {
  const [form, setForm] = useState<ExceptionPolicy | null>(null);
  const [originalForm, setOriginalForm] = useState<ExceptionPolicy | null>(null);
  const [error, setError] = useState<Error | null>(null);
  const [saving, setSaving] = useState(false);
  const [baselineDomain, setBaselineDomain] = useState<ExceptionRolloutDomain | null>(null);
  const [baselineResults, setBaselineResults] = useState<Partial<Record<ExceptionRolloutDomain, ExceptionBaselineScanResponse>>>({});
  const [visibleConfirmation, setVisibleConfirmation] = useState<ExceptionRolloutDomain | null>(null);
  const loadControllerRef = useRef<AbortController | null>(null);
  const loadSequenceRef = useRef(0);
  const canManagePolicy = hasPermission(permissions, "exception_center.policy_manage");
  const load = useCallback(async () => {
    const sequence = ++loadSequenceRef.current;
    loadControllerRef.current?.abort();
    if (!canManagePolicy) {
      loadControllerRef.current = null;
      setForm(null);
      setOriginalForm(null);
      return;
    }
    const controller = new AbortController();
    loadControllerRef.current = controller;
    setError(null);
    try {
      const next = await exceptionPolicy(controller.signal);
      if (controller.signal.aborted || sequence !== loadSequenceRef.current) return;
      setForm(next);
      setOriginalForm(next);
      setVisibleConfirmation(null);
    } catch (reason) {
      if (controller.signal.aborted || sequence !== loadSequenceRef.current || isAbortError(reason)) return;
      setError(normalizeUiError(reason, "巡检策略加载失败"));
    } finally {
      if (sequence === loadSequenceRef.current && loadControllerRef.current === controller) {
        loadControllerRef.current = null;
      }
    }
  }, [canManagePolicy]);
  useEffect(() => {
    void load();
    return () => loadControllerRef.current?.abort();
  }, [load]);
  const changes = form && originalForm ? exceptionPolicyChanges(form, originalForm) : {};
  const hasChanges = Object.keys(changes).length > 0;
  const selectDomainMode = (domain: ExceptionRolloutDomain, mode: ExceptionDomainMode) => {
    if (!form || form.domain_modes[domain] === mode) return;
    if (mode === "visible") {
      setVisibleConfirmation(domain);
      return;
    }
    setVisibleConfirmation((current) => current === domain ? null : current);
    setForm({ ...form, domain_modes: { ...form.domain_modes, [domain]: mode } });
  };
  const confirmVisibleMode = () => {
    if (!form || !visibleConfirmation) return;
    setForm({
      ...form,
      domain_modes: { ...form.domain_modes, [visibleConfirmation]: "visible" }
    });
    setVisibleConfirmation(null);
  };
  const save = async (event: FormEvent) => {
    event.preventDefault();
    if (!form || !originalForm || !canManagePolicy || !hasChanges) return;
    setSaving(true);
    setError(null);
    try {
      const next = await updateExceptionPolicy({
        ...changes,
        expected_updated_at: originalForm.updated_at
      });
      setForm(next);
      setOriginalForm(next);
      setVisibleConfirmation(null);
    } catch (reason) {
      setError(reason instanceof ApiError && reason.status === 409
        ? apiErrorWithMessage(reason, "巡检策略已被其他管理员更新，请刷新后重新修改。")
        : normalizeUiError(reason, "巡检策略保存失败"));
    } finally {
      setSaving(false);
    }
  };
  const establishBaseline = async (domain: ExceptionRolloutDomain) => {
    if (
      !form
      || !originalForm
      || !canManagePolicy
      || saving
      || baselineDomain
      || hasChanges
      || originalForm.domain_modes[domain] !== "shadow"
    ) return;
    setBaselineDomain(domain);
    setError(null);
    try {
      const response = await runExceptionBaselineScan(domain, originalForm.updated_at);
      setBaselineResults((current) => ({ ...current, [domain]: response }));
      try {
        const latestPolicy = await exceptionPolicy();
        setForm(latestPolicy);
        setOriginalForm(latestPolicy);
      } catch (refreshReason) {
        setError(normalizeUiError(refreshReason, "基线已建立，但最新策略版本刷新失败；刷新策略后再继续操作"));
      }
    } catch (reason) {
      setError(reason instanceof ApiError && reason.status === 409
        ? apiErrorWithMessage(reason, "巡检策略已变化，基线未执行；请刷新策略后重试。")
        : normalizeUiError(reason, "基线扫描执行失败"));
    } finally {
      setBaselineDomain(null);
    }
  };
  return (
    <Drawer title="异常巡检策略" subtitle="控制确定性扫描、定时摘要和模型诊断预算" onClose={onClose}>
      {error ? <ApiErrorNotice error={error} onRetry={() => void load()} /> : null}
      {!form && !error ? <div className="h-72 animate-pulse rounded-lg bg-secondary" /> : null}
      {form ? (
        <form className="grid gap-4" onSubmit={save}>
          <section className="overflow-hidden rounded-lg border border-border bg-white" data-testid="exception-domain-modes">
            <div className="border-b border-border px-4 py-3">
              <h3 className="m-0 text-sm font-black text-foreground">CRM / 审批灰度模式</h3>
              <p className="m-0 mt-1 text-xs font-bold leading-5 text-muted-foreground">域模式只控制对应确定性规则的扫描与可见性，不会自动开启人工 AI、定时 AI、全量定时巡检、摘要通知或修复动作。</p>
            </div>
            <div className="grid gap-0 md:grid-cols-2">
              {exceptionRolloutDomains.map(({ domain, label }, index) => {
                const savedMode = originalForm?.domain_modes[domain] ?? "off";
                const response = baselineResults[domain];
                const result = response?.result;
                const baselineAllowed = savedMode === "shadow" && !hasChanges && !saving && baselineDomain === null;
                return (
                  <div key={domain} className={`grid gap-3 px-4 py-4 ${index === 0 ? "border-b border-border md:border-b-0 md:border-r" : ""}`} data-testid={`exception-domain-mode-${domain}`}>
                    <div className="flex items-center justify-between gap-3"><strong className="text-sm font-black text-foreground">{label}</strong><Badge tone={form.domain_modes[domain] === "visible" ? "ok" : form.domain_modes[domain] === "shadow" ? "warn" : "neutral"}>{exceptionDomainModeLabels[form.domain_modes[domain]]}</Badge></div>
                    <div className="grid grid-cols-3 overflow-hidden rounded-md border border-border" role="group" aria-label={`${label}异常域模式`}>
                      {(["off", "shadow", "visible"] as ExceptionDomainMode[]).map((mode) => <button key={mode} type="button" aria-pressed={form.domain_modes[domain] === mode} data-testid={`exception-domain-${domain}-${mode}`} onClick={() => selectDomainMode(domain, mode)} className={`min-h-10 border-r border-border px-2 text-xs font-black last:border-r-0 ${form.domain_modes[domain] === mode ? "bg-primary text-white" : "bg-white text-muted-foreground hover:bg-secondary"}`}>{exceptionDomainModeLabels[mode]}</button>)}
                    </div>
                    <p className="m-0 min-h-10 text-xs font-bold leading-5 text-slate-600">{exceptionDomainModeDescriptions[form.domain_modes[domain]]}</p>
                    <div className="rounded-md border border-border bg-secondary/40 px-3 py-2.5" data-testid={`exception-baseline-${domain}`}>
                      <div className="flex flex-wrap items-center justify-between gap-2"><div><strong className="block text-xs font-black text-foreground">建立影子基线</strong><span className="mt-0.5 block text-xs font-bold text-muted-foreground">需先保存为影子模式，且不能有未保存修改。</span></div><Button type="button" secondary disabled={!baselineAllowed} onClick={() => void establishBaseline(domain)}>{baselineDomain === domain ? "扫描中" : "建立基线"}</Button></div>
                      {savedMode !== "shadow" ? <p className="m-0 mt-2 text-xs font-black text-amber-700">当前已保存模式为“{exceptionDomainModeLabels[savedMode]}”，不能执行基线扫描。</p> : hasChanges ? <p className="m-0 mt-2 text-xs font-black text-amber-700">请先保存模式修改，再建立基线。</p> : null}
                      {result ? <p className="m-0 mt-2 text-xs font-black text-emerald-700" role="status" data-testid={`exception-baseline-result-${domain}`}>扫描 {result.scanned} · 新建 {result.created} · 新增 {result.new} · 复发 {result.reopened} · 证据更新 {result.evidence_updated} · 解决 {result.resolved}</p> : null}
                    </div>
                  </div>
                );
              })}
            </div>
            <div className="border-t border-border bg-amber-50 px-4 py-3 text-xs font-bold leading-5 text-amber-900" data-testid="exception-baseline-guardrails">基线扫描不会发送通知、不会调用 AI、不会执行修复，也不会启用任何定时任务。它只把影子模式下首次发现的既有问题登记为存量案件。</div>
          </section>
          {visibleConfirmation ? <div className="rounded-lg border border-red-200 bg-red-50 px-4 py-3" role="alertdialog" aria-label="确认切换为可见模式" data-testid="exception-visible-confirmation"><strong className="block text-sm font-black text-red-800">确认向业务用户开放{exceptionRolloutDomains.find((item) => item.domain === visibleConfirmation)?.label}异常？</strong><p className="m-0 mt-1 text-xs font-bold leading-5 text-red-700">可见模式会按来源权限与数据范围展示案件。请确认影子期权限、重复案件、通知隔离和规则对账已经验收通过。</p><div className="mt-3 flex gap-2"><Button type="button" secondary onClick={() => setVisibleConfirmation(null)}>取消</Button><Button type="button" onClick={confirmVisibleMode}>确认切换为可见</Button></div></div> : null}
          <div className="grid gap-2 sm:grid-cols-2">
            {([
              ["is_enabled", "启用异常中心策略"],
              ["manual_ai_enabled", "允许人工智能诊断"],
              ["scheduled_ai_enabled", "允许定时智能诊断"],
              ["full_scan_enabled", "启用全量巡检"],
              ["digest_enabled", "启用摘要通知"]
            ] as Array<["is_enabled" | "manual_ai_enabled" | "scheduled_ai_enabled" | "full_scan_enabled" | "digest_enabled", string]>).map(([key, label]) => (
              <label key={key} className="flex items-center justify-between gap-4 rounded-lg border border-border bg-secondary px-4 py-3 text-sm font-black text-foreground">
                {label}<input type="checkbox" checked={form[key]} onChange={(event) => setForm({ ...form, [key]: event.target.checked })} />
              </label>
            ))}
          </div>
          <div className="grid gap-3 md:grid-cols-2">
            <label className="grid gap-1.5 text-xs font-black text-muted-foreground">全量扫描 Cron<input className="project-input-sm" value={form.full_scan_cron} onChange={(event) => setForm({ ...form, full_scan_cron: event.target.value })} /></label>
            <label className="grid gap-1.5 text-xs font-black text-muted-foreground">摘要通知 Cron<input className="project-input-sm" value={form.digest_cron} onChange={(event) => setForm({ ...form, digest_cron: event.target.value })} /></label>
            {([
              ["ai_daily_limit", "每日模型调用上限（0 为不限量）", 0],
              ["ai_batch_limit", "单批诊断上限", 1],
              ["manual_ai_daily_limit", "人工诊断每日上限（0 为不限量）", 0],
              ["scheduled_ai_daily_limit", "定时诊断每日上限（0 为不限量）", 0],
              ["scheduled_ai_batch_limit", "定时诊断单批上限", 1],
              ["ai_concurrency", "模型并发数", 1],
              ["stale_diagnosis_hours", "诊断失效小时数", 1]
            ] as Array<["ai_daily_limit" | "ai_batch_limit" | "manual_ai_daily_limit" | "scheduled_ai_daily_limit" | "scheduled_ai_batch_limit" | "ai_concurrency" | "stale_diagnosis_hours", string, number]>).map(([key, label, min]) => (
              <label key={key} className="grid gap-1.5 text-xs font-black text-muted-foreground">{label}<input type="number" min={min} className="project-input-sm" value={form[key]} onChange={(event) => setForm({ ...form, [key]: Number(event.target.value) })} /></label>
            ))}
          </div>
          <div className="project-drawer-sticky-actions"><Button type="submit" disabled={saving || Boolean(baselineDomain) || !hasChanges}>{saving ? "保存中" : hasChanges ? "保存策略" : "没有待保存修改"}</Button></div>
        </form>
      ) : null}
    </Drawer>
  );
}

const EXCEPTION_BATCH_KEEP = "__keep__";
const EXCEPTION_BATCH_DEFAULT = "__default__";
const EXCEPTION_BATCH_MANUAL = "__manual__";

function ExceptionBatchActions({
  caseNos,
  ignoreBlockedCount,
  permissions,
  onClear,
  onCompleted
}: {
  caseNos: string[];
  ignoreBlockedCount: number;
  permissions: PermissionCode[];
  onClear: () => void;
  onCompleted: (message: string) => void;
}) {
  const [mode, setMode] = useState<"assign" | "ignore">("assign");
  const [assigneeChoice, setAssigneeChoice] = useState(EXCEPTION_BATCH_KEEP);
  const [manualAssigneeId, setManualAssigneeId] = useState("");
  const [dueAt, setDueAt] = useState("");
  const [recalculateDueAt, setRecalculateDueAt] = useState(false);
  const [ignoreReason, setIgnoreReason] = useState("");
  const [ignoreUntil, setIgnoreUntil] = useState(toLocalDateTimeInput());
  const [assignableUsers, setAssignableUsers] = useState<UserPublic[]>([]);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<Error | null>(null);

  useEffect(() => {
    if (ignoreBlockedCount > 0 && mode === "ignore") setMode("assign");
  }, [ignoreBlockedCount, mode]);

  useEffect(() => {
    if (!hasPermission(permissions, "user.view")) return;
    let active = true;
    void users()
      .then((rows) => {
        if (active) setAssignableUsers(rows.filter((row) => row.is_active));
      })
      .catch(() => {
        if (active) setAssignableUsers([]);
      });
    return () => {
      active = false;
    };
  }, [permissions]);

  const manualAssigneeValid = assigneeChoice !== EXCEPTION_BATCH_MANUAL || Number(manualAssigneeId) > 0;
  const assigneeChanged = assigneeChoice !== EXCEPTION_BATCH_KEEP && manualAssigneeValid;
  const dueAtChanged = recalculateDueAt || Boolean(dueAt);
  const canSubmitAssignment = caseNos.length > 0 && manualAssigneeValid && (assigneeChanged || dueAtChanged);

  const submitAssignment = async () => {
    if (!canSubmitAssignment) return;
    const payload: { case_nos: string[]; assignee_user_id?: number | null; due_at?: string | null } = { case_nos: caseNos };
    if (assigneeChoice === EXCEPTION_BATCH_DEFAULT) payload.assignee_user_id = null;
    else if (assigneeChoice === EXCEPTION_BATCH_MANUAL) payload.assignee_user_id = Number(manualAssigneeId);
    else if (assigneeChoice !== EXCEPTION_BATCH_KEEP) payload.assignee_user_id = Number(assigneeChoice);
    if (recalculateDueAt) payload.due_at = null;
    else if (dueAt) payload.due_at = new Date(dueAt).toISOString();
    setBusy(true);
    setError(null);
    try {
      const result = await batchAssignExceptionCases(payload);
      onCompleted(`已更新 ${result.updated_count} 条异常案件的负责人或处理时限。`);
    } catch (reason) {
      setError(normalizeUiError(reason, "批量分派失败"));
    } finally {
      setBusy(false);
    }
  };

  const submitIgnore = async () => {
    if (caseNos.length === 0 || ignoreBlockedCount > 0 || ignoreReason.trim().length < 2 || !ignoreUntil) return;
    setBusy(true);
    setError(null);
    try {
      const result = await batchIgnoreExceptionCases({
        case_nos: caseNos,
        reason: ignoreReason.trim(),
        ignored_until: new Date(ignoreUntil).toISOString()
      });
      onCompleted(`已忽略 ${result.updated_count} 条异常案件，到期后将重新进入待处理范围。`);
    } catch (reason) {
      setError(normalizeUiError(reason, "批量忽略失败"));
    } finally {
      setBusy(false);
    }
  };

  return (
    <section className="border-b border-border bg-slate-50 px-3 py-3 sm:px-4" data-testid="exception-batch-toolbar" aria-label="异常案件批量操作">
      <div className="flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between">
        <div className="flex min-w-0 items-center gap-2">
          <ListChecks className="h-4 w-4 shrink-0 text-primary" />
          <strong className="text-sm font-black text-foreground">已选 {caseNos.length} 条</strong>
          <span className="hidden text-xs font-bold text-muted-foreground sm:inline">批量操作对当前选中案件一次生效</span>
        </div>
        <div className="flex flex-wrap gap-2" role="group" aria-label="选择批量操作">
          <button type="button" aria-pressed={mode === "assign"} onClick={() => { setMode("assign"); setError(null); }} className={`project-button-secondary whitespace-nowrap px-3 ${mode === "assign" ? "border-primary bg-primary-soft text-primary" : ""}`}>分派与期限</button>
          <button type="button" aria-pressed={mode === "ignore"} disabled={ignoreBlockedCount > 0} title={ignoreBlockedCount > 0 ? "处理中案件不能忽略，请取消选择后重试" : undefined} onClick={() => { setMode("ignore"); setError(null); }} className={`project-button-secondary whitespace-nowrap px-3 ${mode === "ignore" ? "border-primary bg-primary-soft text-primary" : ""}`}>批量忽略</button>
          <button type="button" onClick={onClear} className="project-button-secondary whitespace-nowrap px-3">取消选择</button>
        </div>
      </div>

      {ignoreBlockedCount > 0 ? <p className="m-0 mt-2 text-xs font-black text-amber-700" data-testid="exception-batch-ignore-blocked">已选 {ignoreBlockedCount} 条处理中案件；可批量分派或调整期限，但不能批量忽略。</p> : null}

      {error ? <div className="mt-3"><ApiErrorNotice error={error} /></div> : null}

      {mode === "assign" ? (
        <div className="mt-3 grid gap-3 border-t border-border pt-3 md:grid-cols-2 xl:grid-cols-[minmax(220px,1fr)_minmax(180px,0.8fr)_auto] xl:items-end" data-testid="exception-batch-assign">
          <label className="grid min-w-0 gap-1.5 text-xs font-black text-muted-foreground">负责人
            <select className="project-input-sm w-full" data-testid="exception-batch-assignee" value={assigneeChoice} onChange={(event) => setAssigneeChoice(event.target.value)}>
              <option value={EXCEPTION_BATCH_KEEP}>保持现负责人</option>
              <option value={EXCEPTION_BATCH_DEFAULT}>恢复默认自动分派</option>
              {assignableUsers.map((row) => <option key={row.id} value={row.id}>{row.real_name}（{row.username}）</option>)}
              <option value={EXCEPTION_BATCH_MANUAL}>指定账号 ID</option>
            </select>
          </label>
          {assigneeChoice === EXCEPTION_BATCH_MANUAL ? (
            <label className="grid min-w-0 gap-1.5 text-xs font-black text-muted-foreground">负责人账号 ID
              <input type="number" min="1" className="project-input-sm w-full" value={manualAssigneeId} onChange={(event) => setManualAssigneeId(event.target.value)} placeholder="输入正整数 ID" />
            </label>
          ) : null}
          <div className="grid min-w-0 gap-1.5">
            <label className="grid gap-1.5 text-xs font-black text-muted-foreground">处理时限
              <input type="datetime-local" className="project-input-sm w-full" data-testid="exception-batch-due-at" value={dueAt} disabled={recalculateDueAt} onChange={(event) => { setDueAt(event.target.value); setRecalculateDueAt(false); }} />
            </label>
            <label className="inline-flex min-h-6 items-center gap-2 text-xs font-bold text-muted-foreground"><input type="checkbox" data-testid="exception-batch-recalculate-due" checked={recalculateDueAt} onChange={(event) => { setRecalculateDueAt(event.target.checked); if (event.target.checked) setDueAt(""); }} />按 SLA 重新计算</label>
          </div>
          <div className="flex flex-wrap items-center gap-2 md:col-span-2 xl:col-span-1 xl:justify-end">
            <span className="text-xs font-bold text-muted-foreground">未填项保持原值；默认项由系统回填</span>
            <Button disabled={busy || !canSubmitAssignment} onClick={() => void submitAssignment()}>{busy ? "提交中" : "应用更新"}</Button>
          </div>
        </div>
      ) : (
        <div className="mt-3 grid gap-3 border-t border-border pt-3 md:grid-cols-2 xl:grid-cols-[minmax(280px,1fr)_minmax(200px,0.7fr)_auto] xl:items-end" data-testid="exception-batch-ignore">
          <label className="grid min-w-0 gap-1.5 text-xs font-black text-muted-foreground">忽略原因
            <textarea className="project-input-sm min-h-20 w-full py-2" data-testid="exception-batch-ignore-reason" maxLength={1000} value={ignoreReason} onChange={(event) => setIgnoreReason(event.target.value)} placeholder="说明这些案件当前为什么无需处理" />
          </label>
          <label className="grid min-w-0 gap-1.5 text-xs font-black text-muted-foreground">忽略至
            <input type="datetime-local" className="project-input-sm w-full" data-testid="exception-batch-ignore-until" value={ignoreUntil} onChange={(event) => setIgnoreUntil(event.target.value)} />
          </label>
          <div className="flex xl:justify-end"><Button secondary disabled={busy || ignoreBlockedCount > 0 || ignoreReason.trim().length < 2 || !ignoreUntil} onClick={() => void submitIgnore()}>{busy ? "提交中" : "确认批量忽略"}</Button></div>
        </div>
      )}
    </section>
  );
}

function exceptionRuntimeTone(status?: string | null): "ok" | "warn" | "bad" | "neutral" {
  if (["healthy", "running", "closed", "completed", "online"].includes(status ?? "")) return "ok";
  if (["failed", "open", "offline", "stalled"].includes(status ?? "")) return "bad";
  if (["degraded", "queued", "processing", "half_open", "stale"].includes(status ?? "")) return "warn";
  return "neutral";
}

function ExceptionOperationsPanel({ permissions }: { permissions: PermissionCode[] }) {
  const [summaryData, setSummaryData] = useState<ExceptionOpsSummary | null>(null);
  const [globalAgentStatus, setGlobalAgentStatus] = useState<CrmAssistantAgentStatus | null>(null);
  const [jobsData, setJobsData] = useState<ExceptionDiagnosisJobPage | null>(null);
  const [jobStatus, setJobStatus] = useState("");
  const [jobKind, setJobKind] = useState<"diagnosis" | "background" | "">("");
  const [jobOffset, setJobOffset] = useState(0);
  const [loading, setLoading] = useState(true);
  const [busyJob, setBusyJob] = useState("");
  const [cancelTarget, setCancelTarget] = useState<ExceptionJobItem | null>(null);
  const [cancelReason, setCancelReason] = useState("");
  const [error, setError] = useState<Error | null>(null);
  const loadControllerRef = useRef<AbortController | null>(null);
  const loadSequenceRef = useRef(0);
  const latestLoadRef = useRef<() => Promise<void>>(async () => undefined);
  const canManagePolicy = hasPermission(permissions, "exception_center.policy_manage");
  const canViewGlobalRuntime = hasPermission(permissions, "crm_insight.view");
  const canReadJobs = canManagePolicy;
  const canOperateJobs = canManagePolicy;
  const jobLimit = 30;
  const load = useCallback(async () => {
    const sequence = ++loadSequenceRef.current;
    loadControllerRef.current?.abort();
    if (!canManagePolicy) {
      loadControllerRef.current = null;
      setSummaryData(null);
      setJobsData({ items: [], total: 0, limit: jobLimit, offset: 0 });
      setLoading(false);
      return;
    }
    const controller = new AbortController();
    loadControllerRef.current = controller;
    setLoading(true);
    setError(null);
    const jobQuery = { status: jobStatus || undefined, limit: jobLimit, offset: jobOffset };
    const jobsRequest: Promise<ExceptionDiagnosisJobPage> = !canReadJobs
      ? Promise.resolve({ items: [], total: 0, limit: jobLimit, offset: 0 })
      : exceptionDiagnosisJobsPage({ ...jobQuery, job_kind: jobKind || "all" }, controller.signal);
    try {
      const [summary, jobs, agentStatus] = await Promise.all([
        exceptionOpsSummary(controller.signal),
        jobsRequest,
        canViewGlobalRuntime ? crmAssistantAgentStatus(controller.signal).catch(() => null) : Promise.resolve(null)
      ]);
      if (controller.signal.aborted || sequence !== loadSequenceRef.current) return;
      setSummaryData(summary);
      setGlobalAgentStatus(agentStatus);
      const lastOffset = jobs.total > 0 ? Math.floor((jobs.total - 1) / jobLimit) * jobLimit : 0;
      if (jobOffset > lastOffset) setJobOffset(lastOffset);
      else setJobsData(jobs);
    } catch (reason) {
      if (!isAbortError(reason) && sequence === loadSequenceRef.current) {
        setError(normalizeUiError(reason, "异常中心运维状态加载失败"));
      }
    } finally {
      if (sequence === loadSequenceRef.current) {
        setLoading(false);
        if (loadControllerRef.current === controller) loadControllerRef.current = null;
      }
    }
  }, [canManagePolicy, canReadJobs, canViewGlobalRuntime, jobStatus, jobKind, jobOffset]);
  latestLoadRef.current = load;
  useEffect(() => {
    void load();
    return () => loadControllerRef.current?.abort();
  }, [load]);
  useEffect(() => {
    if (!canManagePolicy) return;
    const timer = window.setInterval(() => void load(), 30_000);
    return () => window.clearInterval(timer);
  }, [canManagePolicy, load]);

  const applyJobMutation = (next: ExceptionDiagnosisJob) => {
    setJobsData((current) => current ? {
      ...current,
      items: current.items.map((row) => row.job_kind === "diagnosis" && row.id === next.id ? {
        ...row,
        status: next.status as ExceptionJobItem["status"],
        attempts: next.attempts ?? next.attempt_count ?? row.attempts,
        available_at: next.available_at,
        lease_owner: next.lease_owner,
        lease_expires_at: next.lease_expires_at,
        error_message: next.error_message,
        started_at: next.started_at,
        completed_at: next.completed_at
      } : row)
    } : current);
  };

  const retryJob = async (job: ExceptionJobItem) => {
    if (!canOperateJobs || job.job_kind !== "diagnosis") return;
    setBusyJob(`retry-${job.id}`);
    setError(null);
    try {
      const next = await retryExceptionDiagnosisJob(job.id, "异常中心运维人员手动重试");
      applyJobMutation(next);
      await latestLoadRef.current();
    } catch (reason) {
      setError(normalizeUiError(reason, "任务重试失败"));
    } finally {
      setBusyJob("");
    }
  };

  const confirmCancelJob = async () => {
    if (!canOperateJobs || !cancelTarget || cancelTarget.job_kind !== "diagnosis" || cancelReason.trim().length < 2) return;
    setBusyJob(`cancel-${cancelTarget.id}`);
    setError(null);
    try {
      const next = await cancelExceptionDiagnosisJob(cancelTarget.id, cancelReason.trim());
      applyJobMutation(next);
      setCancelTarget(null);
      setCancelReason("");
      await latestLoadRef.current();
    } catch (reason) {
      setError(normalizeUiError(reason, "任务取消失败"));
    } finally {
      setBusyJob("");
    }
  };

  const heartbeatFor = (type: "scheduler" | "worker" | "ai_worker") => summaryData?.heartbeats.find((item) => item.service_type === type);
  const schedulerHeartbeat = heartbeatFor("scheduler");
  const workerHeartbeat = heartbeatFor("worker");
  const aiHeartbeat = heartbeatFor("ai_worker");
  const heartbeatStatus = (heartbeat: typeof schedulerHeartbeat) => heartbeat ? heartbeat.is_stale || heartbeat.is_healthy === false ? "stalled" : "healthy" : "unknown";
  const diagnosisQueued = Number(summaryData?.diagnosis_jobs_by_status.queued ?? 0);
  const diagnosisProcessing = Number(summaryData?.diagnosis_jobs_by_status.processing ?? 0);
  const diagnosisFailed = Number(summaryData?.diagnosis_jobs_by_status.failed ?? 0);
  const backgroundQueued = Number(summaryData?.background_jobs_by_status.queued ?? 0);
  const backgroundProcessing = Number(summaryData?.background_jobs_by_status.processing ?? 0);
  const backgroundFailed = Number(summaryData?.background_jobs_by_status.failed ?? 0);
  const completed24h = Number(summaryData?.diagnosis_completed_24h ?? 0);
  const failed24h = Number(summaryData?.diagnosis_failed_24h ?? 0);
  const successRate24h = completed24h + failed24h > 0 ? completed24h / (completed24h + failed24h) : null;
  const circuit = summaryData?.circuit ?? null;
  const circuitState = circuit == null ? "unavailable" : circuit.stale ? "stale" : circuit.open ? "open" : "closed";
  const circuitLabel = circuitState === "closed" ? "正常" : circuitState === "open" ? "已熔断" : circuitState === "stale" ? "状态已过期" : "状态不可用";
  return (
    <div className="grid gap-4" data-testid="exception-operations-panel">
      <section className="overflow-hidden rounded-lg border border-border bg-white">
        <div className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-4 py-3"><div><h2 className="m-0 text-base font-black text-foreground">巡检与诊断运行状态</h2><p className="m-0 mt-1 text-xs font-bold text-muted-foreground">每 30 秒刷新心跳、队列、预算、熔断和最近扫描结果。</p></div><Button secondary disabled={loading} onClick={load}><RefreshCcw className={`mr-1.5 h-4 w-4 ${loading ? "animate-spin" : ""}`} />刷新</Button></div>
        {error ? <div className="p-4"><ApiErrorNotice error={error} onRetry={load} /></div> : null}
        {loading && !summaryData ? <div className="grid gap-2 p-4 sm:grid-cols-2 xl:grid-cols-4">{Array.from({ length: 4 }).map((_, index) => <div key={index} className="h-20 animate-pulse rounded-md bg-secondary" />)}</div> : null}
        {summaryData ? <>
          <div className="grid sm:grid-cols-2 xl:grid-cols-5">
            {[
              { label: "调度服务", value: heartbeatStatus(schedulerHeartbeat), detail: formatDateTime(schedulerHeartbeat?.last_heartbeat_at), tone: exceptionRuntimeTone(heartbeatStatus(schedulerHeartbeat)) },
              { label: "后台 Worker", value: heartbeatStatus(workerHeartbeat), detail: formatDateTime(workerHeartbeat?.last_heartbeat_at), tone: exceptionRuntimeTone(heartbeatStatus(workerHeartbeat)) },
              { label: "AI Worker", value: heartbeatStatus(aiHeartbeat), detail: formatDateTime(aiHeartbeat?.last_heartbeat_at), tone: exceptionRuntimeTone(heartbeatStatus(aiHeartbeat)) },
              { label: "诊断队列", value: `${diagnosisQueued + diagnosisProcessing} 项`, detail: `排队 ${diagnosisQueued} · 处理中 ${diagnosisProcessing} · 失败 ${diagnosisFailed}`, tone: diagnosisFailed > 0 ? "bad" as const : "neutral" as const },
              { label: "后台队列", value: `${backgroundQueued + backgroundProcessing} 项`, detail: `排队 ${backgroundQueued} · 处理中 ${backgroundProcessing} · 失败 ${backgroundFailed}`, tone: backgroundFailed > 0 ? "bad" as const : "neutral" as const }
            ].map((item) => <div key={item.label} className="min-w-0 border-b border-r border-border px-4 py-3"><div className="flex items-center justify-between gap-2"><span className="text-xs font-black text-muted-foreground">{item.label}</span><Badge tone={item.tone}>{item.value}</Badge></div><strong className="mt-2 block truncate text-sm text-foreground">{item.detail}</strong></div>)}
          </div>
          <div className="grid gap-0 border-t border-border lg:grid-cols-2">
            <div className="px-4 py-3 lg:border-r lg:border-border"><h3 className="m-0 text-sm font-black text-foreground">模型用量与熔断</h3><dl className="mt-3 grid grid-cols-2 gap-3 text-sm"><div><dt className="text-xs font-bold text-muted-foreground">人工诊断</dt><dd className="m-0 mt-1 font-mono font-black">{summaryData.manual_budget.used} / {summaryData.manual_budget.unlimited ? "不限量" : summaryData.manual_budget.limit}</dd></div><div><dt className="text-xs font-bold text-muted-foreground">定时诊断</dt><dd className="m-0 mt-1 font-mono font-black">{summaryData.scheduled_budget.used} / {summaryData.scheduled_budget.unlimited ? "不限量" : summaryData.scheduled_budget.limit}</dd></div><div><dt className="text-xs font-bold text-muted-foreground">模型服务</dt><dd className="m-0 mt-1 truncate font-bold">{summaryData.provider_configured ? summaryData.model ?? "已配置" : "未配置"}</dd></div><div data-testid="exception-circuit-status" data-circuit-state={circuitState}><dt className="text-xs font-bold text-muted-foreground">熔断状态</dt><dd className="m-0 mt-1"><Badge tone={exceptionRuntimeTone(circuitState)}>{circuitLabel}</Badge>{circuit ? <><span className="mt-1 block text-xs font-bold text-muted-foreground">连续失败 {circuit.consecutive_failures} · 重试等待 {circuit.retry_after_seconds} 秒</span><span className="mt-1 block text-xs font-bold text-muted-foreground">{circuit.stale ? `AI Worker 上报已过期 · 上次状态${circuit.open ? "已熔断" : "正常"}` : "AI Worker 状态有效"} · 来源 {circuit.source}</span></> : <span className="mt-1 block text-xs font-bold text-muted-foreground">暂无 AI Worker 熔断状态，不能判定服务正常。</span>}</dd></div></dl></div>
            <div className="px-4 py-3"><h3 className="m-0 text-sm font-black text-foreground">最近一次全量扫描</h3><div className="mt-3 flex flex-wrap items-center gap-2"><Badge tone={failed24h > 0 ? "warn" : "ok"}>24h 成功率 {successRate24h == null ? "-" : `${Math.round(successRate24h * 100)}%`}</Badge><span className="text-xs font-bold text-muted-foreground">完成 {formatDateTime(summaryData.last_full_scan_at)} · 耗时 {summaryData.last_scan_duration_ms == null ? "-" : `${summaryData.last_scan_duration_ms} ms`}</span></div><p className="m-0 mt-3 text-sm font-bold text-foreground">扫描 {summaryData.last_scan_scanned ?? 0} · 新建 {summaryData.last_scan_created ?? 0} · 新增 {summaryData.last_scan_new ?? 0} · 复发 {summaryData.last_scan_reopened ?? 0} · 证据更新 {summaryData.last_scan_evidence_updated ?? 0} · 解决 {summaryData.last_scan_resolved ?? 0}</p></div>
          </div>
        </> : null}
      </section>

      {canViewGlobalRuntime ? <section className="overflow-hidden rounded-lg border border-border bg-white" data-testid="global-ai-runtime-summary">
        <div className="border-b border-border px-4 py-3"><h2 className="m-0 text-base font-black text-foreground">全局 AI 模型与技能调用</h2><p className="m-0 mt-1 text-xs font-bold text-muted-foreground">原 AI 协同页的模型、技能和调用统计已统一归入运行运维。</p></div>
        <div className="grid sm:grid-cols-2 xl:grid-cols-4">
          <div className="border-b border-r border-border px-4 py-3"><span className="text-xs font-black text-muted-foreground">模型</span><strong className="mt-2 block text-sm text-foreground">{globalAgentStatus?.runtime.configured ? globalAgentStatus.runtime.model ?? "GLM-5.2" : "规则兜底"}</strong></div>
          <div className="border-b border-r border-border px-4 py-3"><span className="text-xs font-black text-muted-foreground">技能数</span><strong className="mt-2 block font-mono text-lg text-foreground">{globalAgentStatus?.runtime.skills.length ?? 0}</strong></div>
          <div className="border-b border-r border-border px-4 py-3"><span className="text-xs font-black text-muted-foreground">累计调用</span><strong className="mt-2 block font-mono text-lg text-foreground">{Object.values(globalAgentStatus?.operation_counts ?? {}).reduce((sum, count) => sum + count, 0)}</strong></div>
          <div className="border-b border-border px-4 py-3"><span className="text-xs font-black text-muted-foreground">最近调用</span><strong className="mt-2 block text-sm text-foreground">{formatDateTime(globalAgentStatus?.last_call_at)}</strong></div>
        </div>
        {globalAgentStatus && Object.keys(globalAgentStatus.operation_counts).length ? <div className="flex flex-wrap gap-2 px-4 py-3">{Object.entries(globalAgentStatus.operation_counts).map(([operation, count]) => <span key={operation} className="inline-flex min-h-8 items-center rounded-md border border-border bg-secondary px-3 font-mono text-xs font-bold text-muted-foreground">{operation} · {count}</span>)}</div> : <p className="m-0 px-4 py-4 text-sm font-bold text-muted-foreground">暂无全局 AI 调用记录。</p>}
      </section> : null}

      <DataTableShell title="异常任务队列" description={canReadJobs ? "统一查看智能诊断与后台扫描任务。诊断任务取消必须填写审计原因。" : "当前账号可查看运行状态，但没有诊断任务读取权限。"} meta={jobsData ? `${jobsData.total} 项` : "正在加载"} toolbar={canReadJobs ? <DataToolbar onReset={() => { setJobStatus(""); setJobKind(""); setJobOffset(0); }}><ToolbarSelect label="任务类型" value={jobKind} onChange={(value) => { setJobKind(value as "diagnosis" | "background" | ""); setJobOffset(0); }} options={[{ value: "", label: "全部队列" }, { value: "diagnosis", label: "智能诊断" }, { value: "background", label: "后台扫描" }]} /><ToolbarSelect label="任务状态" value={jobStatus} onChange={(value) => { setJobStatus(value); setJobOffset(0); }} options={[{ value: "", label: "全部状态" }, { value: "queued", label: "排队中" }, { value: "processing", label: "执行中" }, { value: "failed", label: "失败" }, { value: "completed", label: "已完成" }, { value: "cancelled", label: "已取消" }]} /></DataToolbar> : null}>
        {cancelTarget ? <div className="border-b border-amber-200 bg-amber-50 px-4 py-3" data-testid="exception-job-cancel-confirm"><div className="flex flex-col gap-3 lg:flex-row lg:items-end"><label className="grid min-w-0 flex-1 gap-1.5 text-xs font-black text-amber-900">取消原因<textarea className="project-input-sm min-h-16 w-full bg-white py-2" data-testid="exception-job-cancel-reason" maxLength={1000} value={cancelReason} onChange={(event) => setCancelReason(event.target.value)} placeholder={`说明取消任务 ${cancelTarget.job_no} 的原因，至少 2 个字符`} /></label><div className="flex gap-2"><Button secondary onClick={() => { setCancelTarget(null); setCancelReason(""); }}>返回</Button><Button disabled={cancelReason.trim().length < 2 || busyJob === `cancel-${cancelTarget.id}`} onClick={() => void confirmCancelJob()}>{busyJob ? "取消中" : "确认取消"}</Button></div></div></div> : null}
        <Table headers={["任务", "关联案件", "状态", "尝试与租约", "时间", "操作"]} minWidth={980} emptyMessage="当前没有异常任务。">
          {(jobsData?.items ?? []).map((job) => <tr key={`${job.job_kind}-${job.id}`}><td><strong className="block font-mono text-xs text-foreground">{job.job_no}</strong><small className="mt-1 block text-xs font-bold text-muted-foreground">{job.job_kind === "diagnosis" ? "智能诊断" : "后台任务"} · {job.job_type}</small></td><td><strong className="block text-sm text-foreground">{job.case_no ?? "全局任务"}</strong><small className="mt-1 block font-mono text-xs text-muted-foreground">{job.evidence_version ?? job.trigger_type ?? "-"}</small></td><td><Badge tone={exceptionRuntimeTone(job.status)}>{job.status}</Badge>{job.error_message ? <small className="mt-1 block max-w-[260px] text-xs font-bold text-red-700">{job.error_message}</small> : null}</td><td><span className="text-sm font-black text-foreground">{job.attempts} 次</span><small className="mt-1 block text-xs text-muted-foreground">租约至 {formatDateTime(job.lease_expires_at)}</small></td><td><span className="text-sm font-bold text-foreground">{formatDateTime(job.created_at)}</span><small className="mt-1 block text-xs text-muted-foreground">可执行 {formatDateTime(job.available_at)}</small></td><td><div className="flex gap-2">{canOperateJobs && job.job_kind === "diagnosis" && ["failed", "cancelled"].includes(job.status) ? <button type="button" className="project-icon-button" title="重试任务" aria-label={`重试任务 ${job.job_no}`} disabled={Boolean(busyJob)} onClick={() => void retryJob(job)}><RotateCcw className="h-4 w-4" /></button> : null}{canOperateJobs && job.job_kind === "diagnosis" && ["queued", "processing"].includes(job.status) ? <button type="button" className="project-icon-button" title="取消任务" aria-label={`取消任务 ${job.job_no}`} disabled={Boolean(busyJob)} onClick={() => { setCancelTarget(job); setCancelReason(""); }}><X className="h-4 w-4" /></button> : null}{job.job_kind === "background" ? <span className="text-xs font-bold text-muted-foreground">只读</span> : null}</div></td></tr>)}
        </Table>
        {canReadJobs && jobsData && jobsData.total > jobLimit ? <div className="flex flex-col gap-2 border-t border-border px-4 py-3 sm:flex-row sm:items-center sm:justify-between" data-testid="exception-job-pagination"><span className="text-xs font-bold text-muted-foreground">第 {Math.floor(jobOffset / jobLimit) + 1} 页，共 {Math.ceil(jobsData.total / jobLimit)} 页 · {jobsData.total} 项</span><div className="flex gap-2"><Button secondary disabled={loading || jobOffset === 0} onClick={() => setJobOffset(Math.max(0, jobOffset - jobLimit))}>上一页</Button><Button secondary disabled={loading || jobOffset + jobLimit >= jobsData.total} onClick={() => setJobOffset(jobOffset + jobLimit)}>下一页</Button></div></div> : null}
      </DataTableShell>
    </div>
  );
}

function ExceptionDiagnosisQualityPanel({ permissions }: { permissions: PermissionCode[] }) {
  const [data, setData] = useState<ExceptionDiagnosisQuality | null>(null);
  const [error, setError] = useState<Error | null>(null);
  const [loading, setLoading] = useState(true);
  const [rolloutData, setRolloutData] = useState<ExceptionRuleQualityResponse | null>(null);
  const [rolloutError, setRolloutError] = useState<Error | null>(null);
  const [rolloutLoading, setRolloutLoading] = useState(true);
  const [rolloutRefreshKey, setRolloutRefreshKey] = useState(0);
  const [diagnosedFrom, setDiagnosedFrom] = useState("");
  const [diagnosedTo, setDiagnosedTo] = useState("");
  const [qualityQuery, setQualityQuery] = useState<{ diagnosed_from?: string; diagnosed_to?: string }>({});
  const [filterError, setFilterError] = useState("");
  const canManagePolicy = hasPermission(permissions, "exception_center.policy_manage");
  useEffect(() => {
    const controller = new AbortController();
    if (!canManagePolicy) {
      setRolloutData(null);
      setRolloutLoading(false);
      return () => controller.abort();
    }
    setRolloutLoading(true);
    setRolloutError(null);
    void exceptionRuleQuality({ scan_window_days: 30 }).then((response) => {
      if (controller.signal.aborted) return;
      setRolloutData(response);
    }).catch((reason) => {
      if (!isAbortError(reason) && !controller.signal.aborted) {
        setRolloutError(normalizeUiError(reason, "CRM / 审批规则命中统计加载失败"));
      }
    }).finally(() => {
      if (!controller.signal.aborted) setRolloutLoading(false);
    });
    return () => controller.abort();
  }, [canManagePolicy, rolloutRefreshKey]);
  const load = (query = qualityQuery) => {
    if (!canManagePolicy) {
      setData(null);
      setLoading(false);
      return;
    }
    setLoading(true);
    setError(null);
    void exceptionDiagnosisQuality(query).then(setData).catch((reason) => setError(normalizeUiError(reason, "诊断质量报表加载失败"))).finally(() => setLoading(false));
  };
  useEffect(() => load(qualityQuery), [canManagePolicy, qualityQuery]);
  const applyQualityFilters = () => {
    const start = diagnosedFrom ? new Date(diagnosedFrom) : null;
    const end = diagnosedTo ? new Date(diagnosedTo) : null;
    if ((start && Number.isNaN(start.getTime())) || (end && Number.isNaN(end.getTime()))) {
      setFilterError("请输入有效的诊断时间。");
      return;
    }
    if (start && end && start > end) {
      setFilterError("诊断开始时间不能晚于结束时间。");
      return;
    }
    setFilterError("");
    setQualityQuery({
      diagnosed_from: start?.toISOString(),
      diagnosed_to: end?.toISOString()
    });
  };
  const clearQualityFilters = () => {
    setDiagnosedFrom("");
    setDiagnosedTo("");
    setFilterError("");
    setQualityQuery({});
  };
  const percent = (value?: number | null) => value == null ? "-" : `${Math.round(value * (value <= 1 ? 100 : 1))}%`;
  const feedbackRate = data?.feedback_coverage_rate ?? data?.feedback_rate;
  const positiveRate = data?.positive_rate ?? data?.helpful_rate;
  const helpfulCount = data?.helpful ?? data?.by_feedback.helpful ?? 0;
  const partialCount = data?.partial ?? data?.by_feedback.partial ?? 0;
  const incorrectCount = data?.incorrect ?? data?.by_feedback.incorrect ?? 0;
  const tokenUsageLabel = !data
    ? "-"
    : data.total_diagnoses > 0 && data.usage_reported_count === 0
      ? "未上报"
      : `${Number(data.total_tokens ?? 0).toLocaleString()} Token`;
  const qualityRules: ExceptionDiagnosisQualityRule[] = data?.rules?.length
    ? data.rules
    : (data?.by_rule ?? []).map((row) => ({
        domain: null,
        rule_code: row.key,
        diagnoses: row.diagnoses,
        feedback_count: row.rated,
        helpful: row.helpful,
        partial: row.partial,
        incorrect: row.incorrect,
        helpful_rate: row.positive_rate,
        average_confidence: row.average_confidence
      }));
  return (
    <div className="grid gap-4" data-testid="exception-diagnosis-quality">
      <section className="overflow-hidden rounded-lg border border-border bg-white" data-testid="exception-rollout-rule-quality">
        <div className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-4 py-3"><div><h2 className="m-0 text-base font-black text-foreground">CRM / 审批规则质量</h2><p className="m-0 mt-1 text-xs font-bold text-muted-foreground">当前权限范围内的规则命中与案件状态统计，不是错误率或误报率指标。</p></div><Button secondary disabled={rolloutLoading} onClick={() => setRolloutRefreshKey((value) => value + 1)}><RefreshCcw className={`mr-1.5 h-4 w-4 ${rolloutLoading ? "animate-spin" : ""}`} />刷新规则统计</Button></div>
        {rolloutError ? <div className="p-4"><ApiErrorNotice error={rolloutError} onRetry={() => setRolloutRefreshKey((value) => value + 1)} /></div> : null}
        {rolloutLoading && !rolloutData ? <div className="grid gap-3 p-4 md:grid-cols-2">{exceptionRolloutDomains.map(({ domain }) => <div key={domain} className="h-36 animate-pulse rounded-md bg-secondary" />)}</div> : null}
        {rolloutData ? <>
          <div className="border-b border-border bg-secondary/40 px-4 py-2 text-xs font-bold text-muted-foreground">统计窗口 {rolloutData.scan_job_window_days} 天 · {formatDateTime(rolloutData.scan_job_window_start)} 至 {formatDateTime(rolloutData.scan_job_window_end)} · 生成于 {formatDateTime(rolloutData.generated_at)}</div>
          <div className="grid md:grid-cols-2">{exceptionRolloutDomains.map(({ domain, label }, index) => {
          const domainData = rolloutData.domains.find((item) => item.domain === domain);
          const domainRules = rolloutData.rules.filter((item) => item.domain === domain);
          const mode = domainData?.domain_mode ?? "off";
          return <div key={domain} className={`min-w-0 p-4 ${index === 0 ? "border-b border-border md:border-b-0 md:border-r" : ""}`} data-testid={`exception-rollout-domain-${domain}`}>
            <div className="flex items-center justify-between gap-3"><div><strong className="block text-sm font-black text-foreground">{label}</strong><span className="mt-0.5 block text-xs font-bold text-muted-foreground">已保存模式</span></div><Badge tone={mode === "visible" ? "ok" : mode === "shadow" ? "warn" : "neutral"}>{exceptionDomainModeLabels[mode]}</Badge></div>
            <dl className="mt-3 grid grid-cols-2 gap-px overflow-hidden rounded-md border border-border bg-border sm:grid-cols-3">
              {[
                ["规则数", domainRules.length],
                ["活动案件", domainData?.active ?? 0],
                ["存量", domainData?.baseline ?? 0],
                ["新增", domainData?.new ?? 0],
                ["复发", domainData?.reopened ?? 0],
                ["证据变化", domainData?.evidence_changed_events ?? 0]
              ].map(([metric, value]) => <div key={String(metric)} className="bg-white px-3 py-2"><dt className="text-xs font-bold text-muted-foreground">{metric}</dt><dd className="m-0 mt-1 font-mono text-sm font-black text-foreground">{value}</dd></div>)}
            </dl>
            <div className="mt-3 rounded-md border border-border bg-secondary/40 px-3 py-2.5" data-testid={`exception-scan-metrics-${domain}`}>
              <div className="flex items-center justify-between gap-3"><strong className="text-xs font-black text-foreground">后台扫描任务</strong><Badge tone={domainData?.scan_job_metrics_available ? "ok" : "neutral"}>{domainData?.scan_job_metrics_available ? "指标可用" : "指标不可用"}</Badge></div>
              <p className="m-0 mt-1.5 text-xs font-bold text-slate-600">排队 {domainData?.queued_scan_jobs ?? "-"} · 失败 {domainData?.failed_scan_jobs ?? "-"} · P95 {domainData?.scan_latency_p95_ms == null ? "-" : `${domainData.scan_latency_p95_ms} ms`}</p>
              {!domainData?.scan_job_metrics_available ? <p className="m-0 mt-1 text-xs font-bold text-muted-foreground">当前数据范围不能安全汇总全局后台任务，案件质量统计仍按可见范围展示。</p> : null}
            </div>
            {domainRules.length === 0 ? <p className="m-0 mt-3 rounded-md bg-secondary px-3 py-2 text-xs font-bold text-muted-foreground">当前范围没有该业务域的规则命中。</p> : <div className="mt-3 grid gap-2">{domainRules.slice(0, 6).map((row) => (
              <div key={`${row.rule_code}:${row.rule_version}`} className="rounded-md border border-border px-3 py-2" data-testid={`exception-rule-quality-${row.rule_code}`}>
                <div className="flex min-w-0 items-center justify-between gap-3 text-xs"><span className="min-w-0 truncate font-mono font-bold text-slate-700" title={row.rule_code}>{row.rule_code}</span><span className="shrink-0 font-mono font-black text-primary">v{row.rule_version}</span></div>
                <p className="m-0 mt-1 text-xs font-bold text-muted-foreground">活动 {row.active} · 新增 {row.new} · 复发 {row.reopened} · 证据变化 {row.evidence_changed_events}</p>
              </div>
            ))}</div>}
            {domainRules.length > 6 ? <p className="m-0 mt-2 text-xs font-bold text-muted-foreground">其余 {domainRules.length - 6} 条规则可在案件列表按规则筛选查看。</p> : null}
            {domainData?.latest_seen_at ? <p className="m-0 mt-2 text-xs font-bold text-muted-foreground">最近命中 {formatDateTime(domainData.latest_seen_at)}</p> : null}
          </div>;
        })}</div></> : null}
      </section>
      {error ? <ApiErrorNotice error={error} onRetry={() => load()} /> : null}
      <section className="overflow-hidden rounded-lg border border-border bg-white">
        <div className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-4 py-3"><div><h2 className="m-0 text-base font-black text-foreground">诊断质量与反馈</h2><p className="m-0 mt-1 text-xs font-bold text-muted-foreground">反馈只评价诊断解释，不改变确定性异常结论。</p></div><Button secondary disabled={loading} onClick={() => load()}><RefreshCcw className={`mr-1.5 h-4 w-4 ${loading ? "animate-spin" : ""}`} />刷新</Button></div>
        <div className="border-b border-border bg-secondary/40 px-4 py-3" data-testid="exception-quality-time-filter">
          <div className="flex flex-col gap-3 lg:flex-row lg:items-end">
            <label className="grid min-w-0 flex-1 gap-1.5 text-xs font-black text-muted-foreground">诊断开始时间
              <input type="datetime-local" className="project-input-sm bg-white" value={diagnosedFrom} max={diagnosedTo || undefined} onChange={(event) => { setDiagnosedFrom(event.target.value); setFilterError(""); }} />
            </label>
            <label className="grid min-w-0 flex-1 gap-1.5 text-xs font-black text-muted-foreground">诊断结束时间
              <input type="datetime-local" className="project-input-sm bg-white" value={diagnosedTo} min={diagnosedFrom || undefined} onChange={(event) => { setDiagnosedTo(event.target.value); setFilterError(""); }} />
            </label>
            <div className="flex shrink-0 gap-2"><Button secondary onClick={clearQualityFilters}>清除</Button><Button disabled={loading} onClick={applyQualityFilters}>应用筛选</Button></div>
          </div>
          {filterError ? <p className="m-0 mt-2 text-xs font-black text-red-700" role="alert" data-testid="exception-quality-filter-error">{filterError}</p> : null}
        </div>
        <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-6">
          {[
            ["诊断总数", data?.total_diagnoses ?? 0],
            ["收到反馈", data?.feedback_count ?? 0],
            ["反馈覆盖率", percent(feedbackRate)],
            ["正向评价率", percent(positiveRate)],
            ["证据引用有效率", percent(data?.evidence_reference_valid_rate ?? data?.evidence_citation_rate)],
            ["模型用量", tokenUsageLabel]
          ].map(([label, value]) => <div key={String(label)} className="border-b border-r border-border px-4 py-3"><span className="block text-xs font-black text-muted-foreground">{label}</span><strong className="mt-1 block font-mono text-xl font-black text-foreground">{value}</strong></div>)}
        </div>
        {data ? <div className="grid border-t border-border md:grid-cols-3"><div className="px-4 py-3 md:border-r md:border-border"><h3 className="m-0 text-xs font-black text-muted-foreground">评价分布</h3><p className="m-0 mt-2 text-sm font-bold text-foreground">有帮助 {helpfulCount} · 部分正确 {partialCount} · 不正确 {incorrectCount} · 未评价 {data.unrated ?? 0}</p></div><div className="px-4 py-3 md:border-r md:border-border"><h3 className="m-0 text-xs font-black text-muted-foreground">诊断处置</h3><p className="m-0 mt-2 text-sm font-bold text-foreground">可执行 {data.by_disposition.actionable ?? 0} · 人工核对 {data.by_disposition.manual_review ?? 0} · 证据不足 {data.by_disposition.blocked ?? 0}</p></div><div className="px-4 py-3"><h3 className="m-0 text-xs font-black text-muted-foreground">效率与时间</h3><p className="m-0 mt-2 text-sm font-bold text-foreground">平均延迟 {data.average_latency_ms == null ? "-" : `${Math.round(data.average_latency_ms)} ms`} · 解决耗时 {data.average_resolution_hours == null ? "-" : `${data.average_resolution_hours.toFixed(1)} 小时`}</p><span className="mt-1 block text-xs font-bold text-muted-foreground">Token 上报 {data.usage_reported_count}/{data.total_diagnoses} · 完整率 {percent(data.usage_completeness_rate)} · 缺失 {data.usage_missing_count}</span><span className="mt-1 block text-xs font-bold text-muted-foreground">生成于 {formatDateTime(data.generated_at)}</span></div></div> : null}
      </section>
      <DataTableShell title="规则诊断质量" description="优先处理反馈量足够且不正确率较高的规则。" meta={data ? `${qualityRules.length} 条规则` : "正在加载"}>
        <Table headers={["业务域与规则", "诊断", "反馈", "反馈构成", "有帮助率", "可信度", "解决耗时"]} minWidth={920} emptyMessage="当前没有诊断质量数据。">
          {qualityRules.map((row) => <tr key={`${row.domain}-${row.rule_code}`}><td><strong className="block text-sm text-foreground">{exceptionDomainLabels[row.domain ?? ""] ?? row.domain ?? "未分类"}</strong><small className="mt-1 block font-mono text-xs text-muted-foreground">{row.rule_code}</small></td><td className="font-mono font-black">{row.diagnoses}</td><td className="font-mono font-black">{row.feedback_count}</td><td><span className="text-sm font-bold text-foreground">有效 {row.helpful} · 部分 {row.partial} · 错误 {row.incorrect}</span></td><td><Badge tone={(row.helpful_rate ?? 0) >= 0.8 ? "ok" : (row.helpful_rate ?? 0) >= 0.6 ? "warn" : "bad"}>{percent(row.helpful_rate)}</Badge></td><td className="font-mono font-black">{percent(row.average_confidence)}</td><td className="font-mono font-black">{row.average_resolution_hours == null ? "-" : `${row.average_resolution_hours.toFixed(1)}h`}</td></tr>)}
        </Table>
      </DataTableShell>
    </div>
  );
}

function ExceptionCaseDrawer({
  caseNo,
  permissions,
  onPermissionsRefresh,
  aiEnabled,
  aiCaseAnalysisEnabled,
  assistantBusy,
  actionsEnabled,
  navigate,
  onAskAi,
  onClose,
  onChanged
}: {
  caseNo: string;
  permissions: PermissionCode[];
  onPermissionsRefresh: () => Promise<PermissionCode[]>;
  aiEnabled: boolean;
  aiCaseAnalysisEnabled: boolean;
  assistantBusy: boolean;
  actionsEnabled: boolean;
  navigate: (page: Page, path?: string) => void;
  onAskAi: (row: Pick<ExceptionCaseItem, "case_no" | "title" | "severity" | "status" | "evidence_version">) => void;
  onClose: () => void;
  onChanged: () => void;
}) {
  const [detail, setDetail] = useState<ExceptionCaseDetail | null>(null);
  const [error, setError] = useState<Error | null>(null);
  const [busy, setBusy] = useState("");
  const [job, setJob] = useState<ExceptionDiagnosisJob | null>(null);
  const [actionType, setActionType] = useState<ExceptionActionType>("rebuild_inventory_flow");
  const [validation, setValidation] = useState<ExceptionAction | null>(null);
  const [actionResult, setActionResult] = useState<ExceptionAction | null>(null);
  const [assigneeId, setAssigneeId] = useState("");
  const [dueAt, setDueAt] = useState("");
  const [assignableUsers, setAssignableUsers] = useState<UserPublic[]>([]);
  const [ignoreReason, setIgnoreReason] = useState("");
  const [ignoreUntil, setIgnoreUntil] = useState(toLocalDateTimeInput());
  const [feedbackRating, setFeedbackRating] = useState<ExceptionFeedbackRating | "">("");
  const [feedbackCategory, setFeedbackCategory] = useState<ExceptionFeedbackCategory | "">("");
  const [feedbackNote, setFeedbackNote] = useState("");
  const [verifyNote, setVerifyNote] = useState("");
  const [verificationResult, setVerificationResult] = useState<ExceptionVerificationResult | null>(null);
  const [jobCancelOpen, setJobCancelOpen] = useState(false);
  const [jobCancelReason, setJobCancelReason] = useState("");
  const [jobPollIssue, setJobPollIssue] = useState<{ message: string; retryInSeconds?: number; stopped: boolean } | null>(null);
  const [jobPollRetryKey, setJobPollRetryKey] = useState(0);
  const detailLoadControllerRef = useRef<AbortController | null>(null);
  const detailLoadSequenceRef = useRef(0);
  const jobPollSequenceRef = useRef(0);
  const actionSectionRef = useRef<HTMLElement | null>(null);
  const canManagePolicy = hasPermission(permissions, "exception_center.policy_manage");
  const canDiagnose = aiEnabled && hasPermission(permissions, "exception_center.diagnose");
  const canSubmitFeedback = hasPermission(permissions, "exception_center.diagnose");
  const canManage = hasPermission(permissions, "exception_center.manage");
  const availableActionTypes = exceptionActionsForDomain(detail?.domain).filter((value) => hasPermission(permissions, exceptionActionSourcePermissions[value]));
  const caseStatus = detail?.status;
  const caseClosed = caseStatus === "resolved" || caseStatus === "ignored";
  const diagnosisSupported = detail?.diagnosis_supported !== false;
  const canStartDiagnosis = canDiagnose && diagnosisSupported && !caseClosed;
  const canAskAi = aiCaseAnalysisEnabled;
  const canRetryDiagnosisJob = diagnosisSupported
    && canManagePolicy
    && Boolean(job && (job.retryable || ["failed", "cancelled"].includes(job.status)));
  const canAssign = canManage && Boolean(caseStatus && exceptionBatchAssignableStatuses.includes(caseStatus));
  const canIgnore = canManage && Boolean(caseStatus && exceptionBatchIgnoreableStatuses.includes(caseStatus));
  const canVerify = canManage && Boolean(caseStatus && ["open", "action_required", "processing", "blocked"].includes(caseStatus));
  const canExecute = actionsEnabled && hasPermission(permissions, "exception_center.action_execute") && availableActionTypes.length > 0 && Boolean(caseStatus && ["open", "action_required", "blocked"].includes(caseStatus));
  const canPollDiagnosisJob = hasPermission(permissions, "exception_center.diagnose");

  const applyDetail = useCallback((next: ExceptionCaseDetail) => {
    setDetail(next);
    setValidation((current) => current?.evidence_version === next.evidence_version ? current : null);
    setJob(next.active_diagnosis_job ?? null);
    const permittedActions = exceptionActionsForDomain(next.domain).filter((value) => hasPermission(permissions, exceptionActionSourcePermissions[value]));
    const defaultAction = permittedActions[0] ?? exceptionActionsForDomain(next.domain)[0];
    if (defaultAction) setActionType(defaultAction);
    setAssigneeId(next.assignee_user_id ? String(next.assignee_user_id) : "");
    setDueAt(next.due_at ? toLocalDateTimeInput(next.due_at) : "");
  }, [permissions]);
  const load = useCallback(async () => {
    const sequence = ++detailLoadSequenceRef.current;
    detailLoadControllerRef.current?.abort();
    const controller = new AbortController();
    detailLoadControllerRef.current = controller;
    setError(null);
    try {
      const next = await exceptionCase(caseNo, controller.signal);
      if (controller.signal.aborted || sequence !== detailLoadSequenceRef.current) return null;
      applyDetail(next);
      return next;
    } catch (reason) {
      if (!isAbortError(reason) && sequence === detailLoadSequenceRef.current) {
        setError(normalizeUiError(reason, "异常详情加载失败"));
      }
      return null;
    } finally {
      if (sequence === detailLoadSequenceRef.current && detailLoadControllerRef.current === controller) {
        detailLoadControllerRef.current = null;
      }
    }
  }, [applyDetail, caseNo]);
  useEffect(() => {
    void load();
    return () => detailLoadControllerRef.current?.abort();
  }, [load]);
  useEffect(() => {
    if (!canManage || !hasPermission(permissions, "user.view")) return;
    void users().then((rows) => setAssignableUsers(rows.filter((row) => row.is_active))).catch(() => setAssignableUsers([]));
  }, [canManage, permissions]);
  useEffect(() => setJobPollIssue(null), [job?.id]);
  useEffect(() => {
    if (!canPollDiagnosisJob || !job || ["completed", "failed", "cancelled"].includes(job.status)) return;
    const sequence = ++jobPollSequenceRef.current;
    const controller = new AbortController();
    let active = true;
    let timer: number | undefined;
    let consecutiveFailures = 0;
    const schedule = (delay: number) => {
      if (!active || controller.signal.aborted || sequence !== jobPollSequenceRef.current) return;
      timer = window.setTimeout(() => void poll(), delay);
    };
    const refreshAccessAndDetail = async () => {
      const [permissionResult, detailResult] = await Promise.allSettled([
        onPermissionsRefresh(),
        exceptionCase(caseNo, controller.signal)
      ]);
      if (!active || controller.signal.aborted || sequence !== jobPollSequenceRef.current) return;
      if (permissionResult.status === "rejected") {
        setError(normalizeUiError(permissionResult.reason, "权限刷新失败，请重新进入异常中心"));
      }
      if (detailResult.status === "fulfilled") applyDetail(detailResult.value);
      else setError(normalizeUiError(detailResult.reason, "任务轮询已停止，案件详情刷新失败"));
    };
    const poll = async () => {
      let next: ExceptionDiagnosisJob;
      try {
        next = await exceptionDiagnosisJob(job.id, controller.signal);
      } catch (reason) {
        if (!active || controller.signal.aborted || sequence !== jobPollSequenceRef.current || isAbortError(reason)) return;
        const status = reason instanceof ApiError ? reason.status : 0;
        if (status === 401) return;
        if (status === 403 || status === 404) {
          setJobPollIssue({
            message: status === 403 ? "诊断任务读取权限已变化，轮询已停止并刷新权限。" : "诊断任务已不存在，轮询已停止并刷新案件详情。",
            stopped: true
          });
          await refreshAccessAndDetail();
          return;
        }
        if (status === 0 || status >= 500) {
          consecutiveFailures += 1;
          const retryDelay = Math.min(30_000, 2_000 * (2 ** (consecutiveFailures - 1)));
          setJobPollIssue({ message: "任务状态刷新失败，系统将指数退避后重试。", retryInSeconds: Math.ceil(retryDelay / 1000), stopped: false });
          schedule(retryDelay);
          return;
        }
        setJobPollIssue({ message: `任务状态刷新已停止：${normalizeUiError(reason, "请求失败").message}`, stopped: true });
        return;
      }
      if (!active || controller.signal.aborted || sequence !== jobPollSequenceRef.current) return;
      consecutiveFailures = 0;
      setJobPollIssue(null);
      if (["completed", "failed", "cancelled"].includes(next.status)) {
        try {
          const refreshed = await exceptionCase(caseNo, controller.signal);
          if (!active || controller.signal.aborted || sequence !== jobPollSequenceRef.current) return;
          applyDetail(refreshed);
          onChanged();
        } catch (refreshReason) {
          if (!active || controller.signal.aborted || sequence !== jobPollSequenceRef.current || isAbortError(refreshReason)) return;
          setJob(next);
          setJobPollIssue({
            message: "诊断任务已结束，但最新案件详情刷新失败，请立即重试状态刷新。",
            stopped: true
          });
          setError(normalizeUiError(refreshReason, "诊断任务已结束，但案件详情刷新失败"));
        }
        return;
      }
      setJob(next);
      schedule(2_000);
    };
    schedule(jobPollRetryKey > 0 ? 0 : 2_000);
    return () => {
      active = false;
      controller.abort();
      if (timer !== undefined) window.clearTimeout(timer);
    };
  }, [job?.id, job?.status, canPollDiagnosisJob, jobPollRetryKey, caseNo, onPermissionsRefresh]);
  useEffect(() => {
    if (!actionResult || ["completed", "failed", "blocked", "cancelled"].includes(actionResult.status)) return;
    let active = true;
    const timer = window.setInterval(() => {
      void exceptionAction(actionResult.id).then((next) => {
        if (!active) return;
        setActionResult(next);
        if (["completed", "failed", "blocked", "cancelled"].includes(next.status)) {
          window.clearInterval(timer);
          void load();
          onChanged();
        }
      }).catch(() => undefined);
    }, 2_000);
    return () => {
      active = false;
      window.clearInterval(timer);
    };
  }, [actionResult?.id, actionResult?.status]);

  const runMutation = async (key: string, operation: () => Promise<unknown>) => {
    setBusy(key);
    setError(null);
    try {
      await operation();
      await load();
      onChanged();
    } catch (reason) {
      setError(normalizeUiError(reason, "操作失败"));
    } finally {
      setBusy("");
    }
  };

  const diagnose = async () => {
    if (!canStartDiagnosis) return;
    setBusy("diagnose");
    setError(null);
    try {
      const next = await diagnoseExceptionCase(caseNo);
      setJob(next);
      if (["completed", "failed", "cancelled"].includes(next.status)) await load();
    } catch (reason) {
      setError(normalizeUiError(reason, "智能诊断启动失败"));
    } finally {
      setBusy("");
    }
  };

  const mutateJob = async (mode: "retry" | "cancel") => {
    if (!canManagePolicy || !job) return;
    if (mode === "retry" && !diagnosisSupported) return;
    if (mode === "cancel" && jobCancelReason.trim().length < 2) return;
    setBusy(`job-${mode}`);
    setError(null);
    try {
      const next = mode === "retry"
        ? await retryExceptionDiagnosisJob(job.id, "案件详情中手动重试")
        : await cancelExceptionDiagnosisJob(job.id, jobCancelReason.trim());
      setJob(next);
      setJobCancelOpen(false);
      setJobCancelReason("");
      await load();
      onChanged();
    } catch (reason) {
      setError(normalizeUiError(reason, mode === "retry" ? "诊断任务重试失败" : "诊断任务取消失败"));
    } finally {
      setBusy("");
    }
  };

  const validateAction = async () => {
    setBusy("validate");
    setValidation(null);
    setError(null);
    try {
      setValidation(await validateExceptionAction(caseNo, actionType));
    } catch (reason) {
      setError(normalizeUiError(reason, "修复动作预演失败"));
    } finally {
      setBusy("");
    }
  };

  const executeAction = async () => {
    if (!validation?.validation_token) return;
    const suffix = typeof crypto !== "undefined" && "randomUUID" in crypto ? crypto.randomUUID() : `${Date.now()}-${Math.random()}`;
    setBusy("execute");
    setError(null);
    try {
      const next = await executeExceptionAction(caseNo, validation.validation_token, `web-${suffix}`);
      setActionResult(next);
      setValidation(null);
      if (["completed", "failed", "blocked", "cancelled"].includes(next.status)) {
        await load();
        onChanged();
      }
    } catch (reason) {
      setError(normalizeUiError(reason, "修复动作执行失败"));
    } finally {
      setBusy("");
    }
  };

  const sourcePath = detail?.action_path?.startsWith("/") ? withExceptionReturnContext(detail.action_path, caseNo) : null;

  useEffect(() => {
    if (!detail || initialQueryParam("focus") !== "actions") return;
    const timer = window.setTimeout(() => actionSectionRef.current?.scrollIntoView({ behavior: "smooth", block: "start" }), 120);
    return () => window.clearTimeout(timer);
  }, [detail]);
  const latestDiagnosis = detail
    ? (
        detail.diagnosis?.evidence_version === detail.evidence_version
          ? detail.diagnosis
          : detail.diagnoses.find((item) => item.evidence_version === detail.evidence_version) ?? null
      )
    : null;
  const jobUsesCurrentEvidence = Boolean(detail && job && job.evidence_version === detail.evidence_version);
  const actionResultUsesCurrentEvidence = Boolean(detail && actionResult && actionResult.evidence_version === detail.evidence_version);
  const verificationEvidenceVersion = verificationResult?.after?.evidence_version ?? verificationResult?.case.evidence_version;
  const verificationUsesCurrentEvidence = Boolean(detail && verificationResult && verificationEvidenceVersion === detail.evidence_version);
  const feedbackNeedsExplanation = feedbackRating === "partial" || feedbackRating === "incorrect";
  const feedbackNoteMaxLength = feedbackNeedsExplanation
    ? exceptionFeedbackExplanationMaxLength(feedbackCategory || undefined)
    : EXCEPTION_FEEDBACK_NOTE_MAX_LENGTH;
  const feedbackCanSave = Boolean(feedbackRating)
    && (!feedbackNeedsExplanation || (Boolean(feedbackCategory) && feedbackNote.trim().length >= 2));
  useEffect(() => {
    const parsed = parseExceptionFeedbackNote(latestDiagnosis?.feedback_note);
    setFeedbackRating(latestDiagnosis?.feedback_rating ?? "");
    setFeedbackCategory(parsed.category);
    setFeedbackNote(parsed.note);
  }, [latestDiagnosis?.id, latestDiagnosis?.feedback_rating, latestDiagnosis?.feedback_note]);

  const saveDiagnosisFeedback = async () => {
    if (!latestDiagnosis?.id || !feedbackRating || !feedbackCanSave) return;
    setBusy("feedback");
    setError(null);
    try {
      const note = feedbackNeedsExplanation && feedbackCategory
        ? serializeExceptionFeedbackNote(feedbackCategory, feedbackNote)
        : feedbackNote.trim() || null;
      const updated = await submitExceptionDiagnosisFeedback(latestDiagnosis.id, {
        rating: feedbackRating,
        note
      });
      setDetail((current) => current ? {
        ...current,
        diagnosis: current.diagnosis?.id === updated.id ? updated : current.diagnosis,
        diagnoses: current.diagnoses.map((item) => item.id === updated.id ? updated : item)
      } : current);
      const parsed = parseExceptionFeedbackNote(updated.feedback_note);
      setFeedbackRating(updated.feedback_rating ?? "");
      setFeedbackCategory(parsed.category);
      setFeedbackNote(parsed.note);
      onChanged();
    } catch (reason) {
      setError(normalizeUiError(reason, "诊断反馈保存失败"));
    } finally {
      setBusy("");
    }
  };

  const verifyCase = async () => {
    if (!detail || verifyNote.trim().length < 2) return;
    setBusy("verify");
    setError(null);
    setVerificationResult(null);
    try {
      const result = await verifyExceptionCase(caseNo, { note: verifyNote.trim(), expected_evidence_version: detail.evidence_version });
      setVerificationResult(result);
      try {
        const refreshed = await exceptionCase(caseNo);
        applyDetail(refreshed);
      } catch (refreshReason) {
        setError(normalizeUiError(refreshReason, "复检已完成，但最新案件证据加载失败，请手动重试"));
      }
      onChanged();
    } catch (reason) {
      setError(normalizeUiError(reason, "异常复检失败"));
    } finally {
      setBusy("");
    }
  };
  return (
    <Drawer title={detail?.title ?? "异常详情"} subtitle={detail ? `${detail.case_no} · ${exceptionDomainLabels[detail.domain] ?? detail.domain}` : caseNo} onClose={onClose}>
      <div className="grid gap-4">
        {error ? <ApiErrorNotice error={error} navigate={navigate} onRetry={load} /> : null}
        {!detail && !error ? <div className="grid gap-3"><div className="h-24 animate-pulse rounded-lg bg-secondary" /><div className="h-64 animate-pulse rounded-lg bg-secondary" /></div> : null}
        {detail ? (
          <>
            <section className="project-drawer-overview">
              <div className="flex flex-wrap items-start justify-between gap-3">
                <div className="flex flex-wrap items-center gap-2">
                  <Badge tone={exceptionSeverityTone(detail.severity)}>{exceptionSeverityLabels[detail.severity] ?? detail.severity}</Badge>
                  <Badge tone={exceptionStatusTone(detail.status)}>{exceptionStatusLabels[detail.status]}</Badge>
                  <Badge tone="neutral">{exceptionOccurrenceLabels[detail.occurrence_type] ?? detail.occurrence_type}</Badge>
                  {!diagnosisSupported ? <Badge tone="neutral">确定性规则</Badge> : null}
                  {detail.processing_kind ? <Badge tone="warn">{detail.processing_kind === "manual_diagnosis" ? "人工诊断中" : detail.processing_kind === "scheduled_diagnosis" ? "定时诊断中" : "后台巡检中"}</Badge> : null}
                  <span className="text-xs font-black text-muted-foreground">规则 {detail.rule_code}</span>
                </div>
                <div className="flex flex-wrap gap-2">
                  {sourcePath ? <Button secondary onClick={() => navigate(pageFromPath(sourcePath), sourcePath)}><ExternalLink className="mr-1.5 h-4 w-4" />定位原始记录</Button> : null}
                  {canAskAi ? <Button secondary disabled={assistantBusy} onClick={() => detail && onAskAi(detail)}><Sparkles className="mr-1.5 h-4 w-4" />{assistantBusy ? "AI 分析中" : "问 AI 分析"}</Button> : null}
                  {canStartDiagnosis ? <span data-testid="exception-diagnose"><Button onClick={() => void diagnose()} disabled={busy === "diagnose" || Boolean(job && !["completed", "failed", "cancelled"].includes(job.status))}><Siren className="mr-1.5 h-4 w-4" />{busy === "diagnose" ? "启动中" : job && !["completed", "failed", "cancelled"].includes(job.status) ? "诊断中" : "结构化诊断"}</Button></span> : null}
                </div>
              </div>
              <p className="m-0 mt-3 text-sm font-bold leading-6 text-foreground">{detail.reason}</p>
              {detail.initial_guidance ? <p className="m-0 mt-2 rounded-md bg-primary-soft px-3 py-2 text-sm font-bold leading-6 text-primary">处理提示：{detail.initial_guidance}</p> : null}
              {job?.error_message ? <p className="m-0 mt-2 text-sm font-bold text-red-700">诊断失败：{job.error_message}</p> : null}
            </section>

            {job ? <section className="project-drawer-section" data-testid="exception-active-job">
              <div className="flex flex-wrap items-start justify-between gap-3">
                <div><h3 className="project-drawer-section-title">诊断任务</h3><p className="project-drawer-section-subtitle">任务 {job.job_no} · {job.status === "queued" ? "排队中" : job.status === "processing" ? "诊断中" : job.status === "failed" ? "执行失败" : job.status === "cancelled" ? "已取消" : "已完成"} · 证据 {job.evidence_version}</p></div>
                <div className="flex flex-wrap items-center gap-2"><Badge tone={job.status === "failed" ? "bad" : job.status === "completed" ? "ok" : "warn"}>{job.status}</Badge>{!jobUsesCurrentEvidence ? <Badge tone="neutral">历史证据任务</Badge> : null}</div>
              </div>
              <div className="mt-3 grid gap-3 sm:grid-cols-3">
                <div><span className="text-xs font-black text-muted-foreground">尝试次数</span><strong className="mt-1 block text-sm text-foreground">{job.attempts ?? job.attempt_count ?? 0}</strong></div>
                <div><span className="text-xs font-black text-muted-foreground">任务租约至</span><strong className="mt-1 block text-sm text-foreground">{formatDateTime(job.lease_expires_at ?? job.heartbeat_at)}</strong></div>
                <div><span className="text-xs font-black text-muted-foreground">可执行时间</span><strong className="mt-1 block text-sm text-foreground">{formatDateTime(job.available_at ?? job.next_retry_at)}</strong></div>
              </div>
              {["queued", "processing"].includes(job.status) ? <ExceptionDiagnosisProgress status={job.status as "queued" | "processing"} /> : null}
              {job.error_message ? <p className="m-0 mt-3 rounded-md bg-red-50 px-3 py-2 text-sm font-bold text-red-700">{job.error_message}</p> : null}
              {jobPollIssue ? <div className={`mt-3 flex flex-col gap-2 rounded-md border px-3 py-2 sm:flex-row sm:items-center sm:justify-between ${jobPollIssue.stopped ? "border-red-200 bg-red-50 text-red-800" : "border-amber-200 bg-amber-50 text-amber-900"}`} data-testid="exception-job-poll-issue" data-poll-stopped={jobPollIssue.stopped ? "true" : "false"}>
                <p className="m-0 text-sm font-bold leading-5">{jobPollIssue.message}{jobPollIssue.retryInSeconds ? ` 将在 ${jobPollIssue.retryInSeconds} 秒后重试。` : ""}</p>
                <Button secondary onClick={() => {
                  setJobPollIssue(null);
                  setJobPollRetryKey((value) => value + 1);
                  if (["completed", "failed", "cancelled"].includes(job.status)) void load();
                }}><RotateCcw className="mr-1.5 h-4 w-4" />立即重试状态刷新</Button>
              </div> : null}
              {canRetryDiagnosisJob ? <div className="mt-3 flex flex-wrap justify-end gap-2"><span data-testid="exception-job-retry"><Button secondary disabled={busy === "job-retry"} onClick={() => void mutateJob("retry")}><RotateCcw className="mr-1.5 h-4 w-4" />{busy === "job-retry" ? "重试中" : "重试任务"}</Button></span></div> : null}
              {(job.cancellable || ["queued", "processing"].includes(job.status)) && canManagePolicy ? <div className="mt-2 flex justify-end"><Button secondary disabled={busy === "job-cancel"} onClick={() => setJobCancelOpen(true)}><X className="mr-1.5 h-4 w-4" />取消任务</Button></div> : null}
              {jobCancelOpen ? <div className="mt-3 rounded-lg border border-amber-200 bg-amber-50 p-3" data-testid="exception-active-job-cancel"><label className="grid gap-1.5 text-xs font-black text-amber-900">取消原因<textarea className="project-input-sm min-h-16 bg-white py-2" maxLength={1000} value={jobCancelReason} onChange={(event) => setJobCancelReason(event.target.value)} placeholder="说明取消原因，至少 2 个字符；系统会写入审计记录" /></label><div className="mt-2 flex justify-end gap-2"><Button secondary onClick={() => { setJobCancelOpen(false); setJobCancelReason(""); }}>返回</Button><Button disabled={jobCancelReason.trim().length < 2 || busy === "job-cancel"} onClick={() => void mutateJob("cancel")}>{busy === "job-cancel" ? "取消中" : "确认取消"}</Button></div></div> : null}
            </section> : null}

            <section className="project-drawer-section">
              <h3 className="project-drawer-section-title">发生位置</h3>
              <div className="mt-3 grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
                {[
                  ["业务对象", detail.resource_name ?? detail.resource_code ?? detail.resource_id],
                  ["来源", `${detail.source_type}${detail.source_id ? ` / ${detail.source_id}` : ""}`],
                  ["批次", detail.source_batch_id && detail.source_batch_kind ? `${exceptionSourceBatchKindLabels[detail.source_batch_kind]} ${detail.source_batch_id}` : "未关联"],
                  ["数据日期", formatDate(detail.data_date)],
                  ["规则版本", detail.rule_version ?? "未标记"],
                  ["发生周期", detail.occurrence_cycle != null ? `第 ${detail.occurrence_cycle} 周期` : "未标记"],
                  ["影响记录", `${detail.affected_rows} 条`],
                  ["影响数量", detail.affected_quantity],
                  ["发现时间", formatDateTime(detail.detected_at)],
                  ["最近命中", formatDateTime(detail.last_seen_at)]
                ].map(([label, value]) => <div key={String(label)}><span className="text-xs font-black text-muted-foreground">{label}</span><strong className="mt-1 block break-words text-sm text-foreground">{displayValue(value)}</strong></div>)}
              </div>
            </section>

            <section className="project-drawer-section">
              <h3 className="project-drawer-section-title">证据包</h3>
              <p className="project-drawer-section-subtitle">证据版本 {detail.evidence_version}。{diagnosisSupported ? "模型只能依据这里的结构化内容给出解释。" : "这些结构化事实用于确定性规则定位和人工复核。"}</p>
              <div className="mt-3"><ExceptionBusinessEvidence domain={detail.domain} value={detail.evidence} /></div>
            </section>

            <section className="project-drawer-section">
              <h3 className="project-drawer-section-title">结构化诊断</h3>
              {!diagnosisSupported ? <div className="mt-2 rounded-lg border border-slate-200 bg-slate-50 px-4 py-3" data-testid="exception-diagnosis-unsupported"><strong className="block text-sm font-black text-slate-800">当前业务域仅支持确定性规则</strong><p className="m-0 mt-1 text-sm font-bold leading-6 text-slate-600">CRM 与审批异常暂不支持智能诊断。请依据证据包、处理提示和原始业务记录完成人工核对，修正后再执行确定性复检。</p></div> : latestDiagnosis ? <>
                <ExceptionDiagnosisView diagnosis={latestDiagnosis} />
                {canSubmitFeedback ? <div className="mt-3 border-t border-border pt-3" data-testid="exception-diagnosis-feedback">
                  <div className="flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between">
                    <div><strong className="block text-sm font-black text-foreground">这份诊断是否有帮助？</strong><span className="mt-0.5 block text-xs font-bold text-muted-foreground">反馈只评价当前证据版本，不会改变确定性异常结论。</span></div>
                    {latestDiagnosis.feedback_rating ? <span className="text-xs font-black text-emerald-700" data-testid="exception-feedback-saved">已保存：{exceptionFeedbackLabels[latestDiagnosis.feedback_rating]}{latestDiagnosis.feedback_at ? ` · ${formatDateTime(latestDiagnosis.feedback_at)}` : ""}</span> : null}
                  </div>
                  <div className="mt-3 flex flex-wrap gap-2" role="group" aria-label="诊断评价">
                    {(Object.entries(exceptionFeedbackLabels) as Array<[ExceptionFeedbackRating, string]>).map(([value, label]) => <button key={value} type="button" aria-pressed={feedbackRating === value} onClick={() => setFeedbackRating(value)} className={`project-button-secondary px-3 ${feedbackRating === value ? "border-primary bg-primary-soft text-primary" : ""}`}>{label}</button>)}
                  </div>
                  {feedbackNeedsExplanation ? <label className="mt-3 grid gap-1.5 text-xs font-black text-muted-foreground">问题分类（必选）
                    <select className="project-input-sm w-full bg-white" value={feedbackCategory} onChange={(event) => {
                      const category = event.target.value as ExceptionFeedbackCategory | "";
                      setFeedbackCategory(category);
                      setFeedbackNote((current) => current.slice(0, exceptionFeedbackExplanationMaxLength(category || undefined)));
                    }}>
                      <option value="">请选择问题分类</option>
                      {(Object.entries(exceptionFeedbackCategoryLabels) as Array<[ExceptionFeedbackCategory, string]>).map(([value, label]) => <option key={value} value={value}>{label}</option>)}
                    </select>
                  </label> : null}
                  <label className="mt-3 grid gap-1.5 text-xs font-black text-muted-foreground">{feedbackNeedsExplanation ? "具体原因（必填）" : "补充说明（选填）"}
                    <textarea className="project-input-sm min-h-20 w-full py-2" maxLength={feedbackNoteMaxLength} value={feedbackNote} onChange={(event) => setFeedbackNote(event.target.value.slice(0, feedbackNoteMaxLength))} placeholder={feedbackNeedsExplanation ? "请具体说明问题，至少 2 个字符" : "说明哪些判断准确，或补充其他信息"} />
                  </label>
                  <div className="mt-3 flex justify-end"><Button secondary disabled={!feedbackCanSave || busy === "feedback"} onClick={() => void saveDiagnosisFeedback()}>{busy === "feedback" ? "保存中" : latestDiagnosis.feedback_rating ? "更新反馈" : "保存反馈"}</Button></div>
                </div> : null}
              </> : <p className="m-0 mt-2 text-sm font-bold text-muted-foreground">尚未生成智能诊断，确定性异常结论仍然有效。</p>}
            </section>

            {canManage ? (
              <section className="project-drawer-section">
                <h3 className="project-drawer-section-title">责任分派与状态处理</h3>
                {caseClosed ? <p className="m-0 mt-2 rounded-md border border-border bg-secondary px-3 py-2 text-sm font-bold text-muted-foreground">当前案件为“{exceptionStatusLabels[detail.status]}”，不能再次分派、忽略、诊断或执行修复。异常复发后系统会自动重新打开。</p> : null}
                {detail.status === "processing" ? <p className="m-0 mt-2 rounded-md border border-amber-200 bg-amber-50 px-3 py-2 text-sm font-bold text-amber-800">案件正在处理，可调整负责人和期限，也可复检；为避免冲突，当前不能忽略或启动新的修复动作。</p> : null}
                <div className="mt-3 grid gap-3 lg:grid-cols-2">
                  {canAssign ? <div className="grid gap-2 rounded-lg border border-border bg-secondary p-3">
                    <label className="grid gap-1.5 text-xs font-black text-muted-foreground">负责人
                      {assignableUsers.length > 0 ? (
                        <select className="project-input-sm" value={assigneeId} onChange={(event) => setAssigneeId(event.target.value)}><option value="">未分派</option>{assignableUsers.map((row) => <option key={row.id} value={row.id}>{row.real_name}（{row.username}）</option>)}</select>
                      ) : <input type="number" min="1" className="project-input-sm" value={assigneeId} onChange={(event) => setAssigneeId(event.target.value)} placeholder="负责人账号 ID" />}
                    </label>
                    <label className="grid gap-1.5 text-xs font-black text-muted-foreground">处理时限<input type="datetime-local" className="project-input-sm" value={dueAt} onChange={(event) => setDueAt(event.target.value)} /></label>
                    <Button secondary disabled={busy === "assign"} onClick={() => void runMutation("assign", () => assignExceptionCase(caseNo, { assignee_user_id: assigneeId ? Number(assigneeId) : null, due_at: dueAt ? new Date(dueAt).toISOString() : null }))}>{busy === "assign" ? "分派中" : "保存分派"}</Button>
                  </div> : null}
                  {canIgnore ? <div className="grid gap-2 rounded-lg border border-border bg-secondary p-3">
                    <label className="grid gap-1.5 text-xs font-black text-muted-foreground">忽略原因<textarea className="project-input-sm min-h-20 py-2" value={ignoreReason} onChange={(event) => setIgnoreReason(event.target.value)} placeholder="说明为什么当前无需处理" /></label>
                    <label className="grid gap-1.5 text-xs font-black text-muted-foreground">忽略至<input type="datetime-local" className="project-input-sm" value={ignoreUntil} onChange={(event) => setIgnoreUntil(event.target.value)} /></label>
                    <Button secondary disabled={busy === "ignore" || ignoreReason.trim().length < 2 || !ignoreUntil} onClick={() => void runMutation("ignore", () => ignoreExceptionCase(caseNo, { reason: ignoreReason.trim(), ignored_until: new Date(ignoreUntil).toISOString() }))}>{busy === "ignore" ? "处理中" : "暂时忽略"}</Button>
                  </div> : null}
                </div>
                {canVerify ? <div className="mt-3 grid gap-2 rounded-lg border border-border bg-white p-3"><label className="grid gap-1.5 text-xs font-black text-muted-foreground">复检说明<textarea className="project-input-sm min-h-20 py-2" data-testid="exception-verify-note" maxLength={1000} value={verifyNote} onChange={(event) => setVerifyNote(event.target.value)} placeholder="说明已完成的修正、核对范围或复检依据，至少 2 个字符" /></label><div className="flex flex-col items-start gap-3 sm:flex-row sm:items-center sm:justify-between"><span className="text-xs font-bold leading-5 text-muted-foreground">复检会重新执行对应业务域的确定性规则。</span><Button secondary disabled={busy === "verify" || verifyNote.trim().length < 2} onClick={() => void verifyCase()}>{busy === "verify" ? "复检中" : "立即复检"}</Button></div></div> : null}
                {verificationResult ? <div data-testid="exception-verification-evidence" data-evidence-current={verificationUsesCurrentEvidence ? "true" : "false"}>{!verificationUsesCurrentEvidence ? <p className="m-0 mt-3 rounded-md border border-slate-200 bg-slate-50 px-3 py-2 text-xs font-black text-slate-600">这是证据版本 {verificationEvidenceVersion ?? "未标记"} 的历史复检结果，当前版本为 {detail.evidence_version}。</p> : null}<ExceptionVerificationView result={verificationResult} /></div> : null}
              </section>
            ) : null}

            {canExecute ? (
              <section ref={actionSectionRef} className="project-drawer-section scroll-mt-4" data-testid="exception-actions">
                <h3 className="project-drawer-section-title">受控修复动作</h3>
                <p className="project-drawer-section-subtitle">只允许重建派生数据或重新校验。系统不会直接修改库存快照或原始导入文件。</p>
                <div className="mt-3 flex flex-col gap-2 sm:flex-row">
                  <select className="project-input-sm min-w-0 flex-1" value={actionType} onChange={(event) => { setActionType(event.target.value as ExceptionActionType); setValidation(null); }}>{availableActionTypes.map((value) => <option key={value} value={value}>{exceptionActionLabels[value]}</option>)}</select>
                  <Button secondary disabled={busy === "validate"} onClick={() => void validateAction()}>{busy === "validate" ? "预演中" : "预演影响"}</Button>
                </div>
                {validation ? (
                  <div className={`mt-3 rounded-lg border p-3 ${validation.allowed ? "border-emerald-200 bg-emerald-50" : "border-red-200 bg-red-50"}`}>
                    <div className="flex flex-wrap items-center justify-between gap-3"><div><strong className="text-sm text-foreground">{validation.allowed ? "预演通过" : "策略已阻止"}</strong><span className="ml-2 font-mono text-xs font-bold text-muted-foreground">证据 {validation.evidence_version}</span></div>{validation.allowed && validation.validation_token ? <Button disabled={busy === "execute"} onClick={() => void executeAction()}>{busy === "execute" ? "执行中" : "确认执行"}</Button> : null}</div>
                    {validation.blockers.length > 0 ? <p className="m-0 mt-2 text-sm font-bold text-red-700">阻止原因：{validation.blockers.join("；")}</p> : null}
                    <div className="mt-2"><ExceptionObjectView value={validation.impact} /></div>
                  </div>
                ) : null}
                {actionResult ? (
                  <div className="mt-3 rounded-lg border border-border bg-secondary p-3">
                    <div className="flex flex-wrap items-center justify-between gap-2"><div><strong className="text-sm text-foreground">动作 {actionResult.action_no}</strong><span className="ml-2 font-mono text-xs font-bold text-muted-foreground">证据 {actionResult.evidence_version}</span></div><div className="flex items-center gap-2">{!actionResultUsesCurrentEvidence ? <Badge tone="neutral">历史证据结果</Badge> : null}<Badge tone={actionResult.status === "completed" ? "ok" : actionResult.status === "failed" || actionResult.status === "blocked" ? "bad" : "warn"}>{actionResult.status}</Badge></div></div>
                    {actionResult.error_message ? <p className="m-0 mt-2 text-sm font-bold text-red-700">{actionResult.error_message}</p> : null}
                    {actionResult.result ? <div className="mt-2"><ExceptionObjectView value={actionResult.result} /></div> : null}
                  </div>
                ) : null}
              </section>
            ) : null}

            <section className="project-drawer-section">
              <h3 className="project-drawer-section-title">处理历史</h3>
              <div className="mt-3 grid gap-2">
                {[...(detail.events ?? []), ...(detail.actions ?? [])].length > 0 ? [...(detail.events ?? []), ...(detail.actions ?? [])].map((row, index) => (
                  <div key={`${String(row.id ?? row.action_no ?? "history")}-${index}`}><ExceptionObjectView value={row} /></div>
                )) : <p className="m-0 text-sm font-bold text-muted-foreground">暂无处理历史。</p>}
              </div>
            </section>
          </>
        ) : null}
      </div>
    </Drawer>
  );
}

const controlledExceptionActionTypes: ControlledExceptionActionType[] = [
  "rebuild_inventory_flow",
  "rerun_inventory_check",
  "rebuild_receivable_checks",
  "rebuild_master_link_issues",
  "revalidate_import_batch"
];

function isControlledExceptionActionType(value: string): value is ControlledExceptionActionType {
  return controlledExceptionActionTypes.includes(value as ControlledExceptionActionType);
}

function controlledActionIdempotencyKey() {
  const suffix = typeof crypto.randomUUID === "function"
    ? crypto.randomUUID()
    : `${Date.now()}-${Math.random().toString(16).slice(2)}`;
  return `web-ai-action:${suffix}`;
}

function controlledActionBlockerLabel(value: string) {
  if (value.startsWith("missing_permission:")) return `缺少权限：${value.split(":").slice(1).join(":")}`;
  if (value.startsWith("feature_disabled:")) return "功能开关未开放";
  if (value.startsWith("review_status:")) return "提案已完成复核";
  if (value.startsWith("status:")) return "提案当前状态不可执行";
  return ({ validation_expired: "校验已过期，需重新校验", evidence_changed: "案件证据已变化", source_batch_changed: "来源批次已变化", source_action_missing: "来源动作不存在", action_disabled_by_policy: "生产策略未开放该动作" } as Record<string, string>)[value] ?? value;
}

function controlledActionStatusLabel(value: string) {
  return ({ proposed: "待复核", validated: "已校验", blocked: "已阻断", pending: "处理中", completed: "已完成", failed: "失败", cancelled: "已取消", accepted: "已采纳", rejected: "已拒绝" } as Record<string, string>)[value] ?? value;
}

function ControlledActionCenter({ permissions, navigate }: { permissions: PermissionCode[]; navigate: (page: Page, path?: string) => void }) {
  const canReviewCrm = hasPermission(permissions, "crm_insight.review");
  const canExecuteException = hasPermission(permissions, "exception_center.action_execute");
  const [catalog, setCatalog] = useState<ControlledActionCatalogItem[]>([]);
  const [proposals, setProposals] = useState<ControlledActionProposal[]>([]);
  const [proposalTotal, setProposalTotal] = useState(0);
  const [executions, setExecutions] = useState<ControlledActionExecution[]>([]);
  const [executionTotal, setExecutionTotal] = useState(0);
  const [domain, setDomain] = useState("");
  const [reviewStatus, setReviewStatus] = useState<"" | "pending" | "accepted" | "rejected">("pending");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);
  const [message, setMessage] = useState("");
  const [refreshKey, setRefreshKey] = useState(0);
  const [selectedProposal, setSelectedProposal] = useState<ControlledActionProposal | null>(null);
  const [validation, setValidation] = useState<ControlledActionValidation | null>(null);
  const [decision, setDecision] = useState<"accept" | "reject" | "task">("accept");
  const [reviewNote, setReviewNote] = useState("");
  const [confirmed, setConfirmed] = useState(false);
  const [busy, setBusy] = useState(false);
  const [dialogError, setDialogError] = useState<Error | null>(null);
  const [idempotencyKey, setIdempotencyKey] = useState(controlledActionIdempotencyKey);
  const [caseNo, setCaseNo] = useState("");
  const [newActionType, setNewActionType] = useState<ControlledExceptionActionType>("rebuild_inventory_flow");
  const [batchId, setBatchId] = useState("");

  const reload = () => setRefreshKey((value) => value + 1);
  useEffect(() => {
    const controller = new AbortController();
    setLoading(true);
    setError(null);
    Promise.all([
      controlledActionCatalog(),
      controlledActionProposals({ domain: domain || undefined, review_status: reviewStatus || undefined, limit: 50, offset: 0 }, controller.signal),
      controlledActionExecutions({ domain: domain || undefined, limit: 30, offset: 0 }, controller.signal)
    ]).then(([catalogRows, proposalPage, executionPage]) => {
      if (controller.signal.aborted) return;
      setCatalog(catalogRows);
      setProposals(proposalPage.items);
      setProposalTotal(proposalPage.total);
      setExecutions(executionPage.items);
      setExecutionTotal(executionPage.total);
    }).catch((reason) => {
      if (!isAbortError(reason)) setError(normalizeUiError(reason, "受控动作中心加载失败"));
    }).finally(() => {
      if (!controller.signal.aborted) setLoading(false);
    });
    return () => controller.abort();
  }, [domain, reviewStatus, refreshKey]);

  const catalogByType = useMemo(() => new Map(catalog.map((item) => [item.action_type, item])), [catalog]);
  const openProposal = (proposal: ControlledActionProposal) => {
    setSelectedProposal(proposal);
    setValidation(null);
    setDecision("accept");
    setReviewNote("");
    setConfirmed(false);
    setDialogError(null);
    setIdempotencyKey(controlledActionIdempotencyKey());
  };
  const closeProposal = () => {
    if (busy) return;
    setSelectedProposal(null);
    setValidation(null);
    setConfirmed(false);
    setDialogError(null);
  };
  const parametersFor = (proposal: ControlledActionProposal) => {
    const rawBatchId = proposal.parameters.batch_id;
    return typeof rawBatchId === "number" && Number.isInteger(rawBatchId) && rawBatchId > 0 ? { batch_id: rawBatchId } : {};
  };
  const validateProposal = async (proposal: ControlledActionProposal) => {
    if (!proposal.resource_id || !isControlledExceptionActionType(proposal.action_type)) return;
    setBusy(true);
    setDialogError(null);
    try {
      const nextValidation = await validateControlledExceptionAction(proposal.resource_id, proposal.action_type, parametersFor(proposal));
      setValidation(nextValidation);
      setSelectedProposal(nextValidation.proposal);
      setConfirmed(false);
      setIdempotencyKey(controlledActionIdempotencyKey());
    } catch (reason) {
      setValidation(null);
      setDialogError(normalizeUiError(reason, "动作校验失败"));
    } finally {
      setBusy(false);
    }
  };
  const validateNewAction = async () => {
    const normalizedCaseNo = caseNo.trim();
    if (!normalizedCaseNo || busy) return;
    const parsedBatchId = batchId.trim() ? Number.parseInt(batchId, 10) : null;
    if (batchId.trim() && (!parsedBatchId || parsedBatchId <= 0)) {
      setError(new Error("批次 ID 必须为正整数"));
      return;
    }
    setBusy(true);
    setError(null);
    try {
      const nextValidation = await validateControlledExceptionAction(normalizedCaseNo, newActionType, parsedBatchId ? { batch_id: parsedBatchId } : {});
      setValidation(nextValidation);
      setSelectedProposal(nextValidation.proposal);
      setConfirmed(false);
      setDialogError(null);
      setIdempotencyKey(controlledActionIdempotencyKey());
    } catch (reason) {
      setError(normalizeUiError(reason, "动作校验失败"));
    } finally {
      setBusy(false);
    }
  };
  const refreshChangedProposal = async (proposalNo: string, reason: unknown) => {
    if (reason instanceof ApiError && reason.status === 409) {
      try {
        const latest = await controlledActionProposal(proposalNo);
        setSelectedProposal(latest);
      } catch {
        // The original structured error remains the actionable result.
      }
      setValidation(null);
      setConfirmed(false);
      setDialogError(apiErrorWithMessage(reason, "提案或业务证据已变化，已刷新当前状态，请重新校验后再提交。"));
      return;
    }
    setDialogError(normalizeUiError(reason, "受控动作提交失败"));
  };
  const submitSelectedProposal = async () => {
    const proposal = selectedProposal;
    if (!proposal || !confirmed || busy) return;
    if (!window.confirm(`确认以当前账号执行“${catalogByType.get(proposal.action_type)?.label ?? proposal.action_type}”？该操作会写入完整审计。`)) return;
    setBusy(true);
    setDialogError(null);
    try {
      let execution: ControlledActionExecution;
      if (proposal.domain === "crm") {
        execution = await reviewControlledCrmAction(proposal.proposal_no, {
          expected_updated_at: proposal.updated_at,
          confirmation: true,
          decision,
          idempotency_key: idempotencyKey,
          note: reviewNote.trim() || null
        });
      } else {
        if (!validation?.validation_token || validation.proposal.proposal_no !== proposal.proposal_no) {
          setDialogError(new Error("高风险动作必须先重新校验，且校验结果只能在当前弹窗中使用。"));
          return;
        }
        execution = await executeControlledAction(proposal.proposal_no, {
          expected_updated_at: proposal.updated_at,
          confirmation: true,
          idempotency_key: idempotencyKey,
          validation_token: validation.validation_token
        });
      }
      setMessage(`动作 ${execution.execution_no} 已提交，状态：${controlledActionStatusLabel(execution.status)}。`);
      setSelectedProposal(null);
      setValidation(null);
      setConfirmed(false);
      reload();
    } catch (reason) {
      await refreshChangedProposal(proposal.proposal_no, reason);
    } finally {
      setBusy(false);
    }
  };

  const availableExceptionCatalog = catalog.filter((item) => isControlledExceptionActionType(item.action_type));
  return (
    <div data-testid="controlled-action-center">
      {message ? <div className="mb-4 rounded-lg border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm font-bold text-emerald-800" role="status">{message}</div> : null}
      {error ? <div className="mb-4"><ApiErrorNotice error={error} navigate={navigate} onRetry={reload} /></div> : null}

      {canExecuteException ? <section className="mb-4 border-y border-border bg-white px-4 py-4" aria-label="新建受控动作校验">
        <div className="flex flex-col gap-3 xl:flex-row xl:items-end">
          <div className="min-w-0 flex-1"><h2 className="m-0 text-base font-black text-foreground">高风险动作预演</h2><p className="m-0 mt-1 text-sm font-bold text-muted-foreground">输入案件编号后先校验影响范围。校验通过不代表自动执行。</p></div>
          <label className="grid min-w-[220px] gap-1 text-xs font-black text-muted-foreground">案件编号<input className="project-input-sm" value={caseNo} onChange={(event) => setCaseNo(event.target.value)} placeholder="EXC-..." data-testid="controlled-action-case-no" /></label>
          <label className="grid min-w-[220px] gap-1 text-xs font-black text-muted-foreground">动作<select className="project-input-sm" value={newActionType} onChange={(event) => setNewActionType(event.target.value as ControlledExceptionActionType)}>{availableExceptionCatalog.length ? availableExceptionCatalog.map((item) => <option key={item.action_type} value={item.action_type}>{item.label}</option>) : controlledExceptionActionTypes.map((value) => <option key={value} value={value}>{value}</option>)}</select></label>
          <label className="grid min-w-[140px] gap-1 text-xs font-black text-muted-foreground">批次 ID（可选）<input className="project-input-sm" inputMode="numeric" value={batchId} onChange={(event) => setBatchId(event.target.value.replace(/\D/g, ""))} /></label>
          <Button disabled={busy || !caseNo.trim()} onClick={() => void validateNewAction()}><ShieldCheck className="mr-1.5 h-4 w-4" />校验影响</Button>
        </div>
      </section> : null}

      <section className="mb-4 overflow-hidden border-y border-border bg-white" aria-label="受控动作目录">
        <div className="border-b border-border px-4 py-3"><h2 className="m-0 text-base font-black text-foreground">动作目录</h2><p className="m-0 mt-1 text-sm font-bold text-muted-foreground">可用状态同时受功能开关、当前权限、生产策略和风险等级控制。</p></div>
        <div className="grid md:grid-cols-2 xl:grid-cols-3">{catalog.map((item) => <article key={item.action_type} className="min-h-32 border-b border-r border-border px-4 py-3"><div className="flex items-start justify-between gap-3"><strong className="text-sm text-foreground">{item.label}</strong><Badge tone={item.available ? item.risk_level === "high" ? "warn" : "ok" : "neutral"}>{item.available ? `${item.risk_level === "high" ? "高风险" : "可用"}` : "未开放"}</Badge></div><p className="m-0 mt-2 font-mono text-xs text-muted-foreground">{item.domain} · {item.action_type}</p><p className="m-0 mt-2 text-xs font-bold leading-5 text-muted-foreground">{item.blockers.length ? item.blockers.map(controlledActionBlockerLabel).join("；") : `人工确认 · ${item.required_permissions.join("、") || "按来源权限"}`}</p></article>)}</div>
      </section>

      <DataTableShell title="待复核提案" description="仅展示当前账号数据范围内的提案；页面可见不等于允许执行。" meta={loading ? "正在加载" : `${proposals.length} / ${proposalTotal} 条`} toolbar={<DataToolbar onReset={() => { setDomain(""); setReviewStatus("pending"); }}><ToolbarSelect label="业务域" value={domain} onChange={setDomain} options={[{ value: "", label: "全部业务域" }, { value: "crm", label: "客户 CRM" }, { value: "inventory", label: "库存" }, { value: "receivable", label: "应收" }, { value: "master_data", label: "主数据" }, { value: "import", label: "导入" }]} /><ToolbarSelect label="复核状态" value={reviewStatus} onChange={(value) => setReviewStatus(value as typeof reviewStatus)} options={[{ value: "", label: "全部状态" }, { value: "pending", label: "待复核" }, { value: "accepted", label: "已采纳" }, { value: "rejected", label: "已拒绝" }]} /><Button secondary onClick={reload}><RefreshCcw className="mr-1.5 h-4 w-4" />刷新</Button></DataToolbar>}>
        <Table headers={["风险", "提案", "业务对象", "状态", "阻断原因", "操作"]} minWidth={1040} emptyMessage={loading ? "正在加载提案..." : "当前范围没有动作提案。"}>
          {proposals.map((proposal) => {
            const isCrm = proposal.domain === "crm";
            const canOperate = proposal.review_status === "pending" && (isCrm ? canReviewCrm && proposal.executable : canExecuteException);
            return <tr key={proposal.proposal_no}><td><Badge tone={proposal.risk_level === "high" ? "bad" : proposal.risk_level === "medium" ? "warn" : "neutral"}>{proposal.risk_level === "high" ? "高" : proposal.risk_level === "medium" ? "中" : "低"}</Badge></td><td><strong className="block text-sm text-foreground">{catalogByType.get(proposal.action_type)?.label ?? proposal.action_type}</strong><small className="mt-1 block font-mono text-xs text-muted-foreground">{proposal.proposal_no}</small></td><td><strong className="block text-sm text-foreground">{proposal.resource_type ?? proposal.domain}</strong><small className="mt-1 block font-mono text-xs text-muted-foreground">{proposal.resource_id ?? "-"}</small></td><td><Badge tone={proposal.review_status === "pending" ? "warn" : proposal.review_status === "accepted" ? "ok" : "neutral"}>{controlledActionStatusLabel(proposal.review_status)}</Badge><small className="mt-1 block text-xs text-muted-foreground">{controlledActionStatusLabel(proposal.status)}</small></td><td className="max-w-[280px] text-xs font-bold text-muted-foreground">{proposal.blockers.length ? proposal.blockers.map(controlledActionBlockerLabel).join("；") : "无阻断"}</td><td>{canOperate ? <Button secondary onClick={() => openProposal(proposal)}>{isCrm ? "人工复核" : "重新校验"}</Button> : <span className="text-xs font-bold text-muted-foreground">不可操作</span>}</td></tr>;
          })}
        </Table>
      </DataTableShell>

      <div className="mt-4"><DataTableShell title="最近执行" description="所有执行均来自人工确认，并保留幂等和验证记录。" meta={`${executions.length} / ${executionTotal} 条`}><Table headers={["执行编号", "提案", "状态", "尝试", "完成时间", "结果"]} minWidth={940} emptyMessage={loading ? "正在加载执行记录..." : "暂无执行记录。"}>{executions.map((execution) => <tr key={execution.execution_no}><td className="font-mono text-xs font-bold">{execution.execution_no}</td><td className="font-mono text-xs">{execution.proposal_no}</td><td><Badge tone={execution.status === "completed" ? "ok" : execution.status === "failed" ? "bad" : "warn"}>{controlledActionStatusLabel(execution.status)}</Badge></td><td>{execution.attempts}</td><td>{formatDateTime(execution.completed_at)}</td><td className="text-xs font-bold text-muted-foreground">{execution.error_code ? `错误：${execution.error_code}` : execution.verification.human_confirmed === true ? "人工确认，验证完成" : "已记录"}</td></tr>)}</Table></DataTableShell></div>

      {selectedProposal ? <Modal title={selectedProposal.domain === "crm" ? "人工复核 AI 提案" : "高风险动作确认"} onClose={closeProposal} size="wide">
        <div className="grid gap-4" data-testid="controlled-action-confirmation">
          <section className="grid gap-3 border-y border-border bg-slate-50 px-4 py-4 sm:grid-cols-2"><div><span className="text-xs font-black text-muted-foreground">动作</span><strong className="mt-1 block text-sm text-foreground">{catalogByType.get(selectedProposal.action_type)?.label ?? selectedProposal.action_type}</strong></div><div><span className="text-xs font-black text-muted-foreground">业务对象</span><strong className="mt-1 block font-mono text-sm text-foreground">{selectedProposal.resource_id ?? "-"}</strong></div><div><span className="text-xs font-black text-muted-foreground">风险</span><strong className="mt-1 block text-sm text-red-700">{selectedProposal.risk_level === "high" ? "高风险" : "需人工复核"}</strong></div><div><span className="text-xs font-black text-muted-foreground">提案版本</span><strong className="mt-1 block text-sm text-foreground">{formatDateTime(selectedProposal.updated_at)}</strong></div></section>
          {dialogError ? <ApiErrorNotice error={dialogError} navigate={navigate} /> : null}
          {selectedProposal.domain === "crm" ? <><AccountField label="复核结论"><select className="project-input" value={decision} onChange={(event) => setDecision(event.target.value as typeof decision)}><option value="accept">采纳判断</option><option value="reject">拒绝判断</option><option value="task">转为待支持事项</option></select></AccountField><AccountField label="复核说明（可选）"><textarea className="project-input min-h-24" maxLength={1000} value={reviewNote} onChange={(event) => setReviewNote(event.target.value)} /></AccountField></> : <><div className="rounded-lg border border-amber-200 bg-amber-50 px-4 py-3 text-sm font-bold leading-6 text-amber-800">执行前必须重新校验当前案件证据和来源权限。校验令牌不会显示或保存，关闭弹窗后立即丢弃。</div>{validation?.validation_token ? <div className="rounded-lg border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm font-bold text-emerald-800" data-testid="controlled-action-validation-ready">校验通过，有效期至 {formatDateTime(validation.validation_expires_at)}。</div> : <Button secondary disabled={busy} onClick={() => void validateProposal(selectedProposal)}><ShieldCheck className="mr-1.5 h-4 w-4" />{busy ? "校验中" : "重新校验"}</Button>}</>}
          <label className="flex min-h-12 cursor-pointer items-start gap-3 rounded-lg border border-border px-4 py-3 text-sm font-bold text-foreground"><input type="checkbox" className="mt-1" checked={confirmed} onChange={(event) => setConfirmed(event.target.checked)} data-testid="controlled-action-confirm" /><span>我已核对业务对象、风险和影响范围，并确认以当前账号执行。AI 模型未代替我确认。</span></label>
          <div className="flex justify-end gap-2"><Button secondary disabled={busy} onClick={closeProposal}>取消</Button><Button disabled={busy || !confirmed || (selectedProposal.domain !== "crm" && !validation?.validation_token)} onClick={() => void submitSelectedProposal()}>{busy ? "提交中" : selectedProposal.domain === "crm" ? "确认复核" : "确认执行"}</Button></div>
        </div>
      </Modal> : null}
    </div>
  );
}

type ExceptionCenterView = "cases" | "actions" | "operations" | "quality";

function ExceptionCenterPage({ permissions, currentUser, navigate, onPermissionsRefresh, assistantOpen, assistantBusy, assistantContextResetKey, onAssistantContextChange, onAssistantLaunch }: { permissions: PermissionCode[]; currentUser: UserPublic; navigate: (page: Page, path?: string) => void; onPermissionsRefresh: () => Promise<PermissionCode[]>; assistantOpen: boolean; assistantBusy: boolean; assistantContextResetKey: number; onAssistantContextChange: (context: ExceptionAssistantContext) => void; onAssistantLaunch: (launch: ExceptionAssistantLaunch) => void }) {
  const canViewCases = hasPermission(permissions, "exception_center.view");
  const canViewActions = hasAnyPermission(permissions, ["crm_insight.review", "exception_center.action_execute"]);
  const canManage = hasPermission(permissions, "exception_center.manage");
  const canManagePolicy = hasPermission(permissions, "exception_center.policy_manage");
  const requestedCenterView = initialQueryParam("view");
  const canOpenCenterView = (view: ExceptionCenterView) => view === "cases"
    ? canViewCases
    : view === "actions"
        ? canViewActions
        : canManagePolicy;
  const fallbackCenterView: ExceptionCenterView = canViewCases ? "cases" : canViewActions ? "actions" : canManagePolicy ? "operations" : "cases";
  const requestedView = (["cases", "actions", "operations", "quality"] as ExceptionCenterView[]).includes(requestedCenterView as ExceptionCenterView)
    ? requestedCenterView as ExceptionCenterView
    : "cases";
  const initialBatchFilter = useMemo(() => {
    const unassigned = initialQueryParam("source_batch_unassigned") === "true";
    const kind = exceptionSourceBatchKind(initialQueryParam("source_batch_kind"));
    const id = normalizeExceptionBatchId(initialQueryParam("source_batch_id"));
    return {
      kind: unassigned ? "" as const : kind,
      id: unassigned || !kind ? "" : id,
      unassigned
    };
  }, []);
  const [summaryData, setSummaryData] = useState<ExceptionSummary | null>(null);
  const [pageData, setPageData] = useState<ExceptionCasePage | null>(null);
  const [aggregationRows, setAggregationRows] = useState<ExceptionAggregationGroup[]>([]);
  const [aggregationTotal, setAggregationTotal] = useState(0);
  const [aggregationTruncated, setAggregationTruncated] = useState(false);
  const [summaryLoading, setSummaryLoading] = useState(true);
  const [listLoading, setListLoading] = useState(true);
  const [summaryError, setSummaryError] = useState<Error | null>(null);
  const [listError, setListError] = useState<Error | null>(null);
  const [query, setQuery] = useState(() => normalizeExceptionQuery(initialQueryParam("q")));
  const [status, setStatus] = useState(initialQueryParam("status") as ExceptionCaseStatus | "");
  const [domain, setDomain] = useState(initialQueryParam("domain"));
  const [severity, setSeverity] = useState(initialQueryParam("severity"));
  const [occurrenceType, setOccurrenceType] = useState(initialQueryParam("occurrence_type") as ExceptionOccurrenceType | "");
  const [workScope, setWorkScope] = useState(initialQueryParam("assignment") as ExceptionWorkScope | "");
  const [slaFilter, setSlaFilter] = useState(initialQueryParam("sla_status") as ExceptionSlaFilter | "");
  const [ruleCode, setRuleCode] = useState(initialQueryParam("rule_code"));
  const [sourceBatchKind, setSourceBatchKind] = useState<ExceptionSourceBatchKind | "">(initialBatchFilter.kind);
  const [sourceBatchId, setSourceBatchId] = useState(initialBatchFilter.id);
  const [sourceBatchUnassigned, setSourceBatchUnassigned] = useState(initialBatchFilter.unassigned);
  const [groupBy, setGroupBy] = useState(initialQueryParam("group_by") as ExceptionGroupBy | "");
  const [centerView, setCenterView] = useState<ExceptionCenterView>(canOpenCenterView(requestedView) ? requestedView : fallbackCenterView);
  const [offset, setOffset] = useState(0);
  const [refreshKey, setRefreshKey] = useState(0);
  const [selectedCaseNo, setSelectedCaseNo] = useState(initialQueryParam("open"));
  const [selectedCaseNos, setSelectedCaseNos] = useState<Set<string>>(() => new Set());
  const [batchMessage, setBatchMessage] = useState("");
  const [policyOpen, setPolicyOpen] = useState(false);
  const selectPageRef = useRef<HTMLInputElement>(null);
  const pinnedAssistantCaseRef = useRef("");
  const assistantContextResetRef = useRef(assistantContextResetKey);
  const limit = 30;

  useEffect(() => {
    const rawQuery = initialQueryParam("q");
    const normalizedQuery = normalizeExceptionQuery(rawQuery);
    const rawBatchKind = initialQueryParam("source_batch_kind");
    const rawBatchId = initialQueryParam("source_batch_id");
    const normalizedBatchKind = exceptionSourceBatchKind(rawBatchKind);
    const normalizedBatchId = normalizeExceptionBatchId(rawBatchId);
    const unassignedBatch = initialQueryParam("source_batch_unassigned") === "true";
    const conflictingBatch = unassignedBatch && Boolean(rawBatchKind || rawBatchId);
    const invalidBatchKind = Boolean(rawBatchKind) && !normalizedBatchKind;
    const orphanBatchId = Boolean(rawBatchId) && !normalizedBatchKind;
    const invalidBatchId = Boolean(rawBatchId) && !normalizedBatchId;
    if (rawQuery !== normalizedQuery || conflictingBatch || invalidBatchKind || orphanBatchId || invalidBatchId) {
      replaceCurrentQueryParams({
        q: normalizedQuery || null,
        source_batch_kind: conflictingBatch || invalidBatchKind ? null : normalizedBatchKind || null,
        source_batch_id: conflictingBatch || invalidBatchKind || orphanBatchId || invalidBatchId ? null : normalizedBatchId || null
      });
    }
  }, []);

  useEffect(() => {
    if (!canManagePolicy && policyOpen) setPolicyOpen(false);
    const rawQueryView = initialQueryParam("view") || "cases";
    const queryView = (["cases", "actions", "operations", "quality"] as ExceptionCenterView[]).includes(rawQueryView as ExceptionCenterView)
      ? rawQueryView as ExceptionCenterView
      : "cases";
    if (canOpenCenterView(queryView)) {
      if (centerView !== queryView) setCenterView(queryView);
      return;
    }
    const allowedView = canOpenCenterView(centerView) ? centerView : fallbackCenterView;
    if (centerView !== allowedView) setCenterView(allowedView);
    replaceCurrentQueryParams({ view: allowedView === "cases" ? null : allowedView, open: allowedView === "cases" ? undefined : null });
    if (allowedView !== "cases") setSelectedCaseNo("");
  }, [canManagePolicy, canViewCases, canViewActions, centerView, fallbackCenterView, policyOpen]);

  const reload = () => setRefreshKey((value) => value + 1);
  useEffect(() => {
    if (!canViewCases || centerView !== "cases") {
      setSummaryLoading(false);
      setSummaryData(null);
      setSummaryError(null);
      return;
    }
    let active = true;
    setSummaryLoading(true);
    setSummaryError(null);
    setSummaryData(null);
    void exceptionSummary({ occurrence_type: occurrenceType || undefined })
      .then((nextSummary) => {
        if (active) setSummaryData(nextSummary);
      })
      .catch((reason) => {
        if (active) setSummaryError(normalizeUiError(reason, "异常摘要加载失败"));
      })
      .finally(() => {
        if (active) setSummaryLoading(false);
      });
    return () => {
      active = false;
    };
  }, [canViewCases, centerView, occurrenceType, refreshKey]);

  useEffect(() => {
    if (!canViewCases || centerView !== "cases") {
      setListLoading(false);
      setPageData(null);
      setAggregationRows([]);
      setListError(null);
      return;
    }
    let active = true;
    setListLoading(true);
    setListError(null);
    setPageData(null);
    setAggregationRows([]);
    setAggregationTotal(0);
    setAggregationTruncated(false);
    const filters = {
      q: normalizeExceptionQuery(query) || undefined,
      status: status || undefined,
      domain: domain || undefined,
      severity: severity || undefined,
      occurrence_type: occurrenceType || undefined,
      assignment: workScope || undefined,
      sla_status: slaFilter || undefined,
      rule_code: ruleCode.trim() || undefined,
      source_batch_kind: !sourceBatchUnassigned && sourceBatchKind ? sourceBatchKind : undefined,
      source_batch_id: !sourceBatchUnassigned && sourceBatchKind && normalizeExceptionBatchId(sourceBatchId) ? Number(sourceBatchId) : undefined,
      source_batch_unassigned: sourceBatchUnassigned || undefined
    };
    const request = groupBy
      ? exceptionCaseAggregations({ ...filters, group_by: groupBy })
      : exceptionCasesPage({ ...filters, limit, offset });
    void request.then((response) => {
      if (!active) return;
      if ("items" in response) setPageData(response);
      else {
        setAggregationRows(response.groups);
        setAggregationTotal(response.total);
        setAggregationTruncated(response.truncated);
      }
    }).catch((reason) => {
      if (active) setListError(normalizeUiError(reason, "异常案件加载失败"));
    }).finally(() => {
      if (active) setListLoading(false);
    });
    return () => {
      active = false;
    };
  }, [canViewCases, centerView, query, status, domain, severity, occurrenceType, workScope, slaFilter, ruleCode, sourceBatchKind, sourceBatchId, sourceBatchUnassigned, groupBy, offset, refreshKey]);

  useEffect(() => {
    setSelectedCaseNos(new Set());
  }, [query, status, domain, severity, occurrenceType, workScope, slaFilter, ruleCode, sourceBatchKind, sourceBatchId, sourceBatchUnassigned, groupBy, offset]);

  const updateFilters = (updates: { status?: ExceptionCaseStatus | ""; domain?: string; severity?: string; occurrenceType?: ExceptionOccurrenceType | ""; workScope?: ExceptionWorkScope | ""; slaFilter?: ExceptionSlaFilter | ""; ruleCode?: string; sourceBatchKind?: ExceptionSourceBatchKind | ""; sourceBatchId?: string; sourceBatchUnassigned?: boolean; groupBy?: ExceptionGroupBy | ""; query?: string }) => {
    const nextQuery = updates.query !== undefined ? updates.query.slice(0, 200) : query;
    const nextSourceBatchUnassigned = updates.sourceBatchUnassigned !== undefined
      ? updates.sourceBatchUnassigned
      : updates.sourceBatchKind || updates.sourceBatchId
        ? false
        : sourceBatchUnassigned;
    const nextSourceBatchKind = nextSourceBatchUnassigned ? "" : updates.sourceBatchKind !== undefined ? updates.sourceBatchKind : sourceBatchKind;
    const nextSourceBatchId = nextSourceBatchUnassigned || !nextSourceBatchKind ? "" : updates.sourceBatchId !== undefined ? normalizeExceptionBatchId(updates.sourceBatchId) : sourceBatchId;
    if (updates.status !== undefined) setStatus(updates.status);
    if (updates.domain !== undefined) setDomain(updates.domain);
    if (updates.severity !== undefined) setSeverity(updates.severity);
    if (updates.occurrenceType !== undefined) setOccurrenceType(updates.occurrenceType);
    if (updates.workScope !== undefined) setWorkScope(updates.workScope);
    if (updates.slaFilter !== undefined) setSlaFilter(updates.slaFilter);
    if (updates.ruleCode !== undefined) setRuleCode(updates.ruleCode);
    if (updates.sourceBatchKind !== undefined || updates.sourceBatchId !== undefined || updates.sourceBatchUnassigned !== undefined) setSourceBatchKind(nextSourceBatchKind);
    if (updates.sourceBatchKind !== undefined || updates.sourceBatchId !== undefined || updates.sourceBatchUnassigned !== undefined) setSourceBatchId(nextSourceBatchId);
    if (updates.sourceBatchUnassigned !== undefined || updates.sourceBatchKind !== undefined || updates.sourceBatchId !== undefined) setSourceBatchUnassigned(nextSourceBatchUnassigned);
    if (updates.groupBy !== undefined) setGroupBy(updates.groupBy);
    if (updates.query !== undefined) setQuery(nextQuery);
    setOffset(0);
    setBatchMessage("");
    replaceCurrentQueryParams({
      status: updates.status !== undefined ? updates.status : status,
      domain: updates.domain !== undefined ? updates.domain : domain,
      severity: updates.severity !== undefined ? updates.severity : severity,
      occurrence_type: updates.occurrenceType !== undefined ? updates.occurrenceType : occurrenceType,
      assignment: updates.workScope !== undefined ? updates.workScope : workScope,
      sla_status: updates.slaFilter !== undefined ? updates.slaFilter : slaFilter,
      rule_code: updates.ruleCode !== undefined ? updates.ruleCode : ruleCode,
      source_batch_kind: nextSourceBatchKind,
      source_batch_id: nextSourceBatchId,
      source_batch_unassigned: nextSourceBatchUnassigned ? "true" : null,
      group_by: updates.groupBy !== undefined ? updates.groupBy : groupBy,
      q: normalizeExceptionQuery(nextQuery) || null
    });
  };
  const openCase = (caseNo: string) => {
    setSelectedCaseNo(caseNo);
    replaceCurrentQueryParams({ open: caseNo });
  };
  const canAskCaseAi = summaryData?.ai_case_analysis_enabled === true
    && hasPermission(permissions, "exception_center.view")
    && hasPermission(permissions, "crm_insight.view");
  const askCaseAi = (row: Pick<ExceptionCaseItem, "case_no" | "title" | "severity" | "status" | "evidence_version">) => {
    if (!canAskCaseAi || assistantBusy) return;
    setSelectedCaseNo("");
    pinnedAssistantCaseRef.current = row.case_no;
    onAssistantLaunch({
      id: crypto.randomUUID(),
      context: { scope: "case", filters: {}, case_nos: [row.case_no] },
      contextMeta: {
        case_no: row.case_no,
        title: row.title,
        severity: row.severity,
        status: row.status,
        evidence_version: row.evidence_version,
      },
      operation: "exception.case_analysis",
      message: "分析该异常发生的原因，并给出可验证的解决方案",
    });
  };
  const closeCase = () => {
    setSelectedCaseNo("");
    replaceCurrentQueryParams({ open: null });
  };
  const changeCenterView = (next: ExceptionCenterView) => {
    const allowedView = canOpenCenterView(next) ? next : fallbackCenterView;
    setCenterView(allowedView);
    replaceCurrentQueryParams({ view: allowedView === "cases" ? null : allowedView, open: null });
    if (allowedView !== "cases") setSelectedCaseNo("");
  };

  const currentPageSelectableCases = (pageData?.items ?? []).filter((row) => exceptionBatchAssignableStatuses.includes(row.status));
  const currentPageCaseNos = currentPageSelectableCases.map((row) => row.case_no);
  const selectedOnPageCount = currentPageCaseNos.filter((caseNo) => selectedCaseNos.has(caseNo)).length;
  const selectedCases = currentPageSelectableCases.filter((row) => selectedCaseNos.has(row.case_no));
  const selectedProcessingCount = selectedCases.filter((row) => !exceptionBatchIgnoreableStatuses.includes(row.status)).length;
  const allCurrentPageSelected = currentPageCaseNos.length > 0 && selectedOnPageCount === currentPageCaseNos.length;
  useEffect(() => {
    if (selectPageRef.current) {
      selectPageRef.current.indeterminate = selectedOnPageCount > 0 && !allCurrentPageSelected;
    }
  }, [selectedOnPageCount, allCurrentPageSelected]);

  useEffect(() => {
    if (assistantContextResetRef.current !== assistantContextResetKey) {
      assistantContextResetRef.current = assistantContextResetKey;
      pinnedAssistantCaseRef.current = "";
      setSelectedCaseNos(new Set());
    }
    if (selectedCaseNo) pinnedAssistantCaseRef.current = selectedCaseNo;
    if (!assistantOpen && !selectedCaseNo) pinnedAssistantCaseRef.current = "";
    const pinnedCase = selectedCaseNo || (assistantOpen ? pinnedAssistantCaseRef.current : "");
    const selected = Array.from(selectedCaseNos).slice(0, 30);
    const filters: AiChatContext["filters"] = {
      q: normalizeExceptionQuery(query) || null,
      status: status || null,
      domain: domain || null,
      severity: severity || null,
      occurrence_type: occurrenceType || null,
      rule_code: ruleCode.trim() || null
    };
    if (pinnedCase) onAssistantContextChange({ request: { scope: "case", filters: {}, case_nos: [pinnedCase] }, label: `当前案件 · ${pinnedCase}` });
    else if (selected.length) onAssistantContextChange({ request: { scope: "selected_cases", filters: {}, case_nos: selected }, label: `已选案件 · ${selected.length} 条` });
    else onAssistantContextChange({ request: { scope: "current_filters", filters, case_nos: [] }, label: "当前筛选" });
    if (assistantOpen && selectedCaseNo) {
      setSelectedCaseNo("");
      replaceCurrentQueryParams({ open: null });
    }
  }, [assistantOpen, assistantContextResetKey, selectedCaseNo, selectedCaseNos, query, status, domain, severity, occurrenceType, ruleCode, onAssistantContextChange]);

  const toggleCurrentPage = () => {
    setSelectedCaseNos((current) => {
      const next = new Set(current);
      if (allCurrentPageSelected) currentPageCaseNos.forEach((caseNo) => next.delete(caseNo));
      else currentPageCaseNos.forEach((caseNo) => next.add(caseNo));
      return next;
    });
  };
  const toggleCase = (caseNo: string) => {
    setSelectedCaseNos((current) => {
      const next = new Set(current);
      if (next.has(caseNo)) next.delete(caseNo);
      else next.add(caseNo);
      return next;
    });
  };
  const completeBatchAction = (message: string) => {
    setSelectedCaseNos(new Set());
    setBatchMessage(message);
    reload();
  };

  const summaryItems: Array<{ label: string; value: number; status?: ExceptionCaseStatus; tone: string }> = [
    { label: "全部案件", value: summaryData?.total ?? 0, tone: "text-foreground" },
    { label: "待处理", value: summaryData?.open ?? 0, status: "open", tone: "text-red-700" },
    { label: "待执行", value: summaryData?.action_required ?? 0, status: "action_required", tone: "text-red-700" },
    { label: "处理中", value: summaryData?.processing ?? 0, status: "processing", tone: "text-amber-700" },
    { label: "证据不足", value: summaryData?.blocked ?? 0, status: "blocked", tone: "text-amber-700" },
    { label: "已解决", value: summaryData?.resolved ?? 0, status: "resolved", tone: "text-emerald-700" },
    { label: "已忽略", value: summaryData?.ignored ?? 0, status: "ignored", tone: "text-muted-foreground" }
  ];
  return (
    <>
      <Header eyebrow="异常治理与 AI 协同" title="统一异常中心" description="集中处理异常案件、全局 AI 分析、受控动作、运行状态与诊断质量。" actions={<>{centerView === "cases" ? <Button secondary onClick={reload}><RefreshCcw className="mr-1.5 h-4 w-4" />刷新</Button> : null}{canManagePolicy ? <Button secondary onClick={() => setPolicyOpen(true)}><Settings className="mr-1.5 h-4 w-4" />巡检策略</Button> : null}</>} />

      <nav className="mb-4 flex min-w-0 gap-1 overflow-x-auto border-b border-border" aria-label="异常中心视图">
        {[
          { key: "cases" as const, label: "异常案件", icon: Siren, show: canViewCases },
          { key: "actions" as const, label: "受控动作", icon: ShieldCheck, show: canViewActions },
          { key: "operations" as const, label: "运行运维", icon: Activity, show: canManagePolicy },
          { key: "quality" as const, label: "诊断质量", icon: BarChart3, show: canManagePolicy }
        ].filter((item) => item.show).map((item) => { const Icon = item.icon; return <button key={item.key} type="button" aria-current={centerView === item.key ? "page" : undefined} onClick={() => changeCenterView(item.key)} className={`inline-flex min-h-10 shrink-0 items-center gap-2 border-b-2 px-3 text-sm font-black transition ${centerView === item.key ? "border-primary text-primary" : "border-transparent text-muted-foreground hover:text-foreground"}`}><Icon className="h-4 w-4" />{item.label}</button>; })}
      </nav>

      {centerView === "cases" ? <>

      <section className="mb-4 overflow-hidden rounded-lg border border-border bg-white" aria-label="异常案件摘要">
        <div className="grid grid-cols-2 md:grid-cols-4 xl:grid-cols-7">
          {summaryItems.map((item) => {
            const active = (item.status ?? "") === status;
            return <button key={item.label} type="button" data-testid={`exception-summary-${item.status ?? "all"}`} aria-pressed={active} onClick={() => updateFilters({ status: item.status ?? "" })} className={`min-h-20 border-b border-r border-border px-4 py-3 text-left transition hover:bg-primary-soft ${active ? "bg-primary-soft ring-1 ring-inset ring-primary/30" : "bg-white"}`}><span className="block text-xs font-black text-muted-foreground">{item.label}</span><strong className={`mt-1 block font-mono text-2xl font-black ${item.tone}`}>{summaryLoading && !summaryData ? "-" : item.value}</strong></button>;
          })}
        </div>
      </section>

      <section className="mb-4 flex flex-wrap items-center gap-2 border-y border-border bg-white px-3 py-3" aria-label="异常快捷筛选" data-testid="exception-quick-filters">
        <span className="mr-1 text-xs font-black text-muted-foreground">我的工作队列</span>
        {[
          { key: "mine", label: "待我处理", value: summaryData?.assigned_to_me ?? summaryData?.mine ?? 0, active: workScope === "mine", onClick: () => updateFilters({ workScope: workScope === "mine" ? "" : "mine" }) },
          { key: "unassigned", label: "未分派", value: summaryData?.unassigned ?? 0, active: workScope === "unassigned", onClick: () => updateFilters({ workScope: workScope === "unassigned" ? "" : "unassigned" }) },
          { key: "overdue", label: "已超期", value: summaryData?.overdue ?? 0, active: slaFilter === "overdue", onClick: () => updateFilters({ slaFilter: slaFilter === "overdue" ? "" : "overdue" }) },
          { key: "due-soon", label: "24 小时内到期", value: summaryData?.due_soon ?? 0, active: slaFilter === "due_soon", onClick: () => updateFilters({ slaFilter: slaFilter === "due_soon" ? "" : "due_soon" }) }
        ].map((item) => <button key={item.key} type="button" data-testid={`exception-quick-${item.key}`} aria-pressed={item.active} onClick={item.onClick} className={`inline-flex min-h-9 items-center gap-2 rounded-md border px-3 text-sm font-black transition ${item.active ? "border-primary bg-primary-soft text-primary" : "border-border bg-white text-foreground hover:bg-secondary"}`}>{item.label}<span className="font-mono text-xs">{item.value}</span></button>)}
      </section>

      {summaryError ? <div className="mb-4" data-testid="exception-summary-error"><ApiErrorNotice error={summaryError} navigate={navigate} onRetry={reload} /></div> : null}
      {batchMessage ? <div className="mb-4 flex items-start gap-2 rounded-lg border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm font-bold text-emerald-800" role="status" data-testid="exception-batch-success"><Check className="mt-0.5 h-4 w-4 shrink-0" />{batchMessage}</div> : null}

      <DataTableShell
        title="异常案件"
        description="点击任意案件查看证据、原始记录、诊断和处理历史。"
        meta={listLoading ? "正在加载" : groupBy ? `${aggregationRows.length} / ${aggregationTotal} 组` : `${pageData?.total ?? 0} 条`}
        toolbar={<DataToolbar onReset={() => updateFilters({ query: "", status: "", domain: "", severity: "", occurrenceType: "", workScope: "", slaFilter: "", ruleCode: "", sourceBatchKind: "", sourceBatchId: "", sourceBatchUnassigned: false, groupBy: "" })}>
          <ToolbarSearch value={query} onChange={(value) => updateFilters({ query: value })} placeholder="搜索案件编号、规则、对象或原因" maxLength={200} />
          {groupBy ? <span className="inline-flex min-h-9 items-center rounded-md border border-border bg-secondary px-3 text-xs font-bold text-muted-foreground" data-testid="exception-aggregation-search-scope">聚合结果基于当前全部筛选条件，包含关键词</span> : null}
          <ToolbarSelect label="模块" value={domain} onChange={(value) => updateFilters({ domain: value })} options={[{ value: "", label: "全部模块" }, ...Object.entries(exceptionDomainLabels).map(([value, label]) => ({ value, label }))]} />
          <ToolbarSelect label="状态" value={status} onChange={(value) => updateFilters({ status: value as ExceptionCaseStatus | "" })} options={[{ value: "", label: "全部状态" }, ...Object.entries(exceptionStatusLabels).map(([value, label]) => ({ value, label }))]} />
          <ToolbarSelect label="级别" value={severity} onChange={(value) => updateFilters({ severity: value })} options={[{ value: "", label: "全部级别" }, ...Object.entries(exceptionSeverityLabels).map(([value, label]) => ({ value, label }))]} />
          <ToolbarSelect label="发生类型" value={occurrenceType} onChange={(value) => updateFilters({ occurrenceType: value as ExceptionOccurrenceType | "" })} options={[{ value: "", label: "全部类型" }, ...Object.entries(exceptionOccurrenceLabels).map(([value, label]) => ({ value, label }))]} />
          <label className="grid min-w-[180px] gap-1 text-xs font-black text-muted-foreground">规则代码<input className="project-input-sm" value={ruleCode} onChange={(event) => updateFilters({ ruleCode: event.target.value })} placeholder="如 inventory.negative_stock" /></label>
          <ToolbarSelect label="批次类型" value={sourceBatchKind} onChange={(value) => updateFilters({ sourceBatchKind: value as ExceptionSourceBatchKind | "", sourceBatchUnassigned: false })} options={[{ value: "", label: "选择批次类型" }, ...Object.entries(exceptionSourceBatchKindLabels).map(([value, label]) => ({ value, label }))]} />
          <label className="grid min-w-[140px] gap-1 text-xs font-black text-muted-foreground">批次 ID<input type="text" inputMode="numeric" pattern="[1-9][0-9]*" className="project-input-sm disabled:cursor-not-allowed disabled:bg-slate-100" value={sourceBatchId} disabled={!sourceBatchKind || sourceBatchUnassigned} onChange={(event) => updateFilters({ sourceBatchId: event.target.value, sourceBatchUnassigned: false })} placeholder={sourceBatchUnassigned ? "当前：未关联批次" : sourceBatchKind ? "正整数批次 ID" : "先选择批次类型"} /></label>
          {sourceBatchUnassigned ? <button type="button" className="inline-flex min-h-9 items-center rounded-md border border-primary/30 bg-primary-soft px-3 text-xs font-black text-primary" data-testid="exception-unassigned-batch-filter" onClick={() => updateFilters({ sourceBatchKind: "", sourceBatchId: "", sourceBatchUnassigned: false })}>未关联批次 · 清除</button> : null}
          <ToolbarSelect label="聚合视图" value={groupBy} onChange={(value) => updateFilters({ groupBy: value as ExceptionGroupBy | "" })} options={[{ value: "", label: "案件明细" }, { value: "rule", label: "按规则聚合" }, { value: "batch", label: "按批次聚合" }]} />
        </DataToolbar>}
      >
        <div className="flex flex-col gap-2 border-b border-border bg-slate-50 px-3 py-3 text-xs text-muted-foreground sm:px-4 lg:flex-row lg:items-center lg:justify-between" data-testid="exception-occurrence-help">
          <div className="flex min-w-0 items-start gap-2"><CircleHelp className="mt-0.5 h-4 w-4 shrink-0 text-primary" /><span className="font-bold leading-5">存量：{exceptionOccurrenceDescriptions.baseline}；新增：{exceptionOccurrenceDescriptions.new}；复发：{exceptionOccurrenceDescriptions.reopened}。</span></div>
          {occurrenceType ? <span className="shrink-0 font-black text-primary">当前：{exceptionOccurrenceLabels[occurrenceType]} · {summaryData?.by_occurrence?.[occurrenceType] ?? pageData?.total ?? 0} 条</span> : null}
        </div>
        {!groupBy && canManage && currentPageCaseNos.length > 0 ? <div className="flex flex-wrap items-center justify-between gap-2 border-b border-border px-3 py-2.5 sm:px-4" data-testid="exception-page-selection"><label className="inline-flex min-h-8 cursor-pointer items-center gap-2 text-sm font-black text-foreground"><input ref={selectPageRef} type="checkbox" checked={allCurrentPageSelected} onChange={toggleCurrentPage} aria-label="选择当前页全部案件" />选择当前页可操作案件 <span className="text-xs text-muted-foreground">({currentPageCaseNos.length} 条)</span></label>{selectedOnPageCount > 0 ? <span className="text-xs font-black text-primary">已选 {selectedOnPageCount} 条</span> : null}</div> : null}
        {canManage && selectedCases.length > 0 ? <ExceptionBatchActions caseNos={selectedCases.map((row) => row.case_no)} ignoreBlockedCount={selectedProcessingCount} permissions={permissions} onClear={() => setSelectedCaseNos(new Set())} onCompleted={completeBatchAction} /> : null}
        {groupBy && aggregationTruncated ? <div className="border-b border-amber-200 bg-amber-50 px-4 py-3 text-xs font-black text-amber-800" role="status" data-testid="exception-aggregation-truncated">当前显示前 {aggregationRows.length} 组，共 {aggregationTotal} 组。请增加筛选条件后查看其余结果。</div> : null}
        {listError ? <div className="p-4" data-testid="exception-list-error"><ApiErrorNotice error={listError} navigate={navigate} onRetry={reload} /></div> : listLoading && !pageData ? (
          <div className="grid gap-2 p-4">{Array.from({ length: 6 }).map((_, index) => <div key={index} className="h-12 animate-pulse rounded-md bg-secondary" />)}</div>
        ) : ((groupBy && aggregationRows.length === 0) || (!groupBy && pageData && pageData.items.length === 0)) ? (
          <div className="grid min-h-56 place-items-center px-5 py-10 text-center" data-testid="exception-empty-state"><div><CircleHelp className="mx-auto h-8 w-8 text-muted-foreground" /><h3 className="m-0 mt-3 text-base font-black text-foreground">当前筛选范围没有异常案件</h3><p className="m-0 mt-1 text-sm font-bold text-muted-foreground">可重置筛选条件，或等待下一次规则巡检产生新案件。</p></div></div>
        ) : groupBy ? (
          <Table headers={[groupBy === "rule" ? "规则" : "来源批次", "案件数", "严重程度", "SLA", "操作"]} minWidth={720} emptyMessage="当前筛选范围没有聚合结果。">
            {aggregationRows.map((row) => <tr key={row.key}><td><strong className="block text-sm text-foreground">{row.label}</strong><small className="mt-1 block text-xs text-muted-foreground">{groupBy === "rule" ? "同一检测规则" : row.key === "unassigned" ? "未关联任何来源批次" : row.source_batch_kind ? exceptionSourceBatchKindLabels[row.source_batch_kind] : "同一来源批次"}</small></td><td className="font-mono font-black">{row.count}</td><td><span className="text-sm font-bold text-foreground">严重 {row.critical} · 高 {row.high} · 警告 {row.warning}</span></td><td><Badge tone={row.overdue > 0 ? "bad" : "ok"}>超期 {row.overdue}</Badge></td><td><Button secondary onClick={() => updateFilters(groupBy === "rule" ? { ruleCode: row.key, groupBy: "" } : row.key === "unassigned" ? { sourceBatchKind: "", sourceBatchId: "", sourceBatchUnassigned: true, groupBy: "" } : { sourceBatchKind: row.source_batch_kind ?? "legacy", sourceBatchId: String(row.source_batch_id ?? ""), sourceBatchUnassigned: false, groupBy: "" })}>查看明细<ChevronRight className="ml-1 h-4 w-4" /></Button></td></tr>)}
          </Table>
        ) : (
          <Table headers={canManage ? ["选择", "级别", "案件与异常", "模块与对象", "发生位置", "状态", "时间", "操作"] : ["级别", "案件与异常", "模块与对象", "发生位置", "状态", "时间", "操作"]} minWidth={canManage ? 1180 : 1120} emptyMessage="当前筛选范围没有异常案件。">
            {(pageData?.items ?? []).map((row) => (
              <tr key={row.case_no} className="cursor-pointer transition hover:bg-primary-soft" onClick={() => openCase(row.case_no)}>
                {canManage ? <td>{exceptionBatchAssignableStatuses.includes(row.status) ? <input type="checkbox" checked={selectedCaseNos.has(row.case_no)} aria-label={`选择案件 ${row.case_no}`} onClick={(event) => event.stopPropagation()} onChange={() => toggleCase(row.case_no)} /> : <span className="text-xs font-bold text-muted-foreground">不可批量操作</span>}</td> : null}
                <td><Badge tone={exceptionSeverityTone(row.severity)}>{exceptionSeverityLabels[row.severity] ?? row.severity}</Badge></td>
                <td><strong className="block max-w-[260px] truncate text-foreground">{row.title}</strong><small className="mt-1 block font-mono text-xs text-muted-foreground">{row.case_no} · {row.rule_code}</small><small className="mt-1 block text-xs font-black text-primary">{exceptionOccurrenceLabels[row.occurrence_type] ?? row.occurrence_type}</small></td>
                <td><strong className="block text-sm text-foreground">{exceptionDomainLabels[row.domain] ?? row.domain}</strong><small className="mt-1 block max-w-[220px] truncate text-xs text-muted-foreground">{row.resource_name ?? row.resource_code ?? row.resource_id ?? "未关联业务对象"}</small></td>
                <td><span className="block max-w-[260px] line-clamp-2 text-sm font-bold leading-5 text-foreground">{row.reason}</span><small className="mt-1 block text-xs text-muted-foreground">{row.source_batch_kind ? exceptionSourceBatchKindLabels[row.source_batch_kind] : "批次"} {row.source_batch_id ?? "-"} · 数据 {formatDate(row.data_date)}</small></td>
                <td><Badge tone={exceptionStatusTone(row.status)}>{exceptionStatusLabels[row.status]}</Badge><small className="mt-1 block text-xs text-muted-foreground">负责人 {row.assignee_name ?? row.assignee_user_id ?? "未分派"}</small></td>
                <td><span className="text-sm font-bold text-foreground">{formatDateTime(row.last_seen_at)}</span><small className={`mt-1 block text-xs font-bold ${row.sla_status === "overdue" ? "text-red-700" : row.sla_status === "due_soon" ? "text-amber-700" : "text-muted-foreground"}`}>截止 {formatDateTime(row.due_at)}{row.sla_status === "overdue" ? " · 已超期" : row.sla_status === "due_soon" ? " · 24 小时内到期" : ""}</small></td>
                <td><div className="flex items-center gap-2">{canAskCaseAi ? <button type="button" className="project-button-secondary gap-1.5 px-3 text-primary" disabled={assistantBusy} title={assistantBusy ? "AI 正在分析其他案件" : `询问 AI 分析 ${row.case_no}`} onClick={(event) => { event.stopPropagation(); askCaseAi(row); }}><Sparkles className="h-4 w-4" />问 AI</button> : null}<button type="button" className="project-button-secondary gap-1.5 px-3" onClick={(event) => { event.stopPropagation(); openCase(row.case_no); }}>查看<ChevronRight className="h-4 w-4" /></button></div></td>
              </tr>
            ))}
          </Table>
        )}
        {!listError && (pageData?.total ?? 0) > limit ? <div className="flex flex-col gap-2 border-t border-border px-4 py-3 sm:flex-row sm:items-center sm:justify-between"><span className="text-xs font-bold text-muted-foreground">第 {Math.floor(offset / limit) + 1} 页，共 {Math.ceil((pageData?.total ?? 0) / limit)} 页</span><div className="flex gap-2"><Button secondary disabled={offset === 0} onClick={() => setOffset(Math.max(0, offset - limit))}>上一页</Button><Button secondary disabled={offset + limit >= (pageData?.total ?? 0)} onClick={() => setOffset(offset + limit)}>下一页</Button></div></div> : null}
      </DataTableShell>

      {selectedCaseNo ? <ExceptionCaseDrawer caseNo={selectedCaseNo} permissions={permissions} onPermissionsRefresh={onPermissionsRefresh} aiEnabled={summaryData?.ai_enabled === true} aiCaseAnalysisEnabled={canAskCaseAi} assistantBusy={assistantBusy} actionsEnabled={summaryData?.actions_enabled === true} navigate={navigate} onAskAi={askCaseAi} onClose={closeCase} onChanged={reload} /> : null}
      </> : centerView === "actions" ? <ControlledActionCenter permissions={permissions} navigate={navigate} /> : centerView === "operations" ? <ExceptionOperationsPanel permissions={permissions} /> : <ExceptionDiagnosisQualityPanel permissions={permissions} />}
      {policyOpen && canManagePolicy ? <ExceptionPolicyDrawer permissions={permissions} onClose={() => setPolicyOpen(false)} /> : null}
    </>
  );
}

function SettingsPage({ stats, permissions: currentPermissions }: { stats: Summary | null; permissions: PermissionCode[] }) {
  const canViewAudit = hasPermission(currentPermissions, "audit.view");
  const [audits, setAudits] = useState<AuditLog[]>([]);
  const [mobileOverview, setMobileOverview] = useState<MobileOperationsOverview | null>(null);
  const [mobileDevices, setMobileDevices] = useState<MobileAdminDevice[]>([]);
  const [mobileFeedback, setMobileFeedback] = useState<MobileFeedbackRow[]>([]);
  const [mobileAdoption, setMobileAdoption] = useState<MobileAdoptionOverview | null>(null);
  const [mobileError, setMobileError] = useState("");
  useEffect(() => {
    if (canViewAudit) void auditLogs().then(setAudits);
  }, [canViewAudit]);
  useEffect(() => {
    void mobileOperationsOverview()
      .then((payload) => {
        setMobileOverview(payload);
        setMobileError("");
      })
      .catch(() => setMobileError("移动端运维数据暂时不可用"));
  }, []);
  useEffect(() => {
    void mobileAdminDevices().then((payload) => setMobileDevices(payload.items)).catch(() => setMobileDevices([]));
  }, []);
  useEffect(() => {
    void mobileAdminFeedback().then((payload) => setMobileFeedback(payload.items)).catch(() => setMobileFeedback([]));
    void mobileAdoptionOverview().then(setMobileAdoption).catch(() => setMobileAdoption(null));
  }, []);

  const changeFeedbackStatus = (row: MobileFeedbackRow, status: MobileFeedbackRow["status"]) => {
    const resolution = status === "resolved"
      ? window.prompt("请填写处理结果，用户会在 App 内看到：", row.resolution ?? "")
      : row.resolution ?? undefined;
    if (status === "resolved" && !resolution?.trim()) return;
    void updateMobileAdminFeedback(row.id, status, resolution?.trim()).then((updated) => {
      setMobileFeedback((current) => current.map((item) => item.id === updated.id ? updated : item));
    }).catch(() => setMobileError("反馈状态更新失败，请刷新后重试"));
  };

  const recentAudits = audits.slice(0, 12);

  return (
    <>
      <Header eyebrow="SYSTEM CONTROL" title="系统设置" description="运行配置、服务状态和安全入口集中在这里。" />
      <Card className="p-5">
        <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
          <h2 className="m-0 text-xl font-black text-foreground">运行状态</h2>
          <Badge tone="ok">正常</Badge>
        </div>
        <div className="mt-4 grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
          <SettingsStatusTile label="应用" value="管理中心" icon={Settings} />
          <SettingsStatusTile label="环境" value="production" icon={ShieldCheck} tone="ok" />
          <SettingsStatusTile label="权限点" value={stats?.permissions ?? "-"} icon={UserCog} />
          <SettingsStatusTile label="审计日志" value={stats?.audit_logs ?? "-"} icon={History} />
        </div>
      </Card>
      <section className="mt-5 border-y border-border bg-card px-5 py-5">
        <div className="flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between">
          <div>
            <h2 className="m-0 text-xl font-black text-foreground">移动端运维</h2>
            <p className="m-0 mt-1 text-sm text-muted-foreground">设备、版本、弱网同步和客户端异常的最近 7 天摘要</p>
          </div>
          <button
            type="button"
            className="btn-secondary inline-flex items-center gap-2"
            onClick={() => void mobileOperationsOverview().then(setMobileOverview).catch(() => setMobileError("移动端运维数据暂时不可用"))}
          >
            <RefreshCcw className="h-4 w-4" />刷新
          </button>
        </div>
        {mobileError ? <p className="mt-4 text-sm font-bold text-red-600">{mobileError}</p> : null}
        <div className="mt-4 grid gap-3 sm:grid-cols-2 xl:grid-cols-5">
          <SettingsStatusTile label="活跃设备" value={mobileOverview?.active_devices ?? "-"} icon={Phone} />
          <SettingsStatusTile label="同步成功率" value={mobileOverview ? `${mobileOverview.sync_success_rate}%` : "-"} icon={RefreshCcw} tone={mobileOverview && mobileOverview.sync_success_rate >= 99 ? "ok" : "neutral"} />
          <SettingsStatusTile label="待同步" value={mobileOverview?.pending_operations ?? "-"} icon={Clock3} />
          <SettingsStatusTile label="冲突" value={mobileOverview?.conflicts ?? "-"} icon={FileWarning} />
          <SettingsStatusTile label="API P95" value={mobileOverview?.telemetry.api_p95_ms != null ? `${mobileOverview.telemetry.api_p95_ms} ms` : "-"} icon={BarChart3} />
        </div>
        {mobileAdoption ? (
          <div className="mt-4 border-y border-border py-4">
            <div className="flex items-center justify-between gap-3">
              <h3 className="m-0 text-sm font-black text-foreground">移动端采用情况</h3>
              <span className="text-xs text-muted-foreground">近 {mobileAdoption.days} 天</span>
            </div>
            <div className="mt-3 grid gap-3 sm:grid-cols-2 xl:grid-cols-6">
              <SettingsStatusTile label="周活跃" value={`${mobileAdoption.weekly_active_users} / ${mobileAdoption.eligible_users}`} icon={UsersRound} />
              <SettingsStatusTile label="周活跃率" value={`${mobileAdoption.weekly_active_rate.toFixed(1)}%`} icon={BarChart3} tone={mobileAdoption.weekly_active_rate >= 80 ? "ok" : "neutral"} />
              <SettingsStatusTile label="跟进填写平均耗时" value={formatMobileDuration(mobileAdoption.followup_form_avg_ms)} icon={Clock3} />
              <SettingsStatusTile label="反馈平均处理" value={mobileAdoption.feedback_resolution_avg_hours != null ? `${mobileAdoption.feedback_resolution_avg_hours.toFixed(1)} 小时` : "-"} icon={ClipboardList} />
              <SettingsStatusTile label="AI 结构化成功率" value={mobileAdoption.ai_draft_success_rate != null ? `${mobileAdoption.ai_draft_success_rate.toFixed(1)}%` : "-"} icon={ShieldCheck} tone={mobileAdoption.ai_draft_success_rate != null && mobileAdoption.ai_draft_success_rate >= 99 ? "ok" : "neutral"} />
              <SettingsStatusTile label="AI 草稿采用率" value={mobileAdoption.ai_draft_adoption_rate != null ? `${mobileAdoption.ai_draft_adoption_rate.toFixed(1)}%` : "-"} icon={Copy} />
            </div>
            <div className="mt-3 flex flex-wrap gap-2">
              {Object.entries(mobileAdoption.feature_usage).length ? Object.entries(mobileAdoption.feature_usage).sort((a, b) => b[1] - a[1]).map(([key, count]) => (
                <span key={key} className="rounded border border-border bg-muted px-2 py-1 text-xs text-muted-foreground">{mobileFeatureLabel(key)} <strong className="text-foreground">{count}</strong></span>
              )) : <span className="text-sm text-muted-foreground">暂无功能使用记录</span>}
            </div>
          </div>
        ) : null}
        {mobileOverview ? (
          <div className="mt-4 grid gap-4 xl:grid-cols-[0.8fr_1.2fr]">
            <div className="border border-border bg-muted p-4">
              <h3 className="m-0 text-sm font-black text-foreground">版本分布</h3>
              <div className="mt-3 space-y-2">
                {Object.entries(mobileOverview.version_distribution).length ? Object.entries(mobileOverview.version_distribution).map(([version, count]) => (
                  <div key={version} className="flex items-center justify-between text-sm"><span>Android {version}</span><strong>{count} 台</strong></div>
                )) : <span className="text-sm text-muted-foreground">暂无活跃设备</span>}
              </div>
            </div>
            <div className="border border-border bg-muted p-4">
              <h3 className="m-0 text-sm font-black text-foreground">最近异常</h3>
              <div className="mt-3 space-y-2">
                {mobileOverview.telemetry.recent_errors.length ? mobileOverview.telemetry.recent_errors.slice(0, 6).map((row, index) => (
                  <div key={`${row.request_id ?? row.occurred_at}-${index}`} className="grid gap-1 border-b border-border pb-2 text-sm sm:grid-cols-[120px_1fr_auto]">
                    <strong>{row.event_type}</strong><span className="truncate">{row.route ?? row.code ?? "未标注接口"}</span><span className="text-muted-foreground">{row.request_id ?? "-"}</span>
                  </div>
                )) : <span className="text-sm text-muted-foreground">最近没有客户端异常</span>}
              </div>
            </div>
          </div>
        ) : null}
        {mobileDevices.length ? (
          <div className="mt-4">
            <h3 className="m-0 text-sm font-black text-foreground">移动设备会话</h3>
            <div className="mt-3 overflow-x-auto border border-border">
              <table className="w-full min-w-[860px] text-left text-sm">
                <thead className="bg-muted text-muted-foreground"><tr><th className="p-3">账号</th><th className="p-3">设备</th><th className="p-3">版本</th><th className="p-3">最近使用</th><th className="p-3">最近同步</th><th className="p-3">状态</th><th className="p-3">操作</th></tr></thead>
                <tbody>{mobileDevices.map((row) => (
                  <tr key={row.id} className="border-t border-border">
                    <td className="p-3 font-bold">{row.user_label}<small className="ml-2 text-muted-foreground">{row.username}</small></td>
                    <td className="p-3">{row.device_name ?? row.device_model ?? "Android 设备"}</td>
                    <td className="p-3">{row.app_version ?? "-"} / Android {row.android_version ?? "-"}</td>
                    <td className="p-3">{row.last_used_at ?? "-"}</td>
                    <td className="p-3">{row.last_sync_at ?? "-"}</td>
                    <td className="p-3">{row.revoked_at ? "已注销" : "正常"}</td>
                    <td className="p-3">{!row.revoked_at ? <button type="button" className="text-sm font-bold text-red-600" onClick={() => {
                      if (!window.confirm(`确认注销 ${row.user_label} 的这台设备？`)) return;
                      void revokeMobileAdminDevice(row.id).then(() => setMobileDevices((current) => current.map((item) => item.id === row.id ? { ...item, revoked_at: new Date().toISOString() } : item)));
                    }}>注销设备</button> : "-"}</td>
                  </tr>
                ))}</tbody>
              </table>
            </div>
          </div>
        ) : null}
        <div className="mt-5">
          <div className="flex items-center justify-between gap-3">
            <h3 className="m-0 text-sm font-black text-foreground">移动端问题反馈</h3>
            <span className="text-xs text-muted-foreground">{mobileFeedback.length} 条</span>
          </div>
          <div className="mt-3 overflow-x-auto border border-border">
            <table className="w-full min-w-[980px] text-left text-sm">
              <thead className="bg-muted text-muted-foreground"><tr><th className="p-3">用户</th><th className="p-3">类别</th><th className="p-3">描述</th><th className="p-3">页面 / 请求</th><th className="p-3">设备</th><th className="p-3">状态</th><th className="p-3">操作</th></tr></thead>
              <tbody>{mobileFeedback.length ? mobileFeedback.map((row) => (
                <tr key={row.id} className="border-t border-border align-top">
                  <td className="p-3 font-bold">{row.user_label ?? row.user_id}<small className="block text-muted-foreground">{row.created_at}</small></td>
                  <td className="p-3">{mobileFeedbackCategory(row.category)}</td>
                  <td className="max-w-[320px] p-3"><p className="m-0 whitespace-pre-wrap">{row.description}</p>{row.screenshot_path ? <button type="button" className="mt-1 font-bold text-primary" onClick={() => void mobileFeedbackAttachment(row.id).then((blob) => {
                    const url = URL.createObjectURL(blob);
                    window.open(url, "_blank", "noopener,noreferrer");
                    window.setTimeout(() => URL.revokeObjectURL(url), 60_000);
                  }).catch(() => setMobileError("反馈截图打开失败"))}>查看截图</button> : null}{row.resolution ? <small className="mt-1 block text-emerald-700">处理结果：{row.resolution}</small> : null}</td>
                  <td className="p-3">{row.current_route ?? "-"}<small className="block text-muted-foreground">{row.request_id ?? "无请求编号"}</small></td>
                  <td className="p-3">{row.device_model ?? "Android"}<small className="block text-muted-foreground">{row.app_version ?? "-"} / {row.android_version ?? "-"}</small></td>
                  <td className="p-3">{mobileFeedbackStatus(row.status)}</td>
                  <td className="p-3"><div className="flex gap-3">
                    {row.status === "open" ? <button type="button" className="font-bold text-primary" onClick={() => changeFeedbackStatus(row, "processing")}>开始处理</button> : null}
                    {!(["resolved", "closed"] as string[]).includes(row.status) ? <button type="button" className="font-bold text-emerald-700" onClick={() => changeFeedbackStatus(row, "resolved")}>标记解决</button> : null}
                    {row.status !== "closed" ? <button type="button" className="font-bold text-muted-foreground" onClick={() => changeFeedbackStatus(row, "closed")}>关闭</button> : null}
                  </div></td>
                </tr>
              )) : <tr><td colSpan={7} className="p-6 text-center text-muted-foreground">暂无移动端反馈</td></tr>}</tbody>
            </table>
          </div>
        </div>
      </section>
      {canViewAudit ? <AuditTable rows={recentAudits} total={stats?.audit_logs ?? recentAudits.length} /> : null}
    </>
  );
}

function SettingsStatusTile({ label, value, icon: Icon, tone = "neutral" }: { label: string; value: React.ReactNode; icon: LucideIcon; tone?: "ok" | "neutral" }) {
  return (
    <div className={`rounded-lg border p-4 ${tone === "ok" ? "border-emerald-100 bg-emerald-50" : "border-border bg-muted"}`}>
      <div className="flex items-center justify-between gap-3">
        <span className="text-sm font-black text-muted-foreground">{label}</span>
        <Icon className={`h-4 w-4 ${tone === "ok" ? "text-emerald-600" : "text-primary"}`} />
      </div>
      <strong className="mt-3 block truncate text-2xl font-black text-foreground">{value}</strong>
    </div>
  );
}

function formatMobileDuration(value?: number | null) {
  if (value == null) return "-";
  if (value < 60_000) return `${Math.round(value / 1000)} 秒`;
  return `${(value / 60_000).toFixed(1)} 分钟`;
}

function mobileFeatureLabel(key: string) {
  const labels: Record<string, string> = {
    feedback_submitted: "提交反馈",
    voice_input: "语音输入",
    contact_ocr: "名片识别",
    ai_draft_followup: "AI 跟进草稿",
    ai_draft_approval: "AI 审批草稿",
    ai_draft_project: "AI 项目摘要"
  };
  return labels[key] ?? key;
}

function mobileFeedbackStatus(status: MobileFeedbackRow["status"]) {
  return ({ open: "待处理", processing: "处理中", resolved: "已解决", closed: "已关闭" } as const)[status];
}

function mobileFeedbackCategory(category: string) {
  return ({ bug: "功能问题", experience: "体验问题", request: "功能建议", other: "其他" } as Record<string, string>)[category] ?? category;
}

function AuditTable({ rows, total = rows.length, toolbar }: { rows: AuditLog[]; total?: number; toolbar?: React.ReactNode }) {
  return (
    <div className="mt-5">
    <DataTableShell
      title="最近审计"
      meta={`${rows.length} / ${total} 条`}
      toolbar={toolbar}
    >
      <Table headers={["ID", "角色", "动作", "资源", "资源 ID", "时间"]}>
        {rows.map((row) => <tr key={row.id}><td>{row.id}</td><td>{row.role_code ?? "-"}</td><td>{row.action_type}</td><td>{row.resource_type}</td><td>{row.resource_id ?? "-"}</td><td>{row.created_at}</td></tr>)}
      </Table>
    </DataTableShell>
    </div>
  );
}

function Table({
  headers,
  children,
  emptyMessage = "没有符合条件的数据",
  minWidth
}: {
  headers: readonly string[];
  children: React.ReactNode;
  emptyMessage?: string;
  minWidth?: number;
}) {
  const rowNodes = Children.toArray(children).filter((child) => child !== null && child !== undefined);
  const rowCount = rowNodes.length;
  const hasRows = rowCount > 0;
  const tableMinWidth = minWidth ?? Math.max(720, headers.length * 132);
  return (
    <div className="project-table-card">
      <div className="project-table-workbench-bar">
        <div className="project-table-workbench-meta">
          <span className="font-black text-foreground">表格视图</span>
          <span className="project-table-pill">{headers.length} 列</span>
          <span className="project-table-pill">本屏 {rowCount} 行</span>
          {!hasRows ? <span className="project-table-pill">空状态</span> : null}
        </div>
        <span className="project-table-scroll-hint">横向滚动查看全部字段</span>
      </div>
      <div className="project-table-scroll" tabIndex={0} aria-label={`表格，${headers.length} 列，本屏 ${rowCount} 行`}>
        <table className="project-table" style={{ minWidth: tableMinWidth }}>
          <TableHeader>
            <TableRow>{headers.map((header, index) => <TableHead key={`${header}-${index}`}>{header}</TableHead>)}</TableRow>
          </TableHeader>
          <TableBody>
            {hasRows ? rowNodes : (
              <TableRow>
                <TableCell className="project-table-empty" colSpan={Math.max(1, headers.length)}>{emptyMessage}</TableCell>
              </TableRow>
            )}
          </TableBody>
        </table>
      </div>
    </div>
  );
}

export default function App() {
  const { page, navigate, locationKey } = useRoute();
  const [user, setUser] = useState<UserPublic | null>(null);
  const [permissionCodes, setPermissionCodes] = useState<PermissionCode[]>([]);
  const [stats, setStats] = useState<Summary | null>(null);
  const [authChecked, setAuthChecked] = useState(false);
  const [loginError, setLoginError] = useState("");
  const [loginLoading, setLoginLoading] = useState(false);
  const [globalApiError, setGlobalApiError] = useState<ApiError | null>(null);
  const [assistantOpen, setAssistantOpen] = useState(() => initialQueryParam("assistant") === "open" || initialQueryParam("view") === "ai");
  const [assistantContext, setAssistantContext] = useState<ExceptionAssistantContext>(defaultExceptionAssistantContext);
  const [assistantLaunch, setAssistantLaunch] = useState<ExceptionAssistantLaunch | null>(null);
  const [assistantSending, setAssistantSending] = useState(false);
  const [assistantContextResetKey, setAssistantContextResetKey] = useState(0);
  const jumpTools = useMemo(() => createBusinessJumpTools(navigate), [navigate]);
  const refreshPermissions = useCallback(async () => {
    const currentPermissions = await myPermissions();
    setPermissionCodes(currentPermissions);
    return currentPermissions;
  }, []);
  const changeAssistantOpen = useCallback((open: boolean) => {
    const url = new URL(window.location.href);
    if (open) url.searchParams.set("assistant", "open");
    else url.searchParams.delete("assistant");
    if (url.searchParams.get("view") === "ai") url.searchParams.delete("view");
    window.history.pushState(null, "", `${url.pathname}${url.search}${url.hash}`);
    setAssistantOpen(open);
  }, []);
  const updateAssistantContext = useCallback((context: ExceptionAssistantContext) => setAssistantContext(context), []);
  const launchCaseAnalysis = useCallback((launch: ExceptionAssistantLaunch) => {
    setAssistantContext({ request: launch.context, label: `当前案件 · ${launch.contextMeta.case_no}` });
    setAssistantLaunch(launch);
    changeAssistantOpen(true);
  }, [changeAssistantOpen]);

  useEffect(() => {
    const handleApiError = (event: Event) => {
      const detail = (event as CustomEvent<ApiErrorEventDetail>).detail;
      if (detail?.error instanceof ApiError) setGlobalApiError(detail.error);
    };
    window.addEventListener(API_ERROR_EVENT, handleApiError);
    return () => window.removeEventListener(API_ERROR_EVENT, handleApiError);
  }, []);

  useEffect(() => {
    const handleAuthExpired = () => {
      clearToken();
      setUser(null);
      setPermissionCodes([]);
      setStats(null);
      setGlobalApiError(null);
      setAuthChecked(true);
    };
    window.addEventListener(AUTH_EXPIRED_EVENT, handleAuthExpired);
    return () => window.removeEventListener(AUTH_EXPIRED_EVENT, handleAuthExpired);
  }, []);

  useEffect(() => {
    setGlobalApiError(null);
    const legacyAssistantView = page === "exceptions" && initialQueryParam("view") === "ai";
    if (legacyAssistantView) replaceCurrentQueryParams({ view: null, assistant: "open" });
    setAssistantOpen(page === "exceptions" && (initialQueryParam("assistant") === "open" || legacyAssistantView));
  }, [locationKey]);

  useEffect(() => {
    const check = async () => {
      try {
        const currentUser = await me();
        const currentPermissions = await myPermissions();
        setUser(currentUser);
        setPermissionCodes(currentPermissions);
      } catch {
        clearToken();
      } finally {
        setAuthChecked(true);
      }
    };
    void check();
  }, []);

  useEffect(() => {
    if (!user) return;
    void summary().then(setStats).catch(() => setStats(null));
  }, [user, permissionCodes]);

  const loginSubmit = async (username: string, password: string) => {
    setLoginLoading(true);
    setLoginError("");
    try {
      const loggedIn = await login(username, password);
      const currentPermissions = await myPermissions();
      setUser(loggedIn);
      setPermissionCodes(currentPermissions);
      const nextPage = fallbackPageForPermissions(currentPermissions);
      window.history.replaceState(null, "", pathFor(nextPage));
      navigate(nextPage);
    } catch {
      setLoginError("账号或密码不正确，请重新输入。");
    } finally {
      setLoginLoading(false);
    }
  };

  const content = useMemo(() => {
    const activePage = canAccessPageWithContext(page, permissionCodes, locationKey) ? page : fallbackPageForPermissions(permissionCodes);
    if (activePage === "exceptions" && user) return <ExceptionCenterPage key={locationKey} permissions={permissionCodes} currentUser={user} navigate={navigate} onPermissionsRefresh={refreshPermissions} assistantOpen={assistantOpen} assistantBusy={assistantSending} assistantContextResetKey={assistantContextResetKey} onAssistantContextChange={updateAssistantContext} onAssistantLaunch={launchCaseAnalysis} />;
    if (activePage === "master-data") return <MasterDataPage key={locationKey} stats={stats} permissions={permissionCodes} jumpTools={jumpTools} />;
    if (activePage === "sales") return <SalesDetailPage key={locationKey} permissions={permissionCodes} jumpTools={jumpTools} />;
    if (activePage === "inventory") return <InventorySnapshotPage key={locationKey} permissions={permissionCodes} jumpTools={jumpTools} />;
    if (activePage === "purchase") return <PurchaseDetailPage key={locationKey} permissions={permissionCodes} jumpTools={jumpTools} />;
    if (activePage === "account-balance") return <AccountBalancePage key={locationKey} permissions={permissionCodes} jumpTools={jumpTools} />;
    if (activePage === "image-tools") return <ImageToolsSection key={locationKey} permissions={permissionCodes} navigate={navigate} />;
    if ((activePage === "crm" || activePage === "crm-projects") && user) return <CrmModulePage key={locationKey} permissions={permissionCodes} navigate={navigate} currentUser={user} />;
    if (activePage === "users" && user) return <UsersPage key={locationKey} currentUser={user} permissions={permissionCodes} onCurrentUserChange={(nextUser) => setUser(nextUser)} />;
    if (activePage === "settings") return <SettingsPage key={locationKey} stats={stats} permissions={permissionCodes} />;
    return <DashboardPage key={locationKey} stats={stats} permissions={permissionCodes} navigate={navigate} />;
  }, [page, locationKey, stats, navigate, jumpTools, user, permissionCodes, refreshPermissions, assistantOpen, assistantSending, assistantContextResetKey, updateAssistantContext, launchCaseAnalysis]);

  if (!authChecked) {
    return <div className="grid min-h-screen place-items-center bg-background text-sm font-black text-slate-500">正在检查登录状态</div>;
  }

  if (!user) {
    return <FullScreenSignup error={loginError} loading={loginLoading} onSubmit={loginSubmit} />;
  }

  const activePage = canAccessPageWithContext(page, permissionCodes, locationKey) ? page : fallbackPageForPermissions(permissionCodes);
  return (
    <>
      <Shell user={user} permissions={permissionCodes} page={activePage} navigate={navigate} stats={stats} locationKey={locationKey} assistantOpen={assistantOpen} assistantContext={assistantContext} assistantLaunch={assistantLaunch} onAssistantLaunchConsumed={(id) => setAssistantLaunch((current) => current?.id === id ? null : current)} onAssistantSendingChange={setAssistantSending} onAssistantOpenChange={changeAssistantOpen} onAssistantContextClear={() => { setAssistantContext(defaultExceptionAssistantContext); setAssistantContextResetKey((value) => value + 1); }}>{content}</Shell>
      {globalApiError ? (
        <div className="pointer-events-none fixed inset-x-3 top-3 z-[160] mx-auto max-w-4xl sm:inset-x-6" data-testid="global-api-error">
          <div className="pointer-events-auto shadow-xl">
            <ApiErrorNotice
              error={globalApiError}
              navigate={(nextPage, path) => {
                setGlobalApiError(null);
                navigate(nextPage, path);
              }}
              onClose={() => setGlobalApiError(null)}
            />
          </div>
        </div>
      ) : null}
    </>
  );
}
